-- Daily push notifications (pregnancy_day_notifications, mommy_day_notifications) translated into
-- es, fr, hi, id, ja, ko, nl, pl, pt, sv, vi, zh (owner request 2026-11-12; human-quality translation, not machine/Gemini). Batch 20261112290000_push_notifications_i18n_wave7.
-- Only empty cells are filled; existing text is never overwritten. Tables already CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
      AND table_name IN ('pregnancy_day_notifications', 'mommy_day_notifications')) <> 2 THEN
    RAISE EXCEPTION 'PUSH_I18N_GUARD_MISSING'; END IF;
END $$;
UPDATE public.mommy_day_notifications SET body_es = '¿No le deja su juguete a nadie? No es egoísmo, es una etapa real del desarrollo. Lee en el Blog cómo enseñarle no a compartir, sino a jugar por turnos, y ponlo en práctica.', body_fr = 'Il ne prête son jouet à personne ? Ce n''est pas de l''égoïsme, c''est une étape normale du développement. Lisez dans le Blog comment remplacer le partage par le jeu chacun son tour, et mettez-le en pratique.', body_hi = 'अपना खिलौना किसी को नहीं देता? यह स्वार्थ नहीं, विकास की सच्चाई है। ‘बाँटना’ नहीं, ‘बारी-बारी से खेलना’ सिखाने के बारे में ब्लॉग में पढ़िए और आज़माइए।', body_id = 'Ia tidak mau memberikan mainannya kepada siapa pun? Ini bukan egois, ini kenyataan perkembangan. Baca di Blog tentang konsep bermain bergiliran, bukan berbagi, lalu terapkan.', body_ja = 'おもちゃを誰にも貸さない？これはわがままではなく、発達の自然な姿です。「貸してあげる」ではなく「順番に遊ぶ」という考え方をブログで読んで、試してみましょう。', body_ko = '장난감을 아무에게도 안 주나요? 이건 이기심이 아니라 자연스러운 발달 단계예요. ''나눠 쓰기'' 대신 ''차례로 놀기''를 가르치는 법을 블로그에서 읽고 실천해 보세요.', body_nl = 'Geeft hij zijn speelgoed aan niemand? Dat is geen egoïsme, maar een normale fase in zijn ontwikkeling. Lees in de Blogs hoe je hem niet leert delen, maar om de beurt spelen, en pas het toe.', body_pl = 'Nikomu nie daje swojej zabawki? To nie egoizm, tylko etap rozwoju. Przeczytaj na Blogu, jak zamiast „dzielenia się” uczyć zabawy po kolei, i wypróbuj to w praktyce.', body_pt = 'Não empresta o brinquedo a ninguém? Não é egoísmo, é uma fase normal do desenvolvimento. Leia nos Blogues como ensinar não a partilhar, mas a brincar à vez, e ponha em prática.', body_sv = 'Vill barnet inte låta någon annan få leksaken? Det är inte egoism, det är en naturlig del av utvecklingen. Läs i bloggen om hur man lär ut att turas om i stället för att dela, och testa i praktiken.', body_vi = 'Bé không cho ai chơi đồ chơi của mình? Đó không phải ích kỷ mà là một giai đoạn phát triển bình thường. Thay vì ép "chia sẻ", hãy đọc Blog về khái niệm "chơi lần lượt" và áp dụng nhé.', body_zh = '玩具谁都不让碰？这不是自私，而是成长的必经阶段。别急着教“分享”，去博客读读怎样学会“轮流玩”，再试着用起来吧。' WHERE id = '5be6af82-89c1-4468-a900-9f899a3717f7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revolución matutina 🛑', body_es = '¿Hoy rechaza con asco la comida que ayer le encantaba? No es falta de apetito, solo es un intento de tener el control. Habla con Anacan AI sobre cómo mantener la calma en las crisis, respira hondo y nunca conviertas la mesa en un campo de batalla.', title_fr = 'Révolution matinale 🛑', body_fr = 'Le plat qu''il adorait hier, il le rejette aujourd''hui avec dégoût ? Ce n''est pas un manque d''appétit, juste une tentative de prendre le contrôle. Discutez avec Anacan AI de la façon de garder votre calme pendant ces crises, respirez profondément et ne menez jamais de bataille à table.', title_hi = 'सुबह की बगावत 🛑', body_hi = 'कल जो खाना बहुत पसंद था, आज उसे नफ़रत से ठुकरा रहा है? यह भूख की कमी नहीं, बस नियंत्रण की कोशिश है। झगड़ों में शांत कैसे रहें, इस पर Anacan AI से बात कीजिए, गहरी साँस लीजिए और खाने की मेज़ पर कभी लड़ाई मत कीजिए।', title_id = 'Revolusi pagi 🛑', body_id = 'Makanan yang kemarin sangat ia sukai, hari ini ditolak mentah-mentah? Ini bukan tidak nafsu makan, hanya usaha untuk memegang kendali. Ngobrol dengan Anacan AI tentang cara tetap tenang saat krisis, tarik napas dalam, dan jangan pernah bertengkar di meja makan.', title_ja = '朝の革命 🛑', body_ja = '昨日は大好きだった食べものを、今日はいやそうに拒否する？食欲がないのではなく、自分で決めたいだけなんです。かんしゃくのときに落ち着いていられる方法をAnacan AIに相談して、深呼吸。食卓では決して戦わないで。', title_ko = '아침의 반란 🛑', body_ko = '어제 그렇게 좋아하던 음식을 오늘은 질색하며 거부하나요? 입맛이 없는 게 아니라 그저 상황을 통제하려는 시도예요. 이런 위기에 침착함을 지키는 법을 Anacan AI와 이야기하고, 깊게 숨을 쉬고, 식탁에서는 절대 싸우지 마세요.', title_nl = 'Ochtendrevolutie 🛑', body_nl = 'Wijst hij vandaag vol afkeer het eten af waar hij gisteren nog dol op was? Dat is geen gebrek aan eetlust, maar gewoon een poging om de controle te houden. Praat met Anacan AI over hoe je kalm blijft tijdens zo''n crisis, haal diep adem en voer nooit strijd aan tafel.', title_pl = 'Poranna rewolucja 🛑', body_pl = 'Ulubione wczorajsze danie dziś odrzuca z niechęcią? To nie brak apetytu, tylko próba przejęcia kontroli. Porozmawiaj z Anacan AI o tym, jak zachować spokój w kryzysach, weź głęboki oddech i nigdy nie walcz przy stole.', title_pt = 'Revolução matinal 🛑', body_pt = 'Hoje recusa com repugnância a comida de que tanto gostava ontem? Não é falta de apetite, é só uma tentativa de controlo. Fale com o Anacan AI sobre como manter a calma nas crises, respire fundo e nunca faça da mesa um campo de batalha.', title_sv = 'Morgonrevolution 🛑', body_sv = 'Maten barnet älskade i går vägrar hen med avsky i dag? Det är inte dålig aptit, bara ett försök att ta kontroll. Prata med Anacan AI om hur du håller dig lugn i kriserna, andas djupt och bråka aldrig vid matbordet.', title_vi = 'Cuộc nổi loạn buổi sáng 🛑', body_vi = 'Món bé mê hôm qua, hôm nay lại gạt đi đầy khó chịu? Đó không phải biếng ăn, chỉ là bé muốn được kiểm soát. Hãy tâm sự với Anacan AI cách giữ bình tĩnh khi bé ăn vạ, hít một hơi thật sâu và đừng bao giờ "chiến đấu" trên bàn ăn.', title_zh = '早晨的革命 🛑', body_zh = '昨天还爱吃的东西，今天却嫌弃地推开？这不是没胃口，只是想掌握主动权。和Anacan AI聊聊怎样在这种时刻保持冷静，深呼吸，千万别在饭桌上开战。' WHERE id = '6c5b3273-7cbb-4026-9d69-cd0596d59019' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hablar sin parar con el peque y responder a todas sus preguntas agota. Busca en Lugares para mamás una cafetería con rincón infantil, tómate un café caliente, charla con otras mamás y respira un poco.', body_fr = 'Parler sans arrêt avec l''enfant et répondre à ses questions, c''est épuisant. Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants, buvez votre café chaud et soufflez un peu en discutant avec d''autres mamans.', body_hi = 'बच्चे से लगातार बात करना और सवालों के जवाब देना थका देता है। माँ के लिए अनुकूल जगहों में बच्चों के कोने वाला कोई कैफ़े ढूँढिए, अपनी गरम कॉफ़ी पीजिए और दूसरी माँओं से बातें करके थोड़ा साँस लीजिए।', body_id = 'Terus-menerus berbicara dengan anak dan menjawab pertanyaannya itu melelahkan. Temukan kafe dengan pojok anak di Tempat Ramah Ibu, nikmati kopi hangat Anda, mengobrol dengan ibu-ibu lain, dan bernapaslah sejenak.', body_ja = '子どもとずっとおしゃべりして、質問に答え続けるのは疲れますよね。「ママにやさしいスポット」でキッズコーナーのあるカフェを見つけて、温かいコーヒーを飲みながら、ほかのママたちとおしゃべりしてひと息つきましょう。', body_ko = '아이와 쉬지 않고 이야기하고 질문에 답하는 건 지치는 일이에요. 엄마 친화 장소에서 키즈 코너가 있는 카페를 찾아 따뜻한 커피를 마시고, 다른 엄마들과 수다 떨며 잠시 숨을 돌리세요.', body_nl = 'Constant met je kind praten en vragen beantwoorden is vermoeiend. Zoek bij Mamavriendelijke plekken een café met speelhoek, drink je koffie warm op, klets met andere mama''s en kom even op adem.', body_pl = 'Ciągłe rozmowy z dzieckiem i odpowiadanie na pytania męczą. Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci, wypij gorącą kawę, pogadaj z innymi mamami i złap oddech.', body_pt = 'Falar sem parar com a criança e responder a perguntas cansa. Procure nos Locais Amigos das Mães um café com espaço infantil, beba o seu café quente, converse com outras mães e respire um pouco.', body_sv = 'Att prata oavbrutet med barnet och svara på alla frågor är tröttsamt. Hitta ett kafé med lekhörna bland Mammavänliga platser, drick ditt varma kaffe, prata av dig med andra mammor och andas ut en stund.', body_vi = 'Nói chuyện liên tục với bé, trả lời không ngớt các câu hỏi thật mệt. Hãy tìm một quán cà phê có góc chơi cho trẻ trong Địa điểm thân thiện với mẹ, nhâm nhi cà phê nóng và trò chuyện với các mẹ khác để thở một chút.', body_zh = '和孩子说个不停、回答没完没了的问题，真的很累。在妈妈友好场所里找一家有儿童区的咖啡馆，喝杯热咖啡，和其他妈妈聊聊天，喘口气吧。' WHERE id = '4b47f634-fca5-4f0e-a391-d61c2ad9b71e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Papá cuenta el cuento 📚', body_es = 'Esta noche el ritual del sueño es cosa de papá. Que él lea el cuento y tú disfruta del silencio total al otro lado de la puerta.', title_fr = 'Au tour de papa de lire le conte 📚', body_fr = 'Ce soir, le rituel du coucher est entièrement confié à papa. Qu''il lise le conte, pendant que vous savourez un silence total derrière la porte.', title_hi = 'पापा की कहानी वाली बारी 📚', body_hi = 'आज शाम सोने की पूरी रस्म पापा की ज़िम्मेदारी है। कहानी वे पढ़ें, और आप दरवाज़े के पीछे पूरी शांति का मज़ा लीजिए।', title_id = 'Giliran Ayah mendongeng 📚', body_id = 'Malam ini ritual tidur sepenuhnya tugas Ayah. Biarkan ia yang membacakan dongeng, sementara Anda menikmati keheningan total di balik pintu.', title_ja = 'パパの絵本当番 📚', body_ja = '今夜の寝かしつけはすべてパパにおまかせ。パパが絵本を読んでいる間、あなたはドアの向こうで静けさを味わいましょう。', title_ko = '아빠의 동화 당번 📚', body_ko = '오늘 저녁 잠자리 의식은 전부 아빠 몫이에요. 아빠가 동화를 읽는 동안 엄마는 문밖에서 완전한 고요를 즐기세요.', title_nl = 'Papa''s voorleesbeurt 📚', body_nl = 'Het bedritueel is vanavond helemaal papa''s taak. Laat hem het verhaaltje voorlezen, terwijl jij achter de deur geniet van de volledige stilte.', title_pl = 'Tata czyta bajkę 📚', body_pl = 'Dziś wieczorny rytuał usypiania jest w całości na głowie taty. Niech on czyta bajkę, a ty rozkoszuj się zupełną ciszą za drzwiami.', title_pt = 'A vez do pai contar histórias 📚', body_pt = 'Esta noite, o ritual de deitar fica totalmente a cargo do pai. Ele lê a história e a mãe saboreia, do outro lado da porta, o silêncio total.', title_sv = 'Pappas tur med sagan 📚', body_sv = 'I kväll är det pappa som har hand om hela läggningsritualen. Låt honom läsa sagan, medan du njuter av total tystnad på andra sidan dörren.', title_vi = 'Đến lượt bố kể chuyện 📚', body_vi = 'Tối nay, việc dỗ bé ngủ hoàn toàn do bố đảm nhận. Để bố đọc truyện, còn mẹ thì tận hưởng sự yên lặng tuyệt đối sau cánh cửa.', title_zh = '今晚爸爸讲故事 📚', body_zh = '今晚的睡前仪式全交给爸爸。让他来讲故事，你就在门外好好享受彻底的安静吧。' WHERE id = '4e86cfa1-9302-4174-a4b5-457a860c75dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo hago yo! 🛑', body_es = '¿Se mete en todo y vestirse le lleva el triple de tiempo? No mires el desorden, mira su autoestima creciendo. Cuando se te agote la paciencia, lee en el Blog cómo resolver las crisis jugando y respira hondo.', title_fr = 'Je vais le faire tout seul ! 🛑', body_fr = 'Il se mêle de tout et l''habillage prend 3 fois plus de temps ? Ne regardez pas le désordre, regardez sa confiance en soi qui grandit. Quand votre patience déborde, lisez dans le Blog comment désamorcer les crises par le jeu, et respirez profondément.', title_hi = 'मैं खुद करूँगा! 🛑', body_hi = 'हर काम में दखल देता है और कपड़े पहनने में तीन गुना समय लगाता है? बिखरी चीज़ों को नहीं, उसके बढ़ते आत्मविश्वास को देखिए। जब सब्र टूटने लगे, तो खेल से झगड़े सुलझाने के बारे में ब्लॉग में पढ़िए और गहरी साँस लीजिए।', title_id = 'Aku mau sendiri! 🛑', body_id = 'Ia ikut campur di semua hal dan membuat proses berpakaian 3 kali lebih lama? Jangan lihat kekacauannya, lihat rasa percaya dirinya yang tumbuh. Saat kesabaran Anda habis, baca di Blog cara mengatasi krisis lewat permainan dan tarik napas dalam.', title_ja = '自分でやる！ 🛑', body_ja = '何にでも手を出して、着がえに3倍の時間がかかる？散らかったものではなく、育っていく自信に目を向けて。がまんの限界がきたら、かんしゃくを遊びで乗りきる方法をブログで読んで、深呼吸しましょう。', title_ko = '내가 할 거야! 🛑', body_ko = '모든 일에 끼어들어 옷 입는 시간이 세 배로 늘어나나요? 어질러진 것보다 자라나는 자신감을 봐 주세요. 인내심이 바닥날 땐 위기를 놀이로 푸는 법을 블로그에서 읽고 깊게 숨을 쉬세요.', title_nl = 'Ik doe het zelf! 🛑', body_nl = 'Bemoeit hij zich overal mee en duurt aankleden drie keer zo lang? Kijk niet naar de rommel, maar naar zijn groeiende zelfvertrouwen. Raakt je geduld op, lees dan in de Blogs hoe je zo''n crisis met spel oplost, en haal diep adem.', title_pl = 'Sam to zrobię! 🛑', body_pl = 'Wtrąca się we wszystko i ubieranie trwa trzy razy dłużej? Patrz nie na bałagan, ale na rosnącą pewność siebie. Gdy kończy ci się cierpliwość, przeczytaj na Blogu, jak rozwiązywać kryzysy zabawą, i weź głęboki oddech.', title_pt = 'Sou eu que faço! 🛑', body_pt = 'Mete-se em tudo e faz o vestir demorar 3 vezes mais? Não olhe para a confusão, olhe para a autoconfiança que está a crescer. Quando a paciência transbordar, leia nos Blogues como resolver as crises a brincar e respire fundo.', title_sv = 'Jag gör det själv! 🛑', body_sv = 'Lägger barnet sig i allt och gör påklädningen tre gånger så lång? Titta inte på röran, titta på det växande självförtroendet. När tålamodet tar slut, läs i bloggen om hur man löser kriser med lek och andas djupt.', title_vi = 'Con tự làm! 🛑', body_vi = 'Việc gì bé cũng muốn nhúng tay và khiến việc mặc đồ kéo dài gấp 3 lần? Đừng nhìn vào sự bừa bộn, hãy nhìn vào sự tự tin đang lớn dần của bé. Khi mẹ cạn kiên nhẫn, hãy đọc Blog về cách giải quyết những cơn ăn vạ bằng trò chơi và hít thở thật sâu.', title_zh = '我自己来！🛑', body_zh = '什么事都要插手，穿衣服的时间拖长了3倍？别盯着被弄乱的东西，看看宝宝日益增长的自信。耐心快用完时，去博客读读怎样用游戏化解小危机，深呼吸一下。' WHERE id = 'ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El temporizador se ha parado y el peque duerme. Olvídate de las tareas de casa, todo puede esperar. Prepárate una bebida rica de Recetas saludables y disfruta de un rato a solas contigo.', body_fr = 'Le minuteur s''est arrêté, l''enfant dort. Oubliez les tâches ménagères, tout peut attendre. Préparez une boisson originale avec les Recettes saines et savourez un moment rien qu''à vous.', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के काम भूल जाइए, सब इंतज़ार कर सकता है। सेहतमंद रेसिपी से कोई मज़ेदार ड्रिंक बनाइए और अपने साथ वक्त बिताने का मज़ा लीजिए।', body_id = 'Timer berhenti, anak sudah tidur. Lupakan pekerjaan rumah, semuanya bisa menunggu. Buat minuman menarik dari Resep Sehat dan nikmati waktu untuk diri sendiri.', body_ja = 'タイマーが止まり、子どもは眠りました。家事は忘れて、何でも後回しで大丈夫。「ヘルシーレシピ」からおいしいドリンクをつくって、ひとりの時間を楽しみましょう。', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일은 잊으세요, 다 기다려 줄 수 있어요. 건강한 레시피에서 색다른 음료를 만들어 나만의 시간을 즐기세요.', body_nl = 'De timer is gestopt, je kind slaapt. Vergeet het huishouden, alles kan wachten. Maak een lekker drankje uit Gezonde recepten en geniet van de tijd voor jezelf.', body_pl = 'Timer się zatrzymał, dziecko śpi. Zapomnij o obowiązkach domowych, wszystko może poczekać. Przygotuj ciekawy napój ze Zdrowych przepisów i rozkoszuj się chwilą dla siebie.', body_pt = 'O temporizador parou, a criança adormeceu. Esqueça as tarefas da casa, tudo pode esperar. Prepare uma bebida diferente das Receitas Saudáveis e saboreie este tempo só para si.', body_sv = 'Timern har stannat, barnet sover. Glöm hushållssysslorna, allt kan vänta. Gör en god dryck från Hälsosamma recept och njut av att vara för dig själv.', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Hãy quên việc nhà đi, mọi thứ đều có thể chờ. Pha một thức uống thú vị từ Công thức lành mạnh và tận hưởng khoảng thời gian cho riêng mình.', body_zh = '计时器停了，宝宝睡着了。家务先放一边，什么都可以等。从健康食谱里做一杯有趣的饮品，享受和自己独处的时光吧。' WHERE id = '086dfc4e-9fb2-412e-ade9-cb121424e290' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de calma 🤫', title_fr = 'Besoin de calme 🤫', title_hi = 'शांति की ज़रूरत 🤫', title_id = 'Butuh ketenangan 🤫', title_ja = '静けさがほしい 🤫', title_ko = '고요가 필요해 🤫', title_nl = 'Behoefte aan rust 🤫', title_pl = 'Potrzeba ciszy 🤫', title_pt = 'Necessidade de sossego 🤫', title_sv = 'Behov av lugn 🤫', title_vi = 'Cần chút yên tĩnh 🤫', title_zh = '需要安静 🤫' WHERE id = '01916001-64ad-41ab-8fea-1c1101a3ae1c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Le encanta cerrar las puertas de todas las habitaciones y dejarte fuera. Su idea del espacio personal está en plena revolución. Toma medidas para que no se pille los dedos, pero no le estropees este juego de marcar su territorio.', body_fr = 'Il prend un malin plaisir à fermer derrière lui les portes de toutes les pièces et à vous laisser dehors. La notion d''espace personnel fait sa révolution. Prenez vos précautions pour qu''il ne se coince pas les doigts, mais ne gâchez pas ce jeu où il proclame son territoire.', body_hi = 'घर के सारे कमरों के दरवाज़े अंदर से बंद करके आपको बाहर छोड़ने में उसे खास मज़ा आता है। ‘अपनी जगह’ की समझ में क्रांति आ रही है। उँगलियाँ न दबें, इसका इंतज़ाम कीजिए, पर अपना इलाका घोषित करने के उसके इस खेल को बिगाड़िए मत।', body_id = 'Ia senang sekali menutup pintu semua kamar di rumah dan meninggalkan Anda di luar. Konsep ruang pribadinya sedang berkembang pesat. Lakukan pencegahan agar jarinya tidak terjepit, tapi jangan merusak permainannya dalam mengklaim wilayahnya sendiri.', body_ja = '家じゅうの部屋のドアを閉めて、あなたを外に締め出すのが楽しくてたまらない様子。自分だけの空間という考えが芽生えています。指をはさまないよう気をつけつつ、自分の陣地を宣言するこの遊びはじゃましないであげて。', body_ko = '집 안 모든 방문을 닫고 엄마를 밖에 두는 걸 유난히 즐기나요? 개인 공간에 대한 개념이 혁명을 맞았어요. 손가락이 끼지 않게 조심만 하고, 자기 영역을 선포하는 이 놀이는 크게 방해하지 마세요.', body_nl = 'Hij vindt het heerlijk om alle deuren in huis achter zich dicht te doen en jou buiten te laten staan. Zijn besef van persoonlijke ruimte maakt een revolutie door. Zorg dat zijn vingers niet klem komen te zitten, maar verpest dit spelletje van ''mijn eigen gebied'' niet.', body_pl = 'Z wielką frajdą zamyka za sobą drzwi do wszystkich pokoi i zostawia cię na zewnątrz. Poczucie własnej przestrzeni przeżywa rewolucję. Zadbaj o to, by nie przytrzasnął sobie palców, ale nie psuj mu tej zabawy w ogłaszanie własnego terytorium.', body_pt = 'Tem um prazer especial em fechar todas as portas da casa atrás de si e deixá-la do lado de fora. A noção de espaço pessoal está em plena revolução. Proteja os dedos dele, mas não estrague a sério este jogo de declarar o seu próprio território.', body_sv = 'Barnet stänger dörrarna till alla rum bakom sig och tycker det är extra roligt att lämna dig utanför. Förståelsen för det egna utrymmet gör revolution. Se till att inga fingrar kläms, men förstör inte leken där barnet gör anspråk på sitt eget revir.', body_vi = 'Bé thích thú đặc biệt với việc đóng hết cửa các phòng trong nhà và để mẹ ở bên ngoài. Khái niệm không gian riêng của bé đang "bùng nổ". Hãy đề phòng để bé không bị kẹp tay, nhưng đừng phá hỏng trò chơi tuyên bố "lãnh thổ" của bé.', body_zh = '把家里每个房间的门都从里面关上，把你关在外面，玩得特别开心？“私人空间”的概念正在觉醒。注意别夹到手指，但也别破坏这个宣示“自己领地”的游戏。' WHERE id = '97aa3207-a7a2-42a1-9e74-01d2388db3b1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Está sentado frente a la lavadora, tan concentrado en la ropa que gira como si viera dibujos animados. Es un entretenimiento gratis que calma la mente. No le interrumpas y aprovecha tú también para descansar: el caos se ha tomado un pequeño respiro.', body_fr = 'Assis devant la machine à laver, il est si concentré sur le linge qui tourne qu''on dirait qu''il regarde un dessin animé. C''est un divertissement totalement gratuit qui apaise l''esprit. Ne le dérangez pas, profitez-en pour vous reposer, le chaos fait une courte pause.', body_hi = 'वॉशिंग मशीन के सामने बैठकर घूमते कपड़ों पर ऐसे ध्यान लगाए है जैसे कार्टून देख रहा हो। यह बिल्कुल मुफ़्त और मन को शांत करने वाला मनोरंजन है। उसे मत रोकिए, आप भी मौके का फ़ायदा उठाकर आराम कीजिए, अफ़रा-तफ़री ने छोटा सा ब्रेक लिया है।', body_id = 'Ia duduk di depan mesin cuci dan begitu fokus menatap baju yang berputar, seolah sedang menonton kartun. Ini hiburan gratis yang menenangkan pikiran. Jangan ganggu, manfaatkan kesempatan ini untuk beristirahat, kekacauan sedang rehat sebentar.', body_ja = '洗濯機の前に座って、回る洗濯物にアニメを見ているかのように夢中。これはまったくお金のかからない、心が落ち着く遊びです。じゃまをしないで、あなたもこの機会に休みましょう。カオスがちょっとひと休みしています。', body_ko = '세탁기 앞에 앉아 돌아가는 빨래에 만화를 보듯 집중하고 있나요? 완전히 공짜에 마음까지 차분해지는 놀이예요. 방해하지 말고 엄마도 이 기회에 쉬세요. 혼돈이 잠깐 쉬는 시간이에요.', body_nl = 'Hij zit voor de wasmachine en kijkt zo geconcentreerd naar de draaiende kleren alsof het een tekenfilm is. Dit is helemaal gratis vermaak dat zijn hoofd tot rust brengt. Stoor hem niet en grijp zelf ook de kans om uit te rusten, de chaos heeft even pauze.', body_pl = 'Siedzi przed pralką i tak wpatruje się w kręcące się ubrania, jakby oglądał bajkę. To całkowicie darmowa i uspokajająca rozrywka. Nie przeszkadzaj mu, wykorzystaj okazję i też odpocznij, chaos zrobił sobie krótką przerwę.', body_pt = 'Sentou-se em frente à máquina de lavar e está tão concentrado na roupa a girar como se visse desenhos animados. É um entretenimento totalmente gratuito que acalma a mente. Não o interrompa: aproveite também para descansar, o caos fez uma pequena pausa.', body_sv = 'Barnet sitter framför tvättmaskinen och är så fokuserat på kläderna som snurrar, som om det vore en tecknad film. Det är en helt gratis underhållning som lugnar sinnet. Stör inte, ta tillfället i akt och vila du också, kaoset tar en kort paus.', body_vi = 'Bé ngồi trước máy giặt, chăm chú nhìn quần áo quay như đang xem phim hoạt hình. Đây là trò giải trí hoàn toàn miễn phí và giúp tâm trí dịu lại. Đừng làm phiền bé, mẹ cũng tranh thủ nghỉ ngơi đi, sự hỗn loạn đang tạm nghỉ một chút.', body_zh = '坐在洗衣机前，盯着转动的衣服看得入迷，就像在看动画片。这是完全免费、还能让大脑平静的娱乐。别打扰，你也趁机休息一下，混乱暂时按下了暂停键。' WHERE id = '6ae9e7b9-b61e-4945-82bd-3ceb19652949' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras le lees el cuento, a la mínima salta de la cama para ir a por su juguete. No quiere rendirse al sueño. Baja de repente mucho la voz y sigue leyendo en susurros. Para oírte tendrá que volver a la cama y prestar toda su atención.', body_fr = 'Pendant le conte, il saute du lit à la moindre occasion pour aller chercher un jouet. Il ne veut pas céder au sommeil. Baissez soudain la voix et lisez en chuchotant. Pour vous entendre, il sera obligé de revenir au lit et de tendre l''oreille.', body_hi = 'कहानी पढ़ते समय हर मौके पर बिस्तर से कूदकर ‘मैं अपना खिलौना लाता हूँ’ कहकर भागता है? नींद के आगे हार नहीं मानना चाहता। अचानक अपनी आवाज़ बहुत धीमी करके फुसफुसाकर पढ़ना शुरू कीजिए। आपको सुनने के लिए उसे मजबूरन बिस्तर पर लौटकर ध्यान लगाना पड़ेगा।', body_id = 'Saat dibacakan dongeng, setiap ada kesempatan ia melompat dari tempat tidur untuk mengambil mainannya. Ia tidak mau menyerah pada kantuk. Tiba-tiba turunkan suara Anda dan mulailah membaca sambil berbisik. Agar bisa mendengar Anda, ia terpaksa kembali ke tempat tidur dan menyimak.', body_ja = '絵本を読んでいると、何かと理由をつけて「おもちゃ持ってくる」とベッドから飛び出していく。眠りに負けたくないんですね。声のトーンを急にぐっと下げて、ささやき声で読み始めてみて。聞きとろうとして自然にベッドに戻り、耳をすませますよ。', body_ko = '동화를 읽는 동안 틈만 나면 ''장난감 가져올래'' 하며 침대에서 뛰쳐나가나요? 잠에 항복하기 싫은 거예요. 갑자기 목소리를 아주 낮춰 속삭이듯 읽기 시작하세요. 엄마 말을 들으려고 저절로 침대로 돌아와 귀를 기울일 거예요.', body_nl = 'Tijdens het voorlezen springt hij bij elke kans uit bed om nog even een speeltje te halen. Hij wil zich niet overgeven aan de slaap. Ga ineens heel zacht praten en lees fluisterend verder. Om je te kunnen horen, moet hij wel terug in bed kruipen en goed opletten.', body_pl = 'Podczas czytania bajki przy każdej okazji wyskakuje z łóżka, bo musi przynieść zabawkę. Nie chce poddać się snowi. Nagle mocno ścisz głos i zacznij czytać szeptem. Żeby cię usłyszeć, będzie musiał wrócić do łóżka i się skupić.', body_pt = 'Enquanto lê a história, salta da cama a cada oportunidade para ir buscar um brinquedo. Não quer render-se ao sono. Baixe de repente muito o tom de voz e comece a ler em sussurro. Para a ouvir, vai ter de voltar para a cama e prestar atenção.', body_sv = 'Under sagoläsningen hoppar barnet ur sängen vid varje tillfälle för att hämta en leksak. Hen vill inte ge upp för sömnen. Sänk plötsligt rösten rejält och börja läsa viskande. För att höra dig måste barnet gå tillbaka till sängen och lyssna noga.', body_vi = 'Đang đọc truyện, bé cứ chốc chốc lại nhảy khỏi giường đòi đi lấy đồ chơi. Bé chưa muốn chịu thua giấc ngủ. Hãy đột ngột hạ giọng thật nhỏ và bắt đầu đọc thì thầm. Để nghe được mẹ, bé sẽ phải quay lại giường và lắng nghe chăm chú.', body_zh = '讲故事时，总是一有机会就从床上跳起来，说“我去拿玩具”。就是不想乖乖睡觉。突然把声音压得很低，用悄悄话来读吧。为了听清你说什么，宝宝只好回到床上，专心听。' WHERE id = '9069176c-b719-421b-bb4f-85cd101945a6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esto lo he encontrado yo: el toddler posesivo 🔑', title_fr = 'C''est moi qui l''ai trouvé : le tout-petit possessif 🔑', title_hi = '‘यह मुझे मिला’: हक जताने वाला टॉडलर 🔑', title_id = 'Ini aku yang menemukan - balita posesif 🔑', title_ja = 'これ、ぼくが見つけた - 持ちものにこだわるトドラー 🔑', title_ko = '내가 찾은 거야: 소유욕 강한 토들러 🔑', title_nl = 'Dat heb ik gevonden! De bezitterige peuter 🔑', title_pl = 'Ja to znalazłem - mały właściciel 🔑', title_pt = 'Fui eu que encontrei: o pequeno possessivo 🔑', title_sv = 'Jag hittade den: den ägande 3-åringen 🔑', title_vi = 'Con tìm thấy mà! - Bé chập chững thích chiếm hữu 🔑', title_zh = '“这是我找到的”：爱占有的小家伙 🔑' WHERE id = '48be6a74-039a-47b4-b2e6-38a02b369aa1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mini spa en el baño 🛀', body_es = 'Esta noche no lo metas solo a él en la bañera, métete tú también. Cuando el peque se duerma: agua caliente, un poco de espuma y una sola vela encendida en el baño. Cierra la puerta con pestillo y durante 15 minutos deja el papel de mamá y vuelve a ser tú. Te lo mereces.', title_fr = 'Mini-spa dans la salle de bain 🛀', body_fr = 'Ce soir, ce n''est pas seulement lui qui prend un bain, c''est vous aussi. Une fois l''enfant couché : de l''eau chaude, un peu de mousse et une seule bougie allumée. Fermez la porte à clé et, pendant 15 minutes seulement, quittez votre rôle de maman pour redevenir vous-même. Vous le méritez.', title_hi = 'बाथरूम में मिनी-स्पा 🛀', body_hi = 'आज शाम सिर्फ़ उसे नहीं, खुद को भी नहलाइए। बच्चे के सोने के बाद गरम पानी, थोड़ा झाग और बाथरूम में जलती एक मोमबत्ती। दरवाज़ा बंद कीजिए और बस 15 मिनट के लिए माँ की भूमिका से बाहर आकर फिर से खुद बन जाइए, आप इसकी हक़दार हैं।', title_id = 'Mini spa di kamar mandi 🛀', body_id = 'Malam ini, bukan hanya ia yang masuk bak mandi, Anda juga. Setelah anak tidur: air hangat, sedikit busa, dan satu lilin menyala di kamar mandi. Kunci pintunya, dan selama 15 menit keluarlah dari peran ibu dan jadilah diri Anda lagi. Anda pantas mendapatkannya.', title_ja = 'バスルームでミニスパ 🛀', body_ja = '今夜はお子さんだけでなく、あなたもお風呂に入りましょう。子どもが寝たら、温かいお湯に少しの泡、そしてキャンドルをひとつ。ドアに鍵をかけて、たった15分だけママの役をおりて、自分自身に戻りましょう。あなたにはその価値があります。', title_ko = '욕실 속 미니 스파 🛀', body_ko = '오늘 저녁엔 아이만 욕조에 넣지 말고 엄마도 들어가세요. 아이가 잠든 뒤 따뜻한 물, 약간의 거품, 그리고 욕실에 켜 둔 초 하나. 문을 잠그고 딱 15분만 엄마 역할에서 벗어나 다시 나 자신이 되세요. 그럴 자격이 있어요.', title_nl = 'Minispa in de badkamer 🛀', body_nl = 'Laat vanavond niet alleen hem in bad gaan, maar ook jezelf. Als hij slaapt: warm water, wat schuim en één brandende kaars in de badkamer. Doe de deur op slot en stap 15 minuten lang uit je rol als mama om weer even jezelf te zijn. Dat verdien je.', title_pl = 'Mini-spa w łazience 🛀', body_pl = 'Dziś wieczorem kąpiel nie tylko dla niego, ale i dla ciebie. Gdy dziecko zaśnie: ciepła woda, trochę piany i jedna zapalona świeca. Zamknij drzwi na klucz i choć na 15 minut wyjdź z roli mamy i znów bądź sobą, zasługujesz na to.', title_pt = 'Mini-spa na casa de banho 🛀', body_pt = 'Esta noite, não é só ele que vai para a banheira, a mãe também. Depois de a criança adormecer: água quente, um pouco de espuma e uma única vela acesa. Feche a porta à chave e, durante apenas 15 minutos, saia do papel de mãe e volte a ser você. Merece-o.', title_sv = 'Mini-spa i badrummet 🛀', body_sv = 'I kväll är det inte bara barnet som ska i badet, utan du också. När barnet sover: varmt vatten, lite skum och ett enda tänt ljus i badrummet. Lås dörren och kliv ur mammarollen i bara 15 minuter och bli dig själv igen, det förtjänar du.', title_vi = 'Mini-spa trong phòng tắm 🛀', body_vi = 'Tối nay, đừng chỉ tắm cho bé, hãy tắm cho cả chính mình. Sau khi bé ngủ: nước ấm, một chút bọt và một ngọn nến duy nhất trong phòng tắm. Khóa cửa lại và chỉ trong 15 phút, hãy tạm rời vai trò làm mẹ để lại là chính mình, mẹ xứng đáng với điều đó.', title_zh = '浴室里的迷你水疗 🛀', body_zh = '今晚不只给宝宝洗澡，也让自己泡一泡。宝宝睡着后，温热的水、一点泡泡，再点一支蜡烛。锁上门，只用15分钟走出妈妈的角色，重新做回自己，这是你应得的。' WHERE id = '54609407-cfb4-47a1-8f37-28a152cd5950' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesión en el Diario de ánimo', body_es = 'Coge el móvil. En lugar de pasar por la vida de otros en las redes sociales, abre el Diario de ánimo y apunta para el futuro el momento más gracioso que ha tenido hoy. Esta terapia digital también te relajará: mira en la pantalla cómo se van volando las penas.', title_fr = 'Confidence dans le Journal d''humeur', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler la vie des autres sur les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard son moment le plus drôle de la journée. Cette thérapie numérique vous fera du bien aussi : regardez vos soucis s''envoler à l''écran.', title_hi = 'मूड डायरी में एक कबूलनामा', body_hi = 'फ़ोन हाथ में लीजिए। सोशल मीडिया पर दूसरों की ज़िंदगी स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज उसका सबसे मज़ेदार पल भविष्य के लिए लिख लीजिए। यह डिजिटल थेरेपी आपको भी सुकून देगी, स्क्रीन पर देखिए कि परेशानियाँ कैसे उड़ जाती हैं।', title_id = 'Pengakuan di Buku Harian Suasana Hati', body_id = 'Ambil ponsel Anda. Daripada menggulir kehidupan orang lain di media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucunya hari ini untuk masa depan. Terapi digital ini juga akan membuat Anda rileks, lihat di layar bagaimana beban Anda terbang.', title_ja = '気分日記でひと言', body_ja = 'スマホを手にとって。SNSでほかの人の暮らしをスクロールするかわりに、「気分日記」を開いて、今日のいちばんおもしろかった瞬間を未来のために記録しましょう。デジタルセラピーはあなたの心も休めてくれます。悩みが飛んでいくのを画面で見てみて。', title_ko = '기분 일기에 털어놓기', body_ko = '휴대폰을 들어 보세요. SNS에서 남의 삶을 넘겨보는 대신 기분 일기를 열고 오늘 아이가 보여 준 가장 웃긴 순간을 나중을 위해 기록해 두세요. 디지털 치료가 엄마에게도 쉼이 되어, 화면을 보며 걱정이 날아가는 걸 느낄 거예요.', title_nl = 'Een bekentenis in het Stemmingsdagboek', body_nl = 'Pak je telefoon. Scrol niet door het leven van anderen op social media, maar open je Stemmingsdagboek en noteer het grappigste moment van vandaag voor later. Deze digitale therapie geeft jou ook rust: kijk op het scherm hoe je zorgen wegvliegen.', title_pl = 'Wyznanie w Dzienniku nastroju', body_pl = 'Weź telefon do ręki. Zamiast przewijać cudze życie w mediach społecznościowych, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował. Cyfrowa terapia pozwoli ci odpocząć, zobacz na ekranie, jak odlatują troski.', title_pt = 'Uma confissão no Diário de Humor', body_pt = 'Pegue no telemóvel. Em vez de percorrer a vida dos outros nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico de hoje. A terapia digital também a vai descansar: veja no ecrã como as preocupações voam.', title_sv = 'En bekännelse i Humördagboken', body_sv = 'Ta telefonen. I stället för att scrolla igenom andras liv på sociala medier, öppna Humördagboken och anteckna dagens roligaste stund med barnet för framtiden. Den digitala terapin får dig också att vila, se på skärmen hur bekymren flyger iväg.', title_vi = 'Lời thú nhận trong Nhật ký tâm trạng', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt xem cuộc sống của người khác trên mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc buồn cười nhất của bé hôm nay để làm kỷ niệm. Liệu pháp kỹ thuật số này cũng giúp mẹ thư giãn, hãy nhìn màn hình và thấy những muộn phiền bay đi.', title_zh = '心情日记里的坦白', body_zh = '拿起手机。别去刷社交媒体上别人的生活，打开心情日记，把宝宝今天最搞笑的瞬间记下来，留给未来。这份数字疗愈也会让你放松，看着屏幕，烦恼仿佛都飞走了。' WHERE id = '370a629d-a585-41ae-ad7c-85bbfe349f3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Devuélveme la canción! 🎶', title_fr = 'Remets la chanson ! 🎶', title_hi = 'गाना वापस लगाओ! 🎶', title_id = 'Putar lagi lagunya! 🎶', title_ja = '歌を返して！ 🎶', title_ko = '노래 다시 틀어 줘! 🎶', title_nl = 'Geef mijn liedje terug! 🎶', title_pl = 'Puść piosenkę od nowa! 🎶', title_pt = 'Devolve-me a canção! 🎶', title_sv = 'Spela låten igen! 🎶', title_vi = 'Trả lại bài hát cho con! 🎶', title_zh = '把歌还给我！🎶' WHERE id = '8353b398-30f5-4594-98bd-74c894cfb243' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la Comunidad Anacan 💬', title_fr = 'La force de la Communauté Anacan 💬', title_hi = 'Anacan कम्युनिटी की ताकत 💬', title_id = 'Kekuatan Komunitas Anacan 💬', title_ja = 'Anacanコミュニティの力 💬', title_ko = 'Anacan 커뮤니티의 힘 💬', title_nl = 'De kracht van de Anacan Community 💬', title_pl = 'Siła Społeczności Anacan 💬', title_pt = 'A força da Comunidade Anacan 💬', title_sv = 'Styrkan i Anacan Community 💬', title_vi = 'Sức mạnh của Cộng đồng Anacan 💬', title_zh = 'Anacan社区的力量 💬' WHERE id = '7cbac7ca-9f74-4319-bb84-ce56d77a4832' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Entras en la habitación y lo ves con unas tijeras intentando cortarle el pelo a su muñeca. Vivir este momento es la pesadilla de cualquier mamá. Quítale las tijeras sin enfadarte y guarda este intento de peluquero como un archivo divertido en la Sesión de fotos del bebé.', body_fr = 'En entrant dans la pièce, vous le voyez, ciseaux en main, en train de couper les cheveux de sa poupée. Le cauchemar de toute maman. Sans vous énerver, reprenez les ciseaux et gardez cette tentative de coiffeur comme un souvenir drôle dans la Séance photo bébé.', body_hi = 'कमरे में आती हैं और देखती हैं कि वह कैंची लेकर अपनी गुड़िया के बाल काटने की कोशिश कर रहा है। यह पल हर माँ का डरावना सपना है। बिना नाराज़ हुए कैंची ले लीजिए और इस ‘नाई’ वाली कोशिश को बेबी फ़ोटोशूट में एक मज़ेदार याद की तरह सहेज लीजिए।', body_id = 'Saat masuk kamar, Anda melihatnya memegang gunting dan mencoba memotong rambut bonekanya. Momen ini mimpi buruk setiap ibu. Tanpa marah, ambil guntingnya dan simpan percobaan menjadi tukang cukur ini sebagai arsip lucu di Pemotretan Bayi.', body_ja = '部屋に入ると、はさみを手にお人形の髪を切ろうとしている姿が。どのママにとっても悪夢のような瞬間ですね。怒らずにはさみを受けとって、この美容師ごっこは「ベビーフォトセッション」でおもしろい思い出として残しましょう。', body_ko = '방에 들어갔더니 아이가 가위로 인형 머리를 자르고 있나요? 모든 엄마의 악몽 같은 순간이죠. 화내지 말고 가위를 받아 든 뒤, 이 미용사 도전을 아기 사진 촬영으로 웃긴 기록으로 남겨 두세요.', body_nl = 'Je komt de kamer in en ziet hem met een schaar in de hand het haar van zijn pop knippen. Elke mama''s nachtmerrie. Pak zonder boos te worden de schaar af en bewaar deze kapperspoging als grappige herinnering met de Babyfotoshoot.', body_pl = 'Wchodzisz do pokoju i widzisz, jak z nożyczkami w ręku próbuje obciąć włosy lalce. To koszmar każdej mamy. Bez nerwów zabierz nożyczki i zachowaj tę fryzjerską próbę w Sesji zdjęciowej dziecka jako zabawną pamiątkę.', body_pt = 'Entra no quarto e vê-o de tesoura na mão a tentar cortar o cabelo à boneca. É o pesadelo de qualquer mãe. Sem se irritar, tire-lhe a tesoura e guarde esta tentativa de cabeleireiro como uma memória divertida na Sessão Fotográfica do Bebé.', body_sv = 'När du kommer in i rummet ser du att barnet försöker klippa dockans hår med en sax. Att uppleva den stunden är varje mammas mardröm. Ta saxen utan att bli arg och spara frisörförsöket som ett roligt minne med Babyfotografering.', body_vi = 'Bước vào phòng, mẹ thấy bé đang cầm kéo cố cắt tóc cho búp bê. Đó là nỗi ác mộng của mọi bà mẹ. Đừng nổi giận, hãy nhẹ nhàng lấy kéo đi và lưu lại "lần thử làm thợ cắt tóc" này như một kỷ niệm vui bằng Chụp ảnh cho bé.', body_zh = '走进房间，发现宝宝正拿着剪刀给娃娃剪头发。这一幕是每个妈妈的噩梦。别生气，先把剪刀拿走，再把这次“理发尝试”用宝宝写真存成一份搞笑的纪念吧。' WHERE id = '0cf9c44c-98af-4034-b557-39b1dbb9f133' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Es mío! Cuando todo le pertenece 🧸', title_fr = 'C''est à moi ! Tout s''approprier 🧸', title_hi = '‘वह मेरा है!’: हर चीज़ पर हक जताना 🧸', title_id = 'Itu punyaku! - Mengklaim segalanya 🧸', title_ja = 'それ、ぼくの！ - 何でも自分のもの 🧸', title_ko = '내 거야! 뭐든 다 갖고 싶어 🧸', title_nl = 'Dat is van mij! Alles willen bezitten 🧸', title_pl = 'To moje! - Wszystko jest jego 🧸', title_pt = 'É meu! A fase do "tudo é meu" 🧸', title_sv = 'Den är min! Att äga allt 🧸', title_vi = 'Của con hết! - Giai đoạn chiếm hữu 🧸', title_zh = '“那是我的！”：什么都想占有 🧸' WHERE id = '04ffb755-8100-4999-9284-739b81b180be' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mundo de los cuentos 🪄', body_es = 'Deja a un lado los cuentos clásicos. Abre Cuentos inteligentes. Crea un cuento especial.', title_fr = 'Le monde des contes 🪄', body_fr = 'Laissez de côté les contes classiques. Ouvrez les Contes intelligents. Créez un conte unique.', title_hi = 'कहानियों की दुनिया 🪄', body_hi = 'पुरानी कहानियाँ एक तरफ़ रखिए। स्मार्ट कहानियाँ खोलिए। एक खास कहानी बनाइए।', title_id = 'Dunia dongeng 🪄', body_id = 'Singkirkan dongeng klasik. Buka Dongeng Pintar. Buat dongeng istimewa.', title_ja = 'お話の世界 🪄', body_ja = '昔話はひと休み。「スマートおはなし」を開いて、特別なお話をつくりましょう。', title_ko = '동화의 세계 🪄', body_ko = '고전 동화는 잠시 내려놓으세요. 스마트 동화를 열고 우리만의 동화를 만들어 보세요.', title_nl = 'De wereld van sprookjes 🪄', body_nl = 'Leg de klassieke sprookjes even weg. Open Slimme sprookjes. Maak een eigen sprookje.', title_pl = 'Świat bajek 🪄', body_pl = 'Odłóż klasyczne bajki na bok. Otwórz Mądre bajki. Stwórz wyjątkową bajkę.', title_pt = 'O mundo das histórias 🪄', body_pt = 'Ponha de lado as histórias clássicas. Abra as Histórias Inteligentes. Crie uma história especial.', title_sv = 'Sagornas värld 🪄', body_sv = 'Lägg de klassiska sagorna åt sidan. Öppna Smarta sagor. Skapa en alldeles egen saga.', title_vi = 'Thế giới cổ tích 🪄', body_vi = 'Hãy tạm gác những truyện cổ tích kinh điển. Mở Truyện cổ tích thông minh. Tạo một câu chuyện đặc biệt.', title_zh = '童话世界 🪄', body_zh = '把经典童话先放一边。打开智慧童话，创作一个专属故事吧。' WHERE id = '11adcff5-957f-4e30-8ecc-96f09d1482fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla en susurros con la pared 🤫', body_es = '¿Se mete en la cama, se gira hacia la pared y le cuenta sus cosas a alguien en susurros? ¡Qué ternura! Apaga las luces, escucha cómo esos susurros se mezclan con el sueño y descansa.', title_fr = 'Conversation chuchotée avec le mur 🤫', body_fr = 'Couché dans son lit, tourné vers le mur, il chuchote des confidences à quelqu''un ? C''est tellement mignon ! Éteignez la lumière, écoutez ces chuchotements se mêler au sommeil et reposez-vous.', title_hi = 'दीवार से फुसफुसाती बातें 🤫', body_hi = 'बिस्तर पर जाकर, दीवार की ओर मुँह करके किसी से फुसफुसाकर बातें कर रहा है? कितना प्यारा है! लाइटें बंद कीजिए, सुनिए कि वे फुसफुसाहटें कैसे नींद में घुल जाती हैं, और आराम कीजिए।', title_id = 'Bisik-bisik dengan dinding 🤫', body_id = 'Ia naik ke tempat tidur, menghadap dinding, dan berbisik-bisik curhat dengan seseorang? Manis sekali! Matikan lampu dan beristirahatlah sambil mendengarkan bisikan itu perlahan larut dalam tidur.', title_ja = '壁とひそひそ話 🤫', body_ja = 'ベッドに入って壁のほうを向き、誰かとひそひそおしゃべり？なんてかわいい！明かりを消して、そのささやきが眠りにとけていくのを聞きながら、あなたも休んでね。', title_ko = '벽과 나누는 속삭임 🤫', body_ko = '침대에 누워 벽 쪽으로 돌아누운 채 누군가와 속삭이며 수다를 떨고 있나요? 너무 귀여워요! 불을 끄고 그 속삭임이 잠으로 스며드는 소리를 들으며 쉬세요.', title_nl = 'Fluistergesprekken met de muur 🤫', body_nl = 'Ligt hij in bed met zijn gezicht naar de muur en fluistert hij met iemand? Zo lief! Doe het licht uit, luister hoe dat gefluister overgaat in slaap en rust zelf ook uit.', title_pl = 'Szeptana rozmowa ze ścianą 🤫', body_pl = 'Kładzie się do łóżka, odwraca twarzą do ściany i szeptem się komuś zwierza? Jakie to słodkie! Zgaś światło, posłuchaj, jak te szepty mieszają się ze snem, i odpocznij.', title_pt = 'Segredos sussurrados à parede 🤫', body_pt = 'Deitou-se, virou-se para a parede e está a contar segredos a alguém em sussurro? Que ternura! Apague as luzes e descanse, a ouvir esses sussurros a misturarem-se com o sono.', title_sv = 'Viskande samtal med väggen 🤫', body_sv = 'Har barnet krupit ner i sängen, vänt ansiktet mot väggen och viskar med någon? Så sött! Släck lamporna, lyssna på hur viskningarna smälter ihop med sömnen och vila.', title_vi = 'Thì thầm với bức tường 🤫', body_vi = 'Bé lên giường, quay mặt vào tường và thì thầm tâm sự với ai đó? Thật đáng yêu! Hãy tắt đèn, thư giãn và lắng nghe những lời thì thầm ấy dần hòa vào giấc ngủ.', title_zh = '和墙壁说悄悄话 🤫', body_zh = '钻进被窝，脸朝着墙，悄悄地和谁在说心事？太可爱了！关上灯，听着那些悄悄话慢慢融进梦里，你也歇一歇吧。' WHERE id = 'c78f6742-28ba-40d4-8884-94cee25316f0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha armado una buena porque le has dado el agua en el vaso amarillo? No le des más vueltas, esta mañana solo está poniendo a prueba sus límites. Échale el agua en el vaso azul en un segundo, pon paz en la habitación y guarda tu energía para el resto del día.', body_fr = 'C''est l''apocalypse parce que vous avez servi l''eau dans le verre jaune ? Ne cherchez pas plus loin, il teste juste ses limites ce matin. Versez aussitôt l''eau dans le verre bleu, rétablissez la paix et gardez votre énergie pour le reste de la journée.', body_hi = 'पानी पीले गिलास में दिया, इसलिए कमरे में तूफ़ान आ गया? ज़्यादा मत सोचिए, वह बस आज सुबह अपनी सीमाएँ परख रहा है। फ़ौरन पानी नीले गिलास में डाल दीजिए, कमरे में शांति लौटाइए और अपनी ऊर्जा बाकी दिन के लिए बचाइए।', body_id = 'Kiamat terjadi di kamar karena Anda memberinya air di gelas kuning? Jangan terlalu dipikirkan, ia hanya sedang menguji batasannya pagi ini. Segera tuang airnya ke gelas biru, kembalikan kedamaian di kamar, dan simpan energi Anda untuk sisa hari ini.', body_ja = '黄色いコップでお水を出したから、部屋は大さわぎ？深く考えないで。今朝は境界線をためしているだけです。すぐに青いコップに入れなおして部屋に平和をとり戻し、残りの一日のためにエネルギーを守りましょう。', body_ko = '물을 노란 컵에 줬다고 방이 난리가 났나요? 깊이 생각하지 마세요, 오늘 아침 경계를 시험하는 것뿐이에요. 바로 파란 컵에 물을 옮겨 담아 평화를 되찾고, 남은 하루를 위해 에너지를 아끼세요.', body_nl = 'Breekt de hel los omdat je zijn water in een gele beker gaf? Denk er niet te veel over na, hij test vanochtend gewoon zijn grenzen. Schenk het water meteen in een blauwe beker, breng de vrede terug en spaar je energie voor de rest van de dag.', body_pl = 'W pokoju wybuchła awantura, bo podałaś wodę w żółtym kubku? Nie analizuj, on po prostu sprawdza dziś rano granice. Od razu przelej wodę do niebieskiego kubka, przywróć spokój i zachowaj energię na resztę dnia.', body_pt = 'Caiu o Carmo e a Trindade porque lhe deu a água num copo amarelo? Não pense demasiado: esta manhã está só a testar limites. Deite logo a água num copo azul, restabeleça a paz no quarto e guarde a sua energia para o resto do dia.', body_sv = 'Utbryter världens undergång för att du serverade vattnet i det gula glaset? Gå inte på djupet, barnet testar bara sina gränser i morse. Häll genast över vattnet i det blå glaset, skapa fred i rummet och spara din energi till resten av dagen.', body_vi = 'Cả phòng như "tận thế" chỉ vì mẹ đưa nước bằng cốc màu vàng? Đừng nghĩ nhiều, sáng nay bé chỉ đang thử giới hạn thôi. Rót ngay nước sang cốc màu xanh, lập lại hòa bình trong phòng và giữ sức cho phần còn lại của ngày.', body_zh = '因为用黄杯子倒水，房间里就闹翻天了？别想太多，宝宝只是在今早试探你的底线。马上把水倒进蓝杯子，让房间恢复和平，把精力留给接下来的一天。' WHERE id = 'ca5cea03-5260-4977-bf88-cfe3ed937e38' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Enemistad con la aspiradora 🌪️', body_es = '¿Cuando barres la casa llora y te corta el paso para que no barras «su» polvo? Su sentido de pertenencia ha llegado al absurdo. Apaga la aspiradora y haz una ceremonia de despedida del polvo de 5 minutos. Créeme, el caos acabará antes.', title_fr = 'Ennemi juré de l''aspirateur 🌪️', body_fr = 'Quand vous passez l''aspirateur, il pleure et vous barre la route en criant « Aspire pas ma poussière ! » ? Son sentiment d''appartenance atteint l''absurde. Éteignez l''aspirateur et organisez pendant 5 minutes une cérémonie d''au revoir à la poussière. Croyez-moi, ce chaos finira plus vite.', title_hi = 'वैक्यूम क्लीनर से दुश्मनी 🌪️', body_hi = 'घर साफ़ करते समय ‘मेरी धूल मत उठाओ’ कहकर रोते हुए रास्ता रोकता है? अपनेपन का एहसास हद पार कर गया है। वैक्यूम बंद कीजिए और 5 मिनट धूल को ‘बाय-बाय’ कहने की रस्म कीजिए। यकीन मानिए, इससे यह अफ़रा-तफ़री जल्दी खत्म होगी।', title_id = 'Bermusuhan dengan penyedot debu 🌪️', body_id = 'Saat Anda menyapu rumah, ia menangis menghadang sambil berkata ''Jangan sapu debuku''? Rasa memilikinya sudah sampai tingkat absurd. Matikan sapunya dan adakan upacara ''dadah debu'' selama 5 menit. Percayalah, ini akan mengakhiri kekacauan lebih cepat.', title_ja = '掃除機とのたたかい 🌪️', body_ja = '掃除をしていると「ぼくのほこりを吸わないで」と泣いて立ちはだかる？「自分のもの」という気持ちがおかしなほど強くなっています。掃除機を止めて、5分間ほこりに「バイバイ」する儀式をしてみて。そのほうが早くおさまりますよ。', title_ko = '청소기와의 전쟁 🌪️', body_ko = '청소기를 돌리면 ''내 먼지 치우지 마!'' 하고 울며 막아서나요? 소유욕이 엉뚱한 경지에 이르렀어요. 청소기를 끄고 5분간 먼지에게 ''안녕'' 인사하는 의식을 치러 주세요. 정말이에요, 이 혼란이 더 빨리 끝나요.', title_nl = 'Vijandschap met de stofzuiger 🌪️', body_nl = 'Staat hij huilend in de weg als je stofzuigt, omdat je ''zijn stof'' niet mag opzuigen? Zijn gevoel van bezit is absurd geworden. Zet de stofzuiger uit en houd 5 minuten een ''dag-dag stof''-ceremonie. Geloof ons, zo is de chaos sneller voorbij.', title_pl = 'Wojna z odkurzaczem 🌪️', body_pl = 'Gdy sprzątasz, płacze „nie zamiataj moich okruszków” i zastępuje ci drogę? Poczucie posiadania sięgnęło absurdu. Wyłącz odkurzacz i urządź 5-minutową ceremonię pożegnania z okruszkami. Uwierz, ten chaos skończy się szybciej.', title_pt = 'Inimigo do aspirador 🌪️', body_pt = 'Enquanto limpa a casa, chora e põe-se à sua frente a dizer "não aspires o meu pó"? O sentimento de posse chegou ao absurdo. Desligue o aspirador e faça uma cerimónia de 5 minutos para dizer adeus ao pó. Acredite, o caos acaba mais depressa.', title_sv = 'Fiende med dammsugaren 🌪️', body_sv = 'Gråter barnet och ställer sig i vägen när du städar: ”Sug inte upp mitt damm!”? Ägarkänslan har nått absurda nivåer. Stäng av dammsugaren och håll en 5 minuters hejdå-ceremoni för dammet. Tro mig, då tar kaoset slut fortare.', title_vi = 'Kẻ thù máy hút bụi 🌪️', body_vi = 'Khi mẹ quét nhà, bé khóc và chắn đường: "Đừng quét bụi của con"? Cảm giác sở hữu của bé đã đến mức phi lý. Hãy tắt máy và tổ chức "lễ tạm biệt bụi" 5 phút. Tin đi, sự hỗn loạn này sẽ kết thúc nhanh hơn.', title_zh = '和吸尘器的“深仇大恨” 🌪️', body_zh = '你扫地时，宝宝哭着挡住你说“别扫我的灰尘”？归属感已经强烈到有点荒诞了。关掉扫帚，花5分钟办一场和灰尘说“拜拜”的仪式。相信我，这样混乱会结束得更快。' WHERE id = 'f8e8bb79-94ba-4264-b58d-e4f81f8007f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ropa, otra vez al revés 🧥', body_es = '¿Vais a salir y quiere ponerse botas de agua y manga corta? No discutas. Abre el tiempo y la ropa y enséñale que el móvil no lo permite. Deja la regla en manos de la pantalla, quítate de en medio y se pondrá la camiseta tan tranquilo.', title_fr = 'Encore un mélange de vêtements 🧥', body_fr = 'Vous sortez, mais il veut mettre des bottes en caoutchouc et un t-shirt à manches courtes ? Ne discutez pas. Ouvrez Météo et tenue et montrez-lui que le téléphone ne l''autorise pas. Confiez la règle à l''écran, effacez-vous, et il enfilera tranquillement son haut.', title_hi = 'कपड़े फिर गड़बड़ हो गए 🧥', body_hi = 'बाहर जा रहे हैं, पर वह गमबूट और हाफ़ स्लीव पहनना चाहता है? बहस मत कीजिए। मौसम और कपड़े खोलिए और दिखाइए कि फ़ोन इसकी इजाज़त नहीं दे रहा। नियम डिजिटल स्क्रीन पर डाल दीजिए, खुद बीच से हट जाइए, वह चुपचाप अपनी कमीज़ पहन लेगा।', title_id = 'Bajunya salah pilih lagi 🧥', body_id = 'Mau keluar rumah, tapi ia ingin memakai sepatu bot karet dan kaus lengan pendek? Jangan berdebat. Buka Cuaca dan Pakaian, tunjukkan bahwa ponsel tidak mengizinkannya. Serahkan aturan pada layar digital, Anda cukup menyingkir, dan ia akan memakai bajunya dengan tenang.', title_ja = 'また服でもめる 🧥', body_ja = 'お出かけなのに、長ぐつに半そでがいいと言う？言い合いはやめましょう。「天気と服装」を開いて、スマホが「だめ」と言っているのを見せて。ルールはデジタル画面にまかせて、あなたは一歩下がれば、すんなりシャツを着てくれますよ。', title_ko = '옷차림이 또 뒤죽박죽 🧥', body_ko = '외출하려는데 장화에 반팔을 입겠다고 하나요? 다투지 마세요. 날씨와 옷차림을 열어 휴대폰이 허락하지 않는다고 보여 주세요. 규칙은 화면에 맡기고 엄마는 빠지면, 조용히 긴팔을 입을 거예요.', title_nl = 'De kleren zijn weer door elkaar 🧥', body_nl = 'Jullie gaan naar buiten, maar hij wil regenlaarzen en een T-shirt met korte mouwen aan? Ga niet in discussie. Open Weer en kleding en laat zien dat de telefoon het niet toestaat. Laat het scherm de regel brengen, stap zelf opzij, en hij trekt rustig zijn shirt aan.', title_pl = 'Znowu pomieszane ubrania 🧥', body_pl = 'Wychodzicie, a on chce włożyć kalosze i koszulkę z krótkim rękawem? Nie kłóć się. Otwórz Pogodę i ubiór i pokaż, że telefon na to nie pozwala. Przenieś zasadę na ekran, sama zejdź z linii ognia, a on spokojnie założy bluzkę.', title_pt = 'A roupa voltou a baralhar-se 🧥', body_pt = 'Vão sair e ele quer galochas e manga curta? Não discuta. Abra o Tempo e Roupa e mostre-lhe que o telemóvel não deixa. Passe a regra para o ecrã digital, saia de cena e ele vai vestir a camisola sem protestar.', title_sv = 'Kläderna är fel igen 🧥', body_sv = 'Ni ska gå ut, men barnet vill ha gummistövlar och kortärmat? Bråka inte. Öppna Väder och kläder och visa att telefonen inte tillåter det. Lägg regeln på den digitala skärmen, kliv själv åt sidan, så tar barnet lugnt på sig tröjan.', title_vi = 'Quần áo lại lộn xộn rồi 🧥', body_vi = 'Sắp ra ngoài mà bé đòi đi ủng cao su với áo cộc tay? Đừng tranh cãi. Mở Thời tiết và trang phục, cho bé thấy điện thoại "không cho phép" bộ đồ đó. Để màn hình đặt ra quy tắc, mẹ đứng ngoài cuộc, bé sẽ ngoan ngoãn mặc áo vào.', title_zh = '衣服又穿乱了 🧥', body_zh = '要出门了，宝宝却想穿雨靴配短袖？别争了。打开天气与穿衣，让宝宝看看手机也“不允许”。把规则交给屏幕，你退到一边，宝宝自己就会乖乖穿好上衣。' WHERE id = '0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sueño de una taza de té ☕', body_es = '¿Estás tan cansada que, mientras juega, te has escapado a escondidas a la cocina y has cerrado la puerta? Tienes razón. Abre el Diario de ánimo y escribe solo tres palabras: Hoy he sobrevivido. A veces una mamá solo necesita esa escapada de 5 minutos.', title_fr = 'Le rêve d''une tasse de thé ☕', body_fr = 'Vous êtes si épuisée que, pendant qu''il joue, vous vous êtes faufilée en cachette dans la cuisine en fermant la porte ? Vous avez raison. Ouvrez le Journal d''humeur et écrivez juste quelques mots : « Aujourd''hui, j''ai survécu. » Parfois, une maman a seulement besoin de ces 5 minutes d''évasion.', title_hi = 'एक कप चाय का सपना ☕', body_hi = 'इतनी थक गई हैं कि उसके खेलते समय चुपके से रसोई में भागकर दरवाज़ा बंद कर लिया? आप सही हैं। मूड डायरी खोलिए और बस दो शब्द लिखिए: ‘आज बच गई’। कभी-कभी माँ को बस वही 5 मिनट की छुट्टी चाहिए होती है।', title_id = 'Mimpi secangkir teh ☕', body_id = 'Begitu lelahnya sampai Anda diam-diam kabur ke dapur dan menutup pintu selagi ia bermain? Anda benar. Buka Buku Harian Suasana Hati dan tulis dua kata saja: ''Hari ini aku bertahan.'' Kadang seorang ibu hanya butuh pelarian 5 menit itu.', title_ja = 'お茶一杯の夢 ☕', body_ja = '疲れきって、子どもが遊んでいる間にこっそりキッチンに逃げこんでドアを閉めた？それでいいんです。「気分日記」を開いて、たったひと言「今日も乗りきった」と書きましょう。ママにはときどき、その5分の避難が必要です。', title_ko = '차 한 잔의 꿈 ☕', body_ko = '너무 지쳐서 아이가 노는 사이 몰래 부엌으로 도망가 문을 닫았나요? 그럴 만해요. 기분 일기를 열고 딱 한 줄만 쓰세요: ''오늘도 살아남았다.'' 엄마에겐 가끔 이 5분의 도피만 있으면 돼요.', title_nl = 'Dromen van een kopje thee ☕', body_nl = 'Ben je zo moe dat je stiekem naar de keuken bent gevlucht en de deur hebt dichtgedaan terwijl hij speelt? Je hebt gelijk. Open je Stemmingsdagboek en schrijf maar twee woorden: ''Vandaag overleefd.'' Soms heeft een mama gewoon die ontsnapping van 5 minuten nodig.', title_pl = 'Marzenie o filiżance herbaty ☕', body_pl = 'Jesteś tak zmęczona, że gdy on się bawi, ukradkiem uciekłaś do kuchni i zamknęłaś drzwi? Masz rację. Otwórz Dziennik nastroju i napisz tylko trzy słowa: „Dziś przetrwałam”. Czasem mamie potrzebna jest tylko ta 5-minutowa ucieczka.', title_pt = 'O sonho de uma chávena de chá ☕', body_pt = 'Está tão cansada que, enquanto ele brinca, fugiu às escondidas para a cozinha e fechou a porta? Tem toda a razão. Abra o Diário de Humor e escreva só três palavras: "hoje sobrevivi". Às vezes a mãe só precisa dessa fuga de 5 minutos.', title_sv = 'Drömmen om en kopp te ☕', body_sv = 'Är du så trött att du smög ut i köket och stängde dörren medan barnet lekte? Du gör rätt. Öppna Humördagboken och skriv bara tre ord: Jag överlevde idag. Ibland behöver en mamma bara den där 5-minutersflykten.', title_vi = 'Giấc mơ một tách trà ☕', body_vi = 'Mệt đến mức mẹ lén chạy vào bếp và đóng cửa lại khi bé đang chơi? Mẹ hoàn toàn có lý. Hãy mở Nhật ký tâm trạng và viết chỉ vài chữ: "Hôm nay mình đã sống sót." Đôi khi, mẹ chỉ cần 5 phút "trốn chạy" như thế.', title_zh = '一杯茶的梦想 ☕', body_zh = '累到趁宝宝玩的时候，偷偷溜进厨房关上门？你没有错。打开心情日记，只写几个字：“今天我活下来了。”有时候，妈妈需要的就只是这5分钟的逃离。' WHERE id = '310c5e1a-58e7-49ee-a785-62a8445bbaba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Atrapa la nube, que no se vaya! ☁️', body_es = '¿Mira por la ventana y llora porque la nube se va? No pierdas tiempo explicándole el viento con ciencia. Dile que se ha ido a saludar a otros niños. Cambia su curiosa filosofía por un poco de humor y pequeñas historias inventadas, y salva el día.', title_fr = 'Attrape le nuage, qu''il ne parte pas ! ☁️', body_fr = 'Il regarde par la fenêtre et pleure parce que le nuage s''en va ? Ne perdez pas de temps à expliquer le vent scientifiquement. Dites-lui : « Il est parti dire bonjour aux autres enfants. » Remplacez sa drôle de philosophie par un peu d''humour et de petites histoires inventées, et sauvez la journée.', title_hi = 'बादल को पकड़ो, जाने न दो! ☁️', body_hi = 'खिड़की से देखकर बादल के चले जाने पर रो रहा है? हवा का वैज्ञानिक कारण समझाने में समय मत गँवाइए। कहिए, ‘वह अब दूसरे बच्चों को नमस्ते कहने गया है।’ उसके इस अनोखे फ़लसफ़े का जवाब हँसी और छोटी-छोटी कहानियों से दीजिए और दिन बचा लीजिए।', title_id = 'Tangkap awannya, jangan biarkan pergi! ☁️', body_id = 'Ia menangis melihat dari jendela karena awannya pergi? Jangan buang waktu menjelaskan angin secara ilmiah. Katakan ''Ia sedang pergi menyapa anak-anak lain''. Ganti filsafat anehnya ini dengan komedi dan sedikit cerita karangan, dan selamatkan hari Anda.', title_ja = '雲をつかまえて、行かないで！ ☁️', body_ja = '窓の外を見て、雲が行ってしまうと泣いている？風の科学的な説明で時間を使わないで。「ほかの子たちにあいさつしに行ったんだよ」と言ってあげて。この子のふしぎな哲学には、ユーモアと小さなお話でこたえて一日を救いましょう。', title_ko = '구름아, 가지 마! ☁️', body_ko = '창밖을 보다가 구름이 떠난다고 우나요? 바람을 과학적으로 설명하느라 시간 쓰지 마세요. ''지금 다른 아이들한테 인사하러 갔어''라고 말해 주세요. 아이의 엉뚱한 철학엔 유머와 작은 상상으로 답하고 하루를 구하세요.', title_nl = 'Vang die wolk, laat hem niet gaan! ☁️', body_nl = 'Huilt hij bij het raam omdat de wolk wegdrijft? Verspil geen tijd aan een wetenschappelijke uitleg over wind. Zeg: ''Hij is nu andere kinderen gedag gaan zeggen.'' Beantwoord zijn vreemde filosofie met humor en kleine verzinsels en red zo de dag.', title_pl = 'Złap chmurkę, niech nie odpływa! ☁️', body_pl = 'Patrzy przez okno i płacze, że chmura odpływa? Nie trać czasu na naukowe tłumaczenie wiatru. Powiedz, że poszła przywitać się z innymi dziećmi. Zamień tę jego dziwną filozofię w komedię i małą bajeczkę i uratuj dzień.', title_pt = 'Agarra a nuvem, não a deixes ir! ☁️', body_pt = 'Chora à janela porque a nuvem foi embora? Não perca tempo a explicar o vento cientificamente. Diga-lhe: "Foi cumprimentar outras crianças". Troque esta filosofia estranha por humor e pequenas histórias inventadas e salve o dia.', title_sv = 'Håll fast molnet, låt det inte gå! ☁️', body_sv = 'Tittar barnet ut genom fönstret och gråter för att molnet åker iväg? Slösa inte tid på att förklara vinden vetenskapligt. Säg att det har åkt för att hälsa på andra barn. Byt ut den konstiga filosofin mot humor och små påhitt och rädda dagen.', title_vi = 'Giữ đám mây lại, đừng để nó đi! ☁️', body_vi = 'Bé nhìn qua cửa sổ và khóc vì đám mây trôi đi? Đừng mất thời gian giải thích khoa học về gió. Chỉ cần nói: "Mây đi chào các bạn nhỏ khác rồi." Hãy đáp lại triết lý kỳ lạ của bé bằng chút hài hước và những câu chuyện tưởng tượng nhỏ để cứu vãn cả ngày.', title_zh = '抓住云朵，别让它走！☁️', body_zh = '看着窗外的云飘走，宝宝哭了？别浪费时间用科学解释风。就说：“它现在去跟别的小朋友打招呼了。”用一点幽默和小小的编故事回应宝宝奇特的“哲学”，拯救这一天吧。' WHERE id = 'a80cc41d-cd81-475f-9ddf-075470e2ad74' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lucha en el sofá con papá 🤼‍♂️', body_es = '¿Ha salido corriendo a esconderse para no irse a la cama? Pásale la pelota a papá. Que hagan una lucha de mentira en el sofá. Ese juego ruidoso y sudoroso con papá le quitará hasta la última gota de energía rebelde y lo rendirá al sueño.', title_fr = 'Lutte sur le canapé avec papa 🤼‍♂️', body_fr = 'Il s''est enfui et caché pour ne pas aller au lit ? Passez la balle à papa. Qu''ils fassent semblant de lutter. Ce jeu bruyant et transpirant entre papa et son enfant aspirera ses dernières réserves d''énergie têtue et le livrera au sommeil.', title_hi = 'पापा के साथ सोफ़े पर कुश्ती 🤼‍♂️', body_hi = 'सोने न जाने के लिए भागकर छिप गया? गेंद पापा के पाले में डालिए। उन्हें सोफ़े पर नकली कुश्ती करने दीजिए। पापा के साथ यह शोर-शराबे वाला, पसीना छुड़ाने वाला खेल बच्चे की आखिरी ज़िद्दी ऊर्जा भी सोख लेगा और उसे नींद के हवाले कर देगा।', title_id = 'Gulat di sofa bersama Ayah 🤼‍♂️', body_id = 'Ia lari dan bersembunyi supaya tidak tidur? Oper bolanya ke Ayah. Biarkan mereka gulat pura-pura di sofa. Permainan Ayah dan anak yang heboh dan bikin berkeringat ini akan menyedot sisa energi keras kepalanya dan membuatnya menyerah pada kantuk.', title_ja = 'パパとソファでレスリング 🤼‍♂️', body_ja = '寝たくなくて逃げて隠れた？ボールはパパにパス。ソファでレスリングごっこをしてもらいましょう。にぎやかで汗をかくパパとの遊びが、最後のがんこなエネルギーまで使いきって、眠りへと導いてくれます。', title_ko = '아빠와 소파 레슬링 🤼‍♂️', body_ko = '자러 가기 싫어서 도망쳐 숨었나요? 공을 아빠에게 넘기세요. 소파에서 장난 레슬링을 하게 두세요. 시끌벅적하고 땀나는 아빠와의 놀이가 마지막 남은 고집스러운 에너지까지 빼내 잠에 항복하게 할 거예요.', title_nl = 'Stoeien op de bank met papa 🤼‍♂️', body_nl = 'Is hij weggerend en verstopt om niet naar bed te hoeven? Speel de bal door naar papa. Laat ze op de bank een nepworstelpartij houden. Dat luidruchtige, bezwete spel met papa zuigt zijn laatste koppige energie op en laat hem zich overgeven aan de slaap.', title_pl = 'Zapasy z tatą na kanapie 🤼‍♂️', body_pl = 'Uciekł i schował się, żeby nie iść spać? Przekaż piłeczkę tacie. Niech pobawią się w udawane zapasy. Ta głośna, męcząca zabawa z tatą wyssie z dziecka resztki upartej energii i odda je we władanie snu.', title_pt = 'Luta no sofá com o pai 🤼‍♂️', body_pt = 'Fugiu e escondeu-se para não ir para a cama? Passe a bola ao pai. Que façam uma luta a fingir no sofá. Essa brincadeira barulhenta e suada com o pai vai gastar a última energia teimosa e entregá-lo ao sono.', title_sv = 'Soffbrottning med pappa 🤼‍♂️', body_sv = 'Sprang barnet iväg och gömde sig för att slippa gå och lägga sig? Skicka bollen till pappa. Låt dem låtsasbrottas i soffan. Den högljudda, svettiga leken med pappa suger ut barnets sista envisa energi och får hen att ge upp för sömnen.', title_vi = 'Đấu vật trên sofa cùng bố 🤼‍♂️', body_vi = 'Bé chạy trốn để khỏi phải đi ngủ? Hãy chuyền bóng cho bố. Để hai bố con vật nhau "giả vờ" một trận. Trò chơi ồn ào, đẫm mồ hôi cùng bố sẽ rút cạn chút năng lượng bướng bỉnh cuối cùng và đưa bé vào giấc ngủ.', title_zh = '和爸爸在沙发上摔跤 🤼‍♂️', body_zh = '为了不去睡觉，跑去躲起来了？把球传给爸爸。让他们在沙发上假装摔跤。这场又吵又出汗的父子/父女游戏，会把宝宝最后那点倔强的能量耗光，让宝宝乖乖入睡。' WHERE id = '154abe48-3205-47d2-a68c-a06bfd4856c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cansada de las mamás de internet? 📵', body_es = '¡No te desanimes al abrir Instagram y ver los niños perfectos de todo el mundo! Cierra esa app y entra en la Comunidad Anacan. Verás que en todas las casas hay el mismo desorden que en la tuya y que todos los niños son ruidosos. Respira hondo, ¡no estás sola!', title_fr = 'Fatiguée des mamans d''Internet ? 📵', body_fr = 'Ne vous découragez pas en voyant les enfants parfaits de tout le monde dès que vous ouvrez Instagram ! Fermez cette appli et rejoignez la Communauté Anacan. Voyez que chez les autres aussi, la maison est sens dessus dessous et les enfants bruyants, respirez profondément : vous n''êtes pas seule !', title_hi = 'इंटरनेट वाली माँओं से थक गईं? 📵', body_hi = 'इंस्टाग्राम खोलते ही सबके परफ़ेक्ट बच्चे देखकर हिम्मत मत हारिए! वह ऐप बंद कीजिए और Anacan कम्युनिटी में आइए। देखिए कि सबके घर आपके घर जैसे ही बिखरे हैं और बच्चे उतने ही शोर मचाते हैं, गहरी साँस लीजिए, आप अकेली नहीं हैं!', title_id = 'Lelah dengan ibu-ibu di internet? 📵', body_id = 'Jangan patah semangat melihat anak-anak sempurna orang lain begitu membuka Instagram! Tutup aplikasinya, masuk ke Komunitas Anacan. Lihat bahwa rumah semua orang berantakan seperti rumah Anda dan anak-anak mereka juga berisik, lalu tarik napas dalam. Anda tidak sendirian!', title_ja = 'ネットのママたちに疲れた？ 📵', body_ja = 'インスタを開くたびに、みんなの完璧な子どもを見て落ちこまないで！そのアプリは閉じて、Anacanコミュニティへ。どの家もあなたの家のように散らかっていて、子どもはにぎやかなのを見て、深呼吸しましょう。ひとりじゃないよ！', title_ko = '인터넷 속 엄마들에 지쳤나요? 📵', body_ko = '인스타그램을 열자마자 다들 완벽한 아이만 보여서 기운 빠지나요? 그 앱은 닫고 Anacan 커뮤니티에 들어가 보세요. 다들 집이 엄마 집처럼 엉망이고 아이들도 시끄럽다는 걸 보고 깊게 숨 쉬세요. 혼자가 아니에요!', title_nl = 'Moe van internetmama''s? 📵', body_nl = 'Raak niet ontmoedigd als je op Instagram ieders perfecte kinderen ziet! Sluit die app en ga naar de Anacan Community. Zie dat bij iedereen het huis net zo''n rommel is en de kinderen net zo luidruchtig zijn als bij jou, haal diep adem: je bent niet alleen!', title_pl = 'Masz dość internetowych mam? 📵', body_pl = 'Nie trać ducha, gdy tylko otworzysz Instagram i zobaczysz same idealne dzieci! Zamknij tę aplikację i wejdź do Społeczności Anacan. Zobacz, że u innych w domu jest taki sam bałagan jak u ciebie, a dzieci są równie głośne, i weź głęboki oddech, nie jesteś sama!', title_pt = 'Cansada das mães da internet? 📵', body_pt = 'Não desanime ao ver os filhos perfeitos de toda a gente mal abre o Instagram! Feche essa app e entre na Comunidade Anacan. Vai ver que as casas dos outros estão tão desarrumadas como a sua e os filhos são igualmente barulhentos. Respire fundo, não está sozinha!', title_sv = 'Trött på nätmammorna? 📵', body_sv = 'Bli inte nedslagen av att se allas perfekta barn så fort du öppnar Instagram! Stäng appen och gå in i Anacan Community. Se att alla andras hem är lika stökiga som ditt och deras barn lika högljudda, andas djupt, du är inte ensam!', title_vi = 'Mệt vì những bà mẹ trên mạng? 📵', body_vi = 'Đừng nản lòng khi vừa mở Instagram đã thấy những đứa trẻ hoàn hảo của mọi người! Hãy đóng ứng dụng đó lại và vào Cộng đồng Anacan. Thấy nhà ai cũng bừa bộn, con ai cũng ồn ào như nhà mình, mẹ sẽ thở phào: mình không đơn độc!', title_zh = '被网上的妈妈们累到了？📵', body_zh = '一打开Instagram就看到别人家完美的孩子，别灰心！关掉那个应用，来Anacan社区吧。看到大家家里都和你家一样乱、孩子都一样吵，深呼吸，你不是一个人！' WHERE id = '1d80be38-a3ec-4e4f-a266-479942a81b0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo cocino yo! 🍳', body_es = '¿Quería batir el huevo él solito y medio bol ha acabado en la mesa? Deja que disfrute de esa mirada orgullosa de chef. La cocina se iba a limpiar igualmente, pero no toques su ego en desarrollo ni su independencia.', title_fr = 'C''est moi qui vais cuisiner ! 🍳', body_fr = 'Il tenait absolument à battre les œufs lui-même et la moitié du bol s''est renversée sur la table ? Laissez-le savourer son regard de chef fier. La cuisine sera lavée de toute façon, mais ne touchez pas à son ego en plein développement ni à son indépendance.', title_hi = 'यह मैं बनाऊँगा! 🍳', body_hi = 'अंडा खुद ही फेंटना था और आधा कटोरा मेज़ पर गिर गया? उस गर्वीले शेफ़ वाली नज़र का मज़ा उसे लेने दीजिए। रसोई तो वैसे भी धुलेगी, पर उसके बढ़ते आत्मसम्मान और आत्मनिर्भरता को ठेस मत पहुँचाइए।', title_id = 'Aku yang masak! 🍳', body_id = 'Ia bersikeras mengocok telur sendiri dan setengah isi mangkuk tumpah ke meja? Biarkan ia menikmati tatapan bangga seorang koki. Dapur toh akan dibersihkan, tapi jangan sentuh ego dan kemandiriannya yang sedang tumbuh.', title_ja = 'ぼくが料理する！ 🍳', body_ja = '卵を自分で混ぜると言ってきかず、半分がテーブルにこぼれた？誇らしげなシェフの顔を楽しませてあげて。キッチンはどうせ洗うもの。育っていく自我と自立心には手をつけないであげましょう。', title_ko = '내가 요리할 거야! 🍳', body_ko = '달걀을 꼭 자기가 풀겠다더니 반이 식탁에 쏟아졌나요? 그 뿌듯한 꼬마 셰프의 눈빛을 즐기게 해 주세요. 부엌은 어차피 닦을 거예요. 자라나는 자아와 독립심은 건드리지 마세요.', title_nl = 'Ik ga dit koken! 🍳', body_nl = 'Wilde hij per se zelf het ei kloppen en ging de helft over de tafel? Laat hem genieten van die trotse koksblik. De keuken moet toch schoongemaakt worden, maar kom niet aan zijn groeiende ego en zelfstandigheid.', title_pl = 'Ja to ugotuję! 🍳', body_pl = 'Koniecznie chciał sam roztrzepać jajko i połowa miski wylądowała na stole? Pozwól mu nacieszyć się dumnym spojrzeniem kucharza. Kuchnię i tak trzeba będzie umyć, ale nie podcinaj jego rosnącego ego i samodzielności.', title_pt = 'Sou eu que cozinho! 🍳', body_pt = 'Fez questão de bater os ovos sozinho e metade foi parar à mesa? Deixe-o saborear aquele olhar orgulhoso de cozinheiro. A cozinha vai ser limpa de qualquer forma, mas não toque no ego e na independência que estão a crescer.', title_sv = 'Det är jag som lagar maten! 🍳', body_sv = 'Ville barnet absolut vispa ägget själv och halva skålen hamnade på bordet? Låt hen njuta av sin stolta kockblick. Köket ska ändå diskas, men rör inte den växande självkänslan och självständigheten.', title_vi = 'Con sẽ nấu món này! 🍳', body_vi = 'Bé nhất định tự đánh trứng và một nửa đổ hết ra bàn? Hãy để bé tận hưởng ánh mắt tự hào của một đầu bếp. Bếp đằng nào cũng phải lau, nhưng đừng làm tổn thương cái tôi và sự tự lập đang lớn dần của bé.', title_zh = '我来做饭！🍳', body_zh = '非要自己打鸡蛋，结果一半洒在桌上？让宝宝好好享受那份小厨师的骄傲吧。厨房反正都要收拾，但别伤害宝宝正在成长的自我和独立性。' WHERE id = 'f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La reserva secreta de pasta 🍝', body_es = '¿Al lavarle el pantalón ha salido pasta seca del bolsillo? No es glotonería, es planificación infantil. Tírala a la basura con cara seria, pero sonríe por dentro a ese pequeño explorador y proveedor. ¡Están creciendo!', title_fr = 'La réserve secrète de pâtes 🍝', body_fr = 'En lavant son pantalon, vous avez trouvé des pâtes séchées dans sa poche ? Ce n''est pas de la gourmandise, c''est une planification d''enfant. Jetez-les avec un air sérieux, mais souriez intérieurement à ce petit explorateur ravitailleur. Ils grandissent !', title_hi = 'पास्ता का गुप्त भंडार 🍝', body_hi = 'पैंट धोते समय जेब से सूखा पास्ता निकला? यह लालच नहीं, बच्चों वाली प्लानिंग है। गंभीर चेहरे से उसे कूड़े में डालिए, पर अंदर ही अंदर इस खोजी और भंडार जमा करने वाले बच्चे पर मुस्कुराइए। बच्चे बड़े हो रहे हैं!', title_id = 'Persediaan makaroni rahasia 🍝', body_id = 'Saat mencuci celananya, keluar makaroni kering dari sakunya? Ini bukan rakus, ini perencanaan ala anak-anak. Buang ke tempat sampah dengan wajah serius, tapi dalam hati tersenyumlah pada si penjelajah dan pemasok kecil ini. Mereka sedang tumbuh!', title_ja = 'ひみつのパスタ備蓄 🍝', body_ja = 'ズボンを洗おうとしたら、ポケットから乾いたパスタが出てきた？食いしんぼうではなく、子どもなりの計画です。まじめな顔で捨てながらも、心の中ではこの探検家で調達係の子にほほえんで。大きくなっていますね！', title_ko = '비밀 파스타 비축 🍝', body_ko = '바지를 빨려다 주머니에서 말라붙은 파스타가 나왔나요? 욕심이 아니라 아이다운 계획이에요. 진지한 얼굴로 버리되, 속으로는 이 탐험가이자 보급 담당 꼬마에게 미소 지어 주세요. 이렇게 크는 거예요!', title_nl = 'Geheime pastavoorraad 🍝', body_nl = 'Kwam er bij het wassen opgedroogde pasta uit zijn broekzak? Dat is geen hebzucht, maar kinderlijke planning. Gooi het met een serieus gezicht weg, maar glimlach vanbinnen om deze kleine ontdekkingsreiziger en bevoorrader. Ze worden groot!', title_pl = 'Tajny zapas makaronu 🍝', body_pl = 'Podczas prania spodni z kieszeni wypadł zaschnięty makaron? To nie łakomstwo, tylko dziecięce planowanie. Z poważną miną wyrzuć go do kosza, ale uśmiechnij się w duchu do tego małego zwiadowcy i zaopatrzeniowca. Rosną!', title_pt = 'A reserva secreta de massa 🍝', body_pt = 'Ao lavar as calças, saiu do bolso massa seca? Não é gula, é planeamento infantil. Com uma cara séria, deite-a ao lixo, mas sorria por dentro a este pequeno explorador e fornecedor. Estão a crescer!', title_sv = 'Ett hemligt pastaförråd 🍝', body_sv = 'Hittade du torkad pasta i byxfickan när du tvättade? Det är inte girighet, det är barnslig planering. Släng den med allvarlig min, men le inombords åt den lilla upptäcktsresanden och förrådsförvaltaren. De växer!', title_vi = 'Kho mì ống bí mật 🍝', body_vi = 'Lúc giặt quần cho bé, mẹ thấy trong túi có miếng mì ống khô? Đó không phải tham ăn, mà là một kiểu "lên kế hoạch" của trẻ con. Hãy nghiêm mặt bỏ vào thùng rác, nhưng thầm mỉm cười với nhà thám hiểm kiêm "người dự trữ" nhỏ này. Bé lớn rồi!', title_zh = '秘密的意面储备 🍝', body_zh = '洗裤子时，从口袋里掏出了干掉的意面？这不是贪吃，而是孩子式的“计划”。板着脸把它扔进垃圾桶，但心里对这个小探险家兼“后勤官”笑一笑吧。孩子们都在长大！' WHERE id = '66d60d54-4a5d-4de0-a372-047beaa63d3c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El número del silencio en la pantalla 🤫', body_es = 'Por fin se ha dormido. ¿Hay tanto silencio en casa que te pitan los oídos? Abre el Medidor de sonido en la app. Ver ese 0 decibelios será el mejor masaje visual del mundo para tu cerebro cansado y saturado de ruido.', title_fr = 'Le chiffre du silence à l''écran 🤫', body_fr = 'Il dort enfin. Un tel silence est tombé sur la maison que vos oreilles bourdonnent ? Ouvrez le Sonomètre dans l''application. Voir afficher 0 décibel sera le meilleur massage visuel au monde pour votre cerveau fatigué, saturé de bruit.', title_hi = 'स्क्रीन पर खामोशी का आँकड़ा 🤫', body_hi = 'आखिरकार सो गया। घर में ऐसा सन्नाटा छा गया कि कानों में सीटी सी बज रही है? ऐप में साउंड मीटर खोलिए। वह ‘0 डेसिबल’ देखना आपके थके, शोर से भरे दिमाग के लिए दुनिया की सबसे अच्छी विज़ुअल मसाज होगी।', title_id = 'Angka keheningan di layar 🤫', body_id = 'Akhirnya ia tidur. Rumah begitu hening sampai telinga Anda berdenging? Buka Pengukur Suara di aplikasi. Melihat tulisan 0 desibel itu akan menjadi pijatan visual terbaik di dunia untuk otak Anda yang lelah dan penuh kebisingan.', title_ja = '静けさを示す画面の数字 🤫', body_ja = 'やっと寝てくれた。家が静かすぎて耳鳴りがする？アプリで「サウンドメーター」を開いてみて。0デシベルの表示を見ることが、疲れて騒音でいっぱいの頭にとって、世界一の目のマッサージになります。', title_ko = '화면 속 고요의 숫자 🤫', body_ko = '드디어 잠들었어요. 집이 너무 고요해져 귀가 울릴 정도인가요? 앱에서 소음 측정기를 열어 보세요. 0 데시벨이라는 숫자를 보는 것만으로 소음에 지친 머리에 세상에서 가장 좋은 시각적 마사지가 될 거예요.', title_nl = 'Stilte in cijfers op het scherm 🤫', body_nl = 'Eindelijk slaapt hij. Is het zo stil in huis dat je oren suizen? Open de Geluidsmeter in de app. Kijken naar die 0 decibel is de beste visuele massage voor je vermoeide, door lawaai overprikkelde brein.', title_pl = 'Cisza w liczbach na ekranie 🤫', body_pl = 'Wreszcie zasnął. W domu zapadła taka cisza, że aż dzwoni ci w uszach? Otwórz w aplikacji Miernik dźwięku. Widok napisu 0 decybeli będzie dla twojego zmęczonego, przeładowanego hałasem mózgu najlepszym wizualnym masażem na świecie.', title_pt = 'O número do silêncio no ecrã 🤫', body_pt = 'Finalmente adormeceu. Caiu um silêncio tão grande na casa que lhe zumbem os ouvidos? Abra o Medidor de Som na app. Olhar para aqueles 0 decibéis será a melhor massagem visual do mundo para o seu cérebro cansado e inchado de barulho.', title_sv = 'Tystnaden i siffror på skärmen 🤫', body_sv = 'Äntligen sover barnet. Det har blivit så tyst hemma att det ringer i öronen? Öppna Ljudmätaren i appen. Att titta på 0 decibel blir världens bästa visuella massage för din trötta, bullerfyllda hjärna.', title_vi = 'Con số của sự im lặng trên màn hình 🤫', body_vi = 'Cuối cùng bé cũng ngủ. Nhà yên tĩnh đến mức tai mẹ ù đi? Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số 0 decibel sẽ là màn mát-xa thị giác tuyệt vời nhất cho bộ não mệt mỏi, căng thẳng vì tiếng ồn của mẹ.', title_zh = '屏幕上的安静数字 🤫', body_zh = '终于睡着了。家里安静得让你耳朵都嗡嗡响？打开应用里的分贝仪。看着那个0分贝，对你疲惫、被噪音塞满的大脑来说，就是世界上最好的视觉按摩。' WHERE id = 'd2eca751-d4a9-42ee-89e8-a1b216e785bc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La etiqueta de la camiseta pica! 🏷️', body_es = '¿No se la quiere poner porque esa etiquetita de atrás se le clava como una aguja? La sensibilidad sensorial de los 3,5 años vuelve loco a cualquiera. No entres a discutir: coge las tijeras, córtala de raíz y cierra esta minicrisis en un segundo.', title_fr = 'L''étiquette du t-shirt pique ! 🏷️', body_fr = 'Il refuse de s''habiller parce que la petite étiquette au dos le pique comme une aiguille ? La sensibilité sensorielle de 3 ans et demi rend fou. N''entrez même pas dans la discussion : prenez les ciseaux, coupez-la à la racine et réglez cette mini-crise en une seconde.', title_hi = 'कमीज़ का लेबल चुभ रहा है! 🏷️', body_hi = 'कपड़े नहीं पहनेगा, क्योंकि पीछे का वह छोटा लेबल उसे सुई की तरह चुभता है? 3.5 साल की संवेदी संवेदनशीलता किसी को भी पागल कर दे। बहस में मत पड़िए, कैंची उठाइए, जड़ से काट दीजिए और यह छोटा संकट सेकंडों में खत्म कीजिए।', title_id = 'Label bajunya menusuk! 🏷️', body_id = 'Ia tidak mau berpakaian karena label kecil di belakang bajunya terasa menusuk seperti jarum? Kepekaan sensorik usia 3,5 tahun memang bisa bikin pusing. Jangan berdebat, ambil gunting, potong labelnya sampai habis, dan tutup krisis kecil ini dalam sekejap.', title_ja = 'シャツのタグがチクチク！ 🏷️', body_ja = '背中の小さなタグが針のように刺さるから、着ないと言う？3歳半の感覚の敏感さには参りますよね。言い合いはせずに、はさみでタグを根元から切って、このミニ危機をすぐに解決しましょう。', title_ko = '옷 라벨이 따가워! 🏷️', body_ko = '뒤에 달린 작은 라벨이 바늘처럼 찔러서 안 입겠다고 하나요? 3.5세의 감각 예민함은 정말 사람을 미치게 하죠. 다투지 말고 가위로 라벨을 싹 잘라 이 작은 위기를 바로 끝내세요.', title_nl = 'Dat labeltje prikt! 🏷️', body_nl = 'Wil hij zich niet aankleden omdat dat kleine labeltje achterin prikt als een naald? De zintuiglijke gevoeligheid van een 3,5-jarige kan je gek maken. Ga niet in discussie, pak de schaar, knip het eraf en los deze minicrisis in een seconde op.', title_pl = 'Metka w koszulce gryzie! 🏷️', body_pl = 'Nie założy, bo ta mała metka z tyłu kłuje go jak igła? Wrażliwość sensoryczna 3,5-latka potrafi doprowadzić do szału. Nie wchodź w dyskusję, weź nożyczki, odetnij ją u nasady i zamknij ten mini kryzys w sekundę.', title_pt = 'A etiqueta da camisola pica! 🏷️', body_pt = 'Não se quer vestir porque aquela etiquetazinha atrás o pica como uma agulha? A sensibilidade sensorial dos 3,5 anos dá com qualquer um em doido. Não discuta: pegue na tesoura, corte-a pela raiz e resolva esta mini-crise num segundo.', title_sv = 'Lappen på tröjan sticks! 🏷️', body_sv = 'Barnet vägrar ta på sig tröjan för att den lilla lappen i nacken sticks som en nål? Den sensoriska känsligheten vid 3,5 år kan göra vem som helst galen. Gå inte in i något gräl, ta saxen, klipp bort lappen helt och avsluta minikrisen på en sekund.', title_vi = 'Mác áo cấn quá! 🏷️', body_vi = 'Bé không chịu mặc áo vì cái mác nhỏ sau lưng cấn như kim châm? Sự nhạy cảm giác quan của tuổi 3,5 có thể khiến mẹ phát điên. Đừng tranh cãi, cầm kéo cắt tận gốc và kết thúc "khủng hoảng mini" này trong vài giây.', title_zh = '衣服标签扎人！🏷️', body_zh = '不肯穿，因为背后那个小标签像针一样扎？3岁半的感官敏感真能把人逼疯。别争了，拿起剪刀从根部剪掉，几秒钟就化解这场小危机。' WHERE id = 'd6eb2191-63cd-4b2d-9410-9f12b1424bea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Esa piedra era mía! 🪨', body_es = '¿Llora a gritos porque has tirado la piedra sucia que trajo del parque? Resulta que era su mejor amiga. Busca enseguida otro objeto brillante y salva la situación con maña con una historia inventada: «Mira, la piedra te ha enviado esto de recuerdo».', title_fr = 'Ce caillou, c''était le mien ! 🪨', body_fr = 'Il hurle parce que vous avez jeté le caillou sale qu''il avait rapporté du parc ? C''était apparemment son meilleur ami. Trouvez vite un autre objet brillant et sauvez habilement la situation avec une histoire inventée : « Regarde, le caillou t''a envoyé ça en souvenir. »', title_hi = 'वह पत्थर मेरा था! 🪨', body_hi = 'पार्क से लाया गंदा पत्थर आपने फेंक दिया, इसलिए रो-रोकर चिल्ला रहा है? पता चला, वह उसका सबसे करीबी दोस्त था। फ़ौरन कोई और चमकदार चीज़ ढूँढिए और ‘देखो, पत्थर ने तुम्हें यह याद के तौर पर भेजा है’ कहकर एक मनगढ़ंत कहानी से बड़ी चतुराई से हालात संभालिए।', title_id = 'Batu itu punyaku! 🪨', body_id = 'Ia menjerit karena Anda membuang batu kotor yang ia bawa dari taman? Ternyata itu sahabat terbaiknya. Segera cari benda lain yang berkilau, katakan ''Lihat, batunya mengirim ini sebagai kenang-kenangan untukmu'', dan selamatkan keadaan dengan cerdik lewat cerita karangan.', title_ja = 'あの石、ぼくのだったのに！ 🪨', body_ja = '公園から持ち帰った汚れた石を捨てたら大泣き？なんと親友だったそうです。すぐに別のきらきらしたものを見つけて、「見て、石がこれを記念に送ってくれたよ」とお話をつくって、うまく切りぬけましょう。', title_ko = '그 돌 내 거였어! 🪨', body_ko = '공원에서 주워 온 더러운 돌을 버렸다고 울부짖나요? 알고 보니 가장 친한 친구였네요. 얼른 다른 반짝이는 물건을 찾아 ''봐, 돌이 이걸 기념으로 보내 줬어''라고 이야기를 지어 능숙하게 상황을 수습하세요.', title_nl = 'Die steen was van mij! 🪨', body_nl = 'Jammert hij omdat je die vieze steen uit het park hebt weggegooid? Blijkbaar was het zijn beste vriend. Zoek snel iets anders dat glimt, zeg: ''Kijk, de steen heeft je dit als aandenken gestuurd'' en red de situatie handig met een verzonnen verhaal.', title_pl = 'To był mój kamień! 🪨', body_pl = 'Rozpacza, bo wyrzuciłaś brudny kamień, który przyniósł z parku? Okazuje się, że to był jego najlepszy przyjaciel. Od razu znajdź inny błyszczący przedmiot, powiedz: „Zobacz, kamień przysłał ci to na pamiątkę” i zgrabnie uratuj sytuację wymyśloną historyjką.', title_pt = 'Aquela pedra era minha! 🪨', body_pt = 'Grita porque deitou fora aquela pedra suja que ele trouxe do parque? Afinal era o melhor amigo dele. Encontre logo outro objeto brilhante, diga "Olha, a pedra mandou-te isto de recordação" e salve a situação com mestria com uma história inventada.', title_sv = 'Den stenen var min! 🪨', body_sv = 'Skriker barnet för att du slängde den smutsiga stenen hen tog med från parken? Det visar sig att det var hens bästa vän. Hitta genast ett annat glänsande föremål, säg ”Titta, stenen skickade det här till dig som minne” och rädda situationen skickligt med en påhittad historia.', title_vi = 'Hòn đá đó là của con! 🪨', body_vi = 'Bé gào khóc vì mẹ vứt hòn đá bẩn nhặt từ công viên về? Hóa ra đó là bạn thân nhất của bé. Hãy nhanh tay tìm một món đồ lấp lánh khác và nói: "Nhìn này, hòn đá gửi con làm quà kỷ niệm đấy", khéo léo cứu vãn tình hình bằng một câu chuyện tưởng tượng.', title_zh = '那块石头是我的！🪨', body_zh = '你把从公园捡回来的脏石头扔了，宝宝就大哭？原来那是宝宝最好的朋友。马上找一个亮晶晶的东西，说：“看，石头给你寄来了这个纪念品。”用一个小故事巧妙化解局面。' WHERE id = '772e1eef-c912-4a17-abaa-b5296c686fe3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi cuento, mis reglas 📖', body_es = '¿Te has equivocado en una palabra del cuento y te ha corregido al instante? ¡Se lo sabe de memoria! Cierra el libro y dile: «Entonces esta noche me lo lees tú». Deja que trabaje su mundo imaginario y tú solo túmbate y escucha su voz.', title_fr = 'Mon conte, mes règles 📖', body_fr = 'Vous vous êtes trompée d''un mot en lisant le conte et il vous a aussitôt corrigée ? Il le connaît donc par cœur ! Fermez le livre et dites : « Alors ce soir, c''est toi qui me lis. » Laissez son imaginaire travailler, et vous, allongez-vous et écoutez simplement sa voix.', title_hi = 'मेरी कहानी, मेरे नियम 📖', body_hi = 'कहानी पढ़ते समय कोई शब्द गलत बोला और उसने फ़ौरन आपको ठीक कर दिया? यानी उसे याद हो गई है! किताब बंद कीजिए और कहिए, ‘तो आज शाम तुम मुझे पढ़कर सुनाओ।’ उसकी कल्पना की दुनिया को काम करने दीजिए, और आप बस लेटकर उसकी आवाज़ सुनिए।', title_id = 'Dongengku, aturanku 📖', body_id = 'Saat membacakan dongeng Anda salah mengucapkan satu kata dan ia langsung membetulkan? Berarti ia sudah hafal! Tutup bukunya dan katakan ''Kalau begitu malam ini kamu yang bacakan untuk Mama''. Biarkan dunia khayalnya bekerja, sementara Anda cukup berbaring dan mendengarkan suaranya.', title_ja = 'わたしのお話、わたしのルール 📖', body_ja = '絵本を読んでいて言いまちがえたら、すぐに直された？暗記しているんですね！本を閉じて「じゃあ今夜はママに読んで」と言ってみて。この子の想像の世界を働かせて、あなたは横になって声を聞くだけでOK。', title_ko = '내 동화, 내 규칙 📖', body_ko = '동화를 읽다 한 단어를 틀렸더니 바로 고쳐 주나요? 다 외웠다는 뜻이에요! 책을 덮고 ''그럼 오늘은 네가 읽어 줘''라고 해 보세요. 아이의 상상 세계가 움직이게 두고, 엄마는 누워서 그 목소리만 들으세요.', title_nl = 'Mijn verhaal, mijn regels 📖', body_nl = 'Las je tijdens het voorlezen een woord verkeerd en verbeterde hij je meteen? Dan kent hij het uit zijn hoofd! Sluit het boek en zeg: ''Lees jij mij vanavond dan maar voor.'' Laat zijn fantasie het werk doen, en jij ligt gewoon te luisteren naar zijn stem.', title_pl = 'Moja bajka, moje zasady 📖', body_pl = 'Pomyliłaś słowo podczas czytania bajki, a on od razu cię poprawił? Czyli zna ją na pamięć! Zamknij książkę i powiedz: „To dziś wieczorem ty mi poczytaj”. Niech pracuje jego wyobraźnia, a ty po prostu połóż się i słuchaj jego głosu.', title_pt = 'A minha história, as minhas regras 📖', body_pt = 'Ao ler a história, disse mal uma palavra e ele corrigiu-a logo? Quer dizer que já a sabe de cor! Feche o livro e diga: "Então esta noite és tu que me lês". Deixe o mundo da imaginação dele trabalhar e limite-se a deitar-se e a ouvir a voz dele.', title_sv = 'Min saga, mina regler 📖', body_sv = 'Sa du fel ord när du läste sagan och barnet rättade dig direkt? Då kan hen den utantill! Stäng boken och säg: ”Då får du läsa för mig i kväll.” Låt fantasin arbeta, medan du bara ligger och lyssnar på barnets röst.', title_vi = 'Truyện của con, luật của con 📖', body_vi = 'Đọc truyện mà mẹ đọc sai một từ, bé sửa ngay lập tức? Vậy là bé thuộc lòng rồi! Hãy gấp sách lại: "Vậy tối nay con đọc cho mẹ nghe nhé." Để trí tưởng tượng của bé làm việc, còn mẹ chỉ việc nằm nghe giọng bé.', title_zh = '我的故事，我的规则 📖', body_zh = '讲故事时你说错了一个词，宝宝立刻纠正你？说明已经背下来了！合上书，说：“那今晚你读给我听。”让宝宝的想象力尽情发挥，你只要躺着听宝宝的声音就好。' WHERE id = '8d7ffafe-9007-449d-a1c5-50fafa6a8a92' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El detective de la sopa en acción 🥕', body_es = '¿Ha metido la cuchara en la sopa, ha encontrado una sola cebolla y la ha apartado? ¡Precisión de joyero! Mira ya Recetas saludables, aprende a triturar esas verduras y esconderlas en salsas desde mañana, y gana en secreto.', title_fr = 'Le détective de la soupe en action 🥕', body_fr = 'Il a plongé sa cuillère dans la soupe, trouvé un seul morceau d''oignon et l''a mis de côté ? Une précision d''orfèvre ! Consultez vite les Recettes saines, apprenez comment mixer ces légumes et les cacher dans les sauces dès demain, et gagnez en douce.', title_hi = 'सूप जासूस काम पर 🥕', body_hi = 'चम्मच सूप में डालकर एक-एक प्याज़ का टुकड़ा ढूँढा और किनारे रख दिया? सुनार जैसी बारीकी! फ़ौरन सेहतमंद रेसिपी देखिए, सीखिए कि कल से उन सब्ज़ियों को ब्लेंडर में पीसकर सॉस में कैसे छिपाना है, और चुपके से जीत जाइए।', title_id = 'Detektif sup sedang bertugas 🥕', body_id = 'Ia mencelupkan sendok ke sup, menemukan sepotong bawang, lalu menyisihkannya? Ketelitian tukang perhiasan! Segera lihat Resep Sehat, pelajari cara memblender sayur dan menyembunyikannya dalam saus mulai besok, lalu menangkan diam-diam.', title_ja = 'スープ探偵、出動中 🥕', body_ja = 'スプーンでスープの中から玉ねぎをひとつ見つけて、よけた？職人なみの正確さです！すぐに「ヘルシーレシピ」を見て、明日から野菜をブレンダーにかけてソースに隠す方法を知り、こっそり勝利しましょう。', title_ko = '수프 탐정 출동 🥕', body_ko = '숟가락으로 수프를 뒤져 양파 한 조각을 찾아내 옆으로 빼놓았나요? 보석 세공사 같은 정밀함이네요! 바로 건강한 레시피에서 내일부터 채소를 블렌더에 갈아 소스에 숨기는 법을 배워 몰래 승리하세요.', title_nl = 'Soepdetective aan het werk 🥕', body_nl = 'Viste hij met zijn lepel één stukje ui uit de soep en legde hij het opzij? Dat is de precisie van een juwelier! Kijk meteen in Gezonde recepten hoe je vanaf morgen groenten pureert en in sauzen verstopt, en win stiekem.', title_pl = 'Detektyw zupowy w akcji 🥕', body_pl = 'Zanurzył łyżkę w zupie, znalazł jedną cebulkę i odłożył ją na bok? Precyzja jubilera! Od razu zajrzyj do Zdrowych przepisów, dowiedz się, jak od jutra miksować warzywa i chować je w sosach, i po cichu wygraj.', title_pt = 'Detetive da sopa em ação 🥕', body_pt = 'Mergulhou a colher na sopa, encontrou um único pedaço de cebola e pô-lo de lado? Precisão de ourives! Veja já nas Receitas Saudáveis como, a partir de amanhã, triturar esses legumes e escondê-los nos molhos, e ganhe em segredo.', title_sv = 'Soppdetektiven i tjänst 🥕', body_sv = 'Stack barnet ner skeden i soppan, hittade en enda löktärna och lade den åt sidan? Juvelerarprecision! Titta genast i Hälsosamma recept, lär dig hur du från i morgon mixar grönsakerna och gömmer dem i såser, och vinn i smyg.', title_vi = 'Thám tử súp đang làm nhiệm vụ 🥕', body_vi = 'Bé thả thìa vào súp, tìm ra đúng một miếng hành và gạt sang một bên? Chính xác như thợ kim hoàn! Hãy xem ngay Công thức lành mạnh để học cách xay nhuyễn rau, giấu vào nước sốt từ ngày mai và lặng lẽ giành chiến thắng.', title_zh = '汤里的小侦探上岗啦 🥕', body_zh = '用勺子在汤里翻出一块洋葱，挑到一边？这精准度堪比珠宝匠！马上去看看健康食谱，学学明天怎样把蔬菜打成泥藏进酱汁里，悄悄赢下这一局。' WHERE id = 'ba68f77d-f963-479b-bdc5-453510fe2fd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En silencio, en pareja 🥂', body_es = 'El peque duerme y la casa está recogida. Siéntate en el sofá junto a tu pareja, sin encender siquiera la tele. Solo miraos con esa mirada de «esto también lo hemos conseguido, hemos sobrevivido». Créeme, este es el momento más romántico y auténtico de ser padres.', title_fr = 'En silence, à deux 🥂', body_fr = 'L''enfant dort, la maison est rangée. Asseyez-vous côte à côte sur le canapé avec votre partenaire, sans même allumer la télé. Échangez simplement ce regard qui dit « On y est arrivés, on a survécu ». Croyez-moi, voilà le moment le plus romantique et le plus vrai de la vie de parents.', title_hi = 'जोड़ी के रूप में खामोशी में 🥂', body_hi = 'बच्चा सो गया, घर समेट लिया। अपने साथी के साथ सोफ़े पर पास-पास बैठिए, टीवी भी मत चलाइए। बस एक-दूसरे को ‘यह भी कर लिया, हम बच गए’ वाली नज़र से देखिए। यकीन मानिए, पेरेंटिंग का सबसे रोमांटिक और सच्चा पल यही है।', title_id = 'Hening berdua sebagai pasangan 🥂', body_id = 'Anak sudah tidur, rumah sudah rapi. Duduklah berdampingan dengan pasangan di sofa, bahkan tanpa menyalakan TV. Cukup saling bertukar tatapan ''kita berhasil melewati ini juga''. Percayalah, inilah momen paling romantis dan nyata dalam menjadi orang tua.', title_ja = 'ふたりで静かな時間を 🥂', body_ja = '子どもは寝て、家も片づいた。パートナーとソファに並んで座り、テレビもつけないで。ただ「今日も乗りきったね」という視線を交わしましょう。それこそが、子育てのいちばんロマンチックで本当の瞬間です。', title_ko = '부부가 함께하는 고요 🥂', body_ko = '아이는 잠들고 집도 정리됐어요. 배우자와 소파에 나란히 앉아 TV도 켜지 마세요. 그저 ''오늘도 해냈다, 살아남았다''는 눈빛을 서로 나누세요. 이게 바로 육아에서 가장 로맨틱하고 진짜인 순간이에요.', title_nl = 'Samen in stilte 🥂', body_nl = 'Je kind slaapt, het huis is opgeruimd. Ga met je partner naast elkaar op de bank zitten, zet zelfs de tv niet aan. Geef elkaar gewoon die blik van ''we hebben het weer gered, we hebben het overleefd''. Geloof ons, dit is het meest romantische en echte moment van het ouderschap.', title_pl = 'We dwoje w ciszy 🥂', body_pl = 'Dziecko śpi, dom posprzątany. Usiądź z partnerem obok siebie na kanapie, nawet nie włączajcie telewizora. Po prostu wymieńcie spojrzenia mówiące „i to nam się udało, przetrwaliśmy”. Uwierz, to właśnie najbardziej romantyczna i prawdziwa chwila rodzicielstwa.', title_pt = 'Em silêncio, como um casal 🥂', body_pt = 'A criança adormeceu, a casa está arrumada. Sente-se no sofá ao lado do seu companheiro, nem sequer ligue a televisão. Troquem apenas aquele olhar de "também conseguimos isto, sobrevivemos". Acredite, é este o momento mais romântico e verdadeiro da parentalidade.', title_sv = 'Tystnad som par 🥂', body_sv = 'Barnet sover, huset är städat. Sätt dig bredvid din partner i soffan och slå inte ens på tv:n. Ge bara varandra blicken som säger ”vi klarade det här också, vi överlevde”. Tro mig, det är föräldraskapets mest romantiska och äkta stund.', title_vi = 'Hai vợ chồng trong yên lặng 🥂', body_vi = 'Bé đã ngủ, nhà đã dọn. Hãy ngồi cạnh chồng trên sofa, thậm chí đừng bật TV. Chỉ cần trao nhau ánh mắt "Chúng ta lại làm được rồi, lại sống sót rồi". Tin đi, đó chính là khoảnh khắc lãng mạn và chân thật nhất của việc làm cha mẹ.', title_zh = '两个人的安静时光 🥂', body_zh = '宝宝睡了，家也收拾好了。和另一半并肩坐在沙发上，连电视都别开。只要彼此对视一眼：“这一关我们也挺过来了。”相信我，这才是为人父母最浪漫、最真实的时刻。' WHERE id = '3f320efd-46d8-4e41-85e8-a584506068f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ese temido «¡Quiero!» del súper 🛒', body_es = '¿Grita por un chocolate justo delante de la caja? No cedas aunque te miren los de atrás. Abre la Lista de la compra y dile: «Aquí no está, la caja no lo va a leer». Una autoridad externa siempre les resulta más convincente.', title_fr = 'Le terrible « Je veux ! » au supermarché 🛒', body_fr = 'Il hurle pour un chocolat juste devant la caisse ? Malgré les regards derrière vous, ne cédez pas. Ouvrez la Liste de courses et dites : « Ce n''est pas dedans, la caisse ne le lira pas. » Une autorité extérieure leur paraît toujours plus convaincante.', title_hi = 'सुपरमार्केट में वह डरावना ‘मुझे चाहिए!’ 🛒', body_hi = 'ठीक काउंटर के सामने चॉकलेट के लिए चिल्ला रहा है? पीछे वालों की नज़रों के बावजूद हार मत मानिए। शॉपिंग लिस्ट खोलिए और कहिए, ‘यह इसमें नहीं है, काउंटर इसे स्कैन नहीं करेगा।’ बाहर की कोई ‘अथॉरिटी’ बच्चों को हमेशा ज़्यादा भरोसेमंद लगती है।', title_id = '''Aku mau!'' yang menakutkan di supermarket 🛒', body_id = 'Ia menjerit minta cokelat tepat di depan kasir? Jangan menyerah meski orang-orang di belakang memandangi. Buka Daftar Belanja dan katakan ''Ini tidak ada di sini, kasirnya tidak akan bisa membacanya''. Otoritas dari luar selalu terasa lebih meyakinkan bagi mereka.', title_ja = 'スーパーで、あのこわい「ほしい！」 🛒', body_ja = 'レジの目の前でチョコがほしいと叫ぶ？後ろの人の視線があっても負けないで。「買い物リスト」を開いて「ここには入っていないから、レジは読みとってくれないよ」と言いましょう。外からのルールのほうが、子どもにはいつも説得力があります。', title_ko = '마트에서 듣는 무서운 ''사 줘!'' 🛒', body_ko = '계산대 바로 앞에서 초콜릿 사 달라고 소리치나요? 뒷사람들 시선에도 굴복하지 마세요. 쇼핑 목록을 열고 ''여기 없지? 계산대가 이건 안 읽어 줘''라고 말하세요. 바깥의 권위는 아이에게 늘 더 설득력 있게 들려요.', title_nl = 'Dat gevreesde ''Ik wil!'' in de supermarkt 🛒', body_nl = 'Schreeuwt hij vlak voor de kassa om chocola? Geef niet toe, ook al kijken de mensen achter je. Open het Boodschappenlijstje en zeg: ''Het staat er niet op, de kassa scant het niet.'' Een autoriteit van buitenaf is voor hen altijd overtuigender.', title_pl = 'To straszne „Chcę!” w sklepie 🛒', body_pl = 'Krzyczy o czekoladę tuż przed kasą? Mimo spojrzeń ludzi w kolejce nie poddawaj się. Otwórz Listę zakupów i powiedz: „Tego tu nie ma, kasa tego nie zeskanuje”. Zewnętrzny autorytet zawsze brzmi dla dzieci bardziej przekonująco.', title_pt = 'O temível "Eu quero!" no supermercado 🛒', body_pt = 'Grita por um chocolate mesmo em frente à caixa? Apesar dos olhares de quem está atrás, não ceda. Abra a Lista de Compras e diga: "Não está aqui, a caixa não o vai ler". Uma autoridade externa parece-lhes sempre mais convincente.', title_sv = 'Det fruktade ”Jag vill ha!” i affären 🛒', body_sv = 'Skriker barnet efter choklad precis framför kassan? Ge inte efter, trots blickarna från folket i kön. Öppna Inköpslistan och säg: ”Den står inte här, kassan kommer inte att läsa den.” En yttre auktoritet känns alltid mer övertygande för barn.', title_vi = 'Câu "Con muốn!" đáng sợ ở siêu thị 🛒', body_vi = 'Bé gào đòi sô-cô-la ngay trước quầy thu ngân? Dù người phía sau nhìn chằm chằm, đừng nhượng bộ. Mở Danh sách mua sắm và nói: "Không có trong này, quầy thu ngân sẽ không quét món này đâu." Một "uy quyền bên ngoài" luôn khiến bé tin hơn.', title_zh = '超市里那句可怕的“我要！” 🛒', body_zh = '就在收银台前为了巧克力尖叫？不管后面的人怎么看，都别让步。打开购物清单，说：“这里面没有，收银台扫不了它。”来自外部的“权威”对孩子总是更有说服力。' WHERE id = '5c1ffe1c-132b-41ee-89f2-40908e4efd15' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué me has hablado? 😤', body_es = '¿Se ha enfadado solo porque le has dicho «Buenos días»? La etapa de los enfados sin motivo sigue a todo gas. No vayas a por ello, sírvete un té y tómatelo. Ya verás como en 2 minutos viene a abrazarte las rodillas. ¡Tiene las emociones hechas un lío!', title_fr = 'Pourquoi tu m''as parlé ? 😤', body_fr = 'Il s''est fâché simplement parce que vous lui avez dit « Bonjour » ? La période des bouderies sans raison bat son plein. Ne vous en mêlez pas, servez-vous un thé et buvez-le. Soyez sûre que dans 2 minutes, il viendra se blottir contre vos genoux. Ses émotions sont tellement embrouillées !', title_hi = 'तुमने मुझसे बात क्यों की? 😤', body_hi = 'आपने बस ‘गुड मॉर्निंग’ कहा और वह नाराज़ हो गया? बिना वजह रूठने का दौर पूरे ज़ोर पर है। उसके पीछे मत पड़िए, अपनी चाय डालिए और पीजिए। यकीन रखिए, 2 मिनट बाद आकर आपके घुटनों से लिपट जाएगा। उसकी भावनाएँ बहुत उलझी हुई हैं!', title_id = 'Kenapa ngomong sama aku? 😤', body_id = 'Ia marah hanya karena Anda bilang ''Selamat pagi''? Masa ngambek tanpa alasan sedang berjalan dengan kecepatan penuh. Jangan dilawan, tuang teh Anda dan minumlah. Yakinlah, 2 menit kemudian ia akan datang memeluk lutut Anda. Emosinya memang sedang campur aduk!', title_ja = 'なんで話しかけたの？ 😤', body_ja = '「おはよう」と言っただけで怒った？理由のないすね期が全開です。向き合わず、お茶を入れて飲みましょう。2分もすれば、ひざにぎゅっと抱きついてきますよ。気持ちがそれだけごちゃごちゃなんです！', title_ko = '왜 나한테 말 걸었어? 😤', body_ko = '그냥 ''좋은 아침''이라고 했을 뿐인데 화를 내나요? 이유 없이 토라지는 시기가 한창이에요. 맞서지 말고 차를 따라 마시세요. 2분 뒤면 다가와 무릎을 껴안을 거예요. 감정이 그만큼 뒤죽박죽이거든요!', title_nl = 'Waarom praat je tegen mij? 😤', body_nl = 'Werd hij boos alleen omdat je ''Goedemorgen'' zei? De periode van mokken zonder reden is in volle gang. Ga er niet op in, schenk je thee in en drink. Reken maar dat hij over 2 minuten je knie komt omhelzen. Zijn gevoelens zijn zo door elkaar!', title_pl = 'Czemu się do mnie odezwałaś? 😤', body_pl = 'Złości się, bo po prostu powiedziałaś „Dzień dobry”? Etap obrażania się bez powodu trwa w najlepsze. Nie naciskaj, nalej sobie herbaty i ją wypij. Zobaczysz, za 2 minuty przyjdzie i przytuli się do twoich kolan. Ma w sobie tyle pomieszanych emocji!', title_pt = 'Porque é que falaste comigo? 😤', body_pt = 'Zangou-se só porque lhe disse "bom dia"? A fase dos amuos sem razão continua a todo o gás. Não insista, sirva-se de chá e beba-o. Pode ter a certeza de que daqui a 2 minutos vem abraçar-lhe os joelhos. As emoções dele estão tão baralhadas!', title_sv = 'Varför pratade du med mig? 😤', body_sv = 'Blev barnet arg bara för att du sa ”God morgon”? Perioden av sura miner utan anledning går för fullt. Gå inte emot, häll upp ditt te och drick det. Du kan vara säker på att barnet kommer och kramar ditt knä om 2 minuter. Känslorna är så förvirrade!', title_vi = 'Sao mẹ lại nói chuyện với con? 😤', body_vi = 'Bé nổi giận chỉ vì mẹ nói "Chào buổi sáng"? Thời kỳ dỗi vô cớ đang diễn ra hết tốc lực. Đừng đôi co, cứ rót trà mà uống. Yên tâm, 2 phút sau bé sẽ chạy đến ôm chân mẹ. Cảm xúc của bé đang rối tung lên mà!', title_zh = '你干嘛跟我说话？😤', body_zh = '只因为你说了一句“早上好”就生气了？莫名其妙闹别扭的阶段正火力全开。别硬碰硬，倒杯茶喝。放心，2分钟后宝宝就会跑来抱住你的腿。小家伙的情绪真是太复杂了！' WHERE id = '68fe0739-89b9-4724-85e1-174aecc17d9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un peque a cuatro patas 🐾', body_es = '¿Esta mañana ha salido de la cama gateando como un perrito y no como un niño? No le leas las reglas ni te enfades. Dile «¡Bravo, mi perrito listo!» y dale el desayuno. Unirte a sus juegos de rol ahorra muchísima más energía que ponerte cabezota.', title_fr = 'L''enfant à quatre pattes 🐾', body_fr = 'Ce matin, il est sorti du lit à quatre pattes, comme un chien plutôt que comme un enfant ? Ne faites pas la leçon et ne vous énervez pas. Dites « Bravo, mon toutou intelligent ! » et servez-lui son petit-déjeuner. Entrer dans ses jeux de rôle économise bien plus d''énergie que s''entêter.', title_hi = 'चार पैरों वाला बच्चा 🐾', body_hi = 'आज सुबह वह बिस्तर से बच्चे की तरह नहीं, कुत्ते की तरह रेंगते हुए निकला? नियम समझाकर परेशान मत होइए। ‘शाबाश, मेरे समझदार डॉगी’ कहकर नाश्ता दे दीजिए। रोल-प्ले में शामिल होना ज़िद करने से कहीं ज़्यादा ऊर्जा बचाता है।', title_id = 'Anak berkaki empat 🐾', body_id = 'Pagi ini ia keluar dari tempat tidur bukan seperti anak, tapi merangkak seperti anjing? Jangan membacakan aturan dan jadi kesal. Katakan ''Pintar sekali anjing kecil Mama'' dan berikan sarapannya. Ikut bermain peran jauh lebih menghemat energi daripada beradu keras kepala.', title_ja = '四つ足の子ども 🐾', body_ja = '今朝はベッドから子どもではなく、わんちゃんとしてハイハイで出てきた？ルールを説いて怒らないで。「えらいね、かしこいワンちゃん」と言って朝ごはんをあげましょう。ごっこ遊びに乗るほうが、意地の張り合いよりずっとエネルギーの節約になります。', title_ko = '네 발로 다니는 아이 🐾', body_ko = '오늘 아침 아이가 사람이 아니라 강아지처럼 기어서 침대에서 나왔나요? 훈계하며 짜증 내지 마세요. ''우리 똑똑한 멍멍이 잘했어''라며 아침을 주세요. 역할 놀이에 함께하는 게 고집 싸움보다 훨씬 에너지를 아껴 줘요.', title_nl = 'Het kind op vier pootjes 🐾', body_nl = 'Kroop hij vanochtend niet als kind, maar als hondje uit bed? Ga geen regels opsommen en word niet boos. Zeg ''Goed zo, mijn slimme hondje'' en geef hem zijn ontbijt. Meedoen met rollenspel kost veel minder energie dan koppig volhouden.', title_pl = 'Dziecko na czworakach 🐾', body_pl = 'Dziś rano wyszedł z łóżka nie jak dziecko, ale na czworakach jak piesek? Nie wygłaszaj zasad i się nie denerwuj. Powiedz: „Brawo, mój mądry piesku” i podaj śniadanie. Włączenie się w zabawę w odgrywanie ról oszczędza dużo więcej energii niż upieranie się.', title_pt = 'A criança de quatro patas 🐾', body_pt = 'Esta manhã saiu da cama não como uma criança, mas a gatinhar como um cão? Não se irrite a ditar regras. Diga "Muito bem, meu cãozinho esperto" e dê-lhe o pequeno-almoço. Entrar nos jogos de faz de conta poupa muito mais energia do que teimar.', title_sv = 'Ett barn på alla fyra 🐾', body_sv = 'Kröp barnet ur sängen i morse som en hund i stället för som ett barn? Läs inte upp regler och bli inte irriterad. Säg ”Duktig, min smarta vovve!” och servera frukosten. Att gå med i rollekar sparar mångdubbelt mer energi än att tjafsa.', title_vi = 'Em bé bốn chân 🐾', body_vi = 'Sáng nay bé không bước ra khỏi giường như một đứa trẻ mà bò ra như một chú cún? Đừng bực mình giảng giải quy tắc. Hãy nói "Giỏi lắm, cún con thông minh của mẹ" rồi đưa bữa sáng. Tham gia trò nhập vai tiết kiệm sức hơn gấp nhiều lần so với giằng co.', title_zh = '四条腿走路的孩子 🐾', body_zh = '今早宝宝不是像小孩一样，而是像小狗一样从床上爬出来的？别讲规矩、别生气。说一句“真棒，我聪明的小狗狗”，然后把早餐递过去。加入角色扮演，比较劲省力得多。' WHERE id = '5a73dbf6-a948-449b-bd9f-bd6acec175f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un grito repentino a medianoche 😭', body_es = '¿Se ha despertado de noche llorando con los ojos cerrados y no te oye? Pasa por el Análisis del llanto: son terrores nocturnos. Intenta no despertarlo, solo quédate a su lado, cógele la mano y acarícialo. Se calmará solo y volverá a dormirse profundamente.', title_fr = 'Un cri soudain en pleine nuit 😭', body_fr = 'Il s''est réveillé la nuit en pleurant, les yeux fermés, et ne vous entend pas ? Vérifiez avec l''Analyse des pleurs : c''est une terreur nocturne. N''essayez pas de le réveiller, restez simplement près de lui, tenez-lui la main et caressez-le. Il se calmera de lui-même et retombera dans un sommeil profond.', title_hi = 'आधी रात को अचानक चीख 😭', body_hi = 'रात को आँखें बंद किए रोते हुए जागा और आपकी बात नहीं सुन रहा? क्राइंग एनालिसिस बताता है: यह नाइट टेरर है। जगाने की कोशिश मत कीजिए, बस पास रहिए, हाथ थामकर सहलाइए। वह अपने आप शांत होकर फिर गहरी नींद में चला जाएगा।', title_id = 'Jeritan tiba-tiba di tengah malam 😭', body_id = 'Malam-malam ia terbangun menangis dengan mata terpejam dan tidak mendengar Anda? Periksa dengan Analisis Tangisan; ini teror tidur (night terror). Jangan coba membangunkannya, cukup berada di sampingnya, pegang dan usap tangannya. Ia akan tenang sendiri dan kembali tidur nyenyak.', title_ja = '真夜中の突然の叫び 😭', body_ja = '夜中に目を閉じたまま泣いて起き、あなたの声が聞こえていない？「泣き声分析」で確かめてみましょう。これは夜驚症です。起こそうとせず、ただそばにいて手をにぎり、なでてあげて。自然に落ち着いて、また深い眠りに戻ります。', title_ko = '한밤중 갑작스러운 비명 😭', body_ko = '밤에 눈을 감은 채 울며 깨어나 엄마 말을 듣지 못하나요? 울음 분석은 넘기세요, 이건 야경증이에요. 깨우려 하지 말고 곁에서 손을 잡고 쓰다듬어 주세요. 스스로 진정하고 다시 깊이 잠들 거예요.', title_nl = 'Plots gegil midden in de nacht 😭', body_nl = 'Werd hij ''s nachts huilend wakker met zijn ogen dicht en hoort hij je niet? Laat het door Huilanalyse gaan; dit is nachtangst (pavor nocturnus). Probeer hem niet wakker te maken, blijf gewoon bij hem, pak zijn hand en aai hem. Hij kalmeert vanzelf en valt weer diep in slaap.', title_pl = 'Nagły krzyk w środku nocy 😭', body_pl = 'W nocy obudził się z płaczem, z zamkniętymi oczami, i cię nie słyszy? Sprawdź to w Analizie płaczu; to lęk nocny. Nie próbuj go budzić, po prostu bądź obok, trzymaj go za rękę i głaszcz. Sam się uspokoi i znów zapadnie w głęboki sen.', title_pt = 'Gritos repentinos a meio da noite 😭', body_pt = 'Acordou de noite a chorar, de olhos fechados, e não a ouve? Confirme com a Análise do Choro: é terror noturno. Tente não o acordar, fique só ao lado dele, pegue-lhe na mão e faça-lhe festas. Vai acalmar-se sozinho e voltar a adormecer profundamente.', title_sv = 'Ett plötsligt skrik mitt i natten 😭', body_sv = 'Vaknade barnet gråtande på natten med slutna ögon och hör dig inte? Kontrollera med Gråtanalys; det är nattskräck. Försök inte väcka barnet, stå bara bredvid, håll handen och stryk lätt. Barnet lugnar sig av sig självt och somnar djupt igen.', title_vi = 'Tiếng hét bất ngờ lúc nửa đêm 😭', body_vi = 'Ban đêm bé khóc thét, mắt vẫn nhắm và không nghe thấy mẹ? Hãy kiểm tra bằng Phân tích tiếng khóc; đây là hoảng sợ khi ngủ. Cố đừng đánh thức bé, chỉ cần ở bên, nắm tay và vuốt ve. Bé sẽ tự bình tĩnh lại và chìm vào giấc ngủ sâu.', title_zh = '半夜突然尖叫 😭', body_zh = '半夜闭着眼睛哭醒，好像听不见你说话？用哭声分析看看：这是夜惊。尽量别叫醒宝宝，只要陪在身边，握着小手轻轻抚摸。宝宝会自己平静下来，重新进入深睡。' WHERE id = 'b5299007-402e-4c46-9a86-5fb45df938df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi cuerpo no es mío 🔋', body_es = '¿Se te pega a las piernas todo el día pidiendo brazos? Estás agotada físicamente. Estás saturada de contacto (touched out). Déjalo en su habitación con sus juguetes y escápate 5 minutos al baño, solo para sentir la soledad. Es tu derecho.', title_fr = 'Mon corps ne m''appartient plus 🔋', body_fr = 'Il s''accroche à vos jambes toute la journée et veut des câlins ? Vous êtes physiquement à bout. Vous vivez la saturation du toucher (touched out). Laissez-le dans la pièce avec ses jouets et filez 5 minutes dans la salle de bain, juste pour sentir la solitude. C''est votre droit.', title_hi = 'मेरा शरीर मेरा नहीं रहा 🔋', body_hi = 'दिनभर पैरों से लिपटा रहता है, गोद माँगता है? आप शारीरिक रूप से थक चुकी हैं। यह ‘टच्ड आउट’ वाली थकान है। उसे खिलौनों के साथ कमरे में छोड़कर 5 मिनट बाथरूम चली जाइए और बस अकेलेपन को महसूस कीजिए। यह आपका हक है।', title_id = 'Tubuhku bukan milikku 🔋', body_id = 'Seharian ia menempel di kaki Anda dan minta digendong? Secara fisik Anda sudah habis. Anda sedang mengalami kelelahan disentuh (touched out). Tinggalkan ia di kamar dengan mainannya dan larilah ke kamar mandi selama 5 menit, rasakan saja kesendirian. Itu hak Anda.', title_ja = 'わたしの体はわたしのものじゃない 🔋', body_ja = '一日じゅう足にしがみついて抱っこをせがむ？体力が尽きていますね。「タッチアウト（触れられ疲れ）」を感じているんです。おもちゃと一緒に部屋で遊ばせて、5分だけお風呂場に逃げこんで、ひとりの時間を感じて。それはあなたの権利です。', title_ko = '내 몸이 내 것이 아닌 느낌 🔋', body_ko = '하루 종일 다리에 매달려 안아 달라고 하나요? 몸이 완전히 지쳤어요. 터치 피로(touched out)를 겪고 있는 거예요. 아이를 장난감과 함께 방에 두고 5분만 욕실로 피신해 혼자임을 느껴 보세요. 엄마에게도 그럴 권리가 있어요.', title_nl = 'Mijn lichaam is niet van mij 🔋', body_nl = 'Hangt hij de hele dag aan je been en wil hij steeds op schoot? Je bent lichamelijk op. Je hebt last van aanrakingsmoeheid (touched out). Laat hem met zijn speelgoed in de kamer en vlucht 5 minuten naar de badkamer, gewoon om alleen te zijn. Daar heb je recht op.', title_pl = 'Moje ciało nie należy do mnie 🔋', body_pl = 'Cały dzień wisi ci na nodze i chce na ręce? Jesteś fizycznie wyczerpana. Przeżywasz przebodźcowanie dotykiem (touched out). Zostaw go z zabawkami w pokoju, uciekaj na 5 minut do łazienki i po prostu poczuj samotność. Masz do tego prawo.', title_pt = 'O meu corpo não me pertence 🔋', body_pt = 'Passa o dia agarrado às suas pernas a pedir colo? Está fisicamente esgotada. É o cansaço de toque ("touched out"). Deixe-o no quarto com os brinquedos e fuja 5 minutos para a casa de banho, só para sentir a solidão. É um direito seu.', title_sv = 'Min kropp tillhör inte mig 🔋', body_sv = 'Hänger barnet i benen hela dagen och vill bli buren? Du är fysiskt slutkörd. Du upplever touched out, beröringsutmattning. Lämna barnet med leksakerna i ett säkert rum och fly till badrummet i 5 minuter, känn bara ensamheten. Det har du rätt till.', title_vi = 'Cơ thể này không còn là của mình 🔋', body_vi = 'Cả ngày bé bám chân, đòi bế? Mẹ đã kiệt sức về thể chất. Mẹ đang trải qua cảm giác "quá tải vì bị chạm" (touched out). Hãy để bé chơi đồ chơi trong phòng và trốn vào phòng tắm 5 phút, chỉ để cảm nhận sự một mình. Đó là quyền của mẹ.', title_zh = '我的身体不属于我了 🔋', body_zh = '一整天抱着你的腿，要你抱？你的身体已经透支了。这是“触碰疲劳”（touched out）。让宝宝在房间里玩玩具，你躲进浴室5分钟，好好感受一下独处。这是你应得的。' WHERE id = 'cd19d080-ed21-40f3-b449-164e996aed41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La puerta la abro yo! 🚪', body_es = '¿Al salir de casa ha llorado para que volvieras a cerrar la puerta porque la abriste tú? A esta edad, la sensación de control es la mayor necesidad psicológica. Pierde 1 minuto, pero evita una crisis de 30 minutos en la calle y alimenta su autoestima.', title_fr = 'C''est moi qui ouvre la porte ! 🚪', body_fr = 'En sortant, il a pleuré parce que c''est vous qui avez ouvert la porte, et vous l''a fait refermer ? À cet âge, le sentiment de contrôle est le plus grand besoin psychologique. Laissez-le vous faire perdre 1 minute : vous éviterez une crise de 30 minutes dans la rue et nourrirez sa confiance en soi.', title_hi = 'दरवाज़ा मैं खोलूँगा! 🚪', body_hi = 'घर से निकलते समय दरवाज़ा आपने खोला, इसलिए रो-रोकर फिर से बंद करवाया? इस उम्र में नियंत्रण का एहसास सबसे बड़ी मानसिक ज़रूरत है। इसमें आपका 1 मिनट जाएगा, पर बाहर होने वाले 30 मिनट के झगड़े से बचेंगी और उसका आत्मविश्वास भी बढ़ेगा।', title_id = 'Aku yang buka pintunya! 🚪', body_id = 'Saat keluar rumah ia menangis dan menyuruh pintunya ditutup lagi karena Anda yang membukanya? Rasa memegang kendali adalah kebutuhan psikologis terbesar di usia ini. Biarlah Anda kehilangan 1 menit, tapi cegah krisis 30 menit di jalan dan pupuk rasa percaya dirinya.', title_ja = 'ドアはぼくが開ける！ 🚪', body_ja = '出かけるときにあなたがドアを開けたら、泣いて閉めなおさせた？この年齢では、自分でコントロールしたい気持ちがいちばん大きな心の欲求です。1分かかってもいいから、外での30分のかんしゃくを防いで、自信を育ててあげましょう。', title_ko = '문은 내가 열 거야! 🚪', body_ko = '외출할 때 엄마가 문을 열었다고 울면서 다시 닫게 했나요? 이 나이에 통제감은 가장 큰 심리적 욕구예요. 1분 손해 보더라도, 밖에서 30분짜리 떼를 막고 아이의 자신감을 키워 주세요.', title_nl = 'Ik doe de deur open! 🚪', body_nl = 'Liet hij je huilend de deur weer dichtdoen omdat jij hem opendeed toen jullie weggingen? Een gevoel van controle is op deze leeftijd de grootste psychologische behoefte. Laat hem je die ene minuut kosten, voorkom een crisis van 30 minuten op straat en voed zijn zelfvertrouwen.', title_pl = 'Ja otworzę drzwi! 🚪', body_pl = 'Przy wyjściu z domu płakał, bo to ty otworzyłaś drzwi, i kazał je zamknąć z powrotem? Poczucie kontroli to w tym wieku największa potrzeba psychologiczna. Stracisz 1 minutę, ale zapobiegniesz 30-minutowemu kryzysowi na ulicy i wzmocnisz jego pewność siebie.', title_pt = 'Sou eu que abro a porta! 🚪', body_pt = 'Ao sair de casa, chorou e obrigou-a a fechar a porta outra vez porque foi a mãe a abri-la? Nesta idade, a sensação de controlo é a maior necessidade psicológica. Deixe-o fazê-la perder 1 minuto, evite uma crise de 30 minutos na rua e alimente a autoestima dele.', title_sv = 'Jag öppnar dörren! 🚪', body_sv = 'Grät barnet och fick dig att stänga dörren igen för att det var du som öppnade den när ni skulle gå? Känslan av kontroll är det största psykologiska behovet i den här åldern. Låt det kosta dig 1 minut, men förebygg en 30 minuters kris på gatan och stärk barnets självförtroende.', title_vi = 'Con sẽ mở cửa! 🚪', body_vi = 'Lúc ra khỏi nhà, bé khóc bắt đóng cửa lại chỉ vì mẹ đã mở? Cảm giác kiểm soát là nhu cầu tâm lý lớn nhất ở tuổi này. Hãy chịu mất 1 phút, để tránh 30 phút ăn vạ ngoài đường và nuôi dưỡng sự tự tin của bé.', title_zh = '门要我来开！🚪', body_zh = '出门时因为是你开的门，宝宝就哭着让你关上重来？这个年龄，掌控感是最大的心理需求。让宝宝花掉你1分钟，却能避免街上30分钟的崩溃，还能滋养宝宝的自信。' WHERE id = '3c2e2a41-c838-4dd0-b137-24862355a226' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inundación en la bañera 🌊', body_es = '¿El baño es una excusa y en realidad ha montado un océano en la bañera para jugar con las olas? Deja que juegue. El ruido del agua y las salpicaduras se llevarán toda esa energía cabezota que no se acaba. Por la noche se meterá en la cama sin oponer resistencia.', title_fr = 'Inondation dans la baignoire 🌊', body_fr = 'Le bain n''est qu''un prétexte : en réalité, il crée un océan et joue avec les vagues ? Laissez-le jouer. Le bruit de l''eau et les éclaboussures emporteront toute cette énergie têtue et inépuisable. Le soir, il ira se coucher sans aucune résistance.', title_hi = 'बाथटब में पानी की बाढ़ 🌊', body_hi = 'नहाना तो बहाना है, असल में टब में समंदर बनाकर लहरों से खेल रहा है? खेलने दीजिए। पानी का शोर और छींटे उसके अंदर की वह खत्म न होने वाली ज़िद्दी ऊर्जा बहा ले जाएँगे। शाम को वह बिना किसी विरोध के बिस्तर पर लेट जाएगा।', title_id = 'Banjir di bak mandi 🌊', body_id = 'Mandi hanya alasan, sebenarnya ia menciptakan lautan di bak dan bermain ombak? Biarkan saja. Suara dan cipratan air akan membasuh energi keras kepala yang tak ada habisnya itu. Malam nanti ia akan berbaring di tempat tidur tanpa perlawanan.', title_ja = 'お風呂で大洪水 🌊', body_ja = 'お風呂は口実で、本当は浴槽に海をつくって波遊び？遊ばせてあげましょう。水の音としぶきが、終わりのないがんこなエネルギーを洗い流してくれます。夜はまったく抵抗せずにベッドに入りますよ。', title_ko = '욕조 속 물난리 🌊', body_ko = '목욕은 핑계고 사실은 욕조에 바다를 만들어 파도 놀이를 하나요? 놀게 두세요. 물소리와 물장구가 속에 쌓인 끝없는 고집 에너지를 씻어 줄 거예요. 저녁엔 아무 저항 없이 침대에 누울 거예요.', title_nl = 'Overstroming in bad 🌊', body_nl = 'Is in bad gaan maar een excuus en maakt hij eigenlijk een oceaan om met de golven te spelen? Laat hem lekker spelen. Het geluid en gespetter van het water spoelt al die eindeloze koppige energie weg. ''s Avonds gaat hij zonder enig verzet in bed liggen.', title_pl = 'Powódź w wannie 🌊', body_pl = 'Kąpiel to tylko pretekst, a w wannie tak naprawdę tworzy ocean i bawi się falami? Niech się bawi. Szum i pluskanie wody zmyją z niego tę niekończącą się upartą energię. Wieczorem położy się do łóżka bez żadnego oporu.', title_pt = 'Inundação na banheira 🌊', body_pt = 'O banho é só uma desculpa e, na verdade, ele cria um oceano na banheira e brinca com as ondas? Deixe-o brincar. O barulho e os salpicos da água vão levar consigo toda aquela energia teimosa e sem fim. À noite vai deitar-se sem resistência nenhuma.', title_sv = 'Översvämning i badkaret 🌊', body_sv = 'Är badet bara en förevändning, och barnet har egentligen skapat ett hav i badkaret och leker med vågorna? Låt hen leka. Vattnets ljud och plask sköljer bort den outtröttliga, envisa energin. På kvällen lägger sig barnet utan minsta motstånd.', title_vi = 'Lũ lụt trong bồn tắm 🌊', body_vi = 'Tắm chỉ là cái cớ, thật ra bé đang tạo cả đại dương trong bồn và chơi với sóng? Cứ để bé chơi. Tiếng nước và những cú té nước sẽ cuốn trôi hết năng lượng bướng bỉnh không ngừng bên trong bé. Tối đến, bé sẽ lên giường mà không phản đối chút nào.', title_zh = '浴缸里发大水 🌊', body_zh = '洗澡只是借口，其实是在浴缸里造了一片海洋，和浪花玩耍？就让宝宝玩吧。哗哗的水声和溅起的水花，会把宝宝身体里那股停不下来的倔强能量冲走。晚上就会毫无抵抗地躺上床。' WHERE id = '93ebf06c-8a17-42ec-bbd4-671ae644ffaa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La IA responde a preguntas raras 🤖', body_es = '¿Te has quedado de piedra ante la pregunta «Mamá, ¿adónde va mi sombra por la noche?»? No te inventes nada. Abre Anacan AI, consigue la respuesta científica más tierna y de cuento para 3,5 años y léesela. Siéntete una gran filósofa y una mamá que lo sabe todo.', title_fr = 'La réponse de l''IA aux questions étranges 🤖', body_fr = 'Vous êtes restée figée devant la question « Maman, où va mon ombre la nuit ? » ? N''inventez rien. Ouvrez Anacan AI, obtenez la réponse scientifique la plus douce et la plus féerique pour un enfant de 3 ans et demi, et lisez-la-lui. Sentez-vous comme une grande philosophe, une maman qui sait tout.', title_hi = 'अजीब सवालों का AI जवाब 🤖', body_hi = '‘माँ, मेरी परछाईं रात को कहाँ जाती है?’ सुनकर जम गईं? कुछ मत गढ़िए। Anacan AI खोलिए, 3.5 साल के बच्चे के लिए सबसे परी-कथा जैसा, प्यारा वैज्ञानिक जवाब लीजिए और उसे पढ़कर सुनाइए। खुद को एक बड़ी दार्शनिक और सब कुछ जानने वाली माँ महसूस कीजिए।', title_id = 'Jawaban AI untuk pertanyaan aneh 🤖', body_id = 'Anda terpaku mendengar pertanyaan ''Ma, bayanganku pergi ke mana kalau malam?'' Jangan mengarang apa pun. Buka Anacan AI, dapatkan jawaban ilmiah yang paling manis dan seperti dongeng untuk usia 3,5 tahun, lalu bacakan untuknya. Rasakan diri Anda sebagai filsuf hebat dan ibu yang tahu segalanya.', title_ja = 'ふしぎな質問にはAIが答える 🤖', body_ja = '「ママ、ぼくの影は夜どこへ行くの？」という質問に固まってしまった？何もつくり話をしなくて大丈夫。Anacan AIを開いて、3歳半向けのいちばんお話らしい、かわいい科学的な答えを聞いて読んであげましょう。偉大な哲学者で何でも知っているママの気分を味わって。', title_ko = '엉뚱한 질문엔 AI의 답 🤖', body_ko = '''엄마, 내 그림자는 밤에 어디 가?''라는 질문에 말문이 막혔나요? 아무거나 지어내지 마세요. Anacan AI를 열어 3.5세에게 딱 맞는 동화 같고 귀여운 과학적 답을 받아 읽어 주세요. 위대한 철학자이자 모든 걸 아는 엄마가 된 기분일 거예요.', title_nl = 'AI-antwoord op rare vragen 🤖', body_nl = 'Stond je met je mond vol tanden bij de vraag ''Mama, waar gaat mijn schaduw ''s nachts heen?'' Verzin niets. Open Anacan AI, vraag het meest sprookjesachtige, lieve wetenschappelijke antwoord voor een 3,5-jarige en lees het hem voor. Voel je een grote filosoof en een mama die alles weet.', title_pl = 'Odpowiedź AI na dziwne pytania 🤖', body_pl = 'Zamarłaś przy pytaniu „Mamo, gdzie mój cień chodzi w nocy?”. Niczego nie wymyślaj. Otwórz Anacan AI, uzyskaj najbardziej bajkową i uroczą naukową odpowiedź dla 3,5-latka i mu ją przeczytaj. Poczuj się jak wielka filozofka i mama, która wie wszystko.', title_pt = 'Respostas da IA a perguntas estranhas 🤖', body_pt = 'Ficou sem reação perante a pergunta "Mãe, para onde vai a minha sombra à noite?"? Não invente nada. Abra o Anacan AI, obtenha a resposta científica mais doce e encantadora para os 3,5 anos e leia-lha. Sinta-se uma grande filósofa e uma mãe que sabe tudo.', title_sv = 'AI svarar på konstiga frågor 🤖', body_sv = 'Frös du till inför frågan ”Mamma, vart går min skugga på natten?” Hitta inte på något. Öppna Anacan AI, få det mest sagolika och söta vetenskapliga svaret för en 3,5-åring och läs det för barnet. Känn dig som en stor filosof och en mamma som vet allt.', title_vi = 'AI trả lời những câu hỏi kỳ lạ 🤖', body_vi = 'Mẹ đứng hình trước câu hỏi "Mẹ ơi, ban đêm cái bóng của con đi đâu?" Đừng bịa gì cả. Hãy mở Anacan AI, lấy câu trả lời khoa học ngọt ngào, đậm chất cổ tích nhất cho bé 3,5 tuổi và đọc cho bé nghe. Hãy cảm thấy mình như một triết gia vĩ đại, một người mẹ biết tuốt.', title_zh = '奇怪问题交给AI 🤖', body_zh = '“妈妈，我的影子晚上去哪儿了？”被这个问题问住了？什么都别编。打开Anacan AI，为3岁半的孩子找到一个最像童话、最可爱的科学答案，读给宝宝听。感受一下当个大哲学家、无所不知的妈妈吧。' WHERE id = 'ed5a44fd-8133-4d4a-859e-893fc179d90d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El orgullo de vestirse al revés 👕', body_es = '¿Se ha puesto la camiseta del revés y no te deja arreglarlo de ninguna manera? ¡Es cosa suya! La seguridad de esos ojos que dicen «lo he conseguido» importa más que ir bien vestido. Deja que pasee todo el día así de orgulloso, es su elección.', title_fr = 'La fierté à l''envers 👕', body_fr = 'Il a mis son t-shirt à l''envers et refuse fermement qu''on le remette à l''endroit ? C''est son affaire ! La confiance en soi dans ses yeux qui disent « J''ai réussi » compte plus que de bien s''habiller. Laissez-le se promener ainsi toute la journée, avec fierté : c''est son choix.', title_hi = 'उल्टा पहना हुआ गर्व 👕', body_hi = 'कमीज़ उल्टी पहन ली और उसे ठीक करने ही नहीं देता? यह उसका मामला है! ‘मैंने कर लिया’ कहती आँखों का आत्मविश्वास सही कपड़े पहनने से ज़्यादा ज़रूरी है। उसे पूरा दिन उसी गर्व से घूमने दीजिए, यह उसकी पसंद है।', title_id = 'Bangga memakai terbalik 👕', body_id = 'Ia memakai bajunya terbalik dan dengan tegas tidak mau dibetulkan? Itu urusannya! Rasa percaya diri di matanya yang berkata ''aku bisa'' lebih penting daripada berpakaian dengan benar. Biarkan ia berkeliling seharian dengan bangga seperti itu, itu pilihannya.', title_ja = 'うら返しのプライド 👕', body_ja = 'シャツをうら返しに着て、断固として直させない？本人のことです！「できた」と言っているその目の自信のほうが、正しく着ることより大切。一日じゅう誇らしく着ていさせてあげましょう。それはこの子の選択です。', title_ko = '거꾸로 입은 자부심 👕', body_ko = '티셔츠를 거꾸로 입고 절대 못 고치게 하나요? 아이의 일이에요! ''내가 해냈어'' 하는 눈빛 속 자신감이 옷을 바르게 입는 것보다 더 중요해요. 하루 종일 그렇게 뿌듯하게 다니게 두세요, 아이의 선택이니까요.', title_nl = 'Binnenstebuiten vol trots 👕', body_nl = 'Heeft hij zijn shirt binnenstebuiten aangetrokken en mag je het beslist niet goed doen? Zijn keuze! Het zelfvertrouwen in zijn ogen die zeggen ''het is me gelukt'' is belangrijker dan goed aangekleed zijn. Laat hem de hele dag zo trots rondlopen, het is zijn keuze.', title_pl = 'Duma na lewą stronę 👕', body_pl = 'Założył koszulkę na lewą stronę i stanowczo nie pozwala jej poprawić? Jego sprawa! Pewność siebie w jego oczach, mówiących „udało mi się”, jest ważniejsza niż poprawne ubranie. Niech cały dzień chodzi tak z dumą, to jego wybór.', title_pt = 'O orgulho de vestir do avesso 👕', body_pt = 'Vestiu a camisola do avesso e não a deixa de maneira nenhuma endireitá-la? É com ele! A autoconfiança nos olhos que dizem "eu consegui" é mais importante do que vestir-se bem. Deixe-o andar assim orgulhoso o dia todo, é a escolha dele.', title_sv = 'Stolthet på avigsidan 👕', body_sv = 'Har barnet tagit på sig tröjan bak och fram och låter dig absolut inte rätta till den? Det är hens sak! Självförtroendet i ögonen som säger ”jag klarade det” är viktigare än att vara rätt klädd. Låt barnet gå stolt så hela dagen, det är hens val.', title_vi = 'Niềm tự hào mặc trái 👕', body_vi = 'Bé mặc áo trái và kiên quyết không cho mẹ sửa? Đó là việc của bé! Sự tự tin trong đôi mắt "con làm được rồi" quan trọng hơn mặc đúng nhiều. Cứ để bé đi lại cả ngày đầy tự hào như thế, đó là lựa chọn của bé.', title_zh = '反穿衣服的骄傲 👕', body_zh = '衣服穿反了，还坚决不让你帮忙改？那是宝宝自己的事！眼睛里那份“我做到了”的自信，比穿得正确重要得多。就让宝宝带着这份骄傲过一整天吧，这是宝宝的选择。' WHERE id = '14c25fd3-e3ee-49fb-8520-527d8c11b191' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con susurros 🤫', body_es = '¿Se levanta de la cama, corre por la habitación y no quiere dormir? No grites. De repente, empieza a hablar muy despacio, en susurros. Tendrá que concentrarse tanto para entenderte que su cerebro se cansará y pasará solo al modo sueño. ¡Pruébalo!', title_fr = 'S''endormir en chuchotant 🤫', body_fr = 'Il sort du lit et court dans la chambre, il ne veut pas dormir ? Ne criez pas. Mettez-vous soudain à parler très lentement, en chuchotant. Pour vous comprendre, il devra tellement se concentrer que son cerveau, fatigué, passera automatiquement en mode sommeil. Essayez !', title_hi = 'फुसफुसाहट के साथ नींद 🤫', body_hi = 'बिस्तर से उठकर कमरे में दौड़ रहा है, सोना नहीं चाहता? चिल्लाइए मत। अचानक बहुत धीरे, फुसफुसाकर बोलना शुरू कीजिए। आपको समझने के लिए उसे इतना ध्यान लगाना पड़ेगा कि दिमाग थककर अपने आप स्लीप मोड में चला जाएगा। आज़माइए!', title_id = 'Tertidur dengan bisikan 🤫', body_id = 'Ia bangun dari tempat tidur dan berlarian di kamar, tidak mau tidur? Jangan berteriak. Tiba-tiba mulailah berbicara sangat pelan dan berbisik. Untuk memahami Anda, ia harus sangat berkonsentrasi sampai otaknya lelah dan otomatis masuk ke mode tidur. Coba saja!', title_ja = 'ささやき声で眠りへ 🤫', body_ja = 'ベッドから出て部屋を走りまわり、寝たがらない？叫ばないで。急にとてもゆっくり、ささやき声で話し始めてみましょう。聞きとろうと集中するうちに脳が疲れて、自然と睡眠モードに切りかわります。ためしてみて！', title_ko = '속삭임으로 잠들기 🤫', body_ko = '침대에서 일어나 방을 뛰어다니며 안 자려고 하나요? 소리치지 마세요. 갑자기 아주 천천히, 속삭이듯 말하기 시작하세요. 엄마 말을 알아들으려 집중하다 보면 머리가 지쳐 저절로 수면 모드로 넘어갈 거예요. 해 보세요!', title_nl = 'Fluisterend in slaap 🤫', body_nl = 'Komt hij uit bed en rent hij door de kamer, omdat hij niet wil slapen? Ga niet schreeuwen. Ga ineens heel langzaam en fluisterend praten. Om je te verstaan moet hij zich zo concentreren dat zijn brein moe wordt en vanzelf in slaapstand gaat. Probeer het!', title_pl = 'Zasypianie przy szepcie 🤫', body_pl = 'Wstaje z łóżka, biega po pokoju i nie chce spać? Nie krzycz. Nagle zacznij mówić bardzo cicho, szeptem. Żeby cię zrozumieć, będzie musiał tak bardzo się skupić, że jego mózg się zmęczy i automatycznie przejdzie w tryb snu. Sprawdź!', title_pt = 'Adormecer a sussurrar 🤫', body_pt = 'Levanta-se da cama e corre pelo quarto, não quer dormir? Não grite. Comece de repente a falar muito devagar, em sussurro. Para a perceber, vai ter de se concentrar tanto que o cérebro se cansa e passa automaticamente para o modo de sono. Experimente!', title_sv = 'Att somna till viskningar 🤫', body_sv = 'Kliver barnet ur sängen, springer runt i rummet och vill inte sova? Skrik inte. Börja plötsligt prata väldigt långsamt och viskande. Barnet måste koncentrera sig så mycket för att förstå dig att hjärnan blir trött och går över i sömnläge automatiskt. Prova!', title_vi = 'Đưa bé vào giấc ngủ bằng lời thì thầm 🤫', body_vi = 'Bé bật dậy khỏi giường, chạy quanh phòng, không chịu ngủ? Đừng quát. Bỗng nhiên hãy nói thật chậm, thì thầm. Bé sẽ phải tập trung cao độ để hiểu mẹ, đến mức não mệt và tự động chuyển sang chế độ ngủ. Thử xem!', title_zh = '在悄悄话里入睡 🤫', body_zh = '从床上爬起来满屋跑，不想睡觉？别吼。突然用很轻很慢的悄悄话说话。为了听懂你，宝宝得非常专心，大脑累了就会自动切换到睡眠模式。试试看！' WHERE id = '4ffcb0aa-a9e4-48df-8c7b-2bcf41163980' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento de silencio perfecto 🛋️', body_es = '¿Está tan metido en sus puzles que de repente hay silencio en casa? No sospeches, sírvete un café ya mismo. Esos minutos raros y de oro no los gastes en limpiar ni en la ropa, sino en descansar el alma. No eres un robot.', title_fr = 'Un moment de silence parfait 🛋️', body_fr = 'Il est tellement absorbé par ses puzzles qu''un silence soudain règne dans la maison ? Ne vous méfiez pas, servez-vous tout de suite un café. Ces minutes rares et précieuses, ne les dépensez pas en ménage ou en linge, mais à reposer votre âme. Vous n''êtes pas un robot.', title_hi = 'खामोशी का परफ़ेक्ट पल 🛋️', body_hi = 'अपनी पज़ल से इतनी गहराई से खेल रहा है कि घर में अचानक सन्नाटा छा गया? शक मत कीजिए, फ़ौरन अपने लिए कॉफ़ी डालिए। ये दुर्लभ, सुनहरे मिनट सफ़ाई या कपड़ों पर नहीं, अपने मन को आराम देने में लगाइए। आप रोबोट नहीं हैं।', title_id = 'Momen hening yang sempurna 🛋️', body_id = 'Ia begitu asyik bermain puzzle sampai rumah tiba-tiba hening? Jangan curiga, segera tuang kopi untuk diri sendiri. Pakai menit-menit langka dan berharga itu bukan untuk bersih-bersih atau cucian, tapi untuk mengistirahatkan jiwa Anda. Anda bukan robot.', title_ja = '完璧な静けさのひととき 🛋️', body_ja = 'パズルに夢中で、家が急に静かになった？疑わないで、すぐに自分にコーヒーを入れましょう。その貴重な黄金の数分間は、掃除や洗濯ではなく、心を休めるために使って。あなたはロボットではありません。', title_ko = '완벽한 고요의 순간 🛋️', body_ko = '퍼즐에 푹 빠져 집이 갑자기 조용해졌나요? 의심하지 말고 바로 커피 한 잔 따르세요. 이 귀한 황금 같은 몇 분은 청소나 빨래가 아니라 마음을 쉬는 데 쓰세요. 엄마는 로봇이 아니에요.', title_nl = 'Het perfecte stille moment 🛋️', body_nl = 'Speelt hij zo geconcentreerd met zijn puzzels dat het ineens stil is in huis? Wees niet achterdochtig, schenk jezelf meteen een kop koffie in. Besteed die zeldzame, gouden minuten niet aan schoonmaken of de was, maar aan rust voor je ziel. Je bent geen robot.', title_pl = 'Chwila idealnej ciszy 🛋️', body_pl = 'Tak bardzo pochłonęły go puzzle, że w domu nagle zrobiło się cicho? Nie podejrzewaj niczego, od razu nalej sobie kawy. Te rzadkie, złote minuty przeznacz nie na sprzątanie czy pranie, tylko na odpoczynek dla duszy. Nie jesteś robotem.', title_pt = 'O momento perfeito de silêncio 🛋️', body_pt = 'Está tão concentrado nos puzzles que caiu de repente o silêncio em casa? Não desconfie, sirva-se já de um café. Gaste esses minutos raros e de ouro não em limpezas ou roupa, mas a descansar a alma. Não é um robô.', title_sv = 'En stund av perfekt tystnad 🛋️', body_sv = 'Leker barnet så djupt med pusslen att det plötsligt blev tyst hemma? Bli inte misstänksam, häll genast upp en kopp kaffe åt dig. Lägg de sällsynta, gyllene minuterna på att vila själen, inte på städning eller tvätt. Du är ingen robot.', title_vi = 'Khoảnh khắc yên lặng hoàn hảo 🛋️', body_vi = 'Bé mải mê ghép hình đến mức cả nhà bỗng im phăng phắc? Đừng nghi ngờ, rót ngay cho mình một tách cà phê. Hãy dành những phút vàng hiếm hoi ấy không phải cho dọn dẹp hay quần áo, mà để tâm hồn được nghỉ ngơi. Mẹ đâu phải người máy.', title_zh = '完美的安静时刻 🛋️', body_zh = '拼图拼得那么投入，家里突然安静下来了？别怀疑，马上给自己倒杯咖啡。把这难得的黄金几分钟，用来放松心灵，而不是打扫或洗衣服。你不是机器人。' WHERE id = '5dd3ffc3-a306-476f-91ee-6cb8332ca500' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al servirte un té ves que el móvil ha desaparecido y que detrás del sofá está diciendo «¿Diga?» igual que tú. Está escaneando tus hábitos digitales.', body_fr = 'En vous servant un thé, vous remarquez que votre téléphone a disparu, et derrière le canapé, il dit « Allô » comme vous. Il scanne vos habitudes numériques.', body_hi = 'अपने लिए चाय डालते समय देखा कि आपका फ़ोन गायब है और वह सोफ़े के पीछे आपकी तरह ‘हैलो’ बोल रहा है। वह आपकी डिजिटल आदतों को स्कैन कर रहा है।', body_id = 'Saat menuang teh, Anda sadar ponsel Anda hilang dan ia di balik sofa sedang bilang ''Halo'' persis seperti Anda. Ia sedang memindai kebiasaan digital Anda.', body_ja = '自分にお茶を入れていたら、スマホがなくなっていて、ソファの後ろであなたのまねをして「もしもし」と言っている。あなたのデジタル習慣をスキャン中です。', body_ko = '차를 따르다 보니 휴대폰이 사라졌고, 아이가 소파 뒤에서 엄마처럼 ''여보세요'' 하고 있나요? 엄마의 디지털 습관을 스캔하는 중이에요.', body_nl = 'Je schenkt thee in en merkt dat je telefoon verdwenen is, en achter de bank hoor je hem net als jij ''Hallo?'' zeggen. Hij scant je digitale gewoontes.', body_pl = 'Nalewasz sobie herbatę i nagle widzisz, że telefon zniknął, a on za kanapą mówi „Halo” dokładnie jak ty. Właśnie skanuje twoje cyfrowe nawyki.', body_pt = 'Ao servir-se de chá, reparou que o telemóvel desapareceu e que ele, atrás do sofá, está a dizer "Estou?" como a mãe. Está a digitalizar os seus hábitos digitais.', body_sv = 'När du häller upp te åt dig själv märker du att telefonen har försvunnit, och bakom soffan säger barnet ”Hallå” precis som du. Barnet skannar dina digitala vanor.', body_vi = 'Lúc rót trà, mẹ chợt thấy điện thoại biến mất, và sau sofa vang lên tiếng bé nói "A lô" y như mẹ. Bé đang "quét" thói quen dùng điện thoại của mẹ đấy.', body_zh = '给自己倒茶时，发现手机不见了，原来宝宝正躲在沙发后面学你说“喂？”。宝宝正在“扫描”你的数字习惯。' WHERE id = '8d6625c2-a9b5-42f5-804d-da69978a47f8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Por fin se ha dormido. El pitido de tus oídos no se acaba. Abre el Medidor de sonido en la app. Mira el 0 decibelios en la pantalla y comprueba visualmente cómo el silencio de la habitación entra en tu cerebro y te sana.', body_fr = 'Il s''est enfin endormi. Le bourdonnement dans vos oreilles ne s''arrête pas. Ouvrez le Sonomètre dans l''application. En regardant s''afficher 0 décibel, constatez visuellement comment le silence de la pièce pénètre votre cerveau et vous apaise.', body_hi = 'आखिरकार वह सो गया। कानों की सीटी थम नहीं रही। ऐप में साउंड मीटर खोलिए। स्क्रीन पर ‘0 डेसिबल’ देखते हुए अपनी आँखों से पुष्टि कीजिए कि कमरे की खामोशी आपके दिमाग में कैसे उतर रही है और आपको कैसे ठीक कर रही है।', body_id = 'Akhirnya ia tidur. Dengungan di telinga Anda tak kunjung hilang. Buka Pengukur Suara di aplikasi. Sambil memandangi tulisan 0 desibel di layar, pastikan secara visual bagaimana keheningan kamar meresap ke otak Anda dan memulihkan Anda.', body_ja = 'やっと寝てくれた。耳鳴りがおさまらない？アプリで「サウンドメーター」を開きましょう。画面の0デシベルの表示を見ながら、部屋の静けさが頭にしみこみ、あなたを癒やしていくのを目で確かめて。', body_ko = '드디어 잠들었어요. 귀에서 울리는 소리가 멈추지 않나요? 앱에서 소음 측정기를 열어 보세요. 화면의 0 데시벨을 보며 방 안의 고요가 머릿속에 스며들어 나를 회복시키는 걸 눈으로 확인하세요.', body_nl = 'Eindelijk slaapt hij. Het suizen in je oren houdt niet op. Open de Geluidsmeter in de app. Kijk naar de 0 decibel op het scherm en zie hoe de stilte in de kamer tot je hoofd doordringt en je heelt.', body_pl = 'Wreszcie zasnął. Dzwonienie w uszach nie mija. Otwórz w aplikacji Miernik dźwięku. Patrząc na napis 0 decybeli na ekranie, zobacz na własne oczy, jak cisza w pokoju przenika do twojego mózgu i jak cię leczy.', body_pt = 'Finalmente adormeceu. O zumbido nos ouvidos não passa. Abra o Medidor de Som na app. A olhar para os 0 decibéis no ecrã, confirme visualmente como o silêncio do quarto lhe entra no cérebro e a cura.', body_sv = 'Äntligen sover barnet. Det slutar inte ringa i öronen. Öppna Ljudmätaren i appen. Titta på 0 decibel på skärmen och bekräfta visuellt hur tystnaden i rummet tränger in i hjärnan och läker dig.', body_vi = 'Cuối cùng bé cũng ngủ. Tiếng ù trong tai mẹ vẫn chưa dứt. Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số 0 decibel trên màn hình để tận mắt thấy sự tĩnh lặng trong phòng đang thấm vào tâm trí và chữa lành cho mẹ ra sao.', body_zh = '宝宝终于睡着了。耳朵里的嗡嗡声却停不下来。打开应用里的分贝仪。看着屏幕上的0分贝，直观地确认房间里的安静如何渗入你的大脑、慢慢治愈你。' WHERE id = 'fa66784d-c126-46e1-ac35-502bd4ad5f50' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té en pareja 🥂', title_fr = 'Un thé en couple 🥂', title_hi = 'जोड़ी वाली चाय 🥂', title_id = 'Teh berdua 🥂', title_ja = 'ふたりのお茶時間 🥂', title_ko = '부부의 차 한 잔 🥂', title_nl = 'Thee voor twee 🥂', title_pl = 'Herbata we dwoje 🥂', title_pt = 'Chá a dois 🥂', title_sv = 'Te för två 🥂', title_vi = 'Tách trà cho hai người 🥂', title_zh = '两个人的茶 🥂' WHERE id = '7ce3cc61-1a21-499e-a7c2-d24e3693336c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo a las sombras 👻', title_fr = 'Peur de l''ombre 👻', title_hi = 'परछाईं से डर 👻', title_id = 'Takut bayangan 👻', title_ja = '影がこわい 👻', title_ko = '그림자가 무서워 👻', title_nl = 'Bang voor schaduwen 👻', title_pl = 'Strach przed cieniem 👻', title_pt = 'Medo da sombra 👻', title_sv = 'Rädd för skuggor 👻', title_vi = 'Sợ cái bóng 👻', title_zh = '怕影子 👻' WHERE id = '1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El centro del pan es mío! 🍞', body_es = '¿Se come solo el centro de la rebanada de pan y te da las cortezas? No discutas por las cortezas. A partir de mañana corta el pan con moldes metálicos de galletas (con forma de animales). El diseño resuelve al instante este problema de filosofía alimentaria.', title_fr = 'Le milieu du pain, c''est pour moi ! 🍞', body_fr = 'Il mange juste le milieu de sa tranche de pain et vous tend les croûtes ? Ne discutez pas des croûtes. Dès demain, découpez le pain avec des emporte-pièces en métal (en forme d''animaux). Le design règle instantanément ce problème de philosophie alimentaire.', title_hi = 'ब्रेड का बीच वाला हिस्सा मेरा है! 🍞', body_hi = 'ब्रेड के स्लाइस का सिर्फ़ बीच का हिस्सा खाकर किनारे आपको थमा देता है? किनारों पर बहस मत कीजिए। कल से ब्रेड को धातु के कुकी कटर (जानवरों के आकार वाले) से काटिए। डिज़ाइन खाने के इस फ़लसफ़े की समस्या तुरंत सुलझा देता है।', title_id = 'Bagian tengah roti punyaku! 🍞', body_id = 'Ia hanya memakan bagian tengah roti tawar dan menyodorkan pinggirannya kepada Anda? Jangan berdebat soal pinggiran roti. Mulai besok, potong rotinya dengan cetakan kue logam (bentuk hewan). Desain langsung menyelesaikan masalah filsafat makanan ini.', title_ja = 'パンのまん中はぼくの！ 🍞', body_ja = '食パンのまん中だけ食べて、耳をあなたに差し出す？耳のことで言い合いはやめましょう。明日からは、パンを金属のクッキー型（動物の形）で抜いてみて。デザインがこの食の哲学問題をすぐに解決してくれます。', title_ko = '빵 가운데는 내 거야! 🍞', body_ko = '식빵 가운데만 먹고 테두리는 엄마에게 내미나요? 테두리로 다투지 마세요. 내일부터 동물 모양 금속 쿠키 틀로 빵을 찍어 주세요. 디자인이 이 음식 철학 문제를 단번에 해결해 줘요.', title_nl = 'Het midden van het brood is van mij! 🍞', body_nl = 'Eet hij alleen het midden van zijn boterham en geeft hij jou de korstjes? Ga niet in discussie over korstjes. Steek vanaf morgen het brood uit met metalen koekjesvormpjes (in dierenvormen). Het ontwerp lost dit voedselfilosofische probleem meteen op.', title_pl = 'Środek chleba jest mój! 🍞', body_pl = 'Zjada tylko środek kromki, a skórki podaje tobie? Nie kłóć się o skórki. Od jutra wycinaj chleb metalowymi foremkami do ciastek (w kształcie zwierzątek). Design od razu rozwiązuje ten problem filozofii jedzenia.', title_pt = 'O miolo do pão é meu! 🍞', body_pt = 'Come só o miolo da fatia de pão e estende-lhe as côdeas? Não discuta por causa das côdeas. A partir de amanhã, corte o pão com formas de bolachas de metal (com feitios de animais). O design resolve num instante este problema de filosofia alimentar.', title_sv = 'Mitten av brödet är min! 🍞', body_sv = 'Äter barnet bara mitten av brödskivan och räcker kanterna till dig? Bråka inte om kanterna. Från och med i morgon kan du skära brödet med kakformar i metall (i djurform). Designen löser det här matfilosofiska problemet direkt.', title_vi = 'Ruột bánh mì là của con! 🍞', body_vi = 'Bé chỉ ăn phần ruột của lát bánh mì rồi đưa vỏ cho mẹ? Đừng tranh cãi về phần vỏ. Từ mai, hãy cắt bánh mì bằng khuôn bánh quy kim loại (hình con vật). Một chút thiết kế sẽ giải quyết ngay "vấn đề triết lý ăn uống" này.', title_zh = '面包心是我的！🍞', body_zh = '切片面包只吃中间，把面包边递给你？别为面包边争了。从明天起，用金属饼干模具（动物形状）切面包。造型设计能立刻解决这个“饮食哲学”难题。' WHERE id = 'a4d74500-c7bc-4a1a-a200-c6bae74eb5ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo respira su olor 🫂', body_es = '¿Hoy te ha vuelto loca de verdad y te ha dejado sin energía? Pero duerme en la cama con tanta inocencia... Apaga las luces, no leas cuento. Túmbate a su lado, respira hondo ese olor limpio de niño y da gracias también por este día.', title_fr = 'Respirez simplement son odeur 🫂', body_fr = 'Aujourd''hui, il vous a vraiment rendue folle et a aspiré toute votre énergie ? Mais il dort si innocemment dans son lit... Éteignez la lumière, ne lisez pas de conte. Allongez-vous près de lui, respirez profondément cette pure odeur d''enfant et soyez reconnaissante pour cette journée aussi.', title_hi = 'बस उसकी खुशबू अपने अंदर भर लीजिए 🫂', body_hi = 'आज उसने सच में आपको पागल कर दिया, सारी ऊर्जा निचोड़ ली? पर बिस्तर पर कितना मासूम सो रहा है... लाइटें बंद कीजिए, कहानी मत पढ़िए। उसके पास लेटिए, उस मासूम बच्चे की खुशबू गहरी साँसों में भरिए और इस दिन के लिए भी शुक्रिया कहिए।', title_id = 'Cukup hirup aromanya 🫂', body_id = 'Hari ini ia benar-benar membuat Anda pusing dan menyedot energi Anda? Tapi ia tidur begitu polos di tempat tidurnya... Matikan lampu, tak perlu membacakan dongeng. Berbaringlah di sampingnya, hirup dalam-dalam aroma anak yang bersih itu, dan syukuri hari ini juga.', title_ja = 'においを深く吸いこんで 🫂', body_ja = '今日は本当に振りまわされて、エネルギーを吸いとられた？でも、ベッドではこんなに無邪気に眠っている…。明かりを消して、絵本はお休み。そばに横になって、子どもの清らかなにおいを深く吸いこみ、今日という日にも感謝しましょう。', title_ko = '그냥 냄새를 깊이 들이마셔요 🫂', body_ko = '오늘 정말 미칠 것 같고 에너지를 다 빼앗겼나요? 그래도 침대에선 저렇게 순하게 자고 있죠... 불을 끄고 동화도 읽지 마세요. 옆에 누워 그 깨끗한 아이 냄새를 깊이 들이마시고 오늘 하루에도 감사하세요.', title_nl = 'Snuif gewoon zijn geur op 🫂', body_nl = 'Heeft hij je vandaag echt gek gemaakt en al je energie opgezogen? Maar hij ligt zo onschuldig in bed... Doe het licht uit, lees geen verhaaltje voor. Ga naast hem liggen, snuif diep die zuivere kindergeur op en wees dankbaar voor ook deze dag.', title_pl = 'Po prostu poczuj jego zapach 🫂', body_pl = 'Dziś naprawdę doprowadził cię do szału i wyssał z ciebie energię? A jednak śpi w łóżku tak niewinnie... Zgaś światło, nie czytaj bajki. Połóż się obok, głęboko wdychaj ten czysty dziecięcy zapach i podziękuj także za ten dzień.', title_pt = 'Respire só o cheirinho dele 🫂', body_pt = 'Hoje deu-lhe mesmo cabo da cabeça e sugou-lhe a energia? Mas está a dormir na cama tão inocente... Apague as luzes, não leia histórias. Deite-se ao lado dele, respire fundo aquele cheirinho puro de criança e agradeça também por este dia.', title_sv = 'Andas bara in doften 🫂', body_sv = 'Gjorde barnet dig verkligen galen i dag och sög ut all energi? Men i sängen ligger hen så oskyldigt... Släck lamporna, läs ingen saga. Lägg dig bredvid, andas djupt in den rena barndoften och var tacksam för den här dagen också.', title_vi = 'Chỉ cần hít hương thơm của bé 🫂', body_vi = 'Hôm nay bé thật sự làm mẹ phát điên, rút cạn sức lực? Nhưng lúc này bé nằm ngủ trên giường thật ngây thơ... Hãy tắt đèn, bỏ qua truyện. Nằm xuống cạnh bé, hít thật sâu mùi hương trẻ thơ trong trẻo ấy và biết ơn cả ngày hôm nay.', title_zh = '深深闻一闻宝宝的味道 🫂', body_zh = '今天宝宝真的快把你逼疯了，耗尽了你的能量？可躺在床上的样子又那么天真……关上灯，今天不讲故事。躺在宝宝身边，深深吸一口那纯净的孩子气息，也为这一天心怀感恩吧。' WHERE id = 'e1513af5-17e8-478e-acc0-67084e546889' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de no querer salir de casa ⛅', body_es = '¿Las cuatro paredes te ahogan y él llora en el sofá porque no quiere salir? Abre Tiempo y ropa, elige el conjunto adecuado y llévalo al parque aunque sea a regañadientes. En cuanto le dé el aire fresco en la cara, toda esa agresividad se esfumará. ¡Confiamos en ti!', title_fr = 'Le drame du « Je veux pas sortir » ⛅', body_fr = 'Les quatre murs vous étouffent, et lui pleure sur le canapé, il ne veut pas sortir ? Ouvrez Météo et tenue, choisissez la bonne tenue et emmenez-le au parc, même à contrecœur. Dès que l''air frais touchera son visage, toute son agressivité s''envolera. On compte sur vous !', title_hi = '‘घर से नहीं निकलना’ वाली मुसीबत ⛅', body_hi = 'चार दीवारें आपका दम घोंट रही हैं, और वह सोफ़े पर रोते हुए बाहर जाने से मना कर रहा है? मौसम और कपड़े खोलकर सही कपड़े चुनिए और ज़बरदस्ती ही सही, पार्क ले जाइए। ताज़ी हवा चेहरे पर लगते ही उसका सारा गुस्सा उड़ जाएगा। हमें आप पर भरोसा है!', title_id = 'Drama tidak mau keluar rumah ⛅', body_id = 'Empat dinding terasa menyesakkan, sementara ia menangis di sofa tidak mau keluar? Buka Cuaca dan Pakaian, pilih setelan yang tepat, dan bawa ia ke taman meski harus sedikit dipaksa. Begitu udara segar menyentuh wajahnya, semua agresinya akan hilang. Kami percaya pada Anda!', title_ja = '家から出たくない問題 ⛅', body_ja = '四方の壁に息がつまりそうなのに、この子はソファで泣いて外に出たがらない？「天気と服装」を開いてぴったりのコーデを選び、多少強引にでも公園へ連れ出しましょう。新鮮な空気が顔にあたった瞬間、イライラは吹き飛びます。応援しています！', title_ko = '밖에 나가기 싫어 ⛅', body_ko = '네 벽에 숨이 막히는데 아이는 소파에서 울며 나가기 싫다고 하나요? 날씨와 옷차림을 열어 알맞은 옷을 고르고, 억지로라도 공원에 데려가세요. 맑은 공기가 얼굴에 닿는 순간 그 공격성이 다 날아갈 거예요. 엄마를 믿어요!', title_nl = 'Het ''ik wil niet naar buiten''-verdriet ⛅', body_nl = 'Word je gek van de vier muren, terwijl hij op de bank huilt en niet naar buiten wil? Open Weer en kleding, kies de juiste outfit en ga desnoods met wat moeite naar het park. Zodra de frisse lucht zijn gezicht raakt, waait al die agressie weg. We geloven in je!', title_pl = 'Kłopot z „nie chcę wychodzić” ⛅', body_pl = 'Cztery ściany cię przytłaczają, a on płacze na kanapie i nie chce wyjść z domu? Otwórz Pogodę i ubiór, wybierz odpowiedni zestaw i choćby na siłę zabierz go do parku. Gdy tylko świeże powietrze owieje mu twarz, cała złość uleci. Wierzymy w ciebie!', title_pt = 'O drama do "não quero sair de casa" ⛅', body_pt = 'As quatro paredes estão a sufocá-la e ele chora no sofá sem querer sair? Abra o Tempo e Roupa, escolha a combinação certa e leve-o ao parque, nem que seja à força. Mal o ar puro lhe bater na cara, toda aquela agressividade vai desaparecer. Confiamos em si!', title_sv = 'Jag vill inte gå ut-sorgen ⛅', body_sv = 'Kväver de fyra väggarna dig, medan barnet gråter i soffan och inte vill gå ut? Öppna Väder och kläder, välj rätt kombination och ta med barnet till parken, även om det tar emot. Så fort den friska luften når ansiktet flyger all ilska iväg. Vi tror på dig!', title_vi = 'Nỗi buồn "không muốn ra ngoài" ⛅', body_vi = 'Bốn bức tường làm mẹ ngột ngạt, còn bé thì khóc trên sofa không chịu ra ngoài? Hãy mở Thời tiết và trang phục, chọn bộ đồ phù hợp và đưa bé ra công viên, dù có phải hơi ép một chút. Gió trời vừa chạm mặt, mọi cơn cáu giận sẽ tan biến. Chúng tôi tin mẹ!', title_zh = '“我不想出门”的烦恼 ⛅', body_zh = '四面墙让你喘不过气，宝宝却在沙发上哭着不肯出门？打开天气与穿衣，选好合适的搭配，哪怕连哄带拉也要去公园。新鲜空气一吹到脸上，那些火气就会飞走。我们相信你！' WHERE id = 'f1d4800f-e749-493d-9ba5-56a7cf6edfa0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ley de los alimentos que no se mezclan 🚫', body_es = '¿Se ha armado una revolución en el desayuno porque el tomate ha tocado el pepino? Bienvenida a la filosofía alimentaria oficial de los 3,5 años. No busques lógica: aprende en Recetas saludables a dividir los platos en zonas divertidas y separadas, y resuelve en paz esta crisis absurda.', title_fr = 'La loi des aliments incompatibles 🚫', body_fr = 'Au petit-déjeuner, c''est la révolution parce que la tomate a touché le concombre ? Bienvenue dans la philosophie alimentaire officielle des 3 ans et demi. Ne cherchez pas de logique : apprenez dans les Recettes saines à diviser l''assiette en zones ludiques et séparées, et réglez cette crise absurde en paix.', title_hi = '‘मिलने न देने’ वाले खाने का नियम 🚫', body_hi = 'नाश्ते में टमाटर खीरे को छू गया, इसलिए हंगामा मच गया? 3.5 साल की आधिकारिक ‘खाने की फ़िलॉसफ़ी’ में आपका स्वागत है। तर्क मत ढूँढिए, सेहतमंद रेसिपी में सीखिए कि प्लेट को मज़ेदार और अलग-अलग खानों में कैसे बाँटें, और यह बेतुका संकट शांति से सुलझाइए।', title_id = 'Hukum makanan yang tak boleh bersentuhan 🚫', body_id = 'Revolusi meletus saat sarapan karena tomat menyentuh mentimun? Selamat datang di filsafat makanan resmi usia 3,5 tahun. Jangan cari logikanya, pelajari di Resep Sehat cara membagi piring menjadi zona-zona terpisah yang menyenangkan, dan selesaikan krisis absurd ini dengan damai.', title_ja = 'まぜてはいけない食べものの法則 🚫', body_ja = '朝ごはんでトマトがきゅうりにふれたから革命勃発？3歳半の公式な食の哲学へようこそ。理屈を探さないで。「ヘルシーレシピ」でお皿を楽しく仕切る方法を知って、このおかしな危機を平和に解決しましょう。', title_ko = '섞이면 안 되는 음식의 법칙 🚫', body_ko = '아침 식사에서 토마토가 오이에 닿았다고 난리가 났나요? 3.5세의 공식 음식 철학에 오신 걸 환영해요. 논리를 찾지 말고, 건강한 레시피에서 접시를 재미있고 분리된 구역으로 나누는 법을 배워 이 엉뚱한 위기를 평화롭게 해결하세요.', title_nl = 'De wet van eten dat elkaar niet mag raken 🚫', body_nl = 'Breekt er bij het ontbijt een revolutie uit omdat de tomaat de komkommer raakte? Welkom bij de officiële voedselfilosofie van een 3,5-jarige. Zoek geen logica, leer in Gezonde recepten hoe je borden in leuke, gescheiden vakjes verdeelt, en los deze absurde crisis vreedzaam op.', title_pl = 'Prawo niełączenia potraw 🚫', body_pl = 'Przy śniadaniu wybuchła rewolucja, bo pomidor dotknął ogórka? Witaj w oficjalnej filozofii żywieniowej 3,5-latka. Nie szukaj logiki, dowiedz się ze Zdrowych przepisów, jak podzielić talerz na zabawne, osobne strefy, i rozwiąż ten absurdalny kryzys pokojowo.', title_pt = 'A lei dos alimentos que não se tocam 🚫', body_pt = 'Houve uma revolução ao pequeno-almoço porque o tomate tocou no pepino? Bem-vinda à filosofia alimentar oficial dos 3,5 anos. Não procure lógica: aprenda nas Receitas Saudáveis a dividir o prato em zonas divertidas e separadas e resolva em paz esta crise absurda.', title_sv = 'Lagen om mat som inte får blandas 🚫', body_sv = 'Blev det revolution vid frukosten för att tomaten rörde vid gurkan? Välkommen till 3,5-åringens officiella matfilosofi. Leta inte efter logik, lär dig i Hälsosamma recept hur du delar upp tallriken i roliga, separata zoner och lös den absurda krisen i fred.', title_vi = 'Luật "đồ ăn không được chạm nhau" 🚫', body_vi = 'Cả bữa sáng nổi loạn chỉ vì cà chua chạm vào dưa chuột? Chào mừng mẹ đến với triết lý ăn uống chính thức của tuổi 3,5. Đừng tìm logic, hãy học cách chia đĩa thành những "khu vực riêng" vui nhộn trong Công thức lành mạnh và giải quyết cơn khủng hoảng phi lý này trong hòa bình.', title_zh = '“食物不能碰”定律 🚫', body_zh = '早餐时番茄碰到了黄瓜，就闹起了革命？欢迎来到3岁半的官方“饮食哲学”。别找逻辑了，去健康食谱学学怎样把盘子分成有趣又互不接触的小区域，和平化解这场荒诞的危机。' WHERE id = '3a198cfb-0f8d-4bb9-b96b-0ead690adcbf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Negociación diplomática para dormir 🤝', body_es = 'Para no meterse en la cama, negocia contigo de forma oficial: «Bebo dos sorbos de agua, me das un abrazo y luego me duermo». Sonríe ante esta manipulación de experto. Acepta su condición, apaga las luces con decisión y cierra el trato al instante.', title_fr = 'Négociation diplomatique du coucher 🤝', body_fr = 'Pour ne pas aller au lit, il négocie officiellement avec vous : « Deux gorgées d''eau, un câlin, et après je dors. » Souriez devant ce maître manipulateur. Acceptez sa condition, éteignez fermement la lumière et concluez le contrat sur-le-champ.', title_hi = 'नींद की कूटनीतिक सौदेबाज़ी 🤝', body_hi = 'बिस्तर पर न जाने के लिए आपसे बाकायदा सौदा करता है: ‘दो घूँट पानी पी लूँ, एक बार गले लगा लो, फिर सो जाऊँगा।’ इस माहिर चाल पर मुस्कुराइए। शर्त मान लीजिए, लाइटें पक्के इरादे से बंद कीजिए और सौदा तुरंत पक्का कर दीजिए।', title_id = 'Tawar-menawar tidur yang diplomatis 🤝', body_id = 'Ia resmi bernegosiasi dengan Anda supaya tidak naik ke tempat tidur: ''Aku minum dua teguk air, dipeluk sekali, lalu tidur.'' Tersenyumlah pada manipulasi ahli ini. Terima syaratnya, matikan lampu dengan tegas, dan langsung tutup kesepakatannya.', title_ja = 'おやすみ前の外交交渉 🤝', body_ja = '寝ないために、正式に交渉してきます。「お水を2口飲んで、1回ぎゅっとしてくれたら寝る」。この名人の駆け引きにほほえんで。条件をのんだら、きっぱり明かりを消して、すぐに契約成立です。', title_ko = '외교적인 잠자리 협상 🤝', body_ko = '잠자리에 안 들려고 정식으로 협상하나요? ''물 두 모금 마시고, 한 번 안아 주면 잘게.'' 이 능숙한 협상에 미소 지어 주세요. 조건을 받아들이고 단호하게 불을 꺼서 계약을 바로 마무리하세요.', title_nl = 'Diplomatieke onderhandelingen over bedtijd 🤝', body_nl = 'Onderhandelt hij officieel met je om niet naar bed te hoeven: ''Twee slokjes water, één knuffel, dan ga ik slapen''? Glimlach om deze meesterlijke manipulatie. Accepteer zijn voorwaarde, doe vastberaden het licht uit en sluit de deal meteen.', title_pl = 'Dyplomatyczne negocjacje przed snem 🤝', body_pl = 'Oficjalnie negocjuje z tobą, żeby nie iść do łóżka: „Dwa łyki wody, jeden przytulas i idę spać”. Uśmiechnij się do tej mistrzowskiej manipulacji. Przyjmij warunki, stanowczo zgaś światło i od razu zamknij umowę.', title_pt = 'Negociação diplomática do sono 🤝', body_pt = 'Para não ir para a cama, negoceia consigo formalmente: "Bebo dois golos de água, dás-me um abraço e depois durmo". Sorria a esta manipulação de mestre. Aceite as condições, apague as luzes com firmeza e feche o contrato de imediato.', title_sv = 'Diplomatisk förhandling om läggdags 🤝', body_sv = 'Barnet förhandlar formellt med dig för att slippa gå och lägga sig: ”Två klunkar vatten, en kram, sen sover jag.” Le åt den här mästerliga manipulationen. Godta villkoret, släck bestämt lamporna och slut avtalet på stört.', title_vi = 'Mặc cả giấc ngủ kiểu ngoại giao 🤝', body_vi = 'Bé chính thức mặc cả với mẹ để khỏi lên giường: "Con uống hai ngụm nước, mẹ ôm con một cái, rồi con ngủ." Hãy mỉm cười trước màn "thao túng" bậc thầy này. Chấp nhận điều kiện, rồi dứt khoát tắt đèn để chốt hợp đồng ngay lập tức.', title_zh = '睡前的外交谈判 🤝', body_zh = '为了不上床，正式和你讨价还价：“我喝两口水，抱一下，然后就睡。”对这位谈判高手笑一笑吧。接受条件，然后果断关灯，当场签下这份“合同”。' WHERE id = '9f8b4dfd-dfd3-4045-969a-2d6b122add47' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego del suelo es lava 🌋', body_es = '¡El suelo es lava, súbete al sofá! Su imaginación ha convertido la casa en una selva. Deja tus cosas a un lado y entra tú también en su mundo huyendo de la lava, aunque sea 2 minutos. A veces seguir las reglas del peque es la mejor forma de soltar estrés.', title_fr = 'Le sol, c''est de la lave 🌋', body_fr = '« Le sol, c''est de la lave, monte sur le canapé ! » Son imagination a transformé la maison en jungle. Mettez vos tâches de côté et, même 2 minutes, entrez dans son monde en fuyant la lave vous aussi. Parfois, suivre les règles de l''enfant est la meilleure façon d''évacuer le stress.', title_hi = 'फ़र्श पर लावा वाला खेल 🌋', body_hi = '‘फ़र्श लावा है, सोफ़े पर चढ़ो!’ कल्पना ने घर को जंगल बना दिया है। अपने काम एक तरफ़ रखिए और 2 मिनट के लिए ही सही, लावा से बचते हुए उसकी दुनिया में चली आइए। कभी-कभी बच्चे के नियम मानना तनाव उतारने का सबसे अच्छा तरीका है।', title_id = 'Permainan lantai lava 🌋', body_id = '''Lantainya lava, naik ke sofa!'' Daya khayalnya mengubah rumah menjadi hutan rimba. Tinggalkan dulu urusan Anda dan masuklah ke dunianya, berlari menghindari lava walau hanya 2 menit. Kadang menuruti aturan anak adalah cara terbaik melepas stres.', title_ja = '床はマグマごっこ 🌋', body_ja = '「床はマグマだよ、ソファに乗って！」想像力が家をジャングルに変えています。自分の用事はわきに置いて、2分だけでもマグマから逃げてこの子の世界に入ってみて。ときには子どものルールに従うのが、いちばんのストレス解消法です。', title_ko = '바닥은 용암 놀이 🌋', body_ko = '바닥은 용암이야, 소파로 올라가! 상상력이 집을 정글로 바꿔 놓았어요. 하던 일은 잠시 내려놓고 2분만이라도 용암을 피해 아이의 세계로 들어가 보세요. 가끔은 아이의 규칙을 따르는 게 최고의 스트레스 해소법이에요.', title_nl = 'De vloer is lava 🌋', body_nl = '''De vloer is lava, klim op de bank!'' Zijn fantasie heeft het huis in een jungle veranderd. Leg je eigen klusjes even weg en stap, al is het maar 2 minuten, al vluchtend voor de lava zijn wereld binnen. Soms is je aan de regels van je kind houden de beste manier om stress kwijt te raken.', title_pl = 'Zabawa w lawę na podłodze 🌋', body_pl = '„Podłoga to lawa, wskakuj na kanapę!” Wyobraźnia zmieniła dom w dżunglę. Odłóż swoje sprawy na bok i choć na 2 minuty wejdź do jego świata, uciekając przed lawą. Czasem podporządkowanie się zasadom dziecka to najlepszy sposób na odstresowanie.', title_pt = 'O chão é lava 🌋', body_pt = '"O chão é lava, sobe para o sofá!" A imaginação transformou a casa numa selva. Ponha de lado as suas tarefas e, nem que seja por 2 minutos, fuja também da lava e entre no mundo dele. Às vezes, obedecer às regras da criança é a melhor forma de libertar o stress.', title_sv = 'Golvet är lava-leken 🌋', body_sv = '”Golvet är lava, hoppa upp i soffan!” Fantasin har förvandlat hemmet till en djungel. Lägg dina egna sysslor åt sidan och gå in i barnets värld, även om det bara är i 2 minuter, genom att fly från lavan. Ibland är det bästa sättet att släppa stress att följa barnets regler.', title_vi = 'Trò chơi sàn nhà là dung nham 🌋', body_vi = '"Sàn là dung nham, leo lên sofa đi!" Trí tưởng tượng đã biến ngôi nhà thành khu rừng rậm. Hãy gác việc của mình sang một bên, dù chỉ 2 phút, cùng chạy trốn dung nham và bước vào thế giới của bé. Đôi khi tuân theo luật chơi của trẻ là cách xả stress tốt nhất.', title_zh = '地板上的岩浆游戏 🌋', body_zh = '“地上是岩浆，快爬上沙发！”想象力把家变成了丛林。把手头的事放一放，哪怕只有2分钟，也一起躲岩浆、走进宝宝的世界吧。有时候，听从孩子的规则就是最好的解压方式。' WHERE id = 'd547337a-f6dc-44bb-a0b7-19904928148b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los secretos del cubo de la basura 🗑️', body_es = '¿No juega con el juguete que le compraste en el súper, sino que se pasa el día abrazado al plástico de burbujas que lo envolvía? El cerebro infantil no quiere guiones hechos, quiere libertad. Apunta con orgullo estos momentos de creatividad tan peculiares en el Seguimiento del desarrollo.', title_fr = 'Les secrets de la poubelle 🗑️', body_fr = 'Il joue toute la journée non pas avec le jouet acheté au magasin, mais avec le papier bulle qui l''emballait ? Le cerveau de l''enfant n''aime pas les scénarios tout faits, il aime la liberté. Notez fièrement ces moments de créativité inhabituels dans le Suivi de développement.', title_hi = 'कूड़ेदान के राज़ 🗑️', body_hi = 'दुकान से लाया खिलौना नहीं, बल्कि उसके बबल रैप को गले लगाकर दिनभर खेलता है? बच्चे का दिमाग बनी-बनाई कहानियाँ नहीं, आज़ादी पसंद करता है। उसकी रचनात्मकता के इन अनोखे पलों को गर्व से ग्रोथ ट्रैकर में दर्ज कीजिए।', title_id = 'Rahasia di tempat sampah 🗑️', body_id = 'Ia memeluk dan memainkan seharian bukan mainan yang Anda beli, melainkan plastik gelembung pembungkusnya? Otak anak tidak suka skenario yang sudah jadi, ia suka kebebasan. Catat momen kreativitasnya yang tak biasa ini dengan bangga di Pelacak Perkembangan.', title_ja = 'ゴミ箱のなかのひみつ 🗑️', body_ja = '買ってきたおもちゃではなく、包んでいたプチプチを抱えて一日じゅう遊んでいる？子どもの脳は決まったシナリオより、自由が好きなんです。このユニークな創造の瞬間を、誇りをもって「発達トラッカー」に記録しましょう。', title_ko = '쓰레기통 속 비밀 🗑️', body_ko = '마트에서 산 장난감이 아니라 그걸 싼 뽁뽁이를 끌어안고 하루 종일 노나요? 아이의 뇌는 정해진 시나리오보다 자유를 좋아해요. 이 특별한 창의력의 순간을 성장 기록에 뿌듯하게 남겨 두세요.', title_nl = 'Geheimen uit de prullenbak 🗑️', body_nl = 'Speelt hij de hele dag niet met het speelgoed uit de winkel, maar knuffelt hij het noppenfolie waar het in zat? Een kinderbrein houdt niet van kant-en-klare scenario''s, het houdt van vrijheid. Leg deze bijzondere creatieve momenten vol trots vast in de Groeitracker.', title_pl = 'Tajemnice kosza na śmieci 🗑️', body_pl = 'Cały dzień przytula i bawi się nie zabawką kupioną w sklepie, tylko folią bąbelkową, w którą była zawinięta? Dziecięcy mózg nie lubi gotowych scenariuszy, kocha swobodę. Zapisz z dumą te niezwykłe chwile kreatywności w Śledzeniu rozwoju.', title_pt = 'Segredos do caixote do lixo 🗑️', body_pt = 'Não brinca com o brinquedo que comprou no supermercado, mas passa o dia abraçado ao plástico de bolhas em que vinha embrulhado? O cérebro da criança não gosta de guiões prontos, gosta de liberdade. Registe com orgulho no Registo de Crescimento estes momentos invulgares de criatividade.', title_sv = 'Hemligheterna i soptunnan 🗑️', body_sv = 'Leker barnet hela dagen med bubbelplasten som leksaken från affären var inslagen i, i stället för leksaken? Barnhjärnan gillar inte färdiga manus, den gillar frihet. Anteckna stolt barnets ovanliga kreativa stunder i Utvecklingsspåraren.', title_vi = 'Bí mật trong thùng rác 🗑️', body_vi = 'Bé không chơi món đồ chơi mới mua mà ôm khư khư tấm xốp bóng khí bọc nó cả ngày? Não trẻ không thích kịch bản có sẵn, mà thích sự tự do. Hãy tự hào ghi lại những khoảnh khắc sáng tạo khác thường này trong Theo dõi phát triển.', title_zh = '垃圾桶里的秘密 🗑️', body_zh = '从超市买回的玩具不玩，却抱着包装用的气泡膜玩了一整天？孩子的大脑不喜欢现成的剧本，喜欢自由。把这些不寻常的创造力时刻，骄傲地记在成长记录里吧。' WHERE id = '6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Momentos de paz por la tarde 🛀', body_es = 'Llevas todo el día con la cabeza a punto de estallar de tanto «¿por qué?». Mételo en una bañera con agua tibia y échale un poco de espuma. Tú siéntate al lado y concéntrate solo en el sonido del agua. Ese efecto magnético del agua se llevará su cabezonería y calmará tus nervios.', title_fr = 'Les moments paisibles du soir 🛀', body_fr = 'Toute la journée, les « pourquoi » vous ont fait gonfler la tête. Mettez-le dans un bain d''eau tiède avec un peu de mousse. Et vous, asseyez-vous à côté et concentrez-vous simplement sur le bruit de l''eau. L''effet magnétique de l''eau lavera son entêtement et apaisera vos nerfs.', title_hi = 'शाम के सुकून भरे पल 🛀', body_hi = 'दिनभर के ‘क्यों’ से आपका दिमाग भारी हो गया है। उसे गुनगुने पानी से भरे टब में बिठाइए, थोड़ा झाग डालिए। आप किनारे बैठकर बस पानी की आवाज़ पर ध्यान दीजिए। पानी का यह जादुई असर बच्चे की ज़िद भी धो देगा और आपकी नसों को भी शांत करेगा।', title_id = 'Momen damai di malam hari 🛀', body_id = 'Seharian otak Anda penuh dengan ''kenapa''. Masukkan ia ke bak berisi air hangat dan tambahkan sedikit busa. Anda duduk di samping dan cukup fokus pada suara air. Efek magnet air ini akan membasuh keras kepala anak sekaligus menenangkan saraf Anda.', title_ja = '夜のおだやかなひととき 🛀', body_ja = '一日じゅうの「なんで？」で頭がいっぱい。ぬるめのお湯をはった浴槽に入れて、泡を少し入れましょう。あなたはそばに座って、ただ水の音に集中して。お湯のふしぎな力が、子どものがんこさも、あなたの神経も、やさしくほぐしてくれます。', title_ko = '저녁의 평온한 순간 🛀', body_ko = '하루 종일 ''왜?'' 질문에 머리가 터질 것 같나요? 아이를 미지근한 물을 채운 욕조에 넣고 거품을 조금 풀어 주세요. 엄마는 옆에 앉아 물소리에만 집중하세요. 물의 마법 같은 효과가 아이의 고집도 씻어 내고 엄마의 신경도 가라앉혀 줄 거예요.', title_nl = 'Rustige avondmomenten 🛀', body_nl = 'Je hoofd zit de hele dag vol waaroms. Zet hem in een bad met lauw water en doe er wat schuim in. Ga zelf ernaast zitten en concentreer je alleen op het geluid van het water. Het magnetische effect van water spoelt zijn koppigheid weg en kalmeert ook jouw zenuwen.', title_pl = 'Spokojne wieczorne chwile 🛀', body_pl = 'Cały dzień „dlaczego” przegrzał ci mózg. Włóż go do wanny z ciepłą wodą i dodaj trochę piany. Sama usiądź obok i po prostu skup się na szumie wody. Magnetyczny efekt wody zmyje upór dziecka i ukoi twoje nerwy.', title_pt = 'Momentos de paz ao fim do dia 🛀', body_pt = 'Passou o dia com a cabeça a rebentar de "porquês". Ponha-o na banheira com água morna e junte um pouco de espuma. E a mãe senta-se ao lado e concentra-se apenas no som da água. O efeito magnético da água vai levar a teimosia da criança e acalmar também os seus nervos.', title_sv = 'Lugna kvällsstunder 🛀', body_sv = 'Hela dagen har alla ”varför” fått huvudet att svälla. Lägg barnet i ett badkar med ljummet vatten och lite skum. Sätt dig bredvid och fokusera bara på vattnets ljud. Vattnets magnetiska effekt sköljer bort barnets envishet och lugnar dina nerver.', title_vi = 'Những phút bình yên buổi tối 🛀', body_vi = 'Cả ngày bị "tại sao" dội vào làm đầu mẹ căng ra. Hãy cho bé vào bồn nước ấm, thả thêm chút bọt. Còn mẹ ngồi bên cạnh và chỉ tập trung vào tiếng nước. Sức hút kỳ diệu của nước sẽ vừa cuốn trôi sự bướng bỉnh của bé, vừa làm dịu thần kinh của mẹ.', title_zh = '傍晚的宁静时光 🛀', body_zh = '一整天的“为什么”让你脑袋发胀。把宝宝放进装满温水的浴缸，加点泡泡。你就坐在旁边，专心听水声。水的“魔力”既能冲走宝宝的倔强，也能让你的神经平静下来。' WHERE id = '7fe2513f-2da9-40be-8ba2-3f77c91758aa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No me escuchas! 😤', body_es = 'Te dice «¡Escúchame!» y te gira la cara hacia él con las manos. No te pide tu presencia física, sino el 100% de tu cabeza. Deja el móvil o lo que estés haciendo solo 3 minutos y escúchalo mirándolo a los ojos. Así evitas horas de lloriqueos.', title_fr = 'Tu ne m''écoutes pas ! 😤', body_fr = '« Écoute-moi ! » dit-il en tournant votre visage vers lui avec ses mains. Ce n''est pas votre présence physique qu''il réclame, mais votre cerveau à 100 % avec lui. Lâchez votre téléphone ou ce que vous faites pendant 3 minutes seulement et écoutez-le en le regardant dans les yeux. Cela évite des heures de pleurnicheries.', title_hi = 'तुम मेरी बात नहीं सुन रहीं! 😤', body_hi = '‘मेरी बात सुनो!’ कहकर अपने हाथों से आपका चेहरा अपनी ओर घुमाता है। उसे आपकी मौजूदगी नहीं, आपका 100% ध्यान चाहिए। फ़ोन या हाथ का काम सिर्फ़ 3 मिनट के लिए छोड़कर, पूरी आँखों में आँखें डालकर उसे सुनिए। इससे घंटों चलने वाली ठुनठुनाहट रुक जाती है।', title_id = 'Mama nggak dengar aku! 😤', body_id = '''Dengarkan aku!'' katanya sambil memutar wajah Anda ke arahnya dengan kedua tangan. Ia tidak menuntut kehadiran fisik Anda, tapi otak Anda 100% tertuju padanya. Letakkan ponsel atau pekerjaan Anda selama 3 menit saja dan dengarkan ia dengan kontak mata penuh. Ini mencegah rengekan yang bisa berlangsung berjam-jam.', title_ja = '聞いてないでしょ！ 😤', body_ja = '「聞いて！」と言って、両手であなたの顔を自分のほうに向ける？体がそこにあるだけでなく、頭が100%自分に向いていることを求めているんです。スマホや手もとの作業をたった3分だけ置いて、しっかり目を合わせて話を聞いてあげて。何時間も続くぐずぐずを防げます。', title_ko = '엄마는 내 말 안 듣잖아! 😤', body_ko = '''내 말 들어!'' 하며 두 손으로 엄마 얼굴을 자기 쪽으로 돌리나요? 몸이 곁에 있는 게 아니라 엄마의 머리가 100% 자기에게 있기를 원하는 거예요. 휴대폰이나 하던 일을 딱 3분만 내려놓고 눈을 맞추며 들어 주세요. 몇 시간씩 이어질 칭얼거림을 막아 줘요.', title_nl = 'Je luistert niet naar me! 😤', body_nl = 'Zegt hij ''Luister naar me!'' en draait hij met zijn handjes je gezicht naar zich toe? Hij wil niet alleen dat je er lichamelijk bent, maar dat je hoofd 100% bij hem is. Leg je telefoon of je bezigheid maar 3 minuten weg en luister met volledig oogcontact. Zo voorkom je uren gezeur.', title_pl = 'Ty mnie nie słuchasz! 😤', body_pl = 'Mówi „Posłuchaj mnie!” i rączkami odwraca twoją twarz w swoją stronę. Nie chodzi mu o twoją fizyczną obecność, ale o to, by twój mózg był w 100% przy nim. Odłóż telefon albo to, co robisz, choćby na 3 minuty i wysłuchaj go, patrząc mu w oczy. To zapobiega marudzeniu, które trwałoby godzinami.', title_pt = 'Não me estás a ouvir! 😤', body_pt = 'Diz "Ouve-me!" e vira-lhe a cara para ele com as mãos. Não quer só a sua presença física, quer o seu cérebro 100% nele. Largue o telemóvel ou o que tem nas mãos por apenas 3 minutos e ouça-o com total contacto visual. Isto evita horas de choramingos.', title_sv = 'Du hör inte vad jag säger! 😤', body_sv = '”Lyssna på mig!” säger barnet och vänder ditt ansikte mot sig med händerna. Hen kräver inte din fysiska närvaro, utan att hela din hjärna är hos hen till 100 %. Släpp telefonen eller det du håller på med i bara 3 minuter och lyssna med full ögonkontakt. Det förhindrar gnäll som annars kan pågå i timmar.', title_vi = 'Mẹ không nghe con nói! 😤', body_vi = 'Bé nói "Mẹ nghe con này!" rồi lấy tay xoay mặt mẹ về phía mình. Bé không chỉ đòi mẹ có mặt, mà đòi 100% tâm trí mẹ dành cho bé. Hãy bỏ điện thoại hay việc đang làm chỉ 3 phút và lắng nghe bé với ánh mắt trọn vẹn. Điều này giúp tránh được hàng giờ mè nheo.', title_zh = '你没在听我说话！😤', body_zh = '说着“听我说！”，用小手把你的脸转向自己？宝宝要的不只是你在身边，而是你的大脑100%在宝宝身上。把手机或手头的事放下3分钟，看着宝宝的眼睛认真听。这能避免接下来几个小时的哼哼唧唧。' WHERE id = 'e5f2539f-4aa6-4c0d-ad49-b97d6f90a867' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filosofía de medianoche 🦉', body_es = 'Justo al meterse en la cama te hace preguntas profundas como «Mamá, ¿por qué las nubes no se caen?». El objetivo no es aprender ciencia, sino hablar contigo y retrasar el sueño. Dale una respuesta corta e inventada como «Porque arriba están durmiendo», pon la melodía suave de Cuentos inteligentes y asegura con decisión el silencio de la hora de dormir.', title_fr = 'Philosophie de minuit 🦉', body_fr = 'Juste au moment de se coucher, il pose des questions profondes comme « Maman, pourquoi les nuages ne tombent pas ? ». Le but n''est pas d''apprendre la science, mais de discuter avec vous pour retarder le sommeil. Donnez une réponse courte et inventée comme « Parce qu''ils dorment là-haut », mettez la douce mélodie des Contes intelligents et imposez fermement le silence du coucher.', title_hi = 'आधी रात का फ़लसफ़ा 🦉', body_hi = 'ठीक बिस्तर पर जाते समय ‘माँ, बादल नीचे क्यों नहीं गिरते?’ जैसे गहरे सवाल पूछता है? मकसद विज्ञान सीखना नहीं, आपसे बात करके नींद टालना है। ‘क्योंकि वे ऊपर सो रहे हैं’ जैसा छोटा, मनगढ़ंत जवाब दीजिए और स्मार्ट कहानियों की धीमी धुन लगाकर पक्के इरादे से नींद वाली शांति बनाइए।', title_id = 'Filsafat tengah malam 🦉', body_id = 'Tepat saat naik ke tempat tidur, ia bertanya hal-hal mendalam seperti ''Ma, kenapa awan tidak jatuh ke bawah?'' Tujuannya bukan belajar sains, tapi mengobrol dengan Anda dan menunda tidur. Beri jawaban singkat karangan seperti ''Karena mereka tidur di atas'', putar melodi lembut dari Dongeng Pintar, dan pastikan keheningan tidur dengan tegas.', title_ja = '真夜中の哲学 🦉', body_ja = 'ベッドに入ったとたん「ママ、雲はなんで落ちてこないの？」と深い質問。目的は科学を学ぶことではなく、あなたと話して寝る時間を遅らせること。「上で寝ているからだよ」と短いつくり話で答えて、「スマートおはなし」のやさしいメロディーを流し、静かな眠りの時間をしっかり守りましょう。', title_ko = '한밤중의 철학 🦉', body_ko = '침대에 눕자마자 ''엄마, 구름은 왜 안 떨어져?'' 같은 깊은 질문을 하나요? 과학을 배우려는 게 아니라 엄마와 이야기하며 잠을 미루려는 거예요. ''위에서 자고 있으니까''처럼 짧게 지어낸 답을 하고, 스마트 동화의 잔잔한 멜로디를 틀어 단호하게 잠자리의 고요를 지키세요.', title_nl = 'Middernachtfilosofie 🦉', body_nl = 'Net als hij in bed ligt, stelt hij diepe vragen als ''Mama, waarom vallen wolken niet naar beneden?'' Het doel is niet wetenschap leren, maar met je praten en het slapen uitstellen. Geef een kort, verzonnen antwoord als ''Omdat ze daarboven slapen'' en zorg met een rustig melodietje uit Slimme sprookjes vastberaden voor slaapstilte.', title_pl = 'Filozofia o północy 🦉', body_pl = 'Gdy tylko kładzie się do łóżka, zadaje głębokie pytania w stylu „Mamo, czemu chmury nie spadają?”. Nie chodzi mu o naukę, tylko o rozmowę z tobą i odwleczenie snu. Odpowiedz krótko i z wyobraźnią: „Bo tam na górze śpią”, włącz łagodną melodię z Mądrych bajek i stanowczo zadbaj o senną ciszę.', title_pt = 'Filosofia da meia-noite 🦉', body_pt = 'Mal se deita, faz perguntas profundas como "Mãe, porque é que as nuvens não caem?". O objetivo não é aprender ciência, é falar consigo e adiar o sono. Dê uma resposta curta e inventada como "porque estão a dormir lá em cima", ponha a melodia suave das Histórias Inteligentes e garanta com firmeza o silêncio do sono.', title_sv = 'Midnattsfilosofi 🦉', body_sv = 'Precis när barnet kryper ner i sängen kommer djupa frågor som ”Mamma, varför ramlar inte molnen ner?” Målet är inte att lära sig vetenskap, utan att prata med dig och skjuta upp sömnen. Ge ett kort, påhittat svar som ”För att de sover där uppe”, sätt på den milda melodin i Smarta sagor och säkra lugnet inför sömnen.', title_vi = 'Triết lý lúc nửa đêm 🦉', body_vi = 'Vừa lên giường, bé đã hỏi những câu sâu sắc như "Mẹ ơi, sao mây không rơi xuống?" Mục đích không phải học khoa học, mà là nói chuyện với mẹ để trì hoãn giấc ngủ. Hãy trả lời ngắn gọn, tưởng tượng như "Vì mây đang ngủ trên đó", rồi bật giai điệu êm dịu trong Truyện cổ tích thông minh để dứt khoát mang lại sự yên tĩnh cho giấc ngủ.', title_zh = '半夜的哲学课 🦉', body_zh = '一上床就问“妈妈，云为什么不掉下来？”这样的深奥问题？目的不是学科学，而是和你聊天、拖延睡觉。给个简短的小故事式回答：“因为它们在天上睡觉呢。”再打开智慧童话里的轻柔旋律，坚定地守住睡前的安静。' WHERE id = '0da92da6-227b-4bc4-8733-939d83f883ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esa pregunta que te deja de piedra en el súper 😳', body_es = '¿En la cola de la caja ha preguntado en voz alta «¿Por qué esta señora tiene el pelo así?»? No lo avergüences ni lo mandes callar: lleva enseguida su atención a la Lista de la compra de la app con un «A ver, ¿hemos cogido las manzanas?» y sal de la situación con diplomacia.', title_fr = 'Cette question choc au supermarché 😳', body_fr = 'Dans la file d''attente à la caisse, il a demandé à voix haute « Pourquoi la dame a les cheveux comme ça ? » ? Ne lui faites pas honte pour le faire taire, détournez aussitôt son attention vers la Liste de courses de l''application : « Voyons, on a bien pris les pommes ? », et sortez-vous-en avec diplomatie.', title_hi = 'सुपरमार्केट में वह चौंकाने वाला सवाल 😳', body_hi = 'काउंटर की लाइन में खड़े-खड़े ज़ोर से पूछ लिया, ‘इन आंटी के बाल ऐसे क्यों हैं?’ उसे शर्मिंदा करके चुप मत कराइए, उसका ध्यान तुरंत ऐप की शॉपिंग लिस्ट पर ले जाइए: ‘चलो देखें, हमने सेब ले लिए क्या?’ कहकर कूटनीति से हालात से निकल आइए।', title_id = 'Pertanyaan mengejutkan di supermarket 😳', body_id = 'Saat antre di kasir, ia bertanya keras-keras ''Kenapa rambut tante ini begitu?'' Jangan mempermalukan dan membungkamnya, segera alihkan perhatiannya ke Daftar Belanja di aplikasi: ''Coba kita lihat, apelnya sudah kita beli belum?'' dan keluarlah dari situasi itu secara diplomatis.', title_ja = 'スーパーでのドキッとする質問 😳', body_ja = 'レジに並んでいるとき、大きな声で「このおばさんの髪、なんでこうなの？」と聞いた？叱って黙らせるのではなく、すぐにアプリの「買い物リスト」に注意を向けて「りんごはもう買ったかな？」と言い、上手にその場を切りぬけましょう。', title_ko = '마트에서의 충격 질문 😳', body_ko = '계산대 줄에서 큰 소리로 ''이 아줌마 머리는 왜 이래?''라고 물었나요? 창피를 주며 입을 막지 말고, 바로 앱의 쇼핑 목록으로 관심을 돌리세요. ''우리 사과 샀나 볼까?'' 하며 외교적으로 상황을 빠져나가세요.', title_nl = 'Die schokkende vraag in de supermarkt 😳', body_nl = 'Vroeg hij in de rij bij de kassa luid: ''Waarom ziet het haar van die mevrouw er zo uit?'' Schaam hem niet en snoer hem niet de mond, maar leid zijn aandacht meteen naar het Boodschappenlijstje in de app: ''Even kijken, hebben we de appels al?'' en draai je er diplomatiek uit.', title_pl = 'To szokujące pytanie w sklepie 😳', body_pl = 'Stojąc w kolejce do kasy, głośno zapytał: „Czemu ta pani ma takie włosy?”. Nie zawstydzaj go i nie uciszaj, od razu skieruj jego uwagę na Listę zakupów w aplikacji: „Sprawdźmy, czy kupiliśmy jabłka?” i dyplomatycznie wyjdź z sytuacji.', title_pt = 'Aquela pergunta chocante no supermercado 😳', body_pt = 'Na fila da caixa, perguntou bem alto: "Porque é que o cabelo daquela senhora é assim?" Não o envergonhe nem o mande calar: desvie logo a atenção dele para a Lista de Compras da app, "Vamos ver se já comprámos as maçãs?", e saia da situação com diplomacia.', title_sv = 'Den chockerande frågan i affären 😳', body_sv = 'Frågade barnet högt i kassakön: ”Varför ser tantens hår ut så där?” Skäm inte ut barnet och tysta inte ner hen, led genast om uppmärksamheten till Inköpslistan i appen: ”Ska vi se om vi har köpt äpplen?” och ta dig diplomatiskt ur situationen.', title_vi = 'Câu hỏi "sốc" ở siêu thị 😳', body_vi = 'Đang xếp hàng thanh toán, bé hỏi to: "Sao tóc cô này lại như thế?" Đừng làm bé xấu hổ hay bắt bé im, hãy chuyển ngay sự chú ý của bé sang Danh sách mua sắm trong ứng dụng: "Xem nào, mình đã mua táo chưa nhỉ?" và khéo léo thoát khỏi tình huống.', title_zh = '超市里那个让人震惊的问题 😳', body_zh = '排队结账时，大声问“这个阿姨的头发为什么是这样的？”别羞辱宝宝、也别让宝宝闭嘴，马上把注意力转到应用里的购物清单上：“我们看看苹果买了没有？”巧妙地化解尴尬吧。' WHERE id = '1b4bdd7d-042a-4be6-a59f-82892d67ff8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡¿Por qué has lavado esa camiseta?! 👕', body_es = '¿Se ha declarado luto en casa porque has metido en la lavadora su camiseta favorita y ya desteñida? El apego de los niños a las cosas a veces supera la lógica. No discutas: abre enseguida la Sesión de fotos del bebé, hazle una foto con ese enfado y conviértelo en risa. El truco «A ver qué cara de enfado pones en la pantalla» desvía su atención al instante. ¡Pruébalo!', title_fr = 'Pourquoi tu as lavé ce t-shirt ?! 👕', body_fr = 'C''est le deuil à la maison parce que vous avez mis à la machine son t-shirt préféré tout délavé ? L''attachement des enfants aux objets dépasse parfois la logique. Ne discutez pas, ouvrez vite la Séance photo bébé, photographiez-le avec sa mine fâchée et transformez ça en rire. L''astuce « Viens, on regarde comme tu as l''air fâché à l''écran » détourne aussitôt son attention, essayez !', title_hi = 'वह कमीज़ क्यों धुली?! 👕', body_hi = 'प्यारी, फीकी पड़ चुकी कमीज़ आपने वॉशिंग मशीन में डाल दी, इसलिए घर में मातम छा गया? चीज़ों से बच्चों का लगाव कभी-कभी तर्क से परे होता है। बहस मत कीजिए, फ़ौरन बेबी फ़ोटोशूट खोलिए, उसकी इसी नाराज़ हालत की फ़ोटो लेकर हँसी में बदल दीजिए। ‘चलो देखें, स्क्रीन पर तुम कितने गुस्से में दिखते हो’ वाली तरकीब ध्यान तुरंत भटका देती है, आज़माइए!', title_id = 'Kenapa baju itu dicuci?! 👕', body_id = 'Rumah berkabung karena Anda memasukkan baju kesayangannya yang sudah pudar itu ke mesin cuci? Keterikatan anak pada barang kadang melampaui logika. Jangan berdebat, segera buka Pemotretan Bayi, foto ekspresi kesalnya itu dan ubah jadi tawa. Trik ''Yuk lihat betapa marahnya kamu di layar'' langsung memecah perhatiannya, coba saja!', title_ja = 'なんであのシャツ洗ったの？！ 👕', body_ja = 'お気に入りで色あせたシャツを洗濯機に入れたら、家じゅうが喪に服したような騒ぎ？子どものものへの愛着は、ときに理屈をこえます。言い合いはせず、すぐに「ベビーフォトセッション」を開いて、怒った顔を撮って笑いに変えましょう。「画面でどんなに怒って見えるか見てみよう」作戦は、すぐに気をそらしてくれます。ためしてみて！', title_ko = '그 티셔츠를 왜 빨았어?! 👕', body_ko = '아끼던, 이미 색이 바랜 티셔츠를 세탁기에 넣었다고 집에 초상이 났나요? 아이들의 물건 사랑은 가끔 논리를 넘어서요. 다투지 말고 바로 아기 사진 촬영을 열어 화난 모습을 찍어 웃음으로 바꿔 보세요. ''화면에서 얼마나 화나 보이는지 볼까?'' 작전은 관심을 순식간에 돌려줘요. 해 보세요!', title_nl = 'Waarom is dat shirt gewassen?! 👕', body_nl = 'Is er rouw afgekondigd in huis omdat je dat geliefde, verbleekte shirt in de wasmachine deed? De band van kinderen met spullen gaat soms elke logica te boven. Ga niet in discussie, open meteen de Babyfotoshoot, maak een foto van zijn boze gezicht en maak er een lach van. Het trucje ''Kom, eens kijken hoe boos je eruitziet op het scherm'' leidt hem meteen af, probeer het!', title_pl = 'Czemu ta koszulka została wyprana?! 👕', body_pl = 'W domu ogłoszono żałobę, bo wrzuciłaś do pralki ulubioną, już wyblakłą koszulkę? Przywiązanie dzieci do rzeczy czasem przerasta logikę. Nie kłóć się, od razu otwórz Sesję zdjęciową dziecka, zrób mu zdjęcie w tym złym humorze i zamień to w śmiech. Sztuczka „Zobaczmy, jak groźnie wyglądasz na ekranie” od razu odwraca uwagę, sprawdź!', title_pt = 'Porque é que lavaram aquela camisola?! 👕', body_pt = 'Declarou-se luto em casa porque pôs na máquina aquela camisola preferida e já desbotada? O apego das crianças às coisas às vezes ultrapassa a lógica. Não discuta: abra já a Sessão Fotográfica do Bebé, fotografe-o assim zangado e transforme tudo em riso. O truque "Vamos ver que cara zangada fazes no ecrã" desvia logo a atenção, experimente!', title_sv = 'Varför tvättades den tröjan?! 👕', body_sv = 'Har det utlysts sorg hemma för att du lade den urblekta favorittröjan i tvättmaskinen? Barns band till saker går ibland bortom all logik. Bråka inte, öppna genast Babyfotografering, fotografera barnet i det arga humöret och gör det till skratt. Tricket ”Kom, vi ser hur arg du ser ut på skärmen” skingrar uppmärksamheten direkt, prova!', title_vi = 'Sao lại giặt cái áo đó?! 👕', body_vi = 'Cả nhà như có tang chỉ vì mẹ bỏ chiếc áo yêu thích, đã bạc màu của bé vào máy giặt? Sự gắn bó của trẻ với đồ vật đôi khi vượt qua mọi logic. Đừng tranh cãi, mở ngay Chụp ảnh cho bé, chụp lại vẻ mặt giận dỗi ấy và biến nó thành tiếng cười. Mẹo "Xem trên màn hình con giận trông thế nào nào" sẽ đánh lạc hướng bé ngay, thử xem!', title_zh = '那件衣服为什么洗了？！👕', body_zh = '你把那件心爱又褪了色的衣服扔进洗衣机，家里就“办起了丧事”？孩子对物品的依恋有时超越逻辑。别争了，马上打开宝宝写真，把宝宝生气的样子拍下来，变成笑点。“来看看你在屏幕上生气是什么样子”这一招能立刻转移注意力，试试吧！' WHERE id = '62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga las luces, que empieza el teatro de sombras 🐰', body_es = '¿Le da miedo la oscuridad y no quiere salir solo al pasillo? Apaga del todo las luces de la habitación y enciende una linternita. Haz con las manos sombras de perros y pájaros en la pared y convierte la oscuridad de un sitio que da miedo en un parque de juegos. Se dormirá en un momento.', title_fr = 'Lumières éteintes, que le théâtre d''ombres commence 🐰', body_fr = 'Il a peur du noir et ne veut pas aller seul dans le couloir ? Éteignez complètement la lumière de la pièce et allumez une petite lampe de poche. Créez avec vos mains des ombres de chien et d''oiseau sur le mur, et transformez le noir, de lieu effrayant, en terrain de jeu. Il s''endormira en un instant.', title_hi = 'लाइटें बंद, परछाईं का थिएटर शुरू 🐰', body_hi = 'अंधेरे से डरता है और गलियारे में अकेले नहीं जाना चाहता? कमरे की लाइटें पूरी बंद करके एक छोटी टॉर्च जलाइए। दीवार पर हाथों से कुत्ते, चिड़िया की परछाइयाँ बनाकर अंधेरे को डरावनी जगह से खेल के मैदान में बदल दीजिए। उसे नींद आने में बस कुछ ही पल लगेंगे।', title_id = 'Matikan lampu, teater bayangan dimulai 🐰', body_id = 'Ia takut gelap dan tidak mau ke lorong sendirian? Matikan semua lampu kamar dan nyalakan senter kecil. Buat bayangan anjing dan burung dengan tangan Anda di dinding, ubah gelap dari tempat menakutkan menjadi taman bermain baginya. Ia akan tertidur dalam sekejap.', title_ja = '明かりを消して、影絵劇場の始まり 🐰', body_ja = '暗いのがこわくて、ひとりで廊下に出たがらない？部屋の明かりを全部消して、小さな懐中電灯をつけましょう。壁に手で犬や鳥の影をつくって、暗やみをこわい場所から遊び場に変えてあげて。眠りにつくのはもうすぐです。', title_ko = '불을 끄고 그림자 극장 시작 🐰', body_ko = '어둠이 무서워 혼자 복도에 나가기 싫어하나요? 방 불을 다 끄고 작은 손전등을 켜세요. 벽에 손으로 강아지와 새 그림자를 만들어 어둠을 무서운 곳에서 놀이터로 바꿔 주세요. 잠드는 건 시간문제예요.', title_nl = 'Licht uit, het schaduwtheater begint 🐰', body_nl = 'Is hij bang in het donker en wil hij niet alleen de gang op? Doe al het licht in de kamer uit en zet een klein zaklampje aan. Maak met je handen schaduwen van hondjes en vogels op de muur en verander het donker van een enge plek in een speelplaats. Hij valt zo in slaap.', title_pl = 'Zgaś światło, czas na teatr cieni 🐰', body_pl = 'Boi się ciemności i nie chce sam wyjść na korytarz? Zgaś całkiem światło w pokoju i zapal małą latarkę. Rękami twórz na ścianie cienie pieska i ptaszka, a straszną ciemność zamień dla niego w plac zabaw. Zaśnie w mgnieniu oka.', title_pt = 'Luzes apagadas, começa o teatro de sombras 🐰', body_pt = 'Tem medo do escuro e não quer ir sozinho ao corredor? Apague todas as luzes do quarto e acenda uma pequena lanterna. Faça com as mãos sombras de cães e pássaros na parede e transforme o escuro, de um sítio assustador, num recreio. Adormecer vai ser questão de instantes.', title_sv = 'Släck lamporna, skuggteatern börjar 🐰', body_sv = 'Är barnet rädd för mörkret och vill inte gå ut i hallen ensam? Släck alla lampor i rummet och tänd en liten ficklampa. Gör skuggor av hundar och fåglar med händerna på väggen och förvandla mörkret från en läskig plats till en lekplats. Barnet somnar på nolltid.', title_vi = 'Tắt đèn, kịch bóng bắt đầu 🐰', body_vi = 'Bé sợ bóng tối và không dám ra hành lang một mình? Hãy tắt hết đèn trong phòng và bật một chiếc đèn pin nhỏ. Dùng tay tạo bóng chó, bóng chim trên tường, biến bóng tối từ nơi đáng sợ thành sân chơi của bé. Bé sẽ ngủ chỉ trong chốc lát.', title_zh = '关灯，影子剧场开演 🐰', body_zh = '怕黑，不敢一个人去走廊？把房间的灯全关掉，打开一支小手电筒。用手在墙上做出小狗、小鸟的影子，把黑暗从可怕的地方变成游乐场。宝宝很快就会睡着。' WHERE id = '4e937fd6-67f9-496a-b0c5-be8bf0840c6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas desconectar ☕', body_es = '¿Está tan metido jugando con sus juguetes en la habitación que de repente hay silencio en casa? ¡Ay, cariño, no gastes ese momento en barrer ni en doblar ropa! Túmbate en el sofá, escribe solo 5 minutos de paz en el Diario de ánimo y tómate el café bien caliente. Tú también eres persona en esta casa.', title_fr = 'Vous aussi, vous avez besoin d''être hors ligne ☕', body_fr = 'Il joue si profondément avec ses jouets dans sa chambre qu''un silence soudain s''est abattu sur la maison ? Ma chérie, ne gaspillez pas ce moment à balayer ou à plier du linge ! Allez vous allonger sur le canapé, écrivez juste 5 minutes de paix dans le Journal d''humeur et buvez votre café bien chaud. Vous aussi, vous faites partie de cette maison.', title_hi = 'आपको भी ऑफ़लाइन होना चाहिए ☕', body_hi = 'कमरे में खिलौनों से इतनी गहराई से खेल रहा है कि घर में अचानक सन्नाटा छा गया? मेरी जान, वह पल झाड़ू लगाने या कपड़े तह करने में मत गँवाइए! सोफ़े पर लेट जाइए, मूड डायरी में बस 5 मिनट की शांति लिखिए और कॉफ़ी गरमा-गरम पीजिए। आप भी इस घर की इंसान हैं।', title_id = 'Anda juga perlu offline ☕', body_id = 'Ia begitu asyik bermain di kamar sampai rumah tiba-tiba hening? Aduh sayang, jangan habiskan momen itu untuk menyapu atau melipat baju! Berbaringlah di sofa, tulis 5 menit kedamaian di Buku Harian Suasana Hati, dan minum kopi selagi panas. Anda juga penghuni rumah ini.', title_ja = 'あなたにもオフラインが必要 ☕', body_ja = 'おもちゃに夢中で、家が急に静かになった？その時間を掃除や洗濯物たたみに使わないで！ソファに横になって、「気分日記」に5分間の平和をひと言書き、コーヒーを温かいうちに飲みましょう。あなたもこの家の大切な一員です。', title_ko = '엄마도 오프라인이 필요해요 ☕', body_ko = '방에서 장난감에 푹 빠져 집이 갑자기 조용해졌나요? 그 순간을 청소나 빨래 개기에 쓰지 마세요! 소파에 누워 기분 일기에 5분의 평화를 적고 커피를 따뜻할 때 마시세요. 엄마도 이 집의 사람이에요.', title_nl = 'Jij moet ook even offline ☕', body_nl = 'Speelt hij zo verdiept met zijn speelgoed dat het ineens stil is in huis? Besteed dat moment alsjeblieft niet aan stofzuigen of de was opvouwen! Ga op de bank liggen, schrijf in je Stemmingsdagboek gewoon 5 minuten vrede op en drink je koffie lekker warm. Jij woont hier ook.', title_pl = 'Ty też potrzebujesz trybu offline ☕', body_pl = 'Tak bardzo pochłonęła go zabawa w pokoju, że w domu nagle zapadła cisza? Błagam, nie wydawaj tej chwili na zamiatanie ani składanie ubrań! Połóż się na kanapie, zapisz w Dzienniku nastroju tylko 5 minut spokoju i wypij kawę, póki gorąca. Ty też jesteś domownikiem.', title_pt = 'A mãe também precisa de ficar offline ☕', body_pt = 'Está tão concentrado a brincar com os brinquedos no quarto que caiu de repente o silêncio em casa? Por favor, não gaste esse momento a varrer a casa ou a dobrar roupa! Vá deitar-se no sofá, escreva no Diário de Humor só 5 minutos de paz e beba o café ainda quente. A mãe também é gente desta casa.', title_sv = 'Du behöver också vara offline ☕', body_sv = 'Leker barnet så djupt med leksakerna i rummet att det plötsligt har blivit tyst hemma? Älskade du, lägg inte den stunden på att dammsuga eller vika tvätt! Gå och lägg dig i soffan, skriv bara 5 minuter av frid i Humördagboken och drick kaffet medan det är varmt. Du är också en människa i det här hemmet.', title_vi = 'Mẹ cũng cần "offline" ☕', body_vi = 'Bé mải chơi đồ chơi trong phòng đến mức nhà bỗng yên ắng? Mẹ ơi, đừng dành khoảnh khắc ấy để quét nhà hay gấp quần áo! Hãy nằm dài trên sofa, viết vào Nhật ký tâm trạng chỉ 5 phút bình yên và uống cà phê lúc còn nóng. Mẹ cũng là một thành viên của ngôi nhà này.', title_zh = '你也需要离线一下 ☕', body_zh = '宝宝在房间里玩玩具玩得入迷，家里突然安静了？亲爱的，别把这一刻花在扫地或叠衣服上！去沙发上躺一躺，在心情日记里写下5分钟的平静，趁热喝杯咖啡。你也是这个家的一员。' WHERE id = '6d8c96e4-6f09-4805-a4a8-4acf034ab6c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No he sido yo, ha sido mi osito! 🧸', body_es = '¿Tira el agua al suelo a propósito y le echa la culpa a su juguete? No miente, solo ha descubierto el mecanismo de defensa de los 3,5 años. No te pongas cabezota: dile «Entonces vamos a enseñarle a tu osito cómo se limpia» y dale el trapo. Aprenderá responsabilidad sin que su ego salga herido.', title_fr = 'C''est pas moi qui ai mis le bazar, c''est mon nounours ! 🧸', body_fr = 'Il renverse l''eau exprès et rejette la faute sur son jouet ? Il ne ment pas, il découvre simplement le mécanisme de défense des 3 ans et demi. Ne vous entêtez pas, dites : « Alors viens, on va apprendre à ton nounours comment on nettoie » et mettez-lui le chiffon dans la main. Il apprendra la responsabilité sans que son ego soit blessé.', title_hi = 'मैंने नहीं बिखेरा, मेरे भालू ने किया! 🧸', body_hi = 'जानबूझकर पानी फ़र्श पर गिराकर इल्ज़ाम अपने खिलौने पर डालता है? वह झूठ नहीं बोल रहा, बस 3.5 साल वाले बचाव के तरीके की खोज की है। ज़िद मत कीजिए, कहिए, ‘तो चलो अपने भालू को सिखाते हैं कि सफ़ाई कैसे करते हैं’ और कपड़ा उसके हाथ में दे दीजिए। वह ज़िम्मेदारी भी सीखेगा और उसके अहं को ठेस भी नहीं लगेगी।', title_id = 'Bukan aku yang berantakin, beruangku! 🧸', body_id = 'Ia sengaja menumpahkan air ke lantai lalu menyalahkan mainannya? Ia tidak berbohong, ia baru menemukan mekanisme perlindungan diri usia 3,5 tahun. Jangan beradu keras kepala, katakan ''Kalau begitu, ayo ajari beruangmu cara membersihkannya'' dan berikan lap ke tangannya. Ia belajar tanggung jawab, egonya pun tidak terluka.', title_ja = '散らかしたのはぼくじゃない、くまさんだよ！ 🧸', body_ja = 'わざとお水を床にこぼして、おもちゃのくまさんのせいにする？うそをついているのではなく、3歳半の自分を守る仕組みを発見しただけです。言い合いはせず、「じゃあ、くまさんに拭き方を教えてあげよう」と言ってタオルを渡しましょう。責任を学べて、プライドも傷つきません。', title_ko = '내가 어지른 거 아니야, 곰돌이가 그랬어! 🧸', body_ko = '일부러 물을 쏟아 놓고 장난감 탓을 하나요? 거짓말이 아니라 3.5세의 방어 기제를 발견한 거예요. 고집 싸움하지 말고 ''그럼 곰돌이한테 어떻게 닦는지 가르쳐 주자'' 하며 행주를 손에 쥐여 주세요. 책임감도 배우고 자존심도 다치지 않아요.', title_nl = 'Ik heb het niet gedaan, mijn beer! 🧸', body_nl = 'Gooit hij expres water op de grond en geeft hij zijn knuffel de schuld? Hij liegt niet, hij heeft gewoon het verdedigingsmechanisme van een 3,5-jarige ontdekt. Ga niet in de clinch, zeg: ''Kom, dan leren we je beer hoe je opruimt'' en geef hem een doekje. Zo leert hij verantwoordelijkheid en blijft zijn ego heel.', title_pl = 'To nie ja, to mój miś! 🧸', body_pl = 'Celowo wylał wodę na podłogę i zwala winę na zabawkę? On nie kłamie, po prostu odkrył mechanizm obronny 3,5-latka. Nie upieraj się, powiedz: „To nauczmy misia, jak się sprząta” i daj mu ściereczkę do ręki. Nauczy się odpowiedzialności, a jego ego nie ucierpi.', title_pt = 'Não fui eu que desarrumei, foi o meu urso! 🧸', body_pt = 'Entornou a água de propósito e pôs a culpa no brinquedo? Não está a mentir, só descobriu o mecanismo de defesa dos 3,5 anos. Não teime. Diga "Então vamos ensinar o teu urso a limpar" e dê-lhe o pano. Aprende a responsabilidade e o ego dele não sai ferido.', title_sv = 'Det var inte jag som stökade, det var nallen! 🧸', body_sv = 'Spiller barnet vatten på golvet med flit och skyller på leksaken? Hen ljuger inte, hen har bara upptäckt 3,5-åringens försvarsmekanism. Tjafsa inte, säg ”Då lär vi nallen hur man torkar upp” och ge barnet trasan. Hen lär sig ansvar, och självkänslan tar ingen skada.', title_vi = 'Con không làm đổ, gấu bông làm đấy! 🧸', body_vi = 'Bé cố tình làm đổ nước rồi đổ lỗi cho đồ chơi? Bé không nói dối, chỉ là đã khám phá ra cơ chế tự vệ của tuổi 3,5. Đừng giằng co, hãy nói: "Vậy mình cùng dạy gấu bông cách lau nhé" và đưa khăn cho bé. Bé vừa học được trách nhiệm, vừa không bị tổn thương cái tôi.', title_zh = '不是我弄乱的，是小熊干的！🧸', body_zh = '故意把水洒在地上，却把责任推给玩具？宝宝不是在撒谎，只是发现了3岁半的自我保护机制。别较劲，说“那我们来教小熊怎么擦干净吧”，把毛巾递到宝宝手里。既学会了责任，自尊心也不会受伤。' WHERE id = 'f30558ce-2e74-4368-ad59-ff72d43fefc7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Has pensado en menús distintos para que él coma bien, ¿y tú otra vez has picado algo seco de pie? En Recetas saludables, no solo para niños sino también para mamás, elige una comida energética, lista en 10 minutos y llena de hierro y calcio, y date el valor que mereces.', body_fr = 'Vous avez imaginé différents menus pour le nourrir, et vous, vous avez encore grignoté quelque chose de sec debout ? Dans les Recettes saines, choisissez un repas énergisant, prêt en 10 minutes et riche en fer et en calcium, pas seulement pour les enfants mais aussi pour les mamans, et prenez soin de vous.', body_hi = 'उसका पेट भरने के लिए तरह-तरह के मेन्यू सोचे, पर खुद फिर खड़े-खड़े कुछ सूखा सा खा लिया? सेहतमंद रेसिपी में सिर्फ़ बच्चों के लिए नहीं, माँओं के लिए भी 10 मिनट में बनने वाला, ऊर्जा देने वाला, आयरन और कैल्शियम से भरपूर लंच चुनिए और खुद को अहमियत दीजिए।', body_id = 'Anda memikirkan berbagai menu untuk membuatnya kenyang, tapi Anda sendiri lagi-lagi makan sesuatu yang kering sambil berdiri? Di Resep Sehat bukan hanya ada menu untuk anak, tapi juga untuk ibu. Pilih makan siang penambah energi kaya zat besi dan kalsium yang siap dalam 10 menit, dan hargai diri Anda.', body_ja = 'この子を満足させるためにいろいろな献立を考えたのに、自分はまた立ったまま簡単なものを食べた？「ヘルシーレシピ」には子どもだけでなくママ向けの、元気が出て10分でできる、鉄分とカルシウムたっぷりのランチもあります。自分を大切にしましょう。', body_ko = '아이를 먹이려고 여러 메뉴를 고민했는데 정작 엄마는 또 서서 마른 음식으로 때웠나요? 건강한 레시피에는 아이뿐 아니라 엄마를 위한, 10분이면 만드는 철분과 칼슘 가득한 활력 점심도 있어요. 나를 소중히 대해 주세요.', body_nl = 'Je bedenkt allerlei menu''s om hem te laten eten, maar heb je zelf weer staand iets droogs naar binnen gewerkt? Kies in Gezonde recepten een energieke lunch vol ijzer en calcium die in 10 minuten klaar is, niet alleen voor kinderen maar ook voor mama''s, en geef jezelf de waarde die je verdient.', body_pl = 'Wymyślasz różne menu, żeby go nakarmić, a sama znowu zjadłaś coś suchego na stojąco? Wybierz w Zdrowych przepisach obiad nie tylko dla dzieci, ale też dla mam: energetyczny, gotowy w 10 minut, pełen żelaza i wapnia. Doceń siebie.', body_pt = 'Pensou em menus diferentes para ele comer, mas a mãe voltou a comer qualquer coisa seca de pé? Nas Receitas Saudáveis há almoços não só para crianças, mas também para mães: energéticos, prontos em 10 minutos e ricos em ferro e cálcio. Escolha um e dê-se valor.', body_sv = 'Du har hittat på olika menyer för att få barnet mätt, men själv har du återigen ätit något torrt stående? I Hälsosamma recept finns inte bara rätter för barn utan också energigivande luncher för mammor, fulla av järn och kalcium och klara på 10 minuter. Välj en och ta hand om dig själv.', body_vi = 'Mẹ nghĩ ra đủ thực đơn để bé ăn no, còn mình lại đứng ăn vội thứ gì đó khô khốc? Trong Công thức lành mạnh không chỉ có món cho bé mà còn có món cho mẹ: hãy chọn một bữa trưa giàu năng lượng, giàu sắt và canxi, làm trong 10 phút, và trân trọng bản thân mình.', body_zh = '为了喂饱宝宝想了好几种菜单，自己却又站着随便吃了点干巴巴的东西？在健康食谱里，挑一道不只适合孩子、也适合妈妈的午餐：补充能量、10分钟做好、富含铁和钙，好好珍惜自己。' WHERE id = '1633765a-e691-4a02-b657-169e03223f3f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de «mi juguete está malito» 🩺', body_es = 'Coge su estetoscopio de juguete, examina muy en serio a su osito y le pega una tirita. A través del juego simbólico procesa la compasión y el cuidado. Métete tú también en el papel de paciente, túmbate y deja que te examine en silencio 5 minutos.', title_fr = 'La bataille du « Mon jouet est malade » 🩺', body_fr = 'Avec son stéthoscope en plastique, il examine très sérieusement son nounours et lui colle un pansement. Grâce aux jeux symboliques, il apprivoise la compassion et l''attention aux autres. Entrez dans le rôle du patient à l''hôpital, allongez-vous et laissez-le vous examiner en silence pendant 5 minutes.', title_hi = '‘मेरा खिलौना बीमार है’ वाली जंग 🩺', body_hi = 'खिलौने वाला स्टेथोस्कोप लेकर अपने भालू की गंभीरता से जाँच करता है और उसे बैंडेज लगाता है। प्रतीकात्मक खेलों से वह दया और देखभाल को समझ रहा है। आप भी अस्पताल की मरीज़ बनकर लेट जाइए और उसे 5 मिनट चुपचाप अपनी जाँच करने दीजिए।', title_id = 'Pertempuran ''mainanku sakit'' 🩺', body_id = 'Ia mengambil stetoskop mainan, memeriksa boneka beruangnya dengan serius, lalu menempelkan plester. Lewat permainan simbolik, ia mengolah rasa kasih sayang dan kepedulian. Ambil peran sebagai pasien di rumah sakit, berbaringlah, dan biarkan ia memeriksa Anda dengan tenang selama 5 menit.', title_ja = 'おもちゃが病気だよ大作戦 🩺', body_ja = 'おもちゃの聴診器でくまさんを真剣に診察して、ばんそうこうを貼っている。ごっこ遊びを通して、思いやりやいたわりを心の中で整理しています。あなたも患者さん役になって横になり、5分間静かに診察してもらいましょう。', title_ko = '''내 장난감이 아파'' 대작전 🩺', body_ko = '장난감 청진기로 곰 인형을 진지하게 진찰하고 반창고를 붙여 주나요? 상징 놀이를 통해 연민과 돌봄을 익히고 있어요. 엄마도 병원 환자 역할로 누워서 5분간 조용히 진찰을 받아 보세요.', title_nl = 'De strijd van ''mijn knuffel is ziek'' 🩺', body_nl = 'Pakt hij zijn speelgoedstethoscoop, onderzoekt hij zijn beertje heel serieus en plakt hij er een pleister op? Via symbolisch spel verwerkt hij medeleven en zorg. Speel zelf de patiënt in het ziekenhuis, ga liggen en laat je 5 minuten in stilte onderzoeken.', title_pl = 'Bitwa „Moja zabawka jest chora” 🩺', body_pl = 'Bierze zabawkowy stetoskop, z powagą bada misia i nakleja mu plaster. W zabawach symbolicznych przetwarza współczucie i troskę. Wejdź w rolę pacjentki w szpitalu, połóż się i pozwól mu przez 5 minut w ciszy się zbadać.', title_pt = 'A batalha do "o meu brinquedo está doente" 🩺', body_pt = 'Pega no estetoscópio de brincar, examina muito a sério o ursinho e cola-lhe um penso. Através do jogo simbólico, está a processar a compaixão e o cuidado. Entre no papel de paciente do hospital, deite-se e deixe que a examine 5 minutos em silêncio.', title_sv = 'Striden om den sjuka leksaken 🩺', body_sv = 'Barnet tar leksaksstetoskopet, undersöker nallen på fullt allvar och sätter ett plåster på den. Genom symbolisk lek bearbetar barnet medkänsla och omsorg. Gå in i rollen som patient på sjukhuset, lägg dig ner och låt barnet undersöka dig tyst i 5 minuter.', title_vi = 'Trận chiến "Đồ chơi của con bị ốm" 🩺', body_vi = 'Bé cầm ống nghe đồ chơi, nghiêm túc khám cho gấu bông và dán băng cá nhân cho nó. Qua trò chơi biểu tượng, bé đang học về lòng trắc ẩn và sự quan tâm. Mẹ cũng hãy nằm xuống làm bệnh nhân và để bé lặng lẽ khám cho mình 5 phút.', title_zh = '“我的玩具生病了”大作战 🩺', body_zh = '拿着玩具听诊器认真地给小熊做检查，还贴上创可贴。宝宝正通过象征性游戏消化同情和关爱。你也扮演医院里的病人躺下来，让宝宝安安静静地给你检查5分钟吧。' WHERE id = '2d30d5d5-9abc-4c5e-847a-462fa693fbda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir fácil con Cuentos inteligentes 🪄', body_es = 'Ya te sabes de memoria los libros clásicos. Abre Cuentos inteligentes, haz de tu peque el protagonista y de su habitación el lugar a conquistar, y crea una sesión de sueño original que no te exige ningún esfuerzo.', title_fr = 'Un coucher facile avec les Contes intelligents 🪄', body_fr = 'Vous connaissez les livres classiques par cœur. Ouvrez les Contes intelligents, faites de votre enfant le héros et de sa chambre le lieu à conquérir, et créez un moment de coucher original, sans aucun effort.', title_hi = 'स्मार्ट कहानियों से आसान नींद 🪄', body_hi = 'पुरानी किताबें आपको रट चुकी हैं। स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और जीतने वाली जगह उसके कमरे को बनाकर एक अनोखा, बिना मेहनत वाला नींद का सेशन बनाइए।', title_id = 'Tidur mudah dengan Dongeng Pintar 🪄', body_id = 'Anda sudah hafal buku-buku klasik. Buka Dongeng Pintar, jadikan anak Anda sebagai tokoh utama dan kamarnya sebagai tempat yang harus ditaklukkan, lalu ciptakan sesi tidur yang luar biasa tanpa perlu usaha.', title_ja = 'スマートおはなしで楽に眠りへ 🪄', body_ja = '昔の絵本はもう暗記してしまいましたね。「スマートおはなし」を開いて、主人公はお子さん、冒険の舞台はこの子の部屋にして、いつもとちがう、まったく手間のかからない寝かしつけタイムをつくりましょう。', title_ko = '스마트 동화로 쉽게 잠들기 🪄', body_ko = '고전 책은 이미 다 외웠나요? 스마트 동화를 열어 주인공은 우리 아이, 정복할 장소는 아이 방으로 만들어 보세요. 아무 힘도 들지 않는 특별한 잠자리 시간이 될 거예요.', title_nl = 'Makkelijk slapen met Slimme sprookjes 🪄', body_nl = 'Ken je de klassieke boekjes al uit je hoofd? Open Slimme sprookjes en maak een bijzondere slaapsessie zonder moeite, met je kind als hoofdpersoon en zijn eigen kamer als de plek die veroverd moet worden.', title_pl = 'Łatwy sen z Mądrymi bajkami 🪄', body_pl = 'Klasyczne książki znasz już na pamięć. Otwórz Mądre bajki, uczyń głównym bohaterem swoje dziecko, a miejscem do zdobycia jego pokój i stwórz niezwykły seans usypiania, który nie wymaga żadnego wysiłku.', title_pt = 'Adormecer fácil com as Histórias Inteligentes 🪄', body_pt = 'Já sabe de cor os livros clássicos. Abra as Histórias Inteligentes e crie uma sessão de sono invulgar e sem esforço, com o seu filho como herói principal e o quarto dele como o lugar a conquistar.', title_sv = 'Lätt att somna med Smarta sagor 🪄', body_sv = 'Du kan de klassiska böckerna utantill. Öppna Smarta sagor och skapa en ovanlig, helt ansträngningsfri godnattstund där ditt barn är huvudpersonen och platsen som ska erövras är barnets eget rum.', title_vi = 'Ngủ dễ dàng với Truyện cổ tích thông minh 🪄', body_vi = 'Mẹ đã thuộc lòng các cuốn sách kinh điển. Hãy mở Truyện cổ tích thông minh, lấy bé làm nhân vật chính, căn phòng của bé làm vùng đất cần chinh phục, và tạo một buổi ru ngủ khác thường mà chẳng tốn chút sức nào.', title_zh = '智慧童话，轻松入睡 🪄', body_zh = '经典的书都背下来了？打开智慧童话，让宝宝当主角，把宝宝的房间设为要征服的地方，创造一次与众不同、毫不费力的睡前时光。' WHERE id = '37ed4aaf-5c8b-418c-8274-802f79f0bf41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No hace falta ningún juego, libro ni cuento. Esta noche solo abrázalo contra tu pecho, respira hondo su olor precioso y susúrrale en la oscuridad lo valioso que es y cuánto lo quieres.', body_fr = 'Pas besoin de jeu, de livre ni de conte. Ce soir, serrez-le simplement contre votre poitrine, respirez profondément sa bonne odeur et, dans le noir, chuchotez-lui combien il est précieux et combien vous l''aimez.', body_hi = 'किसी खेल, किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी प्यारी खुशबू गहरी साँसों में भरिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है और आप उसे कितना प्यार करती हैं।', body_id = 'Tak perlu permainan, buku, atau dongeng. Malam ini cukup dekap ia di dada Anda, hirup dalam-dalam aroma indahnya, dan dalam gelap bisikkan betapa berharganya ia dan betapa Anda menyayanginya.', body_ja = '遊びも絵本もお話もいりません。今夜はただ胸に抱きしめて、そのいいにおいを深く吸いこみ、暗やみの中で、どれほど大切か、どんなに愛しているかをささやいてあげましょう。', body_ko = '놀이도, 책도, 동화도 필요 없어요. 오늘 저녁엔 아이를 가슴에 꼭 안고 그 사랑스러운 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중하고 얼마나 사랑하는지 속삭여 주세요.', body_nl = 'Geen spel, boek of sprookje nodig. Druk hem vanavond gewoon tegen je borst, snuif diep zijn heerlijke geur op en fluister in het donker hoe kostbaar hij is en hoeveel je van hem houdt.', body_pl = 'Nie potrzeba żadnej zabawy, książki ani bajki. Dziś wieczorem po prostu przytul go do piersi, głęboko wdychaj jego piękny zapach i w ciemności wyszeptaj mu, jaki jest cenny i jak bardzo go kochasz.', body_pt = 'Não é preciso nenhum jogo, livro ou história. Esta noite, aperte-o simplesmente contra o peito, respire fundo aquele cheirinho tão bom e sussurre-lhe no escuro o quanto é precioso e o quanto o ama.', body_sv = 'Det behövs varken lek, bok eller saga. I kväll håller du bara barnet tätt intill dig, andas djupt in den underbara doften och viskar i mörkret hur värdefullt barnet är och hur mycket du älskar hen.', body_vi = 'Không cần trò chơi, sách hay truyện nào cả. Tối nay, chỉ cần ôm bé vào lòng, hít thật sâu mùi hương dễ thương ấy và thì thầm trong bóng tối rằng bé quý giá với mẹ biết bao, mẹ yêu bé nhường nào.', body_zh = '不需要任何游戏、书或故事。今晚只要把宝宝紧紧抱在怀里，深深吸一口那美好的味道，在黑暗中轻声告诉宝宝，宝宝有多珍贵，你有多爱宝宝。' WHERE id = '72e4a373-da8e-4cf7-b36b-25d3d3a13b6e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En el parque le habla muy en serio a una piedra, o en casa a una silla, y hasta las regaña. A través del juego simbólico procesa el mundo.', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise, et il les gronde. Grâce aux jeux symboliques, il apprivoise le monde.', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ बातें करता है, उन्हें डाँटता है। प्रतीकात्मक खेलों के ज़रिए वह दुनिया को समझ रहा है।', body_id = 'Di taman ia berbicara dengan sangat serius kepada sebuah batu atau kursi di rumah, bahkan memarahinya. Lewat permainan simbolik, ia sedang mengolah dunia.', body_ja = '公園の石や家のいすに、とても真剣に何かを話しかけたり、叱ったりしている。ごっこ遊びを通して、世界を心の中で整理しています。', body_ko = '공원의 돌이나 집 안 의자에게 아주 진지하게 무언가를 말하고 혼내기도 하나요? 상징 놀이를 통해 세상을 이해하는 중이에요.', body_nl = 'Praat hij in het park heel serieus tegen een steen of moppert hij thuis op een stoel? Via symbolisch spel verwerkt hij de wereld.', body_pl = 'W parku z całą powagą opowiada coś kamieniowi albo w domu krzesłu i na nie krzyczy. W zabawach symbolicznych przetwarza świat.', body_pt = 'No parque fala muito a sério com uma pedra ou, em casa, com uma cadeira, e até lhes ralha. Através do jogo simbólico, ele processa o mundo.', body_sv = 'Barnet pratar helt allvarligt med en sten i parken eller en stol hemma och skäller på dem. Genom symbolisk lek bearbetar barnet världen.', body_vi = 'Bé nói chuyện hết sức nghiêm túc với một hòn đá ở công viên hay chiếc ghế ở nhà, thậm chí còn mắng chúng. Qua trò chơi biểu tượng, bé đang tìm hiểu thế giới.', body_zh = '在公园里对着一块石头，或在家对着一把椅子，一本正经地说着什么，还会批评它们。宝宝正在通过象征性游戏理解这个世界。' WHERE id = '8d0e8d79-2ed2-4d47-9d71-055f26b53574' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Ha derramado el agua en la mesa y te exige llorando que la vuelvas a meter en el vaso! Sí, aquí no hay lógica, solo la frustración de un error que no tiene vuelta atrás. No intentes explicarlo: dale un trapo, dile «Venga, vamos a hacer desaparecer esta agua» y conviértelo en un juego.', body_fr = 'Il a renversé l''eau sur la table et exige en pleurant que vous la remettiez dans le verre ! Eh oui, la logique n''a pas sa place ici, juste la frustration d''une erreur irréversible. N''essayez pas d''expliquer, donnez-lui un chiffon, dites « Viens, on fait disparaître cette eau » et passez au jeu.', body_hi = 'मेज़ पर पानी गिरा दिया और अब रोते हुए आपसे कहता है कि वह पानी वापस गिलास में भर दो! हाँ, कमरे में कोई तर्क नहीं, बस एक ऐसी गलती की निराशा है जो पलटी नहीं जा सकती। समझाने की कोशिश मत कीजिए, उसके हाथ में कपड़ा देकर ‘चलो, इस पानी को गायब कर दें’ कहिए और खेल शुरू कर दीजिए।', body_id = 'Ia menumpahkan air di meja dan sambil menangis menuntut Anda mengembalikan air itu ke gelas! Ya, tidak ada logika di sini, hanya kekecewaan atas kesalahan yang tak bisa diulang. Jangan coba menjelaskan, berikan lap ke tangannya, katakan ''Ayo kita hilangkan airnya'' dan beralihlah ke permainan.', body_ja = 'テーブルにお水をこぼして、泣きながら「コップに戻して」と言う！そう、そこに理屈はなく、取り返しのつかない失敗へのがっかりがあるだけ。説明しようとせず、タオルを渡して「このお水を消しちゃおう」と遊びに切りかえましょう。', body_ko = '식탁에 물을 쏟고는 울면서 그 물을 다시 컵에 담아 달라고 하나요? 네, 논리는 없어요. 되돌릴 수 없는 실수에 대한 속상함만 있을 뿐이죠. 설명하려 하지 말고 행주를 건네며 ''이 물을 사라지게 해 보자'' 하고 놀이로 넘어가세요.', body_nl = 'Morste hij water op tafel en eist hij huilend dat jij het weer in de beker doet? Ja, logica is er even niet, alleen teleurstelling over een fout die niet terug te draaien is. Probeer het niet uit te leggen, geef hem een doekje, zeg ''Kom, we laten dit water verdwijnen'' en maak er een spelletje van.', body_pl = 'Rozlał wodę na stół i z płaczem żąda, żebyś zebrała ją z powrotem do kubka! Tak, logiki tu nie ma, jest tylko rozczarowanie nieodwracalnym błędem. Nie próbuj tłumaczyć, daj mu ściereczkę i przejdź do zabawy: „Sprawmy, żeby ta woda zniknęła”.', body_pt = 'Entornou a água na mesa e exige a chorar que a volte a pôr no copo! Sim, aqui não há lógica, só a frustração de um erro que não tem volta. Não tente explicar: dê-lhe um pano, diga "Vamos fazer esta água desaparecer" e passe para a brincadeira.', body_sv = 'Barnet spillde vatten på bordet och kräver gråtande att du ska samla tillbaka vattnet i glaset! Ja, det finns ingen logik i rummet, bara besvikelsen över ett misstag som inte går att göra ogjort. Försök inte förklara, ge barnet en trasa, säg ”Kom, vi får vattnet att försvinna” och gör det till en lek.', body_vi = 'Bé làm đổ nước ra bàn rồi khóc đòi mẹ gom nước lại vào cốc! Đúng vậy, chẳng có chút logic nào, chỉ có nỗi thất vọng vì một lỗi không thể sửa. Đừng cố giải thích, hãy đưa bé chiếc khăn và nói "Mình cùng làm nước biến mất nào", rồi biến nó thành trò chơi.', body_zh = '把水洒在桌上，然后哭着要你把水装回杯子里！是的，这里没有逻辑，只有对无法挽回的错误的失望。别试图解释，递一块毛巾，说“我们来让这些水消失吧”，把它变成一个游戏。' WHERE id = '9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Refugio offline para mamá 🚪', body_es = 'El ruido te hace pitar los oídos. Déjalo en un lugar seguro (o con papá), entra en el baño y cierra la puerta. Mira la pared solo 5 minutos, no hagas nada, ni siquiera abras el móvil. Este breve silencio es el arma más poderosa para devolverte a tu papel de mamá.', title_fr = 'Un refuge hors ligne pour maman 🚪', body_fr = 'Le bruit vous fait bourdonner les oreilles. Laissez-le en lieu sûr (ou avec son papa), entrez aux toilettes et fermez la porte. Regardez simplement le mur pendant 5 minutes, ne faites rien, n''allumez même pas votre téléphone. Ce court silence est l''arme la plus puissante pour retrouver votre rôle de maman.', title_hi = 'माँ के लिए ऑफ़लाइन ठिकाना 🚪', body_hi = 'शोर से कान बज रहे हैं। उसे किसी सुरक्षित जगह (या पापा के पास) छोड़कर बाथरूम में जाइए और दरवाज़ा बंद कर लीजिए। बस 5 मिनट दीवार को देखिए, कुछ मत कीजिए, फ़ोन भी मत खोलिए। यह छोटी सी खामोशी आपको फिर से माँ की भूमिका में लौटाने वाला सबसे ताकतवर हथियार है।', title_id = 'Tempat berlindung offline untuk Ibu 🚪', body_id = 'Kebisingan membuat telinga Anda berdenging. Tinggalkan ia di tempat yang aman (atau serahkan pada ayahnya), masuk ke kamar mandi, dan tutup pintunya. Cukup pandangi dinding selama 5 menit, jangan lakukan apa pun, bahkan jangan buka ponsel. Keheningan singkat ini adalah senjata terkuat untuk mengembalikan Anda ke peran ibu.', title_ja = 'ママのためのオフライン避難所 🚪', body_ja = '騒音で耳がキンキンする。子どもを安全な場所に（またはパパに）まかせて、トイレに入ってドアを閉めましょう。ただ5分間壁を見つめて、何もせず、スマホも開かないで。この短い静けさが、あなたをまたママに戻してくれるいちばん強い武器です。', title_ko = '엄마를 위한 오프라인 피난처 🚪', body_ko = '소음에 귀가 윙윙 울리나요? 아이를 안전한 곳에 (또는 아빠에게) 맡기고 화장실에 들어가 문을 닫으세요. 딱 5분만 벽을 바라보며 아무것도 하지 마세요, 휴대폰도 켜지 말고요. 이 짧은 고요가 다시 엄마 역할로 돌아가게 해 줄 가장 강력한 무기예요.', title_nl = 'Offline schuilplek voor mama 🚪', body_nl = 'Suizen je oren van al het lawaai? Laat hem op een veilige plek (of bij papa) en ga naar de wc met de deur dicht. Staar 5 minuten naar de muur, doe niets, zet zelfs je telefoon niet aan. Deze korte stilte is je sterkste wapen om weer in je rol als mama te stappen.', title_pl = 'Schronienie offline dla mamy 🚪', body_pl = 'Od hałasu dzwoni ci w uszach. Zostaw dziecko w bezpiecznym miejscu (albo z tatą), wejdź do toalety i zamknij drzwi. Przez 5 minut po prostu patrz w ścianę, nic nie rób, nawet nie włączaj telefonu. Ta krótka cisza to najsilniejsza broń, która przywróci cię do roli mamy.', title_pt = 'Refúgio offline para a mãe 🚪', body_pt = 'O barulho faz-lhe zumbir os ouvidos. Deixe-o num sítio seguro (ou com o pai), entre na casa de banho e feche a porta. Fique só 5 minutos a olhar para a parede, sem fazer nada, nem sequer abrir o telemóvel. Este curto silêncio é a arma mais forte para voltar ao papel de mãe.', title_sv = 'En offline-tillflykt för mamma 🚪', body_sv = 'Oljudet får det att ringa i öronen. Lämna barnet på ett säkert ställe (eller hos pappa), gå in på toaletten och stäng dörren. Titta bara på väggen i 5 minuter, gör ingenting, öppna inte ens telefonen. Den korta tystnaden är det starkaste vapnet för att ta dig tillbaka in i mammarollen.', title_vi = 'Góc "offline" cho mẹ 🚪', body_vi = 'Tiếng ồn làm tai mẹ ù đi. Hãy để bé ở nơi an toàn (hoặc nhờ bố), vào nhà vệ sinh và đóng cửa lại. Chỉ cần nhìn vào tường 5 phút, không làm gì cả, thậm chí đừng mở điện thoại. Chút yên lặng ngắn ngủi này là vũ khí mạnh nhất đưa mẹ trở lại vai trò làm mẹ.', title_zh = '妈妈的离线避难所 🚪', body_zh = '吵闹声让你耳朵嗡嗡响。把宝宝留在安全的地方（或交给爸爸），走进卫生间关上门。只是看着墙5分钟，什么都不做，连手机都别打开。这短短的安静，是让你重新回到妈妈角色的最强武器。' WHERE id = 'aff11dbf-a5df-4f87-ba8b-797021b1bfe4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido soltar su energía en casa y no quiere irse a la cama. Llama a papá al sofá. Cuando lo levante por los aires y haga el avión, esas carcajadas que llenan la habitación borrarán en segundos todo el estrés físico acumulado. La pelota está en el tejado de papá.', body_fr = 'Il n''a pas pu se dépenser à la maison et ne veut pas aller au lit. Appelez papa sur le canapé. Quand il soulèvera l''enfant pour faire l''avion, les éclats de rire qui rempliront la pièce effaceront en quelques secondes tout le stress physique accumulé. La balle est dans le camp de papa.', body_hi = 'घर में अपनी ऊर्जा निकाल नहीं पाया और सोने नहीं जाना चाहता। पापा को सोफ़े पर बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ बनाएँगे, तो कमरे में गूँजती खिलखिलाहट सारा जमा शारीरिक तनाव सेकंडों में मिटा देगी। गेंद अब पापा के पाले में है।', body_id = 'Ia belum sempat menyalurkan energinya di rumah dan tidak mau tidur. Panggil Ayah ke sofa. Saat Ayah mengangkatnya tinggi dan membuatnya ''terbang seperti pesawat'', tawa yang memenuhi kamar akan menghapus semua stres fisik yang menumpuk dalam hitungan detik. Bolanya di tangan Ayah.', body_ja = '家でエネルギーを発散しきれず、寝たがらない。パパをソファに呼びましょう。パパが子どもを高く持ち上げて飛行機ごっこをすれば、部屋じゅうに広がる笑い声が、たまった体のストレスを数秒で消してくれます。ボールはパパにパス。', body_ko = '집에서 에너지를 다 쓰지 못해 잠자리에 들기 싫어하나요? 아빠를 소파로 불러 주세요. 아빠가 아이를 번쩍 들어 비행기를 태워 주면, 방을 가득 채우는 웃음소리가 쌓인 몸의 긴장을 순식간에 날려 버릴 거예요. 이제 공은 아빠에게!', body_nl = 'Hij is zijn energie in huis niet kwijtgeraakt en wil niet naar bed. Roep papa naar de bank. Als hij hem als een vliegtuig de lucht in tilt, laat het gelach dat de kamer vult alle opgekropte lichamelijke spanning in een paar seconden verdwijnen. De bal ligt bij papa.', body_pl = 'Nie wyładował energii w domu i nie chce iść spać. Zawołaj tatę na kanapę. Gdy podniesie dziecko i zrobi z niego samolot, śmiech wypełniający pokój w kilka sekund rozładuje całe nagromadzone napięcie. Piłeczka po stronie taty.', body_pt = 'Não conseguiu gastar a energia em casa e não quer ir para a cama. Chame o pai ao sofá. Quando ele o levanta no ar e faz de avião, as gargalhadas que enchem o quarto fazem desaparecer em segundos todo o stress físico acumulado. A bola está com o pai.', body_sv = 'Barnet har inte fått ut sin energi hemma och vill inte gå och lägga sig. Kalla in pappa till soffan. När han lyfter barnet i luften och flyger flygplan, får skrattet som fyller rummet all uppbyggd fysisk stress att försvinna på några sekunder. Bollen ligger hos pappa.', body_vi = 'Bé chưa xả hết năng lượng ở nhà và không chịu đi ngủ. Hãy gọi bố ra sofa. Khi bố nhấc bé lên cao làm máy bay, những tràng cười vang khắp phòng sẽ xóa tan mọi căng thẳng thể chất tích tụ trong vài giây. Giờ đến lượt bố.', body_zh = '在家没把精力用完，不肯上床。把爸爸叫到沙发上。当他把宝宝举高“开飞机”时，满屋子的笑声会在几秒钟内把积攒的身体压力一扫而空。球现在在爸爸那里了。' WHERE id = 'f965edcf-2124-46c3-82a9-e8d418ee755a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La invención de un idioma nuevo 🗣️', body_es = 'Inventa frases poéticas como «Mi juguete está triste» o «El cielo ha llorado», poniendo emociones en las cosas. Su vocabulario y su inteligencia emocional crecen como una tormenta. Guarda ya esta tierna filosofía con el modo vídeo de la Sesión de fotos del bebé.', title_fr = 'L''invention d''une nouvelle langue 🗣️', body_fr = 'Il prête des émotions aux objets et invente des phrases poétiques comme « Mon jouet est triste » ou « Le ciel a pleuré ». Son vocabulaire et son intelligence émotionnelle se développent à toute vitesse. Gardez tout de suite une trace de cette douce philosophie avec le mode vidéo de la Séance photo bébé.', title_hi = 'एक नई भाषा का आविष्कार 🗣️', body_hi = '‘मेरा खिलौना उदास हो गया’, ‘आसमान रो पड़ा’ जैसे वाक्यों में चीज़ों पर भावनाएँ डालकर पूरी तरह गढ़े हुए काव्यात्मक वाक्य बनाता है। उसकी शब्दावली और भावनात्मक समझ तूफ़ान की तरह बढ़ रही है। बेबी फ़ोटोशूट के वीडियो मोड से उसका यह प्यारा फ़लसफ़ा तुरंत सहेज लीजिए।', title_id = 'Menciptakan bahasa baru 🗣️', body_id = 'Ia menyusun kalimat puitis karangannya sendiri dengan memberi perasaan pada benda, seperti ''Mainanku sedih'' atau ''Langit menangis''. Kosakata dan kecerdasan emosionalnya berkembang seperti badai. Segera arsipkan filsafat manisnya ini dengan mode video di Pemotretan Bayi.', title_ja = '新しいことばの発明 🗣️', body_ja = '「おもちゃが悲しくなった」「お空が泣いた」のように、ものに気持ちをのせて、詩のような文をつくり出す。語彙と心の知能が嵐のように育っています。「ベビーフォトセッション」の動画モードで、このかわいい哲学をすぐに残しましょう。', title_ko = '새로운 언어의 탄생 🗣️', body_ko = '''내 장난감이 슬퍼'', ''하늘이 울었어''처럼 물건에 감정을 담아 상상 속 시적인 문장을 만들어 내나요? 어휘력과 감성 지능이 폭풍처럼 자라고 있어요. 아기 사진 촬영의 동영상 모드로 이 사랑스러운 철학을 바로 기록해 두세요.', title_nl = 'Een nieuwe taal uitgevonden 🗣️', body_nl = 'Maakt hij zelfverzonnen poëtische zinnen waarin spullen gevoelens hebben, zoals ''Mijn speelgoed is verdrietig'' of ''De lucht huilde''? Zijn woordenschat en emotionele intelligentie groeien razendsnel. Leg zijn lieve filosofie meteen vast met de videomodus van de Babyfotoshoot.', title_pl = 'Wynalezienie nowego języka 🗣️', body_pl = 'Przypisuje emocje przedmiotom i układa całkiem wymyślone, poetyckie zdania w stylu „Moja zabawka się smuci” albo „Niebo płakało”. Jego słownictwo i inteligencja emocjonalna rozwijają się jak burza. Od razu zachowaj tę słodką filozofię w trybie wideo Sesji zdjęciowej dziecka.', title_pt = 'A invenção de uma nova língua 🗣️', body_pt = 'Constrói frases poéticas totalmente inventadas, dando emoções às coisas, como "O meu brinquedo ficou triste" ou "O céu chorou". O vocabulário e a inteligência emocional crescem como uma tempestade. Arquive já esta doce filosofia com o modo de vídeo da Sessão Fotográfica do Bebé.', title_sv = 'Ett nytt språk uppfinns 🗣️', body_sv = '”Min leksak blev ledsen”, ”Himlen grät”: barnet lägger känslor på saker och bygger helt påhittade, poetiska meningar. Ordförrådet och den känslomässiga intelligensen växer som en storm. Spara genast den söta filosofin med videoläget i Babyfotografering.', title_vi = 'Phát minh ra ngôn ngữ mới 🗣️', body_vi = 'Bé đặt cảm xúc vào đồ vật và tạo ra những câu nói hoàn toàn tưởng tượng, đầy chất thơ như "Đồ chơi của con buồn rồi", "Bầu trời khóc". Vốn từ và trí tuệ cảm xúc của bé đang phát triển như vũ bão. Hãy lưu ngay "triết lý" ngọt ngào này bằng chế độ quay video của Chụp ảnh cho bé.', title_zh = '发明一门新语言 🗣️', body_zh = '说出“我的玩具难过了”“天空哭了”这样把情绪赋予物品、完全自创的诗意句子。宝宝的词汇和情绪智力正在飞速发展。用宝宝写真的视频模式，马上把这份可爱的“哲学”存下来吧。' WHERE id = '535821ef-9689-4454-87b8-1d43fe500b62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El jefe de cocina en acción 🧑‍🍳', body_es = 'Mientras haces magdalenas, quiere sí o sí poner una silla al lado y echar él la harina. Si le dejas, la cocina acabará destrozada. Dale un bol vacío, agua y un poco de harina y dile: «Tú amasa la masa de tu magdalena». Habrá caos, pero su ego quedará totalmente satisfecho.', title_fr = 'Le chef de cuisine en action 🧑‍🍳', body_fr = 'Pendant que vous préparez un gâteau, il veut absolument installer une chaise à côté de vous et verser la farine lui-même. Si vous le laissez faire, la cuisine sera dévastée. Donnez-lui un bol vide, de l''eau et un peu de farine, et dites : « Toi, pétris la pâte de ton gâteau. » Ce sera le chaos, mais son ego sera pleinement satisfait.', title_hi = 'रसोई का लीडर काम पर 🧑‍🍳', body_hi = 'आप केक बना रही हैं और वह पास में कुर्सी लगाकर आटा खुद डालना चाहता है। इजाज़त दी तो रसोई तबाह हो जाएगी। उसे एक खाली कटोरा, पानी और थोड़ा आटा देकर कहिए, ‘तुम अपने केक का आटा गूँधो।’ अफ़रा-तफ़री तो होगी, पर उसका अहं पूरी तरह संतुष्ट होगा।', title_id = 'Kepala dapur sedang bertugas 🧑‍🍳', body_id = 'Saat Anda membuat kue, ia bersikeras menaruh kursi di samping Anda dan menuang tepung sendiri. Kalau diizinkan, dapur bisa hancur. Beri ia mangkuk kosong, air, dan sedikit tepung, lalu katakan ''Kamu uleni adonan kuemu sendiri''. Akan berantakan, tapi egonya terpenuhi sepenuhnya.', title_ja = 'キッチンリーダー、出動中 🧑‍🍳', body_ja = 'カップケーキをつくっていると、必ずいすを持ってきて粉を自分で入れたがる。まかせたらキッチンは大惨事。空のボウルと水と少しの粉を渡して「あなたは自分のケーキの生地をこねてね」と言いましょう。散らかりますが、プライドはしっかり満たされます。', title_ko = '주방 대장 출동 🧑‍🍳', body_ko = '케이크를 만들 때면 꼭 옆에 의자를 갖다 놓고 밀가루를 직접 붓겠다고 하나요? 허락하면 부엌이 초토화될 거예요. 빈 그릇과 물, 밀가루 조금을 주며 ''너는 네 케이크 반죽을 만들어'' 하고 말해 주세요. 난장판은 되겠지만 자존심은 완전히 채워질 거예요.', title_nl = 'De chef-kok aan het werk 🧑‍🍳', body_nl = 'Als jij muffins bakt, zet hij per se een stoel naast je om zelf de bloem te storten. Laat je hem zijn gang gaan, dan is de keuken verloren. Geef hem een lege kom, wat water en een beetje bloem en zeg: ''Kneed jij je eigen deeg maar.'' Er komt chaos, maar zijn ego is helemaal tevreden.', title_pl = 'Szef kuchni w akcji 🧑‍🍳', body_pl = 'Gdy pieczesz babeczki, koniecznie stawia obok krzesło i chce sam wsypać mąkę. Jeśli pozwolisz, kuchnia legnie w gruzach. Daj mu pustą miskę, wodę i trochę mąki i powiedz: „Ty zagnieć ciasto na swoją babeczkę”. Będzie chaos, ale jego ego zostanie w pełni zaspokojone.', title_pt = 'O chefe de cozinha em ação 🧑‍🍳', body_pt = 'Enquanto faz queques, ele põe logo uma cadeira ao seu lado e quer deitar a farinha sozinho. Se deixar, a cozinha fica destruída. Dê-lhe uma taça vazia, água e um pouco de farinha e diga: "Amassa tu a massa do teu queque". Vai haver caos, mas o ego dele fica totalmente satisfeito.', title_sv = 'Kökschefen i tjänst 🧑‍🍳', body_sv = 'När du bakar muffins vill barnet absolut ställa en stol bredvid dig och hälla i mjölet själv. Om du låter hen göra det blir köket förstört. Ge barnet en tom skål, vatten och lite mjöl och säg ”Du knådar degen till din egen muffins”. Det blir kaos, men självkänslan blir helt nöjd.', title_vi = 'Bếp trưởng đang làm việc 🧑‍🍳', body_vi = 'Mẹ làm bánh, bé nhất định kê ghế bên cạnh và đòi tự đổ bột. Nếu cho phép, căn bếp sẽ tan tành. Hãy đưa bé một chiếc bát rỗng, chút nước và ít bột rồi nói: "Con nhào bột bánh của con nhé." Sẽ có hỗn loạn, nhưng cái tôi của bé được thỏa mãn trọn vẹn.', title_zh = '厨房小领袖上岗 🧑‍🍳', body_zh = '你做蛋糕时，非要搬把椅子过来自己倒面粉。要是答应了，厨房就毁了。给宝宝一个空碗、一点水和一点面粉，说“你来揉你自己的蛋糕面团吧”。会有点乱，但宝宝的自我会得到充分满足。' WHERE id = 'baf0af3c-984e-45f1-a68f-93e13e9f1cef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Come tú solo! La rebelión 🥣', body_es = 'Aunque sabe comer solo, exige con cabezonería que le des tú de comer y luego aparta la cuchara y llora. Es la etapa de las contradicciones. No intentes darle de comer ni tengas miedo de que pase hambre. Ponle el plato delante, dile «Cuando tengas hambre, comerás» y levántate de la mesa. Comerá solo.', title_fr = 'La révolte du « Mange tout seul ! » 🥣', body_fr = 'Alors qu''il sait manger seul, il exige obstinément que vous le nourrissiez, puis repousse la cuillère en pleurant. C''est la période des contradictions. N''essayez pas de le nourrir et n''ayez pas peur qu''il ait faim. Posez l''assiette devant lui, dites « Tu mangeras quand tu auras faim » et quittez la table. Il mangera tout seul.', title_hi = '‘तुम ही खिलाओ!’ वाली बगावत 🥣', body_hi = 'खुद खा सकता है, फिर भी ज़िद करता है कि आप खिलाएँ, और फिर चम्मच धकेलकर रोने लगता है। यह विरोधाभासों का दौर है। न खिलाने की कोशिश कीजिए, न उसके भूखे रहने से डरिए। प्लेट सामने रखिए, ‘भूख लगेगी तो खा लेना’ कहकर मेज़ से उठ जाइए। वह खुद खा लेगा।', title_id = 'Pemberontakan ''Mama yang suapin!'' 🥣', body_id = 'Ia sebenarnya bisa makan sendiri, tapi bersikeras minta disuapi, lalu menepis sendoknya dan menangis. Ini masa penuh kontradiksi. Jangan berusaha menyuapinya, jangan juga takut ia kelaparan. Letakkan piring di depannya, katakan ''Kalau lapar, kamu bisa makan'', lalu tinggalkan meja. Ia akan makan sendiri.', title_ja = '「ママが食べさせて！」の反乱 🥣', body_ja = '自分で食べられるのに、食べさせてと言いはり、そのあとスプーンを押しのけて泣く。矛盾の時期です。無理に食べさせようとも、おなかがすくのを心配もしないで。お皿を前に置いて「おなかがすいたら食べてね」と言い、席を立ちましょう。自分で食べますよ。', title_ko = '''엄마가 먹어!'' 반란 🥣', body_ko = '혼자 먹을 수 있으면서도 먹여 달라고 고집하고, 막상 숟가락을 내밀면 밀어내며 우나요? 모순의 시기예요. 억지로 먹이려 하지도, 굶을까 걱정하지도 마세요. 접시를 앞에 두고 ''배고프면 먹어'' 하며 자리에서 일어나세요. 스스로 먹을 거예요.', title_nl = 'De ''Voer jij mij maar!''-opstand 🥣', body_nl = 'Hij kan zelf eten, maar eist koppig dat jij hem voert, en daarna duwt hij de lepel weg en huilt. Dit is de fase van tegenstrijdigheden. Probeer hem niet te voeren en wees niet bang dat hij honger lijdt. Zet het bord voor hem neer, zeg ''Als je honger hebt, eet je wel'' en sta op van tafel. Hij gaat zelf eten.', title_pl = 'Bunt „Jedz sam!” 🥣', body_pl = 'Choć potrafi jeść sam, uparcie żąda, żebyś go karmiła, a potem odpycha łyżkę i płacze. To okres sprzeczności. Nie próbuj go karmić i nie bój się, że będzie głodny. Postaw przed nim talerz, powiedz: „Zjesz, kiedy zgłodniejesz” i wstań od stołu. Zje sam.', title_pt = 'A revolta do "Dá-me tu de comer!" 🥣', body_pt = 'Consegue comer sozinho, mas exige teimosamente que seja a mãe a dar-lhe a comida e depois empurra a colher e chora. É a fase das contradições. Não tente dar-lhe de comer nem tenha medo de que fique com fome. Ponha-lhe o prato à frente, diga "Quando tiveres fome, comes" e levante-se da mesa. Vai comer sozinho.', title_sv = '”Du får äta själv!”-upproret 🥣', body_sv = 'Fast barnet kan äta själv kräver hen envist att du ska mata, och sedan knuffar hen bort skeden och gråter. Det här är motsägelsernas period. Försök varken mata eller oroa dig för att barnet ska bli hungrigt. Ställ tallriken framför barnet, säg ”Du äter när du blir hungrig” och res dig från bordet. Barnet äter själv.', title_vi = 'Cuộc nổi loạn "Mẹ đút cho con!" 🥣', body_vi = 'Dù tự ăn được, bé vẫn khăng khăng đòi mẹ đút, rồi lại đẩy thìa ra và khóc. Đây là giai đoạn của những mâu thuẫn. Đừng cố đút, cũng đừng sợ bé đói. Hãy đặt đĩa trước mặt bé, nói "Khi nào đói thì con ăn" và rời bàn. Bé sẽ tự ăn.', title_zh = '“你喂我！”的反抗 🥣', body_zh = '明明自己会吃，却坚持要你喂，然后又推开勺子大哭。这是充满矛盾的阶段。别硬喂，也别担心宝宝会饿着。把盘子放在宝宝面前，说一句“饿了你就会吃”，然后离开餐桌。宝宝会自己吃的。' WHERE id = 'cba9ff3e-e38f-40b7-b48d-13e030f8993a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡¿Por qué me mira el sol?! ☀️', body_es = '¿Nada más abrir los ojos por la mañana llora a moco tendido diciendo «¿Por qué el sol me mira directamente a los ojos?»? No busques lógica ni intentes explicar fenómenos naturales: solo está enfadado porque no puede controlar el mundo. Corre la cortina, dile «Te he escondido el sol» y resuelve este problema absurdo en un segundo.', title_fr = 'Pourquoi le soleil me regarde ?! ☀️', body_fr = 'Dès qu''il ouvre les yeux le matin, il sanglote : « Pourquoi le soleil me regarde droit dans les yeux ? » N''essayez pas de chercher une logique ni d''expliquer les phénomènes naturels, il est simplement furieux de ne pas pouvoir contrôler le monde. Tirez le rideau, dites « Je t''ai caché le soleil » et réglez ce problème absurde en une seconde.', title_hi = 'सूरज मुझे क्यों देख रहा है?! ☀️', body_hi = 'सुबह आँख खुलते ही ‘सूरज मेरी आँखों में क्यों देख रहा है?’ कहकर फूट-फूटकर रो रहा है? तर्क ढूँढने और प्रकृति समझाने की कोशिश मत कीजिए, वह बस इस बात से गुस्सा है कि दुनिया उसके हिसाब से नहीं चलती। पर्दा खींचिए, ‘मैंने सूरज को तुम्हारे लिए छिपा दिया’ कहिए और यह बेतुकी समस्या सेकंडों में सुलझाइए।', title_id = 'Kenapa matahari melihatku?! ☀️', body_id = 'Begitu membuka mata di pagi hari, ia menangis tersedu-sedu sambil berkata ''Kenapa matahari melihat langsung ke mataku?'' Jangan mencari logika atau mencoba menjelaskan fenomena alam, ia hanya marah karena tidak bisa mengendalikan dunia. Tutup gordennya, katakan ''Mama sudah sembunyikan mataharinya untukmu'', dan selesaikan masalah absurd ini dalam sekejap.', title_ja = 'なんでお日さまがぼくを見るの？！ ☀️', body_ja = '朝起きたとたん「なんでお日さまがぼくの目を見るの？」と大泣き？理屈を探したり自然現象を説明したりしないで。世界を思いどおりにできないことに怒っているだけです。カーテンを引いて「お日さまを隠しておいたよ」と言い、このおかしな問題をすぐに解決しましょう。', title_ko = '해님이 왜 나를 쳐다봐?! ☀️', body_ko = '아침에 눈뜨자마자 ''해님이 왜 내 눈을 똑바로 쳐다봐?'' 하며 엉엉 우나요? 논리를 찾거나 자연 현상을 설명하려 하지 마세요. 세상을 마음대로 못 해서 화가 난 것뿐이에요. 커튼을 치며 ''엄마가 해님을 숨겨 줬어'' 하고 이 엉뚱한 문제를 바로 해결하세요.', title_nl = 'Waarom kijkt de zon naar mij?! ☀️', body_nl = 'Huilt hij tranen met tuiten zodra hij ''s ochtends zijn ogen opendoet: ''Waarom kijkt de zon recht in mijn ogen?'' Zoek geen logica en leg geen natuurverschijnselen uit, hij is gewoon boos dat hij de wereld niet kan besturen. Doe het gordijn dicht, zeg ''Ik heb de zon voor je verstopt'' en los dit absurde probleem in een seconde op.', title_pl = 'Czemu słońce na mnie patrzy?! ☀️', body_pl = 'Ledwo otworzył rano oczy, a już szlocha: „Czemu słońce patrzy mi prosto w oczy?”. Nie szukaj logiki i nie tłumacz zjawisk przyrody, on po prostu złości się, że nie może rządzić światem. Zasłoń zasłony, powiedz „Schowałam dla ciebie słońce” i rozwiąż ten absurdalny problem w sekundę.', title_pt = 'Porque é que o sol está a olhar para mim?! ☀️', body_pt = 'Mal abre os olhos de manhã, chora aos soluços a dizer "Porque é que o sol me olha para os olhos?"? Não procure lógica nem tente explicar a natureza: está só zangado por não conseguir controlar o mundo. Corra a cortina, diga "Escondi o sol para ti" e resolva num segundo este problema absurdo.', title_sv = 'Varför tittar solen på mig?! ☀️', body_sv = 'Gråter barnet förtvivlat så fort hen öppnar ögonen på morgonen: ”Varför tittar solen rakt in i mina ögon?” Leta inte efter logik och försök inte förklara naturfenomen, hen är bara arg över att inte kunna styra världen. Dra för gardinen, säg ”Jag har gömt solen åt dig” och lös det absurda problemet på en sekund.', title_vi = 'Sao Mặt Trời lại nhìn con?! ☀️', body_vi = 'Vừa mở mắt buổi sáng, bé đã khóc nức nở: "Sao Mặt Trời lại nhìn thẳng vào mắt con?" Đừng tìm logic hay cố giải thích hiện tượng tự nhiên, bé chỉ tức vì không thể điều khiển thế giới. Hãy kéo rèm và nói "Mẹ giấu Mặt Trời đi cho con rồi", giải quyết vấn đề phi lý này trong tích tắc.', title_zh = '太阳为什么看着我？！☀️', body_zh = '早上一睁眼就哭着说：“太阳为什么直直地看我的眼睛？”别去找逻辑、解释自然现象，宝宝只是因为管不了这个世界而生气。拉上窗帘，说“我帮你把太阳藏起来了”，几秒钟解决这个荒诞的问题。' WHERE id = '7b9a42e6-44aa-4528-9036-fbb93f662348' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mi coche todavía no se ha dormido! 🚗', body_es = '¿Se niega a meterse en la cama diciendo «Mi coche no tiene sueño»? Los niños suelen cargar su falta de sueño y su resistencia en sus juguetes. No discutas: abre Cuentos inteligentes y crea un cuento sobre coches. En cuanto el coche se duerma, él también cerrará los ojos solo. ¡Pruébalo y verás!', title_fr = 'Ma voiture ne dort pas encore ! 🚗', body_fr = 'Pour ne pas aller au lit, il insiste : « Ma voiture n''a pas sommeil » ? Les enfants projettent souvent leur insomnie et leur résistance sur leurs jouets. Ne discutez pas, ouvrez les Contes intelligents et créez une histoire de voitures. Dès que la voiture s''endormira, il fermera les yeux automatiquement. Essayez, vous verrez !', title_hi = 'मेरी गाड़ी अभी सोई नहीं! 🚗', body_hi = 'बिस्तर पर न जाने के लिए ‘मेरी गाड़ी को नींद नहीं आ रही’ कहकर अड़ा है? बच्चे अक्सर अपनी बेचैनी और ज़िद अपने खिलौनों पर डाल देते हैं। बहस मत कीजिए, स्मार्ट कहानियाँ खोलिए और गाड़ियों के बारे में कहानी बनाइए। जैसे ही गाड़ी सोएगी, वह भी अपने आप आँखें बंद कर लेगा। आज़माकर देखिए!', title_id = 'Mobilku belum tidur! 🚗', body_id = 'Ia bersikeras tidak mau naik ke tempat tidur dengan alasan ''Mobilku belum mengantuk''? Anak sering memindahkan rasa tidak mengantuk dan perlawanannya pada mainan. Jangan berdebat, buka Dongeng Pintar dan buat dongeng tentang mobil. Begitu mobilnya tertidur, ia pun otomatis akan memejamkan mata. Coba dan lihat!', title_ja = 'ぼくの車はまだ寝てないよ！ 🚗', body_ja = '寝ないために「ぼくの車が眠くないって」とがんばる？子どもは眠れない気持ちや抵抗を、よくおもちゃに投影します。言い合いはせず、「スマートおはなし」を開いて車のお話をつくりましょう。車が眠ったら、この子も自然に目を閉じます。ためしてみて！', title_ko = '내 자동차가 아직 안 잤어! 🚗', body_ko = '''내 자동차가 안 졸리대'' 하며 침대에 안 들어가려 버티나요? 아이들은 잠 못 드는 마음과 고집을 장난감에 담곤 해요. 다투지 말고 스마트 동화를 열어 자동차 이야기를 만들어 보세요. 자동차가 잠들면 아이도 저절로 눈을 감을 거예요. 해 보세요!', title_nl = 'Mijn auto slaapt nog niet! 🚗', body_nl = 'Houdt hij vol ''Mijn auto heeft nog geen slaap'' om niet naar bed te hoeven? Kinderen schuiven hun slapeloosheid en verzet vaak af op hun speelgoed. Ga niet in discussie, open Slimme sprookjes en maak een sprookje over auto''s. Zodra de auto in slaap valt, gaan zijn ogen vanzelf ook dicht. Probeer het maar!', title_pl = 'Moje auto jeszcze nie śpi! 🚗', body_pl = 'Upiera się, że nie pójdzie do łóżka, bo „Moje auto nie jest śpiące”? Dzieci często przenoszą własną bezsenność i opór na zabawki. Nie kłóć się, otwórz Mądre bajki i stwórz bajkę o samochodach. Gdy tylko auto zaśnie, on też automatycznie zamknie oczy. Spróbuj i zobacz!', title_pt = 'O meu carro ainda não dormiu! 🚗', body_pt = 'Para não ir para a cama, insiste: "O meu carro não tem sono"? As crianças põem muitas vezes a sua falta de sono e a sua resistência nos brinquedos. Não discuta: abra as Histórias Inteligentes e crie uma história sobre carros. Mal o carro adormecer, ele também fecha os olhos automaticamente. Experimente e veja!', title_sv = 'Min bil har inte somnat än! 🚗', body_sv = 'Protesterar barnet mot att gå och lägga sig med ”Min bil är inte trött”? Barn lägger ofta sin egen sömnlöshet och sitt motstånd på leksakerna. Bråka inte, öppna Smarta sagor och skapa en saga om bilar. Så fort bilen somnar blundar barnet automatiskt också. Prova och se!', title_vi = 'Xe của con chưa ngủ! 🚗', body_vi = 'Bé không chịu lên giường vì "Xe của con chưa buồn ngủ"? Trẻ thường gán việc khó ngủ và sự chống đối của mình cho đồ chơi. Đừng tranh cãi, hãy mở Truyện cổ tích thông minh và tạo một câu chuyện về những chiếc xe. Xe vừa ngủ, bé cũng sẽ tự nhắm mắt. Thử xem!', title_zh = '我的小汽车还没睡呢！🚗', body_zh = '为了不上床，坚持说“我的小汽车还不困”？孩子常常把自己的不想睡和抵抗投射到玩具上。别争了，打开智慧童话，创作一个关于小汽车的故事。小汽车一睡着，宝宝也会自动闭上眼睛。试试看！' WHERE id = 'bf33243a-24ca-4b24-a11a-d703c038cdcf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Que le quiten la corteza al pan! 🍞', body_es = '¿De la tostada solo se come la parte blanda y rechaza con firmeza los bordes? Esta edad tiene una estética visual muy particular. Aprende a cortar el pan con formas de animalitos. El diseño acabará con esta pelea al instante.', title_fr = 'Enlevez la croûte du pain ! 🍞', body_fr = 'Il ne mange que la partie moelleuse du toast et refuse fermement les bords ? Cet âge a une esthétique visuelle bien à lui. Apprenez à découper le pain en jolies formes d''animaux. Le design mettra fin à cette dispute instantanément.', title_hi = 'ब्रेड के किनारे काट दो! 🍞', body_hi = 'टोस्ट का सिर्फ़ नरम हिस्सा खाकर किनारे पक्के इरादे से ठुकरा देता है? इस उम्र का अपना खास दिखावटी सौंदर्य होता है। ब्रेड को प्यारे जानवरों के आकार में काटना सीखिए। डिज़ाइन यह लड़ाई तुरंत खत्म कर देगा।', title_id = 'Potong pinggiran rotinya! 🍞', body_id = 'Ia hanya memakan bagian lembut roti panggang dan dengan tegas menolak pinggirannya? Usia ini punya estetika visual tersendiri. Pelajari cara memotong roti menjadi bentuk hewan yang lucu. Desain akan langsung mengakhiri pertengkaran ini.', title_ja = 'パンの耳を切って！ 🍞', body_ja = 'トーストのやわらかいところだけ食べて、耳はきっぱり拒否？この年齢には独特の見た目の美学があります。パンをかわいい動物の形に切ってみましょう。デザインがこのけんかをすぐに終わらせます。', title_ko = '빵 테두리는 잘라 줘! 🍞', body_ko = '토스트의 부드러운 부분만 먹고 테두리는 단호하게 거부하나요? 이 나이만의 시각적 미학이 있어요. 빵을 귀여운 동물 모양으로 자르는 법을 익혀 보세요. 디자인이 이 다툼을 단번에 끝내 줄 거예요.', title_nl = 'Korstjes eraf! 🍞', body_nl = 'Eet hij alleen het zachte deel van zijn toast en weigert hij de randjes beslist? Deze leeftijd heeft een eigen visuele smaak. Leer het brood in schattige dierenvormen te snijden. Het ontwerp maakt meteen een einde aan deze ruzie.', title_pl = 'Odkrój skórkę od chleba! 🍞', body_pl = 'Zjada tylko miękki środek tosta, a brzegi stanowczo odrzuca? W tym wieku dzieci mają swoją szczególną estetykę wizualną. Naucz się wycinać chleb w kształty uroczych zwierzątek. Design od razu zakończy tę wojnę.', title_pt = 'Tira-me a côdea do pão! 🍞', body_pt = 'Come só a parte mole da torrada e recusa firmemente as bordas? Esta idade tem uma estética visual muito própria. Aprenda a cortar o pão em formas de animais fofos. O design acaba com esta guerra num instante.', title_sv = 'Skär bort skorpan! 🍞', body_sv = 'Äter barnet bara den mjuka delen av rostbrödet och vägrar bestämt kanterna? Den här åldern har sin egen visuella estetik. Lär dig skära brödet i söta djurformer. Designen avslutar bråket direkt.', title_vi = 'Cắt vỏ bánh mì đi! 🍞', body_vi = 'Bé chỉ ăn phần mềm của lát bánh mì nướng và kiên quyết chê phần viền? Tuổi này có "thẩm mỹ thị giác" riêng. Hãy học cách cắt bánh mì thành hình những con vật đáng yêu. Một chút thiết kế sẽ kết thúc cuộc chiến này ngay lập tức.', title_zh = '面包边要切掉！🍞', body_zh = '吐司只吃软的部分，坚决不吃边？这个年龄有自己独特的视觉审美。学着把面包切成可爱的动物形状吧。造型设计会立刻结束这场争执。' WHERE id = '5c063277-1aff-4166-9dbe-d6ab5866cdbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El placer de mirarse en silencio 🥂', body_es = 'El peque duerme y la casa está recogida. Siéntate en el sofá junto a tu pareja, sin encender siquiera la tele. Solo miraos con esa mirada de «hoy también hemos sobrevivido». Créeme, este es el momento más romántico y auténtico de unos padres cansados.', title_fr = 'Le plaisir d''un regard silencieux 🥂', body_fr = 'L''enfant dort, la maison est rangée. Asseyez-vous côte à côte sur le canapé avec votre partenaire, sans même allumer la télé. Échangez simplement ce regard qui dit « On a encore survécu aujourd''hui ». Croyez-moi, voilà le moment le plus romantique et le plus vrai de la vie de parents fatigués.', title_hi = 'खामोश नज़रों का मज़ा 🥂', body_hi = 'बच्चा सो गया, घर समेट लिया। अपने साथी के साथ सोफ़े पर पास-पास बैठिए, टीवी भी मत चलाइए। बस एक-दूसरे को ‘आज भी बच गए’ वाली नज़र से देखिए। यकीन मानिए, थकी हुई पेरेंटिंग का सबसे रोमांटिक और सच्चा पल यही है।', title_id = 'Nikmatnya saling pandang dalam diam 🥂', body_id = 'Anak sudah tidur, rumah sudah rapi. Duduklah berdampingan dengan pasangan di sofa, bahkan tanpa menyalakan TV. Cukup saling bertukar tatapan ''hari ini pun kita bertahan''. Percayalah, inilah momen paling romantis dan nyata bagi orang tua yang lelah.', title_ja = '静かに見つめ合う幸せ 🥂', body_ja = '子どもは寝て、家も片づいた。パートナーとソファに並んで座り、テレビもつけないで。ただ「今日も乗りきったね」という視線を交わしましょう。それこそが、疲れた子育ての中のいちばんロマンチックで本当の瞬間です。', title_ko = '말 없는 눈빛의 행복 🥂', body_ko = '아이는 잠들고 집도 정리됐어요. 배우자와 소파에 나란히 앉아 TV도 켜지 마세요. 그저 ''오늘도 살아남았다''는 눈빛을 서로 나누세요. 이게 바로 지친 육아 속 가장 로맨틱하고 진짜인 순간이에요.', title_nl = 'Het genot van een stille blik 🥂', body_nl = 'Je kind slaapt, het huis is opgeruimd. Ga met je partner naast elkaar op de bank zitten, zet zelfs de tv niet aan. Geef elkaar gewoon die blik van ''ook vandaag hebben we het overleefd''. Geloof ons, dit is het meest romantische en echte moment van vermoeid ouderschap.', title_pl = 'Urok spojrzeń w ciszy 🥂', body_pl = 'Dziecko śpi, dom posprzątany. Usiądź z partnerem obok siebie na kanapie, nawet nie włączajcie telewizora. Po prostu wymieńcie spojrzenia mówiące „dziś też przetrwaliśmy”. Uwierz, to właśnie najbardziej romantyczna i prawdziwa chwila zmęczonego rodzicielstwa.', title_pt = 'O prazer de um olhar em silêncio 🥂', body_pt = 'A criança adormeceu, a casa está arrumada. Sente-se no sofá ao lado do seu companheiro, nem sequer ligue a televisão. Troquem apenas aquele olhar de "hoje também sobrevivemos". Acredite, é este o momento mais romântico e verdadeiro de uma parentalidade cansada.', title_sv = 'Njutningen i en tyst blick 🥂', body_sv = 'Barnet sover, huset är städat. Sätt dig bredvid din partner i soffan och slå inte ens på tv:n. Ge bara varandra blicken som säger ”vi överlevde i dag också”. Tro mig, det är det trötta föräldraskapets mest romantiska och äkta stund.', title_vi = 'Niềm vui của ánh nhìn lặng lẽ 🥂', body_vi = 'Bé đã ngủ, nhà đã dọn. Hãy ngồi cạnh chồng trên sofa, thậm chí đừng bật TV. Chỉ cần trao nhau ánh mắt "Hôm nay mình lại sống sót rồi". Tin đi, đó chính là khoảnh khắc lãng mạn và chân thật nhất của những bậc cha mẹ mệt mỏi.', title_zh = '无声对视的美好 🥂', body_zh = '宝宝睡了，家也收拾好了。和另一半并肩坐在沙发上，连电视都别开。只要彼此对视一眼：“今天我们也挺过来了。”相信我，这就是疲惫的为人父母最浪漫、最真实的时刻。' WHERE id = 'a42141c6-7a93-4719-be36-e495b333ffee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tragedia de la mancha invisible 👕', body_es = '¿Ha encontrado en la camiseta una mancha que solo se ve con microscopio y se niega a ponérsela? Haz como que la limpias con una toallita húmeda y dile «La he hecho desaparecer con magia». El cerebro de un niño siempre cree en la magia de mamá. ¡Pruébalo y verás!', title_fr = 'La tragédie de la tache invisible 👕', body_fr = 'Il a trouvé sur son t-shirt une tache visible seulement au microscope et refuse de le porter ? Faites semblant de l''essuyer avec une lingette et dites : « Je l''ai fait disparaître par magie. » Le cerveau d''un enfant croit toujours à la magie de sa maman, essayez et vous verrez.', title_hi = 'अदृश्य दाग की त्रासदी 👕', body_hi = 'कमीज़ पर ऐसा दाग ढूँढ लिया जो सिर्फ़ माइक्रोस्कोप से दिखे, और पहनने से मना कर दिया? उस दाग को वेट वाइप से दिखावे के लिए पोंछिए और कहिए, ‘जादू से गायब कर दिया।’ बच्चे का दिमाग माँ के जादू पर हमेशा भरोसा करता है, आज़माकर देखिए।', title_id = 'Tragedi noda tak kasatmata 👕', body_id = 'Ia menemukan noda di bajunya yang hanya terlihat dengan mikroskop dan menolak memakainya? Pura-pura usap noda itu dengan tisu basah dan katakan ''Mama sudah menghilangkannya dengan sihir''. Otak anak selalu percaya pada sihir ibunya, coba dan lihat.', title_ja = '見えないシミの悲劇 👕', body_ja = '顕微鏡でしか見えないようなシミをシャツに見つけて、着るのを拒否？そのシミをウェットティッシュで拭くふりをして「魔法で消したよ」と言いましょう。子どもの脳は、いつもママの魔法を信じています。ためしてみて。', title_ko = '보이지 않는 얼룩의 비극 👕', body_ko = '현미경으로나 보일 만한 얼룩을 찾아내고 옷을 안 입겠다고 하나요? 물티슈로 그 얼룩을 닦는 척하며 ''마법으로 없앴어''라고 말해 주세요. 아이는 엄마의 마법을 언제나 믿어요. 해 보세요.', title_nl = 'Het drama van de onzichtbare vlek 👕', body_nl = 'Weigert hij zijn shirt aan te trekken omdat hij een vlek heeft gevonden die je alleen met een microscoop ziet? Veeg de vlek voor de show weg met een vochtig doekje en zeg ''Ik heb hem weggetoverd''. Een kinderbrein gelooft altijd in mama''s magie, probeer het maar.', title_pl = 'Dramat niewidzialnej plamy 👕', body_pl = 'Znalazł na koszulce plamę widoczną tylko pod mikroskopem i nie chce jej włożyć? Udawaj, że ścierasz ją nawilżaną chusteczką, i powiedz „Usunęłam ją czarami”. Dziecięcy mózg zawsze wierzy w magię mamy, spróbuj i zobacz.', title_pt = 'A tragédia da mancha invisível 👕', body_pt = 'Encontrou na camisola uma mancha que só se vê ao microscópio e recusou-se a vesti-la? Finja que limpa a mancha com um toalhete húmido e diga "Fi-la desaparecer por magia". O cérebro da criança acredita sempre na magia da mãe, experimente e veja.', title_sv = 'Tragedin med den osynliga fläcken 👕', body_sv = 'Vägrar barnet ta på sig tröjan för att hen hittat en fläck som bara syns i mikroskop? Låtsas torka bort fläcken med en våtservett och säg ”Jag trollade bort den”. Barnhjärnan tror alltid på mammas magi, prova och se.', title_vi = 'Thảm họa vết bẩn vô hình 👕', body_vi = 'Bé không chịu mặc áo vì tìm thấy một vết bẩn chỉ nhìn được bằng kính hiển vi? Hãy giả vờ lau vết bẩn bằng khăn ướt và nói "Mẹ dùng phép thuật làm nó biến mất rồi". Não trẻ luôn tin vào phép thuật của mẹ, thử xem nhé.', title_zh = '看不见的污渍惨案 👕', body_zh = '在衣服上发现一块只有显微镜才看得见的污渍，就不肯穿了？用湿巾假装擦一擦，说“我用魔法把它变没了”。孩子的大脑永远相信妈妈的魔法，试试看。' WHERE id = 'fbd48b54-2407-4752-a5b5-4e335233ace4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Dame el agua en otro vaso! 🥤', body_es = '¿Se ha armado una buena porque le has dado el agua en el vaso amarillo? No le des más vueltas, solo está poniendo a prueba sus límites. Échale el agua en el vaso que quiere en un segundo, pon paz en la habitación y guarda tu energía para el resto del día.', title_fr = 'Donne l''eau dans un autre verre ! 🥤', body_fr = 'C''est l''apocalypse parce que vous avez servi l''eau dans le verre jaune ? Ne cherchez pas plus loin, il teste juste ses limites. Versez aussitôt l''eau dans le verre qu''il veut, rétablissez la paix et gardez votre énergie pour le reste de la journée.', title_hi = 'पानी दूसरे गिलास में दो! 🥤', body_hi = 'पानी पीले गिलास में दिया, इसलिए कमरे में तूफ़ान आ गया? ज़्यादा मत सोचिए, वह बस अपनी सीमाएँ परख रहा है। फ़ौरन पानी उसके मनचाहे गिलास में डाल दीजिए, कमरे में शांति लौटाइए और अपनी ऊर्जा बाकी दिन के लिए बचाइए।', title_id = 'Kasih airnya di gelas lain! 🥤', body_id = 'Kiamat terjadi di kamar karena Anda memberinya air di gelas kuning? Jangan terlalu dipikirkan, ia hanya sedang menguji batasannya. Segera tuang airnya ke gelas yang ia mau, kembalikan kedamaian di kamar, dan simpan energi Anda untuk sisa hari ini.', title_ja = 'お水はちがうコップで！ 🥤', body_ja = '黄色いコップでお水を出したから、部屋は大さわぎ？深く考えないで。境界線をためしているだけです。すぐにこの子の好きなコップに入れなおして部屋に平和をとり戻し、残りの一日のためにエネルギーを守りましょう。', title_ko = '물은 다른 컵에 줘! 🥤', body_ko = '물을 노란 컵에 줬다고 방이 난리가 났나요? 깊이 생각하지 마세요, 경계를 시험하는 것뿐이에요. 바로 아이가 원하는 컵에 물을 옮겨 담아 평화를 되찾고, 남은 하루를 위해 에너지를 아끼세요.', title_nl = 'Geef water in een andere beker! 🥤', body_nl = 'Breekt de hel los omdat je zijn water in een gele beker gaf? Denk er niet te veel over na, hij test gewoon zijn grenzen. Schenk het water meteen in de beker die hij wil, breng de vrede terug en spaar je energie voor de rest van de dag.', title_pl = 'Podaj wodę w innym kubku! 🥤', body_pl = 'W pokoju wybuchła awantura, bo podałaś wodę w żółtym kubku? Nie analizuj, on po prostu sprawdza granice. Od razu przelej wodę do kubka, który chce, przywróć spokój i zachowaj energię na resztę dnia.', title_pt = 'Dá-me a água noutro copo! 🥤', body_pt = 'Caiu o Carmo e a Trindade porque lhe deu a água num copo amarelo? Não pense demasiado: está só a testar limites. Deite logo a água no copo que ele quer, restabeleça a paz no quarto e guarde a sua energia para o resto do dia.', title_sv = 'Ge mig vattnet i ett annat glas! 🥤', body_sv = 'Utbryter världens undergång för att du serverade vattnet i det gula glaset? Gå inte på djupet, barnet testar bara sina gränser. Häll genast över vattnet i det glas hen vill ha, skapa fred i rummet och spara din energi till resten av dagen.', title_vi = 'Đưa nước bằng cốc khác cơ! 🥤', body_vi = 'Cả phòng như "tận thế" chỉ vì mẹ đưa nước bằng cốc màu vàng? Đừng nghĩ nhiều, bé chỉ đang thử giới hạn thôi. Rót ngay nước sang chiếc cốc bé muốn, lập lại hòa bình trong phòng và giữ sức cho phần còn lại của ngày.', title_zh = '换个杯子倒水！🥤', body_zh = '因为用黄杯子倒水，房间里就闹翻天了？别想太多，宝宝只是在试探底线。马上把水倒进宝宝想要的杯子，让房间恢复和平，把精力留给接下来的一天。' WHERE id = '081fe93d-51fc-4e73-b956-ea2d06dcec72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica de la carrera para salir del parque 🌳', body_es = 'Es hora de volver del parque y empiezan las crisis de llanto. Llevarlo a rastras no va a funcionar. Dile «¿A ver quién llega antes al coche andando como un pingüino?» y lleva su atención enseguida a una competición divertida. Seguro que querrá ganar.', title_fr = 'La tactique de la course pour quitter le parc 🌳', body_fr = 'C''est l''heure de rentrer du parc et les crises de larmes ont commencé. Le traîner ne servira à rien. Dites : « Voyons qui arrivera le premier à la voiture en marchant comme un pingouin ! » et détournez aussitôt son attention vers une course rigolote. Il voudra absolument gagner.', title_hi = 'पार्क से निकलने की मुकाबले वाली तरकीब 🌳', body_hi = 'पार्क से लौटने का समय हो गया और रोना शुरू हो गया है। उसे घसीटकर ले जाना काम नहीं करेगा। ‘चलो देखें, गाड़ी तक पेंगुइन की तरह कौन जल्दी पहुँचता है?’ कहकर उसका ध्यान तुरंत एक मज़ेदार मुकाबले पर ले जाइए। वह ज़रूर जीतना चाहेगा।', title_id = 'Taktik lomba untuk pulang dari taman 🌳', body_id = 'Sudah waktunya pulang dari taman dan krisis tangisan dimulai. Menyeretnya tidak akan berhasil. Katakan ''Yuk lihat, siapa yang paling cepat jalan seperti penguin sampai mobil?'' dan segera alihkan perhatiannya ke lomba yang lucu. Ia pasti ingin menang.', title_ja = '公園から帰るための競争作戦 🌳', body_ja = '公園から帰る時間になって、泣きわめき始めた。引きずって連れていってもうまくいきません。「車までペンギン歩きでどっちが早く行けるかな？」と言って、すぐにおもしろい競争に気をそらしましょう。きっと勝ちたくなりますよ。', title_ko = '공원에서 나오는 시합 작전 🌳', body_ko = '공원에서 돌아갈 시간인데 울음 폭발이 시작됐나요? 끌고 가는 건 소용없어요. ''차까지 누가 더 빨리 펭귄처럼 걸어갈까?'' 하며 바로 재미있는 시합으로 관심을 돌리세요. 아이는 꼭 이기고 싶어 할 거예요.', title_nl = 'De wedstrijdtactiek om het park te verlaten 🌳', body_nl = 'Het is tijd om naar huis te gaan en de huilbuien zijn begonnen. Hem meeslepen werkt niet. Zeg: ''Wie loopt er het snelst als een pinguïn naar de auto?'' en richt zijn aandacht meteen op een grappige wedstrijd. Hij wil vast winnen.', title_pl = 'Taktyka rywalizacji przy wyjściu z parku 🌳', body_pl = 'Pora wracać z parku i zaczęły się płaczliwe kryzysy. Ciągnięcie go siłą nic nie da. Zapytaj: „Zobaczmy, kto szybciej dojdzie do auta jak pingwin?” i od razu przekieruj jego uwagę na zabawną rywalizację. Na pewno będzie chciał wygrać.', title_pt = 'A tática da competição para sair do parque 🌳', body_pt = 'É hora de voltar do parque e começaram as crises de choro. Levá-lo arrastado não vai resultar. Desvie logo a atenção dele para uma competição divertida: "Vamos ver quem chega mais depressa ao carro a andar como um pinguim?" Ele vai querer ganhar de certeza.', title_sv = 'Tävlingstaktiken för att lämna parken 🌳', body_sv = 'Det är dags att gå hem från parken och gråtkriserna har börjat. Att släpa iväg barnet fungerar inte. Säg ”Vi ser vem som först kommer till bilen gående som en pingvin!” och led genast om uppmärksamheten till en rolig tävling. Barnet kommer absolut att vilja vinna.', title_vi = 'Chiến thuật thi đua để rời công viên 🌳', body_vi = 'Đến giờ rời công viên và cơn khóc lóc bắt đầu. Kéo lê bé đi sẽ không có tác dụng. Hãy nói "Xem ai đi kiểu chim cánh cụt ra xe nhanh hơn nào?" để chuyển ngay sự chú ý của bé sang một cuộc thi vui nhộn. Bé chắc chắn sẽ muốn thắng.', title_zh = '离开公园的比赛战术 🌳', body_zh = '该从公园回家了，哭闹开始了。硬拖着走没有用。说一句“我们看看谁能像企鹅一样先走到车边？”，马上把注意力引到一场搞笑的比赛上。宝宝一定会想赢。' WHERE id = '12e39cd9-ad30-497d-8902-0c8e0d1a5c56' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lucha en el sofá con papá 🤼‍♂️', body_es = '¿Ha salido corriendo a esconderse para no irse a la cama? Pásale la pelota a papá. Que hagan una lucha de mentira en el sofá. Ese juego ruidoso y sudoroso le quitará hasta la última gota de energía rebelde y lo rendirá al sueño sin esfuerzo.', title_fr = 'Lutte sur le canapé avec papa 🤼‍♂️', body_fr = 'Il s''est enfui et caché pour ne pas aller au lit ? Passez la balle à papa. Qu''ils fassent semblant de lutter. Ce jeu bruyant et transpirant aspirera ses dernières réserves d''énergie têtue et le livrera facilement au sommeil.', title_hi = 'पापा के साथ सोफ़े पर कुश्ती 🤼‍♂️', body_hi = 'सोने न जाने के लिए भागकर छिप गया? गेंद पापा के पाले में डालिए। उन्हें सोफ़े पर नकली कुश्ती करने दीजिए। यह शोर-शराबे वाला, पसीना छुड़ाने वाला खेल बच्चे की आखिरी ज़िद्दी ऊर्जा भी सोख लेगा और उसे आसानी से नींद के हवाले कर देगा।', title_id = 'Gulat di sofa bersama Ayah 🤼‍♂️', body_id = 'Ia lari dan bersembunyi supaya tidak tidur? Oper bolanya ke Ayah. Biarkan mereka gulat pura-pura di sofa. Permainan heboh yang bikin berkeringat ini akan menyedot sisa energi keras kepalanya dan membuatnya mudah menyerah pada kantuk.', title_ja = 'パパとソファでレスリング 🤼‍♂️', body_ja = '寝たくなくて逃げて隠れた？ボールはパパにパス。ソファでレスリングごっこをしてもらいましょう。にぎやかで汗をかく遊びが、最後のがんこなエネルギーまで使いきって、すんなり眠りへと導いてくれます。', title_ko = '아빠와 소파 레슬링 🤼‍♂️', body_ko = '자러 가기 싫어서 도망쳐 숨었나요? 공을 아빠에게 넘기세요. 장난 레슬링을 하게 두세요. 시끌벅적하고 땀나는 놀이가 마지막 남은 고집스러운 에너지까지 빼내 쉽게 잠에 항복하게 할 거예요.', title_nl = 'Stoeien op de bank met papa 🤼‍♂️', body_nl = 'Is hij weggerend en verstopt om niet naar bed te hoeven? Speel de bal door naar papa. Laat ze op de bank een nepworstelpartij houden. Dat luidruchtige, bezwete spel zuigt zijn laatste koppige energie op en laat hem makkelijk in slaap vallen.', title_pl = 'Zapasy z tatą na kanapie 🤼‍♂️', body_pl = 'Uciekł i schował się, żeby nie iść spać? Przekaż piłeczkę tacie. Niech pobawią się w udawane zapasy. Ta głośna, męcząca zabawa wyssie z dziecka resztki upartej energii i łatwo odda je we władanie snu.', title_pt = 'Luta no sofá com o pai 🤼‍♂️', body_pt = 'Fugiu e escondeu-se para não ir para a cama? Passe a bola ao pai. Que façam uma luta a fingir junto à parede. Essa brincadeira barulhenta e suada vai gastar a última energia teimosa e entregá-lo facilmente ao sono.', title_sv = 'Soffbrottning med pappa 🤼‍♂️', body_sv = 'Sprang barnet iväg och gömde sig för att slippa gå och lägga sig? Skicka bollen till pappa. Låt dem låtsasbrottas i soffan. Den högljudda, svettiga leken suger ut barnets sista envisa energi och får hen att lätt ge upp för sömnen.', title_vi = 'Đấu vật trên sofa cùng bố 🤼‍♂️', body_vi = 'Bé chạy trốn để khỏi phải đi ngủ? Hãy chuyền bóng cho bố. Để hai bố con vật nhau "giả vờ" bên tường. Trò chơi ồn ào, đẫm mồ hôi ấy sẽ rút cạn chút năng lượng bướng bỉnh cuối cùng và đưa bé vào giấc ngủ thật dễ dàng.', title_zh = '和爸爸在沙发上摔跤 🤼‍♂️', body_zh = '为了不去睡觉，跑去躲起来了？把球传给爸爸。让他们假装摔跤。这场又吵又出汗的游戏，会把宝宝最后那点倔强的能量耗光，让宝宝轻松入睡。' WHERE id = 'ec5e51b0-e017-4226-9363-9dfff1dce391' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El efecto hipnótico de la música 🎶', body_es = 'Prueba a cortar con música clásica suave las tormentas sin motivo que estallan al atardecer. Apaga la tele. Muchas veces este truco tan sencillo, con su frecuencia profunda, tapa el ruido y trae a la habitación una calma casi milagrosa.', title_fr = 'L''effet hypnotique de la musique 🎶', body_fr = 'Essayez de calmer les tempêtes sans raison de fin de journée avec une musique classique douce. Éteignez la télé. Très souvent, cette astuce toute simple couvre le bruit grâce à sa fréquence profonde et apporte comme par miracle le calme dans la pièce.', title_hi = 'संगीत का सम्मोहक असर 🎶', body_hi = 'शाम को बिना वजह उठने वाले तूफ़ानों को हल्के शास्त्रीय संगीत से रोककर देखिए। टीवी बंद कीजिए। अक्सर यह आसान तरकीब, वह गहरी धुन, शोर को दबा देती है और कमरे में किसी चमत्कार की तरह शांति ले आती है।', title_id = 'Efek hipnosis musik 🎶', body_id = 'Coba redakan badai tanpa sebab menjelang malam dengan musik klasik yang lembut. Matikan TV. Sering kali trik sederhana ini, dengan frekuensinya yang dalam, meredam kebisingan dan entah bagaimana membawa ketenangan ajaib ke dalam kamar.', title_ja = '音楽の催眠効果 🎶', body_ja = '夕方に理由もなく起きる嵐を、静かなクラシック音楽でしずめてみましょう。テレビは消して。このシンプルな工夫で、深い周波数が騒音をかき消し、部屋にふしぎな落ち着きが訪れることがよくあります。', title_ko = '음악의 최면 효과 🎶', body_ko = '저녁 무렵 이유 없이 터지는 폭풍을 잔잔한 클래식 음악으로 잠재워 보세요. TV는 끄고요. 이 간단한 비법이 깊은 주파수로 소음을 덮고, 방 안에 신기할 만큼 고요함을 가져다주는 경우가 많아요.', title_nl = 'Het hypnotiserende effect van muziek 🎶', body_nl = 'Probeer de onverklaarbare stormen aan het eind van de middag te temperen met rustige klassieke muziek. Zet de tv uit. Vaak overstemt dit simpele trucje het lawaai met zijn diepe klanken en brengt het op wonderlijke wijze rust in de kamer.', title_pl = 'Efekt muzycznej hipnozy 🎶', body_pl = 'Spróbuj przerwać wieczorne burze bez powodu lekką muzyką klasyczną. Wyłącz telewizor. Ta prosta sztuczka często zagłusza hałas głęboką częstotliwością i w jakiś cudowny sposób wprowadza do pokoju spokój.', title_pt = 'O efeito hipnótico da música 🎶', body_pt = 'Experimente cortar as tempestades sem razão do fim da tarde com música clássica suave. Desligue a televisão. Muitas vezes este truque simples abafa o barulho com aquela frequência profunda e traz ao quarto uma calma quase milagrosa.', title_sv = 'Musikalisk hypnoseffekt 🎶', body_sv = 'Prova att bryta kvällens omotiverade stormar med lätt klassisk musik. Stäng av tv:n. Ofta dränker det här enkla tricket oljudet med sin djupa frekvens och ger rummet ett nästan magiskt lugn.', title_vi = 'Hiệu ứng thôi miên của âm nhạc 🎶', body_vi = 'Hãy thử dập tắt những cơn bão vô cớ lúc chiều tối bằng chút nhạc cổ điển nhẹ nhàng. Tắt TV đi. Thường thì mẹo đơn giản này, với tần số trầm sâu, sẽ át đi tiếng ồn và mang lại sự yên bình kỳ diệu cho căn phòng.', title_zh = '音乐催眠效应 🎶', body_zh = '傍晚莫名其妙的情绪风暴，试试用轻柔的古典音乐来化解。关掉电视。很多时候，这个简单的小技巧能盖过那些低频噪音，给房间带来一种神奇的平静。' WHERE id = '01fb525b-af8a-41d4-8fd1-724d4fd01667' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las palabras que se inventa 🗣️', body_es = 'Construye frases curiosas como «El cielo ha llorado» o «El coche se ha enfadado». Su vocabulario crece como una tormenta y juega con las palabras. Abre el Seguimiento del desarrollo y archiva esta filosofía tierna y poética: dentro de unos años os reiréis mucho leyéndola.', title_fr = 'Les mots qu''il invente 🗣️', body_fr = 'Il construit des phrases étranges comme « Le ciel a pleuré » ou « La voiture boude ». Son vocabulaire grandit à toute vitesse et il joue avec les mots. Ouvrez le Suivi de développement et archivez cette douce philosophie poétique : dans quelques années, vous en rirez beaucoup en la relisant.', title_hi = 'उसके खुद गढ़े हुए शब्द 🗣️', body_hi = '‘आसमान रो पड़ा’, ‘गाड़ी रूठ गई’ जैसे अनोखे वाक्य बनाता है। उसकी शब्दावली तूफ़ान की तरह बढ़ रही है और वह शब्दों से खेल रहा है। ग्रोथ ट्रैकर खोलिए और उसका यह प्यारा, काव्यात्मक फ़लसफ़ा सहेज लीजिए, सालों बाद पढ़कर आप खूब हँसेंगे।', title_id = 'Kata-kata karangannya sendiri 🗣️', body_id = 'Ia menyusun kalimat aneh seperti ''Langit menangis'' atau ''Mobilnya ngambek''. Kosakatanya tumbuh seperti badai dan ia bermain dengan kata-kata. Buka Pelacak Perkembangan dan arsipkan filsafat puitisnya yang manis ini, bertahun-tahun lagi kalian akan tertawa membacanya.', title_ja = '自分でつくったことば 🗣️', body_ja = '「お空が泣いた」「車がすねた」のような、ふしぎな文をつくる。語彙が嵐のように増えて、ことばで遊んでいます。「発達トラッカー」を開いて、このかわいくて詩的な哲学を記録しておきましょう。何年も後に読んで、きっと大笑いしますよ。', title_ko = '스스로 지어낸 말들 🗣️', body_ko = '''하늘이 울었어'', ''자동차가 삐졌어'' 같은 독특한 문장을 만드나요? 어휘가 폭풍처럼 늘고 말을 가지고 놀고 있어요. 성장 기록을 열고 이 귀엽고 시적인 철학을 보관해 두세요. 몇 년 뒤 읽으며 실컷 웃게 될 거예요.', title_nl = 'Zelfverzonnen woorden 🗣️', body_nl = 'Maakt hij vreemde zinnen als ''De lucht huilde'' of ''De auto is boos''? Zijn woordenschat groeit razendsnel en hij speelt met woorden. Open de Groeitracker en bewaar zijn lieve, poëtische filosofie in het archief, over een paar jaar lees je het terug en lachen jullie je slap.', title_pl = 'Słowa jego własnego wymysłu 🗣️', body_pl = 'Układa dziwne zdania w stylu „Niebo płakało” czy „Auto się obraziło”. Jego słownictwo rośnie jak burza, a on bawi się słowami. Otwórz Śledzenie rozwoju i dodaj do archiwum tę słodką, poetycką filozofię, za kilka lat będziecie się z niej śmiać do łez.', title_pt = 'Palavras inventadas por ele 🗣️', body_pt = 'Constrói frases estranhas como "O céu chorou" ou "O carro amuou". O vocabulário cresce como uma tempestade e ele brinca com as palavras. Abra o Registo de Crescimento e arquive esta filosofia doce e poética: daqui a uns anos vão rir-se muito ao lê-la.', title_sv = 'Egna påhittade ord 🗣️', body_sv = 'Barnet bygger konstiga meningar som ”Himlen grät” och ”Bilen blev sur”. Ordförrådet växer som en storm och hen leker med orden. Öppna Utvecklingsspåraren och spara den söta, poetiska filosofin, om många år kommer ni att skratta gott när ni läser den.', title_vi = 'Những từ bé tự nghĩ ra 🗣️', body_vi = 'Bé tạo ra những câu nói lạ như "Bầu trời khóc", "Xe ô tô dỗi rồi". Vốn từ của bé lớn lên như vũ bão và bé đang chơi đùa với ngôn từ. Hãy mở Theo dõi phát triển và lưu lại "triết lý" ngọt ngào, đầy chất thơ này, nhiều năm sau đọc lại cả nhà sẽ cười thật nhiều.', title_zh = '自己发明的词 🗣️', body_zh = '会造出“天空哭了”“汽车生气了”这样奇特的句子。宝宝的词汇量飞速增长，还在玩文字游戏。打开成长记录，把这份可爱又有诗意的“哲学”存档，多年后再读一定会笑个不停。' WHERE id = 'd8b40eb7-3665-4514-839c-874f3d30ec40' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La culpa del descanso con pantallas 📺', body_es = '¿Hoy tenías mucho que hacer y ha pasado mucho rato delante de la tele? ¿Te come la culpa por dentro? No puedes ser perfecta todos los días. A veces las pantallas son la niñera más inocente que nos salva de grandes caos. No te castigues.', title_fr = 'Culpabilité de la pause écran 📺', body_fr = 'Aujourd''hui, vous aviez beaucoup à faire et il est resté longtemps devant la télé ? La culpabilité vous ronge ? Vous ne pouvez pas être parfaite tous les jours. Parfois, les écrans sont la nounou la plus innocente qui nous sauve des grands chaos. Ne vous en voulez pas.', title_hi = 'बिना स्क्रीन वाले ब्रेक का अपराधबोध 📺', body_hi = 'आज आपके पास बहुत काम था, इसलिए वह देर तक टीवी के सामने रहा? अंदर ही अंदर अपराधबोध खा रहा है? आप हर दिन परफ़ेक्ट नहीं हो सकतीं। कभी-कभी स्क्रीन ही वह मासूम आया होती है जो हमें बड़ी अफ़रा-तफ़री से बचाती है। खुद पर बोझ मत डालिए।', title_id = 'Rasa bersalah soal jeda tanpa layar 📺', body_id = 'Hari ini Anda sangat sibuk sehingga ia lama di depan TV? Rasa bersalah menggerogoti hati Anda? Anda tidak bisa sempurna setiap hari. Kadang layar adalah pengasuh paling polos yang menyelamatkan kita dari kekacauan besar. Jangan terlalu membebani diri.', title_ja = '画面の時間への罪悪感 📺', body_ja = '今日は用事が多くて、テレビの前にいる時間が長くなった？罪悪感で胸がちくちくする？毎日完璧ではいられません。ときには画面が、大きなカオスから救ってくれるいちばん無邪気なベビーシッターです。自分を責めないで。', title_ko = '화면 시간에 대한 죄책감 📺', body_ko = '오늘 할 일이 많아 아이가 TV 앞에 오래 있었나요? 죄책감이 마음을 갉아먹나요? 매일 완벽할 순 없어요. 때로는 화면이 큰 혼란에서 우리를 구해 주는 가장 순한 베이비시터예요. 자신을 너무 몰아붙이지 마세요.', title_nl = 'Schuldgevoel over schermtijd 📺', body_nl = 'Zat hij vandaag lang voor de tv omdat jij veel te doen had? Knaagt het schuldgevoel? Je kunt niet elke dag perfect zijn. Soms is een scherm de onschuldigste oppas die ons van grote chaos redt. Wees niet zo streng voor jezelf.', title_pl = 'Wyrzuty sumienia po czasie przed ekranem 📺', body_pl = 'Dziś miałaś dużo pracy i długo siedział przed telewizorem? Gryzą cię wyrzuty sumienia? Nie możesz być idealna każdego dnia. Czasem ekran to najbardziej niewinna niania, która ratuje nas przed wielkim chaosem. Nie obwiniaj się.', title_pt = 'A culpa da pausa com ecrã 📺', body_pt = 'Hoje tinha muito que fazer e ele passou muito tempo em frente à televisão? A culpa está a roê-la por dentro? Não pode ser perfeita todos os dias. Às vezes os ecrãs são a ama mais inocente, que nos salva de grandes caos. Não se sobrecarregue.', title_sv = 'Dåligt samvete över skärmtid 📺', body_sv = 'Hade du så mycket att göra i dag att barnet satt länge framför tv:n? Gnager det dåliga samvetet? Du kan inte vara perfekt varje dag. Ibland är skärmen den mest oskyldiga barnvakten som räddar oss från stort kaos. Lägg inte allt på dig själv.', title_vi = 'Day dứt vì không có giờ nghỉ màn hình 📺', body_vi = 'Hôm nay mẹ bận nhiều việc nên bé ngồi trước TV lâu? Cảm giác tội lỗi đang gặm nhấm mẹ? Mẹ không thể hoàn hảo mỗi ngày. Đôi khi màn hình là "bảo mẫu" vô tội nhất cứu chúng ta khỏi những hỗn loạn lớn. Đừng tự làm khó mình.', title_zh = '屏幕时间的内疚 📺', body_zh = '今天事情太多，宝宝在电视前待得太久了？心里满是内疚？你不可能每天都完美。有时候，屏幕就是把我们从大混乱中拯救出来的最无辜的“保姆”。别给自己太大压力。' WHERE id = 'f96cc98d-a4e0-44e3-9617-a284b205c20e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le da miedo la oscuridad y no se va a la cama? Apaga del todo las luces de la habitación y enciende una linternita. Haz con las manos sombras de perros y pájaros en la pared. Convierte la oscuridad que da miedo en un parque de juegos y se dormirá en un momento.', body_fr = 'Il a peur du noir et ne veut pas aller au lit ? Éteignez complètement la lumière de la chambre et allumez une petite lampe de poche. Créez avec vos mains des ombres de chien et d''oiseau sur le mur. Transformez ce noir effrayant en terrain de jeu : il s''endormira en un instant.', body_hi = 'अंधेरे से डरता है और सोने नहीं जाता? कमरे की लाइटें पूरी बंद करके छोटी टॉर्च जलाइए। दीवार पर हाथों से कुत्ते, चिड़िया की परछाइयाँ बनाइए। डरावने अंधेरे को उसके लिए खेल का मैदान बना दीजिए, उसे नींद आने में बस कुछ ही पल लगेंगे।', body_id = 'Ia takut gelap dan tidak mau tidur? Matikan semua lampu kamar dan nyalakan senter kecil. Buat bayangan anjing dan burung dengan tangan Anda di dinding. Ubah gelap yang menakutkan menjadi taman bermain baginya, ia akan tertidur dalam sekejap.', body_ja = '暗いのがこわくて寝たがらない？部屋の明かりを全部消して、小さな懐中電灯をつけましょう。壁に手で犬や鳥の影をつくって。こわい暗やみを遊び場に変えれば、眠りにつくのはもうすぐです。', body_ko = '어둠이 무서워 잠자리에 들지 않나요? 방 불을 다 끄고 작은 손전등을 켜세요. 벽에 손으로 강아지와 새 그림자를 만들어 무서운 어둠을 놀이터로 바꿔 주세요. 잠드는 건 시간문제예요.', body_nl = 'Is hij bang in het donker en wil hij niet naar bed? Doe al het licht in de kamer uit en zet een klein zaklampje aan. Maak met je handen schaduwen van hondjes en vogels op de muur. Verander het enge donker in een speelplaats, hij valt zo in slaap.', body_pl = 'Boi się ciemności i nie chce iść do łóżka? Zgaś całkiem światło w pokoju i zapal małą latarkę. Rękami twórz na ścianie cienie pieska i ptaszka. Zamień straszną ciemność w plac zabaw, a zaśnie w mgnieniu oka.', body_pt = 'Tem medo do escuro e não quer ir para a cama? Apague todas as luzes do quarto e acenda uma pequena lanterna. Faça com as mãos sombras de cães e pássaros na parede. Transforme o escuro assustador num recreio e adormecer vai ser questão de instantes.', body_sv = 'Är barnet rädd för mörkret och vill inte gå och lägga sig? Släck alla lampor i rummet och tänd en liten ficklampa. Gör skuggor av hundar och fåglar med händerna på väggen. Förvandla det läskiga mörkret till en lekplats, så somnar barnet på nolltid.', body_vi = 'Bé sợ bóng tối và không chịu đi ngủ? Hãy tắt hết đèn trong phòng và bật một chiếc đèn pin nhỏ. Dùng tay tạo bóng chó, bóng chim trên tường. Biến bóng tối đáng sợ thành sân chơi của bé, và bé sẽ ngủ chỉ trong chốc lát.', body_zh = '怕黑，不肯上床？把房间的灯全关掉，打开一支小手电筒。用手在墙上做出小狗、小鸟的影子。把可怕的黑暗变成宝宝的游乐场，宝宝很快就会睡着。' WHERE id = '246edaf3-5d30-44d2-bda4-13ec5fbf5f36' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Los dinosaurios no comen papilla! 🦖', body_es = '¿Por la mañana no contesta a ninguna pregunta y solo ruge? Hoy es un T-Rex. Adáptate a la identidad que se ha inventado con un «¿Y los T-Rex desayunan?» y consigue que se siente a la mesa sin lágrimas.', title_fr = 'Les dinosaures ne mangent pas de bouillie ! 🦖', body_fr = 'Le matin, il ne répond à aucune question et se contente de rugir ? Aujourd''hui, c''est un T-Rex. Demandez : « Et les T-Rex, ils prennent un petit-déjeuner ? », adaptez-vous à ce personnage inventé et faites-le s''asseoir à table sans larmes.', title_hi = 'डायनासोर दलिया नहीं खाते! 🦖', body_hi = 'सुबह किसी सवाल का जवाब नहीं देता, बस दहाड़ता है? आज वह एक टी-रेक्स है। ‘तो क्या टी-रेक्स नाश्ता करते हैं?’ कहकर उसके गढ़े हुए किरदार के हिसाब से ढल जाइए और पक्का कीजिए कि वह बिना आँसुओं के मेज़ पर बैठ जाए।', title_id = 'Dinosaurus tidak makan bubur! 🦖', body_id = 'Pagi ini ia tidak menjawab satu pun pertanyaan, hanya mengaum? Hari ini ia seekor T-Rex. Ikuti identitas karangannya ini dengan bertanya ''T-Rex sarapan nggak ya?'' dan pastikan ia duduk di meja tanpa air mata.', title_ja = '恐竜はおかゆを食べない！ 🦖', body_ja = '朝、何を聞いても答えず、ガオーとうなるだけ？今日はティラノサウルスなんです。「じゃあ、ティラノサウルスは朝ごはん食べるの？」と聞いて、この子がつくったキャラクターに合わせ、涙なしで食卓につけるようにしましょう。', title_ko = '공룡은 죽 안 먹어! 🦖', body_ko = '아침에 아무 질문에도 대답 없이 으르렁거리기만 하나요? 오늘은 티라노사우루스래요. ''그런데 티라노도 아침 먹나?'' 하며 아이가 만든 캐릭터에 맞춰 주고, 눈물 없이 식탁에 앉게 해 주세요.', title_nl = 'Dinosaurussen eten geen pap! 🦖', body_nl = 'Geeft hij ''s ochtends op geen enkele vraag antwoord en brult hij alleen maar? Vandaag is hij een T-rex. Ga mee in zijn verzonnen identiteit met ''Eten T-rexen eigenlijk ontbijt?'' en zorg dat hij zonder tranen aan tafel gaat zitten.', title_pl = 'Dinozaury nie jedzą owsianki! 🦖', body_pl = 'Rano nie odpowiada na żadne pytanie, tylko ryczy? Dziś jest T-Reksem. Zapytaj: „A czy T-Reksy jedzą śniadanie?”, dopasuj się do wymyślonej przez niego postaci i sprawisz, że usiądzie do stołu bez łez.', title_pt = 'Os dinossauros não comem papas! 🦖', body_pt = 'De manhã não responde a nenhuma pergunta, só ruge? Hoje é um T-Rex. Entre na personagem que ele inventou perguntando "E os T-Rex tomam o pequeno-almoço?" e faça com que se sente à mesa sem lágrimas.', title_sv = 'Dinosaurier äter inte gröt! 🦖', body_sv = 'Svarar barnet inte på en enda fråga på morgonen, utan bara ryter? I dag är hen en T-Rex. Säg ”Men äter T-Rexar frukost?”, anpassa dig efter den påhittade personligheten och se till att barnet sätter sig vid bordet utan tårar.', title_vi = 'Khủng long không ăn cháo! 🦖', body_vi = 'Sáng nay bé không trả lời câu nào, chỉ gầm gừ? Hôm nay bé là một con T-Rex. Hãy hòa theo nhân vật bé tự nghĩ ra: "Thế T-Rex có ăn sáng không nhỉ?", để bé ngồi vào bàn mà không có giọt nước mắt nào.', title_zh = '恐龙不吃粥！🦖', body_zh = '早上什么问题都不回答，只会“嗷呜”？今天宝宝是一只霸王龙。说一句“那霸王龙早上吃早餐吗？”，配合宝宝编出来的这个身份，让宝宝不掉眼泪地坐到餐桌前。' WHERE id = 'd3b4180b-5723-4f72-a6c8-b4229f2e876c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy estoy agotada 🛑', body_es = 'Todo se ha juntado y has levantado la voz. Y ahora te remuerde la conciencia. No eres un robot. Abre el Diario de ánimo y escribe: «Hoy estoy cansada de verdad». Esta confesión te ayudará mucho más que obligarte a sonreír de mentira.', title_fr = 'Aujourd''hui, je suis à bout 🛑', body_fr = 'Tout s''est accumulé et vous avez haussé le ton. Et maintenant, vous culpabilisez. Vous n''êtes pas un robot. Ouvrez le Journal d''humeur et écrivez : « Aujourd''hui, j''étais vraiment fatiguée. » Cet aveu vous aidera bien plus que de vous forcer à un faux sourire.', title_hi = 'आज मैं थककर चूर हूँ 🛑', body_hi = 'सब कुछ एक साथ हो गया और आपकी आवाज़ ऊँची हो गई। अब आपको अपराधबोध हो रहा है। आप रोबोट नहीं हैं। मूड डायरी खोलिए और लिखिए, ‘आज मैं सच में थक गई।’ खुद को नकली मुस्कान के लिए मजबूर करने से ज़्यादा यह कबूलनामा आपकी मदद करेगा।', title_id = 'Hari ini aku habis 🛑', body_id = 'Semuanya datang bersamaan dan Anda meninggikan suara. Sekarang Anda dihantui rasa bersalah. Anda bukan robot. Buka Buku Harian Suasana Hati dan tulis ''Hari ini aku benar-benar lelah''. Pengakuan ini akan jauh lebih membantu daripada memaksa diri tersenyum palsu.', title_ja = '今日はもう限界 🛑', body_ja = 'いろいろ重なって、つい声を荒らげてしまった。そして今、罪悪感でいっぱい。あなたはロボットではありません。「気分日記」を開いて「今日は本当に疲れた」と書きましょう。無理に笑顔をつくるより、この正直なひと言のほうがずっと助けになります。', title_ko = '오늘은 다 소진됐어 🛑', body_ko = '모든 게 한꺼번에 몰려와 목소리를 높였고, 지금은 죄책감에 괴로운가요? 엄마는 로봇이 아니에요. 기분 일기를 열고 ''오늘 정말 지쳤다''라고 써 보세요. 억지로 웃는 것보다 이렇게 털어놓는 게 훨씬 도움이 될 거예요.', title_nl = 'Vandaag ben ik op 🛑', body_nl = 'Alles kwam tegelijk en je verhief je stem. Nu voel je je schuldig. Je bent geen robot. Open je Stemmingsdagboek en schrijf: ''Vandaag was ik echt moe.'' Deze bekentenis helpt je meer dan jezelf dwingen tot een nepglimlach.', title_pl = 'Dziś nie mam już sił 🛑', body_pl = 'Wszystko nałożyło się na siebie i podniosłaś głos. Teraz męczą cię wyrzuty sumienia. Nie jesteś robotem. Otwórz Dziennik nastroju i napisz: „Dziś naprawdę jestem zmęczona”. To wyznanie pomoże ci bardziej niż zmuszanie się do sztucznego uśmiechu.', title_pt = 'Hoje esgotei-me 🛑', body_pt = 'Juntou-se tudo e levantou a voz. Agora está cheia de remorsos. Não é um robô. Abra o Diário de Humor e escreva: "Hoje estou mesmo cansada". Esta confissão vai ajudá-la muito mais do que obrigar-se a sorrir à força.', title_sv = 'I dag tog det slut för mig 🛑', body_sv = 'Allt kom på en gång och du höjde rösten. Nu har du dåligt samvete. Du är ingen robot. Öppna Humördagboken och skriv ”I dag var jag verkligen trött”. Den här bekännelsen hjälper dig mer än att tvinga fram ett falskt leende.', title_vi = 'Hôm nay mẹ cạn sức rồi 🛑', body_vi = 'Mọi chuyện dồn dập và mẹ đã lớn tiếng. Giờ mẹ lại thấy day dứt. Mẹ đâu phải người máy. Hãy mở Nhật ký tâm trạng và viết: "Hôm nay mình thật sự mệt." Thừa nhận điều đó sẽ giúp mẹ nhiều hơn là ép mình cười gượng.', title_zh = '今天我被掏空了 🛑', body_zh = '所有事情都赶到一起，你提高了嗓门。现在又满心内疚。你不是机器人。打开心情日记，写下“今天我真的累了”。比起逼自己假笑，这份坦白更能帮到你。' WHERE id = 'e089800c-6f76-4909-bafd-021551368a5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Por la mañana te ha mirado como a una desconocida y te ha dicho «¿Tú quién eres? ¿Dónde está mi mamá?»? Es un nuevo juego de rol. Dile: «Soy la vecina, tu mamá viene ahora». Que la habitación se llene de risas por la mañana: ahorra muchísima más energía que ponerse cabezota.', body_fr = 'Le matin, il vous a regardée comme une inconnue et a dit : « Qui es-tu ? Où est ma maman ? » C''est un nouveau jeu de rôle. Dites : « Je suis la voisine, ta maman arrive. » Que la chambre éclate de rire dès le matin : cela économise bien plus d''énergie que de s''entêter.', body_hi = 'सुबह आपको अजनबी की तरह देखकर पूछा, ‘तुम कौन हो? मेरी माँ कहाँ है?’ यह नया रोल-प्ले है। कहिए, ‘मैं पड़ोस वाली आंटी हूँ, तुम्हारी माँ अभी आ रही है।’ सुबह हँसी से कमरा गूँजने दीजिए, यह ज़िद करने से कहीं ज़्यादा ऊर्जा बचाता है।', body_id = 'Pagi ini ia menatap Anda seperti orang asing dan berkata ''Kamu siapa? Mamaku mana?'' Ini permainan peran baru. Katakan ''Aku tante tetangga, mamamu sebentar lagi datang''. Biarkan kamar pecah oleh tawa pagi ini, ini jauh lebih menghemat energi daripada beradu keras kepala.', body_ja = '朝、知らない人を見るような顔で「あなたは誰？ママはどこ？」と言った？新しいごっこ遊びです。「となりのおばさんよ、ママはすぐ来るからね」と言ってあげて。朝から笑いで部屋をいっぱいにしましょう。意地の張り合いよりずっとエネルギーの節約になります。', body_ko = '아침에 낯선 사람 보듯 ''누구세요? 우리 엄마 어디 있어요?'' 했나요? 새로운 역할 놀이예요. ''나는 옆집 아줌마야, 엄마는 곧 오실 거야'' 하고 받아 주세요. 아침부터 웃음으로 방이 떠나가게 두세요, 고집 싸움보다 훨씬 에너지를 아껴 줘요.', body_nl = 'Keek hij je ''s ochtends aan als een vreemde en zei hij: ''Wie ben jij? Waar is mijn mama?'' Dit is een nieuw rollenspel. Zeg: ''Ik ben de buurvrouw, je mama komt zo.'' Laat de kamer vanochtend schudden van het lachen, dat bespaart je veel meer energie dan koppig volhouden.', body_pl = 'Rano spojrzał na ciebie jak na obcą i zapytał: „Kim jesteś? Gdzie moja mama?”. To nowa zabawa w odgrywanie ról. Powiedz: „Jestem panią sąsiadką, mama zaraz przyjdzie”. Niech poranek wypełni śmiech, to oszczędza dużo więcej energii niż upieranie się.', body_pt = 'De manhã olhou para si como para uma estranha e disse "Quem és tu? Onde está a minha mãe?"? É um novo jogo de faz de conta. Diga "Sou a vizinha, a tua mãe já vem". Deixe que o quarto se encha de gargalhadas logo de manhã: poupa muito mais energia do que teimar.', body_sv = 'Tittade barnet på dig som på en främling i morse och sa ”Vem är du? Var är mamma?” Det är en ny rollek. Säg ”Jag är tanten från grannhuset, mamma kommer snart”. Låt rummet fyllas av skratt på morgonen, det sparar mångdubbelt mer energi än att tjafsa.', body_vi = 'Sáng nay bé nhìn mẹ như người lạ và hỏi "Cô là ai? Mẹ con đâu?" Đây là trò nhập vai mới. Hãy nói: "Cô là cô hàng xóm, mẹ con sắp về rồi." Để cả phòng rộn tiếng cười buổi sáng, cách này tiết kiệm sức hơn gấp nhiều lần so với giằng co.', body_zh = '早上像看陌生人一样看着你说：“你是谁？我妈妈在哪儿？”这是新的角色扮演游戏。说“我是邻居阿姨，你妈妈马上就来”。让早晨的笑声充满房间，这比较劲省力得多。' WHERE id = 'a8aeb934-2767-4365-a584-e2b99fc16215' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirlo sin leer el cuento 🪄', body_es = '¿Esta noche no te queda aliento para leer el cuento? Abre Cuentos inteligentes. Pon de fondo solo los susurros del bosque y el viento. En la oscuridad, escuchad esos sonidos de la naturaleza y descansad los dos del ruido. El cansancio visual desaparecerá al instante.', title_fr = 'L''endormir sans lire de conte 🪄', body_fr = 'Ce soir, vous n''avez pas le souffle pour lire un conte ? Ouvrez les Contes intelligents. Mettez seulement en fond les bruissements de la forêt et le vent. Dans le noir, en écoutant ces sons de la nature, reposez-vous tous les deux du bruit. La fatigue visuelle disparaîtra aussitôt.', title_hi = 'बिना कहानी पढ़े सुलाना 🪄', body_hi = 'आज शाम कहानी पढ़ने की हिम्मत नहीं बची? स्मार्ट कहानियाँ खोलिए। बस सरसराते जंगल और हवा की आवाज़ें बैकग्राउंड में लगाइए। अंधेरे में प्रकृति की वे आवाज़ें सुनते हुए आप दोनों शोर से आराम कीजिए। आँखों की थकान तुरंत उतर जाएगी।', title_id = 'Menidurkan tanpa membacakan dongeng 🪄', body_id = 'Malam ini Anda tidak punya tenaga untuk membacakan dongeng? Buka Dongeng Pintar. Putar saja suara hutan dan angin yang berdesir sebagai latar. Dalam gelap, beristirahatlah berdua dari kebisingan sambil mendengarkan suara alam itu. Kelelahan visual pun langsung hilang.', title_ja = '絵本を読まずに寝かしつけ 🪄', body_ja = '今夜は絵本を読む元気がない？「スマートおはなし」を開いて、ささやくような森と風の音だけを背景に流しましょう。暗やみの中で自然の音を聞きながら、ふたりとも騒音から休んで。目の疲れもすぐにとれます。', title_ko = '동화 읽지 않고 재우기 🪄', body_ko = '오늘 저녁엔 동화 읽을 기운도 없나요? 스마트 동화를 열고 바스락거리는 숲과 바람 소리만 배경으로 틀어 두세요. 어둠 속에서 자연의 소리를 들으며 두 사람 모두 소음에서 벗어나 쉬세요. 눈의 피로도 금세 풀릴 거예요.', title_nl = 'In slaap zonder voorlezen 🪄', body_nl = 'Heb je vanavond geen adem meer om voor te lezen? Open Slimme sprookjes. Zet alleen ruisende bos- en windgeluiden op de achtergrond. Luister samen in het donker naar die natuurgeluiden en rust allebei uit van het lawaai. De visuele vermoeidheid is meteen weg.', title_pl = 'Usypianie bez czytania bajki 🪄', body_pl = 'Dziś wieczorem nie masz siły czytać bajki? Otwórz Mądre bajki. Włącz w tle tylko szum lasu i wiatru. Słuchając w ciemności odgłosów natury, oboje odpocznijcie od hałasu. Zmęczenie wzroku od razu minie.', title_pt = 'Adormecer sem ler a história 🪄', body_pt = 'Esta noite não tem fôlego para ler uma história? Abra as Histórias Inteligentes. Ponha de fundo apenas os sons sussurrados da floresta e do vento. No escuro, a ouvir os sons da natureza, descansem os dois do barulho. O cansaço visual acaba num instante.', title_sv = 'Somna utan att läsa sagan 🪄', body_sv = 'Orkar du inte läsa saga i kväll? Öppna Smarta sagor. Sätt bara på susande skog och vind som bakgrund. Lyssna på naturljuden i mörkret och vila båda två från oljudet. Den visuella tröttheten försvinner direkt.', title_vi = 'Ru ngủ mà không cần đọc truyện 🪄', body_vi = 'Tối nay mẹ không còn hơi để đọc truyện? Hãy mở Truyện cổ tích thông minh. Chỉ cần bật tiếng rừng xào xạc và tiếng gió làm nền. Trong bóng tối, cả hai mẹ con cùng lắng nghe âm thanh thiên nhiên và nghỉ ngơi khỏi tiếng ồn. Sự mệt mỏi thị giác sẽ tan biến ngay.', title_zh = '不讲故事也能哄睡 🪄', body_zh = '今晚没力气讲故事了？打开智慧童话。只放沙沙的森林声和风声当背景。在黑暗中听着这些自然的声音，你们俩都从喧闹中歇一歇。视觉疲劳会立刻消失。' WHERE id = 'cf7b3532-560e-4c59-af5f-4a64a8510605' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tesoro olvidado en la lavadora 🍝', body_es = '¿Al lavarle el pantalón ha salido pasta seca o una piedra del bolsillo? No es glotonería, es exploración infantil. Tírala a la basura con cara seria, pero sonríe por dentro a ese pequeño proveedor. Apúntalo como un momento gracioso en el Seguimiento del desarrollo.', title_fr = 'Le trésor oublié dans la machine à laver 🍝', body_fr = 'En lavant son pantalon, vous avez trouvé dans sa poche des pâtes séchées ou un caillou ? Ce n''est pas de la gourmandise, c''est une exploration d''enfant. Jetez-les avec un air sérieux, mais souriez intérieurement à ce petit ravitailleur. Notez-le comme un moment drôle dans le Suivi de développement.', title_hi = 'वॉशिंग मशीन में भूला हुआ खज़ाना 🍝', body_hi = 'पैंट धोते समय जेब से सूखा पास्ता या पत्थर निकला? यह लालच नहीं, बच्चों वाली खोजबीन है। गंभीर चेहरे से उसे कूड़े में डालिए, पर अंदर ही अंदर इस भंडार जमा करने वाले बच्चे पर मुस्कुराइए। ग्रोथ ट्रैकर में इसे एक मज़ेदार पल के रूप में दर्ज कीजिए।', title_id = 'Harta karun yang terlupa di mesin cuci 🍝', body_id = 'Saat mencuci celananya, dari sakunya keluar makaroni kering atau batu? Ini bukan rakus, ini penjelajahan ala anak-anak. Buang ke tempat sampah dengan wajah serius, tapi dalam hati tersenyumlah pada si pemasok kecil ini. Catat sebagai momen lucu di Pelacak Perkembangan.', title_ja = '洗濯機で見つかった宝もの 🍝', body_ja = 'ズボンを洗おうとしたら、ポケットから乾いたパスタや石が出てきた？食いしんぼうではなく、子どもなりの探検です。まじめな顔で捨てながらも、心の中ではこの調達係の子にほほえんで。「発達トラッカー」におもしろい瞬間として記録しましょう。', title_ko = '세탁기에서 발견된 보물 🍝', body_ko = '바지를 빨려다 주머니에서 말라붙은 파스타나 돌멩이가 나왔나요? 욕심이 아니라 아이다운 탐험이에요. 진지한 얼굴로 버리되, 속으로는 이 꼬마 보급 담당에게 미소 지어 주세요. 성장 기록에 웃긴 순간으로 남겨 두세요.', title_nl = 'Een vergeten schat in de wasmachine 🍝', body_nl = 'Kwam er bij het wassen opgedroogde pasta of een steentje uit zijn broekzak? Dat is geen hebzucht, maar kinderlijk ontdekken. Gooi het met een serieus gezicht weg, maar glimlach vanbinnen om je kleine verzamelaar. Leg het als grappig moment vast in de Groeitracker.', title_pl = 'Skarb zapomniany w pralce 🍝', body_pl = 'Podczas prania spodni z kieszeni wypadł zaschnięty makaron albo kamyk? To nie łakomstwo, tylko dziecięce odkrywanie. Z poważną miną wyrzuć to do kosza, ale uśmiechnij się w duchu do tego małego zaopatrzeniowca. Zapisz to w Śledzeniu rozwoju jako zabawny moment.', title_pt = 'O tesouro esquecido na máquina de lavar 🍝', body_pt = 'Ao lavar as calças, saiu do bolso massa seca ou uma pedra? Não é gula, é exploração infantil. Com uma cara séria, deite-a ao lixo, mas sorria por dentro a este pequeno fornecedor. Registe este momento cómico no Registo de Crescimento.', title_sv = 'En bortglömd skatt i tvättmaskinen 🍝', body_sv = 'Hittade du torkad pasta eller en sten i byxfickan när du tvättade? Det är inte girighet, det är barnslig upptäckarlust. Släng den med allvarlig min, men le inombords åt den lilla förrådsförvaltaren. Anteckna det som en rolig stund i Utvecklingsspåraren.', title_vi = 'Kho báu bị bỏ quên trong máy giặt 🍝', body_vi = 'Lúc giặt quần, mẹ thấy trong túi bé có miếng mì ống khô hay hòn sỏi? Đó không phải tham lam, mà là một cuộc thám hiểm kiểu trẻ con. Hãy nghiêm mặt bỏ vào thùng rác, nhưng thầm mỉm cười với "người dự trữ" nhỏ này. Ghi lại khoảnh khắc hài hước này trong Theo dõi phát triển.', title_zh = '洗衣机里被遗忘的宝藏 🍝', body_zh = '洗裤子时，从口袋里掏出干掉的意面或石头？这不是贪吃，而是孩子式的探险。板着脸把它扔进垃圾桶，但心里对这个小“后勤官”笑一笑吧。把它当作搞笑时刻记在成长记录里。' WHERE id = 'f8301d61-e90d-4d1c-b4e2-7f1feb3be70d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los miedos raros 🤖', body_es = '¿De repente le ha entrado miedo al desagüe de la bañera? No busques enfermedades en internet. Pregunta a Anacan AI, descubre que es una fobia totalmente normal y pasajera propia de la imaginación de esta edad, y apaga el pánico.', title_fr = 'Le début de peurs étranges 🤖', body_fr = 'Il s''est soudain mis à avoir peur du trou d''évacuation de la baignoire ? Ne cherchez pas de maladie sur Internet. Demandez à Anacan AI et découvrez que c''est une phobie tout à fait normale et passagère liée à l''imagination de cet âge. La panique retombera.', title_hi = 'अजीब डर की शुरुआत 🤖', body_hi = 'अचानक बाथरूम में पानी जाने वाले छेद से डरने लगा? इंटरनेट पर बीमारी मत ढूँढिए। Anacan AI से पूछिए, जानिए कि यह इस उम्र की कल्पना से आने वाला बिल्कुल सामान्य और अस्थायी डर है, और घबराहट शांत कीजिए।', title_id = 'Awal ketakutan-ketakutan aneh 🤖', body_id = 'Tiba-tiba ia takut pada lubang pembuangan air di kamar mandi? Jangan mencari penyakit di internet. Tanyakan pada Anacan AI, pelajari bahwa ini fobia yang sepenuhnya normal dan sementara akibat imajinasi di usia ini, dan padamkan kepanikan Anda.', title_ja = 'ふしぎなこわがりの始まり 🤖', body_ja = '急にお風呂の排水口をこわがるようになった？ネットで病気を検索しないで。Anacan AIに聞いて、これがこの年齢の想像力からくる、ごく普通の一時的な恐怖だと知って、パニックをしずめましょう。', title_ko = '이상한 두려움의 시작 🤖', body_ko = '갑자기 욕조 배수구를 무서워하기 시작했나요? 인터넷에서 병을 찾아보지 마세요. Anacan AI에게 물어보고, 이 나이의 상상력에서 오는 아주 정상적이고 일시적인 공포라는 걸 알고 마음을 놓으세요.', title_nl = 'Als vreemde angsten beginnen 🤖', body_nl = 'Is hij ineens bang voor het afvoerputje in de badkamer? Ga niet online naar ziektes zoeken. Vraag het Anacan AI, ontdek dat dit een heel normale en tijdelijke angst is die bij de fantasie van deze leeftijd hoort, en laat je paniek los.', title_pl = 'Początek dziwnych lęków 🤖', body_pl = 'Nagle zaczął się bać odpływu w wannie? Nie szukaj chorób w internecie. Zapytaj Anacan AI, dowiedz się, że to zupełnie normalna i przejściowa fobia, którą przynosi wyobraźnia w tym wieku, i ugaś panikę.', title_pt = 'O início de medos estranhos 🤖', body_pt = 'De repente começou a ter medo do ralo da banheira? Não procure doenças na internet. Pergunte ao Anacan AI e descubra que é uma fobia totalmente normal e passageira, trazida pela imaginação desta idade, e apague o pânico.', title_sv = 'Konstiga rädslor börjar 🤖', body_sv = 'Har barnet plötsligt börjat bli rädd för avloppet i badkaret? Googla inte efter sjukdomar. Fråga Anacan AI, få veta att det är en helt normal och övergående fobi som kommer med fantasin i den här åldern, och släck paniken.', title_vi = 'Khi những nỗi sợ lạ bắt đầu 🤖', body_vi = 'Bé bỗng dưng sợ lỗ thoát nước trong phòng tắm? Đừng lên mạng tìm bệnh. Hãy hỏi Anacan AI để biết đây là nỗi sợ hoàn toàn bình thường và nhất thời do trí tưởng tượng ở tuổi này, và dập tắt sự hoảng hốt.', title_zh = '奇怪的恐惧出现了 🤖', body_zh = '突然开始害怕浴室里的下水口？别上网查病。问问Anacan AI，了解这是这个年龄的想象力带来的完全正常、暂时的恐惧，平息你的恐慌吧。' WHERE id = '3f11dc71-3a89-4499-8bac-19038f6fdeb4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Como yo solo! 🥣', body_es = 'Aunque sabe comer solo, insiste en que le des tú de comer, pero cuando le acercas la cuchara la aparta y llora. Ni él sabe lo que quiere. Ponle el plato delante, dile «Cuando tengas hambre, comerás» y levántate de la mesa. Cuando tenga hambre, comerá solo.', title_fr = 'Je vais manger tout seul ! 🥣', body_fr = 'Alors qu''il sait manger seul, il exige que vous le nourrissiez, mais quand vous tendez la cuillère, il la repousse en pleurant. Il ne sait pas lui-même ce qu''il veut. Posez l''assiette devant lui, dites « Tu mangeras quand tu auras faim » et quittez la table. Quand il aura faim, il mangera tout seul.', title_hi = 'मैं खुद खाऊँगा! 🥣', body_hi = 'खुद खा सकता है, फिर भी ज़िद करता है कि आप खिलाएँ, और चम्मच बढ़ाने पर धकेलकर रोने लगता है। उसे खुद नहीं पता कि क्या करे। प्लेट सामने रखिए, ‘भूख लगेगी तो खा लेना’ कहिए और मेज़ से उठ जाइए। भूख लगने पर वह खुद खा लेगा।', title_id = 'Aku makan sendiri! 🥣', body_id = 'Ia sebenarnya bisa makan sendiri, tapi bersikeras minta disuapi, dan saat Anda menyodorkan sendok, ia menepisnya lalu menangis. Ia sendiri tidak tahu apa yang ia mau. Letakkan piring di depannya, katakan ''Kalau lapar, kamu bisa makan'', lalu tinggalkan meja. Saat lapar, ia akan makan sendiri.', title_ja = '自分で食べる！ 🥣', body_ja = '自分で食べられるのに、食べさせてと言いはり、スプーンを差し出すと押しのけて泣く。本人もどうしたいのかわからないんです。お皿を前に置いて「おなかがすいたら食べてね」と言い、席を立ちましょう。おなかがすけば自分で食べます。', title_ko = '나 혼자 먹을 거야! 🥣', body_ko = '혼자 먹을 수 있으면서도 먹여 달라고 조르고, 숟가락을 내밀면 밀어내며 우나요? 본인도 뭘 원하는지 몰라요. 접시를 앞에 두고 ''배고프면 먹어'' 하며 자리에서 일어나세요. 배가 고프면 혼자 먹을 거예요.', title_nl = 'Ik eet zelf! 🥣', body_nl = 'Hij kan zelf eten, maar eist toch dat jij hem voert, en als je de lepel aanreikt, duwt hij die weg en huilt hij. Hij weet zelf ook niet wat hij wil. Zet het bord voor hem neer, zeg ''Als je honger hebt, eet je wel'' en sta op van tafel. Als hij honger heeft, eet hij zelf.', title_pl = 'Sam zjem! 🥣', body_pl = 'Choć potrafi jeść sam, uparcie żąda, żebyś go karmiła, a gdy podajesz łyżkę, odpycha ją i płacze. Sam nie wie, czego chce. Postaw przed nim talerz, powiedz „Zjesz, kiedy zgłodniejesz” i wstań od stołu. Gdy zgłodnieje, zje sam.', title_pt = 'Eu como sozinho! 🥣', body_pt = 'Consegue comer sozinho, mas insiste que seja a mãe a dar-lhe a comida e, quando lhe estende a colher, empurra-a e chora. Nem ele sabe o que quer. Ponha-lhe o prato à frente, diga "Quando tiveres fome, comes" e levante-se da mesa. Quando tiver fome, come sozinho.', title_sv = 'Jag äter själv! 🥣', body_sv = 'Fast barnet kan äta själv kräver hen envist att du ska mata, men när du räcker fram skeden knuffar hen bort den och gråter. Hen vet inte själv vad hen vill. Ställ tallriken framför barnet, säg ”Du äter när du blir hungrig” och res dig från bordet. När barnet blir hungrigt äter hen själv.', title_vi = 'Con tự ăn! 🥣', body_vi = 'Dù tự ăn được, bé vẫn khăng khăng đòi mẹ đút, nhưng khi mẹ đưa thìa thì lại đẩy ra và khóc. Chính bé cũng không biết mình muốn gì. Hãy đặt đĩa trước mặt bé, nói "Khi nào đói thì con ăn" và rời bàn. Khi đói, bé sẽ tự ăn.', title_zh = '我自己吃！🥣', body_zh = '明明自己会吃，却坚持要你喂，你递过勺子又推开大哭。宝宝自己也不知道想怎样。把盘子放在宝宝面前，说一句“饿了你就会吃”，然后离开餐桌。饿了宝宝自己会吃的。' WHERE id = '51e9982e-8a0e-4e2c-9ee7-749ec67f6283' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedícate un poco más de tiempo 💆‍♂️', body_es = 'Cuando el peque se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Tienes el cuello agarrotado de tanto correr todo el día. No sois solo padres que comparten casa: sois el mayor apoyo psicológico el uno del otro.', title_fr = 'Prenez encore un peu de temps pour vous 💆‍♂️', body_fr = 'Une fois l''enfant couché, demandez à votre partenaire un massage des épaules de 10 minutes. Toute cette journée de course vous a raidi la nuque. Vous n''êtes pas seulement des parents qui partagent la même maison, vous êtes l''un pour l''autre le plus proche soutien psychologique.', title_hi = 'थोड़ा और समय अपने लिए 💆‍♂️', body_hi = 'बच्चे के सोने के बाद अपने साथी से 10 मिनट कंधों की मालिश माँगिए। दिनभर की भागदौड़ से गर्दन अकड़ गई है। आप बस एक घर में रहने वाले माता-पिता नहीं, एक-दूसरे के सबसे करीबी भावनात्मक सहारे हैं।', title_id = 'Luangkan sedikit waktu untuk diri sendiri 💆‍♂️', body_id = 'Setelah anak tidur, mintalah pijat bahu 10 menit dari pasangan Anda. Leher Anda kaku karena seharian berlarian. Kalian bukan sekadar orang tua yang berbagi rumah yang sama, kalian adalah pendukung psikologis terdekat satu sama lain.', title_ja = 'もう少し自分の時間を 💆‍♂️', body_ja = '子どもが寝たら、パートナーに10分間の肩もみをお願いしましょう。一日じゅう走りまわって、首がこっていますね。ふたりはただ同じ家に住む親ではなく、お互いのいちばん身近な心の支えです。', title_ko = '나를 위한 시간을 조금 더 💆‍♂️', body_ko = '아이가 잠들면 배우자에게 10분간 어깨 마사지를 부탁하세요. 하루 종일 뛰어다니느라 목이 뭉쳤잖아요. 두 사람은 한집에 사는 부모일 뿐 아니라 서로에게 가장 가까운 마음의 지원군이에요.', title_nl = 'Neem wat tijd voor jezelf 💆‍♂️', body_nl = 'Vraag je partner om een schoudermassage van 10 minuten als je kind slaapt. Van al het rennen vandaag zit je nek vast. Jullie zijn niet alleen ouders die hetzelfde huis delen, jullie zijn elkaars grootste psychologische steun.', title_pl = 'Poświęć sobie jeszcze trochę czasu 💆‍♂️', body_pl = 'Gdy dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Po całym dniu biegania szyja ci zesztywniała. Nie jesteście tylko rodzicami dzielącymi jeden dom, jesteście dla siebie najbliższym wsparciem psychicznym.', title_pt = 'Reserve um pouco de tempo para si 💆‍♂️', body_pt = 'Depois de a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. De tanto correr o dia todo, ficou com o pescoço preso. Não são apenas pais que partilham a mesma casa, são o maior apoio psicológico um do outro.', title_sv = 'Ta lite mer tid för dig själv 💆‍♂️', body_sv = 'När barnet har somnat, be din partner om en 10 minuters axelmassage. Nacken har stelnat av hela dagens springande. Ni är inte bara föräldrar som delar samma hem, ni är varandras närmaste psykologiska stöd.', title_vi = 'Dành thêm chút thời gian cho bản thân 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy nhờ chồng mát-xa vai cho mình 10 phút. Chạy tới chạy lui cả ngày làm cổ mẹ cứng đờ. Hai người không chỉ là cha mẹ sống chung một nhà, mà còn là chỗ dựa tâm lý gần gũi nhất của nhau.', title_zh = '再给自己留点时间 💆‍♂️', body_zh = '宝宝睡着后，请另一半给你按摩10分钟肩膀。忙了一整天，脖子都僵了。你们不只是住在同一个屋檐下的父母，更是彼此最亲近的心理支柱。' WHERE id = 'cc8c59da-7b2e-4da4-87ec-e11a59ea5011' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las mamás de Instagram y la realidad 📱', body_es = '¡No te desanimes al abrir Instagram y ver los niños perfectos de todo el mundo! Cierra esa app y entra en la Comunidad Anacan. Verás que en todas las casas hay el mismo desorden que en la tuya y que todos los niños son ruidosos, y dirás: «¡Soy totalmente normal!».', title_fr = 'Les mamans d''Instagram et la réalité 📱', body_fr = 'Ne vous découragez pas en voyant les enfants parfaits de tout le monde dès que vous ouvrez Instagram ! Fermez cette appli et rejoignez la Communauté Anacan. Voyez que chez les autres aussi, la maison est sens dessus dessous et les enfants bruyants, et dites-vous : « Je suis tout à fait normale ! »', title_hi = 'इंस्टाग्राम वाली माँएँ और असलियत 📱', body_hi = 'इंस्टाग्राम खोलते ही सबके परफ़ेक्ट बच्चे देखकर हिम्मत मत हारिए! वह ऐप बंद कीजिए और Anacan कम्युनिटी में आइए। देखिए कि सबके घर आपके घर जैसे ही बिखरे हैं और बच्चे उतने ही शोर मचाते हैं, और कहिए, ‘मैं बिल्कुल नॉर्मल हूँ!’', title_id = 'Ibu-ibu Instagram dan kenyataan 📱', body_id = 'Jangan patah semangat melihat anak-anak sempurna orang lain begitu membuka Instagram! Tutup aplikasinya, masuk ke Komunitas Anacan. Lihat bahwa rumah semua orang berantakan seperti rumah Anda dan anak-anak mereka juga berisik, lalu katakan ''Aku sepenuhnya normal!''', title_ja = 'インスタのママたちと現実 📱', body_ja = 'インスタを開くたびに、みんなの完璧な子どもを見て落ちこまないで！そのアプリは閉じて、Anacanコミュニティへ。どの家もあなたの家のように散らかっていて、子どもはにぎやかなのを見て、「わたし、まったく普通だ」と言いましょう！', title_ko = '인스타그램 엄마들과 현실 📱', body_ko = '인스타그램을 열자마자 다들 완벽한 아이만 보여서 기운 빠지나요? 그 앱은 닫고 Anacan 커뮤니티에 들어가 보세요. 다들 집이 엄마 집처럼 엉망이고 아이들도 시끄럽다는 걸 보며 ''나 완전 정상이야''라고 말해 보세요!', title_nl = 'Instagrammama''s en de realiteit 📱', body_nl = 'Raak niet ontmoedigd als je op Instagram ieders perfecte kinderen ziet! Sluit die app en ga naar de Anacan Community. Zie dat bij iedereen het huis net zo''n rommel is en de kinderen net zo luidruchtig zijn als bij jou, en zeg: ''Ik ben helemaal normaal!''', title_pl = 'Mamy z Instagrama a rzeczywistość 📱', body_pl = 'Nie trać ducha, gdy tylko otworzysz Instagram i zobaczysz same idealne dzieci! Zamknij tę aplikację i wejdź do Społeczności Anacan. Zobacz, że u innych w domu jest taki sam bałagan jak u ciebie, a dzieci są równie głośne, i powiedz sobie: „Jestem zupełnie normalna”!', title_pt = 'As mães do Instagram e a realidade 📱', body_pt = 'Não desanime ao ver os filhos perfeitos de toda a gente mal abre o Instagram! Feche essa app e entre na Comunidade Anacan. Ao ver que as casas dos outros estão tão desarrumadas como a sua e os filhos são igualmente barulhentos, vai dizer: "Afinal sou perfeitamente normal!"', title_sv = 'Instagrammammor och verkligheten 📱', body_sv = 'Bli inte nedslagen av att se allas perfekta barn så fort du öppnar Instagram! Stäng appen och gå in i Anacan Community. Se att alla andras hem är lika stökiga som ditt och deras barn lika högljudda, och säg ”Jag är helt normal”!', title_vi = 'Các bà mẹ Instagram và thực tế 📱', body_vi = 'Đừng nản lòng khi vừa mở Instagram đã thấy những đứa trẻ hoàn hảo của mọi người! Hãy đóng ứng dụng đó lại và vào Cộng đồng Anacan. Thấy nhà ai cũng bừa bộn, con ai cũng ồn ào như nhà mình, mẹ sẽ nói: "Mình hoàn toàn bình thường!"', title_zh = 'Instagram上的妈妈与现实 📱', body_zh = '一打开Instagram就看到别人家完美的孩子，别灰心！关掉那个应用，来Anacan社区吧。看到大家家里都和你家一样乱、孩子都一样吵，你会说：“我完全正常！”' WHERE id = '68be8da2-a2bd-442f-bb8b-f854ddbaa84b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando suena la campana, a dormir ⏱️', body_es = 'La hora de dormir se alarga y se alarga. Agua, baño, despedirse de la pared... Pon el temporizador del móvil. Establece la regla: «Cuando suena la campanita, todos apagamos las luces». Al oír ese sonido se meterá en la cama sin protestar.', title_fr = 'Quand la sonnerie retentit, on dort ⏱️', body_fr = 'L''heure du coucher s''éternise. L''eau, les toilettes, dire au revoir au mur... Réglez le minuteur de votre téléphone. Instaurez la règle « Quand la sonnerie retentit, tout le monde éteint la lumière ». En l''entendant, il ira au lit sans la moindre protestation.', title_hi = 'घंटी बजी तो सो जाएँगे ⏱️', body_hi = 'सोने का समय खिंचता ही जाता है। पानी, टॉयलेट, दीवार को गुड नाइट... फ़ोन का टाइमर लगाइए। नियम बनाइए: ‘घंटी की आवाज़ आते ही सब लाइटें बंद करते हैं।’ वह आवाज़ सुनकर बिना किसी विरोध के बिस्तर पर चला जाएगा।', title_id = 'Saat bel berbunyi, kita tidur ⏱️', body_id = 'Waktu tidur terus molor. Minum, ke toilet, pamitan dengan dinding... Pasang timer di ponsel. Buat aturan ''Saat bel berbunyi, semua lampu dimatikan''. Begitu mendengar bunyinya, ia akan naik ke tempat tidur tanpa protes.', title_ja = 'ベルが鳴ったらみんな寝る ⏱️', body_ja = '寝る時間がどんどん延びていく。お水、トイレ、壁におやすみ…。スマホのタイマーをセットして、「ベルが鳴ったらみんな明かりを消す」というルールを決めましょう。その音を聞いたら、文句も言わずにベッドに入りますよ。', title_ko = '알람이 울리면 자는 거야 ⏱️', body_ko = '잠자리 시간이 끝없이 늘어지나요? 물, 화장실, 벽에게 인사하기... 휴대폰 타이머를 맞추고 ''알람이 울리면 모두 불을 끈다''는 규칙을 정하세요. 그 소리가 들리면 아무 저항 없이 침대에 들어갈 거예요.', title_nl = 'Als de bel gaat, gaan we slapen ⏱️', body_nl = 'Bedtijd rekt zich eindeloos uit. Water, wc, de muur welterusten zeggen... Zet een timer op je telefoon. Maak de regel: ''Als de bel gaat, doet iedereen het licht uit.'' Als hij dat geluid hoort, kruipt hij zonder protest in bed.', title_pl = 'Gdy zadzwoni dzwonek, idziemy spać ⏱️', body_pl = 'Pora snu ciągnie się w nieskończoność. Woda, toaleta, żegnanie się ze ścianą... Nastaw minutnik w telefonie. Wprowadź zasadę: „Gdy zadzwoni dzwonek, wszyscy gaszą światło”. Gdy usłyszy ten dźwięk, położy się do łóżka bez żadnego sprzeciwu.', title_pt = 'Quando toca a campainha, vamos dormir ⏱️', body_pt = 'A hora de dormir estica-se sem fim. Água, casa de banho, despedir-se da parede... Programe o temporizador do telemóvel. Crie a regra "quando a campainha toca, todos apagam as luzes". Quando ouvir o som, vai para a cama sem protestar.', title_sv = 'När klockan ringer sover vi ⏱️', body_sv = 'Läggdags drar ut mer och mer. Vatten, toaletten, säga god natt till väggen... Ställ in timern på telefonen. Inför regeln ”när klockan ringer släcker alla”. När barnet hör ljudet går hen och lägger sig utan protester.', title_vi = 'Chuông reo là đi ngủ ⏱️', body_vi = 'Giờ đi ngủ cứ kéo dài mãi. Uống nước, đi vệ sinh, chúc ngủ ngon bức tường... Hãy đặt hẹn giờ trên điện thoại. Đặt quy tắc "Nghe tiếng chuông là cả nhà tắt đèn". Nghe tiếng chuông, bé sẽ lên giường mà không phản đối gì.', title_zh = '铃声一响就睡觉 ⏱️', body_zh = '睡前时间越拖越长。喝水、上厕所、和墙壁说再见……设好手机计时器。定一个规则：“铃声一响，大家都关灯。”听到铃声，宝宝就会毫无异议地上床。' WHERE id = '9d186c69-6a80-405e-9b2f-01d72d720233' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un peque a cuatro patas 🐾', body_es = '¿Esta mañana ha salido de la cama gateando como un perrito y no como un niño? No le leas las reglas ni te enfades. Dile «¡Bravo, mi perrito listo!» y dale el desayuno. Unirte a sus juegos de rol ahorra muchísima más energía que ponerte cabezota.', title_fr = 'L''enfant à quatre pattes 🐾', body_fr = 'Ce matin, il est sorti du lit à quatre pattes, comme un chien plutôt que comme un enfant ? Ne faites pas la leçon et ne vous énervez pas. Dites « Bravo, mon toutou intelligent ! » et servez-lui son petit-déjeuner. Entrer dans ses jeux de rôle économise bien plus d''énergie que s''entêter.', title_hi = 'चार पैरों वाला बच्चा 🐾', body_hi = 'आज सुबह वह बिस्तर से बच्चे की तरह नहीं, कुत्ते की तरह रेंगते हुए निकला? नियम समझाकर परेशान मत होइए। ‘शाबाश, मेरे समझदार डॉगी’ कहकर नाश्ता दे दीजिए। रोल-प्ले में शामिल होना ज़िद करने से कहीं ज़्यादा ऊर्जा बचाता है।', title_id = 'Anak berkaki empat 🐾', body_id = 'Pagi ini ia keluar dari tempat tidur bukan seperti anak, tapi merangkak seperti anjing? Jangan membacakan aturan dan jadi kesal. Katakan ''Pintar sekali anjing kecil Mama'' dan berikan sarapannya. Ikut bermain peran jauh lebih menghemat energi daripada beradu keras kepala.', title_ja = '四つ足の子ども 🐾', body_ja = '今朝はベッドから子どもではなく、わんちゃんとしてハイハイで出てきた？ルールを説いて怒らないで。「えらいね、かしこいワンちゃん」と言って朝ごはんをあげましょう。ごっこ遊びに乗るほうが、意地の張り合いよりずっとエネルギーの節約になります。', title_ko = '네 발로 다니는 아이 🐾', body_ko = '오늘 아침 아이가 사람이 아니라 강아지처럼 기어서 침대에서 나왔나요? 훈계하며 짜증 내지 마세요. ''우리 똑똑한 멍멍이 잘했어''라며 아침을 주세요. 역할 놀이에 함께하는 게 고집 싸움보다 훨씬 에너지를 아껴 줘요.', title_nl = 'Het kind op vier pootjes 🐾', body_nl = 'Kroop hij vanochtend niet als kind, maar als hondje uit bed? Ga geen regels opsommen en word niet boos. Zeg ''Goed zo, mijn slimme hondje'' en geef hem zijn ontbijt. Meedoen met rollenspel kost veel minder energie dan koppig volhouden.', title_pl = 'Dziecko na czworakach 🐾', body_pl = 'Dziś rano wyszedł z łóżka nie jak dziecko, ale na czworakach jak piesek? Nie wygłaszaj zasad i się nie denerwuj. Powiedz: „Brawo, mój mądry piesku” i podaj śniadanie. Włączenie się w zabawę w odgrywanie ról oszczędza dużo więcej energii niż upieranie się.', title_pt = 'A criança de quatro patas 🐾', body_pt = 'Esta manhã saiu da cama não como uma criança, mas a gatinhar como um cão? Não se irrite a ditar regras. Diga "Muito bem, meu cãozinho esperto" e dê-lhe o pequeno-almoço. Entrar nos jogos de faz de conta poupa muito mais energia do que teimar.', title_sv = 'Ett barn på alla fyra 🐾', body_sv = 'Kröp barnet ur sängen i morse som en hund i stället för som ett barn? Läs inte upp regler och bli inte irriterad. Säg ”Duktig, min smarta vovve!” och servera frukosten. Att gå med i rollekar sparar mångdubbelt mer energi än att tjafsa.', title_vi = 'Em bé bốn chân 🐾', body_vi = 'Sáng nay bé không bước ra khỏi giường như một đứa trẻ mà bò ra như một chú cún? Đừng bực mình giảng giải quy tắc. Hãy nói "Giỏi lắm, cún con thông minh của mẹ" rồi đưa bữa sáng. Tham gia trò nhập vai tiết kiệm sức hơn gấp nhiều lần so với giằng co.', title_zh = '四条腿走路的孩子 🐾', body_zh = '今早宝宝不是像小孩一样，而是像小狗一样从床上爬出来的？别讲规矩、别生气。说一句“真棒，我聪明的小狗狗”，然后把早餐递过去。加入角色扮演，比较劲省力得多。' WHERE id = 'e4247830-a48b-4a17-9555-7ca391f03a7d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento de silencio perfecto 🛋️', body_es = '¿Está tan metido en sus puzles que de repente hay silencio en casa? No sospeches, sírvete un café ya mismo. Esos minutos raros y de oro no los gastes en limpiar ni en la ropa, sino en descansar el alma y mirar al techo. No eres un robot.', title_fr = 'Un moment de silence parfait 🛋️', body_fr = 'Il est tellement absorbé par ses puzzles qu''un silence soudain règne dans la maison ? Ne vous méfiez pas, servez-vous tout de suite un café. Ces minutes rares et précieuses, ne les dépensez pas en ménage ou en linge, mais à reposer votre âme et à contempler le plafond. Vous n''êtes pas un robot.', title_hi = 'खामोशी का परफ़ेक्ट पल 🛋️', body_hi = 'अपनी पज़ल से इतनी गहराई से खेल रहा है कि घर में अचानक सन्नाटा छा गया? शक मत कीजिए, फ़ौरन अपने लिए कॉफ़ी डालिए। ये दुर्लभ, सुनहरे मिनट सफ़ाई या कपड़ों पर नहीं, अपने मन को आराम देने और छत निहारने में लगाइए। आप रोबोट नहीं हैं।', title_id = 'Momen hening yang sempurna 🛋️', body_id = 'Ia begitu asyik bermain puzzle sampai rumah tiba-tiba hening? Jangan curiga, segera tuang kopi untuk diri sendiri. Pakai menit-menit langka dan berharga itu bukan untuk bersih-bersih atau cucian, tapi untuk mengistirahatkan jiwa dan memandangi langit-langit. Anda bukan robot.', title_ja = '完璧な静けさのひととき 🛋️', body_ja = 'パズルに夢中で、家が急に静かになった？疑わないで、すぐに自分にコーヒーを入れましょう。その貴重な黄金の数分間は、掃除や洗濯ではなく、心を休めて天井をながめるために使って。あなたはロボットではありません。', title_ko = '완벽한 고요의 순간 🛋️', body_ko = '퍼즐에 푹 빠져 집이 갑자기 조용해졌나요? 의심하지 말고 바로 커피 한 잔 따르세요. 이 귀한 황금 같은 몇 분은 청소나 빨래가 아니라 마음을 쉬고 천장을 바라보는 데 쓰세요. 엄마는 로봇이 아니에요.', title_nl = 'Het perfecte stille moment 🛋️', body_nl = 'Speelt hij zo geconcentreerd met zijn puzzels dat het ineens stil is in huis? Wees niet achterdochtig, schenk jezelf meteen een kop koffie in. Besteed die zeldzame, gouden minuten niet aan schoonmaken of de was, maar aan rust voor je ziel, naar het plafond staren. Je bent geen robot.', title_pl = 'Chwila idealnej ciszy 🛋️', body_pl = 'Tak bardzo pochłonęły go puzzle, że w domu nagle zrobiło się cicho? Nie podejrzewaj niczego, od razu nalej sobie kawy. Te rzadkie, złote minuty przeznacz nie na sprzątanie czy pranie, tylko na odpoczynek dla duszy i patrzenie w sufit. Nie jesteś robotem.', title_pt = 'O momento perfeito de silêncio 🛋️', body_pt = 'Está tão concentrado nos puzzles que caiu de repente o silêncio em casa? Não desconfie, sirva-se já de um café. Gaste esses minutos raros e de ouro não em limpezas ou roupa, mas a descansar a alma e a olhar para o teto. Não é um robô.', title_sv = 'En stund av perfekt tystnad 🛋️', body_sv = 'Leker barnet så djupt med pusslen att det plötsligt blev tyst hemma? Bli inte misstänksam, häll genast upp en kopp kaffe åt dig. Lägg de sällsynta, gyllene minuterna på att vila själen och stirra i taket, inte på städning eller tvätt. Du är ingen robot.', title_vi = 'Khoảnh khắc yên lặng hoàn hảo 🛋️', body_vi = 'Bé mải mê ghép hình đến mức cả nhà bỗng im phăng phắc? Đừng nghi ngờ, rót ngay cho mình một tách cà phê. Hãy dành những phút vàng hiếm hoi ấy không phải cho dọn dẹp hay quần áo, mà để tâm hồn nghỉ ngơi, ngắm trần nhà. Mẹ đâu phải người máy.', title_zh = '完美的安静时刻 🛋️', body_zh = '拼图拼得那么投入，家里突然安静下来了？别怀疑，马上给自己倒杯咖啡。把这难得的黄金几分钟，用来放松心灵、发发呆看看天花板，而不是打扫或洗衣服。你不是机器人。' WHERE id = '051e4221-4f19-4e4b-a097-d797006e0813' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La etiqueta de la camiseta pica! 🏷️', body_es = '¿No se la quiere poner porque esa etiquetita de atrás se le clava como una aguja? La sensibilidad sensorial de esta edad vuelve loco a cualquiera. No entres a discutir: coge las tijeras, córtala de raíz y cierra esta minicrisis en un segundo.', title_fr = 'L''étiquette du t-shirt pique ! 🏷️', body_fr = 'Il refuse de s''habiller parce que la petite étiquette au dos le pique comme une aiguille ? La sensibilité sensorielle de cet âge rend fou. N''entrez même pas dans la discussion : prenez les ciseaux, coupez-la à la racine et réglez cette mini-crise en une seconde.', title_hi = 'कमीज़ का लेबल चुभ रहा है! 🏷️', body_hi = 'कपड़े नहीं पहनेगा, क्योंकि पीछे का वह छोटा लेबल उसे सुई की तरह चुभता है? इस उम्र की संवेदी संवेदनशीलता किसी को भी पागल कर दे। बहस में मत पड़िए, कैंची उठाइए, जड़ से काट दीजिए और यह छोटा संकट सेकंडों में खत्म कीजिए।', title_id = 'Label bajunya menusuk! 🏷️', body_id = 'Ia tidak mau berpakaian karena label kecil di belakang bajunya terasa menusuk seperti jarum? Kepekaan sensorik usia ini memang bisa bikin pusing. Jangan berdebat, ambil gunting, potong labelnya sampai habis, dan tutup krisis kecil ini dalam sekejap.', title_ja = 'シャツのタグがチクチク！ 🏷️', body_ja = '背中の小さなタグが針のように刺さるから、着ないと言う？この年齢の感覚の敏感さには参りますよね。言い合いはせずに、はさみでタグを根元から切って、このミニ危機をすぐに解決しましょう。', title_ko = '옷 라벨이 따가워! 🏷️', body_ko = '뒤에 달린 작은 라벨이 바늘처럼 찔러서 안 입겠다고 하나요? 이 나이의 감각 예민함은 정말 사람을 미치게 하죠. 다투지 말고 가위로 라벨을 싹 잘라 이 작은 위기를 바로 끝내세요.', title_nl = 'Dat labeltje prikt! 🏷️', body_nl = 'Wil hij zich niet aankleden omdat dat kleine labeltje achterin prikt als een naald? De zintuiglijke gevoeligheid op deze leeftijd kan je gek maken. Ga niet in discussie, pak de schaar, knip het eraf en los deze minicrisis in een seconde op.', title_pl = 'Metka w koszulce gryzie! 🏷️', body_pl = 'Nie założy, bo ta mała metka z tyłu kłuje go jak igła? Wrażliwość sensoryczna w tym wieku potrafi doprowadzić do szału. Nie wchodź w dyskusję, weź nożyczki, odetnij ją u nasady i zamknij ten mini kryzys w sekundę.', title_pt = 'A etiqueta da camisola pica! 🏷️', body_pt = 'Não se quer vestir porque aquela etiquetazinha atrás o pica como uma agulha? A sensibilidade sensorial desta idade dá com qualquer um em doido. Não discuta: pegue na tesoura, corte-a pela raiz e resolva esta mini-crise num segundo.', title_sv = 'Lappen på tröjan sticks! 🏷️', body_sv = 'Barnet vägrar ta på sig tröjan för att den lilla lappen i nacken sticks som en nål? Den sensoriska känsligheten i den här åldern kan göra vem som helst galen. Gå inte in i något gräl, ta saxen, klipp bort lappen helt och avsluta minikrisen på en sekund.', title_vi = 'Mác áo cấn quá! 🏷️', body_vi = 'Bé không chịu mặc áo vì cái mác nhỏ sau lưng cấn như kim châm? Sự nhạy cảm giác quan ở tuổi này có thể khiến mẹ phát điên. Đừng tranh cãi, cầm kéo cắt tận gốc và kết thúc "khủng hoảng mini" này trong vài giây.', title_zh = '衣服标签扎人！🏷️', body_zh = '不肯穿，因为背后那个小标签像针一样扎？这个年龄的感官敏感真能把人逼疯。别争了，拿起剪刀从根部剪掉，几秒钟就化解这场小危机。' WHERE id = '87efef38-8bd8-470c-82a9-956ee26f1fa2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con susurros 🤫', body_es = '¿Se levanta de la cama, corre por la habitación y no quiere dormir? No grites. De repente, empieza a hablar muy despacio, en susurros. Tendrá que concentrarse tanto para entenderte que su cerebro se cansará y pasará solo al modo sueño. ¡Pruébalo!', title_fr = 'S''endormir en chuchotant 🤫', body_fr = 'Il sort du lit et court dans la chambre, il ne veut pas dormir ? Ne criez pas. Mettez-vous soudain à parler très lentement, en chuchotant. Pour vous comprendre, il devra tellement se concentrer que son cerveau, fatigué, passera automatiquement en mode sommeil. Essayez !', title_hi = 'फुसफुसाहट के साथ नींद 🤫', body_hi = 'बिस्तर से उठकर कमरे में दौड़ रहा है, सोना नहीं चाहता? चिल्लाइए मत। अचानक बहुत धीरे, फुसफुसाकर बोलना शुरू कीजिए। आपको समझने के लिए उसे इतना ध्यान लगाना पड़ेगा कि दिमाग थककर अपने आप स्लीप मोड में चला जाएगा। आज़माइए!', title_id = 'Tertidur dengan bisikan 🤫', body_id = 'Ia bangun dari tempat tidur dan berlarian di kamar, tidak mau tidur? Jangan berteriak. Tiba-tiba mulailah berbicara sangat pelan dan berbisik. Untuk memahami Anda, ia harus sangat berkonsentrasi sampai otaknya lelah dan otomatis masuk ke mode tidur. Coba saja!', title_ja = 'ささやき声で眠りへ 🤫', body_ja = 'ベッドから出て部屋を走りまわり、寝たがらない？叫ばないで。急にとてもゆっくり、ささやき声で話し始めてみましょう。聞きとろうと集中するうちに脳が疲れて、自然と睡眠モードに切りかわります。ためしてみて！', title_ko = '속삭임으로 잠들기 🤫', body_ko = '침대에서 일어나 방을 뛰어다니며 안 자려고 하나요? 소리치지 마세요. 갑자기 아주 천천히, 속삭이듯 말하기 시작하세요. 엄마 말을 알아들으려 집중하다 보면 머리가 지쳐 저절로 수면 모드로 넘어갈 거예요. 해 보세요!', title_nl = 'Fluisterend in slaap 🤫', body_nl = 'Komt hij uit bed en rent hij door de kamer, omdat hij niet wil slapen? Ga niet schreeuwen. Ga ineens heel langzaam en fluisterend praten. Om je te verstaan moet hij zich zo concentreren dat zijn brein moe wordt en vanzelf in slaapstand gaat. Probeer het!', title_pl = 'Zasypianie przy szepcie 🤫', body_pl = 'Wstaje z łóżka, biega po pokoju i nie chce spać? Nie krzycz. Nagle zacznij mówić bardzo cicho, szeptem. Żeby cię zrozumieć, będzie musiał tak bardzo się skupić, że jego mózg się zmęczy i automatycznie przejdzie w tryb snu. Sprawdź!', title_pt = 'Adormecer a sussurrar 🤫', body_pt = 'Levanta-se da cama e corre pelo quarto, não quer dormir? Não grite. Comece de repente a falar muito devagar, em sussurro. Para a perceber, vai ter de se concentrar tanto que o cérebro se cansa e passa automaticamente para o modo de sono. Experimente!', title_sv = 'Att somna till viskningar 🤫', body_sv = 'Kliver barnet ur sängen, springer runt i rummet och vill inte sova? Skrik inte. Börja plötsligt prata väldigt långsamt och viskande. Barnet måste koncentrera sig så mycket för att förstå dig att hjärnan blir trött och går över i sömnläge automatiskt. Prova!', title_vi = 'Đưa bé vào giấc ngủ bằng lời thì thầm 🤫', body_vi = 'Bé bật dậy khỏi giường, chạy quanh phòng, không chịu ngủ? Đừng quát. Bỗng nhiên hãy nói thật chậm, thì thầm. Bé sẽ phải tập trung cao độ để hiểu mẹ, đến mức não mệt và tự động chuyển sang chế độ ngủ. Thử xem!', title_zh = '在悄悄话里入睡 🤫', body_zh = '从床上爬起来满屋跑，不想睡觉？别吼。突然用很轻很慢的悄悄话说话。为了听懂你，宝宝得非常专心，大脑累了就会自动切换到睡眠模式。试试看！' WHERE id = 'd321475d-a2ef-4c95-8a95-ccdb6522c470' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La mentira de «¡Lo ha tirado mi juguete!» 🤷‍♂️', body_es = '¿Ha tirado el agua al suelo a propósito, pero señala su coche con el dedo y dice «Me ha empujado»? No es mentir, es un mecanismo de defensa. Dile «Vamos a enseñarle también a ese coche cómo se limpia» y despista su cabecita con maña.', title_fr = 'Le mensonge du « C''est mon jouet qui l''a fait tomber ! » 🤷‍♂️', body_fr = 'Il a renversé l''eau exprès, mais montre sa voiture du doigt en disant « C''est elle qui l''a poussée » ? Ce n''est pas un mensonge, c''est un mécanisme de défense. Dites « Viens, on va apprendre à cette voiture comment on nettoie » et détournez habilement son attention.', title_hi = '‘मेरे खिलौने ने गिराया!’ वाला झूठ 🤷‍♂️', body_hi = 'जानबूझकर पानी गिराया, पर उँगली से अपनी गाड़ी दिखाकर बोला, ‘इसने धक्का दिया’? यह झूठ नहीं, बचाव का तरीका है। ‘चलो, उस गाड़ी को भी सिखाते हैं कि सफ़ाई कैसे करते हैं’ कहकर बड़ी चतुराई से उसका ध्यान बहलाइए।', title_id = 'Kebohongan ''Mainanku yang menjatuhkan!'' 🤷‍♂️', body_id = 'Ia sengaja menumpahkan air ke lantai, tapi menunjuk mobilnya dan berkata ''Dia yang dorong''? Ini bukan berbohong, ini mekanisme perlindungan diri. Katakan ''Ayo kita ajari mobil itu cara membersihkannya'' dan kelabui pikirannya dengan cerdik.', title_ja = '「おもちゃがたおしたの！」といううそ 🤷‍♂️', body_ja = 'わざとお水を床にこぼしたのに、指で車をさして「この子が押した」と言った？うそではなく、自分を守る仕組みです。「じゃあ、その車にも拭き方を教えてあげよう」と言って、上手に気持ちを切りかえましょう。', title_ko = '''장난감이 넘어뜨렸어!'' 거짓말 🤷‍♂️', body_ko = '일부러 물을 쏟아 놓고 자동차를 가리키며 ''얘가 밀었어''라고 했나요? 거짓말이 아니라 방어 기제예요. ''그럼 자동차한테도 어떻게 닦는지 가르쳐 주자'' 하며 능숙하게 아이의 관심을 돌리세요.', title_nl = 'De smoes ''Mijn speelgoed deed het!'' 🤷‍♂️', body_nl = 'Gooide hij expres water op de grond, maar wees hij naar zijn autootje: ''Die duwde het''? Dat is geen liegen, maar een verdedigingsmechanisme. Zeg ''Kom, dan leren we die auto ook hoe je opruimt'' en speel slim in op zijn brein.', title_pl = 'Kłamstewko „To zabawka przewróciła!” 🤷‍♂️', body_pl = 'Celowo wylał wodę na podłogę, ale pokazał palcem na swoje autko i powiedział: „To ono popchnęło”? To nie kłamstwo, tylko mechanizm obronny. Powiedz: „To nauczmy też autko, jak się sprząta” i zręcznie go przechytrz.', title_pt = 'A mentira do "Foi o meu brinquedo!" 🤷‍♂️', body_pt = 'Entornou a água de propósito, mas apontou para o carrinho e disse "Foi ele que empurrou"? Não é mentir, é um mecanismo de defesa. Diga "Então vamos ensinar o carro a limpar" e engane o cérebro dele com mestria.', title_sv = 'Lögnen ”Min leksak välte det!” 🤷‍♂️', body_sv = 'Spillde barnet vatten på golvet med flit, men pekade på bilen och sa ”Den knuffade”? Det är inte att ljuga, det är en försvarsmekanism. Säg ”Kom, då lär vi bilen hur man torkar upp” och lura hjärnan skickligt.', title_vi = 'Lời nói dối "Đồ chơi làm đổ!" 🤷‍♂️', body_vi = 'Bé cố tình làm đổ nước nhưng lại chỉ vào chiếc xe đồ chơi: "Nó đẩy đấy"? Đây không phải nói dối, mà là cơ chế tự vệ. Hãy khéo léo "lừa" bộ não nhỏ: "Vậy mình cùng dạy chiếc xe cách lau nhé."', title_zh = '“是我的玩具弄倒的！”的谎话 🤷‍♂️', body_zh = '故意把水洒在地上，却指着小汽车说“是它推的”？这不是撒谎，而是自我保护机制。说一句“那我们也教教小汽车怎么擦干净吧”，巧妙地转移宝宝的注意力。' WHERE id = '7e80987d-061d-4fcd-8171-45d84324b66e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El número del silencio en la pantalla 🤫', body_es = 'Por fin se ha dormido. ¿Hay tanto silencio en casa que te pitan los oídos? Abre el Medidor de sonido en la app. Ver ese 0 decibelios será el mejor masaje visual del mundo para tu cerebro cansado y saturado de ruido.', title_fr = 'Le chiffre du silence à l''écran 🤫', body_fr = 'Il dort enfin. Un tel silence est tombé sur la maison que vos oreilles bourdonnent ? Ouvrez le Sonomètre dans l''application. Voir afficher 0 décibel sera le meilleur massage visuel au monde pour votre cerveau fatigué, saturé de bruit.', title_hi = 'स्क्रीन पर खामोशी का आँकड़ा 🤫', body_hi = 'आखिरकार सो गया। घर में ऐसा सन्नाटा छा गया कि कानों में सीटी सी बज रही है? ऐप में साउंड मीटर खोलिए। वह ‘0 डेसिबल’ देखना आपके थके, शोर से भरे दिमाग के लिए दुनिया की सबसे अच्छी विज़ुअल मसाज होगी।', title_id = 'Angka keheningan di layar 🤫', body_id = 'Akhirnya ia tidur. Rumah begitu hening sampai telinga Anda berdenging? Buka Pengukur Suara di aplikasi. Melihat tulisan 0 desibel itu akan menjadi pijatan visual terbaik di dunia untuk otak Anda yang lelah dan penuh kebisingan.', title_ja = '静けさを示す画面の数字 🤫', body_ja = 'やっと寝てくれた。家が静かすぎて耳鳴りがする？アプリで「サウンドメーター」を開いてみて。0デシベルの表示を見ることが、疲れて騒音でいっぱいの頭にとって、世界一の目のマッサージになります。', title_ko = '화면 속 고요의 숫자 🤫', body_ko = '드디어 잠들었어요. 집이 너무 고요해져 귀가 울릴 정도인가요? 앱에서 소음 측정기를 열어 보세요. 0 데시벨이라는 숫자를 보는 것만으로 소음에 지친 머리에 세상에서 가장 좋은 시각적 마사지가 될 거예요.', title_nl = 'Stilte in cijfers op het scherm 🤫', body_nl = 'Eindelijk slaapt hij. Is het zo stil in huis dat je oren suizen? Open de Geluidsmeter in de app. Kijken naar die 0 decibel is de beste visuele massage voor je vermoeide, door lawaai overprikkelde brein.', title_pl = 'Cisza w liczbach na ekranie 🤫', body_pl = 'Wreszcie zasnął. W domu zapadła taka cisza, że aż dzwoni ci w uszach? Otwórz w aplikacji Miernik dźwięku. Widok napisu 0 decybeli będzie dla twojego zmęczonego, przeładowanego hałasem mózgu najlepszym wizualnym masażem na świecie.', title_pt = 'O número do silêncio no ecrã 🤫', body_pt = 'Finalmente adormeceu. Caiu um silêncio tão grande na casa que lhe zumbem os ouvidos? Abra o Medidor de Som na app. Olhar para aqueles 0 decibéis será a melhor massagem visual do mundo para o seu cérebro cansado e inchado de barulho.', title_sv = 'Tystnaden i siffror på skärmen 🤫', body_sv = 'Äntligen sover barnet. Det har blivit så tyst hemma att det ringer i öronen? Öppna Ljudmätaren i appen. Att titta på 0 decibel blir världens bästa visuella massage för din trötta, bullerfyllda hjärna.', title_vi = 'Con số của sự im lặng trên màn hình 🤫', body_vi = 'Cuối cùng bé cũng ngủ. Nhà yên tĩnh đến mức tai mẹ ù đi? Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số 0 decibel sẽ là màn mát-xa thị giác tuyệt vời nhất cho bộ não mệt mỏi, căng thẳng vì tiếng ồn của mẹ.', title_zh = '屏幕上的安静数字 🤫', body_zh = '终于睡着了。家里安静得让你耳朵都嗡嗡响？打开应用里的分贝仪。看着那个0分贝，对你疲惫、被噪音塞满的大脑来说，就是世界上最好的视觉按摩。' WHERE id = 'a3c5807d-b2c4-4369-a70a-3e8219c1c3ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación verduras invisibles 🥦', body_es = '¿Ha encontrado esa única zanahoria en la sopa y ha dicho «Esto no me lo como»? ¡Escena conocida! Haz puré las verduras y mételas en las salsas, ¡a ver cómo las encuentra ahora! Gánale a ese genio de la cocina.', title_fr = 'Opération légumes invisibles 🥦', body_fr = 'Il a trouvé l''unique rondelle de carotte dans la soupe et a dit « Je mange pas ça » ? Scène connue ! Réduisez les légumes en purée et ajoutez-les aux sauces, on verra s''il les trouve maintenant ! Battez ce petit génie culinaire.', title_hi = 'अदृश्य सब्ज़ियों का मिशन 🥦', body_hi = 'सूप में गाजर का वह एक टुकड़ा ढूँढकर बोला, ‘यह मैं नहीं खाऊँगा’? जाना-पहचाना नज़ारा है! सब्ज़ियों की प्यूरी बनाकर सॉस में मिलाइए, फिर देखते हैं कैसे ढूँढता है! उसकी पाक-कला वाली समझ को मात दीजिए।', title_id = 'Operasi sayur tak kasatmata 🥦', body_id = 'Ia menemukan satu potong wortel di supnya dan berkata ''Aku nggak mau makan ini''? Pemandangan yang akrab! Haluskan sayurnya dan campurkan ke saus, coba lihat bagaimana ia akan menemukannya sekarang! Kalahkan kecerdasan kulinernya itu.', title_ja = '見えない野菜作戦 🥦', body_ja = 'スープの中のにんじんひとかけを見つけて「これは食べない」と言った？よくある光景です！野菜をピューレにしてソースにまぜ、さあ見つけられるかな！この小さなシェフの知恵に勝ちましょう。', title_ko = '보이지 않는 채소 작전 🥦', body_ko = '수프 속 당근 한 조각을 찾아내고 ''이거 안 먹어'' 했나요? 익숙한 장면이죠! 채소를 퓌레로 만들어 소스에 섞어 보세요. 이제 어떻게 찾나 볼까요! 그 요리 감별 능력을 이겨 보세요.', title_nl = 'Operatie onzichtbare groenten 🥦', body_nl = 'Vond hij dat ene stukje wortel in zijn soep en zei hij ''Dit eet ik niet''? Herkenbaar! Pureer de groenten en verwerk ze in sauzen, eens kijken hoe hij ze nu vindt! Wees zijn kookinstinct te slim af.', title_pl = 'Operacja niewidzialne warzywa 🥦', body_pl = 'Znalazł w zupie tę jedną marchewkę i oznajmił: „Tego nie jem”? Znajomy widok! Zmiksuj warzywa i dodaj je do sosów, zobaczymy, jak teraz je znajdzie! Przechytrz ten kulinarny geniusz.', title_pt = 'Operação legumes invisíveis 🥦', body_pt = 'Encontrou na sopa aquele único pedaço de cenoura e disse "Isto não como"? Cena conhecida! Faça puré dos legumes e junte-os aos molhos: vamos ver como os encontra agora! Vença aquela inteligência de pequeno chef.', title_sv = 'Operation osynliga grönsaker 🥦', body_sv = 'Hittade barnet den enda morotsbiten i soppan och sa ”Det där äter jag inte”? Bekant scen! Mixa grönsakerna och blanda dem i såser, så får vi se hur hen hittar dem nu! Överlista den lilla kockhjärnan.', title_vi = 'Chiến dịch rau củ vô hình 🥦', body_vi = 'Bé tìm ra đúng một miếng cà rốt trong súp và tuyên bố "Con không ăn cái này"? Cảnh quen thuộc quá! Hãy xay nhuyễn rau và trộn vào nước sốt, xem giờ bé còn tìm thấy không! Hãy chiến thắng "trí tuệ ẩm thực" ấy.', title_zh = '隐形蔬菜行动 🥦', body_zh = '在汤里找到唯一一块胡萝卜，就说“我不吃这个”？这场面太熟悉了！把蔬菜打成泥拌进酱汁里，看宝宝现在还怎么找！智胜这位小美食家吧。' WHERE id = 'c034d9ff-ba06-4346-b3af-4ee27df0fc64' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi cuerpo no es mío 🔋', body_es = '¿Se te pega a las piernas todo el día pidiendo brazos? Estás agotada físicamente. Estás saturada de contacto. Déjalo en su habitación con sus juguetes, escápate 5 minutos al baño y cierra la puerta. Solo siente esa soledad.', title_fr = 'Mon corps ne m''appartient plus 🔋', body_fr = 'Il s''accroche à vos jambes toute la journée et veut des câlins ? Vous êtes physiquement à bout. Vous vivez la saturation du toucher. Laissez-le dans la pièce avec ses jouets, filez 5 minutes dans la salle de bain et fermez la porte. Ressentez simplement cette solitude.', title_hi = 'मेरा शरीर मेरा नहीं रहा 🔋', body_hi = 'दिनभर पैरों से लिपटा रहता है, गोद माँगता है? आप शारीरिक रूप से थक चुकी हैं। यह छुए जाने की थकान है। उसे खिलौनों के साथ कमरे में छोड़कर 5 मिनट बाथरूम चली जाइए, दरवाज़ा बंद कीजिए। बस उस अकेलेपन को महसूस कीजिए।', title_id = 'Tubuhku bukan milikku 🔋', body_id = 'Seharian ia menempel di kaki Anda dan minta digendong? Secara fisik Anda sudah habis. Anda sedang mengalami kelelahan disentuh. Tinggalkan ia di kamar dengan mainannya, larilah ke kamar mandi selama 5 menit, dan tutup pintunya. Rasakan saja kesendirian itu.', title_ja = 'わたしの体はわたしのものじゃない 🔋', body_ja = '一日じゅう足にしがみついて抱っこをせがむ？体力が尽きていますね。触れられ疲れを感じているんです。おもちゃと一緒に部屋で遊ばせて、5分だけお風呂場に逃げこみ、ドアを閉めて。ただそのひとりの時間を感じましょう。', title_ko = '내 몸이 내 것이 아닌 느낌 🔋', body_ko = '하루 종일 다리에 매달려 안아 달라고 하나요? 몸이 완전히 지쳤어요. 터치 피로를 겪고 있는 거예요. 아이를 장난감과 함께 방에 두고 5분만 욕실로 피신해 문을 닫으세요. 그저 혼자임을 느껴 보세요.', title_nl = 'Mijn lichaam is niet van mij 🔋', body_nl = 'Hangt hij de hele dag aan je been en wil hij steeds op schoot? Je bent lichamelijk op. Je hebt last van aanrakingsmoeheid. Laat hem met zijn speelgoed in de kamer, vlucht 5 minuten naar de badkamer en doe de deur dicht. Voel gewoon even die rust van het alleen zijn.', title_pl = 'Moje ciało nie należy do mnie 🔋', body_pl = 'Cały dzień wisi ci na nodze i chce na ręce? Jesteś fizycznie wyczerpana. Przeżywasz przebodźcowanie dotykiem. Zostaw go z zabawkami w pokoju, uciekaj na 5 minut do łazienki i zamknij drzwi. Po prostu poczuj tę samotność.', title_pt = 'O meu corpo não me pertence 🔋', body_pt = 'Passa o dia agarrado às suas pernas a pedir colo? Está fisicamente esgotada. É o cansaço de toque. Deixe-o no quarto com os brinquedos, fuja 5 minutos para a casa de banho e feche a porta. Sinta apenas essa solidão.', title_sv = 'Min kropp tillhör inte mig 🔋', body_sv = 'Hänger barnet i benen hela dagen och vill bli buren? Du är fysiskt slutkörd. Du upplever beröringsutmattning. Lämna barnet med leksakerna i ett säkert rum, fly till badrummet i 5 minuter och stäng dörren. Känn bara ensamheten.', title_vi = 'Cơ thể này không còn là của mình 🔋', body_vi = 'Cả ngày bé bám chân, đòi bế? Mẹ đã kiệt sức về thể chất. Mẹ đang "quá tải vì bị chạm". Hãy để bé chơi đồ chơi trong phòng, trốn vào phòng tắm 5 phút và đóng cửa lại. Chỉ cần cảm nhận khoảnh khắc một mình ấy.', title_zh = '我的身体不属于我了 🔋', body_zh = '一整天抱着你的腿，要你抱？你的身体已经透支了。这是“触碰疲劳”。让宝宝在房间里玩玩具，你躲进浴室5分钟，关上门。好好感受那份独处。' WHERE id = '3b221a5a-9106-4d1d-8e8e-3de653008273' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un grito repentino a medianoche 😭', body_es = '¿Se ha despertado de noche llorando con los ojos cerrados y no te oye? Pasa por el Análisis del llanto: son terrores nocturnos. Intenta no despertarlo, solo quédate a su lado, cógele la mano y acarícialo. Se calmará solo y volverá a dormirse profundamente.', title_fr = 'Un cri soudain en pleine nuit 😭', body_fr = 'Il s''est réveillé la nuit en pleurant, les yeux fermés, et ne vous entend pas ? Vérifiez avec l''Analyse des pleurs : c''est une terreur nocturne. N''essayez pas de le réveiller, restez simplement près de lui, tenez-lui la main et caressez-le. Il se calmera de lui-même et retombera dans un sommeil profond.', title_hi = 'आधी रात को अचानक चीख 😭', body_hi = 'रात को आँखें बंद किए रोते हुए जागा और आपकी बात नहीं सुन रहा? क्राइंग एनालिसिस बताता है: यह नाइट टेरर है। जगाने की कोशिश मत कीजिए, बस पास रहिए, हाथ थामकर सहलाइए। वह अपने आप शांत होकर फिर गहरी नींद में चला जाएगा।', title_id = 'Jeritan tiba-tiba di tengah malam 😭', body_id = 'Malam-malam ia terbangun menangis dengan mata terpejam dan tidak mendengar Anda? Periksa dengan Analisis Tangisan; ini teror tidur (night terror). Jangan coba membangunkannya, cukup berada di sampingnya, pegang dan usap tangannya. Ia akan tenang sendiri dan kembali tidur nyenyak.', title_ja = '真夜中の突然の叫び 😭', body_ja = '夜中に目を閉じたまま泣いて起き、あなたの声が聞こえていない？「泣き声分析」で確かめてみましょう。これは夜驚症です。起こそうとせず、ただそばにいて手をにぎり、なでてあげて。自然に落ち着いて、また深い眠りに戻ります。', title_ko = '한밤중 갑작스러운 비명 😭', body_ko = '밤에 눈을 감은 채 울며 깨어나 엄마 말을 듣지 못하나요? 울음 분석은 넘기세요, 이건 야경증이에요. 깨우려 하지 말고 곁에서 손을 잡고 쓰다듬어 주세요. 스스로 진정하고 다시 깊이 잠들 거예요.', title_nl = 'Plots gegil midden in de nacht 😭', body_nl = 'Werd hij ''s nachts huilend wakker met zijn ogen dicht en hoort hij je niet? Laat het door Huilanalyse gaan; dit is nachtangst (pavor nocturnus). Probeer hem niet wakker te maken, blijf gewoon bij hem, pak zijn hand en aai hem. Hij kalmeert vanzelf en valt weer diep in slaap.', title_pl = 'Nagły krzyk w środku nocy 😭', body_pl = 'W nocy obudził się z płaczem, z zamkniętymi oczami, i cię nie słyszy? Sprawdź to w Analizie płaczu; to lęk nocny. Nie próbuj go budzić, po prostu bądź obok, trzymaj go za rękę i głaszcz. Sam się uspokoi i znów zapadnie w głęboki sen.', title_pt = 'Gritos repentinos a meio da noite 😭', body_pt = 'Acordou de noite a chorar, de olhos fechados, e não a ouve? Confirme com a Análise do Choro: é terror noturno. Tente não o acordar, fique só ao lado dele, pegue-lhe na mão e faça-lhe festas. Vai acalmar-se sozinho e voltar a adormecer profundamente.', title_sv = 'Ett plötsligt skrik mitt i natten 😭', body_sv = 'Vaknade barnet gråtande på natten med slutna ögon och hör dig inte? Kontrollera med Gråtanalys; det är nattskräck. Försök inte väcka barnet, stå bara bredvid, håll handen och stryk lätt. Barnet lugnar sig av sig självt och somnar djupt igen.', title_vi = 'Tiếng hét bất ngờ lúc nửa đêm 😭', body_vi = 'Ban đêm bé khóc thét, mắt vẫn nhắm và không nghe thấy mẹ? Hãy kiểm tra bằng Phân tích tiếng khóc; đây là hoảng sợ khi ngủ. Cố đừng đánh thức bé, chỉ cần ở bên, nắm tay và vuốt ve. Bé sẽ tự bình tĩnh lại và chìm vào giấc ngủ sâu.', title_zh = '半夜突然尖叫 😭', body_zh = '半夜闭着眼睛哭醒，好像听不见你说话？用哭声分析看看：这是夜惊。尽量别叫醒宝宝，只要陪在身边，握着小手轻轻抚摸。宝宝会自己平静下来，重新进入深睡。' WHERE id = '633ad245-30eb-4956-9f39-7177c312745a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desastre del pinche de cocina 🧑‍🍳', body_es = '¿Mientras estirabas la masa ha venido, ha puesto su silla y quería echar él la harina sí o sí? Si no le dejas, llorará. Dale un bol pequeño de plástico y un poco de harina. La cocina quedará hecha un desastre, pero esa cara seria de chef vale más que tu limpieza.', title_fr = 'La catastrophe du petit commis de cuisine 🧑‍🍳', body_fr = 'Pendant que vous étaliez la pâte, il a installé sa chaise et voulait absolument verser la farine lui-même ? Si vous refusez, il pleurera. Donnez-lui un petit bol en plastique et un peu de farine. La cuisine sera sens dessus dessous, mais sa mine de chef sérieux vaut bien votre ménage.', title_hi = 'रसोई में मददगार वाली आफ़त 🧑‍🍳', body_hi = 'आप आटा बेल रही थीं, वह आकर अपनी कुर्सी लगा बैठा और आटा खुद ही डालना चाहता है? मना करेंगी तो रोएगा। उसे एक छोटा प्लास्टिक का कटोरा और थोड़ा आटा दे दीजिए। रसोई गंदी होगी, पर उसके गंभीर शेफ़ वाले चेहरे के आगे आपकी सफ़ाई कुछ भी नहीं।', title_id = 'Bencana si asisten dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia datang membawa kursinya dan bersikeras menuang tepung sendiri? Kalau tidak diizinkan, ia akan menangis. Beri ia mangkuk plastik kecil dan sedikit tepung. Dapur akan belepotan, tapi ekspresi koki seriusnya itu sepadan dengan kebersihan Anda.', title_ja = 'キッチンのお手伝い大惨事 🧑‍🍳', body_ja = '生地をのばしていると、いすを持ってきて粉を自分で入れたがった？だめと言えば泣いてしまう。小さなプラスチックのボウルと少しの粉を渡しましょう。キッチンは粉だらけになりますが、その真剣なシェフの顔は、掃除の手間に見合う価値があります。', title_ko = '주방 도우미 대참사 🧑‍🍳', body_ko = '반죽을 밀고 있는데 의자를 끌고 와서 꼭 밀가루를 자기가 붓겠다고 하나요? 허락하지 않으면 울 거예요. 작은 플라스틱 그릇과 밀가루를 조금 주세요. 부엌은 엉망이 되겠지만, 그 진지한 꼬마 셰프의 표정은 깨끗한 부엌보다 값져요.', title_nl = 'Rampenhulpje in de keuken 🧑‍🍳', body_nl = 'Was je deeg aan het uitrollen en zette hij zijn stoel ernaast om per se zelf de bloem te storten? Laat je het niet toe, dan gaat hij huilen. Geef hem een klein plastic bakje en wat bloem. De keuken wordt een ravage, maar die serieuze koksblik is je schoonmaakwerk waard.', title_pl = 'Katastrofa pomocnika w kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, przystawił krzesło i koniecznie chce sam wsypać mąkę? Jeśli nie pozwolisz, będzie płakał. Daj mu małą plastikową miskę i trochę mąki. Kuchnia będzie w mące, ale jego poważna mina kucharza jest warta twojego sprzątania.', title_pt = 'O desastre do ajudante de cozinha 🧑‍🍳', body_pt = 'Enquanto estendia a massa, ele pôs a cadeira ao seu lado e quis deitar a farinha sozinho? Se não deixar, vai chorar. Dê-lhe uma pequena taça de plástico e um pouco de farinha. A cozinha vai ficar um caos, mas aquela cara séria de cozinheiro vale bem a limpeza.', title_sv = 'Köksmedhjälparkatastrofen 🧑‍🍳', body_sv = 'Kom barnet och ställde fram sin stol när du kavlade degen och ville absolut hälla i mjölet själv? Om du säger nej blir det gråt. Ge barnet en liten plastskål och lite mjöl. Köket blir nedsölat, men den allvarliga kockminen är värd din städning.', title_vi = 'Thảm họa phụ bếp 🧑‍🍳', body_vi = 'Mẹ đang cán bột thì bé kê ghế lại và nhất định đòi tự đổ bột? Không cho thì bé sẽ khóc. Hãy đưa bé một chiếc bát nhựa nhỏ và ít bột. Căn bếp sẽ ngập bột, nhưng vẻ mặt đầu bếp nghiêm túc ấy đáng giá hơn công dọn dẹp của mẹ.', title_zh = '厨房小帮手大灾难 🧑‍🍳', body_zh = '你擀面团时，宝宝搬来椅子，非要自己倒面粉？不让就会哭。给宝宝一个小塑料碗和一点面粉吧。厨房会变得一团糟，但那副认真的小厨师表情，值得你多打扫一次。' WHERE id = '8febb55a-81bd-4c4c-969e-a2b64ee79f90' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La puerta la abro yo! 🚪', body_es = '¿Al salir de casa ha llorado para que volvieras a cerrar la puerta porque la abriste tú, y luego la ha abierto él? A esta edad, la sensación de control es la mayor necesidad psicológica. Pierde 1 minuto, pero evita una crisis de 30 minutos en la calle.', title_fr = 'C''est moi qui ouvre la porte ! 🚪', body_fr = 'En sortant, il a pleuré parce que c''est vous qui avez ouvert la porte, vous l''a fait refermer et l''a ouverte lui-même ? À cet âge, le sentiment de contrôle est le plus grand besoin psychologique. Laissez-le vous faire perdre 1 minute, mais évitez une crise de 30 minutes dans la rue.', title_hi = 'दरवाज़ा मैं खोलूँगा! 🚪', body_hi = 'घर से निकलते समय दरवाज़ा आपने खोला, इसलिए रो-रोकर फिर बंद करवाया और खुद खोला? इस उम्र में नियंत्रण का एहसास सबसे बड़ी मानसिक ज़रूरत है। इसमें आपका 1 मिनट जाएगा, पर बाहर होने वाले 30 मिनट के झगड़े से बच जाएँगी।', title_id = 'Aku yang buka pintunya! 🚪', body_id = 'Saat keluar rumah ia menangis dan menyuruh pintunya ditutup lagi karena Anda yang membukanya, lalu ia membukanya sendiri? Rasa memegang kendali adalah kebutuhan psikologis terbesar di usia ini. Biarlah Anda kehilangan 1 menit, tapi cegah krisis 30 menit di jalan.', title_ja = 'ドアはぼくが開ける！ 🚪', body_ja = '出かけるときにあなたがドアを開けたら、泣いて閉めなおさせ、自分で開けた？この年齢では、自分でコントロールしたい気持ちがいちばん大きな心の欲求です。1分かかってもいいから、外での30分のかんしゃくを防ぎましょう。', title_ko = '문은 내가 열 거야! 🚪', body_ko = '외출할 때 엄마가 문을 열었다고 울면서 다시 닫게 하고 자기가 열었나요? 이 나이에 통제감은 가장 큰 심리적 욕구예요. 1분 손해 보더라도, 밖에서 30분짜리 떼를 미리 막으세요.', title_nl = 'Ik doe de deur open! 🚪', body_nl = 'Liet hij je huilend de deur weer dichtdoen omdat jij hem opendeed toen jullie weggingen, zodat hij hem zelf kon openen? Een gevoel van controle is op deze leeftijd de grootste psychologische behoefte. Laat hem je die ene minuut kosten en voorkom een crisis van 30 minuten op straat.', title_pl = 'Ja otworzę drzwi! 🚪', body_pl = 'Przy wyjściu z domu płakał, bo to ty otworzyłaś drzwi, kazał je zamknąć i otworzył sam? Poczucie kontroli to w tym wieku największa potrzeba psychologiczna. Stracisz 1 minutę, ale zapobiegniesz 30-minutowemu kryzysowi na ulicy.', title_pt = 'Sou eu que abro a porta! 🚪', body_pt = 'Ao sair de casa, chorou e obrigou-a a fechar a porta outra vez para a abrir ele, porque foi a mãe a abri-la? Nesta idade, a sensação de controlo é a maior necessidade psicológica. Deixe-o fazê-la perder 1 minuto, mas evite uma crise de 30 minutos na rua.', title_sv = 'Jag öppnar dörren! 🚪', body_sv = 'Grät barnet och fick dig att stänga dörren igen för att det var du som öppnade den när ni skulle gå, och öppnade den sedan själv? Känslan av kontroll är det största psykologiska behovet i den här åldern. Låt det kosta dig 1 minut, men förebygg en 30 minuters kris på gatan.', title_vi = 'Con sẽ mở cửa! 🚪', body_vi = 'Lúc ra khỏi nhà, bé khóc bắt đóng cửa lại để tự mở, chỉ vì mẹ đã mở trước? Cảm giác kiểm soát là nhu cầu tâm lý lớn nhất ở tuổi này. Hãy chịu mất 1 phút để tránh 30 phút ăn vạ ngoài đường.', title_zh = '门要我来开！🚪', body_zh = '出门时因为是你开的门，宝宝就哭着让你关上，再自己打开？这个年龄，掌控感是最大的心理需求。让宝宝花掉你1分钟，却能避免街上30分钟的崩溃。' WHERE id = '026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quedarse en blanco en medio del súper 🛒', body_es = '¿Te has quedado parada en medio del súper pensando «¿A qué venía yo?»? El cerebro de mamá está de verdad a tope. Abrir la Lista de la compra de la app y confiar en esa memoria digital siempre te salvará de este caos.', title_fr = 'Figée au milieu du supermarché 🛒', body_fr = 'Vous vous êtes arrêtée au milieu du supermarché en vous demandant « Qu''est-ce que je venais acheter ? » ? Le cerveau d''une maman est vraiment surchargé. Ouvrir la Liste de courses de l''application et faire confiance à cette mémoire numérique vous sauvera toujours de ce chaos.', title_hi = 'सुपरमार्केट के बीच में जम जाना 🛒', body_hi = 'सुपरमार्केट के बीच खड़ी होकर सोच में पड़ गईं, ‘मैं क्या लेने आई थी?’ माँ का दिमाग सच में बहुत भरा होता है। ऐप में शॉपिंग लिस्ट खोलकर उस डिजिटल याददाश्त पर भरोसा करना आपको इस अफ़रा-तफ़री से हमेशा बचाएगा।', title_id = 'Terpaku di tengah supermarket 🛒', body_id = 'Anda berdiri di tengah supermarket dan termenung, ''Tadi aku mau beli apa ya?'' Otak seorang ibu memang sangat penuh. Membuka Daftar Belanja di aplikasi dan mengandalkan memori digital itu akan selalu menyelamatkan Anda dari kekacauan ini.', title_ja = 'スーパーのまん中でフリーズ 🛒', body_ja = 'スーパーのまん中で立ち止まって「何を買いに来たんだっけ？」と考えこんだ？ママの頭は本当にいっぱいなんです。アプリの「買い物リスト」を開いて、そのデジタルの記憶にたよれば、いつでもこのカオスから救われます。', title_ko = '마트 한가운데서 멍해지는 순간 🛒', body_ko = '마트 한가운데 서서 ''내가 뭘 사러 왔더라?'' 하고 멍해졌나요? 엄마의 머리는 정말 꽉 차 있거든요. 앱의 쇼핑 목록을 열고 디지털 기억에 맡기면 이런 혼란에서 언제나 구해 줄 거예요.', title_nl = 'Bevroren midden in de supermarkt 🛒', body_nl = 'Sta je midden in de supermarkt te denken: ''Wat kwam ik hier ook alweer halen?'' Een mamabrein zit echt overvol. Open het Boodschappenlijstje in de app en vertrouw op dat digitale geheugen, dan red je je altijd uit deze chaos.', title_pl = 'Zawieszona na środku sklepu 🛒', body_pl = 'Stoisz na środku sklepu i zastanawiasz się: „Po co ja tu przyszłam?”. Mamusiowy mózg naprawdę jest przepełniony. Otwórz Listę zakupów w aplikacji i zaufaj tej cyfrowej pamięci, zawsze uratuje cię z tego chaosu.', title_pt = 'Parada no meio do supermercado 🛒', body_pt = 'Parou no meio do supermercado a pensar "O que é que eu vim cá comprar?"? O cérebro de mãe anda mesmo cheio. Abrir a Lista de Compras da app e confiar nessa memória digital vai salvá-la sempre deste caos.', title_sv = 'Att stelna till mitt i affären 🛒', body_sv = 'Står du mitt i affären och funderar ”Vad var det jag skulle köpa?” Mammahjärnan är verkligen överfull. Att öppna Inköpslistan i appen och lita på det digitala minnet räddar dig alltid ur det här kaoset.', title_vi = 'Đứng hình giữa siêu thị 🛒', body_vi = 'Đứng giữa siêu thị, mẹ ngẩn ra: "Mình định mua gì nhỉ?" Đầu óc người mẹ thật sự đã quá tải. Mở Danh sách mua sắm trong ứng dụng và tin vào "bộ nhớ số" ấy sẽ luôn cứu mẹ khỏi mớ hỗn loạn này.', title_zh = '在超市中间愣住了 🛒', body_zh = '站在超市中间想：“我是来买什么的？”当了妈妈，大脑真的太满了。打开应用里的购物清单，交给这份数字记忆，总能帮你摆脱这种混乱。' WHERE id = '9e3821dd-5beb-4da8-ba9b-4369b4836b0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inundación en la bañera 🌊', body_es = '¿El baño es una excusa y en realidad ha montado un océano en la bañera para jugar con las olas? Deja que juegue. El ruido del agua y las salpicaduras se llevarán toda esa energía cabezota que no se acaba. Por la noche se meterá en la cama sin oponer resistencia.', title_fr = 'Inondation dans la baignoire 🌊', body_fr = 'Le bain n''est qu''un prétexte : en réalité, il crée un océan et joue avec les vagues ? Laissez-le jouer. Le bruit de l''eau et les éclaboussures emporteront toute cette énergie têtue et inépuisable. Le soir, il ira se coucher sans aucune résistance.', title_hi = 'बाथटब में पानी की बाढ़ 🌊', body_hi = 'नहाना तो बहाना है, असल में टब में समंदर बनाकर लहरों से खेल रहा है? खेलने दीजिए। पानी का शोर और छींटे उसके अंदर की वह खत्म न होने वाली ज़िद्दी ऊर्जा बहा ले जाएँगे। शाम को वह बिना किसी विरोध के बिस्तर पर लेट जाएगा।', title_id = 'Banjir di bak mandi 🌊', body_id = 'Mandi hanya alasan, sebenarnya ia menciptakan lautan di bak dan bermain ombak? Biarkan saja. Suara dan cipratan air akan membasuh energi keras kepala yang tak ada habisnya itu. Malam nanti ia akan berbaring di tempat tidur tanpa perlawanan.', title_ja = 'お風呂で大洪水 🌊', body_ja = 'お風呂は口実で、本当は浴槽に海をつくって波遊び？遊ばせてあげましょう。水の音としぶきが、終わりのないがんこなエネルギーを洗い流してくれます。夜はまったく抵抗せずにベッドに入りますよ。', title_ko = '욕조 속 물난리 🌊', body_ko = '목욕은 핑계고 사실은 욕조에 바다를 만들어 파도 놀이를 하나요? 놀게 두세요. 물소리와 물장구가 속에 쌓인 끝없는 고집 에너지를 씻어 줄 거예요. 저녁엔 아무 저항 없이 침대에 누울 거예요.', title_nl = 'Overstroming in bad 🌊', body_nl = 'Is in bad gaan maar een excuus en maakt hij eigenlijk een oceaan om met de golven te spelen? Laat hem lekker spelen. Het geluid en gespetter van het water spoelt al die eindeloze koppige energie weg. ''s Avonds gaat hij zonder enig verzet in bed liggen.', title_pl = 'Powódź w wannie 🌊', body_pl = 'Kąpiel to tylko pretekst, a w wannie tak naprawdę tworzy ocean i bawi się falami? Niech się bawi. Szum i pluskanie wody zmyją z niego tę niekończącą się upartą energię. Wieczorem położy się do łóżka bez żadnego oporu.', title_pt = 'Inundação na banheira 🌊', body_pt = 'O banho é só uma desculpa e, na verdade, ele cria um oceano na banheira e brinca com as ondas? Deixe-o brincar. O barulho e os salpicos da água vão levar consigo toda aquela energia teimosa e sem fim. À noite vai deitar-se sem resistência nenhuma.', title_sv = 'Översvämning i badkaret 🌊', body_sv = 'Är badet bara en förevändning, och barnet har egentligen skapat ett hav i badkaret och leker med vågorna? Låt hen leka. Vattnets ljud och plask sköljer bort den outtröttliga, envisa energin. På kvällen lägger sig barnet utan minsta motstånd.', title_vi = 'Lũ lụt trong bồn tắm 🌊', body_vi = 'Tắm chỉ là cái cớ, thật ra bé đang tạo cả đại dương trong bồn và chơi với sóng? Cứ để bé chơi. Tiếng nước và những cú té nước sẽ cuốn trôi hết năng lượng bướng bỉnh không ngừng bên trong bé. Tối đến, bé sẽ lên giường mà không phản đối chút nào.', title_zh = '浴缸里发大水 🌊', body_zh = '洗澡只是借口，其实是在浴缸里造了一片海洋，和浪花玩耍？就让宝宝玩吧。哗哗的水声和溅起的水花，会把宝宝身体里那股停不下来的倔强能量冲走。晚上就会毫无抵抗地躺上床。' WHERE id = 'c3a12f76-8197-4f4b-b339-db8bd083cf0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El orgullo de vestirse al revés 👕', body_es = '¿Se ha puesto la camiseta del revés y no te deja arreglarlo de ninguna manera? ¡Es cosa suya! La seguridad de esos ojos que dicen «lo he conseguido» importa más que ir bien vestido. Deja que pasee todo el día así de orgulloso, es su libre elección.', title_fr = 'La fierté à l''envers 👕', body_fr = 'Il a mis son t-shirt à l''envers et refuse fermement qu''on le remette à l''endroit ? C''est son affaire ! La confiance en soi dans ses yeux qui disent « J''ai réussi » compte plus que de bien s''habiller. Laissez-le se promener ainsi toute la journée, avec fierté : c''est son libre choix.', title_hi = 'उल्टा पहना हुआ गर्व 👕', body_hi = 'कमीज़ उल्टी पहन ली और उसे ठीक करने ही नहीं देता? यह उसका मामला है! ‘मैंने कर लिया’ कहती आँखों का आत्मविश्वास सही कपड़े पहनने से ज़्यादा ज़रूरी है। उसे पूरा दिन उसी गर्व से घूमने दीजिए, यह उसकी अपनी पसंद है।', title_id = 'Bangga memakai terbalik 👕', body_id = 'Ia memakai bajunya terbalik dan dengan tegas tidak mau dibetulkan? Itu urusannya! Rasa percaya diri di matanya yang berkata ''aku bisa'' lebih penting daripada berpakaian dengan benar. Biarkan ia berkeliling seharian dengan bangga seperti itu, itu pilihan bebasnya.', title_ja = 'うら返しのプライド 👕', body_ja = 'シャツをうら返しに着て、断固として直させない？本人のことです！「できた」と言っているその目の自信のほうが、正しく着ることより大切。一日じゅう誇らしく着ていさせてあげましょう。それはこの子の自由な選択です。', title_ko = '거꾸로 입은 자부심 👕', body_ko = '티셔츠를 거꾸로 입고 절대 못 고치게 하나요? 아이의 일이에요! ''내가 해냈어'' 하는 눈빛 속 자신감이 옷을 바르게 입는 것보다 더 중요해요. 하루 종일 그렇게 뿌듯하게 다니게 두세요, 아이의 자유로운 선택이니까요.', title_nl = 'Binnenstebuiten vol trots 👕', body_nl = 'Heeft hij zijn shirt binnenstebuiten aangetrokken en mag je het beslist niet goed doen? Zijn keuze! Het zelfvertrouwen in zijn ogen die zeggen ''het is me gelukt'' is belangrijker dan goed aangekleed zijn. Laat hem de hele dag zo trots rondlopen, het is zijn vrije keuze.', title_pl = 'Duma na lewą stronę 👕', body_pl = 'Założył koszulkę na lewą stronę i stanowczo nie pozwala jej poprawić? Jego sprawa! Pewność siebie w jego oczach, mówiących „udało mi się”, jest ważniejsza niż poprawne ubranie. Niech cały dzień chodzi tak z dumą, to jego wolny wybór.', title_pt = 'O orgulho de vestir do avesso 👕', body_pt = 'Vestiu a camisola do avesso e não a deixa de maneira nenhuma endireitá-la? É com ele! A autoconfiança nos olhos que dizem "eu consegui" é mais importante do que vestir-se bem. Deixe-o andar assim orgulhoso o dia todo, é a escolha livre dele.', title_sv = 'Stolthet på avigsidan 👕', body_sv = 'Har barnet tagit på sig tröjan bak och fram och låter dig absolut inte rätta till den? Det är hens sak! Självförtroendet i ögonen som säger ”jag klarade det” är viktigare än att vara rätt klädd. Låt barnet gå stolt så hela dagen, det är hens fria val.', title_vi = 'Niềm tự hào mặc trái 👕', body_vi = 'Bé mặc áo trái và kiên quyết không cho mẹ sửa? Đó là việc của bé! Sự tự tin trong đôi mắt "con làm được rồi" quan trọng hơn mặc đúng nhiều. Cứ để bé đi lại cả ngày đầy tự hào như thế, đó là lựa chọn tự do của bé.', title_zh = '反穿衣服的骄傲 👕', body_zh = '衣服穿反了，还坚决不让你帮忙改？那是宝宝自己的事！眼睛里那份“我做到了”的自信，比穿得正确重要得多。就让宝宝带着这份骄傲过一整天吧，这是宝宝自由的选择。' WHERE id = '006ab58d-d1e7-4e1c-a78e-139ada266050' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando tu voz no funciona, llega papá 🤡', body_es = '¿Ya no hace caso de lo que dices y se resiste? ¿Y en cuanto llega papá con ruidos de animales raros y caras graciosas se echa a reír al instante? A veces este humor sin lógica de los hombres salva de verdad la casa. Míralo desde fuera.', title_fr = 'Quand votre voix ne suffit plus, papa arrive 🤡', body_fr = 'Il ne fait plus attention à ce que vous dites et résiste ? Mais dès que papa arrive avec des cris d''animaux bizarres et des grimaces, il éclate de rire ? Parfois, cet humour masculin sans logique sauve vraiment la maison. Observez de loin.', title_hi = 'जब आपकी आवाज़ काम न आए, पापा आते हैं 🤡', body_hi = 'अब आपकी बातों पर ध्यान नहीं देता, अड़ा रहता है? और पापा ने आकर अजीब जानवरों की आवाज़ें और मज़ेदार चेहरे बनाए तो तुरंत हँसने लगा? कभी-कभी पुरुषों का यह बेतुका हास्य सच में घर बचा लेता है। किनारे से देखिए।', title_id = 'Saat suara Anda tak mempan, Ayah datang 🤡', body_id = 'Ia tak lagi menghiraukan kata-kata Anda dan terus melawan? Begitu Ayah datang dan membuat suara hewan aneh serta ekspresi lucu, ia langsung tertawa? Kadang humor tak masuk akal para pria ini benar-benar menyelamatkan rumah. Saksikan saja dari samping.', title_ja = 'ママの声が効かないときはパパの出番 🤡', body_ja = 'あなたの言うことはもう聞かず、言いはるばかり？パパが来て、変な動物の声やおもしろい顔をしたとたん笑い出した？ときにはパパの理屈ぬきのユーモアが、本当に家を救ってくれます。そばで見守りましょう。', title_ko = '엄마 말이 안 통할 땐 아빠 등장 🤡', body_ko = '엄마 말은 이제 들은 척도 안 하고 버티나요? 그런데 아빠가 와서 이상한 동물 소리와 우스운 표정을 짓자마자 바로 웃음이 터졌나요? 가끔은 아빠들의 엉뚱한 유머가 정말 집을 구해요. 옆에서 지켜보세요.', title_nl = 'Als jouw stem niet werkt, komt papa 🤡', body_nl = 'Trekt hij zich niets meer aan van wat jij zegt en verzet hij zich? En begint hij meteen te lachen zodra papa rare dierengeluiden en gekke gezichten trekt? Soms redt die onlogische humor van mannen echt het huis. Kijk lekker toe.', title_pl = 'Gdy twój głos nie działa, przychodzi tata 🤡', body_pl = 'Nie zwraca już uwagi na to, co mówisz, i się upiera? A gdy przyszedł tata i zaczął wydawać dziwne zwierzęce odgłosy i robić śmieszne miny, od razu się roześmiał? Czasem ten nielogiczny męski humor naprawdę ratuje dom. Popatrz z boku.', title_pt = 'Quando a sua voz não resulta, chega o pai 🤡', body_pt = 'Já não liga ao que diz e resiste? Mas mal o pai chega e faz sons estranhos de animais e caretas cómicas, desata logo a rir? Às vezes este humor sem lógica dos homens salva mesmo a casa. Observe à distância.', title_sv = 'När din röst inte räcker kommer pappa 🤡', body_sv = 'Bryr sig barnet inte längre om vad du säger och sätter sig på tvären? Och så fort pappa kommer och gör konstiga djurläten och roliga miner börjar hen skratta? Ibland räddar männens ologiska humor verkligen hemmet. Titta på från sidan.', title_vi = 'Khi lời mẹ không hiệu quả, bố xuất hiện 🤡', body_vi = 'Bé không còn để tâm đến lời mẹ, cứ bướng bỉnh? Thế mà bố vừa đến, giả tiếng thú kỳ quặc và làm mặt hề, bé đã cười phá lên? Đôi khi kiểu hài hước "phi logic" của đàn ông thật sự cứu cả ngôi nhà. Cứ đứng ngoài mà xem.', title_zh = '你的话不管用时，爸爸来了 🤡', body_zh = '你说什么宝宝都不理，还在较劲？爸爸一来，学几声奇怪的动物叫、做几个搞笑的鬼脸，宝宝马上就笑了？有时候，男人这种没逻辑的幽默真能拯救整个家。在一旁看着就好。' WHERE id = 'a6797020-6e00-4e51-85e1-ce4c1dc47785' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La IA responde a preguntas raras 🤖', body_es = '¿Te has quedado de piedra ante la pregunta «Mamá, ¿adónde va mi sombra por la noche?»? No te inventes nada. Abre Anacan AI, consigue la respuesta científica más tierna y de cuento para esta edad y léesela. Te sentirás una gran filósofa.', title_fr = 'La réponse de l''IA aux questions étranges 🤖', body_fr = 'Vous êtes restée figée devant la question « Maman, où va mon ombre la nuit ? » ? N''inventez rien. Ouvrez Anacan AI, obtenez la réponse scientifique la plus douce et la plus féerique pour son âge, et lisez-la-lui. Vous vous sentirez comme une grande philosophe.', title_hi = 'अजीब सवालों का AI जवाब 🤖', body_hi = '‘माँ, मेरी परछाईं रात को कहाँ जाती है?’ सुनकर जम गईं? कुछ मत गढ़िए। Anacan AI खोलिए, इस उम्र के लिए सबसे परी-कथा जैसा, प्यारा वैज्ञानिक जवाब लीजिए और उसे पढ़कर सुनाइए। आप खुद को एक बड़ी दार्शनिक महसूस करेंगी।', title_id = 'Jawaban AI untuk pertanyaan aneh 🤖', body_id = 'Anda terpaku mendengar pertanyaan ''Ma, bayanganku pergi ke mana kalau malam?'' Jangan mengarang apa pun. Buka Anacan AI, dapatkan jawaban ilmiah yang paling manis dan seperti dongeng untuk usia ini, lalu bacakan untuknya. Anda akan merasa seperti filsuf hebat.', title_ja = 'ふしぎな質問にはAIが答える 🤖', body_ja = '「ママ、ぼくの影は夜どこへ行くの？」という質問に固まってしまった？何もつくり話をしなくて大丈夫。Anacan AIを開いて、この年齢向けのいちばんお話らしい、かわいい科学的な答えを聞いて読んであげましょう。偉大な哲学者の気分になれますよ。', title_ko = '엉뚱한 질문엔 AI의 답 🤖', body_ko = '''엄마, 내 그림자는 밤에 어디 가?''라는 질문에 말문이 막혔나요? 아무거나 지어내지 마세요. Anacan AI를 열어 이 나이에 딱 맞는 동화 같고 귀여운 과학적 답을 받아 읽어 주세요. 위대한 철학자가 된 기분일 거예요.', title_nl = 'AI-antwoord op rare vragen 🤖', body_nl = 'Stond je met je mond vol tanden bij de vraag ''Mama, waar gaat mijn schaduw ''s nachts heen?'' Verzin niets. Open Anacan AI, vraag het meest sprookjesachtige, lieve wetenschappelijke antwoord voor deze leeftijd en lees het hem voor. Je voelt je een grote filosoof.', title_pl = 'Odpowiedź AI na dziwne pytania 🤖', body_pl = 'Zamarłaś przy pytaniu „Mamo, gdzie mój cień chodzi w nocy?”. Niczego nie wymyślaj. Otwórz Anacan AI, uzyskaj najbardziej bajkową i uroczą naukową odpowiedź dla tego wieku i mu ją przeczytaj. Poczujesz się jak wielka filozofka.', title_pt = 'Respostas da IA a perguntas estranhas 🤖', body_pt = 'Ficou sem reação perante a pergunta "Mãe, para onde vai a minha sombra à noite?"? Não invente nada. Abra o Anacan AI, obtenha a resposta científica mais doce e encantadora para esta idade e leia-lha. Vai sentir-se uma grande filósofa.', title_sv = 'AI svarar på konstiga frågor 🤖', body_sv = 'Frös du till inför frågan ”Mamma, vart går min skugga på natten?” Hitta inte på något. Öppna Anacan AI, få det mest sagolika och söta vetenskapliga svaret för den här åldern och läs det för barnet. Du kommer att känna dig som en stor filosof.', title_vi = 'AI trả lời những câu hỏi kỳ lạ 🤖', body_vi = 'Mẹ đứng hình trước câu hỏi "Mẹ ơi, ban đêm cái bóng của con đi đâu?" Đừng bịa gì cả. Hãy mở Anacan AI, lấy câu trả lời khoa học ngọt ngào, đậm chất cổ tích nhất cho lứa tuổi này và đọc cho bé nghe. Mẹ sẽ thấy mình như một triết gia vĩ đại.', title_zh = '奇怪问题交给AI 🤖', body_zh = '“妈妈，我的影子晚上去哪儿了？”被这个问题问住了？什么都别编。打开Anacan AI，为这个年龄的孩子找到一个最像童话、最可爱的科学答案，读给宝宝听。你会觉得自己像个大哲学家。' WHERE id = 'bf79338f-3f38-4811-b226-50574547225b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escribir la rabia que llevo dentro 📝', body_es = '¿Nadie ve lo cansada que estás en casa y eso te hace explotar? Abre el Diario de ánimo. Escribe ahí todo lo que hoy te ha vuelto loca. Aceptar la emoción y escribirla te ayudará mucho más que sonreír de mentira.', title_fr = 'Écrire la colère qui est en moi 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée à la maison, et ça vous fait exploser ? Ouvrez le Journal d''humeur. Écrivez-y tout ce qui vous a rendue folle aujourd''hui. Accepter l''émotion et l''écrire vous aidera bien plus qu''un sourire forcé.', title_hi = 'अंदर का गुस्सा लिख डालना 📝', body_hi = 'कोई नहीं देखता कि आप घर में कितना थकती हैं, और इससे आप फट पड़ती हैं? मूड डायरी खोलिए। आज जिसने भी आपको पागल किया, सब वहाँ लिख दीजिए। नकली मुस्कान से ज़्यादा भावना को स्वीकार करके लिखना आपकी मदद करेगा।', title_id = 'Menuliskan amarah di dalam diri 📝', body_id = 'Tidak ada yang melihat betapa lelahnya Anda di rumah, dan itu membuat Anda ingin meledak? Buka Buku Harian Suasana Hati. Tulis di sana semua yang membuat Anda kesal hari ini. Menerima dan menuliskan emosi akan jauh lebih membantu daripada tersenyum palsu.', title_ja = '心の中の怒りを書き出す 📝', body_ja = '家でどれだけ疲れているか誰も気づいてくれなくて、爆発しそう？「気分日記」を開きましょう。今日イライラしたことを全部そこに書いて。無理に笑顔をつくるより、気持ちを受けとめて書くほうがずっと助けになります。', title_ko = '속에 쌓인 화를 글로 쓰기 📝', body_ko = '집에서 내가 얼마나 지치는지 아무도 몰라줘서 폭발할 것 같나요? 기분 일기를 열고 오늘 나를 미치게 한 걸 전부 적어 보세요. 억지로 웃는 것보다 감정을 받아들이고 글로 쓰는 게 훨씬 도움이 될 거예요.', title_nl = 'De boosheid van me afschrijven 📝', body_nl = 'Ziet niemand hoe moe je thuis bent en word je daar gek van? Open je Stemmingsdagboek. Schrijf alles op wat je vandaag gek heeft gemaakt. Je emoties accepteren en opschrijven helpt je meer dan een nepglimlach.', title_pl = 'Wypisz złość, która w tobie siedzi 📝', body_pl = 'Nikt nie widzi, jak bardzo męczysz się w domu, i to doprowadza cię do wybuchu? Otwórz Dziennik nastroju. Zapisz tam wszystko, co dziś doprowadzało cię do szału. Przyjęcie emocji i zapisanie ich pomoże ci bardziej niż sztuczny uśmiech.', title_pt = 'Escrever a raiva que trago cá dentro 📝', body_pt = 'Ninguém vê o quanto se cansa em casa e isso fá-la explodir? Abra o Diário de Humor. Escreva lá tudo o que hoje a deixou louca. Aceitar a emoção e escrevê-la vai ajudá-la mais do que sorrir à força.', title_sv = 'Skriv ner ilskan inom dig 📝', body_sv = 'Ingen ser hur trött du blir hemma, och det får dig att explodera? Öppna Humördagboken. Skriv ner allt som gjort dig galen i dag. Att acceptera känslan och skriva ner den hjälper dig mer än ett konstlat leende.', title_vi = 'Viết ra cơn giận trong lòng 📝', body_vi = 'Không ai thấy mẹ ở nhà mệt đến mức nào, và điều đó khiến mẹ muốn bùng nổ? Hãy mở Nhật ký tâm trạng. Viết hết vào đó mọi điều khiến mẹ phát điên hôm nay. Chấp nhận và viết ra cảm xúc sẽ giúp mẹ nhiều hơn là cười gượng.', title_zh = '把心里的火写下来 📝', body_zh = '没人看到你在家有多累，这让你快要爆发了？打开心情日记。把今天让你抓狂的事都写进去。比起假笑，接纳情绪、把它写下来，更能帮到你。' WHERE id = '50a90b1b-61b0-4de1-8146-038e23b46eb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Largas charlas con objetos 🗣️', body_es = '¿En el parque le habla muy en serio a una piedra, o en casa a una silla? A través del juego está asimilando las reglas y el mundo.', title_fr = 'Longues conversations avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise ? Par le jeu, il assimile les règles et le monde.', title_hi = 'बेजान चीज़ों से लंबी बातें 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ बातें करता है? वह खेल के ज़रिए नियम और दुनिया समझ रहा है।', title_id = 'Obrolan panjang dengan benda mati 🗣️', body_id = 'Ia berbicara dengan sangat serius kepada sebuah batu di taman atau kursi di rumah? Lewat permainan, ia sedang memahami aturan dan dunia.', title_ja = 'ものとの長いおしゃべり 🗣️', body_ja = '公園の石や家のいすに、とても真剣に何かを話しかけている？遊びを通して、ルールや世界を身につけているんです。', title_ko = '물건들과 나누는 긴 대화 🗣️', body_ko = '공원의 돌이나 집 안 의자에게 아주 진지하게 무언가를 말하나요? 놀이를 통해 규칙과 세상을 익히는 중이에요.', title_nl = 'Lange gesprekken met levenloze dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of thuis tegen een stoel? Via spel leert hij de regels en de wereld kennen.', title_pl = 'Długie rozmowy z przedmiotami 🗣️', body_pl = 'W parku z całą powagą opowiada coś kamieniowi albo w domu krzesłu? Przez zabawę oswaja zasady i świat.', title_pt = 'Longas conversas com objetos 🗣️', body_pt = 'No parque fala muito a sério com uma pedra ou, em casa, com uma cadeira? Através do jogo, está a aprender as regras e o mundo.', title_sv = 'Långa samtal med livlösa ting 🗣️', body_sv = 'Pratar barnet helt allvarligt med en sten i parken eller en stol hemma? Genom leken tar barnet till sig reglerna och världen.', title_vi = 'Những cuộc trò chuyện dài với đồ vật 🗣️', body_vi = 'Bé nói chuyện hết sức nghiêm túc với một hòn đá ở công viên hay chiếc ghế ở nhà? Qua trò chơi, bé đang học về các quy tắc và thế giới.', title_zh = '和没有生命的东西长谈 🗣️', body_zh = '在公园里对着一块石头，或在家对着一把椅子，一本正经地说着什么？宝宝正在通过游戏理解规则和这个世界。' WHERE id = '86283ea0-922f-4b91-8fed-55bf6231330d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esta noche, solo abrazos 🫂', body_es = 'No hace falta ningún juego ni libro ruidoso. Esta noche solo abrázalo contra tu pecho, respira hondo ese olor limpio de niño y susúrrale en la oscuridad lo valioso que es. Con eso os bastará a los dos.', title_fr = 'Ce soir, juste des câlins 🫂', body_fr = 'Pas besoin de jeu ni de livre bruyant. Ce soir, serrez-le simplement contre votre poitrine, respirez profondément cette pure odeur d''enfant et, dans le noir, chuchotez-lui combien il est précieux. Cela suffira à tous les deux.', title_hi = 'आज शाम बस गले लगें 🫂', body_hi = 'किसी खेल या शोर वाली किताब की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उस मासूम बच्चे की खुशबू गहरी साँसों में भरिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है। आप दोनों के लिए इतना काफ़ी होगा।', title_id = 'Malam ini cukup berpelukan 🫂', body_id = 'Tak perlu permainan atau buku yang berisik. Malam ini cukup dekap ia di dada Anda, hirup dalam-dalam aroma anak yang bersih itu, dan dalam gelap bisikkan betapa berharganya ia. Ini sudah cukup untuk kalian berdua.', title_ja = '今夜はただ抱きしめよう 🫂', body_ja = '遊びも音の出る絵本もいりません。今夜はただ胸に抱きしめて、子どもの清らかなにおいを深く吸いこみ、暗やみの中で、どれほど大切かをささやいてあげて。それだけで、ふたりとも満たされます。', title_ko = '오늘 저녁엔 그냥 안아 줘요 🫂', body_ko = '놀이도, 시끄러운 책도 필요 없어요. 오늘 저녁엔 아이를 가슴에 꼭 안고 그 깨끗한 아이 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한지 속삭여 주세요. 두 사람 모두에게 그걸로 충분해요.', title_nl = 'Laten we vanavond gewoon knuffelen 🫂', body_nl = 'Geen spel of druk boek nodig. Druk hem vanavond gewoon tegen je borst, snuif diep die zuivere kindergeur op en fluister in het donker hoe kostbaar hij is. Dat is genoeg voor jullie allebei.', title_pl = 'Dziś wieczorem po prostu się przytulmy 🫂', body_pl = 'Nie potrzeba żadnej zabawy ani głośnej książki. Dziś wieczorem po prostu przytul go do piersi, głęboko wdychaj ten czysty dziecięcy zapach i w ciemności wyszeptaj mu, jaki jest cenny. To wystarczy wam obojgu.', title_pt = 'Esta noite, só abraços 🫂', body_pt = 'Não é preciso nenhum jogo nem livro barulhento. Esta noite, aperte-o simplesmente contra o peito, respire fundo aquele cheirinho puro de criança e sussurre-lhe no escuro o quanto é precioso. Chega para os dois.', title_sv = 'I kväll kramas vi bara 🫂', body_sv = 'Det behövs varken lek eller högljudda böcker. I kväll håller du bara barnet tätt intill dig, andas djupt in den rena barndoften och viskar i mörkret hur värdefullt barnet är. Det räcker för er båda.', title_vi = 'Tối nay chỉ cần ôm nhau thôi 🫂', body_vi = 'Không cần trò chơi hay sách ồn ào nào cả. Tối nay, chỉ cần ôm bé vào lòng, hít thật sâu mùi hương trẻ thơ trong trẻo ấy và thì thầm trong bóng tối rằng bé quý giá biết bao. Như vậy là đủ cho cả hai mẹ con.', title_zh = '今晚就抱抱吧 🫂', body_zh = '不需要任何游戏，也不需要吵闹的书。今晚只要把宝宝紧紧抱在怀里，深深吸一口那纯净的孩子气息，在黑暗中轻声告诉宝宝有多珍贵。这对你们俩都足够了。' WHERE id = 'b3273f0d-ec07-48f9-82e7-89e57daaf623' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Yo lo sé, te lo enseño ☝️', body_es = '¿Viene a explicarte algo que tú ya sabes con una cara muy seria e inteligente? Está poniendo a prueba su inteligencia. Muérdete el labio para no reírte, pero escúchalo muy en serio y dile: «¿De verdad? Muchas gracias».', title_fr = 'Je sais, je vais t''apprendre ☝️', body_fr = 'Il vient vous expliquer, avec une mine très sérieuse et savante, quelque chose que vous savez déjà ? Il teste son intelligence. Mordez-vous la lèvre pour ne pas rire, mais écoutez-le très sérieusement et dites : « Vraiment ? Merci beaucoup. »', title_hi = 'मुझे पता है, तुम्हें भी सिखाता हूँ ☝️', body_hi = 'जो बात आप जानती हैं, वही आकर बड़े गंभीर और समझदार चेहरे से आपको समझाता है? वह अपनी बुद्धि परख रहा है। हँसी रोकने के लिए होंठ दबाइए, पर बड़ी गंभीरता से सुनकर कहिए, ‘सच में? बहुत-बहुत शुक्रिया।’', title_id = 'Aku tahu, aku ajari kamu ya ☝️', body_id = 'Ia datang dan menjelaskan sesuatu yang sudah Anda ketahui dengan wajah sangat serius dan sok pintar? Ia sedang menguji kecerdasannya. Gigit bibir supaya tidak tertawa, tapi dengarkan ia dengan sangat serius dan katakan ''Oh ya? Terima kasih banyak''.', title_ja = 'わたし知ってるよ、教えてあげる ☝️', body_ja = 'あなたが知っていることを、とても真剣でかしこい顔で説明してくれる？自分の知恵をためしているんです。笑わないよう唇をかみつつ、とても真剣に聞いて「本当？ありがとう」と言いましょう。', title_ko = '내가 알아, 엄마한테도 알려 줄게 ☝️', body_ko = '엄마가 이미 아는 걸 아주 진지하고 똑똑한 표정으로 설명해 주나요? 자기 지식을 시험하는 중이에요. 웃음을 참으려 입술을 깨물더라도 아주 진지하게 듣고 ''정말? 고마워''라고 말해 주세요.', title_nl = 'Ik weet het, ik leer het jou ook ☝️', body_nl = 'Legt hij jou met een heel serieus, slim gezicht iets uit wat jij allang weet? Hij test zijn eigen verstand. Bijt op je lip om niet te lachen, luister heel serieus en zeg: ''Echt? Dank je wel!''', title_pl = 'Ja wiem, to cię nauczę ☝️', body_pl = 'Z bardzo poważną i mądrą miną tłumaczy ci coś, co doskonale wiesz? Sprawdza swoją inteligencję. Przygryź wargę, żeby się nie roześmiać, ale wysłuchaj go z pełną powagą i powiedz: „Naprawdę? Bardzo dziękuję”.', title_pt = 'Eu sei, deixa-me ensinar-te ☝️', body_pt = 'Vem explicar-lhe algo que a mãe já sabe, com uma expressão muito séria e inteligente? Está a testar a sua inteligência. Morda o lábio para não se rir, mas ouça-o com toda a seriedade e diga: "A sério? Muito obrigada".', title_sv = 'Jag vet, jag ska lära dig ☝️', body_sv = 'Förklarar barnet något du redan vet, med en väldigt allvarlig och klok min? Hen testar sin egen intelligens. Bit dig i läppen för att inte skratta, men lyssna på fullt allvar och säg ”Verkligen? Tack så mycket!”', title_vi = 'Con biết, để con dạy mẹ ☝️', body_vi = 'Bé đến giải thích cho mẹ một điều mẹ đã biết với vẻ mặt cực kỳ nghiêm túc và thông thái? Bé đang thử trí tuệ của mình. Cắn môi để khỏi bật cười, nhưng hãy lắng nghe thật nghiêm túc và nói: "Thật à? Cảm ơn con nhiều nhé."', title_zh = '我知道，我来教你 ☝️', body_zh = '把你本来就知道的事，带着一本正经、很聪明的表情讲给你听？宝宝在测试自己的智慧。咬住嘴唇别笑，非常认真地听完，说：“真的吗？太谢谢你了。”' WHERE id = '113aa528-0657-4840-905d-63eec2aa048b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Papá cuenta mal la historia 📖', body_es = 'Esta noche la voz no es tuya. Dale el libro de cuentos a papá. Que cuente la historia al revés a propósito, de forma graciosa y absurda. Disfruta viendo desde fuera cómo el peque se lo pasa en grande corrigiéndolo y se ríe a carcajadas.', title_fr = 'Papa raconte l''histoire de travers 📖', body_fr = 'Ce soir, ce n''est pas vous qui parlez. Donnez le livre de contes à papa. Qu''il raconte l''histoire exprès à l''envers, de façon drôle et absurde. Regardez de loin, avec délice, l''enfant prendre plaisir à le corriger et éclater de rire.', title_hi = 'पापा का कहानी गलत सुनाना 📖', body_hi = 'आज शाम आवाज़ आपकी नहीं। कहानी की किताब पापा को दीजिए। पापा कहानी जानबूझकर उल्टी, मज़ेदार और बेतुके ढंग से सुनाएँ। किनारे से मज़े लेकर देखिए कि बच्चा उन्हें ठीक करने में कितना आनंद लेता है और ठहाके लगाता है।', title_id = 'Ayah salah menceritakan dongeng 📖', body_id = 'Malam ini bukan suara Anda. Serahkan buku dongeng kepada Ayah. Biarkan Ayah sengaja menceritakan kisahnya terbalik, lucu, dan absurd. Nikmati dari samping betapa senangnya anak membetulkannya sambil tertawa terbahak-bahak.', title_ja = 'パパのお話はまちがいだらけ 📖', body_ja = '今夜の声はあなたではありません。絵本をパパに渡しましょう。パパにわざとお話をあべこべに、おかしくめちゃくちゃに話してもらって。子どもが楽しそうに直して大笑いするのを、そばでゆっくり眺めましょう。', title_ko = '아빠가 이야기를 틀리게 해 줄 때 📖', body_ko = '오늘 저녁 목소리는 엄마 몫이 아니에요. 동화책을 아빠에게 넘기세요. 아빠가 일부러 이야기를 거꾸로, 우스꽝스럽고 엉뚱하게 들려주게 하세요. 아이가 아빠를 고쳐 주며 깔깔 웃는 모습을 옆에서 즐겁게 지켜보세요.', title_nl = 'Papa vertelt het verhaal verkeerd 📖', body_nl = 'Vanavond is het niet jouw stem. Geef het sprookjesboek aan papa. Laat hem het verhaal expres verkeerd om, grappig en absurd vertellen. Kijk genietend toe hoe je kind het met plezier verbetert en het uitschatert.', title_pl = 'Tata opowiada bajkę na opak 📖', body_pl = 'Dziś wieczorem to nie twój głos. Oddaj książkę z bajkami tacie. Niech celowo opowiada historię na opak, zabawnie i absurdalnie. Z przyjemnością przyglądaj się z boku, jak dziecko z frajdą go poprawia i zanosi się śmiechem.', title_pt = 'O pai conta a história mal 📖', body_pt = 'Esta noite a voz não é a sua. Dê o livro de histórias ao pai. Que ele conte a história de propósito ao contrário, de forma cómica e absurda. Observe com prazer, à distância, como a criança adora corrigi-lo e se ri às gargalhadas.', title_sv = 'När pappa berättar sagan fel 📖', body_sv = 'I kväll är det inte din röst. Ge sagoboken till pappa. Låt honom berätta historien med flit bakvänt, roligt och absurt. Njut från sidan av hur barnet älskar att rätta honom och skrattar högt.', title_vi = 'Khi bố kể chuyện sai 📖', body_vi = 'Tối nay không phải giọng của mẹ. Hãy đưa cuốn truyện cho bố. Để bố cố tình kể ngược, kể thật buồn cười và vô lý. Rồi đứng ngoài thích thú ngắm bé say sưa sửa lời bố và cười khanh khách.', title_zh = '爸爸把故事讲错了 📖', body_zh = '今晚不用你开口。把故事书交给爸爸。让爸爸故意把故事讲反、讲得又搞笑又荒诞。在一旁好好欣赏宝宝纠正爸爸时那副得意、哈哈大笑的样子吧。' WHERE id = '70129896-2f43-4370-bbff-f84bbbb58845' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Olvida la limpieza, que se queden los juguetes 🎨', body_es = '¿Ha creado una gran obra con trocitos en medio de la habitación y no te deja recogerla? Deja a un lado la obsesión por la limpieza. No toques el caos que ha creado, la limpieza puede esperar a mañana. La casa no es un museo.', title_fr = 'Oubliez le ménage, laissez les jouets 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre avec des bouts de papier et ne vous laisse pas ranger ? Mettez de côté l''obsession du ménage. Ne touchez pas au chaos qu''il a créé, le ménage peut bien attendre demain. La maison n''est pas un musée.', title_hi = 'सफ़ाई छोड़िए, खिलौने पड़े रहने दीजिए 🎨', body_hi = 'कमरे के बीच टुकड़ों से एक बड़ी कलाकृति बना दी है और समेटने नहीं देता? सफ़ाई की धुन एक तरफ़ रखिए। उसकी बनाई अफ़रा-तफ़री को मत छूइए, सफ़ाई वैसे भी कल तक रुक सकती है। घर कोई म्यूज़ियम नहीं है।', title_id = 'Lupakan bersih-bersih, biarkan mainannya 🎨', body_id = 'Di tengah kamar ia membuat karya besar dari potongan-potongan kecil dan tidak mengizinkan Anda membereskannya? Singkirkan dulu obsesi kebersihan. Jangan sentuh kekacauan yang ia ciptakan, bersih-bersih toh bisa menunggu besok. Rumah bukan museum.', title_ja = 'お片づけはお休み、おもちゃはそのまま 🎨', body_ja = '部屋のまん中で、小さなかけらから大作をつくって片づけさせてくれない？きれい好きはひと休み。この子がつくったカオスには手をつけないで。掃除は明日でも大丈夫。家は美術館ではありません。', title_ko = '청소는 내려놓고, 장난감은 그대로 🎨', body_ko = '방 한가운데 자투리로 커다란 작품을 만들어 놓고 못 치우게 하나요? 깔끔 강박은 잠시 내려놓으세요. 아이가 만든 혼돈은 건드리지 마세요. 청소는 내일로 미뤄도 돼요. 집은 박물관이 아니니까요.', title_nl = 'Laat het opruimen, het speelgoed blijft liggen 🎨', body_nl = 'Heeft hij midden in de kamer een groot kunstwerk van snippers gemaakt en mag je niet opruimen? Zet je opruimwoede opzij. Kom niet aan de chaos die hij heeft gemaakt, opruimen kan heus tot morgen wachten. Je huis is geen museum.', title_pl = 'Odpuść sprzątanie, niech zabawki zostaną 🎨', body_pl = 'Na środku pokoju stworzył z okruchów wielkie dzieło i nie pozwala go sprzątnąć? Odłóż obsesję porządku na bok. Nie ruszaj jego chaosu, sprzątanie i tak może poczekać do jutra. Dom to nie muzeum.', title_pt = 'Esqueça a arrumação, os brinquedos ficam 🎨', body_pt = 'No meio do quarto criou uma grande obra com migalhas e não a deixa arrumar? Ponha de lado a obsessão pela limpeza. Não toque no caos que ele criou, a limpeza pode ficar para amanhã. A casa não é um museu.', title_sv = 'Strunta i städningen, låt leksakerna ligga 🎨', body_sv = 'Har barnet skapat ett stort konstverk av smulor mitt i rummet och låter dig inte städa? Lägg städmanin åt sidan. Rör inte kaoset barnet skapat, städningen kan ändå vänta till i morgon. Hemmet är inget museum.', title_vi = 'Kệ việc dọn dẹp, cứ để đồ chơi đó 🎨', body_vi = 'Bé tạo ra một "tác phẩm" lớn từ những mẩu vụn giữa phòng và không cho mẹ dọn? Hãy gác lại nỗi ám ảnh sạch sẽ. Đừng động vào sự hỗn loạn bé tạo ra, việc dọn dẹp đằng nào cũng có thể để đến mai. Nhà đâu phải viện bảo tàng.', title_zh = '别管打扫了，玩具就留着吧 🎨', body_zh = '在房间中间用碎片拼出了一件“大作品”，还不让你收拾？先放下你的整洁强迫症。别碰宝宝创造的混乱，打扫反正可以留到明天。家不是博物馆。' WHERE id = 'e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te cuenta los dibujos animados 📺', body_es = '¿Te cuenta los dibujos que ha visto con una lógica totalmente distinta y te explica muy en serio quién fue adónde? Escúchalo con atención, como si te lo creyeras todo. Deja que se sienta el más listo y el más fuerte del mundo.', title_fr = 'Il vous raconte son dessin animé 📺', body_fr = 'Il vous raconte le dessin animé qu''il a regardé avec une tout autre logique et vous explique sérieusement qui est allé où ? Écoutez-le attentivement, comme si vous croyiez à tout. Laissez-le se sentir le plus intelligent et le plus fort du monde.', title_hi = 'आपको कार्टून की कहानी सुनाता है 📺', body_hi = 'देखा हुआ कार्टून आपको बिल्कुल अलग तर्क से सुनाता है, गंभीरता से समझाता है कि कौन कहाँ गया? उसे ध्यान से, जैसे आप हर बात पर यकीन कर रही हों, सुनिए। उसे खुद को दुनिया का सबसे समझदार और ताकतवर महसूस करने दीजिए।', title_id = 'Ia menceritakan kartunnya kepada Anda 📺', body_id = 'Ia menceritakan kartun yang ditontonnya dengan logika yang sama sekali berbeda dan dengan serius menjelaskan siapa pergi ke mana? Dengarkan ia dengan saksama, seolah Anda percaya semuanya. Biarkan ia merasa menjadi yang paling pintar dan kuat di dunia.', title_ja = 'アニメのお話をしてくれる 📺', body_ja = '見たアニメを、まったくちがう理屈で話してくれて、誰がどこへ行ったか真剣に説明する？何でも信じているかのように、しっかり聞いてあげましょう。世界一かしこくて強い気分を味わわせてあげて。', title_ko = '만화 이야기를 들려줘요 📺', body_ko = '본 만화를 완전히 다른 논리로 이야기하며 누가 어디로 갔는지 진지하게 설명하나요? 모든 걸 믿는 것처럼 귀 기울여 들어 주세요. 세상에서 가장 똑똑하고 강한 사람이 된 기분을 느끼게 해 주세요.', title_nl = 'Hij vertelt jou de tekenfilm na 📺', body_nl = 'Vertelt hij de tekenfilm die hij zag na met een totaal andere logica en legt hij heel serieus uit wie waarheen ging? Luister aandachtig, alsof je alles gelooft. Laat hem zich de slimste en sterkste van de wereld voelen.', title_pl = 'Opowiada ci bajkę z telewizji 📺', body_pl = 'Opowiada ci obejrzaną bajkę według zupełnie innej logiki i z powagą tłumaczy, kto dokąd poszedł? Słuchaj uważnie, jakbyś we wszystko wierzyła. Niech poczuje się najmądrzejszy i najsilniejszy na świecie.', title_pt = 'Conta-lhe os desenhos animados 📺', body_pt = 'Conta-lhe os desenhos animados que viu com uma lógica totalmente diferente e explica muito a sério quem foi para onde? Ouça-o com atenção, como se acreditasse em tudo. Deixe-o sentir-se a pessoa mais inteligente e forte do mundo.', title_sv = 'Barnet berättar tecknade filmen för dig 📺', body_sv = 'Berättar barnet den tecknade filmen hen sett med en helt annan logik och förklarar allvarligt vem som gick vart? Lyssna noga, som om du tror på allt. Låt hen känna sig som världens klokaste och starkaste.', title_vi = 'Bé kể lại phim hoạt hình cho mẹ 📺', body_vi = 'Bé kể lại bộ phim hoạt hình vừa xem theo một logic hoàn toàn khác, nghiêm túc giải thích ai đi đâu? Hãy chăm chú lắng nghe như thể mẹ tin từng lời. Để bé thấy mình là người thông minh và mạnh mẽ nhất thế giới.', title_zh = '给你讲动画片 📺', body_zh = '用完全不同的逻辑给你讲刚看过的动画片，一本正经地解释谁去了哪里？认真听，就像你全都信了一样。让宝宝觉得自己是世界上最聪明、最厉害的人吧。' WHERE id = '4501063e-24e5-4f32-a723-396adeab0d2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ese temido «quiero» del súper 🛒', body_es = '¿Grita por un chocolate justo delante de la caja? No cedas aunque te miren los de atrás. Abre la Lista de la compra y dile: «Aquí no está, la caja no lo va a leer». Una autoridad externa siempre les resulta más convincente.', title_fr = 'Le terrible « Je veux » au supermarché 🛒', body_fr = 'Il hurle pour un chocolat juste devant la caisse ? Malgré les regards derrière vous, ne cédez pas. Ouvrez la Liste de courses et dites : « Ce n''est pas dedans, la caisse ne le lira pas. » Une autorité extérieure leur paraît toujours plus convaincante.', title_hi = 'सुपरमार्केट वाला वह डरावना ‘मुझे चाहिए’ 🛒', body_hi = 'ठीक काउंटर के सामने चॉकलेट के लिए चिल्ला रहा है? पीछे वालों की नज़रों के बावजूद हार मत मानिए। शॉपिंग लिस्ट खोलिए और कहिए, ‘यह इसमें नहीं है, काउंटर इसे स्कैन नहीं करेगा।’ बाहर की कोई ‘अथॉरिटी’ बच्चों को हमेशा ज़्यादा भरोसेमंद लगती है।', title_id = '''Aku mau'' yang menakutkan di supermarket 🛒', body_id = 'Ia menjerit minta cokelat tepat di depan kasir? Jangan menyerah meski orang-orang di belakang memandangi. Buka Daftar Belanja dan katakan ''Ini tidak ada di sini, kasirnya tidak akan bisa membacanya''. Otoritas dari luar selalu terasa lebih meyakinkan bagi mereka.', title_ja = 'スーパーでのあのこわい「ほしい」 🛒', body_ja = 'レジの目の前でチョコがほしいと叫ぶ？後ろの人の視線があっても負けないで。「買い物リスト」を開いて「ここには入っていないから、レジは読みとってくれないよ」と言いましょう。外からのルールのほうが、子どもにはいつも説得力があります。', title_ko = '마트에서 듣는 무서운 ''사 줘'' 🛒', body_ko = '계산대 바로 앞에서 초콜릿 사 달라고 소리치나요? 뒷사람들 시선에도 굴복하지 마세요. 쇼핑 목록을 열고 ''여기 없지? 계산대가 이건 안 읽어 줘''라고 말하세요. 바깥의 권위는 아이에게 늘 더 설득력 있게 들려요.', title_nl = 'Dat gevreesde ''ik wil'' in de supermarkt 🛒', body_nl = 'Schreeuwt hij vlak voor de kassa om chocola? Geef niet toe, ook al kijken de mensen achter je. Open het Boodschappenlijstje en zeg: ''Het staat er niet op, de kassa scant het niet.'' Een autoriteit van buitenaf is voor hen altijd overtuigender.', title_pl = 'To straszne „chcę” w sklepie 🛒', body_pl = 'Krzyczy o czekoladę tuż przed kasą? Mimo spojrzeń ludzi w kolejce nie poddawaj się. Otwórz Listę zakupów i powiedz: „Tego tu nie ma, kasa tego nie zeskanuje”. Zewnętrzny autorytet zawsze brzmi dla dzieci bardziej przekonująco.', title_pt = 'O temível "eu quero" do supermercado 🛒', body_pt = 'Grita por um chocolate mesmo em frente à caixa? Apesar dos olhares de quem está atrás, não ceda. Abra a Lista de Compras e diga: "Não está aqui, a caixa não o vai ler". Uma autoridade externa parece-lhes sempre mais convincente.', title_sv = 'Det fruktade ”jag vill ha” i affären 🛒', body_sv = 'Skriker barnet efter choklad precis framför kassan? Ge inte efter, trots blickarna från folket i kön. Öppna Inköpslistan och säg: ”Den står inte här, kassan kommer inte att läsa den.” En yttre auktoritet känns alltid mer övertygande för barn.', title_vi = 'Câu "Con muốn!" đáng sợ ở siêu thị 🛒', body_vi = 'Bé gào đòi sô-cô-la ngay trước quầy thu ngân? Dù người phía sau nhìn chằm chằm, đừng nhượng bộ. Mở Danh sách mua sắm và nói: "Không có trong này, quầy thu ngân sẽ không quét món này đâu." Một "uy quyền bên ngoài" luôn khiến bé tin hơn.', title_zh = '超市里那句可怕的“我要” 🛒', body_zh = '就在收银台前为了巧克力尖叫？不管后面的人怎么看，都别让步。打开购物清单，说：“这里面没有，收银台扫不了它。”来自外部的“权威”对孩子总是更有说服力。' WHERE id = '68a8ce66-c86f-4596-b8d3-b0d44f55a37d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quitarse todo el cansancio con agua 🛀', body_es = 'A veces nada funciona y simplemente llora por todo. Mételo en una bañera con agua tibia. Ese poder casi místico del agua para quitar tensión traerá al instante una gran calma a toda la habitación y a su sistema nervioso. Pruébalo y verás.', title_fr = 'Laver toute la fatigue avec de l''eau 🛀', body_fr = 'Parfois, rien ne marche, il pleure pour tout. Mettez-le dans un bain d''eau tiède. Le pouvoir mystique et apaisant de l''eau apportera instantanément une grande sérénité à toute la pièce et à son système nerveux. Essayez et vous verrez.', title_hi = 'पानी से सारी थकान धो डालना 🛀', body_hi = 'कभी-कभी कुछ भी काम नहीं करता, वह बस हर बात पर रोता है। उसे गुनगुने पानी से भरे टब में बिठाइए। पानी की वह रहस्यमयी, तनाव सोखने वाली ताकत पूरे कमरे और उसके तंत्रिका तंत्र में तुरंत गहरा सुकून ले आएगी। आज़माकर देखिए।', title_id = 'Membasuh semua lelah dengan air 🛀', body_id = 'Kadang tak ada yang berhasil, ia hanya menangisi segalanya. Masukkan ia ke bak berisi air hangat. Kekuatan air yang misterius dan meredakan ketegangan itu akan langsung membawa ketenangan besar ke seluruh kamar dan sistem sarafnya. Coba dan lihat.', title_ja = 'お湯で疲れを洗い流す 🛀', body_ja = '何をしてもうまくいかず、何にでも泣いてしまう日もあります。ぬるめのお湯をはった浴槽に入れてあげましょう。お湯のふしぎな、緊張をほぐす力が、部屋じゅうにもこの子の神経にもすぐに大きな安らぎを届けます。ためしてみて。', title_ko = '물로 피로를 씻어 내요 🛀', body_ko = '가끔은 아무것도 통하지 않고 아이가 모든 일에 울기만 하죠. 미지근한 물을 채운 욕조에 넣어 주세요. 긴장을 풀어 주는 물의 신비한 힘이 방 전체와 아이의 신경계에 금세 큰 평온을 가져다줄 거예요. 해 보세요.', title_nl = 'Alle vermoeidheid wegspoelen met water 🛀', body_nl = 'Soms werkt niets en huilt hij gewoon om alles. Zet hem in een bad met lauw water. De mystieke, spanning verlagende kracht van water brengt meteen grote rust in de hele kamer en in zijn zenuwstelsel. Probeer het maar.', title_pl = 'Zmyć wodą całe zmęczenie 🛀', body_pl = 'Czasem nic nie działa, on po prostu płacze o wszystko. Włóż go do wanny z ciepłą wodą. Tajemnicza, kojąca moc wody od razu przyniesie wielki spokój całemu pokojowi i jego układowi nerwowemu. Sprawdź i zobacz.', title_pt = 'Lavar todo o cansaço com água 🛀', body_pt = 'Às vezes nada resulta e ele chora por tudo. Ponha-o na banheira com água morna. O poder místico da água, que alivia a tensão, vai trazer logo uma grande paz a todo o quarto e ao sistema nervoso dele. Experimente e veja.', title_sv = 'Skölj bort all trötthet med vatten 🛀', body_sv = 'Ibland fungerar ingenting, barnet gråter bara över allt. Lägg barnet i ett badkar med ljummet vatten. Vattnets mystiska, spänningsdämpande kraft ger genast ett stort lugn i hela rummet och i barnets nervsystem. Prova och se.', title_vi = 'Gột rửa mọi mệt mỏi bằng nước 🛀', body_vi = 'Đôi khi chẳng có gì hiệu quả, bé cứ khóc vì mọi thứ. Hãy cho bé vào bồn nước ấm. Sức mạnh kỳ diệu, xua tan căng thẳng của nước sẽ ngay lập tức mang lại sự bình yên lớn cho cả căn phòng và hệ thần kinh của bé. Thử xem nhé.', title_zh = '用水洗去所有疲惫 🛀', body_zh = '有时候什么都不管用，宝宝对什么都哭。把宝宝放进装满温水的浴缸。水那种神奇、能化解紧张的力量，会立刻给整个房间和宝宝的神经系统带来平静。试试看吧。' WHERE id = '7a348b09-00b7-46e1-8565-808daca1314c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No adivines el tiempo por la ventana ⛅', body_es = '¿Fuera hace sol, pero también sopla viento? Si la herramienta Tiempo y ropa te aconseja vestirlo por capas, hazle caso. En vez de quedarte dudando y refunfuñando en la puerta, elige el conjunto adecuado y salid tranquilos.', title_fr = 'Ne devinez pas la météo par la fenêtre ⛅', body_fr = 'Il y a du soleil dehors, mais aussi du vent ? Si l''outil Météo et tenue vous conseille de l''habiller en plusieurs couches, faites-lui confiance. Plutôt que d''hésiter et de râler sur le pas de la porte, choisissez la bonne tenue et sortez sereinement.', title_hi = 'मौसम का अंदाज़ा खिड़की से मत लगाइए ⛅', body_hi = 'बाहर धूप है, पर हवा भी चल रही है? अगर मौसम और कपड़े टूल परतों में कपड़े पहनाने की सलाह दे, तो उस पर भरोसा कीजिए। दरवाज़े पर दुविधा में खड़े होकर बड़बड़ाने के बजाय सही कपड़े चुनिए और आराम से बाहर निकलिए।', title_id = 'Jangan menebak cuaca dari jendela ⛅', body_id = 'Di luar cerah, tapi juga berangin? Kalau fitur Cuaca dan Pakaian menyarankan berpakaian berlapis, percayalah. Daripada bimbang dan mengomel di depan pintu, pilih setelan yang tepat dan keluarlah dengan nyaman.', title_ja = '天気は窓から予想しないで ⛅', body_ja = '外は晴れているけれど、風も吹いている？「天気と服装」が重ね着をすすめているなら、信じましょう。玄関で迷ってぶつぶつ言うより、ぴったりのコーデを選んで、気持ちよくお出かけしましょう。', title_ko = '날씨는 창밖으로 짐작하지 마세요 ⛅', body_ko = '밖에 해는 났는데 바람도 부나요? 날씨와 옷차림 도구가 겹쳐 입히라고 하면 믿으세요. 현관에서 망설이며 투덜대기보다 알맞은 옷을 골라 편하게 나가세요.', title_nl = 'Raad het weer niet door het raam ⛅', body_nl = 'Schijnt buiten de zon, maar waait het ook? Als Weer en kleding je aanraadt hem laagjes aan te trekken, vertrouw daarop. In plaats van besluiteloos en mopperend bij de deur te staan, kies je de juiste outfit en gaan jullie rustig naar buiten.', title_pl = 'Nie oceniaj pogody przez okno ⛅', body_pl = 'Na dworze świeci słońce, ale też wieje wiatr? Jeśli narzędzie Pogoda i ubiór radzi ubrać go na cebulkę, zaufaj mu. Zamiast stać niezdecydowana w drzwiach i narzekać, wybierz odpowiedni zestaw i spokojnie wyjdźcie.', title_pt = 'Não adivinhe o tempo pela janela ⛅', body_pt = 'Lá fora há sol, mas também sopra vento? Se a ferramenta Tempo e Roupa aconselha vesti-lo por camadas, confie. Em vez de ficar indecisa à porta a resmungar, escolha a combinação certa e saiam tranquilos.', title_sv = 'Gissa inte vädret genom fönstret ⛅', body_sv = 'Solen skiner ute, men det blåser också? Om verktyget Väder och kläder tipsar om att klä barnet i lager, lita på det. I stället för att stå villrådig och muttra vid dörren, välj rätt kombination och gå ut i lugn och ro.', title_vi = 'Đừng đoán thời tiết qua cửa sổ ⛅', body_vi = 'Bên ngoài có nắng nhưng gió cũng thổi? Nếu Thời tiết và trang phục khuyên mặc nhiều lớp, hãy tin nó. Thay vì đứng phân vân càu nhàu ở cửa, hãy chọn bộ đồ phù hợp và thoải mái ra ngoài.', title_zh = '别隔着窗户猜天气 ⛅', body_zh = '外面有太阳，但也在刮风？如果天气与穿衣工具建议分层穿，就相信它。与其在门口犹豫唠叨，不如选好合适的搭配，安心出门。' WHERE id = '1d8c6250-cd7d-4c49-8588-80172d7ce7fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Su comida no la comparte contigo 🍳', body_es = '¿No te da nada de su plato, pero insiste en comer del tuyo? Los niños siempre confían plenamente en lo que eligen sus padres. No pelees: pásale el bocado con cariño y sonríe ante este egoísmo tan cómico.', title_fr = 'Il ne partage pas son repas avec vous 🍳', body_fr = 'Il ne vous donne rien de son assiette, mais vient insister pour manger dans la vôtre ? Les enfants font toujours entièrement confiance aux choix de leurs parents. Ne luttez pas, donnez-lui la bouchée avec amour et souriez simplement à cet égoïsme comique.', title_hi = 'अपना खाना आपको नहीं देगा 🍳', body_hi = 'अपनी प्लेट का खाना आपको नहीं देता, पर आकर ज़िद से आपकी प्लेट से खाना चाहता है? बच्चे अपने माता-पिता की पसंद पर हमेशा पूरा भरोसा करते हैं। लड़िए मत, निवाला प्यार से उसे दे दीजिए और इस मज़ेदार स्वार्थ पर बस मुस्कुराइए।', title_id = 'Makanannya sendiri tidak akan dibagi 🍳', body_id = 'Ia tidak mau membagi isi piringnya, tapi bersikeras makan dari piring Anda? Anak selalu sepenuhnya percaya pada pilihan orang tuanya. Jangan dilawan, berikan suapan itu dengan penuh cinta dan tersenyumlah saja pada keegoisan lucu ini.', title_ja = '自分のごはんはくれない 🍳', body_ja = '自分のお皿のものはくれないのに、あなたのお皿からは食べたがる？子どもはいつも、親の選ぶものを信頼しています。争わずに、ひと口を愛情こめて分けてあげて、このおかしなわがままにただほほえみましょう。', title_ko = '자기 음식은 절대 안 줘 🍳', body_ko = '자기 접시는 절대 안 나눠 주면서 엄마 접시의 음식은 꼭 먹겠다고 하나요? 아이들은 부모의 선택을 언제나 믿어요. 실랑이하지 말고 한 입을 사랑스럽게 건네며 이 귀여운 이기심에 그냥 웃어 주세요.', title_nl = 'Zijn eigen eten deelt hij niet 🍳', body_nl = 'Geeft hij jou niets van zijn bord, maar wil hij per se van jouw bord eten? Kinderen vertrouwen altijd volledig op de keuze van hun ouders. Ga de strijd niet aan, geef hem liefdevol een hapje en glimlach gewoon om dit grappige egoïsme.', title_pl = 'Swojego jedzenia ci nie odda 🍳', body_pl = 'Nie daje ci nic ze swojego talerza, ale uparcie chce jeść z twojego? Dzieci zawsze w pełni ufają wyborom rodziców. Nie walcz, z miłością podaj mu kęs i po prostu uśmiechnij się do tego zabawnego egoizmu.', title_pt = 'Não dá a comida dele 🍳', body_pt = 'Não lhe dá nada do prato dele, mas vem insistir em comer do seu? As crianças confiam sempre totalmente nas escolhas dos pais. Não lute: passe-lhe a garfada com amor e sorria simplesmente a este egoísmo cómico.', title_sv = 'Ger inte bort sin egen mat 🍳', body_sv = 'Barnet delar inte med sig av det som ligger på hens tallrik, men vill envist äta från din? Barn litar alltid helt på föräldrarnas val. Kämpa inte emot, ge barnet tuggan med kärlek och le bara åt den komiska egoismen.', title_vi = 'Không chia đồ ăn của mình 🍳', body_vi = 'Bé không cho mẹ ăn gì trong đĩa của mình, nhưng lại nhất định đòi ăn từ đĩa của mẹ? Trẻ luôn hoàn toàn tin vào lựa chọn của cha mẹ. Đừng giằng co, hãy âu yếm đút cho bé một miếng và mỉm cười trước sự "ích kỷ" đáng yêu này.', title_zh = '自己的饭不给你 🍳', body_zh = '自己盘子里的不给你，却非要来吃你盘子里的？孩子总是完全信任父母的选择。别较劲，满怀爱意地把这一口递给宝宝，对这份可爱的“自私”笑一笑吧。' WHERE id = '78e7980c-5a72-49e5-bf40-4486d421427a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi cuento, mis reglas 📖', body_es = '¿Te has equivocado en una palabra del cuento y te ha corregido al instante? ¡Se lo sabe de memoria! Cierra el libro y dile: «Entonces esta noche me lo lees tú». Deja que trabaje su mundo imaginario y tú solo túmbate y escucha esa vocecita tan dulce.', title_fr = 'Mon conte, mes règles 📖', body_fr = 'Vous vous êtes trompée d''un mot en lisant le conte et il vous a aussitôt corrigée ? Il le connaît donc par cœur ! Fermez le livre et dites : « Alors ce soir, c''est toi qui me lis. » Laissez son imaginaire travailler, et vous, allongez-vous et écoutez simplement sa douce voix.', title_hi = 'मेरी कहानी, मेरे नियम 📖', body_hi = 'कहानी पढ़ते समय कोई शब्द गलत बोला और उसने फ़ौरन आपको ठीक कर दिया? यानी उसे याद हो गई है! किताब बंद कीजिए और कहिए, ‘तो आज शाम तुम मुझे पढ़कर सुनाओ।’ उसकी कल्पना की दुनिया को काम करने दीजिए, और आप बस लेटकर उसकी प्यारी आवाज़ सुनिए।', title_id = 'Dongengku, aturanku 📖', body_id = 'Saat membacakan dongeng Anda salah mengucapkan satu kata dan ia langsung membetulkan? Berarti ia sudah hafal! Tutup bukunya dan katakan ''Kalau begitu malam ini kamu yang bacakan untuk Mama''. Biarkan dunia khayalnya bekerja, sementara Anda cukup berbaring dan mendengarkan suara manisnya.', title_ja = 'わたしのお話、わたしのルール 📖', body_ja = '絵本を読んでいて言いまちがえたら、すぐに直された？暗記しているんですね！本を閉じて「じゃあ今夜はママに読んで」と言ってみて。この子の想像の世界を働かせて、あなたは横になってかわいい声を聞くだけでOK。', title_ko = '내 동화, 내 규칙 📖', body_ko = '동화를 읽다 한 단어를 틀렸더니 바로 고쳐 주나요? 다 외웠다는 뜻이에요! 책을 덮고 ''그럼 오늘은 네가 읽어 줘''라고 해 보세요. 아이의 상상 세계가 움직이게 두고, 엄마는 누워서 그 귀여운 목소리만 들으세요.', title_nl = 'Mijn verhaal, mijn regels 📖', body_nl = 'Las je tijdens het voorlezen een woord verkeerd en verbeterde hij je meteen? Dan kent hij het uit zijn hoofd! Sluit het boek en zeg: ''Lees jij mij vanavond dan maar voor.'' Laat zijn fantasie het werk doen, en jij ligt gewoon te luisteren naar dat lieve stemmetje.', title_pl = 'Moja bajka, moje zasady 📖', body_pl = 'Pomyliłaś słowo podczas czytania bajki, a on od razu cię poprawił? Czyli zna ją na pamięć! Zamknij książkę i powiedz: „To dziś wieczorem ty mi poczytaj”. Niech pracuje jego wyobraźnia, a ty po prostu połóż się i słuchaj jego słodkiego głosu.', title_pt = 'A minha história, as minhas regras 📖', body_pt = 'Ao ler a história, disse mal uma palavra e ele corrigiu-a logo? Quer dizer que já a sabe de cor! Feche o livro e diga: "Então esta noite és tu que me lês". Deixe o mundo da imaginação dele trabalhar e limite-se a deitar-se e a ouvir aquela voz doce.', title_sv = 'Min saga, mina regler 📖', body_sv = 'Sa du fel ord när du läste sagan och barnet rättade dig direkt? Då kan hen den utantill! Stäng boken och säg: ”Då får du läsa för mig i kväll.” Låt fantasin arbeta, medan du bara ligger och lyssnar på barnets söta röst.', title_vi = 'Truyện của con, luật của con 📖', body_vi = 'Đọc truyện mà mẹ đọc sai một từ, bé sửa ngay lập tức? Vậy là bé thuộc lòng rồi! Hãy gấp sách lại: "Vậy tối nay con đọc cho mẹ nghe nhé." Để trí tưởng tượng của bé làm việc, còn mẹ chỉ việc nằm nghe giọng nói ngọt ngào của bé.', title_zh = '我的故事，我的规则 📖', body_zh = '讲故事时你说错了一个词，宝宝立刻纠正你？说明已经背下来了！合上书，说：“那今晚你读给我听。”让宝宝的想象力尽情发挥，你只要躺着听那甜甜的声音就好。' WHERE id = 'bdc2de1f-725b-4742-942a-3e8bf91a38f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Construir la torre y luego tirarla 🧱', body_es = '¿Construye con mucho esfuerzo una torre de bloques y luego la tira de un golpe entre carcajadas? Aunque a ti te dé pena tanto trabajo, él está aprendiendo física y causa y efecto. Estos derrumbes son nuevas conexiones en su cerebro, no te enfades.', title_fr = 'Construire la tour, puis la démolir 🧱', body_fr = 'Il construit une tour de cubes avec beaucoup d''efforts, puis la démolit en éclatant de rire ? Même si vous regrettez votre peine, il apprend la physique, la cause et l''effet. Ces démolitions sont de nouvelles connexions dans son cerveau, ne vous énervez pas.', title_hi = 'मीनार बनाना, फिर गिराना 🧱', body_hi = 'बड़ी मेहनत से ब्लॉक्स की मीनार बनाता है, फिर ठहाका लगाकर उसे गिरा देता है? आपको उसकी मेहनत पर अफ़सोस हो सकता है, पर वह भौतिकी और कारण-परिणाम सीख रहा है। ये गिरती मीनारें उसके दिमाग में नए जुड़ाव हैं, नाराज़ मत होइए।', title_id = 'Membangun menara, lalu merobohkannya 🧱', body_id = 'Ia susah payah membangun menara dari balok, lalu merobohkannya dengan sekali sentuh sambil tertawa terbahak-bahak? Meski Anda menyayangkan jerih payahnya, ia sedang belajar fisika dan sebab-akibat. Reruntuhan ini adalah koneksi baru di otaknya, jangan kesal.', title_ja = 'タワーをつくって、こわす 🧱', body_ja = '一生けんめいブロックでタワーをつくり、大笑いしながら一気にこわす？あなたは苦労が惜しくても、この子は物理や原因と結果を学んでいます。こわれたものは、脳の中の新しいつながり。イライラしないで。', title_ko = '탑을 쌓고, 무너뜨리고 🧱', body_ko = '공들여 블록 탑을 쌓고는 깔깔 웃으며 단번에 무너뜨리나요? 엄마는 그 수고가 아깝겠지만 아이는 물리와 원인과 결과를 배우고 있어요. 이 무너짐이 아이 뇌의 새로운 연결이에요, 화내지 마세요.', title_nl = 'Een toren bouwen en dan omgooien 🧱', body_nl = 'Bouwt hij met veel moeite een toren van blokken en gooit hij hem daarna schaterend om? Ook al vind jij het zonde van de moeite, hij leert natuurkunde en oorzaak en gevolg. Die verwoestingen zijn nieuwe verbindingen in zijn brein, word niet boos.', title_pl = 'Zbudować wieżę i ją zburzyć 🧱', body_pl = 'Z wielkim trudem buduje wieżę z klocków, a potem ze śmiechem jednym ruchem ją burzy? Ty żałujesz jego pracy, a on poznaje fizykę oraz przyczynę i skutek. Te zniszczenia to nowe połączenia w jego mózgu, nie denerwuj się.', title_pt = 'Construir a torre e depois deitá-la abaixo 🧱', body_pt = 'Constrói com muito esforço uma torre de cubos e depois deita-a abaixo às gargalhadas? Mesmo que a mãe tenha pena do trabalho, ele está a aprender física e causa-efeito. Estas destruições são novas ligações no cérebro dele, não se irrite.', title_sv = 'Bygga ett torn och sedan riva det 🧱', body_sv = 'Bygger barnet ett torn av klossar med stor möda och river det sedan med ett gapskratt? Även om du tycker det är synd om ansträngningen, lär sig barnet fysik och orsak och verkan. Raserna är nya kopplingar i hjärnan, bli inte irriterad.', title_vi = 'Xây tháp rồi phá tháp 🧱', body_vi = 'Bé cặm cụi xây tháp bằng khối gỗ, rồi cười khanh khách đẩy đổ nó? Dù mẹ tiếc công sức, bé đang học vật lý và quan hệ nhân quả. Những lần "phá hủy" này là những kết nối mới trong não bé, đừng bực mình nhé.', title_zh = '搭好高塔，再推倒 🧱', body_zh = '费了好大劲用积木搭起高塔，然后哈哈大笑着一下推倒？你也许心疼那份辛苦，但宝宝正在学习物理和因果关系。这些“破坏”就是大脑里新建立的连接，别生气。' WHERE id = '02c28ca2-9054-4fe0-ba4f-902da3aebfad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Y mi comida dónde está? 🥗', body_es = '¿Le preparas al peque un plato especial con verduras y tú te quedas mordisqueando pan? ¡Para! Hazte esa ensalada fácil de 5 minutos para mamás del plan de Nutrición y no olvides por fin recargar el motor principal de esta casa (tú). Tú importas.', title_fr = 'Où est mon déjeuner ? 🥗', body_fr = 'Vous préparez à l''enfant une assiette spéciale de légumes et vous, vous grignotez du pain ? Stop ! Faites la salade facile en 5 minutes pour les mamans du Plan de nutrition, et n''oubliez pas enfin de recharger le moteur principal de cette maison (vous-même). Vous comptez.', title_hi = 'मेरा लंच कहाँ है? 🥗', body_hi = 'बच्चे के लिए सब्ज़ियों वाली खास प्लेट बनाई और खुद ब्रेड चबा रही हैं? रुकिए! फ़ीडिंग प्लान में माँओं के लिए वाला 5 मिनट का आसान सलाद बनाइए, और इस घर के असली इंजन (यानी खुद को) चार्ज करना मत भूलिए। आप ज़रूरी हैं।', title_id = 'Makan siangku mana? 🥗', body_id = 'Anda menyiapkan piring sayur istimewa untuk anak, sementara Anda sendiri cuma mengunyah roti? Berhenti! Buat salad 5 menit yang mudah untuk ibu dari Rencana Nutrisi, dan akhirnya jangan lupa mengisi ulang mesin utama rumah ini (yaitu Anda). Anda berharga.', title_ja = 'わたしのランチはどこ？ 🥗', body_ja = '子どもには野菜たっぷりの特別なお皿を用意して、自分はパンをかじっている？ストップ！「栄養管理ツール」にあるママ向けの簡単5分サラダをつくって、この家のメインエンジン（あなた自身）の充電を忘れないで。あなたは大切な人です。', title_ko = '내 점심은 어디 있지? 🥗', body_ko = '아이에겐 채소 가득한 특별 식판을 차려 주고 정작 엄마는 빵만 뜯고 있나요? 잠깐만요! 식단 계획에 있는 엄마를 위한 간단한 5분 샐러드를 만들어, 이 집의 엔진인 나 자신을 충전하는 걸 잊지 마세요. 엄마는 소중해요.', title_nl = 'Waar is mijn lunch? 🥗', body_nl = 'Maak je een speciaal bordje met groenten voor je kind, terwijl je zelf op een stuk brood knaagt? Stop! Maak die makkelijke salade van 5 minuten voor mama''s uit het onderdeel Voeding en vergeet niet eindelijk de belangrijkste motor van dit huis (jezelf) op te laden. Jij doet ertoe.', title_pl = 'A gdzie mój obiad? 🥗', body_pl = 'Przygotowałaś dziecku specjalny talerz z warzywami, a sama podgryzasz chleb? Stop! Zrób z planu karmienia tę łatwą 5-minutową sałatkę dla mam i w końcu nie zapomnij naładować głównego silnika tego domu, czyli siebie. Jesteś ważna.', title_pt = 'Onde está o meu almoço? 🥗', body_pt = 'Preparou-lhe um prato especial com legumes e a mãe está a roer pão? Pare! Faça aquela salada fácil de 5 minutos para mães do plano de alimentação e não se esqueça de carregar, finalmente, o motor principal desta casa (você). Você é importante.', title_sv = 'Var är min lunch? 🥗', body_sv = 'Har du gjort en speciell grönsakstallrik till barnet medan du själv gnager på en brödbit? Stopp! Gör den enkla 5-minuterssalladen för mammor i matplanen och glöm inte att äntligen ladda hemmets viktigaste motor (dig själv). Du är viktig.', title_vi = 'Bữa trưa của mẹ đâu? 🥗', body_vi = 'Mẹ chuẩn bị cho bé đĩa rau củ đặc biệt, còn mình thì gặm bánh mì? Dừng lại! Hãy làm món salad 5 phút dễ dàng dành cho mẹ trong Kế hoạch dinh dưỡng, và đừng quên "sạc pin" cho động cơ chính của ngôi nhà này (chính mẹ). Mẹ rất quan trọng.', title_zh = '我的午饭呢？🥗', body_zh = '给宝宝做了一盘专门的蔬菜餐，自己却在啃面包？停！在喂养计划里做一份给妈妈的5分钟简单沙拉，别忘了给这个家的主引擎（你自己）充充电。你很重要。' WHERE id = '380dd8d0-d6f8-457c-b025-9b12f69938f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga las luces, que llegue el sueño 🌙', body_es = '1 hora antes de dormir, apaga todas las luces fuertes de la habitación y la tele. A medida que la habitación se oscurece, empezará a bostezar solo. Activa así la melatonina (la hormona del sueño) de forma discreta y natural, y facilítate la tarea.', title_fr = 'Éteignez les lumières, que le sommeil vienne 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières fortes et la télé dans la pièce. À mesure que la pièce s''assombrit, il commencera automatiquement à bâiller. Activez ainsi la mélatonine (l''hormone du sommeil) en douce et naturellement, et facilitez-vous la tâche.', title_hi = 'लाइटें बंद, नींद आए 🌙', body_hi = 'सोने से 1 घंटा पहले कमरे की सारी तेज़ लाइटें और टीवी बंद कर दीजिए। कमरा जैसे-जैसे धुँधला होगा, वह अपने आप जम्हाई लेने लगेगा। मेलाटोनिन (नींद का हार्मोन) को इसी तरह चुपचाप और प्राकृतिक तरीके से चालू कीजिए और अपना काम आसान बनाइए।', title_id = 'Matikan lampu, biarkan kantuk datang 🌙', body_id = '1 jam sebelum tidur, matikan semua lampu terang dan TV di kamar. Seiring kamar makin redup, ia akan otomatis mulai menguap. Dengan cara ini aktifkan melatonin (hormon tidur) secara diam-diam dan alami, dan permudah tugas Anda.', title_ja = '明かりを消して、眠りを呼ぼう 🌙', body_ja = '寝る1時間前に、部屋の明るい照明とテレビをすべて消しましょう。部屋が暗くなるにつれて、自然とあくびが出てきます。メラトニン（睡眠ホルモン）をこうしてさりげなく自然に働かせて、寝かしつけを楽にしましょう。', title_ko = '불을 끄면 잠이 와요 🌙', body_ko = '잠들기 1시간 전에 방 안의 밝은 조명과 TV를 모두 끄세요. 방이 어두워질수록 저절로 하품을 하기 시작할 거예요. 이렇게 몰래, 자연스럽게 멜라토닌(수면 호르몬)이 나오게 해서 엄마 일도 덜어 보세요.', title_nl = 'Licht uit, tijd voor slaap 🌙', body_nl = 'Doe een uur voor bedtijd alle felle lampen en de tv in de kamer uit. Naarmate het donkerder wordt, begint hij vanzelf te gapen. Zo zet je stiekem en op natuurlijke wijze melatonine (het slaaphormoon) aan het werk en maak je het jezelf makkelijker.', title_pl = 'Zgaś światło, niech przyjdzie sen 🌙', body_pl = 'Godzinę przed snem zgaś w pokoju wszystkie mocne światła i telewizor. Gdy w pokoju zrobi się ciemniej, automatycznie zacznie ziewać. Tak po cichu i naturalnie uruchomisz melatoninę (hormon snu) i ułatwisz sobie zadanie.', title_pt = 'Apague as luzes e o sono vem 🌙', body_pt = '1 hora antes de dormir, apague todas as luzes fortes do quarto e a televisão. À medida que o quarto escurece, ele começa a bocejar automaticamente. Ative assim a melatonina (hormona do sono), de forma discreta e natural, e facilite o seu trabalho.', title_sv = 'Släck lamporna, låt sömnen komma 🌙', body_sv = 'En timme före läggdags, släck alla starka lampor och tv:n i rummet. När rummet blir mörkare börjar barnet gäspa automatiskt. Sätt i gång melatoninet (sömnhormonet) i smyg och på naturlig väg och gör det lättare för dig själv.', title_vi = 'Tắt đèn, giấc ngủ đến 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và TV trong phòng. Căn phòng càng tối, bé sẽ tự động bắt đầu ngáp. Đó là cách lặng lẽ và tự nhiên để kích hoạt melatonin (hormone giấc ngủ), giúp việc của mẹ nhẹ nhàng hơn.', title_zh = '关灯，睡意就来 🌙', body_zh = '睡前1小时，把房间里所有强光和电视都关掉。房间暗下来，宝宝就会自然地打起哈欠。就这样悄悄地、自然地启动褪黑素（睡眠激素），让自己轻松一点。' WHERE id = '44db284c-e980-4095-8376-f1dcb5c24c8a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La gravedad que acaba en el suelo 🍝', body_es = '¿Tira la comida al suelo a propósito y se queda mirando cómo cae? No grites: en realidad no quiere provocarte, quiere comprobar la gravedad. Retírale el plato con calma, la lección ya la darás luego.', title_fr = 'La gravité renversée par terre 🍝', body_fr = 'Il jette exprès son repas par terre et le regarde tomber ? Ne criez pas : en réalité, il ne veut pas vous agacer, mais tester la gravité. Retirez calmement l''assiette devant lui, la leçon attendra.', title_hi = 'फ़र्श पर गिरता गुरुत्वाकर्षण 🍝', body_hi = 'खाना जानबूझकर फ़र्श पर फेंककर उसे गिरते देखता है? चिल्लाइए मत, वह असल में चिढ़ाना नहीं, गुरुत्वाकर्षण परखना चाहता है। प्लेट चुपचाप उसके सामने से हटा लीजिए, यह पाठ बाद में पढ़ा लीजिएगा।', title_id = 'Gravitasi yang tumpah ke lantai 🍝', body_id = 'Ia sengaja menjatuhkan makanan ke lantai lalu memperhatikannya? Jangan berteriak, sebenarnya ia bukan ingin membuat Anda kesal, tapi ingin menguji gravitasi. Ambil piringnya dengan tenang dari depannya, pelajarannya bisa dibahas nanti.', title_ja = '床に落ちる重力の実験 🍝', body_ja = 'わざと食べものを床に落として、それを見ている？叫ばないで。本当はイライラさせたいのではなく、重力を確かめたいんです。お皿をそっと下げて、レッスンはまた今度にしましょう。', title_ko = '바닥으로 쏟아지는 중력 실험 🍝', body_ko = '일부러 음식을 바닥에 떨어뜨리고 그걸 지켜보나요? 소리치지 마세요. 약 올리려는 게 아니라 중력을 시험하는 거예요. 조용히 접시를 치우고, 이야기는 나중에 하세요.', title_nl = 'Zwaartekracht op de vloer 🍝', body_nl = 'Gooit hij expres eten op de grond en kijkt hij het na? Ga niet schreeuwen, hij wil je niet irriteren maar de zwaartekracht testen. Haal het bord rustig weg, de les komt later wel.', title_pl = 'Grawitacja rozlana na podłodze 🍝', body_pl = 'Celowo rzuca jedzenie na podłogę i patrzy, jak spada? Nie krzycz, on wcale nie chce cię drażnić, tylko sprawdza grawitację. Spokojnie zabierz mu talerz sprzed nosa, lekcję przerobisz później.', title_pt = 'A gravidade que cai no chão 🍝', body_pt = 'Atira a comida ao chão de propósito e fica a olhar? Não grite: na verdade não quer irritá-la, quer testar a gravidade. Tire-lhe o prato da frente com calma, a lição fica para depois.', title_sv = 'Tyngdkraften på golvet 🍝', body_sv = 'Kastar barnet maten på golvet med flit och tittar efter den? Skrik inte, hen vill egentligen inte reta dig, utan testa tyngdkraften. Ta lugnt bort tallriken, lektionen kan du ta senare.', title_vi = 'Trọng lực trên sàn nhà 🍝', body_vi = 'Bé cố tình ném đồ ăn xuống sàn rồi nhìn theo? Đừng quát, bé không muốn chọc tức mẹ, mà muốn thử nghiệm trọng lực. Hãy bình tĩnh lấy đĩa đi, bài học để sau cũng được.', title_zh = '掉到地上的万有引力 🍝', body_zh = '故意把食物扔到地上，还盯着看？别吼，宝宝其实不是想惹你，而是在测试万有引力。平静地把盘子从宝宝面前拿走，这堂课以后再上。' WHERE id = '63fa1eaa-e73f-4258-a342-669de7f7f892' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Llámame Batman! 🦇', body_es = '¿Se ha despertado, rechaza su nombre y exige que lo llamen de otra forma? ¡Adáptate! Durante 5 minutos dile «Aquí tienes, Batman, cómete las gachas» y convierte la tensión de la habitación en comedia.', title_fr = 'Appelle-moi Batman ! 🦇', body_fr = 'Il s''est réveillé ce matin, refuse son propre prénom et exige qu''on l''appelle autrement ? Adaptez-vous ! Pendant 5 minutes, dites « Voilà, Batman, mange ta bouillie » et transformez la tension de la pièce en comédie.', title_hi = 'मुझे बैटमैन बुलाओ! 🦇', body_hi = 'सुबह उठकर अपना नाम ठुकरा दिया और किसी और नाम से बुलाए जाने की माँग करता है? ढल जाइए! 5 मिनट तक ‘लीजिए बैटमैन, अपना दलिया खाइए’ कहकर कमरे का तनाव कॉमेडी में बदल दीजिए।', title_id = 'Panggil aku Batman! 🦇', body_id = 'Ia bangun pagi, menolak namanya sendiri, dan menuntut dipanggil dengan nama lain? Ikuti saja! Selama 5 menit, ubah ketegangan di kamar menjadi komedi dengan berkata ''Silakan, Batman, makan buburmu''.', title_ja = 'バットマンって呼んで！ 🦇', body_ja = '朝起きて自分の名前を拒否し、別の名前で呼んでと言う？合わせてあげましょう！5分間「どうぞ、バットマン、おかゆをめしあがれ」と言って、部屋の緊張をコメディに変えましょう。', title_ko = '나를 배트맨이라고 불러! 🦇', body_ko = '아침에 일어나서 자기 이름을 거부하고 다른 이름으로 불러 달라고 하나요? 맞춰 주세요! 5분 동안 ''자, 배트맨, 죽 드세요'' 하며 방 안의 긴장을 코미디로 바꾸세요.', title_nl = 'Noem me Batman! 🦇', body_nl = 'Werd hij wakker, wil hij zijn eigen naam niet meer en eist hij dat je hem anders noemt? Ga erin mee! Zeg 5 minuten lang ''Alsjeblieft Batman, eet je pap op'' en verander de spanning in de kamer in komedie.', title_pl = 'Mów do mnie Batman! 🦇', body_pl = 'Rano się obudził, odrzuca własne imię i żąda, żeby mówić do niego inaczej? Dostosuj się! Przez 5 minut mów: „Proszę, Batmanie, zjedz owsiankę” i zamień napięcie w pokoju w komedię.', title_pt = 'Chama-me Batman! 🦇', body_pt = 'Acordou, recusa o próprio nome e exige ser chamado de outra maneira? Entre no jogo! Durante 5 minutos diga "Aqui tens, Batman, come as tuas papas" e transforme a tensão do quarto em comédia.', title_sv = 'Kalla mig Batman! 🦇', body_sv = 'Har barnet vaknat, vägrar sitt eget namn och kräver att bli kallat något annat? Anpassa dig! I 5 minuter säger du ”Varsågod, Batman, ät din gröt” och förvandlar spänningen i rummet till komedi.', title_vi = 'Gọi con là Batman! 🦇', body_vi = 'Sáng thức dậy, bé từ chối tên của mình và đòi được gọi bằng tên khác? Hãy hòa theo! Trong 5 phút, nói "Mời Batman ăn cháo ạ" và biến căng thẳng trong phòng thành tiếng cười.', title_zh = '叫我蝙蝠侠！🦇', body_zh = '早上醒来就拒绝自己的名字，要你用别的名字叫？配合一下！用5分钟说说“请吧，蝙蝠侠，来吃粥”，把房间里的紧张变成喜剧。' WHERE id = '6e8cabf6-04bc-4e0f-a26d-cdeb494389a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama del elástico del pijama 👖', body_es = 'Grita que el pijama le aprieta (aunque se le está cayendo). Es su sensibilidad sensorial. Dile «Espera, que le echo un hechizo para que se agrande» y haz como que estiras el pijama. ¡Se lo creerá!', title_fr = 'Le drame de l''élastique du pyjama 👖', body_fr = 'Il hurle parce que son pyjama le serre (alors qu''il lui tombe des hanches). Ses sensibilités sensorielles s''en mêlent. Dites « Attends, je vais lire une formule magique pour qu''il s''agrandisse » et faites semblant d''étirer le pyjama. Il y croira !', title_hi = 'पजामे के इलास्टिक की मुसीबत 👖', body_hi = 'पजामा उसे कस रहा है, कहकर चीख-पुकार मचा रहा है (जबकि वह नीचे खिसक रहा है)। संवेदी संवेदनशीलता हावी है। कहिए, ‘रुको, जादुई मंत्र पढ़ती हूँ ताकि यह ढीला हो जाए’ और पजामे को दिखावे के लिए खींचिए। वह इस पर यकीन कर लेगा!', title_id = 'Drama karet piyama 👖', body_id = 'Ia menjerit karena piyamanya terasa sempit (padahal sampai melorot). Kepekaan sensoriknya sedang kambuh. Katakan ''Tunggu, Mama bacakan mantra supaya melar'' dan pura-pura tarik piyamanya. Ia akan percaya!', title_ja = 'パジャマのゴムが大問題 👖', body_ja = 'パジャマがきついと大さわぎ（実はずり落ちているのに）。感覚の敏感さが出ています。「待って、魔法の呪文で広げるね」と言って、パジャマを引っぱるふりをしましょう。きっと信じますよ！', title_ko = '잠옷 고무줄 소동 👖', body_ko = '잠옷이 꽉 낀다고 울부짖나요? (사실은 흘러내리는데도요.) 감각 예민함이 발동한 거예요. ''잠깐, 마법 주문을 걸어서 늘려 줄게'' 하며 잠옷을 늘리는 척하세요. 아이는 믿을 거예요!', title_nl = 'Het elastiekdrama van de pyjama 👖', body_nl = 'Gilt hij dat zijn pyjama knelt (terwijl die van hem af zakt)? Zijn zintuiglijke gevoeligheid speelt op. Zeg ''Wacht, ik spreek een toverspreuk uit zodat hij groter wordt'' en trek voor de show aan de pyjama. Hij gelooft het!', title_pl = 'Dramat z gumką od piżamy 👖', body_pl = 'Rozpacza, że piżama go ciśnie (choć tak naprawdę z niego spada). Odzywa się wrażliwość sensoryczna. Powiedz: „Poczekaj, rzucę czar, żeby się poszerzyła” i na niby ją rozciągnij. Uwierzy!', title_pt = 'O drama do elástico do pijama 👖', body_pt = 'Grita que o pijama o aperta (quando na verdade lhe está a cair). É a sensibilidade sensorial a funcionar. Diga "Espera, vou dizer um feitiço para ele alargar" e finja que estica o pijama. Ele vai acreditar!', title_sv = 'Pyjamasresårens sorg 👖', body_sv = 'Barnet skriker att pyjamasen klämmer (fast den håller på att trilla av). Den sensoriska känsligheten spelar in. Säg ”Vänta, jag läser en trollformel så att den blir större” och låtsas dra i pyjamasen. Barnet kommer att tro på det!', title_vi = 'Nỗi khổ dây chun quần ngủ 👖', body_vi = 'Bé gào lên vì quần ngủ chật (dù thật ra nó còn tuột xuống). Sự nhạy cảm giác quan đang lên tiếng. Hãy nói "Đợi đã, để mẹ đọc thần chú cho nó rộng ra" và giả vờ kéo giãn quần. Bé sẽ tin đấy!', title_zh = '睡衣松紧带的烦恼 👖', body_zh = '哭喊着说睡衣太紧（其实都快掉下来了）。这是感官敏感在作怪。说“等一下，我念个魔法咒语让它变松”，然后假装拉一拉睡衣。宝宝会相信的！' WHERE id = 'b81a0aff-ac53-43cf-bdca-b8bf4192300e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Si cierro los ojos, desapareceré 👀', body_es = '¿Intenta no parpadear y aguanta hasta que se le llenan los ojos de lágrimas? El cerebro infantil se inventa miedos inexplicables. Convierte este miedo absurdo en un juego: «Mira, yo los he cerrado y sigo aquí».', title_fr = 'Si je ferme les yeux, je disparais 👀', body_fr = 'Il essaie de ne pas cligner des yeux et résiste jusqu''à en avoir les larmes ? Le cerveau d''un enfant invente des peurs inexplicables. Dites « Regarde, j''ai fermé les yeux et je suis toujours là » et transformez cette peur absurde en jeu.', title_hi = 'आँखें बंद करूँ तो गायब हो जाऊँगा 👀', body_hi = 'पलक न झपकाने की कोशिश करता है और आँखों में पानी आने तक अड़ा रहता है? बच्चे का दिमाग अजीब-अजीब डर गढ़ लेता है। ‘देखो, मैंने आँखें बंद कीं, फिर भी यहीं हूँ’ कहकर इस बेतुके डर को खेल में बदल दीजिए।', title_id = 'Kalau aku pejamkan mata, aku akan hilang 👀', body_id = 'Ia berusaha tidak berkedip dan bertahan sampai matanya berair? Otak anak menciptakan ketakutan yang tak bisa dijelaskan. Katakan ''Lihat, Mama pejamkan mata, Mama masih di sini'' dan ubah ketakutan absurd ini menjadi permainan.', title_ja = '目をつぶったら、ぼくは消えるよ 👀', body_ja = 'まばたきしないようにがんばって、涙が出るまでこらえている？子どもの脳は説明のつかないこわさをつくり出します。「見て、目をつぶったけど、まだここにいるよ」と言って、このふしぎなこわさを遊びに変えましょう。', title_ko = '눈을 감으면 나는 사라져 👀', body_ko = '눈을 깜빡이지 않으려고 눈물이 날 때까지 버티나요? 아이의 뇌는 설명할 수 없는 두려움을 지어내요. ''봐, 엄마 눈 감았는데 아직 여기 있지?'' 하며 이 엉뚱한 두려움을 놀이로 바꿔 주세요.', title_nl = 'Als ik mijn ogen dichtdoe, verdwijn ik 👀', body_nl = 'Probeert hij niet te knipperen en houdt hij vol tot zijn ogen tranen? Een kinderbrein verzint onverklaarbare angsten. Maak van deze absurde angst een spelletje: ''Kijk, ik doe mijn ogen dicht en ik ben er nog steeds.''', title_pl = 'Jak zamknę oczy, zniknę 👀', body_pl = 'Stara się nie mrugać i wytrzymuje, aż oczy mu łzawią? Dziecięcy mózg wymyśla niewytłumaczalne lęki. Powiedz: „Zobacz, zamknęłam oczy i dalej tu jestem” i zamień ten absurdalny strach w zabawę.', title_pt = 'Se fechar os olhos, desapareço 👀', body_pt = 'Tenta não pestanejar e resiste até os olhos lacrimejarem? O cérebro da criança inventa medos inexplicáveis. Transforme este medo absurdo num jogo: "Olha, eu fechei os olhos e continuo aqui".', title_sv = 'Om jag blundar försvinner jag 👀', body_sv = 'Försöker barnet låta bli att blinka och står emot tills ögonen tåras? Barnhjärnan hittar på oförklarliga rädslor. Säg ”Titta, jag blundade och är fortfarande kvar” och gör den absurda rädslan till en lek.', title_vi = 'Con nhắm mắt là con biến mất 👀', body_vi = 'Bé cố không chớp mắt và gồng đến chảy nước mắt? Não trẻ tự nghĩ ra những nỗi sợ khó giải thích. Hãy biến nỗi sợ phi lý này thành trò chơi: "Nhìn này, mẹ nhắm mắt rồi mà vẫn ở đây."', title_zh = '我一闭眼就会消失 👀', body_zh = '拼命不眨眼，直到眼泪都流出来？孩子的大脑会编出无法解释的恐惧。说“你看，我闭上眼睛了，我还在这儿呢”，把这个荒诞的恐惧变成游戏。' WHERE id = '070422be-d317-4a23-a559-6432c6ae63ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No me toques, que da calor 🛑', body_es = '¿De repente no quiere que lo abraces? ¡No te lo tomes a mal! Está poniendo a prueba sus límites personales y que su cuerpo es solo suyo. Es una señal de independencia, míralo con orgullo desde fuera.', title_fr = 'Me touche pas, j''ai chaud 🛑', body_fr = 'Il a soudain refusé un câlin ? Ne vous vexez pas ! Il teste ses limites personnelles, le fait que son corps n''appartient qu''à lui. C''est un signe d''indépendance, observez-le de loin avec fierté.', title_hi = 'मुझे मत छुओ, गर्मी लगती है 🛑', body_hi = 'अचानक आपको गले लगाने से मना कर दिया? बुरा मत मानिए! वह अपनी निजी सीमाएँ परख रहा है कि उसका शरीर सिर्फ़ उसका है। यह आत्मनिर्भरता की निशानी है, किनारे से गर्व से देखिए।', title_id = 'Jangan sentuh aku, panas 🛑', body_id = 'Tiba-tiba ia menolak memeluk Anda? Jangan tersinggung! Ia sedang menguji batasan pribadinya, bahwa tubuhnya hanya miliknya. Ini tanda kemandirian, saksikan dengan bangga dari samping.', title_ja = 'さわらないで、暑いの 🛑', body_ja = '急に抱っこを拒否された？傷つかないで！自分の境界線や、体は自分だけのものだということをためしています。自立のサインです。そばで誇らしく見守りましょう。', title_ko = '만지지 마, 더워 🛑', body_ko = '갑자기 엄마에게 안기기를 거부했나요? 서운해하지 마세요! 자기 몸은 자기 것이라는 개인 경계를 시험하는 중이에요. 독립의 신호니까 옆에서 뿌듯하게 지켜봐 주세요.', title_nl = 'Niet aanraken, het is te warm 🛑', body_nl = 'Wil hij ineens niet meer door jou geknuffeld worden? Voel je niet gekwetst! Hij test zijn persoonlijke grenzen en ontdekt dat zijn lichaam alleen van hem is. Dit is een teken van zelfstandigheid, kijk trots van een afstandje toe.', title_pl = 'Nie dotykaj mnie, jest gorąco 🛑', body_pl = 'Nagle nie chce się do ciebie przytulić? Nie obrażaj się! Sprawdza swoje granice i to, że jego ciało należy tylko do niego. To oznaka samodzielności, przyglądaj się z dumą.', title_pt = 'Não me toques, tenho calor 🛑', body_pt = 'De repente recusou o seu abraço? Não fique magoada! Está a testar os seus limites pessoais e a perceber que o corpo só lhe pertence a ele. É um sinal de independência, observe com orgulho à distância.', title_sv = 'Rör mig inte, det blir varmt 🛑', body_sv = 'Vägrade barnet plötsligt att kramas? Ta inte illa upp! Hen testar sina personliga gränser och att kroppen bara tillhör hen själv. Det är ett tecken på självständighet, titta stolt på från sidan.', title_vi = 'Đừng chạm vào con, nóng lắm 🛑', body_vi = 'Bé bỗng từ chối cái ôm của mẹ? Đừng tự ái! Bé đang thử ranh giới cá nhân và học rằng cơ thể chỉ thuộc về mình. Đó là dấu hiệu của sự tự lập, hãy tự hào quan sát từ xa.', title_zh = '别碰我，太热了 🛑', body_zh = '突然不肯让你抱了？别难过！宝宝在测试个人边界，确认身体只属于自己。这是独立的标志，在一旁骄傲地看着吧。' WHERE id = '652ec194-fa0e-4ca8-ab49-626452c474ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir debajo del sillón 🛋️', body_es = '¿Ha rechazado su cama y se ha dormido acurrucado debajo del sillón? No lo saques de ahí a la fuerza ni lo despiertes. Deja que disfrute de dormir en un sitio distinto y protegido, y tú descansa también.', title_fr = 'Dodo sous le fauteuil 🛋️', body_fr = 'Il a refusé son lit et s''est endormi recroquevillé sous le fauteuil ? Ne le sortez pas de là de force et ne le réveillez pas. Laissez-le savourer le plaisir de dormir dans un endroit différent et protégé, et reposez-vous aussi.', title_hi = 'आरामकुर्सी के नीचे नींद 🛋️', body_hi = 'अपना बिस्तर छोड़कर आरामकुर्सी के नीचे सिकुड़कर सो गया? उसे ज़बरदस्ती वहाँ से निकालकर मत जगाइए। उसे एक अलग, सुरक्षित जगह में सोने का मज़ा लेने दीजिए, और आप भी आराम कीजिए।', title_id = 'Tidur di bawah kursi 🛋️', body_id = 'Ia menolak tempat tidurnya dan tidur meringkuk di bawah kursi berlengan? Jangan paksa menariknya keluar dan membangunkannya. Biarkan ia menikmati tidur di tempat yang berbeda dan terlindung, Anda pun bisa beristirahat.', title_ja = 'いすの下でおねんね 🛋️', body_ja = 'ベッドを拒否して、いすの下で丸くなって眠っている？無理に出して起こさないで。いつもとちがう守られた場所で眠るのを楽しませてあげて、あなたも休みましょう。', title_ko = '안락의자 밑에서 잠들기 🛋️', body_ko = '침대를 마다하고 안락의자 밑에 웅크려 잠들었나요? 억지로 꺼내 깨우지 마세요. 색다르고 아늑한 공간에서 자는 즐거움을 누리게 두고, 엄마도 쉬세요.', title_nl = 'Slapen onder de fauteuil 🛋️', body_nl = 'Wilde hij zijn bed niet en ligt hij opgekruld onder de fauteuil te slapen? Trek hem er niet onder vandaan en maak hem niet wakker. Laat hem genieten van slapen op een andere, beschutte plek, en rust zelf ook uit.', title_pl = 'Sen pod fotelem 🛋️', body_pl = 'Odrzucił swoje łóżko i zasnął zwinięty pod fotelem? Nie wyciągaj go stamtąd na siłę i nie budź. Niech nacieszy się snem w innym, chronionym miejscu, a ty też odpocznij.', title_pt = 'Uma soneca debaixo do cadeirão 🛋️', body_pt = 'Recusou a cama e adormeceu enroscado debaixo do cadeirão? Não o tire de lá à força nem o acorde. Deixe-o saborear o prazer de dormir num espaço diferente e protegido, e descanse também.', title_sv = 'Sömn under fåtöljen 🛋️', body_sv = 'Har barnet vägrat sin säng och somnat hopkrupen under fåtöljen? Dra inte fram och väck barnet. Låt hen njuta av att sova på en annorlunda, skyddad plats, och vila du också.', title_vi = 'Giấc ngủ dưới gầm ghế bành 🛋️', body_vi = 'Bé chê giường và cuộn mình ngủ dưới gầm ghế bành? Đừng lôi bé ra hay đánh thức bé. Để bé tận hưởng cảm giác ngủ ở một chỗ khác lạ, được che chắn, còn mẹ cũng nghỉ ngơi đi.', title_zh = '睡在扶手椅下面 🛋️', body_zh = '不睡自己的床，蜷在扶手椅下面睡着了？别硬把宝宝拉出来、弄醒。让宝宝享受在一个不一样、有安全感的地方睡觉，你也歇一歇。' WHERE id = 'c7f18643-0c26-48a6-bc85-4480566ce781' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué está caliente la papilla? 🥣', body_es = 'Si no está caliente no se la come, ¿pero ahora llora porque está caliente? ¡Callejón sin salida! Échale a propósito un trocito de hielo de colores: en un segundo le llamará la atención y se calmará.', title_fr = 'Pourquoi la bouillie est chaude ? 🥣', body_fr = 'Il ne la mange pas si elle n''est pas chaude, mais là il pleure parce qu''elle est chaude ? Situation sans issue ! Ajoutez exprès un glaçon coloré : en une seconde, sa curiosité sera piquée et il se calmera.', title_hi = 'दलिया गरम क्यों है? 🥣', body_hi = 'गरम न हो तो खाता नहीं, पर अब गरम है इसलिए रो रहा है? उलझन भरी हालत! उसमें जानबूझकर एक रंगीन बर्फ़ का टुकड़ा डाल दीजिए, वह सेकंडों में उत्सुक होकर शांत हो जाएगा।', title_id = 'Kenapa buburnya panas? 🥣', body_id = 'Kalau tidak panas ia tidak mau makan, tapi sekarang menangis karena panas? Jalan buntu! Sengaja masukkan sepotong es berwarna ke dalamnya, dalam sekejap rasa penasarannya muncul dan ia akan tenang.', title_ja = 'なんでおかゆが熱いの？ 🥣', body_ja = '熱くないと食べないのに、今度は熱いと泣いている？八方ふさがり！わざとカラフルな氷をひとつ入れてみて。すぐに興味を引かれて落ち着きます。', title_ko = '죽이 왜 뜨거워? 🥣', body_ko = '뜨겁지 않으면 안 먹는다더니 이제는 뜨겁다고 우나요? 진퇴양난이죠! 일부러 색깔 있는 얼음 한 조각을 넣어 보세요. 금세 호기심이 생겨 진정될 거예요.', title_nl = 'Waarom is de pap warm? 🥣', body_nl = 'Hij eet het niet als het niet warm is, maar nu huilt hij omdat het warm is? Een uitzichtloze situatie! Doe er expres een gekleurd ijsblokje in, dat trekt meteen zijn aandacht en hij kalmeert.', title_pl = 'Czemu owsianka jest ciepła? 🥣', body_pl = 'Zimnej nie zje, a teraz płacze, że jest ciepła? Sytuacja bez wyjścia! Wrzuć do niej celowo kolorową kostkę lodu, w sekundę przyciągnie to jego uwagę i się uspokoi.', title_pt = 'Porque é que as papas estão quentes? 🥣', body_pt = 'Se não estiverem quentes não come, mas agora chora porque estão quentes? Um beco sem saída! Ponha lá dentro de propósito um cubo de gelo colorido: num segundo desperta-lhe a curiosidade e ele acalma-se.', title_sv = 'Varför är gröten varm? 🥣', body_sv = 'Om den inte är varm äter barnet den inte, men nu gråter hen för att den är varm? En omöjlig situation! Lägg med flit i en färgglad isbit, då fångas intresset och barnet lugnar sig på en sekund.', title_vi = 'Sao cháo lại nóng? 🥣', body_vi = 'Không nóng thì bé không ăn, mà giờ lại khóc vì nóng? Tình thế bế tắc! Hãy cố ý thả một viên đá màu vào, bé sẽ tò mò ngay và bình tĩnh lại trong tích tắc.', title_zh = '粥为什么是热的？🥣', body_zh = '不热不吃，现在又因为热而哭？进退两难！故意往里面放一块彩色冰块，几秒钟就能吸引宝宝的兴趣，让宝宝平静下来。' WHERE id = '1fe87964-746d-4cf2-a7f3-21730045a9ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Llorar detrás de la puerta 🚪', body_es = '¿Ha cerrado la puerta, llora solo en su habitación y no quiere que entres? No intentes abrazarlo a la fuerza. A veces los niños también quieren vivir sus emociones a solas: dale tiempo y espacio.', title_fr = 'Pleurer derrière la porte 🚪', body_fr = 'Il a fermé la porte, pleure seul dans sa chambre et ne veut pas de vous ? N''essayez pas de le prendre dans vos bras de force. Parfois, les enfants aussi veulent vivre leurs émotions seuls : donnez-lui du temps et de l''espace.', title_hi = 'दरवाज़े के पीछे रोना 🚪', body_hi = 'दरवाज़ा बंद करके अपने कमरे में अकेले रो रहा है और आपको नहीं चाहता? ज़बरदस्ती गले लगाने की कोशिश मत कीजिए। कभी-कभी बच्चे भी अपनी भावनाएँ अकेले जीना चाहते हैं, उसे समय और जगह दीजिए।', title_id = 'Menangis di balik pintu 🚪', body_id = 'Ia menutup pintu, menangis sendirian di kamarnya, dan tidak mau Anda dekati? Jangan paksa memeluknya. Kadang anak juga ingin merasakan emosinya sendirian, beri ia waktu dan ruang.', title_ja = 'ドアのむこうで泣く 🚪', body_ja = 'ドアを閉めて部屋でひとりで泣き、あなたを寄せつけない？無理に抱きしめようとしないで。子どもだって、気持ちをひとりで感じたいときがあります。時間と場所をあげましょう。', title_ko = '문 뒤에서 우는 아이 🚪', body_ko = '문을 닫고 방에서 혼자 울며 엄마를 거부하나요? 억지로 안으려 하지 마세요. 아이들도 가끔은 감정을 혼자 겪고 싶어 해요. 시간과 공간을 주세요.', title_nl = 'Huilen achter de deur 🚪', body_nl = 'Doet hij de deur dicht, huilt hij alleen in zijn kamer en wil hij jou niet? Probeer hem niet te dwingen tot een knuffel. Soms willen kinderen hun gevoelens ook alleen beleven, geef hem tijd en ruimte.', title_pl = 'Płacz za drzwiami 🚪', body_pl = 'Zamknął drzwi, płacze sam w pokoju i nie chce cię widzieć? Nie próbuj przytulać go na siłę. Czasem dzieci też chcą przeżyć emocje w samotności, daj mu czas i przestrzeń.', title_pt = 'A chorar atrás da porta 🚪', body_pt = 'Fechou a porta, chora sozinho no quarto e não a quer lá? Não tente abraçá-lo à força. Às vezes as crianças também querem viver as emoções sozinhas, dê-lhe tempo e espaço.', title_sv = 'Gråt bakom dörren 🚪', body_sv = 'Har barnet stängt dörren och gråter ensamt i sitt rum och vill inte ha dig där? Försök inte krama med tvång. Ibland vill barn också uppleva sina känslor ensamma, ge hen tid och utrymme.', title_vi = 'Khóc sau cánh cửa 🚪', body_vi = 'Bé đóng cửa, khóc một mình trong phòng và không muốn mẹ vào? Đừng cố ôm bé. Đôi khi trẻ cũng muốn tự trải qua cảm xúc của mình, hãy cho bé thời gian và không gian.', title_zh = '躲在门后哭 🚪', body_zh = '关上门一个人在房间里哭，还不要你进去？别硬要去抱。有时候孩子也想独自消化情绪，给宝宝一些时间和空间吧。' WHERE id = '8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabia contra el lobo del libro 🐺', body_es = '¿Le da puñetazos al dibujo del lobo del libro y lo regaña? ¡Tiene una imaginación increíble! Sin romper su realidad, alimenta su autoestima diciéndole: «Me has protegido, eres muy valiente».', title_fr = 'En colère contre le loup du livre 🐺', body_fr = 'Il donne des coups de poing à l''image du loup dans le livre et le gronde ? Son imagination est formidable ! Sans briser la réalité, dites « Tu m''as protégée, tu es très courageux » et nourrissez sa confiance en soi.', title_hi = 'किताब वाले भेड़िये पर गुस्सा 🐺', body_hi = 'किताब में भेड़िये की तस्वीर को मुक्का मारकर डाँट रहा है? उसकी कल्पना शानदार है! असलियत तोड़े बिना, ‘तुमने मुझे बचा लिया, तुम बहुत बहादुर हो’ कहकर उसका आत्मविश्वास बढ़ाइए।', title_id = 'Marah pada serigala di buku 🐺', body_id = 'Ia meninju gambar serigala di buku dan memarahinya? Imajinasinya luar biasa! Tanpa merusak kenyataannya, pupuk rasa percaya dirinya dengan berkata ''Kamu melindungi Mama, kamu berani sekali''.', title_ja = '絵本のオオカミに怒る 🐺', body_ja = '絵本のオオカミの絵をパンチして叱っている？すばらしい想像力です！現実をこわさずに「守ってくれたのね、とっても勇敢だね」と言って、自信を育ててあげましょう。', title_ko = '책 속 늑대에게 화내기 🐺', body_ko = '책 속 늑대 그림을 주먹으로 치며 혼내나요? 상상력이 대단해요! 현실을 깨지 말고 ''엄마를 지켜 줬구나, 정말 용감해'' 하며 자신감을 키워 주세요.', title_nl = 'Boos op de wolf in het boek 🐺', body_nl = 'Slaat en scheldt hij op het plaatje van de wolf in het boek? Wat een fantasie! Doorbreek zijn werkelijkheid niet en voed zijn zelfvertrouwen met: ''Jij hebt mij beschermd, wat ben je dapper.''', title_pl = 'Złość na wilka z książki 🐺', body_pl = 'Uderza piąstką obrazek wilka w książce i na niego krzyczy? Ma wspaniałą wyobraźnię! Nie burząc jej, powiedz: „Obroniłeś mnie, jesteś bardzo odważny” i wzmocnij jego pewność siebie.', title_pt = 'Zangado com o lobo do livro 🐺', body_pt = 'Dá murros na imagem do lobo do livro e ralha-lhe? Que imaginação fantástica! Sem quebrar a fantasia, alimente a autoconfiança dele: "Protegeste-me, és muito corajoso".', title_sv = 'Ilska mot vargen i boken 🐺', body_sv = 'Slår barnet på vargbilden i boken och skäller på den? Fantasin är fantastisk! Utan att förstöra verkligheten, säg ”Du skyddade mig, du är så modig” och stärk självförtroendet.', title_vi = 'Giận con sói trong sách 🐺', body_vi = 'Bé đấm và mắng hình con sói trong sách? Trí tưởng tượng thật tuyệt vời! Đừng phá vỡ thế giới của bé, hãy nuôi dưỡng sự tự tin: "Con đã bảo vệ mẹ, con dũng cảm lắm."', title_zh = '对书里的大灰狼生气 🐺', body_zh = '用小拳头打书上的大灰狼图片，还骂它？想象力真了不起！不打破宝宝的想象，说一句“你保护了我，你真勇敢”，滋养宝宝的自信。' WHERE id = 'f52f2ceb-159e-4eff-95c6-70eae6ed7217' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No me pongas tú los calcetines! 🧦', body_es = '¿Rechaza con firmeza todo lo que haces? ¡Genial! Deja la ropa en el sofá y lanza el reto: «¿Quién se viste primero?». Se vestirá solo en segundos.', title_fr = 'Ne me mets pas mes chaussettes ! 🧦', body_fr = 'Il refuse fermement tout ce que vous faites ? Parfait ! Posez les vêtements sur le canapé et lancez la course « Qui s''habille en premier ? ». Il s''habillera seul en quelques secondes.', title_hi = 'मेरे मोज़े तुम मत पहनाओ! 🧦', body_hi = 'आपका किया हर काम पक्के इरादे से ठुकरा देता है? बढ़िया! कपड़े सोफ़े पर रखिए और ‘कौन पहले पहनेगा?’ वाली रेस शुरू कीजिए। वह सेकंडों में खुद पहन लेगा।', title_id = 'Jangan Mama yang pakaikan kaus kakiku! 🧦', body_id = 'Ia dengan tegas menolak semua yang Anda lakukan? Bagus! Taruh bajunya di sofa dan mulai lomba ''Siapa yang paling cepat berpakaian?'' Ia akan berpakaian sendiri dalam hitungan detik.', title_ja = 'くつ下はママがはかせないで！ 🧦', body_ja = 'あなたのすることをすべてきっぱり拒否する？いいですね！服をソファに置いて「どっちが先に着られるかな？」競争を始めましょう。あっという間に自分で着ますよ。', title_ko = '양말은 엄마가 신기지 마! 🧦', body_ko = '엄마가 하는 건 뭐든 단호하게 거부하나요? 좋아요! 옷을 소파에 두고 ''누가 먼저 입나?'' 시합을 시작하세요. 몇 초 만에 혼자 입을 거예요.', title_nl = 'Niet jij doet mijn sokken aan! 🧦', body_nl = 'Wijst hij resoluut alles af wat jij doet? Mooi zo! Leg de kleren op de bank en begin een wedstrijdje: ''Wie is er het eerst aangekleed?'' Binnen een paar seconden heeft hij zichzelf aangekleed.', title_pl = 'Nie zakładaj mi skarpetek! 🧦', body_pl = 'Stanowczo odrzuca wszystko, co robisz? Świetnie! Połóż ubrania na kanapie i zacznij wyścig „Kto pierwszy się ubierze?”. Ubierze się sam w kilka sekund.', title_pt = 'Não me calces tu as meias! 🧦', body_pt = 'Recusa com firmeza tudo o que a mãe faz? Ótimo! Ponha a roupa no sofá e lance a corrida "Quem se veste primeiro?". Ele veste-se sozinho em segundos.', title_sv = 'Du får inte ta på mig strumpan! 🧦', body_sv = 'Vägrar barnet bestämt allt du gör? Utmärkt! Lägg kläderna på soffan och starta tävlingen ”Vem blir påklädd först?”. Barnet klär på sig själv på några sekunder.', title_vi = 'Mẹ đừng đi tất cho con! 🧦', body_vi = 'Bé kiên quyết từ chối mọi việc mẹ làm? Tuyệt! Đặt quần áo lên sofa và mở cuộc thi "Ai mặc đồ xong trước nào?". Bé sẽ tự mặc chỉ trong vài giây.', title_zh = '袜子不要你给我穿！🧦', body_zh = '你做的每件事都被坚决拒绝？很好！把衣服放在沙发上，来一场“谁先穿好？”的比赛。宝宝几秒钟就会自己穿好。' WHERE id = '3c299611-0f24-405d-b774-857cf09c273e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filosofía debajo de la mesa 🤔', body_es = '¿Se mete debajo de la mesa y desde ahí te cuenta cosas inventadas? Deja que ese pequeño filósofo se quede en su mundo imaginario y tú aprovecha este rato para descansar.', title_fr = 'La philosophie sous la table 🤔', body_fr = 'Il s''est glissé sous la table et vous raconte de là des histoires inventées ? Laissez ce petit philosophe dans son monde imaginaire, et profitez de ce moment pour vous reposer.', title_hi = 'मेज़ के नीचे का फ़लसफ़ा 🤔', body_hi = 'मेज़ के नीचे घुसकर वहाँ से आपको कुछ गढ़ी हुई बातें सुनाता है? उस नन्हे दार्शनिक को अपनी कल्पना की दुनिया में रहने दीजिए, और आप इस समय का फ़ायदा उठाकर आराम कीजिए।', title_id = 'Filsafat di kolong meja 🤔', body_id = 'Ia masuk ke kolong meja dan dari sana menceritakan berbagai karangan kepada Anda? Biarkan filsuf kecil itu tetap di dunia khayalnya, manfaatkan waktu ini untuk beristirahat.', title_ja = 'テーブルの下の哲学 🤔', body_ja = 'テーブルの下にもぐって、そこからつくり話を聞かせてくれる？小さな哲学者は空想の世界にいさせてあげて、あなたもこの時間に休みましょう。', title_ko = '식탁 밑의 철학 🤔', body_ko = '식탁 밑에 들어가 이런저런 이야기를 지어내 들려주나요? 꼬마 철학자가 상상의 세계에 머물게 두고, 엄마도 이 시간에 쉬세요.', title_nl = 'Filosofie onder de tafel 🤔', body_nl = 'Kruipt hij onder de tafel en vertelt hij je van daaruit allerlei verzonnen dingen? Laat die kleine filosoof lekker in zijn fantasiewereld en gebruik deze tijd om zelf uit te rusten.', title_pl = 'Filozofia spod stołu 🤔', body_pl = 'Wszedł pod stół i stamtąd opowiada ci zmyślone historie? Niech ten mały filozof zostanie w swoim wymyślonym świecie, a ty wykorzystaj ten czas i odpocznij.', title_pt = 'Filosofia debaixo da mesa 🤔', body_pt = 'Meteu-se debaixo da mesa e de lá conta-lhe histórias inventadas? Deixe o pequeno filósofo ficar no seu mundo imaginário e aproveite este tempo para descansar.', title_sv = 'Filosofi under bordet 🤔', body_sv = 'Har barnet krupit in under bordet och berättar påhittade saker för dig därifrån? Låt den lilla filosofen stanna i sin fantasivärld, och ta tillfället i akt att vila.', title_vi = 'Triết lý dưới gầm bàn 🤔', body_vi = 'Bé chui xuống gầm bàn và kể cho mẹ những câu chuyện tự nghĩ ra từ dưới đó? Cứ để "triết gia" nhỏ ở lại trong thế giới tưởng tượng của mình, còn mẹ tranh thủ nghỉ ngơi.', title_zh = '桌子底下的哲学 🤔', body_zh = '钻到桌子底下，在那儿给你编故事讲？就让这位小哲学家待在自己想象的世界里吧，你也趁这段时间休息一下。' WHERE id = '3d738e03-bc77-4be0-b44b-95ecf5e6cdb0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El edredón hace ruido 🛌', body_es = '¡No puede dormir por el crujido del edredón! Las excusas raras están en su punto álgido. Tápalo con una manta ligera: al ver que tienes solución para todo, se rendirá.', title_fr = 'La couette fait du bruit 🛌', body_fr = 'Il ne peut pas dormir à cause du froissement de la couette ! Les excuses bizarres sont à leur comble. Couvrez-le d''une couverture légère : en voyant que vous avez une solution à tout, il capitulera.', title_hi = 'रज़ाई की आवाज़ आ रही है 🛌', body_hi = 'रज़ाई की सरसराहट से सो नहीं पा रहा! अजीब बहाने चरम पर हैं। उसे हल्का कंबल ओढ़ा दीजिए, जब देखेगा कि आपके पास हर चीज़ का इलाज है, तो हार मान लेगा।', title_id = 'Selimutnya berisik 🛌', body_id = 'Katanya ia tidak bisa tidur karena selimutnya berkeresek! Alasan-alasan aneh sedang di puncaknya. Selimuti ia dengan selimut tipis, melihat Anda punya solusi untuk segalanya, ia akan menyerah.', title_ja = 'ふとんの音がうるさい 🛌', body_ja = 'ふとんのカサカサいう音で眠れないんだって！ふしぎな言いわけがピークです。軽いブランケットをかけてあげましょう。何にでも解決策があるとわかれば、観念しますよ。', title_ko = '이불 소리가 들려 🛌', body_ko = '이불 바스락거리는 소리 때문에 못 자겠대요! 엉뚱한 핑계가 절정이에요. 가벼운 담요로 덮어 주세요. 엄마가 뭐든 해결책을 찾는 걸 보고 결국 항복할 거예요.', title_nl = 'Het dekbed maakt geluid 🛌', body_nl = 'Kan hij niet slapen door het geritsel van het dekbed! De rare smoesjes zijn op hun hoogtepunt. Dek hem toe met een licht dekentje, hij ziet dat je overal een oplossing voor hebt en geeft zich over.', title_pl = 'Kołdra hałasuje 🛌', body_pl = 'Nie może zasnąć, bo kołdra szeleści! Dziwne wymówki osiągają szczyt. Przykryj go lekkim kocykiem, a gdy zobaczy, że na wszystko masz sposób, się podda.', title_pt = 'O barulho do edredão 🛌', body_pt = 'Não consegue dormir por causa do restolhar do edredão! As desculpas estranhas estão no auge. Tape-o com uma manta leve: ao ver que tem solução para tudo, vai render-se.', title_sv = 'Täcket låter 🛌', body_sv = 'Barnet kunde tydligen inte sova för att täcket prasslade! De konstiga ursäkterna är på topp. Lägg en lätt filt över barnet, när hen ser att du har en lösning på allt ger hen upp.', title_vi = 'Chăn kêu sột soạt 🛌', body_vi = 'Bé không ngủ được vì tiếng sột soạt của chăn! Những lý do kỳ lạ đang lên đến đỉnh điểm. Hãy đắp cho bé một tấm chăn mỏng, thấy mẹ có cách giải quyết mọi thứ, bé sẽ chịu thua.', title_zh = '被子太吵了 🛌', body_zh = '说被子沙沙响，吵得睡不着！各种奇怪的借口正处于巅峰。给宝宝换一条轻薄的毯子，看到你什么都有办法，宝宝就会投降。' WHERE id = 'b5d5bf11-5ce6-464a-892e-f00915b62103' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La almohada no está recta! 🛏️', body_es = '¿Llora para que le pongas la almohada recta al milímetro? Es la búsqueda de la perfección. Sigue sus reglas, coloca la almohada como si la hubieras medido con regla y apaga las luces con decisión.', title_fr = 'L''oreiller n''est pas droit ! 🛏️', body_fr = 'Il pleure pour que l''oreiller soit ajusté au millimètre ? C''est la quête de la perfection. Pliez-vous aux règles, arrangez l''oreiller comme s''il était mesuré à la règle et éteignez la lumière avec fermeté.', title_hi = 'तकिया सीधा नहीं है! 🛏️', body_hi = 'तकिए को मिलीमीटर तक ठीक करवाने के लिए रो रहा है? यह परफ़ेक्शन की तलाश है। नियम मान लीजिए, तकिया ऐसे ठीक कीजिए जैसे स्केल से नापा हो, और पक्के इरादे से लाइटें बंद कर दीजिए।', title_id = 'Bantalnya tidak lurus! 🛏️', body_id = 'Ia menangis minta bantalnya dirapikan sampai ke milimeter? Ini pencarian kesempurnaan. Ikuti aturannya, rapikan bantal seolah diukur dengan penggaris, lalu matikan lampu dengan tegas.', title_ja = 'まくらがまっすぐじゃない！ 🛏️', body_ja = 'まくらをミリ単位で直したくて泣いている？完璧を求めているんです。ルールに従って、定規で測ったようにまくらを整え、きっぱり明かりを消しましょう。', title_ko = '베개가 삐뚤어졌어! 🛏️', body_ko = '베개를 밀리미터 단위로 맞추겠다고 우나요? 완벽을 추구하는 중이에요. 규칙에 따라 자로 잰 듯 베개를 반듯하게 놓고, 단호하게 불을 끄세요.', title_nl = 'Het kussen ligt niet goed! 🛏️', body_nl = 'Huilt hij omdat zijn kussen tot op de millimeter recht moet liggen? Hij zoekt perfectie. Ga mee in zijn regels, leg het kussen neer alsof je het met een liniaal hebt opgemeten en doe dan vastberaden het licht uit.', title_pl = 'Poduszka leży krzywo! 🛏️', body_pl = 'Płacze, bo poduszkę trzeba poprawić co do milimetra? To pogoń za perfekcją. Podporządkuj się zasadom, ułóż poduszkę jak od linijki i stanowczo zgaś światło.', title_pt = 'A almofada não está direita! 🛏️', body_pt = 'Chora para que a almofada fique ajeitada ao milímetro? É a procura da perfeição. Siga as regras, endireite a almofada como se a tivesse medido com régua e apague as luzes com firmeza.', title_sv = 'Kudden ligger inte rakt! 🛏️', body_sv = 'Gråter barnet för att kudden ska ligga rätt på millimetern? Det är jakten på perfektion. Följ reglerna, rätta till kudden som om den vore uppmätt med linjal och släck lamporna bestämt.', title_vi = 'Gối chưa thẳng! 🛏️', body_vi = 'Bé khóc đòi chỉnh gối chuẩn từng milimet? Đó là hành trình tìm kiếm sự hoàn hảo. Hãy làm theo luật, chỉnh gối như được đo bằng thước kẻ, rồi dứt khoát tắt đèn.', title_zh = '枕头没放正！🛏️', body_zh = '为了把枕头调整到毫米级精准而哭？这是在追求完美。照规矩来，像用尺子量过一样把枕头摆正，然后果断关灯。' WHERE id = '553ac831-9d91-4727-b2a6-83bd86e98633' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pánico al silencio en casa 🚪', body_es = '¿De repente hay demasiado silencio en casa? Saldrás a buscarlo y lo encontrarás soñando despierto detrás de una puerta. No te asustes: se está alejando del ruido para reiniciarse. Dale este tiempo.', title_fr = 'Panique du silence à la maison 🚪', body_fr = 'La maison est soudain devenue très silencieuse ? En partant à sa recherche, vous le trouverez rêveur derrière une porte. Ne vous inquiétez pas, il s''éloigne du bruit pour se réinitialiser, accordez-lui ce temps.', title_hi = 'घर की खामोशी से घबराहट 🚪', body_hi = 'घर अचानक बहुत शांत हो गया? ढूँढने निकलेंगी तो उसे दरवाज़े के पीछे सपनों में खोया पाएँगी। डरिए मत, वह शोर से दूर होकर खुद को रीसेट कर रहा है, उसे यह समय दीजिए।', title_id = 'Panik karena rumah hening 🚪', body_id = 'Rumah tiba-tiba sangat hening? Anda akan mencarinya dan menemukannya di balik pintu sedang melamun. Jangan takut, ia sedang menjauh dari kebisingan dan me-reset dirinya, berikan waktu ini untuknya.', title_ja = '家が静かすぎてドキッ 🚪', body_ja = '家が急にしーんとした？探しに行くと、ドアのかげで空想にふけっている姿が見つかります。心配しないで。騒音から離れて自分をリセットしているんです。この時間を認めてあげて。', title_ko = '집 안이 너무 조용할 때의 공포 🚪', body_ko = '집이 갑자기 너무 조용해졌나요? 찾아 나서 보면 문 뒤에서 멍하니 공상에 빠진 아이를 발견할 거예요. 걱정 마세요, 소음에서 벗어나 스스로를 리셋하는 중이에요. 그 시간을 허락해 주세요.', title_nl = 'Paniek om de stilte in huis 🚪', body_nl = 'Is het ineens heel stil in huis? Ga op zoek en je vindt hem dromerig achter een deur. Schrik niet, hij trekt zich terug van het lawaai om zichzelf te resetten. Gun hem die tijd.', title_pl = 'Panika, gdy w domu cicho 🚪', body_pl = 'W domu nagle zrobiło się bardzo cicho? Ruszysz na poszukiwania i znajdziesz go rozmarzonego za drzwiami. Nie bój się, oddala się od hałasu i resetuje, daj mu ten czas.', title_pt = 'O pânico do silêncio em casa 🚪', body_pt = 'A casa ficou de repente muito silenciosa? Vá procurá-lo e vai encontrá-lo atrás de uma porta, a sonhar acordado. Não se assuste: está a afastar-se do barulho para se reiniciar, dê-lhe este tempo.', title_sv = 'Panik över tystnaden hemma 🚪', body_sv = 'Har det plötsligt blivit väldigt tyst hemma? Du går och letar och hittar barnet drömmande bakom en dörr. Var inte rädd, hen drar sig undan oljudet och startar om sig själv, ge hen den tiden.', title_vi = 'Hoảng vì nhà bỗng im lặng 🚪', body_vi = 'Nhà bỗng im ắng quá? Đi tìm thử, mẹ sẽ thấy bé đang mơ mộng sau cánh cửa. Đừng lo, bé đang tránh xa tiếng ồn để "khởi động lại" bản thân, hãy cho bé khoảng thời gian này.', title_zh = '家里太安静的恐慌 🚪', body_zh = '家里突然变得特别安静？去找一找，会发现宝宝正在门后发呆。别担心，宝宝在远离吵闹、给自己“重启”，给宝宝这点时间吧。' WHERE id = '895f4c44-bb71-4d9f-917c-8dc75b779cc8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de la galleta rota 🍪', body_es = '¿Se ha armado una buena porque la galletita salada se ha partido en dos? No la puedes volver a pegar. Dile «Mira, ahora hay dos: una para mí y otra para ti» y pon en marcha las matemáticas y el compartir.', title_fr = 'Le drame du biscuit cassé 🍪', body_fr = 'C''est l''apocalypse parce que le biscuit s''est cassé en deux ? Vous ne pourrez pas le recoller. Dites « Regarde, maintenant il y en a deux, un pour moi, un pour toi » et faites entrer en jeu les maths et le partage.', title_hi = 'बिस्कुट टूटने का दुख 🍪', body_hi = 'क्रैकर दो टुकड़ों में टूट गया, इसलिए हंगामा मच गया? आप उसे जोड़ नहीं सकतीं। ‘देखो, अब दो हो गए, एक मेरा, एक तुम्हारा’ कहकर गणित और बाँटना दोनों चालू कर दीजिए।', title_id = 'Drama biskuit patah 🍪', body_id = 'Kiamat terjadi karena biskuitnya patah jadi dua? Anda tidak bisa merekatkannya lagi. Katakan ''Lihat, sekarang jadi dua, satu untuk Mama, satu untukmu'' dan aktifkan matematika serta berbagi.', title_ja = 'クラッカーがわれた事件 🍪', body_ja = 'クラッカーがふたつにわれて大さわぎ？くっつけることはできません。「見て、ふたつになったよ、ひとつはママに、ひとつはあなたに」と言って、算数と分け合う心を働かせましょう。', title_ko = '크래커가 부러졌어 🍪', body_ko = '크래커가 두 조각 났다고 난리가 났나요? 다시 붙일 수는 없죠. ''봐, 이제 두 개가 됐어, 하나는 엄마 거, 하나는 네 거'' 하며 수학과 나눔을 시작해 보세요.', title_nl = 'Het drama van de gebroken cracker 🍪', body_nl = 'Breekt de hel los omdat de cracker in tweeën brak? Je kunt hem niet weer aan elkaar plakken. Zeg ''Kijk, nu zijn het er twee, één voor mij en één voor jou'' en zet rekenen en delen aan het werk.', title_pl = 'Dramat połamanego krakersa 🍪', body_pl = 'Wybuchła awantura, bo krakers przełamał się na pół? Nie skleisz go z powrotem. Powiedz: „Zobacz, teraz są dwa, jeden dla mnie, jeden dla ciebie” i uruchom matematykę oraz dzielenie się.', title_pt = 'O drama da bolacha partida 🍪', body_pt = 'Caiu o Carmo e a Trindade porque a bolacha se partiu ao meio? Não a consegue colar outra vez. Diga "Olha, agora são duas: uma para mim, outra para ti" e ponha em ação a matemática e a partilha.', title_sv = 'Sorgen över det trasiga kexet 🍪', body_sv = 'Utbryter världens undergång för att kexet gick av på mitten? Du kan inte limma ihop det. Säg ”Titta, nu blev det två, en till mig och en till dig” och sätt i gång både matten och delandet.', title_vi = 'Nỗi buồn bánh quy giòn bị gãy 🍪', body_vi = 'Cả nhà như "tận thế" chỉ vì chiếc bánh quy giòn bị gãy đôi? Mẹ không thể dán nó lại được. Hãy nói "Nhìn này, giờ thành hai cái rồi, một cho mẹ, một cho con" để khởi động cả toán học lẫn sự chia sẻ.', title_zh = '饼干断了的烦恼 🍪', body_zh = '饼干断成两半，就闹翻天了？你没法把它粘回去。说“你看，现在有两块了，一块给我，一块给你”，顺便练练数学和分享。' WHERE id = 'fceb9d37-669a-42ac-ae17-36b46f1fa546' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El helado se quedó en el sueño 🍦', body_es = '¿Estaba comiendo helado en sueños y se ha enfadado contigo porque lo has despertado? El sueño y la realidad se le han mezclado. Abraza esa carita enfadada y ríete: tardará 2 minutos en volver a la realidad.', title_fr = 'La glace est restée dans le rêve 🍦', body_fr = 'Il mangeait une glace dans son rêve et vous en veut de l''avoir réveillé ? Le rêve et la réalité se mélangent. Serrez ce petit visage fâché dans vos bras et riez, il lui faudra 2 minutes pour revenir à la réalité.', title_hi = 'आइसक्रीम सपने में रह गई 🍦', body_hi = 'सपने में आइसक्रीम खा रहा था और आपने जगा दिया, इसलिए आपसे नाराज़ है? सपना और असलियत आपस में मिल गए हैं। उस गुस्से वाले चेहरे को गले लगाकर हँसिए, असलियत में लौटने में उसे 2 मिनट लगेंगे।', title_id = 'Es krimnya tertinggal di mimpi 🍦', body_id = 'Ia marah karena Anda membangunkannya saat ia sedang makan es krim dalam mimpi? Mimpi dan kenyataan sedang bercampur. Peluk wajah cemberutnya itu dan tertawalah, ia butuh 2 menit untuk kembali ke kenyataan.', title_ja = 'アイスは夢の中に 🍦', body_ja = '夢の中でアイスを食べていたのに、起こしたから怒っている？夢と現実がまざっているんです。その怒った顔を抱きしめて笑ってあげて。現実に戻るまで2分ほどです。', title_ko = '꿈속에 두고 온 아이스크림 🍦', body_ko = '꿈에서 아이스크림을 먹고 있었는데 깨웠다고 화를 내나요? 꿈과 현실이 뒤섞인 거예요. 그 화난 얼굴을 안아 주며 웃어 주세요, 현실로 돌아오는 데 2분이면 돼요.', title_nl = 'Het ijsje bleef in de droom 🍦', body_nl = 'At hij in zijn droom een ijsje en is hij boos op je omdat je hem wakker maakte? Droom en werkelijkheid lopen door elkaar. Knuffel dat boze gezichtje en lach, over 2 minuten is hij terug in de werkelijkheid.', title_pl = 'Lody zostały we śnie 🍦', body_pl = 'Złości się na ciebie, bo obudziłaś go, gdy we śnie jadł lody? Sen i rzeczywistość mu się pomieszały. Przytul tę złą minkę i się uśmiechnij, powrót do rzeczywistości zajmie mu 2 minuty.', title_pt = 'O gelado ficou no sonho 🍦', body_pt = 'Estava a comer um gelado no sonho e zangou-se consigo por o ter acordado? O sonho e a realidade misturaram-se. Abrace aquela cara zangada e ria-se: vai levar 2 minutos a voltar à realidade.', title_sv = 'Glassen blev kvar i drömmen 🍦', body_sv = 'Åt barnet glass i drömmen och blev arg på dig för att du väckte hen? Dröm och verklighet har flutit ihop. Krama det arga ansiktet och skratta, det tar 2 minuter att komma tillbaka till verkligheten.', title_vi = 'Que kem còn trong giấc mơ 🍦', body_vi = 'Bé đang ăn kem trong mơ và giận mẹ vì bị đánh thức? Giấc mơ và thực tại đang lẫn vào nhau. Hãy ôm lấy khuôn mặt giận dỗi ấy và cười, bé sẽ mất 2 phút để quay về thực tại.', title_zh = '冰淇淋留在梦里了 🍦', body_zh = '梦里正在吃冰淇淋，你把宝宝叫醒了，宝宝就冲你发火？梦和现实混在一起了。抱住那张生气的小脸笑一笑，回到现实只需要2分钟。' WHERE id = '7871e777-44f4-425d-a10e-dda0547ccfc1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El color de la botella de agua 🚰', body_es = '¿De noche pide agua, pero no en el vaso rojo? No busques lógica ni le des lecciones a medianoche. Cámbiale el vaso enseguida y guarda tu energía para la mañana y la paz.', title_fr = 'La couleur de la gourde 🚰', body_fr = 'Il veut de l''eau la nuit, mais pas dans le verre rouge ? Ne cherchez pas de logique au milieu de la nuit pour lui faire la leçon. Changez aussitôt de verre et gardez votre énergie pour le matin et la paix.', title_hi = 'पानी की बोतल का रंग 🚰', body_hi = 'रात को पानी चाहिए, पर लाल गिलास में नहीं? आधी रात तर्क ढूँढकर उसे पाठ मत पढ़ाइए। फ़ौरन गिलास बदल दीजिए, अपनी ऊर्जा सुबह और शांति के लिए बचाइए।', title_id = 'Warna botol minum 🚰', body_id = 'Malam-malam ia minta air, tapi tidak mau gelas merah? Tengah malam bukan waktunya mencari logika dan memberi pelajaran. Segera ganti gelasnya, simpan energi Anda untuk pagi dan kedamaian.', title_ja = 'お水のコップの色 🚰', body_ja = '夜中にお水がほしいけれど、赤いコップはいや？真夜中に理屈を探して説教しないで。すぐにコップを替えて、エネルギーは朝と平和のためにとっておきましょう。', title_ko = '물컵 색깔 문제 🚰', body_ko = '밤에 물을 달라는데 빨간 컵은 싫대요? 한밤중에 논리를 찾으며 훈계하지 마세요. 바로 컵을 바꾸고, 에너지는 아침과 평화를 위해 아껴 두세요.', title_nl = 'De kleur van de drinkfles 🚰', body_nl = 'Wil hij ''s nachts water, maar niet in de rode beker? Zoek midden in de nacht geen logica en ga geen les geven. Verwissel meteen de beker en bewaar je energie voor de ochtend en de vrede.', title_pl = 'Kolor butelki na wodę 🚰', body_pl = 'W nocy chce wody, ale nie w czerwonym kubku? Nie szukaj w środku nocy logiki i nie dawaj lekcji. Od razu zmień kubek, a energię zachowaj na rano i na spokój.', title_pt = 'A cor da garrafa de água 🚰', body_pt = 'Quer água de noite, mas não no copo vermelho? A meio da noite não procure lógica nem dê lições. Troque logo o copo e guarde a energia para a manhã e para a paz.', title_sv = 'Vattenflaskans färg 🚰', body_sv = 'Vill barnet ha vatten på natten, men inte i det röda glaset? Leta inte efter logik och håll inga lektioner mitt i natten. Byt glas direkt och spara energin till morgonen och freden.', title_vi = 'Màu của bình nước 🚰', body_vi = 'Nửa đêm bé đòi nước, nhưng không phải bằng cốc đỏ? Giữa đêm đừng tìm logic hay giảng giải cho bé. Đổi cốc ngay, giữ sức cho buổi sáng và cho hòa bình.', title_zh = '水瓶的颜色 🚰', body_zh = '半夜要喝水，却不要红杯子？半夜别讲道理、别上课。马上换个杯子，把精力留给早晨和和平。' WHERE id = '94d22bcb-5e09-49a0-bea6-432b56a92308' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La obsesión de «tengo una piedra en el zapato» 👟', body_es = '¡Te hace quitarle el zapato y mirarlo 10 veces y no hay ninguna piedra! ¿Te suena? Haz como que coges una motita negra, dile «¡Mira, la encontré, estamos salvados!» y seguid con el paseo.', title_fr = 'La psychose du « J''ai un caillou dans ma chaussure » 👟', body_fr = 'Il vous fait enlever et vérifier sa chaussure 10 fois, et il n''y a pas de caillou ! Ce scénario vous dit quelque chose ? Faites semblant de prendre un petit grain noir et dites « Regarde, je l''ai trouvé, on est sauvés ! », puis continuez la promenade.', title_hi = '‘मेरे जूते में पत्थर है’ वाला वहम 👟', body_hi = '10 बार जूता उतरवाकर दिखवाता है, पत्थर है ही नहीं! यह नज़ारा जाना-पहचाना लगा? दिखावे के लिए हाथ में एक काला सा कण उठाइए, ‘देखो, मिल गया, बच गए’ कहिए और सैर जारी रखिए।', title_id = 'Kepanikan ''ada batu di sepatuku'' 👟', body_id = 'Ia menyuruh Anda melepas dan memeriksa sepatunya 10 kali, padahal tidak ada batu! Skenario ini terdengar akrab? Pura-pura ambil butiran hitam kecil, katakan ''Lihat, sudah ketemu, kita selamat'' dan lanjutkan jalan-jalan.', title_ja = 'くつの中に石が入ってる問題 👟', body_ja = 'くつを10回もぬがせて確かめさせるのに、石はない！この場面、見覚えがありますか？小さな黒いつぶを手にとったふりをして「ほら、見つけた、助かったね」と言い、お散歩を続けましょう。', title_ko = '''신발에 돌 들어갔어'' 소동 👟', body_ko = '신발을 열 번이나 벗겨 확인하게 하는데 돌은 없나요? 익숙한 장면이죠? 손에 작은 검은 알갱이를 쥔 척하고 ''봐, 찾았다, 이제 살았다!'' 하며 산책을 이어 가세요.', title_nl = 'De ''er zit een steentje in mijn schoen''-psychose 👟', body_nl = 'Moet je zijn schoen 10 keer uittrekken om te kijken, maar er zit geen steentje in! Klinkt bekend? Doe alsof je een zwart korreltje pakt, zeg ''Kijk, gevonden, we zijn gered'' en wandel verder.', title_pl = 'Obsesja „mam kamyk w bucie” 👟', body_pl = 'Każe ci 10 razy zdejmować i sprawdzać but, a kamyka nie ma! Znasz ten scenariusz? Udawaj, że wyjmujesz małe czarne ziarenko, powiedz: „Zobacz, znalazłam, uratowani” i kontynuujcie spacer.', title_pt = 'A obsessão da "pedra no sapato" 👟', body_pt = 'Obriga-a a tirar-lhe o sapato 10 vezes para ver, e não há pedra nenhuma! Este cenário é-lhe familiar? Finja que apanha um grãozinho preto, diga "Olha, encontrei, estamos salvos" e continuem o passeio.', title_sv = 'Psykosen ”Det är en sten i skon” 👟', body_sv = 'Får barnet dig att ta av och kolla skon 10 gånger, och det finns ingen sten! Känns scenariot bekant? Låtsas ta upp ett litet svart korn, säg ”Titta, jag hittade den, vi är räddade” och fortsätt promenaden.', title_vi = 'Nỗi ám ảnh "có sỏi trong giày" 👟', body_vi = 'Bé bắt mẹ cởi giày ra kiểm tra 10 lần, mà chẳng có viên sỏi nào! Kịch bản quen thuộc chứ? Hãy giả vờ nhặt một hạt đen nhỏ: "Nhìn này, mẹ tìm thấy rồi, mình được cứu rồi" và tiếp tục đi dạo.', title_zh = '“鞋里有石头”的执念 👟', body_zh = '让你把鞋脱下来检查了10次，根本没有石头！这个场景眼熟吗？假装从鞋里拿出一粒小黑点，说“看，找到了，得救了”，然后继续散步。' WHERE id = 'c160b0b4-c39a-4e5d-bbc5-111f29e33385' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rebelión del baño 🛀', body_es = '¿No quiere meterse en el agua? Echa dentro recipientes de colores, incluso utensilios de cocina de plástico. De repente el agua pasará de ser un sitio que da miedo a un centro de diversión.', title_fr = 'La révolte du bain 🛀', body_fr = 'Il ne veut pas entrer dans l''eau ? Mettez-y des récipients de différentes couleurs, et même des ustensiles de cuisine en plastique. L''eau passera soudain d''endroit effrayant à centre de loisirs.', title_hi = 'नहाने के खिलाफ़ बगावत 🛀', body_hi = 'पानी में नहीं जाना चाहता? उसमें अलग-अलग रंग के बर्तन, यहाँ तक कि प्लास्टिक के रसोई के सामान डाल दीजिए। पानी अचानक डरावनी जगह से मनोरंजन का केंद्र बन जाएगा।', title_id = 'Pemberontakan mandi 🛀', body_id = 'Ia tidak mau masuk ke air? Masukkan wadah-wadah berwarna, bahkan peralatan dapur plastik ke dalamnya. Air tiba-tiba akan berubah dari tempat menakutkan menjadi pusat hiburan.', title_ja = 'お風呂いやいや反乱 🛀', body_ja = 'お湯に入りたがらない？いろいろな色の容器や、プラスチックのキッチンおもちゃを入れてみましょう。お風呂が急に、こわい場所から楽しいアミューズメントに変わります。', title_ko = '목욕 거부 반란 🛀', body_ko = '물에 들어가기 싫어하나요? 여러 색깔의 그릇이나 플라스틱 주방 놀이 도구를 넣어 주세요. 물이 갑자기 무서운 곳에서 놀이 공간으로 바뀔 거예요.', title_nl = 'Badopstand 🛀', body_nl = 'Wil hij niet in het water? Gooi er bakjes in verschillende kleuren in, of zelfs plastic keukenspullen. Het water verandert ineens van een enge plek in een pretpark.', title_pl = 'Bunt przy kąpieli 🛀', body_pl = 'Nie chce wejść do wody? Wrzuć do wanny kolorowe pojemniki, a nawet plastikowe przybory kuchenne. Woda nagle zmieni się ze strasznego miejsca w centrum rozrywki.', title_pt = 'A revolta do banho 🛀', body_pt = 'Não quer entrar na água? Ponha lá dentro copos de cores diferentes e até utensílios de cozinha de plástico. De repente, a água deixa de ser um sítio assustador e passa a ser um centro de diversão.', title_sv = 'Badrevolten 🛀', body_sv = 'Vill barnet inte gå i vattnet? Lägg i olikfärgade skålar och till och med plastköksgrejer. Vattnet förvandlas plötsligt från en läskig plats till ett nöjescenter.', title_vi = 'Cuộc nổi loạn giờ tắm 🛀', body_vi = 'Bé không chịu vào nước? Hãy thả vào bồn những chiếc cốc nhiều màu, thậm chí đồ dùng nhà bếp bằng nhựa. Bồn nước sẽ bỗng nhiên biến từ nơi đáng sợ thành trung tâm vui chơi.', title_zh = '洗澡大反抗 🛀', body_zh = '不肯下水？往里面放些不同颜色的容器，甚至塑料厨房玩具。水会一下子从可怕的地方变成游乐中心。' WHERE id = '56bcf6ad-42a4-41b4-a775-ca5dbc61f766' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Soy papá 👔', body_es = '¿Por la mañana se pone los zapatos grandes de papá y quiere ir a trabajar? ¡Sin prisas! Acompáñalo hasta la puerta: en cuanto vea el ascensor, volverá riéndose.', title_fr = 'Je suis papa 👔', body_fr = 'Le matin, il met les grandes chaussures de papa et veut aller au travail ? Pas de précipitation ! Accompagnez-le jusqu''à la porte : dès qu''il verra l''ascenseur, il reviendra en riant.', title_hi = 'मैं पापा हूँ 👔', body_hi = 'सुबह पापा के बड़े जूते पहनकर काम पर जाना चाहता है? जल्दी मत कीजिए! दरवाज़े तक विदा कीजिए, लिफ़्ट देखते ही हँसते हुए लौट आएगा।', title_id = 'Aku Ayah 👔', body_id = 'Pagi-pagi ia memakai sepatu besar ayahnya dan ingin berangkat kerja? Jangan buru-buru! Antar ia sampai pintu, begitu melihat lift ia akan kembali sambil tertawa.', title_ja = 'パパになるの 👔', body_ja = '朝、パパの大きなくつをはいて仕事に行きたがる？あわてないで！ドアまで見送ってあげれば、エレベーターを見たとたん笑って戻ってきますよ。', title_ko = '나는 아빠야 👔', body_ko = '아침에 아빠의 큰 신발을 신고 출근하겠다고 하나요? 서두르지 마세요! 문 앞까지 배웅해 주면, 엘리베이터를 보자마자 웃으며 돌아올 거예요.', title_nl = 'Ik ben papa 👔', body_nl = 'Trekt hij ''s ochtends papa''s grote schoenen aan en wil hij naar zijn werk? Geen haast! Breng hem tot aan de deur, zodra hij de lift ziet komt hij lachend terug.', title_pl = 'Jestem tatą 👔', body_pl = 'Rano założył wielkie buty taty i chce iść do pracy? Nie spiesz się! Odprowadź go do drzwi, a gdy tylko zobaczy windę, ze śmiechem wróci.', title_pt = 'Eu sou o pai 👔', body_pt = 'De manhã calça os sapatos grandes do pai e quer ir trabalhar? Não tenha pressa! Acompanhe-o até à porta: mal veja o elevador, volta para trás a rir.', title_sv = 'Jag är pappa 👔', body_sv = 'Har barnet tagit på sig pappas stora skor på morgonen och vill gå till jobbet? Ingen brådska! Följ med till dörren, när hen ser hissen kommer hen tillbaka skrattande.', title_vi = 'Con là bố 👔', body_vi = 'Sáng nay bé xỏ đôi giày to của bố và đòi đi làm? Đừng vội! Cứ tiễn bé ra cửa, vừa thấy thang máy là bé sẽ cười khúc khích quay lại.', title_zh = '我是爸爸 👔', body_zh = '早上穿上爸爸的大鞋子，要去上班？别着急！送到门口，一看到电梯，宝宝就会笑着回来。' WHERE id = '7f7bb774-fd67-46a5-93fe-c0a784ba9885' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por los 0 decibelios 🤫', body_es = '¡Por fin se ha dormido! Abre el Medidor de sonido en la app y mira ese silencio absoluto que cae al fondo de la pantalla. Este silencio visual le dará a tu cerebro cansado un auténtico masaje de spa.', title_fr = 'L''amour des 0 décibel 🤫', body_fr = 'Il dort enfin ! Ouvrez le Sonomètre dans l''application et regardez ce calme absolu tomber au plus bas de l''écran. Ce silence visuel massera votre cerveau fatigué comme un vrai spa.', title_hi = '0 डेसिबल से प्यार 🤫', body_hi = 'आखिरकार सो गया! ऐप में साउंड मीटर खोलिए और स्क्रीन पर सबसे नीचे तक गिरी उस पूरी खामोशी को देखिए। यह दिखती हुई शांति आपके थके दिमाग की असली स्पा जैसी मालिश करेगी।', title_id = 'Cinta 0 desibel 🤫', body_id = 'Akhirnya ia tidur! Buka Pengukur Suara di aplikasi dan saksikan keheningan mutlak yang jatuh ke dasar layar. Keheningan visual ini akan memijat otak Anda yang lelah seperti spa sungguhan.', title_ja = '0デシベルが好き 🤫', body_ja = 'やっと寝た！アプリで「サウンドメーター」を開いて、画面の下まで下がる完全な静けさを眺めましょう。この目で見る静けさが、疲れた頭を本物のスパのようにマッサージしてくれます。', title_ko = '0 데시벨 사랑 🤫', body_ko = '드디어 잠들었어요! 앱에서 소음 측정기를 열고 화면 바닥까지 떨어진 완벽한 고요를 바라보세요. 이 눈에 보이는 정적이 지친 머리를 진짜 스파처럼 마사지해 줄 거예요.', title_nl = 'Verliefd op 0 decibel 🤫', body_nl = 'Eindelijk slaapt hij! Open de Geluidsmeter in de app en kijk naar die absolute stilte onderaan het scherm. Deze visuele stilte masseert je vermoeide brein als een echte spa.', title_pl = 'Miłość do 0 decybeli 🤫', body_pl = 'Wreszcie zasnął! Otwórz w aplikacji Miernik dźwięku i patrz na absolutną ciszę na samym dole ekranu. Ta wizualna cisza zrobi twojemu zmęczonemu mózgowi masaż jak w prawdziwym spa.', title_pt = 'A paixão pelos 0 decibéis 🤫', body_pt = 'Finalmente adormeceu! Abra o Medidor de Som na app e veja aquele silêncio absoluto cair até ao fundo do ecrã. Este silêncio visual vai massajar o seu cérebro cansado como um verdadeiro spa.', title_sv = 'Kärleken till 0 decibel 🤫', body_sv = 'Äntligen sover barnet! Öppna Ljudmätaren i appen och se den totala tystnaden sjunka till botten av skärmen. Den visuella tystnaden masserar din trötta hjärna som ett riktigt spa.', title_vi = 'Tình yêu với 0 decibel 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Hãy mở Đo âm thanh trong ứng dụng và ngắm sự yên tĩnh tuyệt đối chạm đáy màn hình. Sự tĩnh lặng nhìn thấy được này sẽ mát-xa bộ não mệt mỏi của mẹ như một buổi spa thực thụ.', title_zh = '爱上0分贝 🤫', body_zh = '终于睡着了！打开应用里的分贝仪，看着屏幕跌到底的那份绝对安静。这种看得见的安静，会像真正的水疗一样按摩你疲惫的大脑。' WHERE id = 'dbd02f3e-2d56-4baa-bc3c-93886c747027' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El árbol ha tirado su hoja 🍂', body_es = '¿Se ha enfadado con el árbol por la hoja del suelo y lo está regañando? ¡Tiene un vínculo tan puro y cómico con la naturaleza!', title_fr = 'L''arbre a jeté sa feuille 🍂', body_fr = 'Il boude l''arbre et le gronde à cause d''une feuille tombée par terre ? Son lien avec la nature est si pur et si drôle !', title_hi = 'पेड़ ने अपना पत्ता गिरा दिया 🍂', body_hi = 'ज़मीन पर पड़े पत्ते की वजह से पेड़ से रूठकर उसे डाँट रहा है? प्रकृति से उसका रिश्ता कितना सच्चा और मज़ेदार है!', title_id = 'Pohon menjatuhkan daunnya 🍂', body_id = 'Ia ngambek pada pohon dan memarahinya karena daun di tanah? Hubungannya dengan alam begitu murni dan lucu!', title_ja = '木が葉っぱを落とした 🍂', body_ja = '地面の葉っぱのことで木にすねて、叱っている？自然とのつながりが、なんてピュアでおもしろいんでしょう！', title_ko = '나무가 잎을 떨어뜨렸어 🍂', body_ko = '바닥에 떨어진 잎 때문에 나무에게 토라져 혼내나요? 자연과 이렇게 순수하고 웃긴 교감을 하다니요!', title_nl = 'De boom liet zijn blad vallen 🍂', body_nl = 'Is hij boos op een boom en moppert hij erop vanwege een blaadje op de grond? Wat heeft hij een pure en grappige band met de natuur!', title_pl = 'Drzewo zrzuciło liść 🍂', body_pl = 'Obraził się na drzewo z powodu liścia na ziemi i je beszta? Ma z naturą tak czystą i zabawną więź!', title_pt = 'A árvore deixou cair a folha 🍂', body_pt = 'Amuou com a árvore por causa de uma folha no chão e está a ralhar-lhe? Tem uma ligação tão pura e cómica com a natureza!', title_sv = 'Trädet tappade sitt löv 🍂', body_sv = 'Är barnet sur på trädet för lövet på marken och skäller på det? Barnets band till naturen är så rent och roligt!', title_vi = 'Cây làm rơi lá 🍂', body_vi = 'Bé giận cây và mắng nó vì chiếc lá rơi dưới đất? Mối liên kết của bé với thiên nhiên thật trong sáng và hài hước!', title_zh = '树把叶子扔了 🍂', body_zh = '因为地上的落叶，和树闹别扭，还批评它？宝宝和大自然的联系是那么纯真又好笑！' WHERE id = '1c6686dd-4008-4750-acaf-4155c3330cdd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi sombra va delante de mí 👻', body_es = '¿Llora en la calle porque su sombra va delante de él? Cógelo en brazos y dile: «Mira, las sombras se han juntado». En lugar de explicarle física, dale simplemente seguridad.', title_fr = 'Mon ombre passe devant moi 👻', body_fr = 'Il pleure dans la rue parce que son ombre est devant lui ? Prenez-le dans vos bras et dites « Regarde, les ombres se sont rejointes ». Au lieu d''expliquer la physique, donnez-lui simplement de la sécurité.', title_hi = 'मेरी परछाईं मुझसे आगे चल रही है 👻', body_hi = 'उसकी परछाईं उससे आगे है, इसलिए सड़क पर रो रहा है? गोद में उठाइए और कहिए, ‘देखो, परछाइयाँ मिल गईं।’ भौतिकी समझाने के बजाय उसे बस भरोसा दीजिए।', title_id = 'Bayanganku jalan duluan 👻', body_id = 'Ia menangis di jalan karena bayangannya ada di depannya? Gendong ia dan katakan ''Lihat, bayangan kita jadi satu''. Daripada menjelaskan fisika, cukup beri ia rasa aman.', title_ja = '影がぼくより先に行く 👻', body_ja = '影が自分より前にあるからと、道で泣いている？抱き上げて「見て、影がくっついたよ」と言いましょう。物理を説明するより、ただ安心させてあげて。', title_ko = '그림자가 나보다 앞서가 👻', body_ko = '그림자가 자기보다 앞서간다고 길에서 우나요? 안아 올리며 ''봐, 그림자가 하나가 됐어'' 하고 말해 주세요. 물리를 설명하는 대신 그냥 안심시켜 주세요.', title_nl = 'Mijn schaduw loopt voor me uit 👻', body_nl = 'Huilt hij op straat omdat zijn schaduw voor hem uit loopt? Pak hem op en zeg: ''Kijk, onze schaduwen zijn samen.'' Leg geen natuurkunde uit, geef hem gewoon een veilig gevoel.', title_pl = 'Mój cień idzie przede mną 👻', body_pl = 'Płacze na ulicy, bo cień idzie przed nim? Weź go na ręce i powiedz: „Zobacz, cienie się połączyły”. Zamiast tłumaczyć fizykę, po prostu daj mu poczucie bezpieczeństwa.', title_pt = 'A minha sombra vai à minha frente 👻', body_pt = 'Chora na rua porque a sombra vai à frente dele? Pegue-lhe ao colo e diga "Olha, as sombras juntaram-se". Em vez de explicar física, dê-lhe apenas segurança.', title_sv = 'Min skugga går före mig 👻', body_sv = 'Gråter barnet på gatan för att skuggan går före hen? Ta upp barnet i famnen och säg ”Titta, skuggorna blev en”. I stället för att förklara fysiken, ge bara trygghet.', title_vi = 'Cái bóng đi trước con 👻', body_vi = 'Bé khóc giữa đường vì cái bóng đi trước mình? Hãy bế bé lên và nói: "Nhìn này, hai cái bóng đã nhập làm một rồi." Thay vì giải thích vật lý, chỉ cần cho bé cảm giác an toàn.', title_zh = '我的影子走在我前面 👻', body_zh = '因为影子跑到了自己前面，在街上哭了？把宝宝抱起来，说：“看，影子合在一起了。”与其解释物理，不如给宝宝安全感。' WHERE id = '806ceb98-90c4-4de6-a42b-37c72e8d03ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las bromas raras de papá 🤡', body_es = 'No te enfades porque papá lo haya despertado a carcajadas a la hora de dormir. Esas risas alegres reiniciarán del todo el estrés que el peque ha acumulado durante el día. Deja que hagan ruido.', title_fr = 'Les blagues bizarres de papa 🤡', body_fr = 'Ne vous fâchez pas parce que papa l''a fait rire et l''a réveillé à l''heure du coucher. Ces éclats de rire joyeux remettront complètement à zéro le stress accumulé dans la journée, laissez-les faire du bruit.', title_hi = 'पापा के अजीब मज़ाक 🤡', body_hi = 'सोने के समय पापा ने उसे हँसा-हँसाकर जगा दिया, इस पर गुस्सा मत कीजिए। वे खुशी भरे ठहाके बच्चे का दिनभर जमा तनाव पूरी तरह मिटा देंगे, उन्हें शोर मचाने दीजिए।', title_id = 'Lelucon aneh Ayah 🤡', body_id = 'Jangan kesal karena Ayah membuatnya tertawa dan terjaga di jam tidur. Tawa riang itu akan benar-benar mengosongkan stres anak yang menumpuk seharian, biarkan mereka berisik.', title_ja = 'パパのへんな冗談 🤡', body_ja = '寝る時間にパパが笑わせて目をさまさせても、怒らないで。その楽しい笑い声が、一日たまったストレスをすっかりリセットしてくれます。にぎやかにさせてあげましょう。', title_ko = '아빠의 엉뚱한 장난 🤡', body_ko = '잠잘 시간에 아빠가 웃겨서 아이 잠을 깨웠다고 화내지 마세요. 그 신나는 웃음이 하루 동안 쌓인 아이의 스트레스를 완전히 비워 줄 거예요. 실컷 떠들게 두세요.', title_nl = 'Papa''s gekke grapjes 🤡', body_nl = 'Word niet boos als papa hem bij bedtijd aan het lachen maakt en wakker houdt. Dat vrolijke geschater zet alle stress die hij de hele dag heeft opgebouwd helemaal op nul, laat ze maar lawaai maken.', title_pl = 'Dziwne żarty taty 🤡', body_pl = 'Nie złość się, że przed snem tata go rozśmieszył i rozbudził. Ten radosny śmiech całkiem wyzeruje stres nagromadzony przez cały dzień, niech sobie pohałasują.', title_pt = 'As piadas estranhas do pai 🤡', body_pt = 'Não se zangue se o pai o fez rir e o despertou na hora de dormir. Essas gargalhadas alegres vão pôr a zero todo o stress acumulado durante o dia. Deixe-os fazer barulho.', title_sv = 'Pappas konstiga skämt 🤡', body_sv = 'Bli inte arg för att pappa fick barnet att skratta och vakna till vid läggdags. De glada skratten nollställer helt den stress barnet samlat på sig under dagen, låt dem väsnas.', title_vi = 'Những trò đùa kỳ quặc của bố 🤡', body_vi = 'Đừng bực khi bố chọc bé cười đến tỉnh ngủ lúc đi ngủ. Những tràng cười vui vẻ ấy sẽ xóa sạch căng thẳng tích tụ cả ngày của bé, cứ để hai bố con ồn ào.', title_zh = '爸爸的奇怪笑话 🤡', body_zh = '睡觉时间爸爸把宝宝逗笑、弄醒了，别生气。那些欢快的笑声会把宝宝一整天积攒的压力彻底清零，就让他们闹一会儿吧。' WHERE id = 'a0789257-db81-493e-9643-abeb1d193c59' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que no llore el huevo 🍳', body_es = '¿Le ha dado pena el huevo al romperlo y no se lo come? Su empatía no tiene límites. Salva la situación con una historia tierna como «Ahora va a vivir en tus músculos».', title_fr = 'Que l''œuf ne pleure pas 🍳', body_fr = 'Il a eu pitié de l''œuf quand vous l''avez cassé et refuse de le manger ? Son empathie est sans limites. Sauvez la situation avec de douces inventions comme « Maintenant, il va vivre dans tes muscles ».', title_hi = 'अंडा रोए नहीं 🍳', body_hi = 'अंडा तोड़ते समय उसे अंडे पर तरस आ गया और अब खा नहीं रहा? उसकी हमदर्दी की कोई सीमा नहीं। ‘अब यह तुम्हारी मांसपेशियों में रहेगा’ जैसी प्यारी गढ़ी बातों से हालात संभालिए।', title_id = 'Jangan biarkan telurnya menangis 🍳', body_id = 'Ia kasihan pada telur saat Anda memecahkannya dan tidak mau memakannya? Empatinya tak terbatas. Selamatkan keadaan dengan karangan manis seperti ''Sekarang telurnya akan tinggal di ototmu''.', title_ja = '卵さん泣かないで 🍳', body_ja = '卵を割ったら、かわいそうになって食べない？共感力は限りなしです。「卵さんはこれから、あなたの筋肉の中で暮らすんだよ」というかわいいお話で、その場を救いましょう。', title_ko = '달걀이 울면 안 돼 🍳', body_ko = '달걀을 깨뜨리자 불쌍하다며 안 먹나요? 공감 능력에 끝이 없네요. ''이제 달걀은 네 근육 속에서 살게 될 거야'' 같은 귀여운 이야기로 상황을 구해 주세요.', title_nl = 'Het ei mag niet huilen 🍳', body_nl = 'Heeft hij medelijden met het ei als je het breekt en eet hij het niet? Zijn empathie kent geen grenzen. Red de situatie met lieve verzinsels als ''Nu gaat het in jouw spieren wonen.''', title_pl = 'Niech jajko nie płacze 🍳', body_pl = 'Zrobiło mu się żal jajka, gdy je rozbiłaś, i nie chce go jeść? Jego empatia nie zna granic. Uratuj sytuację uroczą bajeczką w stylu „Teraz zamieszka w twoich mięśniach”.', title_pt = 'Que o ovo não chore 🍳', body_pt = 'Ficou com pena do ovo quando o partiu e não o quer comer? A empatia dele não tem limites. Salve a situação com pequenas invenções doces como "Agora vai viver nos teus músculos".', title_sv = 'Ägget får inte gråta 🍳', body_sv = 'Tyckte barnet synd om ägget när du knäckte det, och vill inte äta? Empatin har inga gränser. Rädda situationen med söta påhitt som ”Nu ska det bo i dina muskler”.', title_vi = 'Đừng để quả trứng khóc 🍳', body_vi = 'Bé thương quả trứng khi mẹ đập vỡ nó và không chịu ăn? Lòng trắc ẩn của bé thật vô bờ. Hãy cứu vãn tình hình bằng những câu chuyện ngọt ngào như "Giờ nó sẽ sống trong cơ bắp của con".', title_zh = '别让鸡蛋哭 🍳', body_zh = '你打鸡蛋时，宝宝心疼鸡蛋，不肯吃了？宝宝的同理心没有边界。用“它现在要住进你的肌肉里啦”这样可爱的小故事化解局面吧。' WHERE id = '0879e029-e767-44f9-917b-506cde86d1a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de los susurros 🤫', body_es = '¿No quiere dormir y sale corriendo? Baja la voz de golpe y susurra muy bajito. Prestará toda su atención para oírte, su cerebro se cansará y en 5 minutos se rendirá al sueño.', title_fr = 'Le jeu du chuchotement 🤫', body_fr = 'Il ne veut pas dormir et court partout ? Baissez brusquement la voix, chuchotez très bas. Pour vous entendre, il sera tout ouïe, et son cerveau, fatigué, cédera au sommeil en 5 minutes.', title_hi = 'फुसफुसाहट वाला खेल 🤫', body_hi = 'सोना नहीं चाहता और भाग रहा है? अपनी आवाज़ अचानक धीमी करके बहुत हल्के से फुसफुसाइए। आपको सुनने के लिए वह पूरा ध्यान लगाएगा और दिमाग थककर 5 मिनट में नींद के आगे हार मान लेगा।', title_id = 'Permainan berbisik 🤫', body_id = 'Ia tidak mau tidur dan berlarian? Turunkan suara Anda dengan tajam dan berbisiklah sangat pelan. Ia akan menyimak agar bisa mendengar Anda, otaknya lelah, dan dalam 5 menit ia menyerah pada kantuk.', title_ja = 'ささやきゲーム 🤫', body_ja = '寝たくなくて走りまわる？声をぐっと落として、とても小さな声でささやきましょう。聞きとろうと集中するうちに脳が疲れて、5分で眠りに落ちますよ。', title_ko = '속삭임 놀이 🤫', body_ko = '자기 싫어서 도망 다니나요? 목소리를 확 낮춰 아주 작게 속삭이세요. 엄마 말을 들으려 집중하다 보면 머리가 지쳐 5분 만에 잠에 항복할 거예요.', title_nl = 'Het fluisterspel 🤫', body_nl = 'Wil hij niet slapen en rent hij rond? Ga ineens heel zacht praten en fluister. Om je te horen moet hij goed opletten, zijn brein wordt moe en binnen 5 minuten geeft hij zich over aan de slaap.', title_pl = 'Zabawa w szeptanie 🤫', body_pl = 'Nie chce spać i ucieka? Gwałtownie ścisz głos i szepcz bardzo cicho. Żeby cię usłyszeć, będzie musiał się skupić, jego mózg się zmęczy i za 5 minut podda się snowi.', title_pt = 'O jogo dos sussurros 🤫', body_pt = 'Não quer dormir e foge? Baixe a voz de repente e sussurre muito baixinho. Para a ouvir, vai concentrar-se, o cérebro cansa-se e em 5 minutos rende-se ao sono.', title_sv = 'Viskleken 🤫', body_sv = 'Vill barnet inte sova och springer omkring? Sänk rösten rejält och viska mycket tyst. Barnet blir helt fokuserat för att höra dig, hjärnan blir trött och ger upp för sömnen inom 5 minuter.', title_vi = 'Trò chơi thì thầm 🤫', body_vi = 'Bé không chịu ngủ và chạy lung tung? Hãy đột ngột hạ giọng, thì thầm thật nhỏ. Bé sẽ phải tập trung để nghe mẹ, não mệt đi và 5 phút sau bé sẽ chịu thua giấc ngủ.', title_zh = '悄悄话游戏 🤫', body_zh = '不想睡觉，到处跑？突然压低声音，用很轻很轻的声音说悄悄话。为了听清你，宝宝会全神贯注，大脑累了，5分钟就会睡着。' WHERE id = '7338df78-5f1a-4db5-ae07-ccfc779e153a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo comida roja 🍅', body_es = '¡Hoy es día de manía! ¿Solo quiere cosas rojas? Mira el plan de Nutrición y hoy dale tomate rojo y fresas. Deja que cumpla este curioso deseo, no pelees.', title_fr = 'Seulement des aliments rouges 🍅', body_fr = 'Aujourd''hui, c''est le jour de l''obsession ! Il ne veut que des choses rouges ? Consultez le Plan de nutrition, donnez-lui aujourd''hui des tomates et des fraises bien rouges, laissez ce drôle de désir se réaliser, ne vous battez pas.', title_hi = 'सिर्फ़ लाल खाना 🍅', body_hi = 'आज सनक का दिन है! सिर्फ़ लाल चीज़ें चाहिए? फ़ीडिंग प्लान देखिए, आज उसे लाल टमाटर और स्ट्रॉबेरी दीजिए, उसकी यह अजीब इच्छा पूरी होने दीजिए, लड़िए मत।', title_id = 'Hanya makanan merah 🍅', body_id = 'Hari ini hari obsesi! Ia hanya mau yang berwarna merah? Lihat Rencana Nutrisi, beri ia tomat merah dan stroberi hari ini, biarkan keinginan anehnya terwujud, jangan bertengkar.', title_ja = '赤い食べものだけ 🍅', body_ja = '今日はこだわりの日！赤いものしか食べたくない？「栄養管理ツール」を見て、今日は赤いトマトやいちごをあげましょう。このふしぎな望みをかなえてあげて、戦わないで。', title_ko = '빨간 음식만 먹을래 🍅', body_ko = '오늘은 집착의 날! 빨간 것만 먹겠다고 하나요? 식단 계획을 보고 오늘은 빨간 토마토와 딸기를 주세요. 이 독특한 소원을 들어주고 싸우지 마세요.', title_nl = 'Alleen rood eten 🍅', body_nl = 'Vandaag is het fetisjdag! Wil hij alleen rode dingen? Kijk in het onderdeel Voeding, geef hem vandaag rode tomaten en aardbeien, laat deze rare wens uitkomen en ga de strijd niet aan.', title_pl = 'Tylko czerwone jedzenie 🍅', body_pl = 'Dziś dzień fetyszu! Chce tylko czerwonych rzeczy? Zajrzyj do planu karmienia, daj mu dziś czerwonego pomidora i truskawki, niech to dziwne życzenie się spełni, nie walcz.', title_pt = 'Só comida vermelha 🍅', body_pt = 'Hoje é dia de mania! Só quer coisas vermelhas? Veja o plano de alimentação e dê-lhe hoje tomate vermelho e morangos. Deixe este desejo estranho cumprir-se, não lute.', title_sv = 'Bara röd mat 🍅', body_sv = 'I dag är det besattheternas dag! Vill barnet bara ha röda saker? Titta i matplanen, ge röda tomater och jordgubbar i dag, låt den konstiga önskan gå i uppfyllelse och bråka inte.', title_vi = 'Chỉ ăn đồ màu đỏ 🍅', body_vi = 'Hôm nay là ngày "mê" một thứ! Bé chỉ muốn đồ màu đỏ? Hãy xem Kế hoạch dinh dưỡng, hôm nay cho bé ăn cà chua đỏ, dâu tây, để mong muốn kỳ lạ này thành hiện thực, đừng giằng co.', title_zh = '只吃红色的食物 🍅', body_zh = '今天是“执念日”！只要红色的东西？看看喂养计划，今天就给宝宝吃红番茄、草莓，让这个奇怪的愿望实现吧，别较劲。' WHERE id = '1bf9463f-7457-4983-af0a-2e62627ce701' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi juguete se ha puesto malito 🩺', body_es = '¿Ha ingresado a su osito en el hospital? ¡Ponte tú malita también! Túmbate en el sofá y deja que te haga una revisión de mentira de 10 minutos: con esa excusa descansará tu espalda.', title_fr = 'Mon jouet est tombé malade 🩺', body_fr = 'Il a hospitalisé son nounours ? Tombez malade vous aussi ! Allongez-vous sur le canapé et laissez-le vous examiner pour de faux pendant 10 minutes : votre dos en profitera pour se reposer.', title_hi = 'मेरा खिलौना बीमार हो गया 🩺', body_hi = 'अपने भालू को अस्पताल में भर्ती कर दिया? आप भी बीमार बन जाइए! सोफ़े पर लेट जाइए, उसे 10 मिनट आपकी भी नकली जाँच करने दीजिए, इसी बहाने आपकी कमर को आराम मिलेगा।', title_id = 'Mainanku sakit 🩺', body_id = 'Ia memasukkan beruangnya ke rumah sakit? Anda juga ikut sakit! Berbaringlah di sofa, biarkan ia pura-pura memeriksa Anda selama 10 menit, dengan alasan ini punggung Anda bisa beristirahat.', title_ja = 'おもちゃが病気になった 🩺', body_ja = 'くまさんを病院に入院させた？あなたも患者さんになりましょう！ソファに横になって、10分間診察ごっこをしてもらえば、ついでに腰も休まります。', title_ko = '내 장난감이 아파 🩺', body_ko = '곰 인형을 병원에 입원시켰나요? 엄마도 환자가 되세요! 소파에 누워 10분간 진찰받는 척하면, 이 핑계로 허리도 쉴 수 있어요.', title_nl = 'Mijn knuffel is ziek 🩺', body_nl = 'Heeft hij zijn beer in het ziekenhuis opgenomen? Word jij ook ziek! Ga op de bank liggen en laat je 10 minuten voor de show onderzoeken, dan rust je rug meteen even uit.', title_pl = 'Moja zabawka zachorowała 🩺', body_pl = 'Położył misia w szpitalu? Ty też zachoruj! Połóż się na kanapie i pozwól mu przez 10 minut na niby cię badać, przy okazji odpocznie ci kręgosłup.', title_pt = 'O meu brinquedo está doente 🩺', body_pt = 'Internou o urso no hospital? Fique também doente! Deite-se no sofá e deixe que a examine a fingir durante 10 minutos: com esta desculpa, as suas costas descansam.', title_sv = 'Min leksak är sjuk 🩺', body_sv = 'Har barnet lagt in nallen på sjukhus? Bli sjuk du också! Lägg dig i soffan och låt barnet låtsasundersöka dig i 10 minuter, så får ryggen vila under förevändningen.', title_vi = 'Đồ chơi của con bị ốm 🩺', body_vi = 'Bé đưa gấu bông vào "bệnh viện"? Mẹ cũng bị ốm đi! Nằm lên sofa và để bé "khám" cho mẹ 10 phút, nhân tiện cho lưng mẹ được nghỉ.', title_zh = '我的玩具生病了 🩺', body_zh = '把小熊送进了“医院”？你也来当病人吧！躺到沙发上，让宝宝假装给你检查10分钟，正好借机让腰休息一下。' WHERE id = '73d3b07e-eaa0-4423-b3b3-a6fb8656c01c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La insistencia en «duerme conmigo» 🫂', body_es = '¿Insiste en que duermas a su lado? Sáltate las reglas un día, respira hondo su olor y duérmete tú también con él. Es terapia de amor para los dos.', title_fr = 'L''insistance du « Dors avec moi » 🫂', body_fr = 'Il insiste pour que vous dormiez à côté de lui ? Pour une fois, enfreignez les règles : respirez profondément son odeur et endormez-vous avec lui. C''est une thérapie d''amour pour vous deux.', title_hi = '‘मेरे साथ सोओ’ की ज़िद 🫂', body_hi = 'ज़िद कर रहा है कि आप उसके पास सोएँ? एक दिन नियम तोड़ दीजिए, उसकी खुशबू गहरी साँसों में भरते हुए आप भी उसके साथ सो जाइए। यह दोनों के लिए प्यार की थेरेपी है।', title_id = 'Bersikeras ''Tidur sama aku'' 🫂', body_id = 'Ia bersikeras Anda tidur di sampingnya? Sekali-sekali langgar aturan, hirup dalam-dalam aromanya dan ikutlah tidur bersamanya. Ini terapi cinta untuk kalian berdua.', title_ja = '一緒に寝てとせがむ 🫂', body_ja = 'そばで寝てと言いはる？たまにはルールを破って、においを深く吸いこみながら一緒に眠りましょう。ふたりにとっての愛情セラピーです。', title_ko = '''나랑 같이 자'' 고집 🫂', body_ko = '옆에서 같이 자자고 조르나요? 하루쯤은 규칙을 깨고, 그 냄새를 깊이 들이마시며 함께 잠드세요. 두 사람 모두에게 사랑 치료예요.', title_nl = 'Het ''slaap bij mij''-gesmeek 🫂', body_nl = 'Staat hij erop dat je naast hem slaapt? Breek één keer de regels, snuif diep zijn geur op en slaap ook met hem mee. Het is liefdestherapie voor jullie allebei.', title_pl = 'Upór „śpij ze mną” 🫂', body_pl = 'Nalega, żebyś spała obok niego? Choć raz złam zasady, wdychaj głęboko jego zapach i zaśnij razem z nim. To terapia miłością dla was obojga.', title_pt = 'A insistência do "Dorme comigo" 🫂', body_pt = 'Insiste que durma ao lado dele? Quebre as regras por uma noite, respire fundo o cheirinho dele e adormeça também com ele. É terapia de amor para os dois.', title_sv = 'Sov med mig, tjatar barnet 🫂', body_sv = 'Insisterar barnet på att du ska sova bredvid? Bryt reglerna för en dag, andas djupt in doften och sov du också med barnet. Det är kärleksterapi för er båda.', title_vi = 'Năn nỉ "Ngủ với con" 🫂', body_vi = 'Bé nhất định đòi mẹ ngủ cạnh? Hãy phá lệ một ngày, hít thật sâu mùi hương của bé và ngủ cùng bé. Đó là liệu pháp yêu thương cho cả hai mẹ con.', title_zh = '非要和我一起睡 🫂', body_zh = '坚持要你睡在旁边？偶尔打破一次规矩，深深吸一口宝宝的味道，和宝宝一起睡吧。这对你们俩都是一场爱的疗愈。' WHERE id = 'ea408c5e-c419-4258-9053-eba96cea541e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, ayúdame 🤖', body_es = '¿Te han agotado las preguntas filosóficas sin fin de tu peque? Escríbele a Anacan AI y que prepare por ti al instante las respuestas más científicas, pacientes y tiernas para 4 años.', title_fr = 'Intelligence artificielle, aide-moi 🤖', body_fr = 'Les questions philosophiques incessantes de l''enfant vous ont épuisée ? Écrivez à Anacan AI : qu''il prépare à votre place, tout de suite, les réponses les plus scientifiques, les plus patientes et les plus douces pour un enfant de 4 ans.', title_hi = 'AI, मेरी मदद करो 🤖', body_hi = 'बच्चे के लगातार दार्शनिक सवालों ने आपको थका दिया? Anacan AI को लिखिए, वह आपकी जगह 4 साल के बच्चे के लिए सबसे वैज्ञानिक, सबसे धैर्य वाले और प्यारे जवाब तुरंत तैयार करेगा।', title_id = 'Kecerdasan buatan, bantu aku 🤖', body_id = 'Pertanyaan filosofis anak yang tak ada habisnya membuat Anda kehabisan tenaga? Tulis ke Anacan AI, biarkan ia menyiapkan jawaban paling ilmiah, sabar, dan manis untuk anak usia 4 tahun untuk Anda.', title_ja = 'AIさん、助けて 🤖', body_ja = '子どもの止まらない哲学的な質問で、くたくた？Anacan AIに書きこめば、あなたのかわりに、4歳向けのいちばん科学的で、いちばんやさしく、かわいい答えをすぐに用意してくれます。', title_ko = 'AI야, 도와줘 🤖', body_ko = '끝없이 쏟아지는 철학적 질문에 지쳤나요? Anacan AI에게 써 보세요. 엄마 대신 4세에게 딱 맞는 가장 과학적이고 차분하며 귀여운 답을 바로 준비해 줄 거예요.', title_nl = 'AI, help me 🤖', body_nl = 'Ben je uitgeput van de eindeloze filosofische vragen van je kind? Schrijf het aan Anacan AI en laat het meteen voor jou de meest wetenschappelijke, geduldigste en liefste antwoorden voor een 4-jarige klaarmaken.', title_pl = 'Sztuczna inteligencjo, pomóż mi 🤖', body_pl = 'Niekończące się filozoficzne pytania dziecka cię wyczerpały? Napisz do Anacan AI, niech od razu przygotuje za ciebie najbardziej naukowe, cierpliwe i urocze odpowiedzi dla 4-latka.', title_pt = 'Inteligência Artificial, ajuda-me 🤖', body_pt = 'As perguntas filosóficas sem fim da criança esgotaram-na? Escreva ao Anacan AI e deixe que prepare logo por si as respostas mais científicas, pacientes e doces para os 4 anos.', title_sv = 'AI, hjälp mig 🤖', body_sv = 'Har barnets ändlösa filosofiska frågor tömt dig? Skriv till Anacan AI, så tar det genast fram de mest vetenskapliga, tålmodiga och söta svaren för en 4-åring åt dig.', title_vi = 'Trí tuệ nhân tạo ơi, giúp mẹ với 🤖', body_vi = 'Những câu hỏi triết lý không ngừng của bé làm mẹ kiệt sức? Hãy nhắn cho Anacan AI, để nó thay mẹ soạn ngay những câu trả lời khoa học, kiên nhẫn và ngọt ngào nhất cho bé 4 tuổi.', title_zh = '人工智能，帮帮我 🤖', body_zh = '孩子没完没了的哲学问题让你精疲力尽？写给Anacan AI，让它替你马上准备好适合4岁孩子的最科学、最有耐心又最可爱的回答。' WHERE id = '7d8bddb7-9260-4872-8287-e9bfde4a91d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No me he reconocido en el espejo 🪞', body_es = '¿Se mira al espejo, cambia de muecas y se enfada consigo mismo? Se están formando su identidad y sus emociones. Observa en silencio desde fuera esta actuación.', title_fr = 'Je ne me suis pas reconnu dans le miroir 🪞', body_fr = 'Il se regarde dans le miroir, change d''expression et se met en colère contre lui-même ? Sa personnalité et ses émotions se forment. Observez en silence, de loin, ses talents d''acteur.', title_hi = 'आईने में खुद को नहीं पहचाना 🪞', body_hi = 'आईने में खुद को देखकर, चेहरे के भाव बदलते हुए खुद पर ही गुस्सा होता है? उसकी पहचान और भावनाएँ आकार ले रही हैं। किनारे से चुपचाप उसकी यह एक्टिंग देखिए।', title_id = 'Aku tidak mengenali diriku di cermin 🪞', body_id = 'Ia menatap dirinya di cermin, mengubah-ubah ekspresi, dan marah pada dirinya sendiri? Jati diri dan emosinya sedang terbentuk. Saksikan akting ini dengan diam dari samping.', title_ja = '鏡の中の自分がわからない 🪞', body_ja = '鏡を見て、表情を変えながら自分に怒っている？自我と感情が形づくられています。この名演技を、そばで静かに見守りましょう。', title_ko = '거울 속 내가 낯설어 🪞', body_ko = '거울을 보며 표정을 바꾸다 스스로에게 화를 내나요? 자아와 감정이 자라는 중이에요. 이 연기를 옆에서 조용히 지켜봐 주세요.', title_nl = 'Ik herkende mezelf niet in de spiegel 🪞', body_nl = 'Kijkt hij in de spiegel, trekt hij gezichten en wordt hij boos op zichzelf? Zijn ik-besef en emoties worden gevormd. Kijk stilletjes van een afstand naar zijn acteerwerk.', title_pl = 'Nie poznałem się w lustrze 🪞', body_pl = 'Patrzy na siebie w lustrze, robi miny i złości się sam na siebie? Kształtuje się jego „ja” i emocje. Obserwuj po cichu z boku ten jego popis aktorski.', title_pt = 'Não me reconheci ao espelho 🪞', body_pt = 'Olha-se ao espelho, muda as expressões e zanga-se consigo próprio? A identidade e as emoções estão a formar-se. Observe em silêncio, à distância, esta representação.', title_sv = 'Jag kände inte igen mig i spegeln 🪞', body_sv = 'Tittar barnet på sig själv i spegeln, gör miner och blir arg på sig själv? Jaget och känslorna håller på att formas. Titta tyst på skådespeleriet från sidan.', title_vi = 'Con không nhận ra mình trong gương 🪞', body_vi = 'Bé nhìn mình trong gương, đổi nét mặt liên tục rồi tự giận mình? Cái tôi và cảm xúc của bé đang hình thành. Hãy lặng lẽ quan sát màn diễn này từ xa.', title_zh = '在镜子里认不出自己了 🪞', body_zh = '照着镜子，变换表情，对着自己生气？宝宝的自我意识和情绪正在形成。在一旁静静欣赏这场“表演”吧。' WHERE id = '9135dd5f-177c-4a9d-97a6-1658abd0da9a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡En el cuento salgo yo! 🪄', body_es = 'En Cuentos inteligentes, cambia directamente el nombre del protagonista por el de tu peque. Igual que el protagonista se duerme rápido y obediente en la historia, él se motivará y hará lo mismo.', title_fr = 'Le héros du conte, c''est moi ! 🪄', body_fr = 'Dans les Contes intelligents, remplacez directement le nom du héros par le prénom de l''enfant. Si, tout au long de l''histoire, le héros s''endort vite et sagement, il sera motivé à faire de même.', title_hi = 'कहानी में मैं हूँ! 🪄', body_hi = 'स्मार्ट कहानियों में हीरो का नाम सीधे अपने बच्चे के नाम से बदल दीजिए। कहानी में वह हीरो जितनी जल्दी और बात मानकर सोता है, उससे प्रेरित होकर वह भी वैसा ही करेगा।', title_id = 'Aku yang ada di dongeng! 🪄', body_id = 'Di Dongeng Pintar, ganti nama tokoh utama langsung dengan nama anak Anda. Saat sepanjang cerita tokoh itu tidur dengan cepat dan patuh, ia pun akan termotivasi dan melakukan hal yang sama.', title_ja = 'お話の主人公はわたし！ 🪄', body_ja = '「スマートおはなし」で、主人公の名前をお子さんの名前に変えましょう。お話の主人公がすぐに素直に眠ると、それがやる気になって同じようにしますよ。', title_ko = '동화 속 주인공은 나! 🪄', body_ko = '스마트 동화에서 주인공 이름을 아이 이름으로 바꿔 보세요. 이야기 속 주인공이 금방 말 잘 듣고 잠들면, 아이도 동기를 얻어 똑같이 따라 할 거예요.', title_nl = 'Ik zit in het sprookje! 🪄', body_nl = 'Vervang in Slimme sprookjes de naam van de held direct door de naam van je kind. Als de held in het verhaal snel en braaf gaat slapen, raakt hij gemotiveerd om hetzelfde te doen.', title_pl = 'To ja jestem w bajce! 🪄', body_pl = 'W Mądrych bajkach zamień imię bohatera na imię dziecka. Gdy w całej historii bohater szybko i grzecznie zasypia, ono złapie motywację i zrobi to samo.', title_pt = 'Sou eu na história! 🪄', body_pt = 'Nas Histórias Inteligentes, substitua diretamente o nome do herói pelo nome do seu filho. Ao ver o herói adormecer depressa e bem-comportado ao longo da história, ele vai ficar motivado a fazer o mesmo.', title_sv = 'Det är jag i sagan! 🪄', body_sv = 'I Smarta sagor kan du byta ut hjältens namn direkt mot barnets namn. När hjälten i berättelsen somnar snabbt och snällt blir barnet motiverat och gör likadant.', title_vi = 'Con ở trong truyện! 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy thay tên nhân vật chính bằng chính tên của bé. Khi nhân vật trong truyện đi ngủ nhanh và ngoan, bé cũng sẽ có động lực làm theo.', title_zh = '故事里的人是我！🪄', body_zh = '在智慧童话里，直接把主角的名字换成宝宝的名字。故事里的主角怎样快快地、乖乖地睡着，宝宝也会受到鼓舞，照着做。' WHERE id = 'a579865a-399f-44c5-a9b0-e44cc032ce14' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quedarse en blanco en medio del súper 🛒', body_es = '¿Has entrado en el súper y se te ha olvidado qué ibas a comprar? Si no llevas la Lista de la compra en digital, en ese caos lo olvidarás todo. Confía siempre en tu memoria digital.', title_fr = 'Figée au milieu du supermarché 🛒', body_fr = 'Vous êtes entrée au supermarché et avez oublié ce que vous deviez acheter ? Si vous ne tenez pas votre Liste de courses en version numérique, vous oublierez tout dans ce chaos. Faites toujours confiance à votre mémoire numérique.', title_hi = 'सुपरमार्केट के बीच में जम जाना 🛒', body_hi = 'सुपरमार्केट में घुसीं और भूल गईं कि क्या लेना है? शॉपिंग लिस्ट डिजिटल न रखी, तो उस अफ़रा-तफ़री में सब भूल जाएँगी। अपनी डिजिटल याददाश्त पर हमेशा भरोसा कीजिए।', title_id = 'Terpaku di tengah supermarket 🛒', body_id = 'Anda masuk supermarket dan lupa mau beli apa? Kalau Daftar Belanja tidak disimpan secara digital, Anda akan melupakan semuanya di tengah kekacauan itu. Selalu andalkan memori digital Anda.', title_ja = 'スーパーのまん中でフリーズ 🛒', body_ja = 'スーパーに入ったら、何を買うか忘れてしまった？「買い物リスト」をデジタルで管理しないと、あのカオスの中で全部忘れてしまいます。デジタルの記憶をいつでもたよりにしましょう。', title_ko = '마트 한가운데서 멈춤 🛒', body_ko = '마트에 들어갔는데 뭘 사야 할지 잊어버렸나요? 쇼핑 목록을 디지털로 관리하지 않으면 그 혼란 속에서 다 잊게 돼요. 디지털 기억을 언제나 믿으세요.', title_nl = 'Bevroren midden in de supermarkt 🛒', body_nl = 'Kom je de supermarkt in en weet je niet meer wat je moest kopen? Als je je boodschappenlijstje niet digitaal bijhoudt, vergeet je in die chaos alles. Vertrouw altijd op je digitale geheugen.', title_pl = 'Zawieszona na środku sklepu 🛒', body_pl = 'Weszłaś do sklepu i zapomniałaś, co miałaś kupić? Jeśli nie prowadzisz cyfrowej Listy zakupów, w tym chaosie zapomnisz o wszystkim. Zawsze ufaj swojej cyfrowej pamięci.', title_pt = 'Parada no meio do supermercado 🛒', body_pt = 'Entrou no supermercado e esqueceu-se do que ia comprar? Se não tiver a Lista de Compras em formato digital, naquele caos vai esquecer tudo. Confie sempre na sua memória digital.', title_sv = 'Att stelna till mitt i affären 🛒', body_sv = 'Gick du in i affären och glömde vad du skulle köpa? Om du inte har inköpslistan digitalt glömmer du allt i det kaoset. Lita alltid på ditt digitala minne.', title_vi = 'Đứng hình giữa siêu thị 🛒', body_vi = 'Vào siêu thị rồi mà quên mất định mua gì? Nếu không lưu Danh sách mua sắm trên điện thoại, giữa mớ hỗn loạn ấy mẹ sẽ quên hết. Hãy luôn tin vào "bộ nhớ số" của mình.', title_zh = '在超市中间愣住 🛒', body_zh = '走进超市，却忘了要买什么？如果不把购物清单存在手机上，在那片混乱里你会什么都忘。永远相信你的数字记忆吧。' WHERE id = '2d3b049d-536d-441d-a015-9e7326fee52e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Contar estrellas por la noche 🌟', body_es = '¿Mira al techo del dormitorio y cuenta estrellas imaginarias? Deja que las cuente. Antes de que esas estrellas inventadas lleguen a 10 ya se habrá adormilado y caerá en un sueño profundo.', title_fr = 'Compter les étoiles la nuit 🌟', body_fr = 'Il regarde le plafond de la chambre et compte des étoiles imaginaires ? Laissez-le compter. Avant que ces étoiles inventées n''atteignent 10, il somnolera déjà et tombera dans un sommeil profond.', title_hi = 'रात को तारे गिनना 🌟', body_hi = 'सोने के कमरे की छत देखकर काल्पनिक तारे गिन रहा है? गिनने दीजिए। उन काल्पनिक तारों की गिनती 10 तक पहुँचने से पहले ही वह ऊँघकर गहरी नींद में चला जाएगा।', title_id = 'Menghitung bintang di malam hari 🌟', body_id = 'Ia memandangi langit-langit kamar dan menghitung bintang khayalan? Biarkan saja. Sebelum hitungan bintang karangannya mencapai 10, ia pasti sudah mengantuk dan tertidur lelap.', title_ja = '夜に星をかぞえる 🌟', body_ja = '寝室の天井を見て、空想の星をかぞえている？かぞえさせてあげましょう。空想の星が10になるころには、もうウトウトして深い眠りに落ちています。', title_ko = '밤에 별 세기 🌟', body_ko = '침실 천장을 보며 상상 속 별을 세고 있나요? 세게 두세요. 상상의 별이 10개가 되기 전에 꾸벅꾸벅 졸다 깊이 잠들 거예요.', title_nl = '''s Nachts sterren tellen 🌟', body_nl = 'Kijkt hij naar het plafond van de slaapkamer en telt hij denkbeeldige sterren? Laat hem tellen. Voordat hij bij 10 verzonnen sterren is, is hij al weggedommeld en diep in slaap.', title_pl = 'Liczenie gwiazd w nocy 🌟', body_pl = 'Patrzy w sufit sypialni i liczy wymyślone gwiazdy? Niech liczy. Zanim liczba tych gwiazd dojdzie do 10, już się zdrzemnie i zapadnie w głęboki sen.', title_pt = 'Contar estrelas à noite 🌟', body_pt = 'Olha para o teto do quarto e conta estrelas imaginárias? Deixe-o contar. Antes de as estrelas inventadas chegarem a 10, já vai estar a dormitar e a cair num sono profundo.', title_sv = 'Räkna stjärnor på natten 🌟', body_sv = 'Tittar barnet upp i sovrumstaket och räknar låtsasstjärnor? Låt hen räkna. Innan de påhittade stjärnorna har nått 10 har barnet redan slumrat in och somnat djupt.', title_vi = 'Đếm sao ban đêm 🌟', body_vi = 'Bé nhìn lên trần phòng ngủ và đếm những ngôi sao tưởng tượng? Cứ để bé đếm. Chưa đến ngôi sao thứ 10, bé đã lim dim và chìm vào giấc ngủ sâu.', title_zh = '夜里数星星 🌟', body_zh = '看着卧室的天花板数想象中的星星？就让宝宝数吧。还没数到10颗，宝宝就会打起瞌睡，进入深深的梦乡。' WHERE id = '47345c36-90d7-4e89-b816-0332dc1932ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mis manos son pies 🤸‍♂️', body_es = '¿Intenta andar con las manos y se cae? ¡Su desarrollo motor creativo va a todo gas! Móntale un pequeño circuito de parkour en un rincón seguro de casa y deja que suelte energía.', title_fr = 'Mes mains sont devenues des pieds 🤸‍♂️', body_fr = 'Il essaie de marcher sur les mains et tombe ? Sa motricité créative se développe à toute vitesse ! Aménagez-lui un petit parcours dans un coin sûr de la maison et laissez-le se dépenser.', title_hi = 'मेरे हाथ पैर बन गए 🤸‍♂️', body_hi = 'हाथों के बल चलने की कोशिश में गिर जाता है? रचनात्मक मोटर विकास पूरी रफ़्तार पर है! घर की किसी सुरक्षित जगह उसके लिए छोटा सा पार्कौर बनाइए, उसे अपनी ऊर्जा निकालने दीजिए।', title_id = 'Tanganku jadi kaki 🤸‍♂️', body_id = 'Ia mencoba berjalan dengan tangan lalu jatuh? Perkembangan motorik kreatifnya sedang melaju kencang! Buat lintasan parkur kecil di tempat aman di rumah, biarkan ia menyalurkan energinya.', title_ja = '手が足になった 🤸‍♂️', body_ja = '逆立ちで歩こうとして転んでいる？創造的な運動能力の発達が全開です！家の安全な場所に小さなパルクールコースをつくって、エネルギーを発散させましょう。', title_ko = '손이 발이 됐어 🤸‍♂️', body_ko = '물구나무로 걸으려다 넘어지나요? 창의적인 운동 능력이 쑥쑥 자라고 있어요! 집 안 안전한 곳에 작은 장애물 코스를 만들어 에너지를 쏟아 내게 해 주세요.', title_nl = 'Mijn handen werden voeten 🤸‍♂️', body_nl = 'Probeert hij op zijn handen te lopen en valt hij om? Zijn creatieve motoriek ontwikkelt zich op volle toeren! Bouw op een veilige plek in huis een klein parcours, zodat hij zijn energie kwijt kan.', title_pl = 'Moje ręce stały się nogami 🤸‍♂️', body_pl = 'Próbuje chodzić na rękach i się przewraca? Rozwój twórczej motoryki idzie pełną parą! W bezpiecznym miejscu w domu zbuduj mu mały tor przeszkód, niech wyładuje energię.', title_pt = 'As minhas mãos viraram pés 🤸‍♂️', body_pt = 'Tenta andar com as mãos e cai? O desenvolvimento motor criativo está a todo o gás! Monte-lhe um pequeno percurso de parkour num sítio seguro da casa e deixe-o gastar a energia.', title_sv = 'Händerna blev fötter 🤸‍♂️', body_sv = 'Försöker barnet gå på händerna och ramlar? Den kreativa motoriken utvecklas för fullt! Bygg en liten parkourbana på ett säkert ställe hemma och låt barnet få ut sin energi.', title_vi = 'Tay con thành chân rồi 🤸‍♂️', body_vi = 'Bé cố đi bằng tay rồi ngã nhào? Kỹ năng vận động sáng tạo đang phát triển hết tốc lực! Hãy dựng cho bé một "đường chạy vượt chướng ngại" nhỏ ở góc an toàn trong nhà để bé xả năng lượng.', title_zh = '我的手变成了脚 🤸‍♂️', body_zh = '想用手走路，结果摔倒了？创造性的运动发展正火力全开！在家里安全的地方给宝宝搭一个小小的障碍跑道，让宝宝把精力释放出来。' WHERE id = '924a98d3-0af0-4add-81f0-0d94e1af83c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Papá llega en silencio 👨‍🍼', body_es = 'Justo cuando te quedas sin fuerzas leyendo el cuento, papá entra en silencio en la habitación, lo acaricia y te hace una señal de «ve a descansar». Es el momento más de equipo de ser padres.', title_fr = 'L''arrivée silencieuse de papa 👨‍🍼', body_fr = 'Au moment où vous êtes à bout après avoir lu le conte, papa entre en silence dans la chambre, le caresse et vous fait signe d''aller vous reposer. C''est le moment où la parentalité est le plus un travail d''équipe.', title_hi = 'पापा का चुपचाप आना 👨‍🍼', body_hi = 'जिस पल आप कहानी पढ़ते-पढ़ते थककर चूर हो जाती हैं, पापा चुपचाप कमरे में आकर उसे सहलाते हैं और आपको ‘जाओ, आराम करो’ का इशारा करते हैं। यह पेरेंटिंग का सबसे बढ़िया टीमवर्क वाला पल है।', title_id = 'Kedatangan Ayah yang tanpa suara 👨‍🍼', body_id = 'Saat Anda kehabisan tenaga membacakan dongeng, Ayah masuk kamar diam-diam, mengelusnya, dan memberi isyarat ''Pergi istirahat''. Inilah momen kerja tim paling sejati dalam menjadi orang tua.', title_ja = 'パパが静かにやってくる 👨‍🍼', body_ja = 'お話を読んでくたくたになったとき、パパが静かに部屋に入ってきて子どもをなで、あなたに「休んでおいで」と合図する。子育てでいちばんチームワークを感じる瞬間です。', title_ko = '아빠의 조용한 등장 👨‍🍼', body_ko = '엄마가 동화를 읽다 지쳐 버린 순간, 아빠가 조용히 들어와 아이를 쓰다듬으며 ''가서 쉬어''라는 신호를 보내요. 육아에서 가장 멋진 팀워크의 순간이에요.', title_nl = 'Papa komt stil binnen 👨‍🍼', body_nl = 'Op het moment dat jij uitgeput bent van het voorlezen, komt papa stil de kamer in, aait hem en geeft jou een teken: ga maar rusten. Dit is het ultieme teamwerkmoment van het ouderschap.', title_pl = 'Ciche wejście taty 👨‍🍼', body_pl = 'W chwili, gdy kończą ci się siły od czytania bajki, tata cicho wchodzi do pokoju, głaszcze dziecko i daje ci znak: „idź odpocząć”. To najbardziej drużynowa chwila rodzicielstwa.', title_pt = 'A entrada silenciosa do pai 👨‍🍼', body_pt = 'No momento em que fica esgotada de ler a história, o pai entra no quarto em silêncio, faz-lhe festas e faz-lhe sinal para ir descansar. É o momento de maior trabalho de equipa da parentalidade.', title_sv = 'Pappas tysta entré 👨‍🍼', body_sv = 'Precis när du är slut efter sagoläsningen kommer pappa tyst in i rummet, stryker barnet över håret och ger dig tecknet ”gå och vila”. Det är föräldraskapets bästa lagarbete.', title_vi = 'Bố lặng lẽ xuất hiện 👨‍🍼', body_vi = 'Đúng lúc mẹ đọc truyện đến kiệt sức, bố lặng lẽ vào phòng, vỗ về bé và ra hiệu cho mẹ đi nghỉ. Đó là khoảnh khắc "làm việc nhóm" đúng nghĩa nhất của việc làm cha mẹ.', title_zh = '爸爸悄悄地来了 👨‍🍼', body_zh = '你讲故事讲到精疲力尽时，爸爸悄悄走进房间，轻轻抚摸宝宝，给你一个“去休息吧”的手势。这是为人父母最有团队精神的时刻。' WHERE id = '50f1584c-32c1-44e9-9ef5-89a70a2afc5e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No has pelado bien el plátano 🍌', body_es = '¡El rey de las excusas! Se ha armado una buena porque el plátano lo has pelado tú. Dale otro plátano y deja que lo pele como quiera, aunque sea partiéndolo por la mitad, para no herir su independencia.', title_fr = 'Tu n''as pas bien épluché la banane 🍌', body_fr = 'Le roi des prétextes ! C''est l''apocalypse parce que c''est vous qui avez épluché la banane. Donnez-lui une nouvelle banane et laissez-le l''éplucher comme il veut, même en la cassant en plein milieu, pour ne pas froisser son indépendance.', title_hi = 'तुमने केला ठीक से नहीं छीला 🍌', body_hi = 'बहानों का राजा! केला आपने छीला, इसलिए हंगामा मच गया। नया केला दीजिए, उसे जैसे चाहे, बीच से तोड़कर छीलने दीजिए, ताकि उसकी आत्मनिर्भरता को ठेस न लगे।', title_id = 'Pisangnya salah dikupas 🍌', body_id = 'Raja alasan! Kiamat terjadi karena Anda yang mengupas pisangnya. Beri pisang baru, biarkan ia mengupasnya sesuai keinginannya, bahkan dengan mematahkannya di tengah, supaya kemandiriannya tidak terluka.', title_ja = 'バナナのむき方がちがう 🍌', body_ja = '言いわけの王さま！あなたがバナナをむいたから大さわぎ。新しいバナナを渡して、まん中から折ってむくなど、自分の好きなようにむかせてあげましょう。自立心を傷つけないで。', title_ko = '바나나를 잘못 깠잖아 🍌', body_ko = '핑계의 왕! 엄마가 바나나를 깠다고 난리가 났나요? 새 바나나를 주고 가운데를 똑 부러뜨려서라도 자기 방식대로 까게 두세요. 독립심이 다치지 않게요.', title_nl = 'Je hebt de banaan verkeerd gepeld 🍌', body_nl = 'De koning van de smoesjes! Er breekt een ramp uit omdat jij de banaan pelde. Geef een nieuwe banaan en laat hem die pellen zoals hij wil, desnoods in het midden doorgebroken, zodat zijn zelfstandigheid niet gekrenkt wordt.', title_pl = 'Źle obrałaś banana 🍌', body_pl = 'Król wymówek! Wybuchła awantura, bo to ty obrałaś banana. Daj nowego banana, niech obierze go sam, jak chce, choćby przełamując na środku, żeby nie ucierpiała jego samodzielność.', title_pt = 'Não descascaste bem a banana 🍌', body_pt = 'O rei das desculpas! Caiu o Carmo e a Trindade porque foi a mãe a descascar a banana. Dê-lhe uma banana nova e deixe-o descascá-la como quiser, nem que a parta ao meio, para não ferir a independência dele.', title_sv = 'Du skalade inte bananen rätt 🍌', body_sv = 'Ursäkternas kung! Det blev världens undergång för att du skalade bananen. Ge en ny banan och låt barnet skala den som hen vill, till och med genom att bryta den på mitten, så att självständigheten inte tar skada.', title_vi = 'Mẹ bóc chuối sai rồi 🍌', body_vi = 'Vua viện cớ! Cả nhà như "tận thế" chỉ vì mẹ bóc chuối. Hãy đưa bé quả chuối mới, để bé tự bóc theo ý mình, bẻ đôi ở giữa cũng được, miễn sự tự lập của bé không bị tổn thương.', title_zh = '香蕉剥得不对 🍌', body_zh = '借口之王！因为香蕉是你剥的，就闹翻天了。再给一根新香蕉，让宝宝按自己想要的方式，从正中间掰开来剥，别伤了宝宝的独立心。' WHERE id = '6694bf7a-8c8c-47c1-8991-2a84701c94f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rebelión de «hace mucho calor» 🧥', body_es = '¿Se quita la chaqueta en medio de la calle y la tira, y a ti te da miedo que pase frío? No pelees: cuando tenga frío de verdad, vendrá él mismo a pedirla. Deja que viva la consecuencia.', title_fr = 'La révolte du « Il fait trop chaud » 🧥', body_fr = 'Il enlève son blouson et le jette au milieu de la rue, et vous avez peur qu''il ait froid ? Ne luttez pas : quand il aura vraiment froid, il viendra le réclamer lui-même. Laissez-le vivre la conséquence.', title_hi = '‘बहुत गर्मी है’ वाली बगावत 🧥', body_hi = 'सड़क के बीच में जैकेट उतारकर फेंक देता है और आपको डर है कि ठंड लग जाएगी? लड़िए मत, सच में ठंड लगेगी तो खुद आकर माँगेगा, उसे नतीजा खुद महसूस करने दीजिए।', title_id = 'Pemberontakan ''udaranya panas sekali'' 🧥', body_id = 'Ia melepas dan membuang jaketnya di tengah jalan, sementara Anda takut ia kedinginan? Jangan dilawan, kalau benar-benar kedinginan ia akan datang dan memintanya sendiri, biarkan ia merasakan akibatnya sendiri.', title_ja = '暑すぎる！の反乱 🧥', body_ja = '道のまん中でジャケットをぬいで投げる、そしてあなたは寒くならないか心配？争わないで。本当に寒くなったら自分で着たがります。結果を自分で体験させてあげましょう。', title_ko = '''너무 더워'' 반란 🧥', body_ko = '길 한복판에서 점퍼를 벗어 던지는데 감기 걸릴까 걱정되나요? 다투지 마세요. 정말 추우면 스스로 달라고 할 거예요. 결과를 직접 경험하게 해 주세요.', title_nl = 'De ''het is te warm''-opstand 🧥', body_nl = 'Trekt hij midden op straat zijn jas uit en gooit hij die weg, terwijl jij bang bent dat hij het koud krijgt? Ga de strijd niet aan, als hij het echt koud heeft vraagt hij er zelf om. Laat hem zelf het gevolg ervaren.', title_pl = 'Bunt „jest za gorąco” 🧥', body_pl = 'Na środku ulicy zdejmuje i rzuca kurtkę, a ty boisz się, że zmarznie? Nie walcz, gdy naprawdę zmarznie, sam o nią poprosi, niech sam przekona się o skutkach.', title_pt = 'A revolta do "está muito calor" 🧥', body_pt = 'Tira o casaco no meio da rua e atira-o ao chão, e a mãe tem medo de que ele fique com frio? Não lute: quando tiver frio a sério, vem pedi-lo. Deixe-o viver as consequências.', title_sv = 'Det är för varmt-upproret 🧥', body_sv = 'Tar barnet av sig jackan mitt på gatan och kastar den, medan du är rädd att hen ska frysa? Kämpa inte emot, när barnet verkligen fryser kommer hen själv och vill ha den. Låt barnet uppleva konsekvensen själv.', title_vi = 'Cuộc nổi loạn "Nóng quá" 🧥', body_vi = 'Bé cởi áo khoác vứt ngay giữa đường, còn mẹ lo bé bị lạnh? Đừng giằng co, khi lạnh thật bé sẽ tự đòi, hãy để bé tự trải nghiệm hậu quả.', title_zh = '“太热了”大反抗 🧥', body_zh = '在街上把外套脱下来扔掉，你又担心宝宝着凉？别较劲，真冷了宝宝会自己来要的，让宝宝亲身体验一下后果吧。' WHERE id = '9aaf0e76-e78b-442f-afe1-7bb02c660da6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Soy una silla 🪑', body_es = '¿Se hace pasar por un objeto y se queda inmóvil? Ponle un juguete encima de broma y dile «¡Qué silla tan bonita!». Le encantará este papel tan curioso y se quedará tranquilo.', title_fr = 'Je suis une chaise 🪑', body_fr = 'Il se présente comme un objet et reste immobile ? Posez-lui un jouet dessus pour de faux et dites « Quelle belle chaise ! ». Il adorera ce drôle de rôle et restera calme.', title_hi = 'मैं कुर्सी हूँ 🪑', body_hi = 'खुद को कोई चीज़ बताकर बिना हिले खड़ा है? उस पर दिखावे के लिए एक खिलौना रखिए और कहिए, ‘कितनी सुंदर कुर्सी है।’ उसे यह अनोखा रोल बहुत पसंद आएगा और वह शांत रहेगा।', title_id = 'Aku kursi 🪑', body_id = 'Ia memperkenalkan diri sebagai benda dan berdiri tak bergerak? Pura-pura letakkan mainan di atasnya dan katakan ''Kursi yang bagus sekali''. Ia akan sangat menyukai peran aneh ini dan tetap tenang.', title_ja = 'ぼくはいすです 🪑', body_ja = '自分をものだと言って、じっと動かない？上におもちゃをのせるふりをして「なんてすてきないすでしょう」と言いましょう。このふしぎな役をとても気に入って、静かにしていますよ。', title_ko = '나는 의자야 🪑', body_ko = '자기가 물건이라며 꼼짝 않고 서 있나요? 장난감 하나를 위에 올려놓는 척하며 ''정말 멋진 의자네'' 하고 말해 주세요. 이 엉뚱한 역할을 아주 좋아하며 얌전히 있을 거예요.', title_nl = 'Ik ben een stoel 🪑', body_nl = 'Doet hij alsof hij een voorwerp is en staat hij bewegingloos stil? Leg voor de grap een speeltje op hem en zeg: ''Wat een mooie stoel.'' Hij zal deze rare rol geweldig vinden en rustig blijven.', title_pl = 'Jestem krzesłem 🪑', body_pl = 'Udaje przedmiot i stoi bez ruchu? Połóż na nim na niby zabawkę i powiedz: „Jakie piękne krzesło”. Pokocha tę dziwną rolę i będzie spokojny.', title_pt = 'Eu sou uma cadeira 🪑', body_pt = 'Faz de conta que é um objeto e fica imóvel? Ponha-lhe em cima um brinquedo a fingir e diga "Que cadeira tão bonita". Ele vai adorar este papel estranho e ficar quietinho.', title_sv = 'Jag är en stol 🪑', body_sv = 'Låtsas barnet vara ett föremål och står helt stilla? Låtsas lägga en leksak ovanpå och säg ”Vilken fin stol”. Barnet kommer att älska den konstiga rollen och hålla sig lugn.', title_vi = 'Con là cái ghế 🪑', body_vi = 'Bé tự nhận mình là đồ vật và đứng im bất động? Hãy giả vờ đặt một món đồ chơi lên người bé và nói "Cái ghế đẹp quá!". Bé sẽ rất thích vai diễn kỳ lạ này và giữ yên lặng.', title_zh = '我是一把椅子 🪑', body_zh = '把自己当成一件物品，一动不动？假装在宝宝身上放一个玩具，说“多好的椅子啊”。宝宝会很喜欢这个奇怪的角色，也会安静下来。' WHERE id = '02ff52cb-13af-47d3-83d9-4e3e21f04d45' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué me dice la Comunidad? 💬', body_es = '¿Crees que lo haces todo mal? Entra en la Comunidad Anacan, lee las historias de los peques revoltosos de otras mamás, respira hondo ¡y da gracias por el tuyo!', title_fr = 'Que me dit la Communauté ? 💬', body_fr = 'Vous pensez que vous faites tout de travers ? Rejoignez la Communauté Anacan, lisez les histoires des enfants complètement fous des autres mamans, respirez profondément et soyez reconnaissante pour le vôtre !', title_hi = 'कम्युनिटी मुझसे क्या कहती है? 💬', body_hi = 'लगता है आप सब कुछ गलत कर रही हैं? Anacan कम्युनिटी में आइए, दूसरी माँओं के शरारती बच्चों के किस्से पढ़िए, गहरी साँस लीजिए और अपने बच्चे के लिए शुक्रिया कहिए!', title_id = 'Apa kata komunitas untukku? 💬', body_id = 'Anda merasa melakukan semuanya dengan salah? Masuk ke Komunitas Anacan, baca kisah anak-anak super heboh milik ibu-ibu lain, tarik napas dalam, dan syukuri anak Anda sendiri!', title_ja = 'コミュニティのみんなは何て言う？ 💬', body_ja = '何もかもまちがえている気がする？Anacanコミュニティに入って、ほかのママたちのやんちゃな子どものお話を読み、深呼吸して、わが子に感謝しましょう！', title_ko = '커뮤니티는 뭐라고 할까? 💬', body_ko = '내가 다 잘못하고 있는 것 같나요? Anacan 커뮤니티에 들어가 다른 엄마들의 천방지축 아이들 이야기를 읽고, 깊게 숨 쉬며 우리 아이에게 감사하세요!', title_nl = 'Wat zegt de Community tegen mij? 💬', body_nl = 'Denk je dat je alles verkeerd doet? Ga naar de Anacan Community, lees de verhalen over de wilde kinderen van andere mama''s, haal diep adem en wees dankbaar voor die van jou!', title_pl = 'Co mówi mi Społeczność? 💬', body_pl = 'Myślisz, że wszystko robisz źle? Wejdź do Społeczności Anacan, poczytaj historie o szalonych dzieciach innych mam, weź głęboki oddech i podziękuj za swoje!', title_pt = 'O que me diz a comunidade? 💬', body_pt = 'Acha que está a fazer tudo mal? Entre na Comunidade Anacan, leia as histórias dos filhos endiabrados das outras mães, respire fundo e agradeça pelo seu!', title_sv = 'Vad säger Community till mig? 💬', body_sv = 'Tror du att du gör allt fel? Gå in i Anacan Community, läs andra mammors berättelser om deras galna barn, andas djupt och var tacksam för ditt eget!', title_vi = 'Cộng đồng nói gì với mẹ? 💬', body_vi = 'Mẹ nghĩ mình làm sai mọi thứ? Hãy vào Cộng đồng Anacan, đọc chuyện về những đứa trẻ "quậy tưng" của các mẹ khác, hít thở thật sâu và biết ơn bé nhà mình!', title_zh = '社区里大家怎么说？💬', body_zh = '觉得自己什么都做错了？来Anacan社区，读读其他妈妈家里那些疯狂小家伙的故事，深呼吸，为自己的宝宝心怀感恩吧！' WHERE id = '50fd969e-9bd4-4e5e-8927-9b3b9067a4be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja la habitación totalmente a oscuras 🌙', body_es = '¿No puede dormir por la luz que se cuela desde el pasillo? Busca la perfección. Cierra bien la puerta, oscurece del todo la habitación y deja que la melatonina haga su trabajo natural y lo duerma.', title_fr = 'Faites le noir complet dans la chambre 🌙', body_fr = 'Il n''arrive pas à dormir à cause de la lumière qui filtre du couloir ? Il cherche la perfection. Fermez bien la porte, plongez la chambre dans le noir complet et laissez la mélatonine faire son travail naturel pour l''endormir.', title_hi = 'कमरे में पूरा अंधेरा कर दीजिए 🌙', body_hi = 'गलियारे से आती रोशनी की लकीर की वजह से सो नहीं पा रहा? वह परफ़ेक्शन ढूँढ रहा है। दरवाज़ा कसकर बंद कीजिए, कमरे में पूरा अंधेरा कीजिए, मेलाटोनिन को अपना प्राकृतिक काम करके उसे सुलाने दीजिए।', title_id = 'Buat kamar benar-benar gelap 🌙', body_id = 'Ia tidak bisa tidur karena cahaya merembes dari lorong? Ia sedang mencari kesempurnaan. Tutup pintu rapat-rapat, gelapkan kamar sepenuhnya, biarkan melatonin bekerja secara alami dan membuatnya tertidur.', title_ja = '部屋を真っ暗にしよう 🌙', body_ja = '廊下からもれる光で眠れない？完璧を求めているんです。ドアをしっかり閉めて部屋を真っ暗にし、メラトニンの自然な働きで眠らせてあげましょう。', title_ko = '방을 완전히 어둡게 🌙', body_ko = '복도에서 새어 들어오는 빛 때문에 잠을 못 자나요? 완벽을 찾는 중이에요. 문을 꼭 닫고 방을 완전히 어둡게 해서, 멜라토닌이 자연스럽게 제 할 일을 하며 재워 주게 하세요.', title_nl = 'Maak de kamer helemaal donker 🌙', body_nl = 'Kan hij niet slapen door het licht dat vanuit de gang naar binnen kiert? Hij zoekt perfectie. Doe de deur goed dicht, maak de kamer helemaal donker en laat melatonine zijn natuurlijke werk doen om hem in slaap te krijgen.', title_pl = 'Zaciemnij pokój całkowicie 🌙', body_pl = 'Nie może zasnąć przez światło sączące się z korytarza? Szuka perfekcji. Szczelnie zamknij drzwi, całkiem zaciemnij pokój i pozwól melatoninie naturalnie zrobić swoje i go uśpić.', title_pt = 'Deixe o quarto completamente às escuras 🌙', body_pt = 'Não consegue dormir por causa da luz que entra do corredor? Procura a perfeição. Feche bem a porta, escureça totalmente o quarto e deixe a melatonina fazer o seu trabalho natural e adormecê-lo.', title_sv = 'Gör rummet helt mörkt 🌙', body_sv = 'Kan barnet inte sova för ljuset som läcker in från hallen? Hen söker perfektion. Stäng dörren ordentligt, gör rummet helt mörkt och låt melatoninet göra sitt naturliga jobb och söva barnet.', title_vi = 'Làm phòng tối hoàn toàn 🌙', body_vi = 'Bé không ngủ được vì ánh sáng lọt vào từ hành lang? Bé đang tìm kiếm sự hoàn hảo. Hãy đóng chặt cửa, làm tối hoàn toàn căn phòng, để melatonin tự nhiên làm nhiệm vụ đưa bé vào giấc ngủ.', title_zh = '让房间彻底变暗 🌙', body_zh = '因为走廊透进来的光睡不着？宝宝在追求完美。把门关紧，让房间完全暗下来，让褪黑素自然发挥作用，哄宝宝入睡。' WHERE id = '8d85cb27-805f-4ca6-a6a0-16122a07af20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de la mancha invisible 👕', body_es = '¿Busca una mancha en el pantalón, pero no hay nada? Otra vez esas obsesiones visuales. Haz como que la limpias con una toallita húmeda y dile «Se ha ido volando». El cerebro infantil se cree las ilusiones enseguida.', title_fr = 'Le drame de la tache invisible 👕', body_fr = 'Il cherche une tache sur son pantalon, mais il n''y a rien ? Encore ces obsessions visuelles. Faites semblant d''essuyer avec une lingette et dites « Envolée, partie ! ». Le cerveau d''un enfant croit très vite à l''illusion.', title_hi = 'अदृश्य दाग की परेशानी 👕', body_hi = 'पैंट पर दाग ढूँढ रहा है, पर कुछ है ही नहीं? फिर वही दिखावटी वहम। वेट वाइप से दिखावे के लिए पोंछिए और कहिए, ‘उड़ गया।’ बच्चे का दिमाग भ्रम पर बहुत जल्दी यकीन कर लेता है।', title_id = 'Drama noda tak kasatmata 👕', body_id = 'Ia mencari noda di celananya, padahal tidak ada apa-apa? Lagi-lagi obsesi visual itu. Pura-pura usap dengan tisu basah dan katakan ''Sudah terbang pergi''. Otak anak sangat cepat percaya pada ilusi.', title_ja = '見えないシミ問題 👕', body_ja = 'ズボンにシミを探しているけれど、何もない？またあの見た目へのこだわりです。ウェットティッシュで拭くふりをして「飛んでいったよ」と言いましょう。子どもの脳は、すぐにイリュージョンを信じます。', title_ko = '보이지 않는 얼룩 소동 👕', body_ko = '바지에서 얼룩을 찾는데 아무것도 없나요? 또 시각적 집착이에요. 물티슈로 닦는 척하며 ''날아가 버렸어'' 하고 말해 주세요. 아이의 뇌는 착각을 아주 쉽게 믿어요.', title_nl = 'Het drama van de onzichtbare vlek 👕', body_nl = 'Zoekt hij een vlek op zijn broek, maar er is niets? Weer die visuele obsessies. Veeg voor de show met een vochtig doekje en zeg ''weggevlogen''. Een kinderbrein gelooft heel snel in een illusie.', title_pl = 'Dramat niewidzialnej plamy 👕', body_pl = 'Szuka plamy na spodniach, a tam nic nie ma? Znowu te wizualne obsesje. Udawaj, że ścierasz ją nawilżaną chusteczką, i powiedz: „Odfrunęła”. Dziecięcy mózg bardzo szybko wierzy w iluzję.', title_pt = 'O drama da mancha invisível 👕', body_pt = 'Procura uma mancha nas calças, mas não há nada? Outra vez as obsessões visuais. Finja que limpa com um toalhete húmido e diga "voou, já foi". O cérebro da criança acredita muito depressa na ilusão.', title_sv = 'Sorgen över den osynliga fläcken 👕', body_sv = 'Letar barnet efter en fläck på byxorna, men det finns ingenting? Återigen de visuella tvångstankarna. Låtsastorka med en våtservett och säg ”Den flög iväg”. Barnhjärnan tror väldigt snabbt på illusioner.', title_vi = 'Nỗi khổ vết bẩn vô hình 👕', body_vi = 'Bé tìm vết bẩn trên quần, nhưng chẳng có gì cả? Lại là những ám ảnh thị giác. Hãy giả vờ lau bằng khăn ướt và nói "Bay mất rồi". Não trẻ rất nhanh tin vào ảo giác.', title_zh = '看不见的污渍烦恼 👕', body_zh = '在裤子上找污渍，其实什么都没有？又是那些视觉上的执念。用湿巾假装擦一擦，说“飞走啦”。孩子的大脑很快就会相信这个小魔术。' WHERE id = '6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú siéntate aparte 🛑', body_es = '¿Te pide que te sientes no junto a su cama, sino lejos, en la puerta? ¡No te lo tomes a mal! Es un gran paso hacia su independencia y deberías alegrarte por dentro.', title_fr = 'Toi, assieds-toi plus loin 🛑', body_fr = 'Il exige que vous vous asseyiez non pas près de son lit, mais loin, à l''entrée de la porte ? Ne vous vexez pas ! C''est un grand pas vers son indépendance, réjouissez-vous-en intérieurement.', title_hi = 'तुम दूर बैठो 🛑', body_hi = 'चाहता है कि आप उसके बिस्तर के पास नहीं, दूर दरवाज़े पर बैठें? बुरा मत मानिए! यह आत्मनिर्भरता की ओर उसका बड़ा कदम है, आपको मन ही मन खुश होना चाहिए।', title_id = 'Mama duduk di sana saja 🛑', body_id = 'Ia menuntut Anda duduk bukan di samping tempat tidurnya, tapi jauh, di dekat pintu? Jangan tersinggung! Ini langkah besarnya menuju kemandirian, dalam hati Anda patut bergembira.', title_ja = 'ママははなれて座って 🛑', body_ja = 'ベッドのそばではなく、遠くのドアのところに座ってと言う？傷つかないで！自立への大きな一歩です。心の中で喜んでいいんですよ。', title_ko = '엄마는 저쪽에 앉아 🛑', body_ko = '침대 옆이 아니라 멀리 문 앞에 앉아 있으라고 하나요? 서운해하지 마세요! 독립을 향한 큰 걸음이니 속으로 기뻐하세요.', title_nl = 'Jij gaat daar zitten 🛑', body_nl = 'Eist hij dat je niet naast zijn bed zit, maar ver weg bij de deur? Voel je niet gekwetst! Dit is een grote stap naar zelfstandigheid, vanbinnen mag je blij zijn.', title_pl = 'Ty usiądź z boku 🛑', body_pl = 'Żąda, żebyś siedziała nie przy łóżku, tylko daleko, w drzwiach? Nie obrażaj się! To jego wielki krok ku samodzielności, w duchu powinnaś się cieszyć.', title_pt = 'Tu ficas lá longe 🛑', body_pt = 'Exige que não se sente ao lado da cama dele, mas longe, à porta? Não fique magoada! É um grande passo para a independência, por dentro devia estar contente.', title_sv = 'Du sitter där borta 🛑', body_sv = 'Kräver barnet att du sitter långt bort vid dörren i stället för bredvid sängen? Ta inte illa upp! Det är ett stort steg mot självständighet, inombords borde du glädja dig.', title_vi = 'Mẹ ngồi xa ra 🛑', body_vi = 'Bé đòi mẹ ngồi không phải cạnh giường mà xa, tận ngưỡng cửa? Đừng tự ái! Đó là bước tiến lớn của bé hướng đến sự tự lập, mẹ nên thầm vui mới phải.', title_zh = '你坐远一点 🛑', body_zh = '要你别坐在床边，而是坐远一点，坐到门口？别难过！这是宝宝迈向独立的一大步，你心里应该高兴才对。' WHERE id = '7da643f9-a304-476b-9165-6028a945c141' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pájaro de la ventana es mío 🐦', body_es = '¿Quiere traer a casa el pájaro del patio y llora? Su amor por la naturaleza se desborda. La historia inventada de «Su mamá le está esperando en casa» cambiará al instante esta crisis por calma.', title_fr = 'L''oiseau à la fenêtre est à moi 🐦', body_fr = 'Il veut ramener à la maison l''oiseau de la cour et pleure ? Son amour de la nature déborde. La petite histoire « Sa maman l''attend à la maison » remplacera aussitôt cette crise par la sérénité.', title_hi = 'खिड़की वाली चिड़िया मेरी है 🐦', body_hi = 'आँगन की चिड़िया घर लाना चाहता है और रो रहा है? प्रकृति से प्यार उमड़ रहा है। ‘चिड़िया की माँ घर पर उसका इंतज़ार कर रही है’ वाली छोटी सी कहानी इस संकट को तुरंत सुकून में बदल देगी।', title_id = 'Burung di jendela punyaku 🐦', body_id = 'Ia menangis ingin membawa burung dari halaman ke dalam rumah? Cintanya pada alam meluap-luap. Karangan ''Mama burungnya sedang menunggunya di rumah'' akan langsung mengganti krisis ini dengan ketenangan.', title_ja = '窓の鳥はぼくの 🐦', body_ja = '庭の鳥を家に連れてきたくて泣いている？自然が大好きな気持ちがあふれています。「鳥さんのママがおうちで待っているよ」というお話が、この危機をすぐに安らぎに変えてくれます。', title_ko = '창가의 새는 내 거야 🐦', body_ko = '마당의 새를 집에 데려오겠다며 우나요? 자연 사랑이 넘쳐흘러요. ''새의 엄마가 집에서 기다리고 있어''라는 이야기 하나로 이 위기가 금세 평온으로 바뀔 거예요.', title_nl = 'Die vogel bij het raam is van mij 🐦', body_nl = 'Wil hij de vogel uit de tuin mee naar binnen nemen en huilt hij? Zijn liefde voor de natuur loopt over. Het verzinsel ''De mama van het vogeltje wacht thuis op hem'' verandert deze crisis meteen in rust.', title_pl = 'Ptak za oknem jest mój 🐦', body_pl = 'Chce przynieść do domu ptaszka z podwórka i płacze? Miłość do natury aż kipi. Bajeczka „Mama ptaszka czeka na niego w domu” od razu zamieni ten kryzys w spokój.', title_pt = 'O pássaro da janela é meu 🐦', body_pt = 'Quer trazer para casa o pássaro do quintal e chora? O amor pela natureza transborda. A história inventada "A mãe do pássaro está à espera dele em casa" vai trocar logo esta crise por paz.', title_sv = 'Fågeln i fönstret är min 🐦', body_sv = 'Vill barnet ta in fågeln från gården och gråter? Kärleken till naturen svämmar över. Påhittet ”Fågelns mamma väntar på den hemma” byter genast krisen mot lugn.', title_vi = 'Con chim ngoài cửa sổ là của con 🐦', body_vi = 'Bé khóc đòi mang con chim ngoài sân vào nhà? Tình yêu thiên nhiên đang tràn đầy. Câu chuyện "Mẹ chim đang chờ nó ở nhà" sẽ biến cơn khủng hoảng này thành bình yên ngay lập tức.', title_zh = '窗外的小鸟是我的 🐦', body_zh = '想把院子里的小鸟带回家，还哭了？对大自然的爱满得快溢出来了。编一句“小鸟的妈妈在家等它呢”，就能立刻把这场危机变成平静。' WHERE id = 'b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los miedos nocturnos 👻', body_es = '¿Le da miedo el monstruo de debajo de la cama? Llena de agua un pulverizador vacío y rocía la habitación como si fuera un espantamonstruos mágico. El miedo desaparecerá en un segundo.', title_fr = 'Les peurs nocturnes commencent 👻', body_fr = 'Il a peur du monstre sous le lit ? Remplissez d''eau un vaporisateur vide et vaporisez la chambre comme un spray magique anti-monstres. La peur disparaîtra en une seconde.', title_hi = 'रात के डर शुरू हो रहे हैं 👻', body_hi = 'बिस्तर के नीचे वाले राक्षस से डरता है? खाली स्प्रे बोतल में पानी भरिए और उसे ‘जादुई राक्षस भगाने वाले’ की तरह कमरे में छिड़किए। वह डर सेकंडों में गायब हो जाएगा।', title_id = 'Ketakutan malam dimulai 👻', body_id = 'Ia takut monster di bawah tempat tidur? Isi botol semprot kosong dengan air dan semprotkan ke seluruh kamar sebagai pengusir monster ajaib. Rasa takut itu akan hilang dalam sekejap.', title_ja = '夜のこわさが始まる 👻', body_ja = 'ベッドの下のおばけがこわい？空のスプレーボトルにお水を入れて、魔法のおばけ退散スプレーとして部屋にシュッとしましょう。こわさはすぐに消えますよ。', title_ko = '밤의 두려움이 시작됐어요 👻', body_ko = '침대 밑 괴물이 무섭대요? 빈 분무기에 물을 담아 마법의 괴물 퇴치제처럼 방에 뿌려 주세요. 두려움이 순식간에 사라질 거예요.', title_nl = 'Nachtelijke angsten beginnen 👻', body_nl = 'Is hij bang voor het monster onder het bed? Vul een lege sprayfles met water en spuit het als toverspray tegen monsters door de kamer. Die angst is in een seconde verdwenen.', title_pl = 'Zaczynają się nocne lęki 👻', body_pl = 'Boi się potwora pod łóżkiem? Napełnij wodą pusty spryskiwacz i popryskaj pokój jak magicznym odstraszaczem potworów. Strach zniknie w sekundę.', title_pt = 'Começam os medos noturnos 👻', body_pt = 'Tem medo do monstro debaixo da cama? Encha um borrifador vazio com água e borrife o quarto como se fosse um "spray mágico afasta-monstros". O medo desaparece num segundo.', title_sv = 'Nattliga rädslor börjar 👻', body_sv = 'Är barnet rädd för monstret under sängen? Fyll en tom sprayflaska med vatten och spraya i rummet som en magisk monsterskrämma. Rädslan försvinner på en sekund.', title_vi = 'Nỗi sợ ban đêm bắt đầu 👻', body_vi = 'Bé sợ con quái vật dưới gầm giường? Hãy đổ nước vào một bình xịt rỗng và xịt khắp phòng như "thuốc xua quái vật thần kỳ". Nỗi sợ sẽ biến mất trong tích tắc.', title_zh = '夜晚的恐惧开始了 👻', body_zh = '害怕床底下的怪物？在空喷瓶里装上水，当成魔法驱怪喷雾在房间里喷一喷。恐惧几秒钟就会消失。' WHERE id = '544fb1ce-862b-49f6-8e2e-6b2192929ac3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que me lave los dientes mi dedo 🪥', body_es = '¿Rechaza el cepillo de dientes y quiere lavárselos sí o sí con el dedo? No protestes: también se puede hacer con un dedo limpio con un poquito de pasta. No hagas un drama.', title_fr = 'Je veux me laver les dents avec mon doigt 🪥', body_fr = 'Il refuse la brosse à dents et veut absolument se laver les dents avec son doigt ? Ne protestez pas : on peut aussi le faire avec un doigt propre et un peu de dentifrice, n''en faites pas un drame.', title_hi = 'मेरे दाँत मेरी उँगली साफ़ करे 🪥', body_hi = 'टूथब्रश को मना करता है और उँगली से ही दाँत साफ़ करना चाहता है? विरोध मत कीजिए, थोड़ा सा टूथपेस्ट लगी साफ़ उँगली से भी यह काम हो सकता है, बात का बतंगड़ मत बनाइए।', title_id = 'Aku mau gosok gigi pakai jari 🪥', body_id = 'Ia menolak sikat gigi dan bersikeras membersihkan gigi dengan jarinya? Jangan protes, proses itu juga bisa dilakukan dengan jari bersih yang diolesi sedikit pasta gigi, jangan dibesar-besarkan.', title_ja = '歯は指でみがく 🪥', body_ja = '歯ブラシを拒否して、どうしても指でみがきたい？反対しないで。歯みがき粉を少しつけた清潔な指でも歯みがきはできます。大ごとにしないで。', title_ko = '이는 손가락으로 닦을래 🪥', body_ko = '칫솔을 거부하고 꼭 손가락으로 닦겠다고 하나요? 반대하지 마세요. 치약을 조금 묻힌 깨끗한 손가락으로도 할 수 있어요. 일을 키우지 마세요.', title_nl = 'Mijn vinger poetst mijn tanden 🪥', body_nl = 'Wil hij geen tandenborstel en per se met zijn vinger poetsen? Ga er niet tegenin, met een schone vinger met een klein beetje tandpasta kan het ook, maak er geen groot probleem van.', title_pl = 'Niech mój palec umyje mi zęby 🪥', body_pl = 'Odrzuca szczoteczkę i koniecznie chce myć zęby palcem? Nie sprzeciwiaj się, można to zrobić czystym palcem z odrobiną pasty, nie rób z tego problemu.', title_pt = 'Lavo os dentes com o dedo 🪥', body_pt = 'Recusa a escova de dentes e quer lavá-los com o dedo? Não se oponha: também se pode fazer com um dedo limpo com um pouquinho de pasta. Não faça disto um drama.', title_sv = 'Fingret ska borsta tänderna 🪥', body_sv = 'Vägrar barnet tandborsten och vill absolut borsta med fingret? Protestera inte, det går också att göra med ett rent finger med lite tandkräm på, gör inte saken större än den är.', title_vi = 'Con đánh răng bằng ngón tay 🪥', body_vi = 'Bé từ chối bàn chải và nhất định đòi đánh răng bằng ngón tay? Đừng phản đối, dùng ngón tay sạch với chút kem đánh răng cũng làm được việc đó, đừng làm to chuyện.', title_zh = '用手指刷牙 🪥', body_zh = '拒绝牙刷，非要用手指刷牙？别反对，用干净的手指蘸一点牙膏也能完成，别把小事闹大。' WHERE id = 'b51cc09c-00f6-4b63-945d-9cfceecedfb2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El placer del chocolate secreto 🍫', body_es = '¿Mientras el peque ve la tele, tú te comes un chocolate a escondidas en la cocina? ¡Que aproveche! Para aguantar tantas crisis, es tu barrita de energía más natural. No te culpes.', title_fr = 'Le plaisir du chocolat en cachette 🍫', body_fr = 'Pendant qu''il regarde la télé, vous mangez du chocolat en cachette dans la cuisine ? Bon appétit ! Pour supporter toutes ces crises, c''est votre barre énergétique la plus naturelle, ne vous jugez pas.', title_hi = 'छिपी हुई चॉकलेट का मज़ा 🍫', body_hi = 'बच्चा टीवी देख रहा है और आप रसोई में उससे छिपकर चॉकलेट खा रही हैं? मज़े से खाइए! इतने संकट झेलने के लिए यह आपकी सबसे स्वाभाविक एनर्जी बार है, खुद को दोष मत दीजिए।', title_id = 'Nikmatnya cokelat diam-diam 🍫', body_id = 'Selagi anak menonton TV, Anda diam-diam makan cokelat di dapur? Selamat menikmati! Untuk bertahan menghadapi krisis sebanyak ini, itu bar energi paling alami Anda, jangan salahkan diri.', title_ja = 'こっそりチョコの幸せ 🍫', body_ja = '子どもがテレビを見ている間に、キッチンでこっそりチョコを食べている？めしあがれ！これだけのかんしゃくを乗りきるための、いちばん自然なエナジーバーです。自分を責めないで。', title_ko = '몰래 먹는 초콜릿의 맛 🍫', body_ko = '아이가 TV를 보는 동안 부엌에서 몰래 초콜릿을 먹고 있나요? 맛있게 드세요! 이 많은 위기를 버티는 엄마의 가장 자연스러운 에너지 바예요. 자책하지 마세요.', title_nl = 'Stiekem chocolade snoepen 🍫', body_nl = 'Eet je stiekem chocolade in de keuken terwijl je kind tv kijkt? Eet smakelijk! Om zoveel crisissen te doorstaan is dit je meest natuurlijke energiereep, veroordeel jezelf niet.', title_pl = 'Tajna czekoladowa przyjemność 🍫', body_pl = 'Gdy dziecko ogląda telewizję, w kuchni po kryjomu jesz czekoladę? Smacznego! Żeby znieść tyle kryzysów, to twój najbardziej naturalny baton energetyczny, nie obwiniaj się.', title_pt = 'O prazer do chocolate escondido 🍫', body_pt = 'Enquanto ele vê televisão, come chocolate na cozinha às escondidas? Bom proveito! Para aguentar tantas crises, esta é a sua barra de energia mais natural, não se culpe.', title_sv = 'Den hemliga chokladnjutningen 🍫', body_sv = 'Äter du choklad i smyg i köket medan barnet tittar på tv? Smaklig måltid! För att stå ut med så många kriser är det din mest naturliga energibar, döm inte dig själv.', title_vi = 'Vị ngọt của thanh sô-cô-la bí mật 🍫', body_vi = 'Mẹ lén ăn sô-cô-la trong bếp khi bé đang xem TV? Chúc mẹ ngon miệng! Để chịu đựng ngần ấy "khủng hoảng", đây là thanh năng lượng tự nhiên nhất của mẹ, đừng tự trách mình.', title_zh = '偷偷吃巧克力的快乐 🍫', body_zh = '宝宝看电视时，你躲在厨房偷偷吃巧克力？好好享受吧！为了扛住这么多危机，这是你最天然的能量棒，别责怪自己。' WHERE id = 'e403fe31-012f-4f6b-80cb-45dd719c9f06' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La libertad de la camiseta del revés 👕', body_es = '¿Se ha puesto la camiseta con lo de atrás hacia delante y pasea orgulloso? ¡No lo arregles! Tiene tanta seguridad en sí mismo que solo te queda mirarlo y sentirte orgullosa de este futuro líder de espíritu libre.', title_fr = 'La liberté du t-shirt à l''envers 👕', body_fr = 'Il a mis son t-shirt devant derrière et se promène fièrement ? Ne corrigez pas ! Sa confiance en soi est si grande : regardez de loin ce futur leader à l''esprit libre et soyez fière.', title_hi = 'उल्टी कमीज़ की आज़ादी 👕', body_hi = 'कमीज़ आगे-पीछे उल्टी पहनकर गर्व से घूम रहा है? ठीक मत कीजिए! उसका आत्मविश्वास इतना ऊँचा है, किनारे से देखिए और इस आज़ाद ख्यालों वाले भविष्य के लीडर पर गर्व कीजिए।', title_id = 'Kebebasan baju terbalik 👕', body_id = 'Ia memakai bajunya dengan bagian belakang di depan dan berjalan dengan bangga? Jangan dibetulkan! Rasa percaya dirinya begitu tinggi, saksikan dari samping dan banggalah pada calon pemimpin berjiwa bebas ini.', title_ja = 'うしろ前シャツの自由 👕', body_ja = 'シャツをうしろ前に着て、誇らしげに歩いている？直さないで！自信がそれほど高いんです。そばで見て、この自由な心をもつ未来のリーダーを誇りに思いましょう。', title_ko = '거꾸로 입은 티셔츠의 자유 👕', body_ko = '티셔츠를 앞뒤 거꾸로 입고 뿌듯하게 돌아다니나요? 고치지 마세요! 자신감이 하늘을 찌르니, 옆에서 이 자유로운 영혼의 미래 리더를 자랑스러워해 주세요.', title_nl = 'De vrijheid van een achterstevoren shirt 👕', body_nl = 'Heeft hij zijn shirt achterstevoren aan en loopt hij er trots mee rond? Niet verbeteren! Zijn zelfvertrouwen is zo groot, kijk van een afstand toe en wees trots op deze vrije geest, de leider van de toekomst.', title_pl = 'Wolność koszulki na lewą stronę 👕', body_pl = 'Założył koszulkę tyłem na przód i chodzi z dumą? Nie poprawiaj! Ma tak wysoką pewność siebie, że możesz tylko patrzeć z boku i być dumna z tego wolnego ducha, przyszłego lidera.', title_pt = 'A liberdade da camisola ao contrário 👕', body_pt = 'Vestiu a camisola com as costas para a frente e anda orgulhoso? Não a endireite! A autoconfiança dele está tão alta: observe à distância e orgulhe-se deste futuro líder de espírito livre.', title_sv = 'Friheten i en bakvänd tröja 👕', body_sv = 'Går barnet stolt omkring med tröjan bak och fram? Rätta inte till den! Självförtroendet är så högt, titta på från sidan och var stolt över den här frisinnade framtida ledaren.', title_vi = 'Tự do mặc áo ngược 👕', body_vi = 'Bé mặc áo ngược trước ra sau và tự hào đi khắp nơi? Đừng sửa! Sự tự tin của bé cao đến thế, hãy đứng xa ngắm và tự hào về "nhà lãnh đạo tương lai" có tâm hồn tự do này.', title_zh = '反穿衣服的自由 👕', body_zh = '衣服前后穿反了，还骄傲地走来走去？别去纠正！宝宝的自信满满，在一旁为这个自由灵魂的未来领袖骄傲吧。' WHERE id = '2d98107a-3331-4f7f-8930-8f762e325d02' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una mirada llena de silencio 🥂', body_es = 'El peque duerme y tu pareja y tú os miráis en silencio en el sofá. No decís nada. En realidad, este silencio es la forma más romántica de decir «esto también lo hemos conseguido».', title_fr = 'Un regard plein de silence 🥂', body_fr = 'L''enfant dort, et votre partenaire et vous vous regardez en silence sur le canapé. Vous ne dites rien. Ce silence est en fait la façon la plus romantique de dire « On y est encore arrivés ».', title_hi = 'खामोशी भरी नज़रें 🥂', body_hi = 'बच्चा सो गया, आप और आपका साथी सोफ़े पर चुपचाप एक-दूसरे को देख रहे हैं। कुछ नहीं कह रहे। यह खामोशी असल में ‘यह भी कर लिया’ कहने का सबसे रोमांटिक तरीका है।', title_id = 'Saling pandang dalam hening 🥂', body_id = 'Anak sudah tidur, Anda dan pasangan saling memandang dalam diam di sofa. Tak ada yang bicara. Keheningan ini sebenarnya cara paling romantis untuk berkata ''kita berhasil melewati ini juga''.', title_ja = '静かに見つめ合う 🥂', body_ja = '子どもが寝て、あなたとパートナーはソファで静かに見つめ合う。何も話さない。この静けさこそが「今日も乗りきったね」を伝えるいちばんロマンチックな方法です。', title_ko = '고요 속에 마주한 눈빛 🥂', body_ko = '아이가 잠들고, 배우자와 소파에서 말없이 서로를 바라보고 있나요? 아무 말도 하지 않아요. 이 침묵이야말로 ''오늘도 해냈다''를 말하는 가장 로맨틱한 방법이에요.', title_nl = 'Een blik vol stilte 🥂', body_nl = 'Je kind slaapt, jij en je partner kijken elkaar stil aan op de bank. Jullie zeggen niets. Deze stilte is eigenlijk de meest romantische manier om te zeggen: ''Ook dit hebben we gered.''', title_pl = 'Spojrzenia pełne ciszy 🥂', body_pl = 'Dziecko śpi, a ty i partner w milczeniu patrzycie na siebie na kanapie. Nic nie mówicie. Ta cisza to tak naprawdę najbardziej romantyczny sposób, by powiedzieć „i to nam się udało”.', title_pt = 'Um olhar cheio de silêncio 🥂', body_pt = 'A criança adormeceu e a mãe e o seu companheiro olham um para o outro em silêncio no sofá. Não dizem nada. Na verdade, este silêncio é a forma mais romântica de dizer "também conseguimos isto".', title_sv = 'En blick full av tystnad 🥂', body_sv = 'Barnet sover, och du och din partner tittar tyst på varandra i soffan. Ni säger ingenting. Den tystnaden är egentligen det mest romantiska sättet att säga ”vi klarade det här också”.', title_vi = 'Ánh nhìn trong yên lặng 🥂', body_vi = 'Bé đã ngủ, mẹ và chồng lặng lẽ nhìn nhau trên sofa. Không ai nói gì. Sự im lặng này thật ra là cách lãng mạn nhất để nói "Chúng ta lại làm được rồi".', title_zh = '无声的对视 🥂', body_zh = '宝宝睡了，你和另一半坐在沙发上，静静地看着对方。什么都不说。这份安静，其实就是说“这一关我们也挺过来了”最浪漫的方式。' WHERE id = 'c5aa519b-baae-498e-a13b-bdf83115f0c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El viento me ha empujado 💨', body_es = '¿Se enfada con el viento de la calle y quiere pegarle? Si hubieras mirado antes la herramienta Tiempo y ropa, quizá ni habríais salido. Ahora solo reíos de esta comedia y corred a casa.', title_fr = 'Le vent m''a poussé 💨', body_fr = 'Il est en colère contre le vent dehors et veut le frapper ? Si vous aviez consulté l''outil Météo et tenue avant, vous ne seriez peut-être même pas sortis. Maintenant, riez simplement de cette comédie et rentrez vite à la maison.', title_hi = 'हवा ने मुझे धक्का दिया 💨', body_hi = 'बाहर चलती हवा पर गुस्सा होकर उसे मारना चाहता है? अगर आपने पहले मौसम और कपड़े टूल देख लिया होता, तो शायद आप बाहर निकलते ही नहीं। अब बस इस कॉमेडी पर हँसिए और घर की ओर दौड़िए।', title_id = 'Angin mendorongku 💨', body_id = 'Ia marah pada angin di luar dan ingin memukulnya? Seandainya Anda mengecek Cuaca dan Pakaian lebih dulu, mungkin Anda tidak akan keluar. Sekarang tertawakan saja komedi ini dan berlarilah pulang.', title_ja = '風に押された 💨', body_ja = '外の風に怒って、たたこうとしている？前もって「天気と服装」を見ていたら、出かけなかったかもしれませんね。今はこのコメディに笑って、おうちへ走って帰りましょう。', title_ko = '바람이 나를 밀었어 💨', body_ko = '밖에서 부는 바람에 화가 나서 때리려고 하나요? 날씨와 옷차림 도구를 미리 봤다면 아예 안 나왔을지도 몰라요. 지금은 이 코미디에 웃으며 집으로 뛰어가세요.', title_nl = 'De wind duwde me 💨', body_nl = 'Is hij boos op de wind buiten en wil hij hem slaan? Als je vooraf in Weer en kleding had gekeken, was je misschien niet eens naar buiten gegaan. Lach nu gewoon om deze komedie en ren naar huis.', title_pl = 'Wiatr mnie popchnął 💨', body_pl = 'Złości się na wiatr na dworze i chce go uderzyć? Gdybyś wcześniej zajrzała do narzędzia Pogoda i ubiór, może w ogóle byście nie wyszli. Teraz po prostu pośmiejcie się z tej komedii i biegnijcie do domu.', title_pt = 'O vento empurrou-me 💨', body_pt = 'Zangou-se com o vento lá fora e quer bater-lhe? Se tivesse visto antes a ferramenta Tempo e Roupa, talvez nem tivessem saído. Agora riam-se desta comédia e corram para casa.', title_sv = 'Vinden knuffade mig 💨', body_sv = 'Är barnet argt på vinden ute och vill slå den? Hade du kollat Väder och kläder i förväg hade ni kanske inte ens gått ut. Nu får ni bara skratta åt komedin och springa hem.', title_vi = 'Gió đẩy con 💨', body_vi = 'Bé tức giận với cơn gió ngoài trời và muốn đánh nó? Giá mà mẹ xem Thời tiết và trang phục trước, có lẽ đã chẳng ra ngoài. Giờ chỉ cần cười trước màn hài kịch này và chạy về nhà thôi.', title_zh = '风推我！💨', body_zh = '对着外面刮的风生气，想打它？如果提前看过天气与穿衣工具，可能根本就不出门了。现在就笑着看这出喜剧，赶紧跑回家吧。' WHERE id = 'eaade7fe-4846-47fa-9bc5-4c49360a0a4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Arte en el suelo 🎨', body_es = '¿Ha hecho un dibujo con pasta seca en medio de la habitación y te mira orgulloso? Olvida la limpieza y sonríele.', title_fr = 'L''art au sol 🎨', body_fr = 'Au milieu de la pièce, il a dessiné avec des pâtes sèches et vous regarde fièrement ? Oubliez le ménage, souriez-lui.', title_hi = 'फ़र्श पर कला 🎨', body_hi = 'कमरे के बीच सूखे पास्ता से तस्वीर बनाकर गर्व से आपको देख रहा है? सफ़ाई छोड़िए, उसे देखकर मुस्कुराइए।', title_id = 'Seni di lantai 🎨', body_id = 'Ia menggambar dengan makaroni kering di tengah kamar dan memandang Anda dengan bangga? Lupakan bersih-bersih, tersenyumlah padanya.', title_ja = '床のアート 🎨', body_ja = '部屋のまん中に乾いたパスタで絵をかいて、誇らしげにあなたを見ている？お片づけは気にしないで、ほほえんであげましょう。', title_ko = '바닥 위의 예술 🎨', body_ko = '방 한가운데 마른 파스타로 그림을 그려 놓고 뿌듯하게 엄마를 보나요? 청소는 잊고 미소 지어 주세요.', title_nl = 'Vloerkunst 🎨', body_nl = 'Heeft hij midden in de kamer een schilderij van droge pasta gemaakt en kijkt hij je trots aan? Laat het opruimen, glimlach naar hem.', title_pl = 'Sztuka na podłodze 🎨', body_pl = 'Na środku pokoju ułożył obraz z suchego makaronu i patrzy na ciebie z dumą? Odpuść sprzątanie i się do niego uśmiechnij.', title_pt = 'Arte no chão 🎨', body_pt = 'No meio do quarto fez um desenho com massa seca e olha para si cheio de orgulho? Esqueça a limpeza e sorria-lhe.', title_sv = 'Golvkonst 🎨', body_sv = 'Har barnet gjort en bild av torr pasta mitt i rummet och tittar stolt på dig? Strunta i städningen och le mot barnet.', title_vi = 'Nghệ thuật trên sàn nhà 🎨', body_vi = 'Bé vẽ một bức tranh bằng mì ống khô giữa phòng và tự hào nhìn mẹ? Kệ việc dọn dẹp đi, hãy mỉm cười với bé.', title_zh = '地板艺术 🎨', body_zh = '在房间中间用干意面拼了一幅画，骄傲地看着你？别管打扫了，对宝宝笑一笑吧。' WHERE id = '77606aaa-e2aa-442d-992d-f4dce779d9e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá que da sueño 📖', body_es = '¿Tienes la voz cansada y no te apetece leer el cuento? Pásale la pelota a papá. Su tono de voz distinto y grave y los detalles absurdos que se invente hipnotizarán antes al peque.', title_fr = 'Le conte de papa qui endort 📖', body_fr = 'Votre voix est fatiguée et vous n''avez pas envie de lire le conte ? Passez la balle à papa. Sa voix différente et grave, et les détails absurdes qu''il invente, hypnotiseront l''enfant plus vite.', title_hi = 'पापा की नींद लाने वाली कहानी 📖', body_hi = 'आपकी आवाज़ थक गई है, कहानी पढ़ने का मन नहीं? गेंद पापा के पाले में डालिए। उनकी अलग, भारी आवाज़ और गढ़ी हुई बेतुकी बातें बच्चे पर जल्दी जादू कर देंगी।', title_id = 'Dongeng pengantar tidur dari Ayah 📖', body_id = 'Suara Anda lelah dan tidak ingin membacakan dongeng? Oper bolanya ke Ayah. Suaranya yang berbeda dan berat serta detail-detail absurd karangannya akan lebih cepat menghipnosis anak.', title_ja = 'パパの眠くなるお話 📖', body_ja = '声が疲れて、お話を読みたくない？ボールはパパにパス。いつもとちがう低い声と、パパが考えたおかしなディテールが、子どもをもっと早く眠りに誘います。', title_ko = '잠이 오는 아빠의 동화 📖', body_ko = '목소리도 지치고 동화 읽기도 싫은가요? 공을 아빠에게 넘기세요. 아빠의 다르고 굵은 목소리와 지어낸 엉뚱한 이야기가 아이를 더 빨리 잠들게 할 거예요.', title_nl = 'Papa''s slaapverwekkende sprookje 📖', body_nl = 'Is je stem moe en heb je geen zin om voor te lezen? Speel de bal door naar papa. Zijn andere, zware stem en de absurde details die hij verzint, hypnotiseren je kind veel sneller.', title_pl = 'Usypiająca bajka taty 📖', body_pl = 'Twój głos jest zmęczony i nie chcesz czytać bajki? Przekaż piłeczkę tacie. Jego inny, niski głos i wymyślone absurdalne szczegóły szybciej zahipnotyzują dziecko.', title_pt = 'A história do pai que dá sono 📖', body_pt = 'Tem a voz cansada e não lhe apetece ler a história? Passe a bola ao pai. A voz grossa e diferente dele e os pormenores absurdos que inventa vão hipnotizar a criança mais depressa.', title_sv = 'Pappas sövande saga 📖', body_sv = 'Är rösten trött och du orkar inte läsa sagan? Skicka bollen till pappa. Hans annorlunda, djupa röst och de absurda detaljerna han hittar på hypnotiserar barnet snabbare.', title_vi = 'Câu chuyện ru ngủ của bố 📖', body_vi = 'Giọng mẹ đã mệt, mẹ không muốn đọc truyện nữa? Hãy chuyền bóng cho bố. Giọng trầm ấm khác lạ của bố cùng những chi tiết vô lý bố tự nghĩ ra sẽ "thôi miên" bé nhanh hơn.', title_zh = '爸爸的催眠故事 📖', body_zh = '嗓子累了，不想讲故事？把球传给爸爸。爸爸不一样的低沉嗓音和编出来的荒诞细节，会更快让宝宝“被催眠”。' WHERE id = '92c59586-e756-4176-87f0-6ee0836bd1f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Me duele el pelo 🪮', body_es = '¿Peinarlo es una tortura? Humedécele un poco el pelo con un pulverizador de agua y lleva su atención a las caras graciosas que pones en el espejo. En cuanto se distraiga, péinalo y listo.', title_fr = 'Mes cheveux me font mal 🪮', body_fr = 'Se faire coiffer, c''est la mort ? Humidifiez légèrement ses cheveux avec un vaporisateur d''eau et détournez son attention vers les grimaces que vous faites dans le miroir. Dès qu''il est distrait, coiffez-le et c''est fini.', title_hi = 'मेरे बाल मुझे दुखाते हैं 🪮', body_hi = 'बाल सँवारना मानो मौत के बराबर है? पानी के स्प्रे से हल्का गीला कीजिए और उसका ध्यान आईने में आपके बनाए मज़ेदार चेहरों पर लगाइए। जैसे ही ध्यान भटके, कंघी करके काम खत्म कीजिए।', title_id = 'Rambutku sakit 🪮', body_id = 'Menyisir rambut sama dengan siksaan? Basahi sedikit dengan semprotan air, dan alihkan perhatiannya ke wajah-wajah lucu yang Anda buat di cermin. Begitu ia teralihkan, sisir dan selesaikan.', title_ja = '髪がいたいの 🪮', body_ja = '髪をとかすのは一大事？水スプレーで軽くぬらして、鏡の前でおもしろい顔をして気をそらしましょう。気がそれた瞬間にとかして終わりです。', title_ko = '머리가 아파 🪮', body_ko = '머리 빗기가 세상에서 제일 싫은가요? 분무기로 살짝 적시고, 거울 속 엄마의 웃긴 표정으로 관심을 돌리세요. 정신이 팔린 사이에 얼른 빗어 끝내세요.', title_nl = 'Mijn haar doet pijn 🪮', body_nl = 'Is haren kammen een kwestie van leven of dood? Maak het een beetje nat met een waterspray en leid zijn aandacht af met gekke gezichten in de spiegel. Op het moment dat hij afgeleid is, kam je het snel en klaar.', title_pl = 'Włosy mnie bolą 🪮', body_pl = 'Czesanie to dla niego koniec świata? Lekko zwilż włosy spryskiwaczem z wodą, a jego uwagę skieruj na śmieszne miny, które robisz w lustrze. Gdy tylko się rozproszy, szybko go uczesz.', title_pt = 'O cabelo dói-me 🪮', body_pt = 'Pentear o cabelo é pior do que a morte? Humedeça-o ligeiramente com um borrifador de água e desvie a atenção dele para as caretas cómicas que faz ao espelho. Assim que se distrair, penteie e despache.', title_sv = 'Håret gör ont 🪮', body_sv = 'Är det som döden att kamma håret? Fukta lätt med en vattenspray och led uppmärksamheten till de roliga grimaserna du gör i spegeln. I samma stund som barnet blir distraherat kammar du klart.', title_vi = 'Tóc làm con đau 🪮', body_vi = 'Chải tóc với bé chẳng khác gì cực hình? Hãy xịt chút nước cho tóc hơi ẩm, rồi kéo sự chú ý của bé vào những nét mặt hài hước mẹ làm trong gương. Bé vừa xao nhãng là mẹ chải xong ngay.', title_zh = '梳头好痛 🪮', body_zh = '梳头简直像受刑？用喷水壶轻轻喷湿头发，再在镜子里做几个搞笑的鬼脸吸引宝宝的注意力。趁宝宝分心，一下子梳完。' WHERE id = 'dc97d51e-f4af-4633-84e4-fbe0fbe9e15a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Adónde se ha ido el cielo? ☁️', body_es = '¿Te ha dejado en blanco con una pregunta filosófica repentina en un día de niebla? Dile «Las nubes lo han tapado para que no pase frío». Su cerebro aún no está listo para la explicación científica, solo quiere un cuento.', title_fr = 'Où est passé le ciel ? ☁️', body_fr = 'Par temps de brouillard, sa question philosophique soudaine vous a figé le cerveau ? Dites « Les nuages l''ont recouvert pour qu''il n''ait pas froid ». Son cerveau n''est pas encore prêt pour une explication scientifique, il veut juste une histoire.', title_hi = 'आसमान कहाँ चला गया? ☁️', body_hi = 'धुँधले मौसम में उसके अचानक पूछे दार्शनिक सवाल ने आपका दिमाग जमा दिया? कहिए, ‘बादलों ने उसे ढक दिया ताकि उसे ठंड न लगे।’ उसका दिमाग अभी वैज्ञानिक व्याख्या के लिए तैयार नहीं, उसे बस कहानी चाहिए।', title_id = 'Langitnya pergi ke mana? ☁️', body_id = 'Pertanyaan filosofis mendadak di hari berkabut membuat otak Anda membeku? Katakan ''Awan menyelimutinya supaya tidak kedinginan'', otaknya belum siap untuk penjelasan ilmiah, ia hanya ingin dongeng.', title_ja = 'お空はどこへ行ったの？ ☁️', body_ja = 'くもりの日に急にとんできた哲学的な質問に、頭がフリーズ？「雲がお空をおおってあげたの、寒くないようにね」と言いましょう。科学的な説明の準備はまだできていなくて、ただお話がほしいんです。', title_ko = '하늘은 어디 갔어? ☁️', body_ko = '안개 낀 날 갑자기 던진 철학적 질문에 머리가 굳었나요? ''구름이 하늘이 춥지 않게 덮어 줬어''라고 말해 주세요. 아직 과학적 설명을 받아들일 준비가 안 됐어요, 그저 동화를 원할 뿐이에요.', title_nl = 'Waar is de lucht gebleven? ☁️', body_nl = 'Bevroor je brein bij zijn plotselinge filosofische vraag op een mistige dag? Zeg: ''De wolken hebben hem toegedekt zodat hij het niet koud krijgt.'' Zijn brein is nog niet klaar voor een wetenschappelijke uitleg, hij wil gewoon een sprookje.', title_pl = 'Gdzie się podziało niebo? ☁️', body_pl = 'Nagłe filozoficzne pytanie w mglisty dzień zamroziło ci mózg? Powiedz: „Chmury je przykryły, żeby nie zmarzło”, jego mózg nie jest jeszcze gotowy na naukowe wyjaśnienia, chce po prostu bajki.', title_pt = 'Para onde foi o céu? ☁️', body_pt = 'Num dia de nevoeiro, a pergunta filosófica repentina dele deixou-a sem reação? Diga "As nuvens taparam-no para não ter frio". O cérebro dele ainda não está pronto para explicações científicas, só quer uma história.', title_sv = 'Vart tog himlen vägen? ☁️', body_sv = 'Frös hjärnan till av en plötslig filosofisk fråga en dimmig dag? Säg ”Molnen har bäddat in den så att den inte fryser”. Barnets hjärna är inte redo för en vetenskaplig förklaring än, hen vill bara ha en saga.', title_vi = 'Bầu trời đi đâu rồi? ☁️', body_vi = 'Câu hỏi triết lý bất chợt của bé trong ngày sương mù làm đầu mẹ đơ ra? Hãy nói: "Mây đắp chăn cho bầu trời để nó không bị lạnh." Não bé chưa sẵn sàng cho lời giải thích khoa học, bé chỉ muốn một câu chuyện cổ tích.', title_zh = '天空去哪儿了？☁️', body_zh = '雾蒙蒙的天气里，宝宝突然问的哲学问题让你脑子一下卡住了？就说“云朵把天空盖起来了，免得它着凉”。宝宝的大脑还没准备好听科学解释，只想听个童话。' WHERE id = '1752e8bc-24e4-4f1b-97e5-c557a4522bda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Salir corriendo en medio del súper 🛒', body_es = '¿Delante de la caja sale corriendo de repente y se esconde detrás de las estanterías? Lleva la Lista de la compra en digital para que, en esos momentos de pánico, no se te olvide lo que te falta y no vuelvas a casa con las manos vacías.', title_fr = 'Il s''enfuit au milieu du supermarché 🛒', body_fr = 'Devant la caisse, il s''enfuit soudain et se cache derrière les rayons ? Tenez votre Liste de courses en version numérique, pour ne pas oublier dans ces moments de panique ce qu''il vous reste à acheter et rentrer les mains vides.', title_hi = 'सुपरमार्केट के बीच भाग जाना 🛒', body_hi = 'काउंटर के सामने अचानक भागकर रैक के पीछे छिप जाता है? शॉपिंग लिस्ट डिजिटल रखिए, ताकि ऐसे घबराहट वाले पलों में आप भूलें नहीं कि क्या लेना बाकी है और खाली हाथ घर न लौटें।', title_id = 'Kabur di tengah supermarket 🛒', body_id = 'Di depan kasir ia tiba-tiba lari dan bersembunyi di balik rak? Simpan Daftar Belanja secara digital, supaya di saat panik seperti ini Anda tidak lupa apa saja yang belum dibeli dan pulang dengan tangan kosong.', title_ja = 'スーパーのまん中で逃走 🛒', body_ja = 'レジの前で急に走り出して、棚のうしろに隠れる？「買い物リスト」をデジタルで管理しておけば、こんなパニックのときも買い忘れを防げて、手ぶらで帰らずにすみます。', title_ko = '마트 한가운데서 도망치기 🛒', body_ko = '계산대 앞에서 갑자기 뛰어가 진열대 뒤에 숨나요? 쇼핑 목록을 디지털로 관리해 두세요. 이런 당황스러운 순간에도 안 산 걸 잊고 빈손으로 돌아오지 않게요.', title_nl = 'Wegrennen midden in de supermarkt 🛒', body_nl = 'Rent hij bij de kassa ineens weg en verstopt hij zich achter de schappen? Houd je boodschappenlijstje digitaal bij, zodat je in zo''n paniekmoment niet vergeet wat je nog moest kopen en niet met lege handen thuiskomt.', title_pl = 'Ucieczka na środku sklepu 🛒', body_pl = 'Przed kasą nagle ucieka i chowa się za regałami? Prowadź Listę zakupów cyfrowo, żeby w takich chwilach paniki nie zapomnieć, czego jeszcze nie kupiłaś, i nie wrócić do domu z pustymi rękami.', title_pt = 'Fugir no meio do supermercado 🛒', body_pt = 'De repente foge em frente à caixa e esconde-se atrás das prateleiras? Tenha a Lista de Compras em formato digital para que, nestes momentos de pânico, não se esqueça do que falta comprar e não volte para casa de mãos a abanar.', title_sv = 'Att springa iväg mitt i affären 🛒', body_sv = 'Springer barnet plötsligt iväg framför kassan och gömmer sig bakom hyllorna? Ha inköpslistan digitalt, så att du inte i sådana panikstunder glömmer vad du inte har köpt och kommer hem tomhänt.', title_vi = 'Chạy trốn giữa siêu thị 🛒', body_vi = 'Đang ở quầy thu ngân, bé bỗng chạy đi trốn sau các kệ hàng? Hãy lưu Danh sách mua sắm trên điện thoại, để trong những lúc hoảng loạn như vậy mẹ không quên những món chưa mua và về nhà tay không.', title_zh = '在超市里乱跑 🛒', body_zh = '在收银台前突然跑开，躲到货架后面？把购物清单存在手机上，这样在这种慌乱时刻，也不会忘了还有什么没买，空着手回家。' WHERE id = '2d5bfd88-008f-4b96-a72a-390cdfe7c90d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de los susurros 🤫', body_es = '¿Corre gritando y no quiere dormir? Baja la voz del todo de repente. Empieza a hablar muy bajito, en susurros. Se concentrará para oírte y le entrará sueño.', title_fr = 'Le jeu du chuchotement 🤫', body_fr = 'Il court en criant et ne veut pas dormir ? Baissez soudain complètement la voix. Mettez-vous à parler très bas, en chuchotant. Pour vous entendre, il se concentrera et le sommeil viendra.', title_hi = 'फुसफुसाहट वाला खेल 🤫', body_hi = 'चिल्लाते हुए भाग रहा है, सोना नहीं चाहता? अचानक अपनी आवाज़ पूरी तरह धीमी कर दीजिए। बहुत हल्के से फुसफुसाकर बोलना शुरू कीजिए। आपको सुनने के लिए वह ध्यान लगाएगा और उसे नींद आने लगेगी।', title_id = 'Permainan berbisik 🤫', body_id = 'Ia berlarian sambil berteriak dan tidak mau tidur? Tiba-tiba kecilkan suara Anda sepenuhnya. Mulailah berbicara sangat pelan sambil berbisik. Ia akan memusatkan perhatian untuk mendengar Anda, dan kantuknya akan datang.', title_ja = 'ささやきゲーム 🤫', body_ja = '叫びながら走りまわって、寝たがらない？急に声をぐっと落として、とても小さなささやき声で話し始めましょう。聞きとろうと集中するうちに、眠くなってきます。', title_ko = '속삭임 놀이 🤫', body_ko = '소리 지르며 뛰어다니고 안 자려 하나요? 갑자기 목소리를 완전히 낮추세요. 아주 작게 속삭이며 말하기 시작하면, 엄마 말을 들으려 집중하다가 졸음이 올 거예요.', title_nl = 'Het fluisterspel 🤫', body_nl = 'Rent hij gillend rond en wil hij niet slapen? Laat je stem ineens helemaal wegzakken. Ga heel zacht fluisterend praten. Om je te horen moet hij zich concentreren, en dan komt de slaap vanzelf.', title_pl = 'Zabawa w szeptanie 🤫', body_pl = 'Biega z krzykiem i nie chce spać? Nagle całkiem ścisz głos. Zacznij mówić bardzo cicho, szeptem. Żeby cię usłyszeć, skupi uwagę i przyjdzie sen.', title_pt = 'O jogo dos sussurros 🤫', body_pt = 'Corre aos gritos e não quer dormir? Baixe de repente a voz por completo. Comece a falar muito baixinho, em sussurro. Para a ouvir, vai ter de se concentrar e o sono vai chegar.', title_sv = 'Viskleken 🤫', body_sv = 'Springer barnet runt och skriker och vill inte sova? Dämpa plötsligt rösten helt. Börja prata väldigt tyst och viskande. Barnet koncentrerar sig för att höra dig och blir sömnigt.', title_vi = 'Trò chơi thì thầm 🤫', body_vi = 'Bé vừa la hét vừa chạy, không chịu ngủ? Hãy đột ngột hạ giọng hoàn toàn. Bắt đầu nói thì thầm thật nhỏ. Bé sẽ tập trung để nghe mẹ và cơn buồn ngủ sẽ đến.', title_zh = '悄悄话游戏 🤫', body_zh = '尖叫着到处跑，不想睡觉？突然把声音完全压低。用很轻很轻的悄悄话说话。为了听清你，宝宝会集中注意力，困意就来了。' WHERE id = '5c94e9c6-00cb-4c58-b265-f248e6c3e544' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No soy una madre perfecta 🛑', body_es = '¿Hoy todo ha salido del revés y has gritado? No te arrincones. Escribe en el Diario de ánimo solo esto: «Hoy ha sido un mal día, pero soy una buena madre y mañana lo volveré a intentar».', title_fr = 'Je ne suis pas une maman parfaite 🛑', body_fr = 'Aujourd''hui, tout est parti de travers et vous avez crié ? Ne vous acculez pas. Écrivez simplement dans le Journal d''humeur : « Aujourd''hui, ça s''est mal passé, mais je suis une bonne maman et demain je réessaierai. »', title_hi = 'मैं परफ़ेक्ट माँ नहीं हूँ 🛑', body_hi = 'आज सब उलट-पुलट हो गया और आप चिल्ला पड़ीं? खुद को कोने में मत धकेलिए। मूड डायरी में बस लिखिए: ‘आज का दिन बुरा था, पर मैं अच्छी माँ हूँ और कल फिर कोशिश करूँगी।’', title_id = 'Aku bukan ibu yang sempurna 🛑', body_id = 'Hari ini semuanya kacau dan Anda berteriak? Jangan menyudutkan diri sendiri. Tulis saja di Buku Harian Suasana Hati: ''Hari ini buruk, tapi aku ibu yang baik dan besok aku akan mencoba lagi.''', title_ja = '完璧なママじゃない 🛑', body_ja = '今日は何もかもめちゃくちゃで、怒鳴ってしまった？自分を追いつめないで。「気分日記」にただこう書きましょう。「今日はうまくいかなかった。でもわたしはいいママだし、明日またがんばる」。', title_ko = '나는 완벽한 엄마가 아니에요 🛑', body_ko = '오늘 모든 게 엉망이 되고 소리를 질렀나요? 자신을 몰아세우지 마세요. 기분 일기에 이렇게만 쓰세요: ''오늘은 힘들었지만 나는 좋은 엄마이고, 내일 다시 해 볼 거야.''', title_nl = 'Ik ben geen perfecte mama 🛑', body_nl = 'Liep vandaag alles in de soep en heb je geschreeuwd? Zet jezelf niet in de hoek. Schrijf gewoon in je Stemmingsdagboek: ''Vandaag was zwaar, maar ik ben een goede mama en morgen probeer ik het opnieuw.''', title_pl = 'Nie jestem idealną mamą 🛑', body_pl = 'Dziś wszystko poszło nie tak i krzyknęłaś? Nie zapędzaj się w kozi róg. Po prostu napisz w Dzienniku nastroju: „Dziś był zły dzień, ale jestem dobrą mamą i jutro spróbuję jeszcze raz”.', title_pt = 'Não sou uma mãe perfeita 🛑', body_pt = 'Hoje correu tudo mal e gritou? Não se encurrale. Escreva simplesmente no Diário de Humor: "Hoje foi um mau dia, mas sou uma boa mãe e amanhã volto a tentar".', title_sv = 'Jag är ingen perfekt mamma 🛑', body_sv = 'Gick allt snett i dag och du skrek? Tryck inte in dig själv i ett hörn. Skriv bara i Humördagboken: I dag gick det dåligt, men jag är en bra mamma och i morgon försöker jag igen.', title_vi = 'Mẹ không phải người mẹ hoàn hảo 🛑', body_vi = 'Hôm nay mọi thứ đảo lộn và mẹ đã quát lên? Đừng tự dồn mình vào góc. Hãy viết vào Nhật ký tâm trạng: "Hôm nay thật tệ, nhưng mình là một người mẹ tốt và ngày mai mình sẽ thử lại."', title_zh = '我不是完美妈妈 🛑', body_zh = '今天一切都乱套了，你还吼了？别把自己逼到墙角。在心情日记里写下：“今天过得很糟，但我是个好妈妈，明天我会再试一次。”' WHERE id = '22c6ff37-5069-489b-9d49-2a97d14d2e2e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento con sonido de lluvia 🌧️', body_es = '¿Te has quedado sin voz y sin fuerzas para leer el cuento? En Cuentos inteligentes pon de fondo solo el sonido de la lluvia y del bosque. A veces esta calma de la naturaleza duerme antes que el mejor cuento.', title_fr = 'Un conte au son de la pluie 🌧️', body_fr = 'Vous n''avez plus de voix ni la force de lire un conte ? Dans les Contes intelligents, mettez seulement en fond le son de la pluie et de la forêt. Ce calme de la nature endort parfois plus vite que le meilleur des contes.', title_hi = 'बारिश की आवाज़ वाली कहानी 🌧️', body_hi = 'आवाज़ नहीं निकल रही, कहानी पढ़ने की ताकत नहीं? स्मार्ट कहानियों में बस बारिश और जंगल की आवाज़ बैकग्राउंड में चलाइए। प्रकृति की यह शांति कभी-कभी सबसे अच्छी कहानी से भी जल्दी सुला देती है।', title_id = 'Dongeng dengan suara hujan 🌧️', body_id = 'Suara Anda habis dan tak punya tenaga membacakan dongeng? Di Dongeng Pintar, putar saja suara hujan dan hutan sebagai latar. Ketenangan alam ini kadang lebih cepat membawanya tidur daripada dongeng terbaik.', title_ja = '雨の音のお話 🌧️', body_ja = '声が出ない、お話を読む元気がない？「スマートおはなし」で、雨と森の音だけを背景に流しましょう。自然の静けさは、ときにどんなお話よりも早く眠りへ連れていってくれます。', title_ko = '빗소리 동화 🌧️', body_ko = '목소리도 안 나오고 동화 읽을 힘도 없나요? 스마트 동화에서 빗소리와 숲 소리만 배경으로 틀어 두세요. 자연의 이 고요가 때로는 최고의 동화보다 더 빨리 잠들게 해 줘요.', title_nl = 'Een sprookje met regengeluid 🌧️', body_nl = 'Is je stem op en heb je geen kracht om voor te lezen? Zet in Slimme sprookjes alleen regen- en bosgeluiden op de achtergrond aan. Deze stilte van de natuur laat hem soms sneller in slaap vallen dan het beste sprookje.', title_pl = 'Bajka z odgłosem deszczu 🌧️', body_pl = 'Nie masz głosu ani siły, by czytać bajkę? Włącz w Mądrych bajkach w tle tylko szum deszczu i lasu. Ta cisza natury czasem usypia szybciej niż najlepsza bajka.', title_pt = 'Uma história com som de chuva 🌧️', body_pt = 'Ficou sem voz e não tem forças para ler uma história? Nas Histórias Inteligentes, ponha de fundo apenas o som da chuva e da floresta. Este sossego da natureza às vezes adormece-o mais depressa do que a melhor história.', title_sv = 'Saga med regnljud 🌧️', body_sv = 'Har du ingen röst kvar och orkar inte läsa saga? Sätt bara på regn- och skogsljud som bakgrund i Smarta sagor. Naturens stillhet får ibland barnet att somna snabbare än den bästa sagan.', title_vi = 'Câu chuyện có tiếng mưa 🌧️', body_vi = 'Mẹ khản giọng, không còn sức đọc truyện? Trong Truyện cổ tích thông minh, chỉ cần bật tiếng mưa và tiếng rừng làm nền. Sự tĩnh lặng của thiên nhiên đôi khi đưa bé vào giấc ngủ nhanh hơn cả câu chuyện hay nhất.', title_zh = '有雨声的童话 🌧️', body_zh = '嗓子哑了，没力气讲故事？在智慧童话里只把雨声和森林声当背景打开。大自然的这份宁静，有时比最好的故事更快让人入睡。' WHERE id = '39a82edc-fce3-4cb5-8ef7-be6b2f9a1122' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No me cojas la mano! 🚶‍♂️', body_es = '¿Por el camino te suelta la mano y quiere ir libre? Si es una zona segura, deja que ponga a prueba su independencia y tú síguelo con orgullo dos pasos por detrás.', title_fr = 'Me tiens pas la main ! 🚶‍♂️', body_fr = 'Dans la rue, il lâche votre main et veut marcher librement ? Si la zone est sûre, laissez-le tester son indépendance, et suivez-le simplement deux pas derrière, avec fierté.', title_hi = 'मेरा हाथ मत पकड़ो! 🚶‍♂️', body_hi = 'रास्ते में हाथ छुड़ाकर आज़ाद चलना चाहता है? अगर जगह सुरक्षित है, तो उसे अपनी आत्मनिर्भरता परखने दीजिए, आप बस दो कदम पीछे से गर्व से उसे देखिए।', title_id = 'Jangan pegang tanganku! 🚶‍♂️', body_id = 'Di jalan ia melepaskan tangan Anda dan ingin berjalan bebas? Kalau areanya aman, biarkan ia menguji kemandiriannya, Anda cukup mengikutinya dengan bangga dua langkah di belakang.', title_ja = '手をつながないで！ 🚶‍♂️', body_ja = '道で手をはなして、自由に歩きたがる？安全な場所なら、自立をためさせてあげましょう。あなたは2歩うしろから誇らしく見守るだけでOK。', title_ko = '손 잡지 마! 🚶‍♂️', body_ko = '길에서 손을 놓고 혼자 걷고 싶어 하나요? 안전한 곳이라면 독립심을 시험하게 두고, 엄마는 두 걸음 뒤에서 뿌듯하게 지켜봐 주세요.', title_nl = 'Niet mijn hand vasthouden! 🚶‍♂️', body_nl = 'Laat hij onderweg je hand los en wil hij zelf lopen? Is het een veilige plek, laat hem dan zijn zelfstandigheid testen en loop gewoon trots twee stappen achter hem.', title_pl = 'Nie trzymaj mnie za rękę! 🚶‍♂️', body_pl = 'Na spacerze puszcza twoją rękę i chce iść sam? Jeśli to bezpieczna strefa, niech sprawdzi swoją samodzielność, a ty po prostu idź dwa kroki za nim i patrz z dumą.', title_pt = 'Não me dês a mão! 🚶‍♂️', body_pt = 'Na rua larga-lhe a mão e quer andar sozinho? Se a zona for segura, deixe-o testar a sua independência e limite-se a segui-lo com orgulho, dois passos atrás.', title_sv = 'Håll mig inte i handen! 🚶‍♂️', body_sv = 'Vill barnet släppa din hand och gå fritt på vägen? Om det är en säker zon, låt hen testa sin självständighet, och följ bara efter stolt två steg bakom.', title_vi = 'Đừng nắm tay con! 🚶‍♂️', body_vi = 'Trên đường, bé muốn buông tay mẹ và tự đi? Nếu là khu vực an toàn, hãy để bé thử sự tự lập của mình, mẹ chỉ cần tự hào đi theo sau hai bước.', title_zh = '别牵我的手！🚶‍♂️', body_zh = '走在路上，想松开你的手自己走？如果是安全的地方，就让宝宝试试自己的独立吧，你只要在后面两步远的地方骄傲地看着。' WHERE id = '69d7d720-ce5e-441e-ac6e-b3151e6557c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi cuerpo no es mío 🔋', body_es = '¿Tienes el cuerpo entumecido de que se te suba encima todo el día? Deja al peque 5 minutos solo en la habitación, cierra la puerta, cierra los ojos y respira hondo. Necesitas recuperarte.', title_fr = 'Mon corps ne m''appartient plus 🔋', body_fr = 'Votre corps est engourdi à force qu''il grimpe sur vous toute la journée ? Laissez l''enfant seul dans la pièce 5 minutes, fermez simplement la porte, fermez les yeux et respirez profondément. Vous devez récupérer.', title_hi = 'मेरा शरीर मेरा नहीं रहा 🔋', body_hi = 'दिनभर आप पर चढ़ने से आपका शरीर सुन्न हो गया? 5 मिनट बच्चे को कमरे में अकेला छोड़िए, बस दरवाज़ा बंद कीजिए, आँखें मूँदिए और गहरी साँस लीजिए। आपको फिर से ऊर्जा चाहिए।', title_id = 'Tubuhku bukan milikku 🔋', body_id = 'Tubuh Anda mati rasa karena seharian dipanjat? Tinggalkan anak sendirian di kamar selama 5 menit, tutup pintu, pejamkan mata, dan tarik napas dalam. Anda perlu memulihkan diri.', title_ja = 'わたしの体はわたしのものじゃない 🔋', body_ja = '一日じゅうよじ登られて、体がしびれた？5分だけ子どもを部屋でひとりにして、ドアを閉め、目を閉じて深呼吸を。あなたには回復が必要です。', title_ko = '내 몸이 내 것이 아닌 느낌 🔋', body_ko = '하루 종일 아이가 기어올라서 몸이 저리나요? 5분만 아이를 방에 혼자 두고 문을 닫은 뒤, 눈을 감고 깊게 숨 쉬세요. 엄마도 회복이 필요해요.', title_nl = 'Mijn lichaam is niet van mij 🔋', body_nl = 'Is je lichaam stijf van de hele dag beklommen worden? Laat je kind 5 minuten alleen in de kamer, doe gewoon de deur dicht, sluit je ogen en haal diep adem. Je moet herstellen.', title_pl = 'Moje ciało nie należy do mnie 🔋', body_pl = 'Po całym dniu wspinania się na ciebie twoje ciało zdrętwiało? Zostaw dziecko na 5 minut samo w pokoju, po prostu zamknij drzwi, zamknij oczy i weź głęboki oddech. Musisz się zregenerować.', title_pt = 'O meu corpo não me pertence 🔋', body_pt = 'O corpo está dormente de ele lhe trepar para cima o dia todo? Deixe a criança 5 minutos sozinha no quarto, feche a porta, feche os olhos e respire fundo. Precisa de recuperar.', title_sv = 'Min kropp tillhör inte mig 🔋', body_sv = 'Har kroppen domnat av att barnet klättrat på dig hela dagen? Lämna barnet ensamt i rummet i 5 minuter, stäng bara dörren, blunda och andas djupt. Du måste återhämta dig.', title_vi = 'Cơ thể này không còn là của mình 🔋', body_vi = 'Bị leo trèo lên người cả ngày làm cơ thể mẹ tê cứng? Hãy để bé một mình trong phòng 5 phút, chỉ cần đóng cửa, nhắm mắt và hít thở thật sâu. Mẹ cần được hồi phục.', title_zh = '我的身体不属于我了 🔋', body_zh = '被宝宝爬了一整天，身体都麻了？让宝宝在房间里自己待5分钟，你只要关上门，闭上眼睛，深呼吸。你需要恢复一下。' WHERE id = '1b495b8d-2c5f-47f5-aeda-e199006766ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No me llames niño! 😤', body_es = '¿Dice «Ya soy mayor» y te pone normas en la habitación? Está intentando demostrar que ya ha crecido. Háblale como a un mayor con un «Muy bien, jovencita/jovencito» y gánate su respeto.', title_fr = 'Ne m''appelle pas bébé ! 😤', body_fr = 'Il dit « Je suis grand » et vous impose des règles dans la pièce ? Il essaie de prouver qu''il a grandi. Dites « D''accord, jeune demoiselle / jeune homme », adressez-vous à lui comme à un grand et gagnez son respect.', title_hi = 'मुझे बच्चा मत कहो! 😤', body_hi = '‘मैं बड़ा हो गया हूँ’ कहकर कमरे में आपके लिए नियम बनाता है? वह साबित करने की कोशिश कर रहा है कि वह बड़ा हो गया है। ‘ठीक है, जवान साहब’ कहकर उससे बड़ों की तरह बात कीजिए और उसका सम्मान जीतिए।', title_id = 'Jangan panggil aku anak kecil! 😤', body_id = 'Ia berkata ''Aku sudah besar'' dan membuat aturan untuk Anda di kamar? Ia sedang berusaha membuktikan bahwa ia sudah besar. Sapa ia seperti orang dewasa dengan ''Baik, nona muda/tuan muda'' dan dapatkan rasa hormatnya.', title_ja = '子ども扱いしないで！ 😤', body_ja = '「もう大きいの」と言って、部屋であなたにルールを決める？もう大きくなったことを証明しようとしています。「わかりました、お嬢さん（お兄さん）」と大人のように接して、信頼を得ましょう。', title_ko = '나 아기 아니야! 😤', body_ko = '''나 다 컸어'' 하며 방에서 엄마에게 규칙을 정하나요? 다 컸다는 걸 증명하려는 중이에요. ''알겠습니다, 꼬마 숙녀님/신사님'' 하며 어른처럼 대해 주고 존중을 얻으세요.', title_nl = 'Noem me geen baby! 😤', body_nl = 'Zegt hij ''Ik ben groot'' en stelt hij in de kamer regels voor jou op? Hij probeert te bewijzen dat hij al groot is. Spreek hem aan als een volwassene met ''Goed, jongedame/jongeheer'' en win zijn respect.', title_pl = 'Nie mów do mnie „dziecko”! 😤', body_pl = 'Mówi „Jestem już duży” i ustala ci w pokoju zasady? Próbuje udowodnić, że już dorósł. Powiedz: „Dobrze, młoda damo/młody panie”, zwracaj się do niego jak do dorosłego i zdobądź jego szacunek.', title_pt = 'Não me chames bebé! 😤', body_pt = 'Diz "Já sou crescido" e põe-lhe regras no quarto? Está a tentar provar que já cresceu. Trate-o como um adulto, dizendo "Está bem, jovem senhor/senhora", e ganhe o respeito dele.', title_sv = 'Kalla mig inte barn! 😤', body_sv = 'Säger barnet ”Jag är stor” och sätter upp regler för dig i rummet? Hen försöker bevisa att hen redan har vuxit upp. Säg ”Absolut, unga dam/unge herrn”, tilltala barnet som en vuxen och vinn respekten.', title_vi = 'Đừng gọi con là em bé! 😤', body_vi = 'Bé tuyên bố "Con lớn rồi" và đặt ra luật lệ cho mẹ trong phòng? Bé đang cố chứng minh mình đã lớn. Hãy gọi bé như người lớn: "Được thôi, quý cô/quý ông", và giành được sự tôn trọng của bé.', title_zh = '别叫我小孩！😤', body_zh = '说着“我长大了”，在房间里给你定规矩？宝宝在努力证明自己已经长大。说一句“好的，小女士/小先生”，像对大人一样和宝宝说话，赢得宝宝的尊重。' WHERE id = '81591bb3-d8f2-475d-b7fc-1bd47693b91f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi terapia digital 🤫', body_es = '¿En casa ya todos duermen, pero tu cabeza sigue llena de ruido? Abre el Medidor de sonido. Mirar el 0 decibelios de la habitación te relajará más que una sesión con el psicólogo. Pruébalo.', title_fr = 'Ma thérapie numérique 🤫', body_fr = 'La maison dort, mais votre cerveau est encore plein de bruit ? Ouvrez le Sonomètre. Regarder s''afficher 0 décibel dans la pièce vous détendra plus qu''une séance chez le psy, essayez.', title_hi = 'मेरी डिजिटल थेरेपी 🤫', body_hi = 'घर सो गया, पर आपका दिमाग अब भी शोर से भरा है? साउंड मीटर खोलिए। कमरे में ‘0 डेसिबल’ देखना आपको किसी मनोवैज्ञानिक के सेशन से भी ज़्यादा सुकून देगा, आज़माइए।', title_id = 'Terapi digitalku 🤫', body_id = 'Rumah sudah tidur, tapi otak Anda masih penuh kebisingan? Buka Pengukur Suara. Melihat tulisan 0 desibel di kamar akan membuat Anda lebih rileks daripada sesi dengan psikolog, coba saja.', title_ja = 'わたしのデジタルセラピー 🤫', body_ja = '家は寝静まったのに、頭はまだ騒音でいっぱい？「サウンドメーター」を開きましょう。部屋の0デシベルの表示を見るのは、カウンセリングよりもリラックスできるかも。ためしてみて。', title_ko = '나의 디지털 테라피 🤫', body_ko = '집은 잠들었는데 머릿속은 아직 소음으로 가득한가요? 소음 측정기를 열어 보세요. 방 안의 0 데시벨을 바라보는 게 상담 한 번보다 더 편안할 거예요. 해 보세요.', title_nl = 'Mijn digitale therapie 🤫', body_nl = 'Slaapt het huis, maar zit je hoofd nog vol lawaai? Open de Geluidsmeter. Kijken naar die 0 decibel in de kamer ontspant je meer dan een sessie bij de psycholoog, probeer het maar.', title_pl = 'Moja cyfrowa terapia 🤫', body_pl = 'Dom śpi, ale w twojej głowie wciąż szumi? Otwórz Miernik dźwięku. Patrzenie na napis 0 decybeli w pokoju odpręży cię bardziej niż sesja u psychologa, spróbuj.', title_pt = 'A minha terapia digital 🤫', body_pt = 'A casa adormeceu, mas o seu cérebro ainda está cheio de barulho? Abra o Medidor de Som. Olhar para os 0 decibéis do quarto vai acalmá-la mais do que uma sessão com um psicólogo, experimente.', title_sv = 'Min digitala terapi 🤫', body_sv = 'Huset sover, men hjärnan är fortfarande full av oljud? Öppna Ljudmätaren. Att titta på 0 decibel i rummet lugnar dig mer än en psykologsession, prova.', title_vi = 'Liệu pháp kỹ thuật số của mẹ 🤫', body_vi = 'Cả nhà đã ngủ, nhưng đầu mẹ vẫn đầy tiếng ồn? Hãy mở Đo âm thanh. Nhìn con số 0 decibel trong phòng sẽ giúp mẹ thư thái hơn cả một buổi gặp chuyên gia tâm lý, thử xem.', title_zh = '我的数字疗愈 🤫', body_zh = '家里都睡了，你的脑子里却还满是噪音？打开分贝仪。看着房间里的0分贝，会比一次心理咨询更让你放松，试试吧。' WHERE id = 'a65f1e7a-ca07-4462-bac0-1293b0e5896c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir a sus juguetes 🧸', body_es = '¿Él no se duerme, pero acuesta a sus juguetes uno a uno y los tapa? Este juego de rol en realidad lo va preparando poco a poco, psicológicamente, para su propio sueño. No intervengas.', title_fr = 'Endormir ses jouets 🧸', body_fr = 'Lui ne dort pas, mais il couche ses jouets un par un et les borde ? Ce jeu de rôle le prépare en fait doucement, psychologiquement, à son propre sommeil. N''intervenez pas.', title_hi = 'खिलौनों को सुलाना 🧸', body_hi = 'खुद नहीं सोता, पर खिलौनों को एक-एक करके बिस्तर पर लिटाकर ओढ़ाता है? यह रोल-प्ले असल में उसे धीरे-धीरे, मन से उसकी अपनी नींद के लिए तैयार कर रहा है, दखल मत दीजिए।', title_id = 'Menidurkan mainan-mainannya 🧸', body_id = 'Ia sendiri tidak tidur, tapi menidurkan mainannya satu per satu dan menyelimutinya? Permainan peran ini sebenarnya perlahan menyiapkannya secara psikologis untuk tidurnya sendiri, jangan ikut campur.', title_ja = 'おもちゃを寝かしつける 🧸', body_ja = '自分は寝ないのに、おもちゃをひとつずつベッドに寝かせて布団をかけている？このごっこ遊びが、少しずつ心の中で自分の眠りの準備をさせています。じゃましないで。', title_ko = '장난감 재우기 🧸', body_ko = '자기는 안 자면서 장난감을 하나씩 침대에 눕히고 이불을 덮어 주나요? 이 역할 놀이가 사실 아이를 마음으로부터 천천히 잠에 준비시키는 중이에요. 끼어들지 마세요.', title_nl = 'Zijn knuffels in slaap wiegen 🧸', body_nl = 'Gaat hij zelf niet slapen, maar legt hij zijn knuffels één voor één in bed en dekt hij ze toe? Dit rollenspel bereidt hem eigenlijk langzaam en psychologisch voor op zijn eigen slaap, grijp niet in.', title_pl = 'Usypianie zabawek 🧸', body_pl = 'Sam nie śpi, ale kładzie zabawki po kolei do łóżka i je przykrywa? Ta zabawa w odgrywanie ról tak naprawdę powoli, psychologicznie przygotowuje go do własnego snu, nie przeszkadzaj.', title_pt = 'Adormecer os brinquedos 🧸', body_pt = 'Ele não dorme, mas deita os brinquedos um a um e tapa-os? Este jogo de faz de conta está, na verdade, a prepará-lo devagarinho e psicologicamente para o seu próprio sono. Não interfira.', title_sv = 'Söva leksakerna 🧸', body_sv = 'Sover barnet inte själv, men lägger leksakerna i sängen en efter en och bäddar om dem? Den här rolleken förbereder egentligen barnet psykologiskt, sakta men säkert, för sin egen sömn, lägg dig inte i.', title_vi = 'Ru đồ chơi ngủ 🧸', body_vi = 'Bé chưa chịu ngủ, nhưng lại đặt từng món đồ chơi lên giường và đắp chăn cho chúng? Trò nhập vai này thật ra đang từ từ chuẩn bị tâm lý cho chính giấc ngủ của bé, đừng can thiệp.', title_zh = '哄玩具睡觉 🧸', body_zh = '自己不睡，却把玩具一个个放到床上盖好被子？这个角色扮演其实正在慢慢地从心理上帮宝宝为自己的睡眠做准备，别打扰。' WHERE id = '25ef7ba4-1698-4dbc-9412-9bb568472d80' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué has abierto tú la puerta? 🚪', body_es = '¿Llora porque has abierto tú la puerta y te hace cerrarla para abrirla él? Deja que se tome ese minuto, pero evita en paz los 20 minutos de drama y gritos que se armarían en casa.', title_fr = 'Pourquoi c''est toi qui as ouvert la porte ? 🚪', body_fr = 'Il pleure parce que vous avez ouvert la porte et vous la fait refermer pour l''ouvrir lui-même ? Laissez-le prendre cette minute, et évitez en douceur une apocalypse de 20 minutes de cris à la maison.', title_hi = 'दरवाज़ा तुमने क्यों खोला? 🚪', body_hi = 'आपने दरवाज़ा खोला, इसलिए रोकर फिर बंद करवाता है ताकि खुद खोल सके? उसे 1 मिनट ले लेने दीजिए, पर घर में होने वाले 20 मिनट के हंगामे और चीख-पुकार को शांति से रोक लीजिए।', title_id = 'Kenapa Mama yang buka pintunya? 🚪', body_id = 'Ia menangis karena Anda membuka pintu dan menyuruh menutupnya lagi supaya ia yang membuka? Biarkan ia mengambil 1 menit itu, tapi cegah dengan damai kiamat dan teriakan 20 menit di rumah.', title_ja = 'なんでママがドアを開けたの？ 🚪', body_ja = 'あなたがドアを開けたから泣いて、自分で開けるために閉めなおさせる？1分かかってもいいから、家で起きる20分の大さわぎと叫び声を平和に防ぎましょう。', title_ko = '왜 엄마가 문 열었어? 🚪', body_ko = '엄마가 문을 열었다고 울면서 다시 닫게 하고 자기가 열겠다고 하나요? 1분을 내어 주세요. 집에서 터질 20분짜리 난리와 고함을 평화롭게 막을 수 있어요.', title_nl = 'Waarom deed jij de deur open? 🚪', body_nl = 'Laat hij je huilend de deur weer dichtdoen omdat jij hem opendeed, zodat hij hem zelf kan openen? Laat het hem 1 minuut kosten, zo voorkom je vreedzaam een storm van 20 minuten met geschreeuw in huis.', title_pl = 'Czemu ty otworzyłaś drzwi? 🚪', body_pl = 'Płacze, bo to ty otworzyłaś drzwi, i każe je zamknąć, żeby otworzyć sam? Niech zabierze ci tę 1 minutę, ale pokojowo zapobiegniesz 20-minutowej awanturze i krzykom w domu.', title_pt = 'Porque é que foste tu a abrir a porta? 🚪', body_pt = 'Chora porque foi a mãe a abrir a porta e obriga-a a fechá-la para a abrir ele? Deixe-o levar 1 minuto, mas evite com paz uma tempestade de 20 minutos de gritos em casa.', title_sv = 'Varför öppnade du dörren? 🚪', body_sv = 'Gråter barnet och får dig att stänga dörren igen för att du öppnade den, så att hen kan öppna själv? Låt det ta 1 minut, men förebygg i lugn och ro en 20 minuters katastrof med skrik hemma.', title_vi = 'Sao mẹ lại mở cửa? 🚪', body_vi = 'Bé khóc bắt đóng cửa lại để tự mở, chỉ vì mẹ đã mở trước? Hãy cho bé 1 phút ấy, để êm thấm ngăn một trận "tận thế" la hét 20 phút trong nhà.', title_zh = '门为什么是你开的？🚪', body_zh = '因为门是你开的，就哭着让你关上，好自己再开一次？让宝宝花掉这1分钟吧，却能平和地避免家里一场20分钟的天翻地覆和尖叫。' WHERE id = '7626d265-88f4-40f1-a79c-e9d0f1238d73' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo color verde! 🥦', body_es = '¿Solo busca cosas verdes en el plato? Mira el plan de Nutrición, aprende a hacer bolitas verdes de verdura y hierbas con formas divertidas y satisface esta curiosa manía.', title_fr = 'Seulement du vert ! 🥦', body_fr = 'Il ne cherche que des choses vertes dans son assiette ? Consultez le Plan de nutrition, apprenez à faire avec des herbes de jolies boulettes de légumes verts et satisfaites cette drôle d''obsession.', title_hi = 'सिर्फ़ हरा रंग! 🥦', body_hi = 'प्लेट में सिर्फ़ हरी चीज़ें ढूँढता है? फ़ीडिंग प्लान देखिए, सीखिए कि हरी पत्तेदार सब्ज़ियों से प्यारे आकार की हरी सब्ज़ी की गोलियाँ कैसे बनाएँ, और उसकी इस अजीब सनक को पूरा कीजिए।', title_id = 'Hanya warna hijau! 🥦', body_id = 'Ia hanya mencari yang hijau di piringnya? Lihat Rencana Nutrisi, pelajari cara membuat bola-bola sayur hijau berbentuk lucu dari sayuran daun, dan penuhi obsesi anehnya ini.', title_ja = '緑色だけ！ 🥦', body_ja = 'お皿の中で緑のものだけを探している？「栄養管理ツール」を見て、青菜からかわいい形の緑の野菜ボールをつくる方法を知り、このふしぎなこだわりを満たしてあげましょう。', title_ko = '초록색만 먹을래! 🥦', body_ko = '접시에서 초록색 음식만 찾나요? 식단 계획을 보고 채소로 귀여운 모양의 초록 채소볼을 만드는 법을 배워, 이 독특한 집착을 채워 주세요.', title_nl = 'Alleen groen! 🥦', body_nl = 'Zoekt hij op zijn bord alleen naar groene dingen? Kijk in het onderdeel Voeding, leer hoe je van groene kruiden schattige groene groentebolletjes maakt en geef deze rare voorliefde haar zin.', title_pl = 'Tylko zielony kolor! 🥦', body_pl = 'Szuka na talerzu tylko zielonych rzeczy? Zajrzyj do planu karmienia, dowiedz się, jak zrobić z zieleniny urocze zielone kulki warzywne, i zaspokój ten dziwny fetysz.', title_pt = 'Só a cor verde! 🥦', body_pt = 'No prato só procura coisas verdes? Veja o plano de alimentação, aprenda a fazer com as ervas aromáticas bolinhas verdes de legumes com formas giras e satisfaça esta mania estranha.', title_sv = 'Bara grön färg! 🥦', body_sv = 'Letar barnet bara efter gröna saker på tallriken? Titta i matplanen, lär dig att göra söta, gröna grönsaksbollar av örter och mätta den konstiga besattheten.', title_vi = 'Chỉ màu xanh lá thôi! 🥦', body_vi = 'Bé chỉ tìm đồ màu xanh lá trong đĩa? Hãy xem Kế hoạch dinh dưỡng, học cách làm những viên rau xanh hình thù đáng yêu từ các loại rau thơm và chiều theo "sở thích" kỳ lạ này.', title_zh = '只要绿色的！🥦', body_zh = '盘子里只找绿色的东西？看看喂养计划，学学怎样用绿叶菜做出形状可爱的绿色蔬菜丸子，满足这个奇怪的执念吧。' WHERE id = 'a5284401-af40-43a4-aa11-663792a88d21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los bordes del pan son el enemigo 🍞', body_es = '¿Se come el centro y tira con firmeza los bordes? No pelees con las cortezas. Corta el pan con cortadores de figuras de animales, crea formas sin corteza y deja que disfrute de ese diseño culinario.', title_fr = 'Les bords du pain sont l''ennemi 🍞', body_fr = 'Il mange le milieu et jette fermement les bords ? Ne vous battez pas avec les croûtes. Découpez le pain avec des emporte-pièces en forme d''animaux, créez des formes sans croûte et laissez-le savourer ce design culinaire.', title_hi = 'ब्रेड के किनारे दुश्मन हैं 🍞', body_hi = 'बीच का हिस्सा खाकर किनारे पक्के इरादे से फेंक देता है? किनारों से मत लड़िए। जानवरों के आकार वाले कटर से काटिए, बिना किनारों वाली आकृतियाँ बनाइए, उसे पाक-कला के इस डिज़ाइन का मज़ा लेने दीजिए।', title_id = 'Pinggiran roti adalah musuh 🍞', body_id = 'Ia memakan bagian tengahnya dan dengan tegas membuang pinggirannya? Jangan berperang dengan pinggiran roti. Potong dengan cetakan berbentuk hewan, buat bentuk tanpa pinggiran, dan biarkan ia menikmati desain kuliner itu.', title_ja = 'パンの耳は敵 🍞', body_ja = 'まん中を食べて、耳はきっぱり捨てる？耳と戦わないで。動物の型で抜いて耳のない形をつくり、料理のデザインを楽しませてあげましょう。', title_ko = '빵 테두리는 적이야 🍞', body_ko = '가운데만 먹고 테두리는 단호하게 버리나요? 테두리와 싸우지 마세요. 동물 모양 커터로 테두리 없는 모양을 만들어, 요리 디자인을 즐기게 해 주세요.', title_nl = 'Korstjes zijn de vijand 🍞', body_nl = 'Eet hij het midden op en gooit hij de randjes resoluut weg? Ga niet vechten om korstjes. Steek het brood uit met vormpjes in dierenfiguren, maak korstloze vormen en laat hem genieten van dit culinaire design.', title_pl = 'Skórki chleba to wróg 🍞', body_pl = 'Zjada środek, a skórki stanowczo wyrzuca? Nie walcz ze skórkami. Wycinaj foremkami w kształcie zwierzątek kształty bez skórki, niech cieszy się tym kulinarnym designem.', title_pt = 'As côdeas são o inimigo 🍞', body_pt = 'Come o miolo e deita fora as côdeas com firmeza? Não lute com as côdeas. Corte o pão com formas de animais, crie figuras sem côdea e deixe-o saborear este design culinário.', title_sv = 'Brödkanterna är fienden 🍞', body_sv = 'Äter barnet mitten och slänger bestämt kanterna? Kämpa inte mot skorporna. Skär med djurformade utstickare, gör former utan kant och låt barnet njuta av kockdesignen.', title_vi = 'Viền bánh mì là kẻ thù 🍞', body_vi = 'Bé ăn phần ruột và kiên quyết bỏ phần viền? Đừng chiến đấu với vỏ bánh. Hãy dùng khuôn cắt hình con vật để tạo những hình không có viền, để bé thích thú với "thiết kế ẩm thực" ấy.', title_zh = '面包边是敌人 🍞', body_zh = '只吃中间，坚决扔掉面包边？别和面包边较劲。用动物造型的模具切一切，做出没有边的形状，让宝宝享受这份“料理设计”吧。' WHERE id = '27e63f29-b167-40b2-aa6b-8ed0d0329ca3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No quiere salir de casa ⛅', body_es = '¿Las cuatro paredes te ahogan, pero él llora y no quiere salir? Confía en la herramienta Tiempo y ropa y sácalo aunque sea a regañadientes. En cuanto respire aire fresco, toda esa agresividad de estar en casa se esfumará en un segundo.', title_fr = 'Il ne veut pas sortir de la maison ⛅', body_fr = 'Les quatre murs vous étouffent, mais lui pleure et ne veut pas sortir ? Faites confiance à l''outil Météo et tenue et sortez-le, même à contrecœur. Dès qu''il respirera l''air frais, toute cette agressivité d''intérieur s''envolera en une seconde.', title_hi = 'घर से नहीं निकलना चाहता ⛅', body_hi = 'चार दीवारें आपका दम घोंट रही हैं, पर वह रोकर बाहर जाने से मना कर रहा है? मौसम और कपड़े टूल पर भरोसा करके ज़बरदस्ती ही सही, बाहर ले जाइए। ताज़ी हवा मिलते ही घर के अंदर का सारा गुस्सा सेकंडों में उड़ जाएगा।', title_id = 'Ia tidak mau keluar rumah ⛅', body_id = 'Empat dinding terasa menyesakkan, tapi ia menangis tidak mau keluar? Andalkan Cuaca dan Pakaian dan ajak ia keluar walau harus sedikit dipaksa. Begitu menghirup udara segar, semua agresi di dalam rumah itu akan hilang dalam sekejap.', title_ja = '家から出たくない ⛅', body_ja = '四方の壁に息がつまりそうなのに、泣いて外に出たがらない？「天気と服装」を信じて、多少強引にでも連れ出しましょう。外の空気を吸った瞬間、家の中でのイライラはすぐに吹き飛びます。', title_ko = '밖에 나가기 싫대요 ⛅', body_ko = '네 벽에 숨이 막히는데 아이는 울며 나가기 싫다고 하나요? 날씨와 옷차림 도구를 믿고 억지로라도 데리고 나가세요. 바깥 공기를 마시는 순간 집 안에서 쌓인 공격성이 금세 날아갈 거예요.', title_nl = 'Hij wil de deur niet uit ⛅', body_nl = 'Word je gek van de vier muren, maar huilt hij en wil hij niet naar buiten? Vertrouw op Weer en kleding en ga desnoods met wat moeite toch naar buiten. Zodra hij frisse lucht inademt, waait al die binnenshuis opgebouwde agressie in een seconde weg.', title_pl = 'Nie chce wyjść z domu ⛅', body_pl = 'Cztery ściany cię przytłaczają, a on płacze i nie chce wyjść? Zaufaj narzędziu Pogoda i ubiór i wyjdźcie choćby na siłę. Gdy tylko złapie świeżego powietrza, cała domowa złość w sekundę uleci.', title_pt = 'Não quer sair de casa ⛅', body_pt = 'As quatro paredes estão a sufocá-la, mas ele chora e não quer sair? Confie na ferramenta Tempo e Roupa e leve-o, nem que seja à força. Mal respire ar puro, toda aquela agressividade de dentro de casa desaparece num segundo.', title_sv = 'Vill inte gå ut ⛅', body_sv = 'Kväver de fyra väggarna er, men barnet gråter och vill inte gå ut? Lita på Väder och kläder och ta ut barnet, även om det tar emot. Så fort hen får frisk luft flyger all ilska inomhus iväg på en sekund.', title_vi = 'Bé không muốn ra khỏi nhà ⛅', body_vi = 'Bốn bức tường làm mẹ ngột ngạt, nhưng bé lại khóc không chịu ra ngoài? Hãy tin vào Thời tiết và trang phục và đưa bé ra ngoài, dù có phải hơi ép. Vừa hít thở khí trời, mọi bực bội trong nhà sẽ tan biến trong tích tắc.', title_zh = '不想出门 ⛅', body_zh = '四面墙让你喘不过气，宝宝却哭着不肯出门？相信天气与穿衣工具，哪怕连哄带拉也要出去。一呼吸到新鲜空气，那些在家里积攒的火气几秒钟就会飞走。' WHERE id = '7c97a838-1745-4335-a86c-2bf011bb9f3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lucha en pijama con papá 🤼‍♂️', body_es = '¿No quiere dormir? Que papá haga como que pierde contra él en el sofá. Sudará, dejará ahí toda su última energía y se meterá corriendo en la cama.', title_fr = 'Lutte en pyjama avec papa 🤼‍♂️', body_fr = 'Il ne veut pas dormir ? Papa fait semblant de le battre à la lutte. Il transpirera, y laissera ses dernières forces et filera au lit en courant.', title_hi = 'पापा के साथ पजामा कुश्ती 🤼‍♂️', body_hi = 'सोना नहीं चाहता? पापा सोफ़े पर उससे नकली हार जाते हैं। पसीना बहाकर वह अपनी आखिरी ऊर्जा वहीं छोड़ देगा और दौड़कर बिस्तर में घुस जाएगा।', title_id = 'Gulat piyama bersama Ayah 🤼‍♂️', body_id = 'Ia tidak mau tidur? Ayah pura-pura kalah gulat di sofa. Ia akan berkeringat, menghabiskan semua sisa energinya di sana, dan berlari masuk ke tempat tidur.', title_ja = 'パパとパジャマでレスリング 🤼‍♂️', body_ja = '寝たくない？パパにソファで負けたふりをしてもらいましょう。汗をかいて最後のエネルギーを出しきり、走ってベッドに入りますよ。', title_ko = '아빠와 잠옷 레슬링 🤼‍♂️', body_ko = '자기 싫대요? 아빠가 장난 레슬링에서 져 주게 하세요. 땀을 흘리며 마지막 에너지까지 다 쏟고 나면 침대로 뛰어 들어갈 거예요.', title_nl = 'Pyjamaworstelen met papa 🤼‍♂️', body_nl = 'Wil hij niet slapen? Laat papa hem voor de grap verliezen in een worstelpartij. Hij raakt bezweet, laat al zijn laatste energie achter en rent zo zijn bed in.', title_pl = 'Zapasy w piżamach z tatą 🤼‍♂️', body_pl = 'Nie chce spać? Tata na niby przegrywa z nim zapasy przy ścianie. Spoci się, zostawi tam całą resztkę energii i sam pobiegnie do łóżka.', title_pt = 'Luta de pijama com o pai 🤼‍♂️', body_pt = 'Não quer dormir? O pai deixa-se vencer a fingir numa luta junto à parede. Ele vai suar, deixar lá toda a energia que lhe resta e correr para a cama.', title_sv = 'Pyjamasbrottning med pappa 🤼‍♂️', body_sv = 'Vill barnet inte sova? Pappa låter sig låtsasbesegras i soffan. Barnet blir svettigt, lämnar all sin sista energi där och springer sedan själv till sängen.', title_vi = 'Vật nhau trong bộ đồ ngủ cùng bố 🤼‍♂️', body_vi = 'Bé không chịu ngủ? Để bố giả vờ thua bé trong trận vật bên tường. Bé sẽ đổ mồ hôi, xả hết chút năng lượng cuối cùng và chạy ùa lên giường.', title_zh = '和爸爸的睡衣摔跤赛 🤼‍♂️', body_zh = '不想睡觉？让爸爸在沙发上假装被宝宝打败。宝宝会出一身汗，把最后的精力都留在那里，然后跑着钻进被窝。' WHERE id = 'f3fa598e-4bec-4396-a5cb-220c0c856d23' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Coger fuerzas en la Comunidad 💬', body_es = 'Cuando se te acabe la paciencia, entra en la Comunidad Anacan. Al ver que allí las mamás viven el mismo caos, sentirás por dentro un gran alivio y la sensación de «no estoy sola».', title_fr = 'Puiser des forces dans la Communauté 💬', body_fr = 'Quand votre patience est à bout, rejoignez la Communauté Anacan. En voyant que les mamans là-bas vivent le même chaos, vous ressentirez un grand soulagement et le sentiment de ne pas être seule.', title_hi = 'कम्युनिटी से ताकत पाना 💬', body_hi = 'जब सब्र खत्म हो जाए, Anacan कम्युनिटी में आइए। जब देखेंगी कि वहाँ की माँएँ भी यही अफ़रा-तफ़री झेल रही हैं, तो मन में बड़ा सुकून और ‘मैं अकेली नहीं हूँ’ वाला एहसास जागेगा।', title_id = 'Mendapat kekuatan dari komunitas 💬', body_id = 'Saat kesabaran Anda habis, masuklah ke Komunitas Anacan. Saat melihat ibu-ibu di sana mengalami kekacauan yang sama, akan muncul rasa lega yang besar dan perasaan ''aku tidak sendirian''.', title_ja = 'コミュニティから力をもらう 💬', body_ja = 'がまんの限界がきたら、Anacanコミュニティへ。ほかのママたちも同じカオスを経験しているのを見ると、心が軽くなり「ひとりじゃない」と感じられます。', title_ko = '커뮤니티에서 힘 얻기 💬', body_ko = '인내심이 바닥났을 땐 Anacan 커뮤니티에 들어가 보세요. 다른 엄마들도 똑같은 혼란을 겪는 걸 보면 마음속 깊이 큰 안도감과 ''나만 그런 게 아니구나'' 하는 느낌이 들 거예요.', title_nl = 'Kracht putten uit de Community 💬', body_nl = 'Is je geduld op, ga dan naar de Anacan Community. Als je ziet dat de mama''s daar precies dezelfde chaos meemaken, voel je een grote opluchting en het gevoel ''ik ben niet alleen''.', title_pl = 'Siła ze Społeczności 💬', body_pl = 'Gdy kończy ci się cierpliwość, wejdź do Społeczności Anacan. Gdy zobaczysz, że inne mamy przeżywają ten sam chaos, poczujesz wielką ulgę i to, że nie jesteś sama.', title_pt = 'Ganhar força na comunidade 💬', body_pt = 'Quando a paciência acabar, entre na Comunidade Anacan. Ao ver que as mães de lá vivem o mesmo caos, vai sentir um grande alívio e aquela sensação de "não estou sozinha".', title_sv = 'Hämta kraft från Community 💬', body_sv = 'När tålamodet tar slut, gå in i Anacan Community. När du ser att mammorna där upplever samma kaos får du en stor lättnad och känslan av att du inte är ensam.', title_vi = 'Tiếp thêm sức mạnh từ cộng đồng 💬', body_vi = 'Khi cạn kiên nhẫn, hãy vào Cộng đồng Anacan. Thấy các mẹ ở đó cũng đang trải qua cùng một mớ hỗn loạn, mẹ sẽ thấy nhẹ nhõm vô cùng và cảm nhận rõ "mình không đơn độc".', title_zh = '从社区汲取力量 💬', body_zh = '耐心用完时，来Anacan社区吧。看到那里的妈妈们经历着同样的混乱，你心里会大大松一口气，感到“我不是一个人”。' WHERE id = '2ab3a16c-8538-4df6-b8df-c031bc53d6c7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Esto también lo hemos conseguido! 🚀', body_es = 'La casa ya duerme. Estás preparada para los nuevos caos del próximo mes: eres una experta en esto. Apaga las luces y date las gracias por todos esos pequeños milagros que has creado hoy.', title_fr = 'On y est arrivés ! 🚀', body_fr = 'La maison dort. Vous êtes prête pour les nouveaux chaos du mois prochain, vous êtes une pro. Éteignez la lumière et remerciez-vous pour tous ces petits miracles que vous avez créés aujourd''hui.', title_hi = 'यह भी कर लिया! 🚀', body_hi = 'घर सो गया। अगले महीने की नई अफ़रा-तफ़री के लिए आप तैयार हैं, आप इस काम की उस्ताद हैं। लाइटें बंद कीजिए और आज रचे सभी छोटे-छोटे चमत्कारों के लिए खुद को शुक्रिया कहिए।', title_id = 'Kita berhasil lagi! 🚀', body_id = 'Rumah sudah tidur. Anda siap menghadapi kekacauan baru bulan depan, Anda ahli dalam hal ini. Matikan lampu dan berterima kasihlah pada diri sendiri atas semua keajaiban kecil yang Anda ciptakan hari ini.', title_ja = '今日も乗りきった！ 🚀', body_ja = '家は寝静まりました。来月の新しいカオスにも準備OK、あなたはこの道のプロです。明かりを消して、今日つくり出した小さな奇跡のすべてに、自分にありがとうを言いましょう。', title_ko = '이것도 해냈어요! 🚀', body_ko = '온 집이 잠들었어요. 다음 달의 새로운 혼란도 준비됐죠, 엄마는 이 일의 달인이니까요. 불을 끄고 오늘 만들어 낸 작은 기적들에 대해 스스로에게 고맙다고 말해 주세요.', title_nl = 'Ook dit hebben we gered! 🚀', body_nl = 'Het huis slaapt. Je bent klaar voor de nieuwe chaos van volgende maand, je bent hier een meester in. Doe het licht uit en bedank jezelf voor alle kleine wondertjes die je vandaag hebt gemaakt.', title_pl = 'I to nam się udało! 🚀', body_pl = 'Dom śpi. Jesteś gotowa na nowy chaos kolejnego miesiąca, jesteś mistrzynią w tym fachu. Zgaś światło i podziękuj sobie za wszystkie małe cuda, które dziś stworzyłaś.', title_pt = 'Também conseguimos isto! 🚀', body_pt = 'A casa adormeceu. Está pronta para os novos caos do próximo mês: é mestre nisto. Apague as luzes e agradeça a si própria por todos os pequenos milagres que criou hoje.', title_sv = 'Vi klarade det här också! 🚀', body_sv = 'Huset sover. Du är redo för nästa månads nya kaos, du är mästare på det här. Släck lamporna och tacka dig själv för alla små mirakel du skapade i dag.', title_vi = 'Chúng ta lại làm được rồi! 🚀', body_vi = 'Cả nhà đã ngủ. Mẹ đã sẵn sàng cho những hỗn loạn mới của tháng tới, mẹ là bậc thầy trong việc này. Hãy tắt đèn và cảm ơn chính mình vì tất cả những phép màu nhỏ mẹ đã tạo ra hôm nay.', title_zh = '这一关我们也过了！🚀', body_zh = '家里都睡了。你已经准备好迎接下个月的新混乱，你是这方面的高手。关上灯，为今天创造的那些小小奇迹，谢谢自己吧。' WHERE id = '5a8f1d52-e3d3-4c7e-b491-d2552a236831' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esa sombra es mía 👻', body_es = '¿Se ha adueñado de su sombra, le habla y le da órdenes? Su imaginación no tiene límites.', title_fr = 'Cette ombre est à moi 👻', body_fr = 'Il s''approprie son ombre, lui parle et lui donne des ordres ? Son imagination est sans limites.', title_hi = 'वह परछाईं मेरी है 👻', body_hi = 'अपनी परछाईं पर हक जताकर उससे बातें करता है और उसे निर्देश देता है? उसकी कल्पना की कोई सीमा नहीं।', title_id = 'Bayangan itu punyaku 👻', body_id = 'Ia mengklaim bayangannya sendiri, berbicara dengannya, dan memberinya perintah? Imajinasinya tak terbatas.', title_ja = 'その影はぼくの 👻', body_ja = '自分の影を自分のものにして、話しかけたり指示を出したりしている？想像力は限りなしです。', title_ko = '그 그림자는 내 거야 👻', body_ko = '자기 그림자를 자기 것이라며 말을 걸고 지시까지 하나요? 상상력에 한계가 없네요.', title_nl = 'Die schaduw is van mij 👻', body_nl = 'Eist hij zijn schaduw op, praat hij ermee en geeft hij hem opdrachten? Zijn fantasie kent geen grenzen.', title_pl = 'Ten cień jest mój 👻', body_pl = 'Uważa swój cień za swoją własność, rozmawia z nim i wydaje mu polecenia? Jego wyobraźnia nie zna granic.', title_pt = 'Aquela sombra é minha 👻', body_pt = 'Apropria-se da própria sombra, fala com ela e dá-lhe ordens? A imaginação dele não tem limites.', title_sv = 'Den skuggan är min 👻', body_sv = 'Gör barnet anspråk på sin skugga, pratar med den och ger den order? Fantasin har inga gränser.', title_vi = 'Cái bóng đó là của con 👻', body_vi = 'Bé coi cái bóng là của riêng mình, nói chuyện và ra lệnh cho nó? Trí tưởng tượng của bé thật không có giới hạn.', title_zh = '那个影子是我的 👻', body_zh = '把自己的影子当成自己的，和它说话，还给它下命令？宝宝的想象力没有边界。' WHERE id = '83732257-57c8-43f0-99f6-cb1c1583874a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ataque secreto a la lista 🛒', body_es = '¿Antes de ir al súper has abierto la Lista de la compra en la app y has visto 5 chocolates apuntados? Sí, hace tiempo que aprendió a colarse en tu móvil y a copiar el mundo digital.', title_fr = 'Attaque secrète sur la liste 🛒', body_fr = 'Avant d''aller au supermarché, vous avez ouvert la Liste de courses dans l''application et vu 5 chocolats inscrits dessus ? Eh oui, il a appris depuis longtemps à se faufiler dans votre téléphone et à copier votre monde numérique.', title_hi = 'लिस्ट पर चुपके से हमला 🛒', body_hi = 'सुपरमार्केट जाने से पहले ऐप में शॉपिंग लिस्ट खोली और देखा कि उसमें 5 चॉकलेट लिखी हैं? जी हाँ, उसने आपके फ़ोन में घुसना और डिजिटल दुनिया की नकल करना कब का सीख लिया है।', title_id = 'Serangan diam-diam ke daftar belanja 🛒', body_id = 'Sebelum ke supermarket Anda membuka Daftar Belanja di aplikasi dan melihat tertulis ''5 cokelat'' di sana? Ya, ia sudah lama belajar menyusup ke ponsel Anda dan meniru dunia digital.', title_ja = 'リストにこっそり侵入 🛒', body_ja = 'スーパーに行く前にアプリで「買い物リスト」を開いたら、チョコが5つ書かれていた？そう、この子はとっくにあなたのスマホにしのびこんで、デジタルの世界をまねすることを覚えています。', title_ko = '목록에 몰래 쳐들어왔어요 🛒', body_ko = '마트에 가기 전 앱에서 쇼핑 목록을 열었더니 초콜릿이 5개나 적혀 있나요? 네, 엄마 휴대폰에 몰래 들어가 디지털 세상을 따라 하는 법을 벌써 익혔어요.', title_nl = 'Geheime aanval op het lijstje 🛒', body_nl = 'Open je voor je naar de supermarkt gaat het Boodschappenlijstje in de app en zie je dat er 5 repen chocola op staan? Ja, hij heeft allang geleerd je telefoon binnen te dringen en je digitale wereld na te doen.', title_pl = 'Tajny atak na listę 🛒', body_pl = 'Przed wyjściem do sklepu otworzyłaś w aplikacji Listę zakupów i zobaczyłaś na niej 5 czekolad? Tak, on już dawno nauczył się zakradać do twojego telefonu i kopiować cyfrowy świat.', title_pt = 'Ataque secreto à lista 🛒', body_pt = 'Antes de ir ao supermercado, abriu a Lista de Compras na app e viu escrito "5 chocolates"? Pois é, há muito que ele aprendeu a infiltrar-se no seu telemóvel e a copiar o seu mundo digital.', title_sv = 'En hemlig attack mot listan 🛒', body_sv = 'Innan du gick till affären öppnade du Inköpslistan i appen och såg att det stod 5 chokladkakor på listan? Ja, barnet har för länge sedan lärt sig att ta sig in i din telefon och kopiera den digitala världen.', title_vi = 'Cuộc "tấn công" lén vào danh sách 🛒', body_vi = 'Trước khi đi siêu thị, mẹ mở Danh sách mua sắm trong ứng dụng và thấy có ghi "5 thanh sô-cô-la"? Đúng vậy, bé đã học cách "xâm nhập" điện thoại và bắt chước thế giới số của mẹ từ lâu rồi.', title_zh = '偷偷“入侵”购物清单 🛒', body_zh = '去超市前，你打开应用里的购物清单，却发现上面写着5块巧克力？没错，宝宝早就学会了钻进你的手机，模仿你的数字世界。' WHERE id = '37af8066-a97d-4233-891d-9eb3a99e296b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de la manzana entera 🍏', body_es = '¿Se ha armado un llanto en la habitación porque has cortado la manzana en gajos? Llora diciendo «¡Yo la quería entera!». No busques lógica. Junta los gajos, dile «Mira, ya la he arreglado» y sal de este drama sin sentido con diplomacia.', title_fr = 'Le drame de la pomme entière 🍏', body_fr = 'Des cris dans la pièce parce que vous avez coupé la pomme en tranches ? Il pleure : « Je la voulais entière ! » Ne cherchez pas de logique. Recollez les tranches et dites « Regarde, je l''ai réparée », et sortez-vous de ce drame absurde avec diplomatie.', title_hi = 'साबुत सेब का ड्रामा 🍏', body_hi = 'आपने सेब काट दिया, इसलिए कमरे में चीख-पुकार मच गई? ‘मुझे साबुत चाहिए था!’ कहकर रो रहा है। तर्क मत ढूँढिए। टुकड़ों को आपस में जोड़कर कहिए, ‘देखो, फिर से बना दिया’ और इस बेमतलब ड्रामे से कूटनीति से निकल आइए।', title_id = 'Drama apel utuh 🍏', body_id = 'Kamar penuh jeritan karena Anda mengiris apelnya? Ia menangis, ''Aku maunya utuh!'' Jangan cari logikanya. Rapatkan irisan-irisannya, katakan ''Lihat, sudah Mama perbaiki'', dan keluarlah dari drama tanpa arti ini secara diplomatis.', title_ja = 'まるごとりんごのドラマ 🍏', body_ja = 'りんごを切ったら大泣き？「まるごとがよかったの！」と泣いている。理屈を探さないで。切ったりんごをくっつけて「見て、元どおりにしたよ」と言い、このドラマから上手に切りぬけましょう。', title_ko = '통사과 드라마 🍏', body_ko = '사과를 잘랐다고 ''통째로 먹고 싶었단 말이야!'' 하며 울부짖나요? 논리를 찾지 마세요. 조각을 다시 붙여 ''봐, 다시 고쳐 놨어'' 하며 이 드라마에서 외교적으로 빠져나오세요.', title_nl = 'Het drama van de hele appel 🍏', body_nl = 'Barst er gejammer los omdat je de appel in partjes sneed? Hij huilt: ''Ik wilde hem heel!'' Zoek geen logica. Plak de partjes tegen elkaar, zeg ''Kijk, ik heb hem weer gemaakt'' en ontsnap diplomatiek aan dit zinloze drama.', title_pl = 'Dramat całego jabłka 🍏', body_pl = 'W pokoju wybuchł lament, bo pokroiłaś jabłko? Płacze: „Chciałem całe!”. Nie szukaj logiki. Złóż plasterki z powrotem, powiedz „Zobacz, naprawiłam je” i dyplomatycznie wyjdź z tego bezsensownego dramatu.', title_pt = 'O drama da maçã inteira 🍏', body_pt = 'Houve gritaria no quarto porque cortou a maçã às fatias? Chora a dizer "Eu queria-a inteira!". Não procure lógica. Junte as fatias, diga "Olha, consertei-a" e saia com diplomacia deste drama sem sentido.', title_sv = 'Dramat om det hela äpplet 🍏', body_sv = 'Blev det skrik i rummet för att du skivade äpplet? Barnet gråter: ”Jag ville ha det helt!” Leta inte efter logik. Sätt ihop skivorna, säg ”Titta, jag har lagat det” och ta dig diplomatiskt ur det meningslösa dramat.', title_vi = 'Bi kịch quả táo nguyên vẹn 🍏', body_vi = 'Cả phòng vang tiếng khóc chỉ vì mẹ cắt táo thành lát? Bé khóc: "Con muốn ăn nguyên quả cơ!" Đừng tìm logic. Hãy ghép các lát lại với nhau, nói "Nhìn này, mẹ sửa lại rồi" và khéo léo thoát khỏi màn kịch vô nghĩa này.', title_zh = '完整苹果的闹剧 🍏', body_zh = '你把苹果切成了片，房间里就哭声震天？“我要整个的！”别找逻辑。把苹果片拼回去，说“看，我把它修好了”，巧妙地化解这场毫无意义的闹剧。' WHERE id = '709311bc-b001-46b6-bc4d-6ad222fa6ef4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe que se inventa papá 🦸‍♂️', body_es = '¿Te has quedado sin voz y sin aliento para leer el libro? Pásale la pelota a papá. Que cuente una historia inventada y sin lógica cuyo protagonista sea el propio peque. Tú solo túmbate en el sofá y escucha las carcajadas que salen de la habitación.', title_fr = 'Le héros inventé par papa 🦸‍♂️', body_fr = 'Vous n''avez plus de voix ni le souffle pour lire un livre ? Passez la balle à papa. Qu''il raconte une histoire inventée et sans logique dont le héros est l''enfant lui-même. Vous, allongez-vous simplement sur le canapé et écoutez les éclats de rire venant de la chambre.', title_hi = 'पापा का गढ़ा हुआ हीरो 🦸‍♂️', body_hi = 'आवाज़ नहीं निकल रही, किताब पढ़ने का दम नहीं? गेंद पापा के पाले में डालिए। पापा एक गढ़ी हुई, बेतुकी कहानी सुनाएँ जिसका हीरो खुद बच्चा हो। आप बस सोफ़े पर लेटिए और कमरे से आते ठहाके सुनिए।', title_id = 'Pahlawan karangan Ayah 🦸‍♂️', body_id = 'Suara Anda habis dan tak punya tenaga membacakan buku? Oper bolanya ke Ayah. Biarkan Ayah menceritakan kisah karangan yang tak masuk akal dengan tokoh utamanya si anak sendiri. Anda cukup berbaring di sofa dan mendengarkan tawa dari kamar.', title_ja = 'パパがつくったヒーロー 🦸‍♂️', body_ja = '声が出ない、絵本を読む元気がない？ボールはパパにパス。主人公が子ども自身の、理屈ぬきのつくり話をしてもらいましょう。あなたはソファに横になって、部屋から聞こえる笑い声を聞くだけ。', title_ko = '아빠가 지어낸 영웅 🦸‍♂️', body_ko = '목소리도 안 나오고 책 읽을 기운도 없나요? 공을 아빠에게 넘기세요. 아이가 주인공인 엉뚱하고 말도 안 되는 이야기를 아빠가 지어내게 하세요. 엄마는 소파에 누워 방에서 들려오는 웃음소리를 즐기세요.', title_nl = 'Papa''s verzonnen held 🦸‍♂️', body_nl = 'Is je stem op en heb je geen adem meer om voor te lezen? Speel de bal door naar papa. Laat hem een verzonnen, onlogisch verhaal vertellen met je kind zelf als hoofdpersoon. Lig jij maar op de bank en luister naar het geschater uit de kamer.', title_pl = 'Bohater wymyślony przez tatę 🦸‍♂️', body_pl = 'Nie masz głosu ani siły, by czytać książkę? Przekaż piłeczkę tacie. Niech tata opowie wymyśloną, nielogiczną historię, w której głównym bohaterem jest samo dziecko. Ty po prostu połóż się na kanapie i słuchaj śmiechu dochodzącego z pokoju.', title_pt = 'O herói inventado pelo pai 🦸‍♂️', body_pt = 'Ficou sem voz e não tem fôlego para ler? Passe a bola ao pai. Que ele conte uma história inventada e sem lógica em que o herói principal é a própria criança. A mãe só tem de se deitar no sofá e ouvir as gargalhadas que vêm do quarto.', title_sv = 'Pappas påhittade hjälte 🦸‍♂️', body_sv = 'Har du ingen röst kvar och orkar inte läsa en bok? Skicka bollen till pappa. Låt pappa berätta en påhittad och ologisk historia där barnet självt är huvudpersonen. Lägg dig bara i soffan och lyssna på skratten från rummet.', title_vi = 'Người hùng do bố nghĩ ra 🦸‍♂️', body_vi = 'Mẹ khản giọng, không còn hơi đọc sách? Hãy chuyền bóng cho bố. Để bố kể một câu chuyện tưởng tượng, phi logic mà nhân vật chính là bé. Mẹ chỉ việc nằm dài trên sofa và nghe tiếng cười vọng ra từ phòng.', title_zh = '爸爸编的英雄 🦸‍♂️', body_zh = '嗓子哑了，没力气读书？把球传给爸爸。让爸爸讲一个以宝宝自己为主角、天马行空又不讲逻辑的故事。你只要躺在沙发上，听房间里传出的笑声。' WHERE id = '8b61be71-cfc2-42cd-ad4f-a58585ff674e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La cabezonería del calcetín al revés 🧦', body_es = '¿Se ha puesto el talón del calcetín encima del pie y no te deja arreglarlo de ninguna manera? Que se quede así. Ese orgullo de «esto lo he hecho yo» vale un millón de veces más que ir bien vestido.', title_fr = 'L''entêtement de la chaussette à l''envers 🧦', body_fr = 'Il a mis le talon de sa chaussette sur le dessus du pied et refuse absolument qu''on la remette bien ? Laissez-la ainsi. Sa fierté de dire « J''ai réussi tout seul » vaut un million de fois plus que de bien s''habiller.', title_hi = 'उल्टे पहने मोज़ों की ज़िद 🧦', body_hi = 'मोज़े की एड़ी पैर के ऊपर करके पहन ली और बिल्कुल ठीक नहीं करने देता? वैसे ही रहने दीजिए। ‘यह मैंने कर लिया’ वाला उसका गर्व सही पहनने से लाख गुना ज़्यादा कीमती है।', title_id = 'Keras kepala soal kaus kaki terbalik 🧦', body_id = 'Tumit kaus kakinya ada di punggung kaki dan ia sama sekali tidak mau dibetulkan? Biarkan saja begitu. Rasa bangga ''aku bisa sendiri'' itu sejuta kali lebih berharga daripada berpakaian dengan benar.', title_ja = 'うら返しくつ下のこだわり 🧦', body_ja = 'くつ下のかかとを足の甲にしてはいて、ぜったい直させない？そのままにしておきましょう。「自分でできた」という誇りは、正しくはくより百万倍大切です。', title_ko = '거꾸로 신은 양말 고집 🧦', body_ko = '양말 뒤꿈치를 발등 쪽으로 신고 절대 못 고치게 하나요? 그대로 두세요. ''내가 해냈어'' 하는 자부심은 바르게 신는 것보다 백만 배 더 소중해요.', title_nl = 'De koppige binnenstebuiten sok 🧦', body_nl = 'Heeft hij zijn sok aan met de hiel bovenop zijn voet en mag je het beslist niet goed doen? Laat het zo. Zijn trots van ''dat heb ik zelf gedaan'' is een miljoen keer meer waard dan goed aangekleed zijn.', title_pl = 'Upór ze skarpetką na odwrót 🧦', body_pl = 'Założył skarpetkę piętą na wierzch stopy i stanowczo nie pozwala jej poprawić? Niech tak zostanie. Jego duma, mówiąca „sam to zrobiłem”, jest milion razy cenniejsza niż poprawne ubranie.', title_pt = 'A teimosia da meia ao contrário 🧦', body_pt = 'Calçou a meia com o calcanhar em cima do pé e não a deixa de maneira nenhuma endireitá-la? Deixe ficar assim. O orgulho de "fui eu que fiz" vale um milhão de vezes mais do que estar bem calçado.', title_sv = 'Envisheten med strumpan på tvären 🧦', body_sv = 'Har barnet satt strumphälen ovanpå foten och låter dig inte rätta till den? Låt den sitta så. Stoltheten som säger ”jag klarade det själv” är en miljon gånger mer värd än att vara rätt klädd.', title_vi = 'Cố chấp đi tất ngược 🧦', body_vi = 'Bé đi tất với phần gót ở mu bàn chân và kiên quyết không cho sửa? Cứ để vậy. Niềm tự hào "con tự làm được" ấy quý hơn việc mặc đúng cả triệu lần.', title_zh = '袜子反穿的倔强 🧦', body_zh = '把袜子的后跟穿到了脚背上，还坚决不让你改？就这样吧。宝宝“我做到了”的那份骄傲，比穿得正确珍贵一百万倍。' WHERE id = '167cc8b8-5aaf-4f2a-8be0-934651da76be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La excusa de un sorbito más de agua 💧', body_es = '¿Justo cuando se está quedando dormido salta de la cama diciendo «Tengo mucha sed»? El objetivo no es el agua, sino ganar un poco más de tiempo contigo. Deja antes un vaso antiderrame junto a su cama y corta de raíz esta famosa manipulación.', title_fr = 'Le prétexte de la dernière gorgée d''eau 💧', body_fr = 'Juste au moment de s''endormir, il saute du lit en disant « J''ai trop soif » ? Le but n''est pas l''eau, mais gagner encore un peu de temps avec vous. Posez à l''avance une gourde anti-fuite au bord de son lit et coupez court dès le départ à cette célèbre manipulation.', title_hi = '‘एक घूँट पानी और’ वाला बहाना 💧', body_hi = 'पूरी तरह सोने ही वाला होता है कि ‘बहुत प्यास लगी है’ कहकर बिस्तर से कूद पड़ता है? मकसद पानी नहीं, आपके साथ थोड़ा और समय पाना है। बिस्तर के पास पहले से ही न गिरने वाली पानी की बोतल रखकर इस मशहूर चाल को शुरू में ही रोक दीजिए।', title_id = 'Alasan ''satu teguk air lagi'' 💧', body_id = 'Tepat saat hampir tertidur, ia melompat dari tempat tidur sambil berkata ''Aku haus sekali''? Tujuannya bukan air, tapi mendapat sedikit waktu lagi bersama Anda. Letakkan botol minum anti tumpah di samping tempat tidurnya sejak awal dan patahkan manipulasi terkenal ini sebelum dimulai.', title_ja = 'もうひと口お水の言いわけ 💧', body_ja = 'もう少しで寝そうなときに「のどがかわいた」とベッドから飛び出す？目的はお水ではなく、あなたともう少し一緒にいること。こぼれないマグを前もってベッドのそばに置いて、このおなじみの作戦を先回りで防ぎましょう。', title_ko = '물 한 모금만 더 핑계 💧', body_ko = '막 잠들려는 순간 ''목말라'' 하며 벌떡 일어나나요? 목적은 물이 아니라 엄마와 시간을 조금 더 보내는 거예요. 침대 옆에 쏟아지지 않는 물병을 미리 두어 이 유명한 작전을 처음부터 막으세요.', title_nl = 'De smoes van nog één slokje water 💧', body_nl = 'Springt hij net als hij in slaap valt uit bed met ''Ik heb zo''n dorst''? Het gaat niet om water, maar om nog wat extra tijd met jou. Zet vooraf een lekvrije drinkbeker naast zijn bed en snijd deze bekende manipulatie meteen af.', title_pl = 'Wymówka „jeszcze łyk wody” 💧', body_pl = 'Gdy już prawie zasypia, wyskakuje z łóżka, bo „bardzo chce mu się pić”? Nie chodzi o wodę, tylko o jeszcze trochę czasu z tobą. Postaw wcześniej przy łóżku niewylewny kubek i od początku utnij tę słynną manipulację.', title_pt = 'A desculpa de "só mais um golo de água" 💧', body_pt = 'Mesmo quando está quase a adormecer, salta da cama a dizer "Tenho muita sede"? O objetivo não é a água, é ganhar mais um bocadinho de tempo consigo. Ponha antes ao lado da cama um copo antientornos e corte logo à partida esta famosa manipulação.', title_sv = 'Ursäkten ”en klunk vatten till” 💧', body_sv = 'Precis när barnet håller på att somna hoppar hen upp: ”Jag är så törstig!” Målet är inte vattnet, utan att vinna lite mer tid med dig. Ställ en spillfri vattenflaska vid sängen i förväg och stoppa den berömda manipulationen redan från början.', title_vi = 'Cái cớ "thêm một ngụm nước" 💧', body_vi = 'Đúng lúc sắp ngủ say, bé bật dậy: "Con khát quá"? Mục đích không phải là nước, mà là được ở bên mẹ thêm một chút. Hãy đặt sẵn bình nước chống đổ cạnh giường để chặn trước "chiêu thao túng" nổi tiếng này.', title_zh = '“再喝一口水”的借口 💧', body_zh = '快睡着时，突然说“我好渴”，从床上跳起来？目的不是喝水，而是多和你待一会儿。提前在床边放一个防漏水杯，从一开始就堵住这个经典的小伎俩。' WHERE id = '4081d285-b739-4c34-a223-ae2922366de7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estoy cansada, pero no lo digo 📝', body_es = '¿Nadie ve lo nerviosa que has estado hoy y tener que sonreír a todo el mundo te ahoga? Abre el Diario de ánimo. Vuelca en la pantalla todo ese veneno y esa rabia de dentro. Desahogarte en digital te curará antes que un psicólogo.', title_fr = 'Je suis fatiguée, mais je ne le dis pas 📝', body_fr = 'Personne ne voit à quel point vous avez été à cran aujourd''hui, et sourire à tout le monde vous étouffe ? Ouvrez le Journal d''humeur. Déversez sur l''écran tout ce poison, toute cette colère. Tout vider numériquement vous soulagera plus vite qu''un psy.', title_hi = 'थक गई हूँ, पर कहती नहीं 📝', body_hi = 'कोई नहीं देखता कि आज आप कितनी परेशान रहीं, और सबके सामने मुस्कुराना आपका दम घोंट रहा है? मूड डायरी खोलिए। अंदर का सारा ज़हर और गुस्सा स्क्रीन पर उड़ेल दीजिए। यह डिजिटल भड़ास आपको मनोवैज्ञानिक से भी जल्दी ठीक करेगी।', title_id = 'Aku lelah, tapi tidak bilang 📝', body_id = 'Tak ada yang melihat betapa stresnya Anda hari ini, dan tersenyum kepada semua orang membuat Anda sesak? Buka Buku Harian Suasana Hati. Tumpahkan semua racun dan amarah di dalam diri ke layar. Curhat digital ini akan memulihkan Anda lebih cepat daripada psikolog.', title_ja = '疲れているけど言えない 📝', body_ja = '今日どれだけイライラしたか誰も気づかず、みんなに笑顔を向けるのが苦しい？「気分日記」を開いて、心の中の毒も怒りも全部画面に吐き出しましょう。デジタルで吐き出すことは、思っている以上に心を軽くしてくれます。', title_ko = '지쳤지만 말하지 않아요 📝', body_ko = '오늘 내가 얼마나 속이 상했는지 아무도 모르고, 모두에게 웃어 주는 게 숨 막히나요? 기분 일기를 열고 속에 쌓인 독과 화를 화면에 모두 쏟아 내세요. 디지털로 털어놓는 게 상담보다 더 빨리 회복시켜 줄 거예요.', title_nl = 'Ik ben moe, maar ik zeg het niet 📝', body_nl = 'Ziet niemand hoeveel je vandaag te verduren had en word je benauwd van naar iedereen glimlachen? Open je Stemmingsdagboek. Gooi al dat gif en die boosheid eruit op het scherm. Digitaal spuien heelt je sneller dan een psycholoog.', title_pl = 'Jestem zmęczona, ale tego nie mówię 📝', body_pl = 'Nikt nie widzi, ile dziś przeszłaś nerwów, a uśmiechanie się do wszystkich cię dusi? Otwórz Dziennik nastroju. Wylej na ekran całą truciznę i złość, które w sobie masz. Takie cyfrowe wyrzucenie z siebie wszystkiego uleczy cię szybciej niż psycholog.', title_pt = 'Estou cansada, mas não digo 📝', body_pt = 'Ninguém vê o quanto se enervou hoje e sorrir para toda a gente está a sufocá-la? Abra o Diário de Humor. Despeje no ecrã todo esse veneno e essa raiva. Desabafar no digital vai curá-la mais depressa do que um psicólogo.', title_sv = 'Jag är trött, men säger inget 📝', body_sv = 'Ser ingen hur mycket du har fått stå ut med i dag, och kväver det dig att le mot alla? Öppna Humördagboken. Häll ut allt gift och all ilska på skärmen. Att kräkas ut digitalt läker dig snabbare än en psykolog.', title_vi = 'Mẹ mệt, nhưng không nói ra 📝', body_vi = 'Không ai thấy hôm nay mẹ đã căng thẳng đến mức nào, và việc cứ phải mỉm cười với mọi người làm mẹ nghẹt thở? Hãy mở Nhật ký tâm trạng. Trút hết mọi bực bội, giận dữ trong lòng lên màn hình. "Xả" trên màn hình như vậy sẽ chữa lành cho mẹ nhanh hơn cả gặp chuyên gia tâm lý.', title_zh = '累了，但不说 📝', body_zh = '没人看到你今天受了多少气，对每个人微笑让你喘不过气？打开心情日记。把心里所有的“毒”和怒气都倒在屏幕上。这样的“数字倾吐”会比心理咨询更快治愈你。' WHERE id = '7b85f446-78f0-4be5-9cc1-c336a25ea658' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las rayas del asfalto son ley 🛣️', body_es = '¿Por la calle hace movimientos raros para no pisar las líneas entre las baldosas? La motricidad gruesa y la atención trabajan a la vez. No le metas prisa: cógele de la mano y salta tú también por encima de esas líneas.', title_fr = 'Les lignes du trottoir font la loi 🛣️', body_fr = 'Dans la rue, il fait des mouvements bizarres pour ne pas marcher sur les lignes entre les pavés ? Sa motricité globale et son attention travaillent en même temps. Ne le pressez pas, prenez-le par la main et sautez par-dessus les lignes vous aussi.', title_hi = 'फ़ुटपाथ की लकीरें कानून हैं 🛣️', body_hi = 'सड़क पर चलते समय पत्थरों के बीच की लकीरों पर पैर न रखने के लिए अजीब हरकतें करता है? बड़ी मोटर स्किल्स और ध्यान एक साथ काम कर रहे हैं। जल्दी मत कराइए, उसका हाथ थामिए और आप भी उन लकीरों के ऊपर से कूदिए।', title_id = 'Garis di trotoar adalah hukum 🛣️', body_id = 'Saat berjalan di luar, ia bergerak aneh supaya tidak menginjak garis di antara batu-batu? Motorik kasar dan perhatiannya bekerja bersamaan. Jangan terburu-buru, gandeng tangannya dan ikutlah melompati garis-garis itu.', title_ja = '道路の線はルール 🛣️', body_ja = '道を歩くとき、敷石の間の線をふまないようにふしぎな動きをする？粗大運動と注意力が同時に働いています。急がせずに手をつないで、あなたも一緒に線をぴょんと飛びこえましょう。', title_ko = '보도블록 선은 법이야 🛣️', body_ko = '길을 걸으며 보도블록 사이 선을 밟지 않으려고 이상한 동작을 하나요? 대근육 운동과 집중력이 동시에 작동하는 중이에요. 재촉하지 말고 손을 잡고 엄마도 함께 선을 뛰어넘어 보세요.', title_nl = 'De streepjes op de stoep zijn wet 🛣️', body_nl = 'Maakt hij op straat rare bewegingen om niet op de lijnen tussen de stoeptegels te stappen? Zijn grove motoriek en concentratie werken tegelijk. Jaag hem niet op, pak zijn hand en spring zelf ook over die lijnen.', title_pl = 'Linie na chodniku to prawo 🛣️', body_pl = 'Idąc ulicą, robi dziwne ruchy, żeby nie nadepnąć na linie między płytami? Motoryka duża i uwaga pracują jednocześnie. Nie poganiaj go, weź go za rękę i ty też przeskakuj te linie.', title_pt = 'As riscas do passeio são lei 🛣️', body_pt = 'Na rua, faz movimentos estranhos para não pisar as linhas entre as pedras? A motricidade grossa e a atenção estão a trabalhar ao mesmo tempo. Não o apresse: dê-lhe a mão e salte também por cima das linhas.', title_sv = 'Strecken på asfalten är lag 🛣️', body_sv = 'Gör barnet konstiga rörelser på gatan för att inte trampa på strecken mellan stenarna? Grovmotorik och uppmärksamhet arbetar samtidigt. Stressa inte, ta barnet i handen och hoppa över strecken du också.', title_vi = 'Vạch trên vỉa hè là luật 🛣️', body_vi = 'Đi trên đường, bé có những động tác kỳ lạ để không giẫm lên các đường nối giữa những viên gạch? Kỹ năng vận động thô và sự tập trung đang cùng lúc hoạt động. Đừng giục, hãy nắm tay bé và cùng nhảy qua những đường kẻ ấy.', title_zh = '地上的线就是法律 🛣️', body_zh = '在街上走路时，为了不踩到石砖之间的缝，做出各种奇怪的动作？大运动和注意力正在同时工作。别催，牵着宝宝的手，你也跟着跳过那些线吧。' WHERE id = '4c512e27-6d0e-434b-b3b6-e7db7541662c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo al desagüe 🛁', body_es = '¿Al salir de la bañera le da miedo el agujero por donde se va el agua? Su imaginación funciona de forma absurda. Pon ahí un barquito de juguete de plástico y dile: «Mira, este es el guardián, no se va a llevar nada». La fobia se convertirá al instante en juego.', title_fr = 'La peur du trou d''évacuation 🛁', body_fr = 'En sortant du bain, il a peur du trou par où l''eau s''écoule ? Son imagination fonctionne de façon absurde. Posez-y un petit bateau en plastique et dites « Regarde, c''est un gardien, il n''aspirera rien ». La phobie sera aussitôt remplacée par le jeu.', title_hi = 'पानी जाने वाले छेद का डर 🛁', body_hi = 'टब से निकलते समय उस छेद से डरता है जिससे पानी बह जाता है? उसकी कल्पना बेतुके ढंग से काम कर रही है। वहाँ एक प्लास्टिक की खिलौना नाव रखिए और कहिए, ‘देखो, यह रक्षक है, यह कुछ भी नहीं खींचेगा।’ डर तुरंत खेल में बदल जाएगा।', title_id = 'Takut lubang pembuangan air 🛁', body_id = 'Saat keluar dari bak mandi ia takut pada lubang tempat air mengalir? Imajinasinya bekerja secara absurd. Letakkan kapal mainan plastik di sana dan katakan ''Lihat, ini penjaganya, ia tidak akan menyedot apa pun''. Fobianya langsung tergantikan oleh permainan.', title_ja = '排水口こわい 🛁', body_ja = 'お風呂から出るとき、お湯が流れていく排水口がこわい？想像力がふしぎに働いています。そこにプラスチックのおもちゃの船を置いて「見て、これが守ってくれるから、何も吸いこまないよ」と言いましょう。こわさはすぐに遊びに変わります。', title_ko = '배수구가 무서워 🛁', body_ko = '목욕을 마치고 물이 빠져나가는 배수구를 무서워하나요? 상상력이 엉뚱하게 움직이는 중이에요. 그곳에 플라스틱 장난감 배를 놓고 ''봐, 이게 지켜 주니까 아무것도 빨려 들어가지 않아'' 하고 말해 주세요. 두려움이 금세 놀이로 바뀔 거예요.', title_nl = 'Bang voor het afvoerputje 🛁', body_nl = 'Is hij bang voor het putje waar het water wegloopt als hij uit bad komt? Zijn fantasie slaat absurde wegen in. Leg er een plastic speelgoedbootje op en zeg: ''Kijk, dit is de beschermer, hij laat niets naar binnen zuigen.'' De angst verandert meteen in een spel.', title_pl = 'Strach przed odpływem 🛁', body_pl = 'Przy wychodzeniu z wanny boi się odpływu, którym spływa woda? Wyobraźnia pracuje absurdalnie. Połóż tam plastikowy stateczek i powiedz: „Zobacz, to strażnik, nic nie wciągnie”. Fobia od razu zamieni się w zabawę.', title_pt = 'Medo do ralo da banheira 🛁', body_pt = 'Ao sair da banheira, tem medo do ralo por onde a água se vai? A imaginação está a trabalhar de forma absurda. Ponha lá um barquinho de plástico e diga "Olha, este é o guarda, não deixa sugar nada". A fobia transforma-se logo em brincadeira.', title_sv = 'Rädd för avloppet 🛁', body_sv = 'Är barnet rädd för hålet där vattnet rinner ut när hen kliver ur badet? Fantasin arbetar absurt. Lägg en leksaksbåt i plast där och säg ”Titta, den är en vakt, den suger inte ner något”. Fobin byts genast ut mot lek.', title_vi = 'Nỗi sợ lỗ thoát nước 🛁', body_vi = 'Bước ra khỏi bồn tắm, bé sợ cái lỗ nơi nước chảy đi? Trí tưởng tượng của bé đang hoạt động một cách phi lý. Hãy đặt một chiếc thuyền đồ chơi bằng nhựa ở đó: "Nhìn này, đây là người bảo vệ, nó sẽ không hút thứ gì đâu." Nỗi sợ sẽ lập tức nhường chỗ cho trò chơi.', title_zh = '害怕下水口 🛁', body_zh = '洗完澡，害怕水流走的那个洞？想象力天马行空。在那里放一艘塑料小船，说“看，这是保护罩，什么都不会被吸走”。恐惧马上就会被游戏取代。' WHERE id = '685cde5b-1133-4e8c-aa85-09d262ad4afb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un concierto que empieza a las 6 de la mañana 🎤', body_es = '¿Nada más abrir los ojos se pone a cantar a todo volumen una canción inventada? No cortes esa energía loca con un «Calla, que vas a despertar a los vecinos». Únete tú también. Un niño que empieza el día cantando está menos agresivo el resto del día.', title_fr = 'Le concert de 6 heures du matin 🎤', body_fr = 'Dès qu''il ouvre les yeux, il chante à pleine voix une chanson inventée ? Ne coupez pas cette énergie folle avec un « Chut, tu vas réveiller les voisins ». Joignez-vous à lui. Un enfant qui commence la matinée en chanson est moins agressif toute la journée.', title_hi = 'सुबह 6 बजे शुरू होने वाला कॉन्सर्ट 🎤', body_hi = 'आँख खुलते ही पूरी आवाज़ में कोई गढ़ा हुआ गाना गाने लगता है? ‘चुप रहो, पड़ोसी जाग जाएँगे’ कहकर उस मस्त ऊर्जा को मत रोकिए। आप भी साथ गाइए। जो बच्चा सुबह गाने से शुरुआत करता है, वह दिनभर कम चिड़चिड़ा रहता है।', title_id = 'Konser yang dimulai jam 6 pagi 🎤', body_id = 'Begitu membuka mata, ia menyanyikan lagu karangannya keras-keras? Jangan potong energi gilanya itu dengan berkata ''Ssst, nanti tetangga bangun''. Ikutlah bernyanyi. Anak yang memulai pagi dengan lagu akan lebih sedikit agresif sepanjang hari.', title_ja = '朝6時からのコンサート 🎤', body_ja = '目を開けたとたん、大きな声でつくった歌をうたう？「しーっ、おとなりさんが起きちゃう」とそのパワフルなエネルギーを止めないで。あなたも一緒にうたって。朝を歌で始めた子は、一日じゅう穏やかに過ごせます。', title_ko = '새벽 6시의 콘서트 🎤', body_ko = '눈뜨자마자 목청껏 지어낸 노래를 부르나요? ''조용히 해, 이웃 깨겠어'' 하며 그 넘치는 에너지를 끊지 마세요. 엄마도 함께 불러요. 노래로 아침을 시작한 아이는 하루 종일 덜 공격적이에요.', title_nl = 'Het concert van 6 uur ''s ochtends 🎤', body_nl = 'Zingt hij zodra hij zijn ogen opendoet uit volle borst een zelfverzonnen liedje? Onderbreek die gekke energie niet met ''Stil, de buren worden wakker''. Zing mee. Een kind dat de dag met een liedje begint, is de rest van de dag minder agressief.', title_pl = 'Koncert od 6 rano 🎤', body_pl = 'Ledwo otworzy oczy, a już na cały głos śpiewa wymyśloną piosenkę? Nie przerywaj tej szalonej energii słowami „Cicho, sąsiedzi się obudzą”. Przyłącz się. Dziecko, które zaczyna dzień od piosenki, przez cały dzień jest mniej agresywne.', title_pt = 'O concerto que começa às 6 da manhã 🎤', body_pt = 'Mal abre os olhos, canta a plenos pulmões uma canção inventada? Não corte aquela energia louca com um "Chiu, vais acordar os vizinhos". Junte-se a ele. A criança que começa a manhã a cantar fica menos agressiva durante o dia.', title_sv = 'Konserten som börjar klockan 6 🎤', body_sv = 'Sjunger barnet en påhittad låt för full hals så fort ögonen öppnas? Säg inte ”Tyst, grannarna vaknar” och bryt inte den galna energin. Var med du också. Ett barn som börjar morgonen med sång är mindre aggressivt under dagen.', title_vi = 'Buổi hòa nhạc lúc 6 giờ sáng 🎤', body_vi = 'Vừa mở mắt, bé đã hát vang một bài tự nghĩ ra? Đừng dập tắt nguồn năng lượng ấy bằng câu "Suỵt, hàng xóm thức dậy bây giờ". Hãy hát cùng bé. Đứa trẻ bắt đầu buổi sáng bằng bài hát sẽ ít cáu gắt hơn cả ngày.', title_zh = '早上6点开始的演唱会 🎤', body_zh = '一睁眼就放声高唱自己编的歌？别说“小声点，邻居要醒了”去打断那股疯狂的能量。你也一起唱吧。用歌声开始早晨的孩子，一整天都会少些攻击性。' WHERE id = 'e7c8a731-9f6f-40fe-bb36-efba9869846f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baile de los 0 decibelios del silencio 🤫', body_es = 'Por fin la habitación está a oscuras y se ha dormido. Hay tanto silencio en casa que se te taponan los oídos. Abre el Medidor de sonido en la app. Ver cómo el número de la pantalla baja a 0 decibelios es un auténtico masaje digital para tu cerebro saturado de ruido.', title_fr = 'La danse du silence à 0 décibel 🤫', body_fr = 'Enfin, la chambre est sombre et il dort. Un tel silence est tombé sur la maison que vos oreilles se bouchent. Ouvrez le Sonomètre dans l''application. Regarder le chiffre descendre à 0 décibel à l''écran, c''est un vrai massage numérique pour votre cerveau saturé de bruit.', title_hi = 'खामोशी का 0 डेसिबल वाला नाच 🤫', body_hi = 'आखिरकार कमरे में अंधेरा है और वह सो गया। घर में ऐसा सन्नाटा छाया है कि कान सुन्न हो गए हैं। ऐप में साउंड मीटर खोलिए। स्क्रीन पर 0 डेसिबल तक गिरता आँकड़ा देखना आपके शोर से भरे दिमाग के लिए असली डिजिटल मसाज है।', title_id = 'Tarian 0 desibel keheningan 🤫', body_id = 'Akhirnya kamar gelap dan ia tertidur. Rumah begitu hening sampai telinga Anda terasa tersumbat. Buka Pengukur Suara di aplikasi. Melihat angka di layar turun ke 0 desibel adalah pijatan digital sejati untuk otak Anda yang penuh kebisingan.', title_ja = '静けさの0デシベルダンス 🤫', body_ja = 'やっと部屋が暗くなって、寝てくれた。家が静かすぎて耳がつまりそう。アプリで「サウンドメーター」を開きましょう。画面の数字が0デシベルまで下がるのを眺めるのは、騒音でいっぱいの頭への本物のデジタルマッサージです。', title_ko = '고요가 춤추는 0 데시벨 🤫', body_ko = '드디어 방이 어두워지고 아이가 잠들었어요. 집이 너무 고요해져 귀가 먹먹한가요? 앱에서 소음 측정기를 열어 보세요. 화면의 숫자가 0 데시벨로 내려가는 걸 보는 건 소음에 지친 머리에 진짜 디지털 마사지예요.', title_nl = 'De 0-decibeldans van de stilte 🤫', body_nl = 'Eindelijk is de kamer donker en slaapt hij. Het is zo stil in huis dat je oren dichtzitten. Open de Geluidsmeter in de app. Kijken hoe het getal op het scherm naar 0 decibel zakt is een echte digitale massage voor je door lawaai overprikkelde brein.', title_pl = 'Taniec ciszy na 0 decybelach 🤫', body_pl = 'Wreszcie w pokoju ciemno, a on śpi. W domu zapadła taka cisza, że aż zatyka ci uszy. Otwórz w aplikacji Miernik dźwięku. Patrzenie, jak liczba na ekranie spada do 0 decybeli, to prawdziwy cyfrowy masaż dla twojego przeładowanego hałasem mózgu.', title_pt = 'A dança dos 0 decibéis do silêncio 🤫', body_pt = 'Finalmente o quarto está às escuras e ele adormeceu. Caiu um silêncio tão grande que até lhe tapa os ouvidos. Abra o Medidor de Som na app. Ver no ecrã o número a descer até aos 0 decibéis é uma verdadeira massagem digital para o seu cérebro inchado de barulho.', title_sv = 'Tystnadens dans på 0 decibel 🤫', body_sv = 'Äntligen är rummet mörkt och barnet sover. Det har blivit så tyst att det slår lock för öronen. Öppna Ljudmätaren i appen. Att se siffran på skärmen sjunka till 0 decibel är en riktig digital massage för din bullerfyllda hjärna.', title_vi = 'Vũ điệu 0 decibel của sự im lặng 🤫', body_vi = 'Cuối cùng phòng đã tối và bé đã ngủ. Nhà yên tĩnh đến mức tai mẹ như ù đi. Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số trên màn hình hạ xuống 0 decibel là màn mát-xa kỹ thuật số thực thụ cho bộ não căng thẳng vì tiếng ồn của mẹ.', title_zh = '0分贝的安静之舞 🤫', body_zh = '房间终于暗下来，宝宝睡着了。家里安静得让你耳朵发闷。打开应用里的分贝仪。看着屏幕上的数字降到0分贝，对你那被噪音塞满的大脑来说，就是一次真正的数字按摩。' WHERE id = '7dbcfeb4-6b0f-40e0-a421-e16781d15f4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi juguete se ha enfadado contigo 🧸', body_es = '¿Has gritado y ha venido a decirte «Mi osito se ha enfadado contigo»? Te transmite sus propias emociones a través de las cosas. Pídele perdón al osito muy en serio y abrázalo. Verás cómo el peque se queda tranquilo.', title_fr = 'Mon jouet est fâché contre toi 🧸', body_fr = 'Parce que vous avez crié, il est venu vous dire « Mon nounours est fâché contre toi » ? Il vous transmet ses propres émotions à travers les objets. Présentez très sérieusement vos excuses au nounours et serrez-le dans vos bras. Vous verrez comme l''enfant se détend.', title_hi = 'मेरा खिलौना तुमसे रूठ गया 🧸', body_hi = 'आप चिल्लाईं, तो आकर बोला, ‘मेरा भालू तुमसे रूठ गया’? वह अपनी भावनाएँ चीज़ों पर डालकर आप तक पहुँचा रहा है। भालू से बड़ी गंभीरता से माफ़ी माँगिए और उसे गले लगाइए। देखिए, बच्चा कैसे शांत हो जाता है।', title_id = 'Mainanku ngambek sama Mama 🧸', body_id = 'Karena Anda berteriak, ia datang dan berkata ''Beruangku ngambek sama Mama''? Ia menyampaikan perasaannya sendiri lewat benda. Minta maaflah pada si beruang dengan sangat serius dan peluk ia. Anda akan melihat betapa leganya anak Anda.', title_ja = 'ぼくのおもちゃがママにすねたよ 🧸', body_ja = 'あなたが大きな声を出したら「くまさんがママにすねたって」と言いに来た？自分の気持ちをものにのせて伝えています。くまさんにとても真剣にあやまって、抱きしめてあげて。子どもがほっとするのがわかりますよ。', title_ko = '내 장난감이 엄마한테 삐졌어 🧸', body_ko = '엄마가 소리쳤다고 와서 ''내 곰돌이가 엄마한테 삐졌어''라고 했나요? 자기 감정을 물건에 담아 전하는 거예요. 곰돌이에게 아주 진지하게 사과하고 안아 주세요. 아이가 금세 편안해지는 걸 볼 거예요.', title_nl = 'Mijn knuffel is boos op je 🧸', body_nl = 'Kwam hij zeggen ''Mijn beer is boos op je'' omdat je schreeuwde? Hij legt zijn eigen gevoelens bij een speeltje om ze aan jou duidelijk te maken. Bied de beer heel serieus je excuses aan en knuffel hem. Je ziet meteen hoe je kind ontspant.', title_pl = 'Moja zabawka się na ciebie obraziła 🧸', body_pl = 'Przyszedł i powiedział: „Mój miś się na ciebie obraził”, bo krzyknęłaś? Przekazuje ci swoje emocje przez przedmioty. Bardzo poważnie przeproś misia i go przytul. Zobaczysz, jak dziecku ulży.', title_pt = 'O meu brinquedo está amuado contigo 🧸', body_pt = 'Veio dizer-lhe "O meu urso está amuado contigo" porque gritou? Está a transmitir-lhe as próprias emoções através dos objetos. Peça desculpa ao urso muito a sério e abrace-o. Vai ver como a criança fica aliviada.', title_sv = 'Min leksak är sur på dig 🧸', body_sv = 'Kom barnet och sa ”Nallen är sur på dig” för att du skrek? Hen förmedlar sina egna känslor genom föremål. Be nallen om ursäkt på fullt allvar och krama den. Du kommer att se hur barnet slappnar av.', title_vi = 'Đồ chơi của con giận mẹ rồi 🧸', body_vi = 'Vì mẹ quát nên bé đến bảo: "Gấu của con giận mẹ rồi"? Bé đang gửi cảm xúc của mình vào đồ vật để nói với mẹ. Hãy xin lỗi chú gấu thật nghiêm túc và ôm nó. Mẹ sẽ thấy bé nhẹ nhõm ra sao.', title_zh = '我的玩具生你的气了 🧸', body_zh = '因为你吼了，宝宝过来说“我的小熊生你的气了”？宝宝是借着物品把自己的情绪传达给你。非常认真地向小熊道歉，再抱抱它。你会看到宝宝一下子放松了。' WHERE id = '80129e61-cd59-4c54-9d5e-e6507c3811da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué sale vapor del té? ☕', body_es = '¿Mira el vapor que sale de tu taza y te hace preguntas o le da miedo? ¿No sabes darle una explicación científica? Pide a Anacan AI una explicación filosófica y tierna para 4 años: «Sale volando para unirse a las nubes».', title_fr = 'Pourquoi le thé fume ? ☕', body_fr = 'Il regarde la vapeur qui sort de votre tasse et vous pose des questions, ou il a peur ? Vous ne savez pas comment l''expliquer scientifiquement ? Demandez à Anacan AI une explication douce et philosophique pour un enfant de 4 ans : « Elle s''envole pour rejoindre les nuages. »', title_hi = 'चाय से भाप क्यों निकलती है? ☕', body_hi = 'आपके कप से निकलती भाप देखकर सवाल पूछता है या डरता है? वैज्ञानिक जवाब नहीं सूझ रहा? Anacan AI से 4 साल के बच्चे के लिए दार्शनिक और प्यारा जवाब लीजिए: ‘यह बादलों से मिलने उड़ रही है।’', title_id = 'Kenapa tehnya beruap? ☕', body_id = 'Ia melihat uap yang keluar dari cangkir Anda lalu bertanya atau malah takut? Tidak bisa memberi penjelasan ilmiah? Dapatkan penjelasan filosofis yang manis untuk usia 4 tahun dari Anacan AI: ''Ia terbang untuk bergabung dengan awan.''', title_ja = 'お茶からなんで湯気が出るの？ ☕', body_ja = 'カップから出る湯気を見て、わけを聞いたり、こわがったりする？科学的に説明できない？Anacan AIで、4歳向けの哲学的でかわいい説明をもらいましょう。「雲の仲間になりに飛んでいくんだよ」。', title_ko = '차에서 왜 김이 나? ☕', body_ko = '컵에서 피어오르는 김을 보며 이유를 묻거나 무서워하나요? 과학적으로 설명하기 어렵다면 Anacan AI에게 4세에게 맞는 철학적이고 귀여운 설명을 받아 보세요: ''구름이랑 만나려고 날아가는 거야.''', title_nl = 'Waarom dampt de thee? ☕', body_nl = 'Kijkt hij naar de damp uit je kopje en vraagt hij je om uitleg, of is hij er bang voor? Lukt een wetenschappelijke uitleg niet? Vraag Anacan AI om een filosofische, lieve uitleg voor een 4-jarige: ''Hij vliegt omhoog om bij de wolken te horen.''', title_pl = 'Czemu herbata paruje? ☕', body_pl = 'Patrzy na parę unoszącą się z twojej filiżanki i domaga się wyjaśnień albo się boi? Nie umiesz wytłumaczyć tego naukowo? Weź od Anacan AI filozoficzne i urocze wyjaśnienie dla 4-latka: „Ona leci, żeby dołączyć do chmur”.', title_pt = 'Porque é que o chá deita fumo? ☕', body_pt = 'Olha para o vapor que sai da sua chávena e pede-lhe explicações, ou tem medo? Não consegue dar uma explicação científica? Peça ao Anacan AI uma explicação filosófica e doce para os 4 anos: "Está a voar para se juntar às nuvens".', title_sv = 'Varför ångar teet? ☕', body_sv = 'Tittar barnet på ångan från din kopp och kräver en förklaring eller blir rädd? Kan du inte ge en vetenskaplig förklaring? Få en filosofisk och söt förklaring för en 4-åring från Anacan AI: Den flyger iväg för att följa med molnen.', title_vi = 'Sao trà lại bốc hơi? ☕', body_vi = 'Bé nhìn hơi nước bốc lên từ tách và hỏi mẹ, hoặc thậm chí sợ hãi? Mẹ không giải thích khoa học được? Hãy hỏi Anacan AI một lời giải thích ngọt ngào, đậm chất triết lý cho bé 4 tuổi: "Hơi nước bay lên để nhập vào những đám mây."', title_zh = '茶为什么冒气？☕', body_zh = '看着杯子里冒出的热气，问你为什么，或者有点害怕？给不出科学解释？从Anacan AI那里拿一个适合4岁孩子的、有哲理又可爱的解释：“它飞上去，去和云朵会合啦。”' WHERE id = 'e7d3487a-45d4-44a3-bf97-c34082190904' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La guerra de la chaqueta 🧥', body_es = 'Fuera hace sol, pero no quiere ponerse la chaqueta. No te dejes engañar mirando por la ventana: enséñale la temperatura real y la imagen del niño vestido por capas de la herramienta Tiempo y ropa. Deja la regla en manos del móvil.', title_fr = 'La bataille du blouson 🧥', body_fr = 'Il fait soleil dehors, mais il ne veut pas mettre son blouson. Ne vous fiez pas à ce que vous voyez par la fenêtre : montrez-lui la vraie température et l''image de l''enfant habillé en plusieurs couches dans l''outil Météo et tenue. Confiez la règle au téléphone.', title_hi = 'जैकेट की जंग 🧥', body_hi = 'बाहर धूप है, पर वह जैकेट नहीं पहनना चाहता। खिड़की से देखकर धोखा मत खाइए, मौसम और कपड़े टूल में असली तापमान और परतों में कपड़े पहने बच्चे की तस्वीर उसे दिखाइए। नियम फ़ोन के हवाले कर दीजिए।', title_id = 'Perang jaket 🧥', body_id = 'Di luar cerah, tapi ia tidak mau memakai jaketnya. Jangan tertipu dengan melihat dari jendela, tunjukkan suhu sebenarnya dan gambar anak berpakaian berlapis di Cuaca dan Pakaian. Serahkan aturannya pada ponsel.', title_ja = 'ジャケット戦争 🧥', body_ja = '外は晴れているのに、ジャケットを着たがらない。窓の外を見てだまされないで。「天気と服装」の本当の気温と、重ね着した子どもの絵を見せましょう。ルールはスマホにまかせて。', title_ko = '점퍼 전쟁 🧥', body_ko = '밖에 해가 났다고 점퍼를 안 입겠대요? 창밖만 보고 속지 마세요. 날씨와 옷차림 도구의 실제 기온과 겹쳐 입은 아이 그림을 보여 주세요. 규칙은 휴대폰에 맡기세요.', title_nl = 'Jassenstrijd 🧥', body_nl = 'Buiten schijnt de zon, maar hij wil zijn jas niet aan. Laat je niet misleiden door een blik uit het raam: laat hem de echte temperatuur en het plaatje van een kind in laagjes zien in Weer en kleding. Laat de telefoon de regel stellen.', title_pl = 'Wojna o kurtkę 🧥', body_pl = 'Na dworze świeci słońce, ale on nie chce założyć kurtki. Nie daj się zwieść widokowi z okna, pokaż mu w narzędziu Pogoda i ubiór prawdziwą temperaturę i obrazek dziecka ubranego na cebulkę. Przenieś zasadę na telefon.', title_pt = 'A guerra do casaco 🧥', body_pt = 'Lá fora está sol, mas ele não quer vestir o casaco. Não se deixe enganar pela janela: mostre-lhe a temperatura real e a imagem da criança vestida por camadas na ferramenta Tempo e Roupa. Passe a regra para o telemóvel.', title_sv = 'Jackkriget 🧥', body_sv = 'Solen skiner ute, men barnet vill inte ta på sig jackan. Låt dig inte luras av att titta ut genom fönstret, visa den verkliga temperaturen och bilden på barnet klätt i lager i verktyget Väder och kläder. Lägg regeln på telefonen.', title_vi = 'Cuộc chiến áo khoác 🧥', body_vi = 'Ngoài trời có nắng, nhưng bé không chịu mặc áo khoác. Đừng để bị đánh lừa khi chỉ nhìn qua cửa sổ, hãy cho bé xem nhiệt độ thực tế và hình em bé mặc nhiều lớp trong Thời tiết và trang phục. Để điện thoại đặt ra quy tắc.', title_zh = '外套大战 🧥', body_zh = '外面有太阳，可宝宝不肯穿外套。别被窗外的景象骗了，给宝宝看看天气与穿衣工具里的真实温度和穿了好几层的小朋友图片。把规则交给手机。' WHERE id = '1bdc66c1-4583-42f2-a981-0ba814be491d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué no me ha mirado el pájaro? 🐦', body_es = '¿Ha llorado a moco tendido en el parque porque una paloma se ha ido volando? No busques lógica. Para él es de verdad una gran desilusión. Valida su emoción con cariño: «Te va a echar mucho de menos».', title_fr = 'Pourquoi l''oiseau ne m''a pas regardé ? 🐦', body_fr = 'Il a sangloté parce qu''un pigeon s''est envolé au parc ? Ne cherchez pas de logique. Pour lui, c''est vraiment une grosse déception. Dites « Il va beaucoup s''ennuyer de toi » et validez son émotion avec amour.', title_hi = 'चिड़िया ने मुझे क्यों नहीं देखा? 🐦', body_hi = 'पार्क में एक कबूतर उड़ गया, इसलिए फूट-फूटकर रोया? कमरे में तर्क मत ढूँढिए। उसके लिए यह सच में बड़ी निराशा है। ‘वह तुम्हें बहुत याद करेगा’ कहकर प्यार से उसकी भावना को स्वीकार कीजिए।', title_id = 'Kenapa burungnya tidak melihatku? 🐦', body_id = 'Ia menangis tersedu-sedu karena seekor merpati di taman terbang pergi? Jangan cari logika di sini. Baginya ini benar-benar kekecewaan besar. Akui perasaannya dengan penuh cinta, katakan ''Ia pasti akan sangat merindukanmu''.', title_ja = 'なんで鳥はぼくを見なかったの？ 🐦', body_ja = '公園でハトが飛んでいってしまって大泣き？理屈を探さないで。この子にとっては本当に大きながっかりなんです。「ハトさんもあなたに会えなくてさびしいよ」と言って、気持ちを愛情こめて受けとめましょう。', title_ko = '새가 왜 나를 안 봤어? 🐦', body_ko = '공원에서 비둘기가 날아가 버렸다고 엉엉 울었나요? 논리를 찾지 마세요. 아이에게는 정말 큰 실망이에요. ''새도 너를 많이 보고 싶어 할 거야'' 하며 그 마음을 사랑으로 인정해 주세요.', title_nl = 'Waarom keek de vogel niet naar mij? 🐦', body_nl = 'Huilde hij tranen met tuiten omdat een duif in het park wegvloog? Zoek geen logica. Voor hem is dit echt een grote teleurstelling. Erken zijn gevoel liefdevol met: ''Hij gaat je heel erg missen.''', title_pl = 'Czemu ptak na mnie nie spojrzał? 🐦', body_pl = 'Szlochał w parku, bo gołąb odleciał? Nie szukaj logiki. Dla niego to naprawdę wielkie rozczarowanie. Powiedz: „Będzie bardzo za tobą tęsknił” i z miłością uznaj jego uczucia.', title_pt = 'Porque é que o pássaro não olhou para mim? 🐦', body_pt = 'Chorou aos soluços porque um pombo voou no parque? Não procure lógica. Para ele, é mesmo uma grande desilusão. Valide o sentimento dele com amor: "Ele vai ter muitas saudades tuas".', title_sv = 'Varför tittade inte fågeln på mig? 🐦', body_sv = 'Grät barnet förtvivlat för att en duva flög iväg i parken? Leta inte efter logik. För barnet är det verkligen en stor besvikelse. Säg ”Den kommer att sakna dig så mycket” och bekräfta känslan med kärlek.', title_vi = 'Sao chim không nhìn con? 🐦', body_vi = 'Bé khóc nức nở vì một chú chim bồ câu trong công viên bay mất? Đừng tìm logic. Với bé, đây thật sự là một nỗi thất vọng lớn. Hãy yêu thương công nhận cảm xúc của bé: "Chắc chú chim sẽ nhớ con lắm."', title_zh = '小鸟为什么不看我？🐦', body_zh = '因为公园里的一只鸽子飞走了，哭得稀里哗啦？别在这里找逻辑。对宝宝来说，这真的是很大的失望。说“它会很想你的”，用爱认可宝宝的情绪。' WHERE id = '8b4c98d1-27b9-49ae-b0a2-f93f650bdd45' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que el cuento lleve mi nombre 🪄', body_es = '¿Está harto de los protagonistas de los libros clásicos? En Cuentos inteligentes cambia el nombre del protagonista por el suyo. Cuando oiga lo valiente que es él mismo al dormirse, se rendirá al sueño sin ninguna protesta.', title_fr = 'Je veux mon prénom dans le conte 🪄', body_fr = 'Il en a assez des héros des livres classiques ? Dans les Contes intelligents, remplacez le nom du héros par son prénom. En entendant comme il s''endort courageusement, il cédera au sommeil sans la moindre protestation.', title_hi = 'कहानी में मेरा नाम हो 🪄', body_hi = 'पुरानी किताबों के हीरो से ऊब गया? स्मार्ट कहानियों में हीरो का नाम उसके नाम से बदल दीजिए। जब सुनेगा कि वह खुद कितनी बहादुरी से सो गया, तो बिना किसी विरोध के नींद के आगे हार मान लेगा।', title_id = 'Mau namaku ada di dongeng 🪄', body_id = 'Ia bosan dengan tokoh-tokoh di buku klasik? Di Dongeng Pintar, ganti nama tokohnya dengan namanya. Saat mendengar dirinya tidur dengan berani, ia akan menyerah pada kantuk tanpa protes sedikit pun.', title_ja = 'お話にわたしの名前を 🪄', body_ja = '昔の絵本の主人公にあきてしまった？「スマートおはなし」で、主人公の名前をお子さんの名前に変えましょう。自分が勇敢に眠るお話を聞けば、文句も言わずに眠りに落ちますよ。', title_ko = '동화 속에 내 이름을 넣어 줘 🪄', body_ko = '고전 책 속 주인공들에 질렸나요? 스마트 동화에서 주인공 이름을 아이 이름으로 바꿔 보세요. 자기가 용감하게 잠드는 이야기를 들으면 아무 저항 없이 잠에 항복할 거예요.', title_nl = 'Mijn naam in het sprookje 🪄', body_nl = 'Is hij de helden uit klassieke boekjes beu? Vervang in Slimme sprookjes de naam van de held door zijn naam. Als hij hoort hoe dapper hij zelf gaat slapen, geeft hij zich zonder protest over aan de slaap.', title_pl = 'Niech w bajce będzie moje imię 🪄', body_pl = 'Znudzili mu się bohaterowie klasycznych książek? Zmień w Mądrych bajkach imię bohatera na jego imię. Gdy usłyszy, jak dzielnie sam zasypia, podda się snowi bez żadnego sprzeciwu.', title_pt = 'Quero o meu nome na história 🪄', body_pt = 'Está farto dos heróis dos livros clássicos? Nas Histórias Inteligentes, troque o nome do herói pelo nome dele. Ao ouvir como ele próprio adormece com coragem, vai render-se ao sono sem protestar.', title_sv = 'Låt sagan ha mitt namn 🪄', body_sv = 'Är barnet trött på hjältarna i de klassiska böckerna? Byt hjältens namn mot barnets i Smarta sagor. När hen hör hur modigt hen själv somnar ger hen upp för sömnen utan minsta protest.', title_vi = 'Truyện có tên của con 🪄', body_vi = 'Bé đã chán những nhân vật trong sách kinh điển? Trong Truyện cổ tích thông minh, hãy đổi tên nhân vật chính thành tên của bé. Nghe chính mình dũng cảm đi ngủ ra sao, bé sẽ chịu thua giấc ngủ mà không phản đối gì.', title_zh = '故事里要有我的名字 🪄', body_zh = '看腻了经典书里的主角？在智慧童话里，把主角的名字换成宝宝的名字。听到自己多么勇敢地睡着了，宝宝就会毫无异议地乖乖入睡。' WHERE id = 'cbcac766-bab8-4183-80ab-82267106b24d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy soy un coche 🚗', body_es = '¿Por la mañana te dice «No soy un niño, soy un coche»? No pongas reglas. Dile: «Entonces vamos a llenarte el depósito (de papilla) para que corras rápido». Estos juegos de rol graciosos son muchísimo más fáciles que gritar.', title_fr = 'Aujourd''hui, je suis une voiture 🚗', body_fr = 'Le matin, il vous dit « Je suis pas un enfant, je suis une voiture » ? N''imposez pas de règle. Dites « Alors viens, on fait le plein d''essence (de bouillie) pour que tu roules vite ». Ces jeux de rôle comiques sont bien plus faciles que de crier.', title_hi = 'आज मैं गाड़ी हूँ 🚗', body_hi = 'सुबह आपसे कहता है, ‘मैं बच्चा नहीं, गाड़ी हूँ’? नियम मत थोपिए। कहिए, ‘तो चलो तुम्हारा पेट्रोल (दलिया) भर दें, ताकि तुम तेज़ दौड़ सको।’ ये मज़ेदार रोल-प्ले चिल्लाने से कहीं ज़्यादा आसान हैं।', title_id = 'Hari ini aku mobil 🚗', body_id = 'Pagi ini ia berkata ''Aku bukan anak, aku mobil''? Jangan buat aturan. Katakan ''Kalau begitu, yuk isi bensinmu (buburmu) supaya bisa melaju cepat''. Permainan peran lucu seperti ini jauh lebih mudah daripada berteriak.', title_ja = '今日のぼくは車 🚗', body_ja = '朝「ぼく、子どもじゃない、車だよ」と言う？ルールを決めないで。「じゃあ、速く走れるようにガソリン（おかゆ）を入れようね」と言いましょう。こんなおかしなごっこ遊びのほうが、叫ぶよりずっと楽です。', title_ko = '오늘 나는 자동차야 🚗', body_ko = '아침에 ''나는 아이가 아니라 자동차야''라고 하나요? 규칙을 들이밀지 마세요. ''그럼 빨리 달리게 기름(죽)부터 넣자'' 하고 말해 주세요. 이런 재미있는 역할 놀이가 소리치는 것보다 훨씬 쉬워요.', title_nl = 'Vandaag ben ik een auto 🚗', body_nl = 'Zegt hij ''s ochtends: ''Ik ben geen kind, ik ben een auto''? Ga geen regels stellen. Zeg: ''Kom, dan tanken we je benzine (pap), zodat je hard kunt rijden.'' Zulke grappige rollenspellen zijn veel makkelijker dan schreeuwen.', title_pl = 'Dziś jestem samochodem 🚗', body_pl = 'Rano mówi ci: „Nie jestem dzieckiem, jestem samochodem”? Nie ustalaj zasad. Powiedz: „To zatankujmy ci benzynę (owsiankę), żebyś szybko jeździł”. Takie zabawne odgrywanie ról jest dużo łatwiejsze niż krzyk.', title_pt = 'Hoje sou um carro 🚗', body_pt = 'De manhã diz-lhe "Não sou uma criança, sou um carro"? Não imponha regras. Diga "Então vamos encher o teu depósito (de papas) para andares depressa". Estes jogos de faz de conta cómicos são muito mais fáceis do que gritar.', title_sv = 'I dag är jag en bil 🚗', body_sv = 'Säger barnet på morgonen: ”Jag är inget barn, jag är en bil”? Sätt inte upp regler. Säg ”Då tankar vi din bensin (gröt) så att du kan köra fort”. De här roliga rollekarna är mångdubbelt lättare än att skrika.', title_vi = 'Hôm nay con là ô tô 🚗', body_vi = 'Sáng ra bé nói với mẹ: "Con không phải em bé, con là ô tô"? Đừng đặt luật. Hãy nói: "Vậy mình đổ xăng (cháo) cho xe để chạy thật nhanh nhé." Những trò nhập vai hài hước này dễ hơn la hét gấp nhiều lần.', title_zh = '今天我是一辆汽车 🚗', body_zh = '早上对你说：“我不是小孩，我是汽车”？别定规矩。说“那我们来给你加点油（粥），这样你就能跑得快啦”。这种搞笑的角色扮演，比吼叫轻松多了。' WHERE id = '83683b1a-77a6-45bf-bf9e-6b7ae022a7e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una tarta hecha de arena 🏖️', body_es = '¿En el parque ha mezclado agua y tierra, se ha puesto perdido de barro y te ha hecho una tarta? Olvida la limpieza. Esto es motricidad fina y creatividad.', title_fr = 'Le gâteau de sable 🏖️', body_fr = 'Au parc, il a mélangé l''eau et la terre, s''est couvert de boue et vous a préparé un gâteau ? Oubliez la propreté. C''est de la motricité fine et de la créativité.', title_hi = 'रेत से बना केक 🏖️', body_hi = 'पार्क में पानी और मिट्टी मिलाकर, खुद को कीचड़ से सानकर आपके लिए केक बनाया? सफ़ाई छोड़िए। यह बारीक मोटर स्किल्स और रचनात्मकता है।', title_id = 'Kue dari pasir 🏖️', body_id = 'Di taman ia mencampur air dan tanah, berlumuran lumpur, dan membuatkan kue untuk Anda? Lupakan kebersihan. Ini motorik halus dan kreativitas.', title_ja = '砂でつくるケーキ 🏖️', body_ja = '公園で水と土をまぜて、どろんこになってケーキをつくってくれた？汚れは気にしないで。これは手先の発達と創造力です。', title_ko = '모래로 만든 케이크 🏖️', body_ko = '공원에서 물과 흙을 섞어 온몸이 진흙투성이가 된 채 엄마에게 케이크를 만들어 줬나요? 청소는 잊으세요. 소근육과 창의력이 자라는 중이에요.', title_nl = 'Een taart van zand 🏖️', body_nl = 'Mengde hij in het park water en aarde, zat hij helemaal onder de modder en bakte hij een taart voor jou? Laat het schoonmaken even. Dit is fijne motoriek en creativiteit.', title_pl = 'Tort z piasku 🏖️', body_pl = 'W parku zmieszał wodę z ziemią, ubrudził się błotem od stóp do głów i zrobił ci tort? Odpuść czystość. To motoryka mała i kreatywność.', title_pt = 'Um bolo feito de areia 🏖️', body_pt = 'No parque misturou água e terra, ficou todo enlameado e fez-lhe um bolo? Esqueça a limpeza. Isto é motricidade fina e criatividade.', title_sv = 'En tårta bakad av sand 🏖️', body_sv = 'Blandade barnet vatten och jord i parken, blev lerigt från topp till tå och bakade en tårta åt dig? Strunta i renligheten. Det här är finmotorik och kreativitet.', title_vi = 'Chiếc bánh làm từ cát 🏖️', body_vi = 'Ở công viên, bé trộn nước với đất, lấm lem từ đầu đến chân để làm bánh cho mẹ? Kệ việc dọn dẹp đi. Đây là kỹ năng vận động tinh và sự sáng tạo đấy.', title_zh = '沙子做的蛋糕 🏖️', body_zh = '在公园里把水和土混在一起，弄得满身是泥，给你做了个蛋糕？别管干不干净了。这是精细动作和创造力的发展。' WHERE id = '87824b1c-6e01-4ebd-84b1-4bb784a464e0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La competición de no parpadear 👀', body_es = '¿No quiere dormir y te mira con los ojos muy abiertos a propósito? Jugad a «el primero que cierre los ojos pierde». Se le llenarán los ojos de lágrimas, se cansará de todos modos y en 2 minutos se le cerrarán solos. ¡Pruébalo y verás!', title_fr = 'Le concours de qui ne cligne pas des yeux 👀', body_fr = 'Il ne veut pas dormir et vous fixe exprès en écarquillant les yeux ? Jouez à « Le premier qui ferme les yeux a perdu ». Ses yeux vont piquer, il se fatiguera de toute façon et ils se fermeront tout seuls en 2 minutes. Essayez, vous verrez !', title_hi = 'पलक न झपकाने की होड़ 👀', body_hi = 'सोना नहीं चाहता और जानबूझकर आँखें फाड़कर आपको देख रहा है? ‘जो पहले आँख बंद करेगा, वह हारेगा’ वाला खेल खेलिए। आँखों में पानी आकर वह वैसे भी थक जाएगा और 2 मिनट में आँखें अपने आप बंद हो जाएँगी। आज़माकर देखिए!', title_id = 'Lomba tidak berkedip 👀', body_id = 'Ia tidak mau tidur dan sengaja membelalakkan mata menatap Anda? Mainkan ''Siapa yang memejamkan mata duluan, dia kalah''. Matanya akan berair dan lelah, lalu dalam 2 menit otomatis terpejam. Coba dan lihat!', title_ja = 'にらめっこ競争 👀', body_ja = '寝たくなくて、わざと目を大きく開けてあなたを見る？「先に目をつぶったほうが負け」ゲームをしましょう。涙が出てきて疲れ、2分もすれば自然に目が閉じます。ためしてみて！', title_ko = '눈 깜빡이지 않기 시합 👀', body_ko = '자기 싫어서 일부러 눈을 크게 뜨고 엄마를 쳐다보나요? ''먼저 눈 감는 사람이 지는 거야'' 놀이를 해 보세요. 눈물이 고이며 지쳐서 2분이면 저절로 감길 거예요. 해 보세요!', title_nl = 'De niet-knipperwedstrijd 👀', body_nl = 'Wil hij niet slapen en kijkt hij je expres met grote ogen aan? Speel ''wie het eerst zijn ogen dichtdoet, verliest''. Zijn ogen gaan tranen, hij wordt toch moe en binnen 2 minuten vallen ze vanzelf dicht. Probeer het maar!', title_pl = 'Zawody w niemruganiu 👀', body_pl = 'Nie chce spać i specjalnie patrzy na ciebie szeroko otwartymi oczami? Zagraj w „kto pierwszy zamknie oczy, przegrywa”. Oczy i tak mu załzawią i się zmęczą, a za 2 minuty same się zamkną. Spróbuj i zobacz!', title_pt = 'A competição de não pestanejar 👀', body_pt = 'Não quer dormir e olha para si de olhos arregalados de propósito? Jogue a "quem fechar os olhos primeiro perde". Os olhos vão lacrimejar, ele vai cansar-se de qualquer forma e em 2 minutos fecham-se automaticamente. Experimente e veja!', title_sv = 'Tävlingen om att inte blinka 👀', body_sv = 'Vill barnet inte sova och stirrar på dig med uppspärrade ögon med flit? Lek leken ”Den som blundar först förlorar”. Ögonen tåras och blir trötta ändå och stängs automatiskt inom 2 minuter. Prova och se!', title_vi = 'Thi không chớp mắt 👀', body_vi = 'Bé không chịu ngủ và cố tình trợn mắt nhìn mẹ? Hãy chơi trò "Ai nhắm mắt trước là thua". Mắt bé sẽ cay và mỏi, 2 phút sau tự động khép lại. Thử xem!', title_zh = '不眨眼比赛 👀', body_zh = '不想睡觉，故意瞪大眼睛看着你？玩一个“谁先闭眼谁就输”的游戏。眼睛会流泪，宝宝本来就累了，2分钟后眼睛就会自动合上。试试看！' WHERE id = 'bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los juguetes escondidos en la cama 🧸', body_es = '¿Al meterse en la cama han salido de debajo 3 coches duros? Duerme protegiéndolos. Tranquila: 10 minutos después de que se duerma, sácalos a escondidas para que duerma cómodo.', title_fr = 'Les jouets cachés dans le lit 🧸', body_fr = 'Quand il s''est couché, 3 petites voitures dures sont sorties de sous lui ? Il dort en les protégeant. Pas d''inquiétude : 10 minutes après qu''il s''est endormi, vous retirerez en douce ces objets qui piquent pour qu''il dorme confortablement.', title_hi = 'बिस्तर में छिपे खिलौने 🧸', body_hi = 'बिस्तर में घुसते ही नीचे से 3 सख्त गाड़ियाँ निकलीं? वह उनकी रखवाली करते हुए सोता है। चिंता मत कीजिए, सोने के 10 मिनट बाद वे चुभने वाली चीज़ें चुपके से निकाल लीजिए, ताकि वह आराम से सो सके।', title_id = 'Mainan rahasia di tempat tidur 🧸', body_id = 'Saat masuk ke tempat tidur, dari bawahnya keluar 3 mobil-mobilan keras? Ia tidur sambil menjaganya. Jangan khawatir, 10 menit setelah ia tertidur, Anda bisa diam-diam mengambil benda-benda yang mengganjal itu supaya ia tidur nyaman.', title_ja = 'ベッドの中のひみつのおもちゃ 🧸', body_ja = 'ベッドに入ったら、下からかたい車が3台出てきた？守りながら眠っているんです。心配しないで。寝ついて10分たったら、ごつごつしたものをこっそり取り出して、ぐっすり眠れるようにしてあげましょう。', title_ko = '침대 속 숨은 장난감 🧸', body_ko = '침대에 들어가 보니 밑에서 딱딱한 자동차가 3대나 나왔나요? 지키면서 자는 거예요. 걱정 마세요, 잠든 지 10분 뒤에 배기는 물건을 몰래 빼내 편히 자게 해 주면 돼요.', title_nl = 'Verstopt speelgoed in bed 🧸', body_nl = 'Kwamen er, toen hij in bed kroop, 3 harde autootjes onder hem vandaan? Hij slaapt om ze te beschermen. Geen zorgen, 10 minuten nadat hij in slaap is gevallen, haal je die prikkende spullen stiekem weg, zodat hij lekker slaapt.', title_pl = 'Ukryte zabawki w łóżku 🧸', body_pl = 'Gdy kładzie się do łóżka, spod spodu wyjeżdżają 3 twarde autka? Śpi, pilnując ich. Nie martw się, 10 minut po zaśnięciu po cichu wyjmiesz te uwierające przedmioty i zapewnisz mu wygodny sen.', title_pt = 'Brinquedos escondidos na cama 🧸', body_pt = 'Quando se deitou, saíram debaixo dele 3 carrinhos duros? Dorme a protegê-los. Não se preocupe: 10 minutos depois de adormecer, tire de lá às escondidas esses objetos que picam e garanta que dorme confortável.', title_sv = 'Gömda leksaker i sängen 🧸', body_sv = 'Kom det fram 3 hårda bilar under barnet när hen kröp ner i sängen? Hen sover och skyddar dem. Oroa dig inte, 10 minuter efter att barnet somnat plockar du i smyg bort de obekväma sakerna så att hen sover gott.', title_vi = 'Đồ chơi giấu trên giường 🧸', body_vi = 'Lúc bé lên giường, mẹ thấy bên dưới có 3 chiếc xe đồ chơi cứng? Bé ngủ để bảo vệ chúng. Đừng lo, 10 phút sau khi bé ngủ, mẹ hãy lặng lẽ lấy những món cấn người ấy ra để bé ngủ ngon.', title_zh = '床上藏着的玩具 🧸', body_zh = '宝宝上床时，从下面掏出了3辆硬邦邦的小汽车？宝宝是在守护着它们睡觉。别担心，等宝宝睡着10分钟后，你再悄悄把那些硌人的东西拿出来，让宝宝睡得舒服些。' WHERE id = '20b06f39-a2df-4c97-aab5-39753c3a8a8f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Consuelo secreto en la Comunidad 💬', body_es = '¿Estás tan cansada que no te apetece ni desahogarte con nadie? Entra en la Comunidad Anacan y limítate a leer. Ver cómo otras mamás lidian con las mismas crisis absurdas será tu consuelo silencioso más poderoso.', title_fr = 'Un réconfort discret dans la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez même pas envie de parler à quelqu''un ? Rejoignez la Communauté Anacan et contentez-vous de lire. Voir comment les autres mamans affrontent les mêmes crises absurdes sera le plus puissant des réconforts silencieux.', title_hi = 'कम्युनिटी में चुपचाप मिलने वाली तसल्ली 💬', body_hi = 'बहुत थक गई हैं और किसी से बात करने का भी मन नहीं? Anacan कम्युनिटी में आइए और बस पढ़िए। दूसरी माँएँ उन्हीं बेतुके संकटों से कैसे जूझती हैं, यह देखना आपके लिए सबसे बड़ी खामोश तसल्ली होगी।', title_id = 'Penghiburan diam-diam di komunitas 💬', body_id = 'Anda sangat lelah dan bahkan tidak ingin curhat dengan siapa pun? Masuk ke Komunitas Anacan dan cukup jadi pembaca. Melihat ibu-ibu lain berjuang menghadapi krisis absurd yang sama akan menjadi penghiburan diam-diam yang paling kuat bagi Anda.', title_ja = 'コミュニティでこっそりなぐさめ 💬', body_ja = '疲れきって、誰かと話す気にもなれない？Anacanコミュニティに入って、読むだけにしましょう。ほかのママたちが同じおかしなかんしゃくとどう向き合っているかを見るのが、いちばん力強い静かななぐさめになります。', title_ko = '커뮤니티 속 조용한 위로 💬', body_ko = '너무 지쳐서 누구와 이야기하기조차 싫은가요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들이 똑같이 엉뚱한 위기와 씨름하는 걸 보는 게 가장 강력한 조용한 위로가 될 거예요.', title_nl = 'Stille troost in de Community 💬', body_nl = 'Ben je zo moe dat je zelfs met niemand wilt praten? Ga naar de Anacan Community en lees alleen mee. Zien hoe andere mama''s met precies dezelfde absurde crisissen worstelen, is de sterkste stille troost.', title_pl = 'Ciche pocieszenie w Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie masz ochoty nawet z nikim rozmawiać? Wejdź do Społeczności Anacan i tylko czytaj. Widok tego, jak inne mamy radzą sobie z tymi samymi absurdalnymi kryzysami, będzie dla ciebie najsilniejszym cichym pocieszeniem.', title_pt = 'Um consolo secreto na comunidade 💬', body_pt = 'Está tão cansada que nem lhe apetece desabafar com ninguém? Entre na Comunidade Anacan e seja apenas leitora. Ver como as outras mães lidam com as mesmas crises absurdas será o consolo silencioso mais forte.', title_sv = 'Hemlig tröst i Community 💬', body_sv = 'Är du så trött att du inte ens vill prata av dig med någon? Gå in i Anacan Community och bara läs. Att se hur andra mammor hanterar samma absurda kriser blir den starkaste tysta trösten.', title_vi = 'Niềm an ủi thầm lặng trong cộng đồng 💬', body_vi = 'Mẹ mệt đến mức không muốn tâm sự với ai? Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác đối phó với những cơn "khủng hoảng" phi lý y hệt, đó sẽ là niềm an ủi thầm lặng mạnh mẽ nhất cho mẹ.', title_zh = '在社区里悄悄获得安慰 💬', body_zh = '累到连和人说话都不想？进入Anacan社区，只当一名读者。看到其他妈妈怎样应对同样荒诞的危机，就是给你最有力的无声安慰。' WHERE id = '29e9913a-41eb-42ab-96c8-cc6c3af590fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de la cuchara equivocada 🥄', body_es = '¿Casi se arma una revolución porque le has dado la sopa con la cuchara grande? Cerca de los 4 años, aunque la comida sea la misma, el tamaño del objeto cambia en su lógica el sabor de la comida. No discutas, cambia la cuchara en un segundo y guarda tu energía.', title_fr = 'La crise de la mauvaise cuillère 🥄', body_fr = 'Vous avez servi la soupe avec une grande cuillère et la révolution a failli éclater ? Vers 4 ans, même si la nourriture est la même, la taille de l''objet en change le goût dans sa logique. Ne discutez pas, changez de cuillère en une seconde et préservez votre énergie.', title_hi = 'गलत चम्मच का संकट 🥄', body_hi = 'सूप बड़े चम्मच से दिया, तो लगभग क्रांति हो गई? 4 साल के आसपास, खाना वही हो तब भी, चीज़ का आकार उसके तर्क में खाने का स्वाद बदल देता है। बहस मत कीजिए, फ़ौरन चम्मच बदलिए और अपनी ऊर्जा बचाइए।', title_id = 'Krisis sendok yang salah 🥄', body_id = 'Hampir terjadi revolusi karena Anda memberinya sup dengan sendok besar? Menjelang usia 4 tahun, meski makanannya sama, ukuran fisik benda dalam logikanya mengubah rasa makanan. Jangan berdebat, segera ganti sendoknya dan hemat energi Anda.', title_ja = 'スプーンがちがう危機 🥄', body_ja = '大きなスプーンでスープを出したら、革命が起きそうに？4歳近くになると、中身が同じでも道具の大きさで、この子の中では味が変わるんです。言い合いはせず、すぐにスプーンを替えてエネルギーを守りましょう。', title_ko = '잘못된 숟가락 위기 🥄', body_ko = '수프를 큰 숟가락으로 줬다고 난리가 날 뻔했나요? 4세 무렵에는 음식이 같아도 도구의 크기가 아이의 논리 속에서 맛을 바꿔요. 다투지 말고 바로 숟가락을 바꿔 에너지를 아끼세요.', title_nl = 'De crisis van de verkeerde lepel 🥄', body_nl = 'Brak er bijna een revolutie uit omdat je de soep met een grote lepel gaf? Rond de 4 jaar is het eten hetzelfde, maar in zijn logica verandert de grootte van het bestek de smaak. Ga niet in discussie, verwissel meteen de lepel en spaar je energie.', title_pl = 'Kryzys złej łyżki 🥄', body_pl = 'Prawie wybuchła rewolucja, bo podałaś zupę dużą łyżką? U prawie 4-latka, choć jedzenie jest to samo, fizyczny rozmiar przedmiotu w jego logice zmienia smak potrawy. Nie kłóć się, w sekundę zmień łyżkę i oszczędzaj energię.', title_pt = 'A crise da colher errada 🥄', body_pt = 'Quase rebentou uma revolução porque lhe deu a sopa com a colher grande? Perto dos 4 anos, mesmo que a comida seja igual, o tamanho do objeto muda o sabor na lógica dele. Não discuta: troque a colher num segundo e poupe energia.', title_sv = 'Krisen med fel sked 🥄', body_sv = 'Blev det nästan revolution för att du serverade soppan med en stor sked? Nära 4 år kan maten vara densamma, men i barnets logik ändrar föremålets storlek smaken. Bråka inte, byt sked på en sekund och spara energin.', title_vi = 'Khủng hoảng chiếc thìa sai 🥄', body_vi = 'Suýt nữa nổ ra "cách mạng" chỉ vì mẹ đưa súp bằng thìa to? Gần 4 tuổi, dù món ăn vẫn vậy, kích thước của đồ vật lại làm thay đổi hương vị trong logic của bé. Đừng tranh cãi, đổi thìa ngay và giữ sức nhé.', title_zh = '用错勺子的危机 🥄', body_zh = '因为用大勺子喂汤，差点闹起了革命？快4岁的孩子，就算食物一样，餐具的大小在宝宝的逻辑里也会改变食物的味道。别争了，马上换勺子，保存精力。' WHERE id = 'bab27593-bee1-487c-a8d8-1d9f5c333dc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dejarse caer en el sofá en silencio 🥂', body_es = 'El peque duerme y la casa está recogida. Siéntate en el sofá junto a tu pareja, sin encender siquiera la tele. Solo miraos con esa mirada de «esto también lo hemos conseguido, hemos sobrevivido». Créeme, este es el momento más romántico y auténtico de ser padres.', title_fr = 'S''effondrer en silence sur le canapé 🥂', body_fr = 'L''enfant dort, la maison est rangée. Asseyez-vous côte à côte sur le canapé avec votre partenaire, sans même allumer la télé. Échangez simplement ce regard qui dit « On y est arrivés, on a survécu ». Croyez-moi, voilà le moment le plus romantique et le plus vrai de la vie de parents.', title_hi = 'चुपचाप सोफ़े पर ढह जाना 🥂', body_hi = 'बच्चा सो गया, घर समेट लिया। अपने साथी के साथ सोफ़े पर पास-पास बैठिए, टीवी भी मत चलाइए। बस एक-दूसरे को ‘यह भी कर लिया, हम बच गए’ वाली नज़र से देखिए। यकीन मानिए, पेरेंटिंग का सबसे रोमांटिक और सच्चा पल यही है।', title_id = 'Menjatuhkan diri ke sofa dalam diam 🥂', body_id = 'Anak sudah tidur, rumah sudah rapi. Duduklah berdampingan dengan pasangan di sofa, bahkan tanpa menyalakan TV. Cukup saling bertukar tatapan ''kita berhasil melewati ini juga''. Percayalah, inilah momen paling romantis dan nyata dalam menjadi orang tua.', title_ja = '静かにソファにしずむ 🥂', body_ja = '子どもは寝て、家も片づいた。パートナーとソファに並んで座り、テレビもつけないで。ただ「今日も乗りきったね」という視線を交わしましょう。それこそが、子育てのいちばんロマンチックで本当の瞬間です。', title_ko = '말없이 소파에 털썩 🥂', body_ko = '아이는 잠들고 집도 정리됐어요. 배우자와 소파에 나란히 앉아 TV도 켜지 마세요. 그저 ''오늘도 해냈다, 살아남았다''는 눈빛을 서로 나누세요. 이게 바로 육아에서 가장 로맨틱하고 진짜인 순간이에요.', title_nl = 'Stil op de bank ploffen 🥂', body_nl = 'Je kind slaapt, het huis is opgeruimd. Ga met je partner naast elkaar op de bank zitten, zet zelfs de tv niet aan. Geef elkaar gewoon die blik van ''we hebben het weer gered, we hebben het overleefd''. Geloof ons, dit is het meest romantische en echte moment van het ouderschap.', title_pl = 'Opaść w ciszy na kanapę 🥂', body_pl = 'Dziecko śpi, dom posprzątany. Usiądź z partnerem obok siebie na kanapie, nawet nie włączajcie telewizora. Po prostu wymieńcie spojrzenia mówiące „i to nam się udało, przetrwaliśmy”. Uwierz, to właśnie najbardziej romantyczna i prawdziwa chwila rodzicielstwa.', title_pt = 'Cair no sofá em silêncio 🥂', body_pt = 'A criança adormeceu, a casa está arrumada. Sente-se no sofá ao lado do seu companheiro, nem sequer ligue a televisão. Troquem apenas aquele olhar de "também conseguimos isto, sobrevivemos". Acredite, é este o momento mais romântico e verdadeiro da parentalidade.', title_sv = 'Att tyst sjunka ner i soffan 🥂', body_sv = 'Barnet sover, huset är städat. Sätt dig bredvid din partner i soffan och slå inte ens på tv:n. Ge bara varandra blicken som säger ”vi klarade det här också, vi överlevde”. Tro mig, det är föräldraskapets mest romantiska och äkta stund.', title_vi = 'Lặng lẽ ngả lưng trên sofa 🥂', body_vi = 'Bé đã ngủ, nhà đã dọn. Hãy ngồi cạnh chồng trên sofa, thậm chí đừng bật TV. Chỉ cần trao nhau ánh mắt "Chúng ta lại làm được rồi, lại sống sót rồi". Tin đi, đó chính là khoảnh khắc lãng mạn và chân thật nhất của việc làm cha mẹ.', title_zh = '静静地瘫在沙发上 🥂', body_zh = '宝宝睡了，家也收拾好了。和另一半并肩坐在沙发上，连电视都别开。只要彼此对视一眼：“这一关我们也挺过来了。”相信我，这才是为人父母最浪漫、最真实的时刻。' WHERE id = '6072f87e-09eb-4773-9647-75d90ac37029' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por el color verde 🥦', body_es = '¿Solo busca cosas verdes en el plato y aparta los demás colores? Mira Recetas saludables y aprende a hacer bolitas verdes de verdura y hierbas con formas divertidas.', title_fr = 'L''amour du vert 🥦', body_fr = 'Il ne cherche que des choses vertes dans son assiette et repousse les autres couleurs ? Consultez les Recettes saines et apprenez à faire avec des herbes de jolies boulettes de légumes verts.', title_hi = 'हरे रंग से प्यार 🥦', body_hi = 'प्लेट में सिर्फ़ हरी चीज़ें ढूँढता है और बाकी रंग दूर धकेल देता है? सेहतमंद रेसिपी देखिए, सीखिए कि हरी पत्तेदार सब्ज़ियों से प्यारे आकार की हरी सब्ज़ी की गोलियाँ कैसे बनाएँ।', title_id = 'Cinta warna hijau 🥦', body_id = 'Ia hanya mencari yang hijau di piringnya dan menyingkirkan warna lain? Lihat Resep Sehat, pelajari cara membuat bola-bola sayur hijau berbentuk lucu dari sayuran daun.', title_ja = '緑色が大好き 🥦', body_ja = 'お皿の中で緑のものだけを探して、ほかの色は押しのける？「ヘルシーレシピ」を見て、青菜からかわいい形の緑の野菜ボールをつくる方法を見つけましょう。', title_ko = '초록색 사랑 🥦', body_ko = '접시에서 초록색 음식만 찾고 다른 색은 밀어내나요? 건강한 레시피에서 채소로 귀여운 모양의 초록 채소볼을 만드는 법을 배워 보세요.', title_nl = 'Liefde voor groen 🥦', body_nl = 'Zoekt hij op zijn bord alleen naar groene dingen en duwt hij andere kleuren weg? Kijk in Gezonde recepten en leer hoe je van groene kruiden schattige groene groentebolletjes maakt.', title_pl = 'Miłość do zielonego koloru 🥦', body_pl = 'Szuka na talerzu tylko zielonych rzeczy, a inne kolory odsuwa? Zajrzyj do Zdrowych przepisów i dowiedz się, jak zrobić z zieleniny urocze zielone kulki warzywne.', title_pt = 'O amor pela cor verde 🥦', body_pt = 'No prato só procura coisas verdes e afasta as outras cores? Veja as Receitas Saudáveis e aprenda a fazer com as ervas aromáticas bolinhas verdes de legumes com formas giras.', title_sv = 'Kärleken till grön färg 🥦', body_sv = 'Letar barnet bara efter gröna saker på tallriken och knuffar bort andra färger? Titta i Hälsosamma recept och lär dig att göra söta, gröna grönsaksbollar av örter.', title_vi = 'Tình yêu với màu xanh lá 🥦', body_vi = 'Bé chỉ tìm đồ màu xanh lá trong đĩa và đẩy các màu khác ra? Hãy xem Công thức lành mạnh để học cách làm những viên rau xanh hình thù đáng yêu từ các loại rau thơm.', title_zh = '爱上绿色 🥦', body_zh = '盘子里只找绿色的东西，把其他颜色推到一边？看看健康食谱，学学怎样用绿叶菜做出形状可爱的绿色蔬菜丸子。' WHERE id = 'a980ec72-f146-48fe-a3b4-28ba8f8a9398' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué has cerrado tú la puerta? 🚪', body_es = '¿Al salir de casa ha llorado a gritos porque cerraste tú la puerta y te ha hecho volver a abrirla? La sensación de control es su mayor necesidad. Pierde 1 minuto, pero evita una crisis de llanto de 30 minutos en la calle.', title_fr = 'Pourquoi c''est toi qui as fermé la porte ? 🚪', body_fr = 'En sortant, il a hurlé parce que c''est vous qui avez fermé la porte, et vous l''a fait rouvrir ? Le sentiment de contrôle est son plus grand besoin. Laissez-le vous faire perdre 1 minute, mais évitez une crise de larmes de 30 minutes dans la rue.', title_hi = 'दरवाज़ा तुमने क्यों बंद किया? 🚪', body_hi = 'घर से निकलते समय दरवाज़ा आपने बंद किया, इसलिए चीख-पुकार मचाकर फिर से खुलवाया? नियंत्रण का एहसास उसकी सबसे बड़ी ज़रूरत है। इसमें आपका 1 मिनट जाएगा, पर बाहर होने वाले 30 मिनट के रोने-धोने से बच जाएँगी।', title_id = 'Kenapa Mama yang tutup pintunya? 🚪', body_id = 'Saat keluar rumah ia menjerit karena Anda yang menutup pintu, lalu menyuruh membukanya lagi? Rasa memegang kendali adalah kebutuhan terbesarnya. Biarlah Anda kehilangan 1 menit, tapi cegah krisis tangisan 30 menit di jalan.', title_ja = 'なんでママがドアを閉めたの？ 🚪', body_ja = '出かけるときにあなたがドアを閉めたら大泣きして、また開けさせた？自分でコントロールしたい気持ちが、いちばん大きな欲求です。1分かかってもいいから、外での30分の大泣きを防ぎましょう。', title_ko = '왜 엄마가 문 닫았어? 🚪', body_ko = '외출할 때 엄마가 문을 닫았다고 울부짖으며 다시 열게 했나요? 통제감은 아이의 가장 큰 욕구예요. 1분 손해 보더라도, 밖에서 30분짜리 울음 폭발을 막으세요.', title_nl = 'Waarom deed jij de deur dicht? 🚪', body_nl = 'Barstte hij in gejammer uit en moest je de deur weer opendoen omdat jij hem dichtdeed toen jullie weggingen? Een gevoel van controle is zijn grootste behoefte. Laat hem je die ene minuut kosten en voorkom een huilcrisis van 30 minuten op straat.', title_pl = 'Czemu ty zamknęłaś drzwi? 🚪', body_pl = 'Przy wyjściu z domu zaczął rozpaczać, bo to ty zamknęłaś drzwi, i kazał je znowu otworzyć? Poczucie kontroli to jego największa potrzeba. Stracisz 1 minutę, ale zapobiegniesz 30-minutowemu płaczliwemu kryzysowi na ulicy.', title_pt = 'Porque é que foste tu a fechar a porta? 🚪', body_pt = 'Ao sair de casa, fez um escândalo porque foi a mãe a fechar a porta e obrigou-a a abri-la outra vez? A sensação de controlo é a maior necessidade dele. Deixe-o fazê-la perder 1 minuto, mas evite uma crise de choro de 30 minutos na rua.', title_sv = 'Varför stängde du dörren? 🚪', body_sv = 'Skrek barnet för att du stängde dörren när ni gick hemifrån, och fick dig att öppna den igen? Känslan av kontroll är barnets största behov. Låt det kosta dig 1 minut, men förebygg en 30 minuters gråtkris på gatan.', title_vi = 'Sao mẹ lại đóng cửa? 🚪', body_vi = 'Lúc ra khỏi nhà, bé khóc ầm lên vì mẹ đã đóng cửa và bắt mở lại? Cảm giác kiểm soát là nhu cầu lớn nhất của bé. Hãy chịu mất 1 phút, để tránh 30 phút khóc lóc ngoài đường.', title_zh = '门为什么是你关的？🚪', body_zh = '出门时因为是你关的门，宝宝就大哭，非要重新打开？掌控感是宝宝最大的需求。让宝宝花掉你1分钟，却能避免街上30分钟的大哭。' WHERE id = 'e2f4da77-db67-4ed8-9acb-d0a907894c73' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quién es ese niño del espejo? 🪞', body_es = '¿Se pone delante del espejo y frunce el ceño, haciendo muecas de enfado y caras raras? Está descubriendo cómo se ven las emociones en su cara. Disfruta en silencio, desde fuera, del ensayo de este pequeño actor de teatro.', title_fr = 'Qui est cet enfant dans le miroir ? 🪞', body_fr = 'Debout devant le miroir, il fronce les sourcils et fait des grimaces fâchées et bizarres ? Il découvre à quoi ressemblent les émotions sur son visage. Sans faire de bruit, savourez de loin la répétition de ce petit acteur de théâtre.', title_hi = 'आईने वाला वह बच्चा कौन है? 🪞', body_hi = 'आईने के सामने खड़ा होकर खुद पर भौंहें चढ़ाता है, गुस्से वाले और अजीब चेहरे बनाता है? वह खोज रहा है कि भावनाएँ चेहरे पर कैसी दिखती हैं। किनारे से बिना आवाज़ किए इस नन्हे थिएटर कलाकार की रिहर्सल का मज़ा लीजिए।', title_id = 'Siapa anak di cermin itu? 🪞', body_id = 'Ia berdiri di depan cermin, mengernyitkan dahi, dan membuat ekspresi kesal dan aneh? Ia sedang menemukan bagaimana emosi terlihat di wajahnya. Saksikan dengan senang dan tanpa suara latihan aktor teater mini ini dari samping.', title_ja = '鏡の中のあの子は誰？ 🪞', body_ja = '鏡の前で、まゆをひそめたり、怒った顔やへんな顔をしたりしている？気持ちが顔にどう表れるかを発見しているんです。音を立てずに、この小さな役者さんのリハーサルを楽しく見守りましょう。', title_ko = '거울 속 저 아이는 누구야? 🪞', body_ko = '거울 앞에서 혼자 인상을 쓰고 화난 표정이나 이상한 표정을 짓나요? 감정이 얼굴에 어떻게 드러나는지 탐구하는 중이에요. 소리 내지 말고 이 꼬마 배우의 연습을 즐겁게 지켜보세요.', title_nl = 'Wie is dat kind in de spiegel? 🪞', body_nl = 'Staat hij voor de spiegel te fronsen en boze, rare gezichten te trekken? Hij ontdekt hoe emoties op zijn gezicht eruitzien. Kijk geruisloos en genietend toe bij de repetitie van deze minitheateracteur.', title_pl = 'Kim jest to dziecko w lustrze? 🪞', body_pl = 'Stoi przed lustrem, marszczy brwi i robi złe, dziwne miny? Odkrywa, jak emocje wyglądają na twarzy. Bezgłośnie, z boku, z przyjemnością obserwuj próbę tego miniaturowego aktora teatralnego.', title_pt = 'Quem é aquela criança no espelho? 🪞', body_pt = 'Põe-se em frente ao espelho a franzir a testa sozinho e a fazer caretas zangadas e estranhas? Está a descobrir como as emoções aparecem no rosto. Observe com prazer, à distância e sem fazer barulho, o ensaio deste pequeno ator de teatro.', title_sv = 'Vem är barnet i spegeln? 🪞', body_sv = 'Står barnet framför spegeln och rynkar pannan åt sig själv och gör arga, konstiga miner? Hen upptäcker hur känslor syns i ansiktet. Titta ljudlöst från sidan och njut av den lilla teaterskådespelarens repetition.', title_vi = 'Bạn nhỏ trong gương là ai? 🪞', body_vi = 'Bé đứng trước gương, cau mày, làm những nét mặt giận dữ và kỳ lạ? Bé đang khám phá cảm xúc hiện lên trên khuôn mặt ra sao. Hãy lặng lẽ, thích thú ngắm buổi tập của "diễn viên kịch" tí hon này từ xa.', title_zh = '镜子里的那个孩子是谁？🪞', body_zh = '站在镜子前，对着自己皱眉，做出生气又奇怪的表情？宝宝在探索情绪在脸上是什么样子。别出声，在一旁好好欣赏这位迷你戏剧演员的排练吧。' WHERE id = '2feec242-97b8-4207-9200-a80856e8121d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga las luces y busca la sombra 🔦', body_es = '¿Le da miedo la oscuridad y no se va a la cama? Apaga del todo las luces de la habitación y enciende una linternita. Haz con las manos sombras de perros y pájaros en la pared. Convierte la oscuridad que da miedo en un teatro y le costará menos dormirse.', title_fr = 'Éteignez la lumière, trouvez l''ombre 🔦', body_fr = 'Il a peur du noir et ne veut pas aller au lit ? Éteignez complètement la lumière de la chambre et allumez une petite lampe de poche. Créez avec vos mains des ombres de chien et d''oiseau sur le mur. Transformez ce noir effrayant en théâtre, et il s''endormira plus facilement.', title_hi = 'लाइटें बंद करो, परछाईं ढूँढो 🔦', body_hi = 'अंधेरे से डरता है और सोने नहीं जाता? कमरे की लाइटें पूरी बंद करके छोटी टॉर्च जलाइए। दीवार पर हाथों से कुत्ते, चिड़िया की परछाइयाँ बनाइए। डरावने अंधेरे को उसके लिए थिएटर बना दीजिए, नींद आना आसान हो जाएगा।', title_id = 'Matikan lampu, temukan bayangannya 🔦', body_id = 'Ia takut gelap dan tidak mau tidur? Matikan semua lampu kamar dan nyalakan senter kecil. Buat bayangan anjing dan burung dengan tangan Anda di dinding. Ubah gelap yang menakutkan menjadi teater baginya, tidurnya akan jadi lebih mudah.', title_ja = '明かりを消して、影を見つけよう 🔦', body_ja = '暗いのがこわくて寝たがらない？部屋の明かりを全部消して、小さな懐中電灯をつけましょう。壁に手で犬や鳥の影をつくって。こわい暗やみを劇場に変えれば、眠りにつきやすくなります。', title_ko = '불을 끄고 그림자를 찾아요 🔦', body_ko = '어둠이 무서워 잠자리에 들지 않나요? 방 불을 다 끄고 작은 손전등을 켜세요. 벽에 손으로 강아지와 새 그림자를 만들어 무서운 어둠을 극장으로 바꿔 주세요. 훨씬 쉽게 잠들 거예요.', title_nl = 'Licht uit, zoek de schaduw 🔦', body_nl = 'Is hij bang in het donker en wil hij niet naar bed? Doe al het licht in de kamer uit en zet een klein zaklampje aan. Maak met je handen schaduwen van hondjes en vogels op de muur. Verander het enge donker in een theater, dan valt hij makkelijker in slaap.', title_pl = 'Zgaś światło, znajdź cień 🔦', body_pl = 'Boi się ciemności i nie chce iść do łóżka? Zgaś całkiem światło w pokoju i zapal małą latarkę. Rękami twórz na ścianie cienie pieska i ptaszka. Zamień straszną ciemność w teatr, a łatwiej zaśnie.', title_pt = 'Apague as luzes e encontre a sombra 🔦', body_pt = 'Tem medo do escuro e não quer ir para a cama? Apague todas as luzes do quarto e acenda uma pequena lanterna. Faça com as mãos sombras de cães e pássaros na parede. Transforme o escuro assustador num teatro e adormecer vai ficar mais fácil.', title_sv = 'Släck lamporna, hitta skuggan 🔦', body_sv = 'Är barnet rädd för mörkret och vill inte gå och lägga sig? Släck alla lampor i rummet och tänd en liten ficklampa. Gör skuggor av hundar och fåglar med händerna på väggen. Förvandla det läskiga mörkret till en teater, så blir det lättare att somna.', title_vi = 'Tắt đèn, đi tìm cái bóng 🔦', body_vi = 'Bé sợ bóng tối và không chịu đi ngủ? Hãy tắt hết đèn trong phòng và bật một chiếc đèn pin nhỏ. Dùng tay tạo bóng chó, bóng chim trên tường. Biến bóng tối đáng sợ thành nhà hát cho bé, việc đi ngủ sẽ dễ dàng hơn.', title_zh = '关上灯，找影子 🔦', body_zh = '怕黑，不肯上床？把房间的灯全关掉，打开一支小手电筒。用手在墙上做出小狗、小鸟的影子。把可怕的黑暗变成宝宝的剧场，入睡就会容易多了。' WHERE id = '70b38ef9-bf37-4439-be26-d9a4e96ca1a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una obra maestra en la pared 🖍️', body_es = '¿Tras unos segundos de silencio lo has pillado pintando una obra de arte en la pared con rotuladores? Respira hondo. Su motricidad fina se está desarrollando y la pared se limpia igualmente. Antes de borrar esta obra maestra, hazle una foto sin falta.', title_fr = 'Un chef-d''œuvre sur le mur 🖍️', body_fr = 'Après quelques secondes de silence, vous l''avez trouvé en train de dessiner une œuvre d''art au feutre sur le mur ? Respirez profondément. Sa motricité fine se développe, et le mur, ça se nettoie. Avant d''effacer ce chef-d''œuvre, prenez-le absolument en photo.', title_hi = 'दीवार पर बनी उत्कृष्ट कलाकृति 🖍️', body_hi = 'कुछ सेकंड की खामोशी के बाद उसे दीवार पर मार्कर से कलाकृति बनाते पाया? गहरी साँस लीजिए। उसकी बारीक मोटर स्किल्स बढ़ रही हैं, और दीवार तो वैसे भी साफ़ हो जाती है। मिटाने से पहले इस कलाकृति की फ़ोटो ज़रूर ले लीजिए।', title_id = 'Mahakarya di dinding 🖍️', body_id = 'Setelah beberapa detik hening, Anda menemukannya sedang menggambar karya seni di dinding dengan spidol? Tarik napas dalam. Motorik halusnya berkembang, dan dinding toh bisa dibersihkan. Sebelum menghapusnya, jangan lupa memotret mahakarya ini.', title_ja = '壁にかかれた傑作 🖍️', body_ja = '数秒の静けさのあと、壁にペンでアート作品をかいている姿を発見？深呼吸して。手先が発達していますし、壁はどうせ拭けます。消す前に、この傑作をぜひ写真に撮っておきましょう。', title_ko = '벽에 그린 걸작 🖍️', body_ko = '몇 초간 조용하다 싶더니 벽에 사인펜으로 작품을 그리고 있었나요? 깊게 숨 쉬세요. 소근육이 자라는 중이고, 벽은 어차피 닦여요. 지우기 전에 이 걸작은 꼭 사진으로 남겨 두세요.', title_nl = 'Een meesterwerk op de muur 🖍️', body_nl = 'Vond je hem na een paar seconden stilte terwijl hij met stift een kunstwerk op de muur tekende? Haal diep adem. Zijn fijne motoriek ontwikkelt zich, en de muur is toch afwasbaar. Maak wel eerst een foto van dit meesterwerk voordat je het wegveegt.', title_pl = 'Arcydzieło na ścianie 🖍️', body_pl = 'Po kilku sekundach ciszy znalazłaś go, jak flamastrem maluje na ścianie dzieło sztuki? Weź głęboki oddech. Rozwija się jego motoryka mała, a ścianę i tak da się umyć. Zanim zmyjesz to arcydzieło, koniecznie zrób mu zdjęcie.', title_pt = 'Uma obra-prima na parede 🖍️', body_pt = 'Depois de uns segundos de silêncio, encontrou-o a desenhar uma obra de arte na parede com marcadores? Respire fundo. A motricidade fina está a desenvolver-se, e a parede limpa-se de qualquer forma. Antes de apagar esta obra-prima, não deixe de lhe tirar uma fotografia.', title_sv = 'Ett mästerverk på väggen 🖍️', body_sv = 'Efter några sekunders tystnad hittade du barnet i full färd med att rita ett konstverk på väggen med tusch? Andas djupt. Finmotoriken utvecklas, och väggen går ändå att tvätta. Fotografera absolut mästerverket innan du torkar bort det.', title_vi = 'Kiệt tác trên tường 🖍️', body_vi = 'Sau vài giây im lặng, mẹ thấy bé đang vẽ "tác phẩm nghệ thuật" lên tường bằng bút dạ? Hít thở thật sâu. Kỹ năng vận động tinh của bé đang phát triển, còn tường thì đằng nào cũng lau được. Trước khi lau, nhớ chụp lại kiệt tác này nhé.', title_zh = '墙上的杰作 🖍️', body_zh = '安静了几秒钟后，你发现宝宝正用水彩笔在墙上创作艺术？深呼吸。宝宝的精细动作在发展，墙反正也能擦干净。擦掉之前，一定要先给这幅杰作拍张照。' WHERE id = 'd5008830-7d32-4abc-8ae0-128b13041be3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'A caballito sobre papá 🐴', body_es = '¿No ha soltado toda su energía y se resiste a ir a la cama? Pide ayuda a papá. Cuando se lo suba a la espalda y galope como un caballo, las carcajadas llenarán la habitación y el estrés físico acumulado se irá en segundos entre sudores.', title_fr = 'À dada sur le dos de papa 🐴', body_fr = 'Il n''a pas pu se dépenser complètement et résiste au coucher ? Appelez papa à la rescousse. Quand il prend l''enfant sur son dos et galope comme un cheval, les éclats de rire remplissent la pièce et le stress physique accumulé s''évapore en quelques secondes, en sueur.', title_hi = 'पापा की पीठ पर घुड़सवारी 🐴', body_hi = 'अपनी ऊर्जा पूरी तरह निकाल नहीं पाया और सोने से अड़ा है? पापा को मदद के लिए बुलाइए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनकर दौड़ेंगे, कमरा ठहाकों से भर जाएगा और जमा शारीरिक तनाव पसीने के साथ सेकंडों में गायब हो जाएगा।', title_id = 'Naik kuda di punggung Ayah 🐴', body_id = 'Ia belum sepenuhnya menyalurkan energinya dan menolak tidur? Panggil Ayah untuk membantu. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, tawa memenuhi kamar dan stres fisik yang menumpuk lenyap dalam hitungan detik bersama keringat.', title_ja = 'パパの肩でおうまさん 🐴', body_ja = 'エネルギーを出しきれず、寝たがらない？パパに助けを呼びましょう。パパが子どもを背中に乗せてお馬さんをすれば、笑い声が部屋じゅうに広がり、たまった体のストレスは汗と一緒に数秒で消えていきます。', title_ko = '아빠 목마 타기 🐴', body_ko = '에너지를 다 쓰지 못해 잠자리에서 버티나요? 아빠에게 도움을 청하세요. 아빠가 아이를 등에 태우고 말처럼 달리면 웃음이 방을 가득 채우고, 쌓인 몸의 긴장이 땀과 함께 금세 사라질 거예요.', title_nl = 'Paardjerijden op papa''s nek 🐴', body_nl = 'Is hij zijn energie nog niet kwijt en verzet hij zich tegen bedtijd? Roep papa te hulp. Als die hem op zijn rug neemt en paardje speelt, vult gelach de kamer en verdwijnt alle opgebouwde lichamelijke spanning in een paar seconden in het zweet.', title_pl = 'Jazda konna na plecach taty 🐴', body_pl = 'Nie wyładował do końca energii i upiera się, że nie pójdzie do łóżka? Zawołaj tatę na pomoc. Gdy weźmie dziecko na plecy i zacznie galopować jak koń, śmiech wypełni pokój, a nagromadzone napięcie w kilka sekund wyparuje razem z potem.', title_pt = 'Cavalinho às costas do pai 🐴', body_pt = 'Não conseguiu gastar toda a energia e resiste a ir para a cama? Chame o pai para ajudar. Quando ele o põe às costas e faz de cavalo a galope, as gargalhadas enchem o quarto e o stress físico acumulado desaparece em segundos, a suar.', title_sv = 'Rida på pappas axlar 🐴', body_sv = 'Har barnet inte fått ut all energi och vägrar gå och lägga sig? Kalla på pappa. När han tar barnet på ryggen och leker häst fylls rummet av skratt, och den uppbyggda fysiska stressen svettas bort på några sekunder.', title_vi = 'Cưỡi ngựa trên lưng bố 🐴', body_vi = 'Bé chưa xả hết năng lượng và nhất quyết không lên giường? Hãy gọi bố giúp. Khi bố cõng bé trên lưng phi ngựa, tiếng cười sẽ vang khắp phòng và căng thẳng thể chất tích tụ sẽ tan biến theo mồ hôi chỉ trong vài giây.', title_zh = '骑在爸爸脖子上 🐴', body_zh = '精力还没用完，赖着不肯上床？请爸爸来帮忙。爸爸把宝宝背在背上“骑大马”时，笑声充满房间，积攒的身体压力几秒钟内就随着汗水消失了。' WHERE id = '56af6282-7207-49e4-b888-b735c8e4f791' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada de 5 minutos al baño 🚪', body_es = '¿El ruido te taladra la cabeza y te dan ganas de gritar por todo? Déjalo en un lugar seguro, entra en el baño y cierra la puerta. Mira la pared solo 5 minutos, no hagas nada. Este breve silencio te devolverá a ser una persona normal.', title_fr = '5 minutes d''évasion aux toilettes 🚪', body_fr = 'Le bruit vous transperce le cerveau et vous avez envie de crier contre tout ? Mettez-le en lieu sûr, entrez aux toilettes et fermez la porte. Regardez simplement le mur pendant 5 minutes, ne faites rien. Ce court silence fera de vous à nouveau une personne normale.', title_hi = 'बाथरूम में 5 मिनट की छुट्टी 🚪', body_hi = 'शोर दिमाग में छेद कर रहा है, हर बात पर चिल्लाने का मन है? उसे किसी सुरक्षित जगह छोड़कर बाथरूम में जाइए और दरवाज़ा बंद कर लीजिए। बस 5 मिनट दीवार को देखिए, कुछ मत कीजिए। यह छोटी सी खामोशी आपको फिर से सामान्य इंसान बना देगी।', title_id = 'Kabur 5 menit ke kamar mandi 🚪', body_id = 'Kebisingan menembus otak Anda dan Anda ingin meneriaki segalanya? Tinggalkan ia di tempat yang aman, masuk ke kamar mandi, dan tutup pintunya. Cukup pandangi dinding selama 5 menit, jangan lakukan apa pun. Keheningan singkat ini akan membuat Anda kembali jadi manusia normal.', title_ja = 'トイレに5分避難 🚪', body_ja = '騒音が頭につきささって、何にでも叫びたくなる？子どもを安全な場所に置いて、トイレに入ってドアを閉めましょう。ただ5分間壁を見て、何もしないで。この短い静けさが、あなたをまた普段の自分に戻してくれます。', title_ko = '화장실로 5분 도피 🚪', body_ko = '소음이 머리를 뚫을 것 같고 모든 일에 소리치고 싶나요? 아이를 안전한 곳에 두고 화장실에 들어가 문을 닫으세요. 5분만 벽을 바라보며 아무것도 하지 마세요. 이 짧은 고요가 다시 평범한 나로 돌려놓을 거예요.', title_nl = '5 minuten vluchten naar de wc 🚪', body_nl = 'Boort het lawaai door je hoofd en wil je om alles schreeuwen? Zet hem op een veilige plek, ga naar de wc en doe de deur dicht. Staar gewoon 5 minuten naar de muur en doe niets. Deze korte stilte maakt weer een normaal mens van je.', title_pl = '5-minutowa ucieczka do toalety 🚪', body_pl = 'Hałas świdruje ci mózg i masz ochotę na wszystko krzyczeć? Zostaw go w bezpiecznym miejscu, wejdź do toalety i zamknij drzwi. Przez 5 minut po prostu patrz w ścianę, nic nie rób. Ta krótka cisza znów zrobi z ciebie normalnego człowieka.', title_pt = 'Fuga de 5 minutos para a casa de banho 🚪', body_pt = 'O barulho fura-lhe o cérebro e apetece-lhe gritar com tudo? Deixe-o num sítio seguro, entre na casa de banho e feche a porta. Fique só 5 minutos a olhar para a parede, sem fazer nada. Este curto silêncio vai fazê-la voltar a ser uma pessoa normal.', title_sv = 'En 5-minutersflykt till toaletten 🚪', body_sv = 'Borrar sig oljudet in i hjärnan och du vill skrika åt allt? Lägg barnet på ett säkert ställe, gå in på toaletten och stäng dörren. Titta bara på väggen i 5 minuter, gör ingenting. Den korta tystnaden gör dig till en normal människa igen.', title_vi = '5 phút trốn vào nhà vệ sinh 🚪', body_vi = 'Tiếng ồn khoan vào đầu, mẹ muốn quát lên với mọi thứ? Hãy để bé ở nơi an toàn, vào nhà vệ sinh và đóng cửa lại. Chỉ cần nhìn vào tường 5 phút, không làm gì cả. Chút yên lặng ngắn ngủi này sẽ đưa mẹ trở lại là một người bình thường.', title_zh = '躲进卫生间5分钟 🚪', body_zh = '吵闹声快把你的脑袋钻穿了，看什么都想吼？把宝宝放在安全的地方，走进卫生间关上门。只是看着墙5分钟，什么都不做。这短短的安静会让你重新变回正常人。' WHERE id = '65ce993d-a029-4b05-8c87-ec0d7b807a64' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las gachas son demasiado redondas 🥣', body_es = '¿Se enfada por la forma de la comida y se niega a comer? Sin buscar lógica, remueve las gachas con la cuchara y dile «Mira, ya lo he arreglado». El arte de la ilusión siempre te hará falta como mamá.', title_fr = 'La bouillie est trop ronde 🥣', body_fr = 'Il est fâché contre la forme de son repas et refuse de manger ? Sans chercher de logique, mélangez simplement la bouillie avec la cuillère et dites « Regarde, je l''ai arrangée ». L''art de l''illusion vous servira toujours dans la maternité.', title_hi = 'दलिया बहुत गोल है 🥣', body_hi = 'खाने के आकार पर गुस्सा होकर खाने से मना करता है? तर्क ढूँढे बिना चम्मच से दलिया बस थोड़ा मिला दीजिए और कहिए, ‘देखो, ठीक कर दिया।’ भ्रम की यह कला माँ बनने में आपको हमेशा काम आएगी।', title_id = 'Buburnya terlalu bulat 🥣', body_id = 'Ia marah pada bentuk makanannya dan menolak makan? Tanpa mencari logika, cukup aduk buburnya dengan sendok dan katakan ''Lihat, sudah Mama perbaiki''. Seni ilusi akan selalu Anda butuhkan sebagai ibu.', title_ja = 'おかゆがまるすぎる 🥣', body_ja = '食べものの形に怒って、食べようとしない？理屈を探さずに、スプーンでおかゆをちょっとまぜて「ほら、直したよ」と言いましょう。イリュージョンの技は、子育てでいつも役に立ちます。', title_ko = '죽이 너무 동그래 🥣', body_ko = '음식 모양에 화가 나서 안 먹겠다고 하나요? 논리를 찾지 말고 숟가락으로 죽을 그냥 한번 저은 뒤 ''봐, 고쳐 놨어'' 하고 말해 주세요. 착시의 기술은 육아에 언제나 필요해요.', title_nl = 'De pap is te rond 🥣', body_nl = 'Wordt hij boos om de vorm van zijn eten en weigert hij te eten? Zoek geen logica, roer gewoon met de lepel door de pap en zeg: ''Kijk, ik heb het opgelost.'' De kunst van de illusie heb je als mama altijd nodig.', title_pl = 'Owsianka jest za okrągła 🥣', body_pl = 'Złości się na kształt jedzenia i nie chce jeść? Nie szukaj logiki, po prostu zamieszaj owsiankę łyżką i powiedz: „Zobacz, naprawiłam”. Sztuka iluzji zawsze przyda ci się w macierzyństwie.', title_pt = 'As papas estão demasiado redondas 🥣', body_pt = 'Zanga-se com a forma da comida e recusa-se a comer? Sem procurar lógica, mexa simplesmente as papas com a colher e diga "Olha, consertei". A arte da ilusão vai ser-lhe sempre útil na maternidade.', title_sv = 'Gröten är för rund 🥣', body_sv = 'Blir barnet argt på matens form och vägrar äta? Leta inte efter logik, rör bara om i gröten med skeden och säg ”Titta, jag har fixat det”. Illusionens konst kommer du alltid att behöva som mamma.', title_vi = 'Cháo tròn quá! 🥣', body_vi = 'Bé giận vì hình dạng của món ăn và không chịu ăn? Đừng tìm logic, chỉ cần lấy thìa khuấy cháo và nói "Nhìn này, mẹ sửa rồi". Nghệ thuật ảo thuật sẽ luôn cần thiết trong hành trình làm mẹ.', title_zh = '粥太圆了 🥣', body_zh = '因为食物的形状生气，不肯吃？别找逻辑，用勺子把粥搅一搅，说“看，我修好了”。当妈妈的路上，你永远用得上这门“障眼法”。' WHERE id = 'a5a3dc3f-2634-4d40-9509-dbe4066d8a5a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas sin lógica 😭', body_es = '¿Se ha armado una buena al volver del parque porque no ha podido darle una patada a una piedra? No hay lógica, solo está cansado. No discutas: cógelo en brazos, valida su emoción y lleva su atención a otra cosa.', title_fr = 'Des larmes sans logique 😭', body_fr = 'En rentrant du parc, c''est l''apocalypse parce qu''il n''a pas réussi à taper dans un caillou ? Il n''y a pas de logique, il est juste fatigué. Ne discutez pas, prenez-le dans vos bras, validez son émotion et détournez son attention.', title_hi = 'बेवजह के आँसू 😭', body_hi = 'पार्क से लौटते समय रास्ते में एक पत्थर को लात नहीं मार पाया, इसलिए हंगामा मच गया? कोई तर्क नहीं, वह बस थका हुआ है। बहस मत कीजिए, गोद में उठाइए, उसकी भावना को स्वीकार कीजिए और ध्यान कहीं और लगाइए।', title_id = 'Air mata tanpa logika 😭', body_id = 'Saat pulang dari taman, kiamat terjadi karena ia tidak berhasil menendang sebuah batu? Tak ada logikanya, ia hanya lelah. Jangan berdebat, gendong ia, akui perasaannya, lalu alihkan perhatiannya ke hal lain.', title_ja = '理屈のない涙 😭', body_ja = '公園からの帰り道、石をけれなかったから大さわぎ？理屈はなく、ただ疲れているんです。言い合いはせず、抱き上げて気持ちを受けとめ、ほかのことに気をそらしましょう。', title_ko = '이유 없는 눈물 😭', body_ko = '공원에서 돌아오는 길에 돌을 못 찼다고 난리가 났나요? 논리는 없어요, 그냥 피곤한 거예요. 다투지 말고 안아 올려 마음을 인정해 주고 관심을 다른 곳으로 돌리세요.', title_nl = 'Onlogische tranen 😭', body_nl = 'Breekt de hel los op weg terug uit het park omdat hij een steen niet kon wegschoppen? Er is geen logica, hij is gewoon moe. Ga niet in discussie, neem hem in je armen, erken zijn gevoel en leid zijn aandacht af.', title_pl = 'Łzy bez logiki 😭', body_pl = 'W drodze z parku wybuchła awantura, bo nie udało mu się kopnąć kamienia? Logiki tu nie ma, jest po prostu zmęczony. Nie kłóć się, weź go na ręce, uznaj jego uczucia i odwróć jego uwagę.', title_pt = 'Lágrimas sem lógica 😭', body_pt = 'No regresso do parque, caiu o Carmo e a Trindade porque não conseguiu dar um pontapé numa pedra no caminho? Não há lógica, está só cansado. Não discuta: pegue-lhe ao colo, valide o que sente e desvie a atenção dele para outra coisa.', title_sv = 'Tårar utan logik 😭', body_sv = 'Blev det världens undergång på vägen hem från parken för att barnet inte lyckades sparka på en sten? Det finns ingen logik, hen är bara trött. Bråka inte, ta barnet i famnen, bekräfta känslan och led uppmärksamheten någon annanstans.', title_vi = 'Những giọt nước mắt vô lý 😭', body_vi = 'Trên đường từ công viên về, cả thế giới như sụp đổ chỉ vì bé không đá được một hòn sỏi? Chẳng có logic nào, bé chỉ đang mệt. Đừng tranh cãi, hãy bế bé lên, công nhận cảm xúc của bé và chuyển sự chú ý sang thứ khác.', title_zh = '没有逻辑的眼泪 😭', body_zh = '从公园回家的路上，因为没踢到一块石头就闹翻天了？这里没有逻辑，只是累了。别争，把宝宝抱起来，认可宝宝的情绪，再把注意力引到别处。' WHERE id = '9272ca67-0e34-4d81-b7cc-a00d43d2c52b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los secretos del cuento en susurros 🤫', body_es = '¿Se inventa excusas para escaparse de la cama? Baja la voz del todo y empieza a hablar solo en susurros. Para entenderte tendrá que concentrarse físicamente y su cerebro se dormirá enseguida.', title_fr = 'Les secrets du conte chuchoté 🤫', body_fr = 'Il invente des prétextes pour fuir le lit ? Baissez complètement la voix, ne parlez plus qu''en chuchotant. Pour vous comprendre, il sera physiquement obligé de se concentrer, et son cerveau s''endormira bientôt.', title_hi = 'फुसफुसाती कहानी के राज़ 🤫', body_hi = 'बिस्तर से भागने के बहाने गढ़ रहा है? अपनी आवाज़ पूरी तरह धीमी कर दीजिए, बस फुसफुसाकर बोलना शुरू कीजिए। आपको समझने के लिए उसे पूरा ध्यान लगाना पड़ेगा और उसका दिमाग जल्दी ही नींद में चला जाएगा।', title_id = 'Rahasia dongeng berbisik 🤫', body_id = 'Ia mengarang alasan untuk kabur dari tempat tidur? Kecilkan suara Anda sepenuhnya dan mulailah berbicara hanya dengan berbisik. Untuk memahami Anda, ia terpaksa memusatkan perhatian secara fisik, dan otaknya akan segera tertidur.', title_ja = 'ささやき声のお話のひみつ 🤫', body_ja = 'ベッドから逃げる言いわけを考えている？声をぐっと小さくして、ささやき声だけで話し始めましょう。聞きとるために体ごと集中しなければならず、脳はすぐに眠りに落ちます。', title_ko = '속삭이는 동화의 비밀 🤫', body_ko = '침대에서 빠져나가려고 핑계를 지어내나요? 목소리를 완전히 낮추고 속삭이듯만 말하세요. 엄마 말을 알아들으려면 집중할 수밖에 없고, 머리가 곧 잠에 빠질 거예요.', title_nl = 'Fluistergeheimen bij het sprookje 🤫', body_nl = 'Verzint hij smoesjes om uit bed te ontsnappen? Laat je stem helemaal zakken en praat alleen nog fluisterend. Om je te begrijpen moet hij zich lichamelijk concentreren, en zijn brein valt al snel in slaap.', title_pl = 'Szeptane sekrety bajki 🤫', body_pl = 'Wymyśla wymówki, żeby uciec z łóżka? Całkiem ścisz głos i zacznij mówić tylko szeptem. Żeby cię zrozumieć, będzie musiał fizycznie skupić uwagę, a jego mózg szybko zaśnie.', title_pt = 'Segredos de histórias em sussurro 🤫', body_pt = 'Inventa desculpas para fugir da cama? Baixe a voz por completo e comece a falar só em sussurro. Para a perceber, vai ter de se concentrar fisicamente e o cérebro dele vai adormecer em pouco tempo.', title_sv = 'Viskande sagohemligheter 🤫', body_sv = 'Hittar barnet på ursäkter för att smita ur sängen? Sänk rösten helt och börja bara prata viskande. Barnet måste fysiskt koncentrera sig för att förstå dig, och hjärnan somnar snart.', title_vi = 'Bí mật của câu chuyện thì thầm 🤫', body_vi = 'Bé nghĩ ra đủ lý do để trốn khỏi giường? Hãy hạ giọng hoàn toàn, chỉ nói thì thầm. Để hiểu được mẹ, bé buộc phải tập trung cao độ và não bé sẽ sớm chìm vào giấc ngủ.', title_zh = '悄悄话童话的秘密 🤫', body_zh = '编各种借口想从床上溜走？把声音完全压低，只用悄悄话说话。为了听懂你，宝宝不得不集中注意力，大脑很快就会进入梦乡。' WHERE id = 'bf4ef479-e79f-4536-adc8-2a33fe4bb476' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué me has cortado la voz? 🎶', body_es = '¿Te has puesto a tararear la canción infantil que sonaba de fondo y al instante ha gritado «¡Tú no cantes!»? El único solista de la habitación es él y tus intentos vocales le quitan escenario. No te lo tomes a mal, deja el escenario a este pequeño egoísta.', title_fr = 'Pourquoi tu m''as coupé la parole ? 🎶', body_fr = 'Vous avez fredonné la chanson pour enfants qui passait en fond, et il a aussitôt crié : « Chante pas ! » ? Il est le seul soliste de la pièce, et vos essais vocaux rétrécissent sa scène. Ne vous vexez pas, laissez la scène à ce petit égoïste.', title_hi = 'तुमने मेरी आवाज़ क्यों रोकी? 🎶', body_hi = 'बैकग्राउंड में बजते बच्चों के गाने के साथ आपने गुनगुनाना शुरू किया और वह फ़ौरन चिल्लाया: ‘तुम मत गाओ!’? कमरे का इकलौता गायक वही है, आपकी गायकी उसके मंच को छोटा कर देती है। बुरा मत मानिए, मंच इस नन्हे ‘स्वार्थी’ के हवाले कर दीजिए।', title_id = 'Kenapa Mama potong suaraku? 🎶', body_id = 'Anda ikut bersenandung mengikuti lagu anak-anak di latar, dan ia langsung berteriak ''Mama jangan nyanyi!''? Ialah satu-satunya penyanyi di kamar, usaha vokal Anda mempersempit panggungnya. Jangan tersinggung, serahkan panggung pada si kecil yang egois ini.', title_ja = 'なんでわたしの歌を止めたの？ 🎶', body_ja = '流れている童謡にハミングで加わったら、すぐに「ママはうたわないで！」と叫んだ？部屋のソリストはこの子だけ。あなたの歌声はステージをせまくしてしまうんです。傷つかないで、ステージはこの小さなわがままさんにゆずりましょう。', title_ko = '왜 엄마가 노래해? 🎶', body_ko = '배경에 흐르는 동요를 따라 흥얼거렸더니 바로 ''엄마는 부르지 마!'' 하고 소리쳤나요? 이 방의 유일한 솔리스트는 아이예요. 엄마의 노래가 무대를 좁히는 거죠. 서운해하지 말고 무대를 이 꼬마 스타에게 양보하세요.', title_nl = 'Waarom ben je mijn liedje gestopt? 🎶', body_nl = 'Neuriede je mee met het kinderliedje op de achtergrond en riep hij meteen: ''Niet zingen!''? Hij is de enige solist in de kamer, jouw zangpogingen maken zijn podium kleiner. Voel je niet gekwetst en laat het podium aan deze kleine egoïst.', title_pl = 'Czemu mi przerwałeś? 🎶', body_pl = 'Zanuciłaś do dziecięcej piosenki lecącej w tle, a on od razu krzyknął: „Nie śpiewaj!”? Jest jedynym solistą w pokoju, a twoje wokalne próby zabierają mu scenę. Nie obrażaj się, oddaj scenę temu małemu egoiście.', title_pt = 'Porque é que me cortaste a voz? 🎶', body_pt = 'Cantarolou a canção infantil que tocava de fundo e ele gritou logo: "Não cantes!"? O único solista do quarto é ele, e as suas tentativas vocais encolhem-lhe o palco. Não fique magoada, deixe o palco a este pequeno egoísta.', title_sv = 'Varför avbröt du mig? 🎶', body_sv = 'Nynnade du med i barnlåten i bakgrunden och barnet skrek direkt: ”Sjung inte du!” Barnet är rummets enda solist, och dina sångförsök tar plats från hens scen. Ta inte illa upp, lämna scenen åt den lilla egoisten.', title_vi = 'Sao mẹ lại tắt tiếng con? 🎶', body_vi = 'Mẹ ngân nga theo bài hát thiếu nhi đang phát và bé lập tức hét lên: "Mẹ đừng hát!"? Bé là ca sĩ solo duy nhất trong phòng, những nỗ lực hát của mẹ làm "sân khấu" của bé hẹp lại. Đừng tự ái, hãy nhường sân khấu cho "kẻ ích kỷ" nhỏ này.', title_zh = '为什么不让我唱？🎶', body_zh = '背景里放着儿歌，你跟着哼了几句，宝宝马上大喊：“你别唱！”宝宝是这个房间唯一的独唱歌手，你的演唱挤占了宝宝的舞台。别难过，把舞台让给这个小“自私鬼”吧。' WHERE id = 'dd593bef-61fd-4b06-ae2c-84f70da4ad5c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Elige su propia ropa 👗', body_es = 'Pantalón rojo, zapatillas de deporte y gorro de invierno... Y se empeña en ir así al parque. Olvídate de lo que dirá la gente. Deja que salga con lo que ha elegido: esta libertad es más importante para él que la estética.', title_fr = 'Il choisit ses vêtements tout seul 👗', body_fr = 'Pantalon rouge, baskets et bonnet d''hiver... Et il insiste pour aller au parc comme ça. Peu importe ce que diront les gens. Laissez-le sortir avec son propre choix : cette liberté compte plus pour lui que l''esthétique.', title_hi = 'अपने कपड़े खुद चुनता है 👗', body_hi = 'लाल पैंट, स्पोर्ट्स शूज़ और सर्दियों की टोपी... और ज़िद कि पार्क ऐसे ही जाएगा। लोग क्या कहेंगे, छोड़िए। उसे अपनी पसंद से निकलने दीजिए, यह आज़ादी उसके लिए दिखावट से ज़्यादा ज़रूरी है।', title_id = 'Ia memilih bajunya sendiri 👗', body_id = 'Celana merah, sepatu olahraga, dan topi musim dingin... Dan ia bersikeras pergi ke taman seperti itu. Lupakan apa kata orang. Biarkan ia keluar dengan pilihannya sendiri, kebebasan ini lebih penting baginya daripada estetika.', title_ja = '自分の服は自分で選ぶ 👗', body_ja = '赤いズボンにスニーカー、冬の帽子…。そして、この格好で公園に行くと言いはる。人にどう思われるかは気にしないで。自分で選んだ服で出かけさせましょう。この自由は、見た目よりずっと大切です。', title_ko = '내 옷은 내가 골라 👗', body_ko = '빨간 바지, 운동화, 겨울 모자... 그리고 꼭 이대로 공원에 가겠대요. 남들이 뭐라 할지는 잊으세요. 자기 선택대로 나가게 두세요. 아이에게 이 자유는 멋보다 더 중요해요.', title_nl = 'Hij kiest zelf zijn kleren 👗', body_nl = 'Een rode broek, sportschoenen en een wintermuts... En hij houdt vol dat hij zo naar het park gaat. Trek je niets aan van wat anderen zeggen. Laat hem gaan in wat hij zelf koos, deze vrijheid is voor hem belangrijker dan esthetiek.', title_pl = 'Sam wybiera sobie ubrania 👗', body_pl = 'Czerwone spodnie, sportowe buty i zimowa czapka... I upiera się, że tak pójdzie do parku. Nie przejmuj się, co powiedzą ludzie. Niech wyjdzie w tym, co sam wybrał, ta swoboda jest dla niego ważniejsza niż estetyka.', title_pt = 'Escolhe a própria roupa 👗', body_pt = 'Calças vermelhas, ténis e gorro de inverno... E insiste em ir assim ao parque. Esqueça o que os outros vão dizer. Deixe-o sair com a escolha dele: esta liberdade é mais importante para ele do que a estética.', title_sv = 'Väljer sina kläder själv 👗', body_sv = 'Röda byxor, gympaskor och vintermössa... Och barnet insisterar på att gå till parken så. Strunta i vad andra ska säga. Låt barnet gå ut i sitt eget val, den friheten är viktigare för hen än estetiken.', title_vi = 'Bé tự chọn quần áo 👗', body_vi = 'Quần đỏ, giày thể thao và mũ mùa đông... Và bé nhất định mặc thế ra công viên. Kệ người khác nói gì. Hãy để bé ra ngoài với lựa chọn của mình, sự tự do này quan trọng với bé hơn thẩm mỹ.', title_zh = '自己挑衣服 👗', body_zh = '红裤子、运动鞋，再配一顶冬天的帽子……还坚持就要这样去公园。别管别人怎么说。让宝宝按自己的选择出门吧，这份自由对宝宝来说比好不好看更重要。' WHERE id = '0e5c772e-ad3b-4b0c-99e1-704d879eb64e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pacto del sueño con temporizador ⏱️', body_es = '¿Cuando llega la hora de dormir de repente le entra sed o se despide de la pared? Pon un temporizador. Establece la regla: «Cuando suena la campanita, todos a dormir». Obedecer a una autoridad externa siempre les resulta más fácil.', title_fr = 'L''accord du coucher avec le minuteur ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif ou dit au revoir au mur ? Réglez un minuteur. Instaurez la règle « Quand la sonnerie retentit, tout le monde dort ». Se plier à une autorité extérieure leur paraît toujours plus facile.', title_hi = 'टाइमर वाला नींद का समझौता ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है या दीवार को गुड नाइट कहने लगता है? टाइमर लगाइए। नियम बनाइए: ‘घंटी बजे तो सब सो जाते हैं।’ बाहर की किसी ‘अथॉरिटी’ के आगे झुकना बच्चों को हमेशा आसान लगता है।', title_id = 'Kesepakatan tidur dengan timer ⏱️', body_id = 'Begitu waktu tidur tiba, tiba-tiba ia haus atau berpamitan dengan dinding? Pasang timer. Buat aturan ''Saat bel berbunyi, semua orang tidur''. Tunduk pada otoritas dari luar selalu terasa lebih mudah bagi mereka.', title_ja = 'タイマーで寝る時間の約束 ⏱️', body_ja = '寝る時間になると、急にのどがかわいたり、壁におやすみを言ったり？タイマーをセットして、「ベルが鳴ったらみんな寝る」というルールを決めましょう。外からのルールには、いつも素直に従いやすいものです。', title_ko = '타이머로 잠자리 약속 ⏱️', body_ko = '잘 시간만 되면 갑자기 목이 마르거나 벽에게 인사를 하나요? 타이머를 맞추고 ''알람이 울리면 모두 잔다''는 규칙을 정하세요. 바깥의 권위에는 늘 더 쉽게 따르거든요.', title_nl = 'Slaapafspraak met de timer ⏱️', body_nl = 'Krijgt hij als het bedtijd is ineens dorst of moet hij de muur nog welterusten zeggen? Zet een timer. Maak de regel: ''Als de bel gaat, gaat iedereen slapen.'' Buigen voor een autoriteit van buitenaf valt kinderen altijd makkelijker.', title_pl = 'Umowa o sen z timerem ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić albo żegna się ze ścianą? Nastaw timer. Wprowadź zasadę: „Gdy zadzwoni dzwonek, wszyscy śpią”. Dzieciom zawsze łatwiej podporządkować się zewnętrznemu autorytetowi.', title_pt = 'O acordo de sono com temporizador ⏱️', body_pt = 'Quando chega a hora de dormir, de repente tem sede ou despede-se da parede? Programe um temporizador. Crie a regra "quando a campainha toca, todos dormem". Obedecer a uma autoridade externa é-lhes sempre mais fácil.', title_sv = 'Sömnavtal med timer ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt eller säger god natt till väggen? Ställ in en timer. Inför regeln ”när klockan ringer sover alla”. Att böja sig för en yttre auktoritet känns alltid lättare för barn.', title_vi = 'Thỏa thuận giờ ngủ bằng hẹn giờ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước hay đi chúc ngủ ngon bức tường? Hãy đặt hẹn giờ. Đặt quy tắc "Chuông reo là cả nhà đi ngủ". Trẻ luôn thấy dễ nghe theo một "uy quyền bên ngoài" hơn.', title_zh = '和计时器的睡眠约定 ⏱️', body_zh = '一到睡觉时间就突然口渴，或者去和墙壁说再见？设个计时器。定一个规则：“铃声一响，大家都睡觉。”服从一个外部“权威”，对孩子来说总是更容易。' WHERE id = '1c02e319-6351-4dbf-93b0-072c9cbcabab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué la luna no se ha ido todavía? 🌙', body_es = '¿Por la mañana ha visto la luna en el cielo y te ha preguntado «¿Por qué la luna no se ha ido a dormir?»? No le canses la cabeza con términos científicos. Abre Anacan AI, busca ese cuento astronómico tan tierno para esta edad, léeselo y sacia sus preguntas.', title_fr = 'Pourquoi la lune n''est pas encore partie ? 🌙', body_fr = 'Le matin, il a vu la lune dans le ciel et a demandé « Pourquoi la lune ne dort pas ? » ? Ne fatiguez pas son cerveau avec des termes scientifiques. Ouvrez Anacan AI, trouvez ce doux conte astronomique adapté à son âge, lisez-le-lui et rassasiez sa curiosité.', title_hi = 'चाँद अभी तक गया क्यों नहीं? 🌙', body_hi = 'सुबह आसमान में चाँद देखकर पूछा, ‘चाँद सोया क्यों नहीं?’ वैज्ञानिक शब्दों से उसका दिमाग मत थकाइए। Anacan AI खोलिए, इस उम्र के लिए वह प्यारी, खगोलीय कहानी ढूँढकर उसे सुनाइए और उसके सवालों की प्यास बुझाइए।', title_id = 'Kenapa bulannya belum pergi? 🌙', body_id = 'Pagi ini ia melihat bulan di langit dan bertanya ''Kenapa bulannya belum tidur?'' Jangan bebani otaknya dengan istilah ilmiah. Buka Anacan AI, temukan dongeng astronomi yang manis untuk usia ini, bacakan untuknya, dan puaskan rasa ingin tahunya.', title_ja = 'なんでお月さまはまだいるの？ 🌙', body_ja = '朝、空にお月さまを見て「なんでお月さまは寝ないの？」と聞いた？専門用語で頭を疲れさせないで。Anacan AIを開いて、この年齢向けのかわいい天文学のお話を見つけて読んであげ、好奇心を満たしましょう。', title_ko = '달님은 왜 아직 안 갔어? 🌙', body_ko = '아침 하늘에 뜬 달을 보고 ''달님은 왜 안 자?''라고 물었나요? 과학 용어로 머리 아프게 하지 마세요. Anacan AI를 열어 이 나이에 맞는 귀여운 천문학 동화를 찾아 읽어 주고, 궁금증을 채워 주세요.', title_nl = 'Waarom is de maan nog niet weg? 🌙', body_nl = 'Zag hij ''s ochtends de maan aan de hemel en vroeg hij: ''Waarom slaapt de maan niet?'' Vermoei zijn hoofdje niet met wetenschappelijke termen. Open Anacan AI, zoek dat lieve, sterrenkundige sprookje voor deze leeftijd, lees het voor en stil zijn nieuwsgierigheid.', title_pl = 'Czemu księżyc jeszcze nie poszedł? 🌙', body_pl = 'Rano zobaczył na niebie księżyc i zapytał: „Czemu księżyc nie śpi?”. Nie męcz jego głowy naukowymi terminami. Otwórz Anacan AI, znajdź uroczą, astronomiczną bajkę dla tego wieku, przeczytaj mu ją i zaspokój jego ciekawość.', title_pt = 'Porque é que a lua ainda não foi embora? 🌙', body_pt = 'De manhã viu a lua no céu e perguntou "Porque é que a lua não foi dormir?"? Não lhe canse a cabeça com termos científicos. Abra o Anacan AI, encontre aquela doce história astronómica para esta idade, leia-lha e satisfaça a curiosidade dele.', title_sv = 'Varför har månen inte gått än? 🌙', body_sv = 'Såg barnet månen på himlen på morgonen och frågade ”Varför har månen inte lagt sig?” Trötta inte ut hjärnan med vetenskapliga termer. Öppna Anacan AI, hitta den söta, astronomiska sagan för den här åldern, läs den och mätta nyfikenheten.', title_vi = 'Sao Mặt Trăng vẫn chưa đi? 🌙', body_vi = 'Buổi sáng thấy Mặt Trăng trên trời, bé hỏi: "Sao Mặt Trăng chưa đi ngủ?" Đừng làm bé mệt đầu với thuật ngữ khoa học. Hãy mở Anacan AI, tìm câu chuyện thiên văn ngọt ngào cho lứa tuổi này, đọc cho bé nghe và thỏa mãn trí tò mò của bé.', title_zh = '月亮为什么还没走？🌙', body_zh = '早上看到天上的月亮，问“月亮为什么还没睡？”别用科学术语让宝宝的脑袋累着。打开Anacan AI，为这个年龄找一个可爱的天文童话读给宝宝听，满足宝宝的好奇心。' WHERE id = '42320a1e-019f-4b03-8860-b2a7ebec874e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Del pan solo se come el borde 🍞', body_es = '¿Del pan solo se come la corteza y tira el centro? Ya conoces estas filosofías alimentarias al revés. No pelees con las cortezas. Aprende en el plan de Nutrición a cortar el pan con moldes y crearle cortezas distintas.', title_fr = 'On ne mange que le bord du pain 🍞', body_fr = 'Il ne mange que la croûte du pain et jette le milieu ? Les philosophies alimentaires à l''envers, vous connaissez. Ne vous battez pas avec les croûtes. Apprenez dans le Plan de nutrition à découper le pain avec des emporte-pièces pour lui créer des croûtes différentes.', title_hi = 'ब्रेड का सिर्फ़ किनारा खाया जाता है 🍞', body_hi = 'ब्रेड का सिर्फ़ किनारा खाकर बीच वाला हिस्सा फेंक देता है? उल्टी ‘खाने की फ़िलॉसफ़ी’ आपके लिए नई नहीं। किनारों से मत लड़िए। फ़ीडिंग प्लान में सीखिए कि ब्रेड को साँचों से काटकर उसके लिए अलग-अलग किनारे कैसे बनाएँ।', title_id = 'Hanya pinggiran roti yang dimakan 🍞', body_id = 'Ia hanya memakan pinggiran roti dan membuang bagian tengahnya? Filsafat makanan yang terbalik sudah akrab bagi Anda. Jangan berperang dengan pinggiran roti. Pelajari di Rencana Nutrisi cara memotong roti dengan cetakan dan menciptakan pinggiran yang berbeda untuknya.', title_ja = 'パンは耳だけ食べる 🍞', body_ja = 'パンの耳だけ食べて、まん中は捨てる？あべこべな食の哲学にはもう慣れっこですね。耳と戦わないで。「栄養管理ツール」で、パンを型で抜いていろいろな耳をつくる方法を見てみましょう。', title_ko = '빵은 테두리만 먹어 🍞', body_ko = '빵 테두리만 먹고 가운데는 버리나요? 거꾸로 된 음식 철학, 익숙하죠. 테두리와 싸우지 마세요. 식단 계획에서 틀로 빵을 잘라 색다른 테두리를 만드는 법을 배워 보세요.', title_nl = 'Alleen de korst wordt gegeten 🍞', body_nl = 'Eet hij alleen de korst van het brood en gooit hij het midden weg? Omgekeerde voedselfilosofieën ken je inmiddels. Ga niet vechten om korstjes. Leer in het onderdeel Voeding hoe je brood met vormpjes uitsteekt om hem andere korstjes te geven.', title_pl = 'Jemy tylko skórkę chleba 🍞', body_pl = 'Zjada tylko skórkę chleba, a środek wyrzuca? Odwrócone filozofie żywieniowe dobrze znasz. Nie walcz ze skórkami. Dowiedz się z planu karmienia, jak wycinać chleb foremkami i tworzyć mu różne skórki.', title_pt = 'Do pão só se come a côdea 🍞', body_pt = 'Come só a côdea do pão e deita fora o miolo? As filosofias alimentares ao contrário já lhe são familiares. Não lute com as côdeas. Aprenda no plano de alimentação a cortar o pão com formas e a criar-lhe côdeas diferentes.', title_sv = 'Bara brödkanten äts 🍞', body_sv = 'Äter barnet bara skorpan och slänger mitten? Bakvända matfilosofier känner du redan till. Kämpa inte mot skorporna. Lär dig i matplanen hur du skär brödet med formar och skapar olika kanter.', title_vi = 'Chỉ ăn viền bánh mì 🍞', body_vi = 'Bé chỉ ăn phần viền và bỏ phần ruột bánh mì? Những triết lý ăn uống "ngược đời" đã quá quen với mẹ. Đừng chiến đấu với vỏ bánh. Hãy học cách cắt bánh mì bằng khuôn trong Kế hoạch dinh dưỡng để tạo ra nhiều viền bánh khác nhau cho bé.', title_zh = '面包只吃边 🍞', body_zh = '面包只吃边，把中间扔了？这种反着来的“饮食哲学”你一定不陌生。别和面包边较劲。去喂养计划里学学怎样用模具切面包，给宝宝做出不一样的“边”。' WHERE id = '37e1f058-26f3-4681-8381-3414a60ed5c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Oscuridad para la melatonina 🌌', body_es = 'Para que se duerma antes, apaga todas las pantallas de tele y móvil de la habitación 1 hora antes de dormir. La melatonina (la hormona del sueño) solo se libera rápido en un ambiente oscuro: confía en el proceso natural.', title_fr = 'Le noir pour la mélatonine 🌌', body_fr = 'Pour qu''il s''endorme plus vite, éteignez tous les écrans de télé et de téléphone de la chambre 1 heure avant le coucher. La mélatonine (l''hormone du sommeil) n''est sécrétée rapidement que dans un environnement sombre, faites confiance au processus naturel.', title_hi = 'मेलाटोनिन के लिए अंधेरा 🌌', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी टीवी और फ़ोन की स्क्रीनें बंद कर दीजिए। मेलाटोनिन (नींद का हार्मोन) सिर्फ़ धुँधले माहौल में तेज़ी से बनता है, प्राकृतिक प्रक्रिया पर भरोसा कीजिए।', title_id = 'Gelap untuk melatonin 🌌', body_id = 'Agar ia lebih cepat tertidur, matikan semua layar TV dan ponsel di kamar 1 jam sebelum tidur. Melatonin (hormon tidur) hanya diproduksi dengan cepat di lingkungan yang redup, percayalah pada proses alaminya.', title_ja = 'メラトニンのための暗さ 🌌', body_ja = '早く寝つけるように、寝る1時間前に部屋のテレビやスマホの画面をすべて消しましょう。メラトニン（睡眠ホルモン）は暗い環境でこそすばやく分泌されます。自然の流れを信じて。', title_ko = '멜라토닌을 위한 어둠 🌌', body_ko = '더 빨리 잠들게 하려면 자기 1시간 전에 방 안의 TV와 휴대폰 화면을 모두 끄세요. 멜라토닌(수면 호르몬)은 어두운 환경에서만 빠르게 분비돼요. 자연스러운 과정을 믿으세요.', title_nl = 'Donker voor melatonine 🌌', body_nl = 'Zet een uur voor het slapengaan alle tv- en telefoonschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine (het slaaphormoon) wordt alleen in een donkere omgeving snel aangemaakt, vertrouw op dit natuurlijke proces.', title_pl = 'Ciemność dla melatoniny 🌌', body_pl = 'Żeby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie ekrany telewizora i telefonu. Melatonina (hormon snu) szybko wydziela się tylko w ciemnym otoczeniu, zaufaj naturalnemu procesowi.', title_pt = 'Escuridão para a melatonina 🌌', body_pt = 'Para que adormeça mais depressa, desligue 1 hora antes de dormir todos os ecrãs de televisão e telemóvel do quarto. A melatonina (hormona do sono) só é produzida rapidamente num ambiente escuro, confie no processo natural.', title_sv = 'Mörker för melatoninet 🌌', body_sv = 'För att barnet ska somna snabbare, stäng av alla tv- och telefonskärmar i rummet en timme före läggdags. Melatonin (sömnhormonet) utsöndras snabbt bara i en mörk miljö, lita på den naturliga processen.', title_vi = 'Bóng tối cho melatonin 🌌', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt hết TV và màn hình điện thoại trong phòng 1 tiếng trước giờ ngủ. Melatonin (hormone giấc ngủ) chỉ được tiết ra nhanh trong môi trường tối, hãy tin vào quá trình tự nhiên.', title_zh = '为褪黑素留一片黑暗 🌌', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有电视和手机屏幕。褪黑素（睡眠激素）只有在昏暗的环境里才会快速分泌，相信这个自然的过程吧。' WHERE id = 'd40bcca0-d355-4520-b51b-bece0b2b8663' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué no duermen los juguetes? 🧸', body_es = '¿Él no se duerme, pero acuesta a todos sus juguetes uno a uno y los tapa? Este juego de rol en realidad lo va preparando poco a poco, psicológicamente, para su propio sueño. No intervengas en absoluto.', title_fr = 'Pourquoi les jouets ne dorment pas ? 🧸', body_fr = 'Lui ne dort pas, mais il couche tous ses jouets un par un et les borde ? Ce jeu de rôle le prépare en fait doucement, psychologiquement, à son propre sommeil. Surtout, n''intervenez pas.', title_hi = 'खिलौने क्यों नहीं सोते? 🧸', body_hi = 'खुद नहीं सोता, पर अपने सारे खिलौनों को एक-एक करके बिस्तर पर लिटाकर ओढ़ाता है? यह रोल-प्ले असल में उसे धीरे-धीरे, मन से उसकी अपनी नींद के लिए तैयार कर रहा है, बिल्कुल दखल मत दीजिए।', title_id = 'Kenapa mainannya tidak tidur? 🧸', body_id = 'Ia sendiri tidak tidur, tapi menidurkan semua mainannya satu per satu dan menyelimutinya? Permainan peran ini sebenarnya perlahan menyiapkannya secara psikologis untuk tidurnya sendiri, sama sekali jangan ikut campur.', title_ja = 'なんでおもちゃは寝ないの？ 🧸', body_ja = '自分は寝ないのに、おもちゃを全部ひとつずつベッドに寝かせて布団をかけている？このごっこ遊びが、少しずつ心の中で自分の眠りの準備をさせています。決してじゃましないで。', title_ko = '장난감은 왜 안 자? 🧸', body_ko = '자기는 안 자면서 장난감을 하나씩 모두 침대에 눕히고 이불을 덮어 주나요? 이 역할 놀이가 사실 아이를 마음으로부터 천천히 잠에 준비시키는 중이에요. 절대 끼어들지 마세요.', title_nl = 'Waarom slapen de knuffels niet? 🧸', body_nl = 'Gaat hij zelf niet slapen, maar legt hij al zijn knuffels één voor één in bed en dekt hij ze toe? Dit rollenspel bereidt hem eigenlijk langzaam en psychologisch voor op zijn eigen slaap, grijp beslist niet in.', title_pl = 'Czemu zabawki nie śpią? 🧸', body_pl = 'Sam nie śpi, ale kładzie wszystkie zabawki po kolei do łóżka i je przykrywa? Ta zabawa w odgrywanie ról tak naprawdę powoli, psychologicznie przygotowuje go do własnego snu, absolutnie nie przeszkadzaj.', title_pt = 'Porque é que os brinquedos não dormem? 🧸', body_pt = 'Ele não dorme, mas deita todos os brinquedos um a um e tapa-os? Este jogo de faz de conta está, na verdade, a prepará-lo devagarinho e psicologicamente para o seu próprio sono. Não interfira de maneira nenhuma.', title_sv = 'Varför sover inte leksakerna? 🧸', body_sv = 'Sover barnet inte själv, men lägger alla leksaker i sängen en efter en och bäddar om dem? Den här rolleken förbereder egentligen barnet psykologiskt, sakta men säkert, för sin egen sömn, lägg dig absolut inte i.', title_vi = 'Sao đồ chơi không chịu ngủ? 🧸', body_vi = 'Bé chưa chịu ngủ, nhưng lại đặt từng món đồ chơi lên giường và đắp chăn cho chúng? Trò nhập vai này thật ra đang từ từ chuẩn bị tâm lý cho chính giấc ngủ của bé, tuyệt đối đừng can thiệp.', title_zh = '玩具为什么不睡觉？🧸', body_zh = '自己不睡，却把所有玩具一个个放到床上盖好被子？这个角色扮演其实正在慢慢地从心理上帮宝宝为自己的睡眠做准备，千万别打扰。' WHERE id = 'eb8ec98b-d143-483a-b14c-964f86bd6a10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo respira su olor 🫂', body_es = '¿Hoy te ha vuelto loca de verdad y te ha dejado sin energía? Pero duerme en la cama con tanta inocencia... Apaga las luces. Túmbate a su lado, respira hondo ese olor limpio de niño y susúrrale tu amor en la oscuridad.', title_fr = 'Respirez simplement son odeur 🫂', body_fr = 'Aujourd''hui, il vous a vraiment rendue folle et a aspiré toute votre énergie ? Mais il dort si innocemment dans son lit... Éteignez la lumière. Allongez-vous près de lui, respirez profondément cette pure odeur d''enfant et, dans le noir, chuchotez-lui votre amour.', title_hi = 'बस उसकी खुशबू अपने अंदर भर लीजिए 🫂', body_hi = 'आज उसने सच में आपको पागल कर दिया, सारी ऊर्जा निचोड़ ली? पर बिस्तर पर कितना मासूम सो रहा है... लाइटें बंद कीजिए। उसके पास लेटिए, उस मासूम बच्चे की खुशबू गहरी साँसों में भरिए और अंधेरे में उसे अपना प्यार फुसफुसाकर बताइए।', title_id = 'Cukup hirup aromanya 🫂', body_id = 'Hari ini ia benar-benar membuat Anda pusing dan menyedot energi Anda? Tapi ia tidur begitu polos di tempat tidurnya... Matikan lampu. Berbaringlah di sampingnya, hirup dalam-dalam aroma anak yang bersih itu, dan dalam gelap bisikkan rasa sayang Anda.', title_ja = 'においを深く吸いこんで 🫂', body_ja = '今日は本当に振りまわされて、エネルギーを吸いとられた？でも、ベッドではこんなに無邪気に眠っている…。明かりを消しましょう。そばに横になって、子どもの清らかなにおいを深く吸いこみ、暗やみの中で愛をささやいてあげて。', title_ko = '그냥 냄새를 깊이 들이마셔요 🫂', body_ko = '오늘 정말 미칠 것 같고 에너지를 다 빼앗겼나요? 그래도 침대에선 저렇게 순하게 자고 있죠... 불을 끄세요. 옆에 누워 그 깨끗한 아이 냄새를 깊이 들이마시고, 어둠 속에서 사랑한다고 속삭여 주세요.', title_nl = 'Snuif gewoon zijn geur op 🫂', body_nl = 'Heeft hij je vandaag echt gek gemaakt en al je energie opgezogen? Maar hij ligt zo onschuldig in bed... Doe het licht uit. Ga naast hem liggen, snuif diep die zuivere kindergeur op en fluister in het donker hoeveel je van hem houdt.', title_pl = 'Po prostu poczuj jego zapach 🫂', body_pl = 'Dziś naprawdę doprowadził cię do szału i wyssał z ciebie energię? A jednak śpi w łóżku tak niewinnie... Zgaś światło. Połóż się obok, głęboko wdychaj ten czysty dziecięcy zapach i w ciemności wyszeptaj mu swoją miłość.', title_pt = 'Respire só o cheirinho dele 🫂', body_pt = 'Hoje deu-lhe mesmo cabo da cabeça e sugou-lhe a energia? Mas está a dormir na cama tão inocente... Apague as luzes. Deite-se ao lado dele, respire fundo aquele cheirinho puro de criança e sussurre-lhe no escuro o seu amor.', title_sv = 'Andas bara in doften 🫂', body_sv = 'Gjorde barnet dig verkligen galen i dag och sög ut all energi? Men i sängen ligger hen så oskyldigt... Släck lamporna. Lägg dig bredvid, andas djupt in den rena barndoften och viska din kärlek i mörkret.', title_vi = 'Chỉ cần hít hương thơm của bé 🫂', body_vi = 'Hôm nay bé thật sự làm mẹ phát điên, rút cạn sức lực? Nhưng lúc này bé nằm ngủ trên giường thật ngây thơ... Hãy tắt đèn. Nằm xuống cạnh bé, hít thật sâu mùi hương trẻ thơ trong trẻo ấy và thì thầm lời yêu thương trong bóng tối.', title_zh = '深深闻一闻宝宝的味道 🫂', body_zh = '今天宝宝真的快把你逼疯了，耗尽了你的能量？可躺在床上的样子又那么天真……关上灯。躺在宝宝身边，深深吸一口那纯净的孩子气息，在黑暗中轻声说出你的爱。' WHERE id = '22a3d2df-ec5e-47c6-9766-7dc689ce8423' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quedarse en blanco en medio del súper 🛒', body_es = '¿Has entrado en el súper y se te ha olvidado qué ibas a comprar? Si no llevas la Lista de la compra en digital, en ese caos lo olvidarás todo. Confía siempre en tu memoria digital de la app para no volver a casa con las manos vacías.', title_fr = 'Figée au milieu du supermarché 🛒', body_fr = 'Vous êtes entrée au supermarché et avez oublié ce que vous deviez acheter ? Si vous ne tenez pas votre Liste de courses en version numérique, vous oublierez tout dans ce chaos. Faites toujours confiance à la mémoire numérique de l''application pour ne pas rentrer les mains vides.', title_hi = 'सुपरमार्केट के बीच में जम जाना 🛒', body_hi = 'सुपरमार्केट में घुसीं और भूल गईं कि क्या लेना है? शॉपिंग लिस्ट डिजिटल न रखी, तो उस अफ़रा-तफ़री में सब भूल जाएँगी। ऐप की अपनी डिजिटल याददाश्त पर हमेशा भरोसा कीजिए, ताकि खाली हाथ घर न लौटें।', title_id = 'Terpaku di tengah supermarket 🛒', body_id = 'Anda masuk supermarket dan lupa mau beli apa? Kalau Daftar Belanja tidak disimpan secara digital, Anda akan melupakan semuanya di tengah kekacauan itu. Selalu andalkan memori digital Anda di aplikasi supaya tidak pulang dengan tangan kosong.', title_ja = 'スーパーのまん中でフリーズ 🛒', body_ja = 'スーパーに入ったら、何を買うか忘れてしまった？「買い物リスト」をデジタルで管理しないと、あのカオスの中で全部忘れてしまいます。手ぶらで帰らないように、アプリのデジタルの記憶をいつでもたよりにしましょう。', title_ko = '마트 한가운데서 멈춤 🛒', body_ko = '마트에 들어갔는데 뭘 사야 할지 잊어버렸나요? 쇼핑 목록을 디지털로 관리하지 않으면 그 혼란 속에서 다 잊게 돼요. 빈손으로 돌아오지 않도록 앱 속 디지털 기억을 언제나 믿으세요.', title_nl = 'Bevroren midden in de supermarkt 🛒', body_nl = 'Kom je de supermarkt in en weet je niet meer wat je moest kopen? Als je je boodschappenlijstje niet digitaal bijhoudt, vergeet je in die chaos alles. Vertrouw altijd op het digitale geheugen in de app, zodat je niet met lege handen thuiskomt.', title_pl = 'Zawieszona na środku sklepu 🛒', body_pl = 'Weszłaś do sklepu i zapomniałaś, co miałaś kupić? Jeśli nie prowadzisz cyfrowej Listy zakupów, w tym chaosie zapomnisz o wszystkim. Zawsze ufaj cyfrowej pamięci w aplikacji, żeby nie wrócić do domu z pustymi rękami.', title_pt = 'Parada no meio do supermercado 🛒', body_pt = 'Entrou no supermercado e esqueceu-se do que ia comprar? Se não tiver a Lista de Compras em formato digital, naquele caos vai esquecer tudo. Confie sempre na memória digital da app para não voltar para casa de mãos a abanar.', title_sv = 'Att stelna till mitt i affären 🛒', body_sv = 'Gick du in i affären och glömde vad du skulle köpa? Om du inte har inköpslistan digitalt glömmer du allt i det kaoset. Lita alltid på ditt digitala minne i appen så att du inte kommer hem tomhänt.', title_vi = 'Đứng hình giữa siêu thị 🛒', body_vi = 'Vào siêu thị rồi mà quên mất định mua gì? Nếu không lưu Danh sách mua sắm trên điện thoại, giữa mớ hỗn loạn ấy mẹ sẽ quên hết. Hãy luôn tin vào "bộ nhớ số" trong ứng dụng để không phải về nhà tay không.', title_zh = '在超市中间愣住 🛒', body_zh = '走进超市，却忘了要买什么？如果不把购物清单存在手机上，在那片混乱里你会什么都忘。永远相信应用里的数字记忆，别空着手回家。' WHERE id = '48b463cd-d776-4db6-a471-4507d498dd54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No juegas conmigo! 😤', body_es = '¿Mientras remueves la comida viene y te gira la cara hacia él con las manos: «¡Mírame!»? Tiene razón. No quiere tu presencia física, sino tu atención completa. Deja lo que estás haciendo y escúchalo solo 2 minutos mirándolo a los ojos.', title_fr = 'Tu ne joues pas avec moi ! 😤', body_fr = 'Pendant que vous remuez le plat, il vient tourner votre visage vers lui avec ses mains : « Regarde-moi ! » ? Il a raison. Ce n''est pas votre présence physique qu''il veut, mais votre attention entière. Lâchez ce que vous faites et écoutez-le simplement 2 minutes en le regardant dans les yeux.', title_hi = 'तुम मेरे साथ नहीं खेल रहीं! 😤', body_hi = 'आप खाना चला रही हैं और वह आकर हाथों से आपका चेहरा अपनी ओर घुमाता है: ‘मुझे देखो!’? वह सही है। उसे आपकी मौजूदगी नहीं, आपका पूरा ध्यान चाहिए। काम छोड़िए, बस 2 मिनट पूरी आँखों में आँखें डालकर उसे सुनिए।', title_id = 'Mama nggak main sama aku! 😤', body_id = 'Saat Anda sedang mengaduk masakan, ia datang dan memutar wajah Anda ke arahnya dengan kedua tangan: ''Lihat aku!''? Ia benar. Ia tidak menginginkan kehadiran fisik Anda, tapi perhatian Anda yang utuh. Tinggalkan pekerjaan Anda, cukup 2 menit dengarkan ia dengan kontak mata penuh.', title_ja = 'ママ、遊んでくれない！ 😤', body_ja = '料理をまぜていると、やってきて両手であなたの顔を自分に向けて「ママ、見て！」？そのとおりです。そばにいるだけでなく、まるごとの注意を求めているんです。手を止めて、たった2分、しっかり目を合わせて話を聞いてあげましょう。', title_ko = '엄마는 나랑 안 놀아 줘! 😤', body_ko = '요리하며 냄비를 젓고 있는데 와서 두 손으로 엄마 얼굴을 돌리며 ''나 봐!'' 하나요? 맞는 말이에요. 몸이 곁에 있는 게 아니라 온전한 관심을 원해요. 하던 일을 내려놓고 딱 2분만 눈을 맞추며 들어 주세요.', title_nl = 'Je speelt niet met mij! 😤', body_nl = 'Komt hij terwijl jij in de pan roert met zijn handjes je gezicht naar zich toe draaien: ''Kijk naar mij!''? Hij heeft gelijk. Hij wil niet alleen dat je er bent, hij wil je onverdeelde aandacht. Laat je bezigheid even liggen en luister 2 minuten naar hem met volledig oogcontact.', title_pl = 'Nie bawisz się ze mną! 😤', body_pl = 'Gdy mieszasz obiad, podchodzi i rączkami odwraca twoją twarz do siebie: „Patrz na mnie!”? Ma rację. Nie chodzi mu o twoją fizyczną obecność, tylko o niepodzielną uwagę. Zostaw to, co robisz, i choćby przez 2 minuty słuchaj go, patrząc mu w oczy.', title_pt = 'Não estás a brincar comigo! 😤', body_pt = 'Enquanto mexe a comida, ele vem virar-lhe a cara para ele com as mãos: "Olha para mim!"? Tem razão. Não quer a sua presença física, quer a sua atenção total. Largue o que está a fazer e ouça-o só 2 minutos, com total contacto visual.', title_sv = 'Du leker inte med mig! 😤', body_sv = 'Kommer barnet när du rör i maten och vänder ditt ansikte mot sig med händerna: ”Titta på mig!” Hen har rätt. Hen vill inte ha din fysiska närvaro, utan din odelade uppmärksamhet. Släpp det du gör och lyssna med full ögonkontakt i bara 2 minuter.', title_vi = 'Mẹ không chơi với con! 😤', body_vi = 'Mẹ đang khuấy nồi thì bé đến, lấy tay xoay mặt mẹ về phía mình: "Mẹ nhìn con này!"? Bé nói đúng đấy. Bé không cần mẹ chỉ có mặt, mà cần sự chú ý trọn vẹn của mẹ. Hãy bỏ việc xuống, nhìn thẳng vào mắt bé và lắng nghe chỉ 2 phút.', title_zh = '你都不陪我玩！😤', body_zh = '你在搅锅里的菜时，宝宝过来用小手把你的脸转过去：“看我！”宝宝说得对。宝宝要的不是你在身边，而是你全部的注意力。放下手头的事，只用2分钟，看着宝宝的眼睛认真听。' WHERE id = '9dc02f00-56a0-48da-87a7-8f742a42c374' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una habitación con sonido de lluvia 🌧️', body_es = '¿Te has quedado sin voz y sin fuerzas para leer el cuento? En Cuentos inteligentes pon de fondo solo el sonido de la lluvia y del bosque. A veces esta calma monótona de la naturaleza hipnotiza antes que la mejor historia.', title_fr = 'Une chambre au son de la pluie 🌧️', body_fr = 'Vous n''avez plus de voix ni la force de lire un conte ? Dans les Contes intelligents, mettez seulement en fond le son de la pluie et de la forêt. Ce calme monotone de la nature hypnotise parfois plus vite que la meilleure des histoires.', title_hi = 'बारिश की आवाज़ वाला कमरा 🌧️', body_hi = 'आवाज़ नहीं निकल रही, कहानी पढ़ने की ताकत नहीं? स्मार्ट कहानियों में बस बारिश और जंगल की आवाज़ बैकग्राउंड में चलाइए। प्रकृति की यह एक-सी शांति कभी-कभी सबसे अच्छी कहानी से भी जल्दी जादू कर देती है।', title_id = 'Kamar dengan suara hujan 🌧️', body_id = 'Suara Anda habis dan tak punya tenaga membacakan dongeng? Di Dongeng Pintar, putar saja suara hujan dan hutan sebagai latar. Ketenangan alam yang monoton ini kadang lebih cepat menghipnosis daripada cerita terbaik.', title_ja = '雨の音の部屋 🌧️', body_ja = '声が出ない、お話を読む元気がない？「スマートおはなし」で、雨と森の音だけを背景に流しましょう。単調な自然の静けさは、ときにどんなお話よりも早く眠りに誘います。', title_ko = '빗소리 가득한 방 🌧️', body_ko = '목소리도 안 나오고 동화 읽을 힘도 없나요? 스마트 동화에서 빗소리와 숲 소리만 배경으로 틀어 두세요. 자연의 이 잔잔한 고요가 때로는 최고의 이야기보다 더 빨리 최면을 걸어요.', title_nl = 'Een kamer vol regengeluid 🌧️', body_nl = 'Is je stem op en heb je geen kracht om voor te lezen? Zet in Slimme sprookjes alleen regen- en bosgeluiden op de achtergrond aan. Deze eentonige stilte van de natuur hypnotiseert soms sneller dan het beste verhaal.', title_pl = 'Pokój z odgłosem deszczu 🌧️', body_pl = 'Nie masz głosu ani siły, by czytać bajkę? Włącz w Mądrych bajkach w tle tylko szum deszczu i lasu. Ta monotonna cisza natury czasem hipnotyzuje szybciej niż najlepsza historia.', title_pt = 'Um quarto com som de chuva 🌧️', body_pt = 'Ficou sem voz e não tem forças para ler uma história? Nas Histórias Inteligentes, ponha de fundo apenas o som da chuva e da floresta. Este sossego monótono da natureza às vezes hipnotiza mais depressa do que a melhor história.', title_sv = 'Ett rum med regnljud 🌧️', body_sv = 'Har du ingen röst kvar och orkar inte läsa saga? Sätt bara på regn- och skogsljud som bakgrund i Smarta sagor. Naturens monotona stillhet hypnotiserar ibland snabbare än den bästa berättelsen.', title_vi = 'Căn phòng có tiếng mưa 🌧️', body_vi = 'Mẹ khản giọng, không còn sức đọc truyện? Trong Truyện cổ tích thông minh, chỉ cần bật tiếng mưa và tiếng rừng làm nền. Sự tĩnh lặng đều đều của thiên nhiên đôi khi "thôi miên" bé nhanh hơn cả câu chuyện hay nhất.', title_zh = '有雨声的房间 🌧️', body_zh = '嗓子哑了，没力气讲故事？在智慧童话里只把雨声和森林声当背景打开。大自然这份单调的宁静，有时比最好的故事更快让人“被催眠”。' WHERE id = 'a00b84e6-561e-4101-8d5d-a0f8a705abed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que lo llamen por el nombre que se inventa 🦇', body_es = '¿Se ha despertado, rechaza su nombre y exige «¡Llámame Batman!»? ¡Adáptate! Durante 5 minutos dile «Aquí tienes, Batman, cómete las gachas» y convierte al instante la tensión de la habitación en comedia.', title_fr = 'Se faire appeler par un nom inventé 🦇', body_fr = 'Il s''est réveillé ce matin, refuse son propre prénom et exige « Appelle-moi Batman » ? Adaptez-vous ! Pendant 5 minutes, dites « Voilà, Batman, mange ta bouillie » et transformez aussitôt la tension de la pièce en comédie.', title_hi = 'अपने गढ़े हुए नाम से बुलाया जाना 🦇', body_hi = 'सुबह उठकर अपना नाम ठुकरा दिया और माँग रखी, ‘मुझे बैटमैन बुलाओ’? ढल जाइए! 5 मिनट तक ‘लीजिए बैटमैन, अपना दलिया खाइए’ कहकर कमरे का तनाव तुरंत कॉमेडी में बदल दीजिए।', title_id = 'Dipanggil dengan nama karangannya 🦇', body_id = 'Ia bangun pagi, menolak namanya sendiri, dan menuntut ''Panggil aku Batman''? Ikuti saja! Selama 5 menit, ubah ketegangan di kamar langsung menjadi komedi dengan berkata ''Silakan, Batman, makan buburmu''.', title_ja = '自分でつけた名前で呼んで 🦇', body_ja = '朝起きて自分の名前を拒否し、「バットマンって呼んで」と言う？合わせてあげましょう！5分間「どうぞ、バットマン、おかゆをめしあがれ」と言って、部屋の緊張をすぐにコメディに変えましょう。', title_ko = '스스로 지은 이름으로 불러 줘 🦇', body_ko = '아침에 일어나 자기 이름을 거부하고 ''나를 배트맨이라고 불러''라고 하나요? 맞춰 주세요! 5분 동안 ''자, 배트맨, 죽 드세요'' 하며 방 안의 긴장을 순식간에 코미디로 바꾸세요.', title_nl = 'Genoemd worden met een zelfverzonnen naam 🦇', body_nl = 'Werd hij wakker, wil hij zijn eigen naam niet meer en eist hij: ''Noem me Batman''? Ga erin mee! Zeg 5 minuten lang ''Alsjeblieft Batman, eet je pap op'' en verander de spanning in de kamer meteen in komedie.', title_pl = 'Wymyślone imię 🦇', body_pl = 'Rano się obudził, odrzucił własne imię i zażądał: „Mów do mnie Batman”? Dostosuj się! Przez 5 minut mów: „Proszę, Batmanie, zjedz owsiankę” i od razu zamień napięcie w pokoju w komedię.', title_pt = 'Ser chamado pelo nome que inventou 🦇', body_pt = 'Acordou, recusa o próprio nome e exige "Chama-me Batman"? Entre no jogo! Durante 5 minutos diga "Aqui tens, Batman, come as tuas papas" e transforme logo a tensão do quarto em comédia.', title_sv = 'Att kallas vid ett påhittat namn 🦇', body_sv = 'Har barnet vaknat, vägrat sitt eget namn och krävt ”Kalla mig Batman”? Anpassa dig! I 5 minuter säger du ”Varsågod, Batman, ät din gröt” och förvandlar genast spänningen i rummet till komedi.', title_vi = 'Được gọi bằng tên tự đặt 🦇', body_vi = 'Sáng thức dậy, bé từ chối tên mình và đòi: "Gọi con là Batman"? Hãy hòa theo! Trong 5 phút, nói "Mời Batman ăn cháo ạ" và biến ngay căng thẳng trong phòng thành tiếng cười.', title_zh = '用自己起的名字叫我 🦇', body_zh = '早上醒来就拒绝自己的名字，要求“叫我蝙蝠侠”？配合一下！用5分钟说说“请吧，蝙蝠侠，来吃粥”，立刻把房间里的紧张变成喜剧。' WHERE id = 'a4fa9d13-3510-4b51-9dcb-583bfd5c19ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cansada de las mamás de Instagram 📱', body_es = '¡No te desanimes al abrir Instagram y ver los niños perfectos de todo el mundo! Cierra esa app y entra en la Comunidad Anacan. Verás que en todas las casas hay el mismo desorden que en la tuya: respira hondo, no estás sola.', title_fr = 'Lassée des mamans d''Instagram 📱', body_fr = 'Ne vous découragez pas en voyant les enfants parfaits de tout le monde dès que vous ouvrez Instagram ! Fermez cette appli et rejoignez la Communauté Anacan. Voyez que chez les autres aussi, la maison est sens dessus dessous, respirez profondément : vous n''êtes pas seule.', title_hi = 'इंस्टाग्राम वाली माँओं से थकान 📱', body_hi = 'इंस्टाग्राम खोलते ही सबके परफ़ेक्ट बच्चे देखकर हिम्मत मत हारिए! वह ऐप बंद कीजिए और Anacan कम्युनिटी में आइए। देखिए कि सबके घर आपके घर जैसे ही बिखरे हैं, गहरी साँस लीजिए, आप अकेली नहीं हैं।', title_id = 'Lelah dengan ibu-ibu Instagram 📱', body_id = 'Jangan patah semangat melihat anak-anak sempurna orang lain begitu membuka Instagram! Tutup aplikasinya, masuk ke Komunitas Anacan. Lihat bahwa rumah semua orang berantakan seperti rumah Anda, tarik napas dalam, Anda tidak sendirian.', title_ja = 'インスタのママたちに疲れた 📱', body_ja = 'インスタを開くたびに、みんなの完璧な子どもを見て落ちこまないで！そのアプリは閉じて、Anacanコミュニティへ。どの家もあなたの家のように散らかっているのを見て、深呼吸しましょう。ひとりじゃないよ。', title_ko = '인스타그램 엄마들에 지쳤어요 📱', body_ko = '인스타그램을 열자마자 다들 완벽한 아이만 보여서 기운 빠지나요? 그 앱은 닫고 Anacan 커뮤니티에 들어가 보세요. 다들 집이 엄마 집처럼 엉망이라는 걸 보고 깊게 숨 쉬세요. 혼자가 아니에요.', title_nl = 'Moe van Instagrammama''s 📱', body_nl = 'Raak niet ontmoedigd als je op Instagram ieders perfecte kinderen ziet! Sluit die app en ga naar de Anacan Community. Zie dat bij iedereen het huis net zo''n rommel is als bij jou, haal diep adem: je bent niet alleen.', title_pl = 'Zmęczenie mamami z Instagrama 📱', body_pl = 'Nie trać ducha, gdy tylko otworzysz Instagram i zobaczysz same idealne dzieci! Zamknij tę aplikację i wejdź do Społeczności Anacan. Zobacz, że u innych w domu jest taki sam bałagan jak u ciebie, i weź głęboki oddech, nie jesteś sama.', title_pt = 'Cansada das mães do Instagram 📱', body_pt = 'Não desanime ao ver os filhos perfeitos de toda a gente mal abre o Instagram! Feche essa app e entre na Comunidade Anacan. Ao ver que as casas dos outros estão tão desarrumadas como a sua, respire fundo: não está sozinha.', title_sv = 'Trött på Instagrammammorna 📱', body_sv = 'Bli inte nedslagen av att se allas perfekta barn så fort du öppnar Instagram! Stäng appen och gå in i Anacan Community. Se att alla andras hem är lika stökiga som ditt, andas djupt, du är inte ensam.', title_vi = 'Mệt mỏi vì các bà mẹ Instagram 📱', body_vi = 'Đừng nản lòng khi vừa mở Instagram đã thấy những đứa trẻ hoàn hảo của mọi người! Hãy đóng ứng dụng đó lại và vào Cộng đồng Anacan. Thấy nhà ai cũng bừa bộn như nhà mình, mẹ hãy hít một hơi thật sâu, mẹ không đơn độc.', title_zh = '被Instagram上的妈妈们累到了 📱', body_zh = '一打开Instagram就看到别人家完美的孩子，别灰心！关掉那个应用，来Anacan社区吧。看到大家家里都和你家一样乱，深呼吸，你不是一个人。' WHERE id = 'e5dd03b1-7179-4527-8c52-f0958fe208e9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quitarse todo el estrés con agua 🛀', body_es = 'A veces nada funciona y simplemente llora por todo. Mételo en una bañera con agua tibia. Ese efecto magnético y casi místico del agua para quitar tensión traerá al instante una gran calma a toda la habitación y a su sistema nervioso.', title_fr = 'Laver tout le stress avec de l''eau 🛀', body_fr = 'Parfois, rien ne marche, il pleure pour tout. Mettez-le dans un bain d''eau tiède. L''effet magnétique, mystique et apaisant de l''eau apportera instantanément une grande sérénité à toute la pièce et à son système nerveux.', title_hi = 'पानी से सारा तनाव धो डालना 🛀', body_hi = 'कभी-कभी कुछ भी काम नहीं करता, वह बस हर बात पर रोता है। उसे गुनगुने पानी से भरे टब में बिठाइए। पानी का वह रहस्यमयी, तनाव सोखने वाला चुंबकीय असर पूरे कमरे और उसके तंत्रिका तंत्र में तुरंत गहरा सुकून ले आएगा।', title_id = 'Membasuh semua stres dengan air 🛀', body_id = 'Kadang tak ada yang berhasil, ia hanya menangisi segalanya. Masukkan ia ke bak berisi air hangat. Efek magnet air yang misterius dan meredakan ketegangan itu akan langsung membawa ketenangan besar ke seluruh kamar dan sistem sarafnya.', title_ja = 'お湯でストレスを洗い流す 🛀', body_ja = '何をしてもうまくいかず、何にでも泣いてしまう日もあります。ぬるめのお湯をはった浴槽に入れてあげましょう。お湯のふしぎな、緊張をほぐす力が、部屋じゅうにもこの子の神経にもすぐに大きな安らぎを届けます。', title_ko = '물로 스트레스를 씻어 내요 🛀', body_ko = '가끔은 아무것도 통하지 않고 아이가 모든 일에 울기만 하죠. 미지근한 물을 채운 욕조에 넣어 주세요. 긴장을 풀어 주는 물의 신비한 자석 같은 효과가 방 전체와 아이의 신경계에 금세 큰 평온을 가져다줄 거예요.', title_nl = 'Alle stress wegspoelen met water 🛀', body_nl = 'Soms werkt niets en huilt hij gewoon om alles. Zet hem in een bad met lauw water. Het mystieke, spanning verlagende, magnetische effect van water brengt meteen grote rust in de hele kamer en in zijn zenuwstelsel.', title_pl = 'Zmyć wodą cały stres 🛀', body_pl = 'Czasem nic nie działa, on po prostu płacze o wszystko. Włóż go do wanny z ciepłą wodą. Tajemniczy, kojący, magnetyczny efekt wody od razu przyniesie wielki spokój całemu pokojowi i jego układowi nerwowemu.', title_pt = 'Lavar todo o stress com água 🛀', body_pt = 'Às vezes nada resulta e ele chora por tudo. Ponha-o na banheira com água morna. O efeito magnético e místico da água, que alivia a tensão, vai trazer logo uma grande paz a todo o quarto e ao sistema nervoso dele.', title_sv = 'Skölj bort all stress med vatten 🛀', body_sv = 'Ibland fungerar ingenting, barnet gråter bara över allt. Lägg barnet i ett badkar med ljummet vatten. Vattnets mystiska, spänningsdämpande magnetiska effekt ger genast ett stort lugn i hela rummet och i barnets nervsystem.', title_vi = 'Gột rửa mọi căng thẳng bằng nước 🛀', body_vi = 'Đôi khi chẳng có gì hiệu quả, bé cứ khóc vì mọi thứ. Hãy cho bé vào bồn nước ấm. Sức hút kỳ diệu, xua tan căng thẳng của nước sẽ ngay lập tức mang lại sự bình yên lớn cho cả căn phòng và hệ thần kinh của bé.', title_zh = '用水洗去所有压力 🛀', body_zh = '有时候什么都不管用，宝宝对什么都哭。把宝宝放进装满温水的浴缸。水那种神奇、能化解紧张的“磁力”，会立刻给整个房间和宝宝的神经系统带来平静。' WHERE id = '17e2ffec-fd31-4ab8-8917-684e3ceaaff9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vete, no te quiero 💔', body_es = '¿Te ha dicho «¡Eres una mamá mala, vete!» porque le has dicho que no? Te ha dolido el corazón. Pero todavía no sabe convertir su rabia en palabras: en realidad te está diciendo «estoy decepcionado». No te lo tomes como algo personal, solo abrázalo con amor.', title_fr = 'Va-t''en, je veux pas de toi 💔', body_fr = 'Parce que vous avez refusé ce qu''il voulait, il vous a dit « T''es une méchante maman, va-t''en ! » ? Votre cœur s''est serré. Mais il ne sait pas encore mettre sa colère en mots : en réalité, il dit « Je suis déçu ». Ne le prenez pas personnellement, serrez-le simplement contre vous avec amour.', title_hi = 'जाओ, मुझे तुम नहीं चाहिए 💔', body_hi = 'आपने उसकी बात नहीं मानी, तो बोला, ‘तुम बुरी माँ हो, जाओ!’? दिल में चुभन हुई। पर वह अभी अपने गुस्से को शब्दों में नहीं ढाल पाता, असल में वह कह रहा है, ‘मैं निराश हूँ।’ इसे दिल पर मत लीजिए, बस प्यार से गले लगा लीजिए।', title_id = 'Pergi, aku nggak mau Mama 💔', body_id = 'Karena Anda menolak permintaannya, ia berkata ''Mama jahat, pergi!''? Hati Anda terasa perih. Tapi ia belum bisa mengubah amarahnya menjadi kata-kata, sebenarnya ia sedang bilang ''aku kecewa''. Jangan dimasukkan ke hati, cukup peluk ia dengan penuh cinta.', title_ja = 'あっち行って、ママなんかいらない 💔', body_ja = 'ほしいものをだめと言ったら「ママなんか悪いママ、あっち行って！」？胸がちくっとしますね。でも、まだ怒りをことばにできなくて、本当は「がっかりした」と言っているんです。本気で受けとらず、ただ愛情こめて抱きしめてあげて。', title_ko = '저리 가, 엄마 싫어 💔', body_ko = '원하는 걸 안 들어줬다고 ''엄마 나빠, 저리 가!''라고 했나요? 가슴이 철렁했죠. 하지만 아직 화를 말로 바꾸는 법을 몰라서, 사실은 ''나 실망했어''라고 말하는 거예요. 상처로 받아들이지 말고 그저 사랑으로 안아 주세요.', title_nl = 'Ga weg, ik wil jou niet 💔', body_nl = 'Zei hij ''Jij bent een stomme mama, ga weg!'' omdat je zijn wens weigerde? Dat steekt. Maar hij kan zijn boosheid nog niet in woorden vatten, eigenlijk zegt hij: ''Ik ben teleurgesteld.'' Neem het niet persoonlijk, sla gewoon liefdevol je armen om hem heen.', title_pl = 'Idź sobie, nie chcę cię 💔', body_pl = 'Powiedział ci „Jesteś złą mamą, idź sobie!”, bo odmówiłaś mu czegoś? Zakłuło cię w sercu. Ale on jeszcze nie umie przełożyć złości na słowa, tak naprawdę mówi „jestem rozczarowany”. Nie bierz tego do siebie, po prostu przytul go z miłością.', title_pt = 'Vai-te embora, não te quero 💔', body_pt = 'Disse-lhe "És uma mãe má, vai-te embora!" porque recusou o que ele queria? Doeu-lhe o coração. Mas ele ainda não consegue pôr a raiva em palavras: na verdade está a dizer "fiquei desiludido". Não leve a peito, abrace-o com amor.', title_sv = 'Gå, jag vill inte ha dig 💔', body_sv = 'Sa barnet ”Du är en dålig mamma, gå!” för att du sa nej till det hen ville? Det högg till i hjärtat. Men barnet kan ännu inte sätta ord på sin ilska, egentligen säger hen ”jag blev besviken”. Ta det inte personligt, krama bara med kärlek.', title_vi = 'Mẹ đi đi, con không cần mẹ 💔', body_vi = 'Vì mẹ không chiều theo ý, bé nói: "Mẹ xấu lắm, mẹ đi đi!"? Tim mẹ nhói đau. Nhưng bé chưa biết biến cơn giận thành lời, thật ra bé đang nói "Con thất vọng quá". Đừng để bụng, chỉ cần ôm bé thật yêu thương.', title_zh = '走开，我不要你 💔', body_zh = '因为你拒绝了宝宝的要求，宝宝对你说“你是坏妈妈，走开！”？心里一阵刺痛。可宝宝还不会把愤怒变成准确的词语，其实是在说“我很失望”。别往心里去，带着爱抱抱宝宝吧。' WHERE id = 'd1311034-b416-403f-a981-34577f22c978' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del té con el amigo invisible 🫖', body_es = '¿Sirve té en el aire en un rincón de la habitación y se ríe? ¡Llega la etapa del amigo imaginario!', title_fr = 'L''heure du thé avec l''ami invisible 🫖', body_fr = 'Dans un coin de la chambre, il sert du thé dans le vide et rit ? La période de l''ami imaginaire se développe !', title_hi = 'अदृश्य दोस्त के साथ चाय का वक्त 🫖', body_hi = 'कमरे के कोने में खाली जगह में चाय डालकर हँसता है? काल्पनिक दोस्त वाला दौर आगे बढ़ रहा है!', title_id = 'Minum teh bersama teman tak kasatmata 🫖', body_id = 'Ia menuang teh ke udara kosong di sudut kamar sambil tertawa? Masa teman khayalan sedang berkembang!', title_ja = '見えないお友だちとお茶の時間 🫖', body_ja = '部屋のすみで、何もないところにお茶を注いで笑っている？空想のお友だちの時期が育っています！', title_ko = '보이지 않는 친구와 티타임 🫖', body_ko = '방 한쪽 빈 공간에 차를 따르며 웃고 있나요? 상상 친구 시기가 자라나고 있어요!', title_nl = 'Theetijd met een onzichtbare vriend 🫖', body_nl = 'Schenkt hij in een hoek van de kamer thee in de lucht en lacht hij? De fase van het denkbeeldige vriendje is begonnen!', title_pl = 'Herbatka z niewidzialnym przyjacielem 🫖', body_pl = 'W kącie pokoju nalewa herbatę w powietrze i się śmieje? Rozwija się etap wymyślonego przyjaciela!', title_pt = 'Hora do chá com um amigo invisível 🫖', body_pt = 'Num canto do quarto, serve chá ao vazio e ri-se? A fase do amigo imaginário está a desenvolver-se!', title_sv = 'Tebjudning med en osynlig vän 🫖', body_sv = 'Häller barnet upp te i tomma luften i ett hörn av rummet och skrattar? Perioden med låtsaskompisar utvecklas!', title_vi = 'Giờ uống trà với người bạn vô hình 🫖', body_vi = 'Bé rót trà vào khoảng không ở góc phòng và cười khúc khích? Giai đoạn "bạn tưởng tượng" đang phát triển!', title_zh = '和看不见的朋友喝下午茶 🫖', body_zh = '在房间角落往空气里倒茶，还咯咯笑？想象中的朋友阶段正在发展！' WHERE id = 'e3289711-a700-447f-9c8d-d0e1b469b80e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento que papá lee mal 📖', body_es = 'Esta noche dale el libro de cuentos a papá. Que cuente la historia al revés a propósito, de forma graciosa y absurda. Disfruta viendo desde fuera cómo el peque se lo pasa en grande corrigiéndolo y se ríe a carcajadas.', title_fr = 'Le conte que papa lit de travers 📖', body_fr = 'Ce soir, donnez le livre de contes à papa. Qu''il raconte l''histoire exprès à l''envers, de façon drôle et absurde. Regardez de loin, avec délice, l''enfant prendre plaisir à le corriger et éclater de rire.', title_hi = 'पापा की गलत पढ़ी कहानी 📖', body_hi = 'आज शाम कहानी की किताब पापा को दीजिए। पापा कहानी जानबूझकर उल्टी, मज़ेदार और बेतुके ढंग से सुनाएँ। किनारे से मज़े लेकर देखिए कि बच्चा उन्हें ठीक करने में कितना आनंद लेता है और ठहाके लगाता है।', title_id = 'Dongeng yang salah dibacakan Ayah 📖', body_id = 'Malam ini serahkan buku dongeng kepada Ayah. Biarkan Ayah sengaja menceritakan kisahnya terbalik, lucu, dan absurd. Nikmati dari samping betapa senangnya anak membetulkannya sambil tertawa terbahak-bahak.', title_ja = 'パパがまちがえて読むお話 📖', body_ja = '今夜は絵本をパパに渡しましょう。パパにわざとお話をあべこべに、おかしくめちゃくちゃに話してもらって。子どもが楽しそうに直して大笑いするのを、そばでゆっくり眺めましょう。', title_ko = '아빠가 틀리게 읽는 동화 📖', body_ko = '오늘 저녁엔 동화책을 아빠에게 넘기세요. 아빠가 일부러 이야기를 거꾸로, 우스꽝스럽고 엉뚱하게 들려주게 하세요. 아이가 아빠를 고쳐 주며 깔깔 웃는 모습을 옆에서 즐겁게 지켜보세요.', title_nl = 'Het sprookje dat papa verkeerd voorleest 📖', body_nl = 'Geef vanavond het sprookjesboek aan papa. Laat hem het verhaal expres verkeerd om, grappig en absurd vertellen. Kijk genietend toe hoe je kind het met plezier verbetert en het uitschatert.', title_pl = 'Bajka czytana przez tatę na opak 📖', body_pl = 'Dziś wieczorem oddaj książkę z bajkami tacie. Niech celowo opowiada historię na opak, zabawnie i absurdalnie. Z przyjemnością przyglądaj się z boku, jak dziecko z frajdą go poprawia i zanosi się śmiechem.', title_pt = 'A história que o pai lê mal 📖', body_pt = 'Esta noite, dê o livro de histórias ao pai. Que ele conte a história de propósito ao contrário, de forma cómica e absurda. Observe com prazer, à distância, como a criança adora corrigi-lo e se ri às gargalhadas.', title_sv = 'Sagan som pappa läser fel 📖', body_sv = 'Ge sagoboken till pappa i kväll. Låt honom berätta historien med flit bakvänt, roligt och absurt. Njut från sidan av hur barnet älskar att rätta honom och skrattar högt.', title_vi = 'Câu chuyện bố đọc sai 📖', body_vi = 'Tối nay hãy đưa cuốn truyện cho bố. Để bố cố tình kể ngược, kể thật buồn cười và vô lý. Rồi đứng ngoài thích thú ngắm bé say sưa sửa lời bố và cười khanh khách.', title_zh = '爸爸读错的故事 📖', body_zh = '今晚把故事书交给爸爸。让爸爸故意把故事讲反、讲得又搞笑又荒诞。在一旁好好欣赏宝宝纠正爸爸时那副得意、哈哈大笑的样子吧。' WHERE id = '05726924-8563-423e-bd0f-f5be06f1d806' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pilla-pilla de buena mañana 🏃‍♂️', body_es = '¿A las 7 de la mañana corre por encima de los sofás? No grites. Deja lo que estás haciendo 2 minutos y únete dando saltos. Entrar en su mundo imaginario es, en realidad, una forma curiosa de soltar estrés también para ti.', title_fr = 'Chat perché dès le matin 🏃‍♂️', body_fr = 'À 7 heures du matin, il court sur les canapés ? Ne criez pas. Lâchez tout pendant 2 minutes et rejoignez-le en sautant vous aussi. Entrer dans le monde imaginaire de l''enfant est en fait, pour vous aussi, une drôle de façon d''évacuer le stress.', title_hi = 'सुबह-सुबह पकड़म-पकड़ाई 🏃‍♂️', body_hi = 'सुबह 7 बजे सोफ़ों पर दौड़ रहा है? चिल्लाइए मत। अपने काम 2 मिनट के लिए छोड़कर आप भी उछलते हुए साथ आ जाइए। बच्चे की कल्पना की दुनिया में शामिल होना असल में आपके लिए भी तनाव उतारने का एक अनोखा तरीका है।', title_id = 'Kejar-kejaran pagi-pagi 🏃‍♂️', body_id = 'Jam 7 pagi ia berlarian di atas sofa? Jangan berteriak. Tinggalkan urusan Anda selama 2 menit dan ikutlah melompat bersamanya. Masuk ke dunia khayal anak sebenarnya juga cara unik melepas stres bagi Anda.', title_ja = '朝からおにごっこ 🏃‍♂️', body_ja = '朝7時にソファの上を走りまわっている？叫ばないで。2分だけ手を止めて、あなたも飛びはねて仲間入りしましょう。子どもの空想の世界に入るのは、あなたにとってもふしぎなストレス解消法です。', title_ko = '이른 아침 술래잡기 🏃‍♂️', body_ko = '아침 7시에 소파 위를 뛰어다니나요? 소리치지 마세요. 하던 일을 2분만 내려놓고 엄마도 폴짝폴짝 뛰며 함께하세요. 아이의 상상 세계에 들어가는 건 사실 엄마에게도 색다른 스트레스 해소법이에요.', title_nl = 'Tikkertje in de vroege ochtend 🏃‍♂️', body_nl = 'Rent hij om 7 uur ''s ochtends over de banken? Ga niet schreeuwen. Laat je klusjes 2 minuten liggen en spring gewoon mee. Meegaan in de fantasiewereld van je kind is eigenlijk ook voor jou een vreemd fijne manier om stress kwijt te raken.', title_pl = 'Berek od samego rana 🏃‍♂️', body_pl = 'O 7 rano biega po kanapach? Nie krzycz. Rzuć swoje sprawy na 2 minuty i dołącz do niego, skacząc. Wejście w świat wyobraźni dziecka to tak naprawdę także dla ciebie zaskakujący sposób na odstresowanie.', title_pt = 'Apanhada logo de manhã cedo 🏃‍♂️', body_pt = 'Às 7 da manhã corre por cima dos sofás? Não grite. Largue as tarefas por 2 minutos e junte-se a ele aos saltos. Entrar no mundo de fantasia da criança é, na verdade, uma forma estranha de também libertar o seu stress.', title_sv = 'Kull tidigt på morgonen 🏃‍♂️', body_sv = 'Springer barnet över sofforna klockan 7 på morgonen? Skrik inte. Släpp det du gör i 2 minuter och hoppa med. Att gå in i barnets fantasivärld är faktiskt ett märkligt sätt att släppa stress för dig också.', title_vi = 'Trò đuổi bắt từ sáng sớm 🏃‍♂️', body_vi = '7 giờ sáng bé đã chạy nhảy trên sofa? Đừng quát. Bỏ việc xuống 2 phút và nhảy cùng bé. Hòa vào thế giới tưởng tượng của bé thật ra cũng là một cách xả stress kỳ lạ cho chính mẹ.', title_zh = '一大早的你追我跑 🏃‍♂️', body_zh = '早上7点就在沙发上跑来跑去？别吼。放下手头的事2分钟，你也跳着加入吧。走进孩子的想象世界，其实对你来说也是一种奇妙的解压方式。' WHERE id = '1b87ed18-3cf6-4e93-88b1-58f24b42513f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inquietud por un tartamudeo repentino 🤖', body_es = '¿El tartamudeo repentino de tu peque te ha hecho buscar enfermedades en internet? ¡Para! Descubre con Anacan AI que es un salto del desarrollo de los 4 años y apaga el pánico.', title_fr = 'Panique face à un bégaiement soudain 🤖', body_fr = 'Le bégaiement soudain de votre enfant vous a poussée à chercher des maladies sur Internet ? Stop ! Découvrez avec Anacan AI qu''il s''agit d''un bond de développement des 4 ans, et la panique retombera.', title_hi = 'अचानक हकलाने की घबराहट 🤖', body_hi = 'बच्चे के अचानक हकलाने ने आपको इंटरनेट पर बीमारियाँ ढूँढने पर मजबूर कर दिया? रुकिए! Anacan AI से जानिए कि यह 4 साल वाली विकास की छलांग है, और घबराहट शांत कीजिए।', title_id = 'Panik karena gagap mendadak 🤖', body_id = 'Gagap yang tiba-tiba muncul pada anak membuat Anda mencari-cari penyakit di internet? Berhenti! Pelajari dari Anacan AI bahwa ini lompatan perkembangan usia 4 tahun, dan padamkan kepanikan Anda.', title_ja = '急などもりにドキッ 🤖', body_ja = '急に始まったどもりが心配で、ネットで病気を検索しそう？ストップ！Anacan AIに聞いて、これが4歳の発達のジャンプだと知り、パニックをしずめましょう。', title_ko = '갑작스러운 말더듬에 놀랐을 때 🤖', body_ko = '아이가 갑자기 말을 더듬기 시작해서 인터넷에서 병을 찾아보게 됐나요? 멈추세요! Anacan AI에게 물어 이것이 4세 발달 도약이라는 걸 알고 불안을 내려놓으세요.', title_nl = 'Paniek om plotseling stotteren 🤖', body_nl = 'Ben je door het plotselinge stotteren van je kind online naar ziektes gaan zoeken? Stop! Ontdek via Anacan AI dat dit een ontwikkelingssprong rond 4 jaar is en laat je paniek los.', title_pl = 'Niepokój o nagłe jąkanie 🤖', body_pl = 'Nagłe jąkanie dziecka sprawiło, że zaczęłaś szukać chorób w internecie? Stop! Dowiedz się od Anacan AI, że to skok rozwojowy 4-latka, i ugaś panikę.', title_pt = 'A aflição da gaguez repentina 🤖', body_pt = 'A gaguez que apareceu de repente levou-a a procurar doenças na internet? Pare! Descubra com o Anacan AI que é um salto de desenvolvimento dos 4 anos e apague o pânico.', title_sv = 'Oro över plötslig stamning 🤖', body_sv = 'Fick barnets plötsliga stamning dig att söka efter sjukdomar på nätet? Stopp! Fråga Anacan AI, få veta att det är ett utvecklingssprång vid 4 år och släck paniken.', title_vi = 'Lo lắng vì bé bỗng nói lắp 🤖', body_vi = 'Việc bé bỗng dưng nói lắp khiến mẹ lên mạng tìm bệnh? Dừng lại! Hãy hỏi Anacan AI để biết đây là bước nhảy vọt phát triển của tuổi lên 4, và dập tắt sự hoảng hốt.', title_zh = '突然口吃的慌张 🤖', body_zh = '孩子突然开始口吃，让你忍不住上网查病？停一停！问问Anacan AI，了解这是4岁的成长飞跃，平息你的恐慌吧。' WHERE id = '9c4135ea-bc1e-4450-aea1-64dfec877859' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El número del silencio en la pantalla 📉', body_es = 'Por fin se ha dormido. ¿Hay tanto silencio en casa que te pitan los oídos? Abre el Medidor de sonido en la app. Ver ese 0 decibelios será el mejor masaje visual del mundo para tu cerebro cansado y saturado de ruido.', title_fr = 'Le chiffre du silence à l''écran 📉', body_fr = 'Il dort enfin. Un tel silence est tombé sur la maison que vos oreilles bourdonnent ? Ouvrez le Sonomètre dans l''application. Voir afficher 0 décibel sera le meilleur massage visuel au monde pour votre cerveau fatigué, saturé de bruit.', title_hi = 'स्क्रीन पर खामोशी का आँकड़ा 📉', body_hi = 'आखिरकार सो गया। घर में ऐसा सन्नाटा छा गया कि कानों में सीटी सी बज रही है? ऐप में साउंड मीटर खोलिए। वह ‘0 डेसिबल’ देखना आपके थके, शोर से भरे दिमाग के लिए दुनिया की सबसे अच्छी विज़ुअल मसाज होगी।', title_id = 'Angka keheningan di layar 📉', body_id = 'Akhirnya ia tidur. Rumah begitu hening sampai telinga Anda berdenging? Buka Pengukur Suara di aplikasi. Melihat tulisan 0 desibel itu akan menjadi pijatan visual terbaik di dunia untuk otak Anda yang lelah dan penuh kebisingan.', title_ja = '静けさを示す画面の数字 📉', body_ja = 'やっと寝てくれた。家が静かすぎて耳鳴りがする？アプリで「サウンドメーター」を開いてみて。0デシベルの表示を見ることが、疲れて騒音でいっぱいの頭にとって、世界一の目のマッサージになります。', title_ko = '화면 속 고요의 숫자 📉', body_ko = '드디어 잠들었어요. 집이 너무 고요해져 귀가 울릴 정도인가요? 앱에서 소음 측정기를 열어 보세요. 0 데시벨이라는 숫자를 보는 것만으로 소음에 지친 머리에 세상에서 가장 좋은 시각적 마사지가 될 거예요.', title_nl = 'Stilte in cijfers op het scherm 📉', body_nl = 'Eindelijk slaapt hij. Is het zo stil in huis dat je oren suizen? Open de Geluidsmeter in de app. Kijken naar die 0 decibel is de beste visuele massage voor je vermoeide, door lawaai overprikkelde brein.', title_pl = 'Cisza w liczbach na ekranie 📉', body_pl = 'Wreszcie zasnął. W domu zapadła taka cisza, że aż dzwoni ci w uszach? Otwórz w aplikacji Miernik dźwięku. Widok napisu 0 decybeli będzie dla twojego zmęczonego, przeładowanego hałasem mózgu najlepszym wizualnym masażem na świecie.', title_pt = 'O número do silêncio no ecrã 📉', body_pt = 'Finalmente adormeceu. Caiu um silêncio tão grande na casa que lhe zumbem os ouvidos? Abra o Medidor de Som na app. Olhar para aqueles 0 decibéis será a melhor massagem visual do mundo para o seu cérebro cansado e inchado de barulho.', title_sv = 'Tystnaden i siffror på skärmen 📉', body_sv = 'Äntligen sover barnet. Det har blivit så tyst hemma att det ringer i öronen? Öppna Ljudmätaren i appen. Att titta på 0 decibel blir världens bästa visuella massage för din trötta, bullerfyllda hjärna.', title_vi = 'Con số của sự im lặng trên màn hình 📉', body_vi = 'Cuối cùng bé cũng ngủ. Nhà yên tĩnh đến mức tai mẹ ù đi? Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số 0 decibel sẽ là màn mát-xa thị giác tuyệt vời nhất cho bộ não mệt mỏi, căng thẳng vì tiếng ồn của mẹ.', title_zh = '屏幕上的安静数字 📉', body_zh = '终于睡着了。家里安静得让你耳朵都嗡嗡响？打开应用里的分贝仪。看着那个0分贝，对你疲惫、被噪音塞满的大脑来说，就是世界上最好的视觉按摩。' WHERE id = '15bb2b6b-7a84-4331-86dd-6aee2aba5539' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de «has pelado tú el plátano» 🍌', body_es = '¿Se ha armado una revolución porque el plátano lo has pelado tú? La regla de oro de esta edad: todo lo tiene que decidir él. No puedes volver a pegar el plátano: dale otro y deja que lo pele como quiera, para no herir su independencia.', title_fr = 'La dispute du « C''est toi qui as épluché la banane » 🍌', body_fr = 'C''est la révolution dans la pièce parce que c''est vous qui avez épluché la banane ? La règle d''or de cet âge : c''est lui qui doit tout décider. Vous ne pourrez pas recoller la banane : donnez-en une nouvelle et laissez-le l''éplucher comme il veut, pour ne pas froisser son indépendance.', title_hi = '‘केला तुमने छीला’ वाला झगड़ा 🍌', body_hi = 'केला आपने छीला, इसलिए कमरे में क्रांति आ गई? इस उम्र का सुनहरा नियम: हर बात का फ़ैसला उसे करना है। केला वापस नहीं जोड़ सकतीं, नया केला दीजिए, उसे जैसे चाहे छीलने दीजिए, ताकि उसकी आत्मनिर्भरता को ठेस न लगे।', title_id = 'Perkara ''Mama yang kupas pisangnya'' 🍌', body_id = 'Revolusi meletus di kamar karena Anda yang mengupas pisangnya? Aturan emas usia ini: semuanya harus ia yang putuskan. Pisang tidak bisa ditempel lagi, beri pisang baru, biarkan ia mengupas sesuai keinginannya, supaya kemandiriannya tidak terluka.', title_ja = 'ママがバナナをむいたけんか 🍌', body_ja = 'あなたがバナナをむいたから大さわぎ？この年齢の黄金のルールは「何でも自分で決めたい」。バナナは元に戻せません。新しいバナナを渡して、好きなようにむかせてあげましょう。自立心を傷つけないで。', title_ko = '''엄마가 바나나 깠잖아'' 소동 🍌', body_ko = '엄마가 바나나를 깠다고 방에 혁명이 일어났나요? 이 나이의 황금률: 모든 건 아이가 정해야 해요. 바나나를 다시 붙일 순 없으니 새 바나나를 주고 원하는 대로 까게 두세요. 독립심이 다치지 않게요.', title_nl = 'Het ''jij hebt de banaan gepeld''-drama 🍌', body_nl = 'Breekt er een revolutie uit omdat jij de banaan pelde? De gouden regel van deze leeftijd: hij moet over alles zelf beslissen. Je kunt de schil er niet weer omheen plakken, geef een nieuwe banaan en laat hem die pellen zoals hij wil, zodat zijn zelfstandigheid niet gekrenkt wordt.', title_pl = 'Awantura „to ty obrałaś banana” 🍌', body_pl = 'W pokoju wybuchła rewolucja, bo to ty obrałaś banana? Złota zasada tego wieku: o wszystkim musi decydować on. Banana nie skleisz z powrotem, daj nowego i niech obierze go sam, jak chce, żeby nie ucierpiała jego samodzielność.', title_pt = 'A guerra do "foste tu que descascaste a banana" 🍌', body_pt = 'Houve uma revolução no quarto porque foi a mãe a descascar a banana? A regra de ouro desta idade: é ele que tem de decidir tudo. Não consegue voltar a colar a banana, por isso dê-lhe uma nova e deixe-o descascá-la como quiser, para não ferir a independência dele.', title_sv = 'Bråket om att du skalade bananen 🍌', body_sv = 'Blev det revolution i rummet för att du skalade bananen? Den här ålderns gyllene regel: barnet ska bestämma allt. Du kan inte sätta ihop bananen igen, ge en ny banan och låt barnet skala den som hen vill, så att självständigheten inte tar skada.', title_vi = 'Cuộc chiến "Mẹ bóc chuối" 🍌', body_vi = 'Cả phòng nổi loạn chỉ vì mẹ bóc chuối? Quy tắc vàng của tuổi này: mọi thứ đều phải do bé quyết định. Mẹ không thể dán vỏ chuối lại, hãy đưa quả mới và để bé tự bóc theo ý mình, để sự tự lập của bé không bị tổn thương.', title_zh = '“香蕉是你剥的”之争 🍌', body_zh = '因为香蕉是你剥的，房间里就闹起了革命？这个年龄的黄金法则：什么都得宝宝自己决定。香蕉粘不回去了，再给一根新的，让宝宝按自己想要的方式剥，别伤了宝宝的独立心。' WHERE id = '21cfa5ea-471d-459d-a626-6d4be6cf6e4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equilibrista en el bordillo 🧱', body_es = '¿De camino al parque no quiere ir por el camino recto, sino sí o sí por el borde más estrecho de la acera? Sujétalo del brazo y deja que conquiste esta pequeña cumbre. El equilibrio y la autoestima se desarrollan a la vez de forma perfecta.', title_fr = 'Funambule sur le bord du trottoir 🧱', body_fr = 'En allant au parc, il veut absolument marcher non pas sur le chemin, mais sur le rebord le plus étroit du trottoir ? Assurez-le en lui tenant le bras et laissez-le conquérir ce petit sommet. L''équilibre et la confiance en soi se développent parfaitement en même temps.', title_hi = 'फ़ुटपाथ के किनारे पर रस्सी वाला नट 🧱', body_hi = 'पार्क जाते समय सीधे रास्ते से नहीं, फ़ुटपाथ के सबसे पतले किनारे पर ही चलना चाहता है? हाथ पकड़कर सहारा दीजिए, उसे यह छोटी सी चोटी फ़तह करने दीजिए। संतुलन और आत्मविश्वास एक साथ शानदार ढंग से बढ़ते हैं।', title_id = 'Pemain akrobat tali di tepi trotoar 🧱', body_id = 'Saat ke taman, ia tidak mau lewat jalan biasa dan bersikeras berjalan di tepi trotoar yang paling sempit? Pegangi lengannya untuk berjaga-jaga, biarkan ia menaklukkan puncak kecil ini. Keseimbangan dan rasa percaya dirinya berkembang sempurna sekaligus.', title_ja = '歩道のふちで綱わたり 🧱', body_ja = '公園へ行くとき、まっすぐな道ではなく、歩道のいちばんせまいふちを歩きたがる？腕を支えて、この小さな頂上を制覇させてあげましょう。バランス感覚と自信が同時にぐんぐん育ちます。', title_ko = '보도 끝의 줄타기 곡예사 🧱', body_ko = '공원에 가는 길에 평평한 길이 아니라 꼭 보도 가장 좁은 가장자리로 걷고 싶어 하나요? 팔을 잡아 안전을 지켜 주고 이 작은 정상을 정복하게 두세요. 균형 감각과 자신감이 동시에 쑥쑥 자라요.', title_nl = 'Koorddansen op de stoeprand 🧱', body_nl = 'Wil hij op weg naar het park niet over het pad, maar per se over het smalste randje van de stoep lopen? Houd zijn arm vast voor de veiligheid en laat hem deze kleine top veroveren. Evenwicht en zelfvertrouwen ontwikkelen zich zo tegelijk perfect.', title_pl = 'Linoskoczek na krawężniku 🧱', body_pl = 'W drodze do parku nie chce iść prosto, tylko koniecznie po najwęższej krawędzi krawężnika? Asekuruj go za rękę i pozwól zdobyć ten mały szczyt. Równowaga i pewność siebie rozwijają się jednocześnie wspaniale.', title_pt = 'Equilibrista na beira do passeio 🧱', body_pt = 'A caminho do parque, não quer ir pelo caminho direito, mas sim pela beira mais estreita do passeio? Segure-o pelo braço e deixe-o conquistar este pequeno cume. O equilíbrio e a autoconfiança desenvolvem-se na perfeição ao mesmo tempo.', title_sv = 'Lindansare på trottoarkanten 🧱', body_sv = 'Vill barnet på väg till parken inte gå rakt fram, utan absolut balansera på den smalaste trottoarkanten? Säkra barnet i armen och låt hen erövra den lilla toppen. Balans och självförtroende utvecklas samtidigt.', title_vi = 'Đi dây trên mép vỉa hè 🧱', body_vi = 'Trên đường ra công viên, bé không đi đường thẳng mà nhất định đi trên mép hẹp nhất của vỉa hè? Hãy đỡ tay bé cho an toàn và để bé chinh phục "đỉnh núi" nhỏ này. Khả năng giữ thăng bằng và sự tự tin đang cùng lúc phát triển tuyệt vời.', title_zh = '马路牙子上的走钢丝 🧱', body_zh = '去公园的路上不走平路，非要沿着人行道最窄的边走？扶好宝宝的胳膊，让宝宝征服这座小小的“山峰”吧。平衡感和自信心会同时完美地发展。' WHERE id = 'e6cc1e43-997c-46d7-a69b-a71076271387' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedicarte tiempo no es pecado 🥗', body_es = 'Has montado menús distintos para darle de comer, ¿y tú qué has comido? Hazte esa ensalada fácil de 5 minutos para mamás de Recetas saludables y no olvides por fin recargarte.', title_fr = 'Prendre du temps pour soi n''est pas un péché 🥗', body_fr = 'Vous avez imaginé différents menus pour le nourrir, mais vous, qu''avez-vous mangé ? Faites la salade facile en 5 minutes pour les mamans des Recettes saines, et n''oubliez pas enfin de vous recharger.', title_hi = 'अपने लिए समय निकालना गलत नहीं 🥗', body_hi = 'उसे खिलाने के लिए तरह-तरह के मेन्यू बनाए, पर आपने क्या खाया? सेहतमंद रेसिपी में माँओं के लिए वाला 5 मिनट का आसान सलाद बनाइए, और खुद को चार्ज करना मत भूलिए।', title_id = 'Meluangkan waktu untuk diri sendiri bukan dosa 🥗', body_id = 'Anda menyusun berbagai menu untuk memberinya makan, lalu Anda sendiri makan apa? Buat salad 5 menit yang mudah untuk ibu dari Resep Sehat, dan akhirnya jangan lupa mengisi ulang tenaga Anda.', title_ja = '自分の時間は悪いことじゃない 🥗', body_ja = 'この子に食べさせるためにいろいろな献立を考えたけれど、あなたは何を食べた？「ヘルシーレシピ」にあるママ向けの簡単5分サラダをつくって、自分の充電も忘れないで。', title_ko = '나를 위한 시간은 죄가 아니에요 🥗', body_ko = '아이를 먹이려고 여러 메뉴를 고민했는데 정작 엄마는 뭘 먹었나요? 건강한 레시피에 있는 엄마를 위한 간단한 5분 샐러드를 만들어, 나 자신을 충전하는 걸 잊지 마세요.', title_nl = 'Tijd voor jezelf is geen zonde 🥗', body_nl = 'Je hebt allerlei menu''s bedacht om hem te laten eten, maar wat heb jij gegeten? Maak die makkelijke salade van 5 minuten voor mama''s uit Gezonde recepten en vergeet niet eindelijk jezelf op te laden.', title_pl = 'Czas dla siebie to nie grzech 🥗', body_pl = 'Wymyślasz różne menu, żeby go nakarmić, a co ty zjadłaś? Zrób ze Zdrowych przepisów tę łatwą 5-minutową sałatkę dla mam i w końcu nie zapomnij się naładować.', title_pt = 'Ter tempo para si não é pecado 🥗', body_pt = 'Inventou menus diferentes para ele comer, mas e a mãe, o que comeu? Faça aquela salada fácil de 5 minutos para mães das Receitas Saudáveis e não se esqueça, finalmente, de carregar as suas baterias.', title_sv = 'Det är ingen synd att ta tid för sig själv 🥗', body_sv = 'Du gjorde olika menyer för att få barnet att äta, men vad åt du själv? Gör den enkla 5-minuterssalladen för mammor i Hälsosamma recept och glöm inte att äntligen ladda dig själv.', title_vi = 'Dành thời gian cho bản thân không có gì sai 🥗', body_vi = 'Mẹ đã lên đủ thực đơn để bé ăn, còn mẹ đã ăn gì chưa? Hãy làm món salad 5 phút dễ dàng dành cho mẹ trong Công thức lành mạnh, và cuối cùng, đừng quên "sạc pin" cho chính mình.', title_zh = '给自己留时间不是罪过 🥗', body_zh = '为了喂宝宝想了好几种菜单，那你自己吃了什么？在健康食谱里做一份给妈妈的5分钟简单沙拉，别再忘了给自己充电。' WHERE id = '6daea202-5e39-49bd-9344-4fdbc59064e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una mirada en silencio 🥂', body_es = 'El peque duerme. Tu pareja y tú os miráis en silencio en el sofá. No decís nada. En realidad, este silencio es la forma más romántica y sincera de decir «esto también lo hemos conseguido, somos un gran equipo».', title_fr = 'Un regard silencieux l''un vers l''autre 🥂', body_fr = 'L''enfant dort. Votre partenaire et vous vous regardez en silence sur le canapé. Vous ne dites rien. Ce silence est en fait la façon la plus romantique et la plus sincère de dire « On y est encore arrivés, on forme une super équipe ».', title_hi = 'एक-दूसरे पर खामोश नज़र 🥂', body_hi = 'बच्चा सो गया। आप और आपका साथी सोफ़े पर चुपचाप एक-दूसरे को देख रहे हैं। कुछ नहीं कह रहे। यह खामोशी असल में ‘यह भी कर लिया, हम शानदार टीम हैं’ कहने का सबसे रोमांटिक और सच्चा तरीका है।', title_id = 'Saling pandang dalam diam 🥂', body_id = 'Anak sudah tidur. Anda dan pasangan saling memandang dalam diam di sofa. Tak ada yang bicara. Keheningan ini sebenarnya cara paling romantis dan tulus untuk berkata ''kita berhasil melewati ini juga, kita tim yang hebat''.', title_ja = '静かに見つめ合う 🥂', body_ja = '子どもが寝ました。あなたとパートナーはソファで静かに見つめ合う。何も話さない。この静けさこそが「今日も乗りきったね、最高のチームだね」を伝える、いちばんロマンチックで心のこもった方法です。', title_ko = '말없이 마주한 눈빛 🥂', body_ko = '아이가 잠들었어요. 배우자와 소파에서 말없이 서로를 바라보고 있나요? 아무 말도 하지 않아요. 이 침묵이야말로 ''오늘도 해냈어, 우린 최고의 팀이야''를 말하는 가장 로맨틱하고 진심 어린 방법이에요.', title_nl = 'Een stille blik naar elkaar 🥂', body_nl = 'Je kind slaapt. Jij en je partner kijken elkaar stil aan op de bank. Jullie zeggen niets. Deze stilte is eigenlijk de meest romantische en oprechte manier om te zeggen: ''Ook dit hebben we gered, we zijn een topteam.''', title_pl = 'Ciche spojrzenia 🥂', body_pl = 'Dziecko śpi. Ty i partner w milczeniu patrzycie na siebie na kanapie. Nic nie mówicie. Ta cisza to tak naprawdę najbardziej romantyczny i szczery sposób, by powiedzieć „i to nam się udało, jesteśmy świetną drużyną”.', title_pt = 'Um olhar silencioso a dois 🥂', body_pt = 'A criança adormeceu. A mãe e o seu companheiro olham um para o outro em silêncio no sofá. Não dizem nada. Na verdade, este silêncio é a forma mais romântica e sincera de dizer "também conseguimos isto, somos uma grande equipa".', title_sv = 'En tyst blick på varandra 🥂', body_sv = 'Barnet sover. Du och din partner tittar tyst på varandra i soffan. Ni säger ingenting. Den tystnaden är egentligen det mest romantiska och uppriktiga sättet att säga ”vi klarade det här också, vi är ett toppenlag”.', title_vi = 'Ánh nhìn lặng lẽ dành cho nhau 🥂', body_vi = 'Bé đã ngủ. Mẹ và chồng lặng lẽ nhìn nhau trên sofa. Không ai nói gì. Sự im lặng này thật ra là cách lãng mạn và chân thành nhất để nói "Chúng ta lại làm được rồi, chúng ta là một đội tuyệt vời".', title_zh = '无声地看着彼此 🥂', body_zh = '宝宝睡了。你和另一半坐在沙发上，静静地看着对方。什么都不说。这份安静，其实就是说“这一关我们也过了，我们是最棒的团队”最浪漫、最真诚的方式。' WHERE id = '744c45ec-e43d-4be3-95b9-700cd56edef4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rechazar la chaqueta 🧥', body_es = '¿No quiere ponerse la chaqueta de invierno porque fuera hace sol? Abre Tiempo y ropa y enséñale el símbolo del niño con ropa de invierno en el móvil. Deja la regla en manos de la pantalla, quítate de en medio y se la pondrá tan tranquilo.', title_fr = 'Le refus du blouson 🧥', body_fr = 'Parce qu''il y a du soleil dehors, il ne veut pas mettre son blouson d''hiver ? Ouvrez Météo et tenue et montrez-lui sur le téléphone l''icône de l''enfant en tenue d''hiver. Confiez la règle à l''écran, effacez-vous, et il s''habillera tranquillement.', title_hi = 'जैकेट से इनकार 🧥', body_hi = 'बाहर धूप है, इसलिए सर्दियों वाली जैकेट नहीं पहनना चाहता? मौसम और कपड़े खोलिए, फ़ोन पर सर्दियों के कपड़े पहने बच्चे का निशान दिखाइए। नियम डिजिटल स्क्रीन पर डाल दीजिए, खुद बीच से हट जाइए, वह चुपचाप पहन लेगा।', title_id = 'Menolak jaket 🧥', body_id = 'Ia tidak mau memakai jaket musim dinginnya karena di luar cerah? Buka Cuaca dan Pakaian, tunjukkan simbol anak berpakaian musim dingin di ponsel. Serahkan aturan pada layar digital, Anda cukup menyingkir, dan ia akan berpakaian dengan tenang.', title_ja = 'ジャケットはいや 🧥', body_ja = '外は晴れているから冬のジャケットを着たがらない？「天気と服装」を開いて、冬服を着た子どものマークを見せましょう。ルールはデジタル画面にまかせて、あなたは一歩下がれば、すんなり着てくれますよ。', title_ko = '점퍼는 싫어 🧥', body_ko = '밖에 해가 났다고 겨울 점퍼를 안 입겠대요? 날씨와 옷차림을 열어 휴대폰 속 겨울옷 입은 아이 그림을 보여 주세요. 규칙은 화면에 맡기고 엄마는 빠지면, 조용히 입을 거예요.', title_nl = 'De jas weigeren 🧥', body_nl = 'Wil hij zijn winterjas niet aan omdat de zon schijnt? Open Weer en kleding en laat hem het symbool zien van een kind in winterkleding. Laat het scherm de regel brengen, stap zelf opzij, en hij kleedt zich rustig aan.', title_pl = 'Odmowa założenia kurtki 🧥', body_pl = 'Nie chce założyć zimowej kurtki, bo na dworze świeci słońce? Otwórz Pogodę i ubiór i pokaż w telefonie symbol dziecka w zimowym ubraniu. Przenieś zasadę na ekran, sama zejdź z linii ognia, a on spokojnie się ubierze.', title_pt = 'Recusar o casaco 🧥', body_pt = 'Não quer vestir o casaco de inverno porque está sol? Abra o Tempo e Roupa e mostre-lhe no telemóvel o símbolo da criança com roupa de inverno. Passe a regra para o ecrã digital, saia de cena e ele vai vesti-lo sem protestar.', title_sv = 'Att vägra jackan 🧥', body_sv = 'Vill barnet inte ta på sig vinterjackan för att solen skiner? Öppna Väder och kläder och visa telefonens symbol med ett vinterklätt barn. Lägg regeln på den digitala skärmen, kliv själv åt sidan, så klär barnet lugnt på sig.', title_vi = 'Không chịu mặc áo khoác 🧥', body_vi = 'Bên ngoài có nắng nên bé không chịu mặc áo khoác mùa đông? Hãy mở Thời tiết và trang phục, cho bé xem biểu tượng em bé mặc đồ mùa đông trên điện thoại. Để màn hình đặt ra quy tắc, mẹ đứng ngoài cuộc, bé sẽ ngoan ngoãn mặc vào.', title_zh = '拒绝穿外套 🧥', body_zh = '因为外面有太阳，不肯穿冬天的外套？打开天气与穿衣，给宝宝看手机上穿着冬装的小朋友图标。把规则交给屏幕，你退到一边，宝宝就会乖乖穿上。' WHERE id = '9632825c-5c1a-41f6-900b-2b6b7e88d644' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confidencias en susurros a oscuras 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y susúrrale al oído, muy bajito, lo que ha pasado durante el día o el detalle de su carácter que más te gusta. El susurro es el método más mágico para preparar el cerebro para el sueño.', title_fr = 'Confidences chuchotées dans le noir 🌙', body_fr = 'Éteignez complètement la lumière de la chambre. Allongez-vous près de lui et chuchotez-lui très bas à l''oreille ce qui s''est passé dans la journée, ou le trait de son caractère que vous aimez le plus. Le chuchotement est la méthode la plus magique pour préparer le cerveau au sommeil.', title_hi = 'अंधेरे में फुसफुसाती बातें 🌙', body_hi = 'कमरे की लाइटें पूरी बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें, या उसकी आदत की वह बात जो आपको सबसे प्यारी लगती है, बहुत धीमी आवाज़ में उसके कान में फुसफुसाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे जादुई तरीका है।', title_id = 'Curhat berbisik dalam gelap 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan bisikkan ke telinganya dengan suara sangat pelan kejadian hari ini, atau hal yang paling Anda sukai dari karakternya. Bisikan adalah cara paling ajaib untuk menyiapkan otak tidur.', title_ja = '暗やみでひそひそおしゃべり 🌙', body_ja = '部屋の明かりを全部消しましょう。そばに横になって、今日あったことや、この子のいちばん好きなところを、耳もとでとても小さな声でささやいてあげて。ささやき声は、脳を眠りへ導くいちばんふしぎな方法です。', title_ko = '어둠 속 속삭임 대화 🌙', body_ko = '방 불을 완전히 끄세요. 옆에 누워 오늘 있었던 일이나 아이 성격에서 가장 좋아하는 점을 아주 작은 목소리로 귓가에 속삭여 주세요. 속삭임은 뇌를 잠에 준비시키는 가장 신비로운 방법이에요.', title_nl = 'Fluisterpraatjes in het donker 🌙', body_nl = 'Doe al het licht in de kamer uit. Ga naast hem liggen en fluister heel zacht in zijn oor wat er vandaag gebeurd is, of wat je het allerliefst aan hem vindt. Fluisteren is de meest mystieke manier om het brein klaar te maken voor de slaap.', title_pl = 'Szeptane zwierzenia w ciemności 🌙', body_pl = 'Zgaś całkiem światło w pokoju. Połóż się obok i bardzo cicho wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia, albo co najbardziej kochasz w jego charakterze. Szept to najbardziej magiczna metoda przygotowania mózgu do snu.', title_pt = 'Confidências em sussurro no escuro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e sussurre-lhe ao ouvido, em voz muito baixa, o que aconteceu durante o dia ou o pormenor de que mais gosta no feitio dele. Sussurrar é o método mais místico para preparar o cérebro para o sono.', title_sv = 'Viskande prat i mörkret 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och viska mycket tyst i örat om det som hänt under dagen, eller om det du älskar mest med barnets personlighet. Viskningar är den mest mystiska metoden för att förbereda hjärnan för sömn.', title_vi = 'Thì thầm tâm sự trong bóng tối 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật nhỏ vào tai bé về những gì đã xảy ra trong ngày, hoặc điều mẹ yêu nhất trong tính cách của bé. Lời thì thầm là cách kỳ diệu nhất để chuẩn bị cho não bé đi vào giấc ngủ.', title_zh = '在黑暗里说悄悄话 🌙', body_zh = '把房间的灯全关掉。躺在宝宝身边，用很低很低的声音，在宝宝耳边说说今天发生的事，或者你最喜欢宝宝性格里的哪一点。悄悄话是帮大脑准备入睡最神奇的方法。' WHERE id = '6f53d579-a4b1-4e03-8f30-fcdd7a9084bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La mentira de «no ha sido culpa mía» 🤥', body_es = '¿Ha tirado el agua al suelo a propósito, pero señala su coche con el dedo y dice «Me ha empujado»? No es mentir, es un mecanismo de defensa. Dile «Vamos a enseñarle también a ese coche cómo se limpia» y despista su cabecita con maña.', title_fr = 'Le mensonge du « C''est pas ma faute » 🤥', body_fr = 'Il a renversé l''eau exprès, mais montre sa voiture du doigt en disant « C''est elle qui l''a poussée » ? Ce n''est pas un mensonge, c''est un mécanisme de défense. Dites « Viens, on va apprendre à cette voiture comment on nettoie » et détournez habilement son attention.', title_hi = '‘यह मेरी गलती नहीं’ वाला झूठ 🤥', body_hi = 'जानबूझकर पानी गिराया, पर उँगली से अपनी गाड़ी दिखाकर बोला, ‘इसने धक्का दिया’? यह झूठ नहीं, बचाव का तरीका है। ‘चलो, उस गाड़ी को भी सिखाते हैं कि सफ़ाई कैसे करते हैं’ कहकर बड़ी चतुराई से उसका ध्यान बहलाइए।', title_id = 'Kebohongan ''Ini bukan salahku'' 🤥', body_id = 'Ia sengaja menumpahkan air ke lantai, tapi menunjuk mobilnya dan berkata ''Dia yang dorong''? Ini bukan berbohong, ini mekanisme perlindungan diri. Katakan ''Ayo kita ajari mobil itu cara membersihkannya'' dan kelabui pikirannya dengan cerdik.', title_ja = '「ぼくのせいじゃない」といううそ 🤥', body_ja = 'わざとお水を床にこぼしたのに、指で車をさして「この子が押した」と言った？うそではなく、自分を守る仕組みです。「じゃあ、その車にも拭き方を教えてあげよう」と言って、上手に気持ちを切りかえましょう。', title_ko = '''내 잘못 아니야'' 거짓말 🤥', body_ko = '일부러 물을 쏟아 놓고 자동차를 가리키며 ''얘가 밀었어''라고 했나요? 거짓말이 아니라 방어 기제예요. ''그럼 자동차한테도 어떻게 닦는지 가르쳐 주자'' 하며 능숙하게 아이의 관심을 돌리세요.', title_nl = 'De smoes ''Het is niet mijn schuld'' 🤥', body_nl = 'Gooide hij expres water op de grond, maar wees hij naar zijn autootje: ''Die duwde het''? Dat is geen liegen, maar een verdedigingsmechanisme. Zeg ''Kom, dan leren we die auto ook hoe je opruimt'' en speel slim in op zijn brein.', title_pl = 'Kłamstewko „to nie moja wina” 🤥', body_pl = 'Celowo wylał wodę na podłogę, ale pokazał palcem na swoje autko i powiedział: „To ono popchnęło”? To nie kłamstwo, tylko mechanizm obronny. Powiedz: „To nauczmy też autko, jak się sprząta” i zręcznie go przechytrz.', title_pt = 'A mentira do "não foi culpa minha" 🤥', body_pt = 'Entornou a água de propósito, mas apontou para o carrinho e disse "Foi ele que empurrou"? Não é mentir, é um mecanismo de defesa. Diga "Então vamos ensinar o carro a limpar" e engane o cérebro dele com mestria.', title_sv = 'Lögnen ”Det är inte mitt fel” 🤥', body_sv = 'Spillde barnet vatten på golvet med flit, men pekade på bilen och sa ”Den knuffade”? Det är inte att ljuga, det är en försvarsmekanism. Säg ”Kom, då lär vi bilen hur man torkar upp” och lura hjärnan skickligt.', title_vi = 'Lời nói dối "Không phải lỗi của con" 🤥', body_vi = 'Bé cố tình làm đổ nước nhưng lại chỉ vào chiếc xe đồ chơi: "Nó đẩy đấy"? Đây không phải nói dối, mà là cơ chế tự vệ. Hãy khéo léo "lừa" bộ não nhỏ: "Vậy mình cùng dạy chiếc xe cách lau nhé."', title_zh = '“不是我的错”的谎话 🤥', body_zh = '故意把水洒在地上，却指着小汽车说“是它推的”？这不是撒谎，而是自我保护机制。说一句“那我们也教教小汽车怎么擦干净吧”，巧妙地转移宝宝的注意力。' WHERE id = 'ba2db9df-7097-4890-b7eb-8938c592806f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La política del tobogán en el parque 🤝', body_es = '¿En el tobogán ha empujado a otro niño para subirse él? No te avergüences ni le pegues. Recuérdale la regla con voz suave pero firme: «Ahora le toca a él, luego a ti». Así aprenderá las normas sociales.', title_fr = 'La politique du toboggan au parc 🤝', body_fr = 'Il a poussé un autre enfant pour passer avant lui sur le toboggan ? Ne le frappez pas parce que vous avez honte. Dites « Maintenant, c''est son tour, après c''est toi » et rappelez la règle d''une voix douce mais ferme. C''est ainsi qu''il apprendra les règles sociales.', title_hi = 'पार्क में फिसलपट्टी की राजनीति 🤝', body_hi = 'फिसलपट्टी पर दूसरे बच्चे को धक्का देकर खुद चढ़ना चाहा? शर्मिंदा होकर बच्चे को मारिए मत। ‘अभी उसकी बारी है, फिर तुम्हारी’ कहकर नियम को नरम, पर पक्की आवाज़ में याद दिलाइए। सामाजिक नियम वह ऐसे ही सीखेगा।', title_id = 'Politik perosotan di taman 🤝', body_id = 'Ia mendorong anak lain di perosotan supaya bisa meluncur duluan? Jangan malu lalu memukulnya. Ingatkan aturannya dengan suara lembut tapi tegas: ''Sekarang gilirannya, nanti kamu''. Begitulah ia belajar aturan sosial.', title_ja = '公園のすべり台のルール 🤝', body_ja = 'すべり台でほかの子を押して、自分が先にすべろうとした？恥ずかしさからたたいたりしないで。「今はあの子の番、次があなたね」と、やさしく、でもきっぱりとルールを伝えましょう。こうして社会のルールを学んでいきます。', title_ko = '놀이터 미끄럼틀 규칙 🤝', body_ko = '미끄럼틀에서 다른 아이를 밀치고 자기가 타려고 했나요? 창피하다고 아이를 때리지 마세요. ''지금은 저 친구 차례, 그다음이 너야'' 하며 부드럽지만 단호하게 규칙을 알려 주세요. 이렇게 사회 규칙을 배워요.', title_nl = 'Glijbaanpolitiek in het park 🤝', body_nl = 'Duwde hij op de glijbaan een ander kind weg om zelf te gaan? Schaam je niet en sla hem niet. Herinner hem met een zachte maar vaste stem aan de regel: ''Nu is hij aan de beurt, daarna jij.'' Zo leert hij de sociale regels.', title_pl = 'Polityka na zjeżdżalni w parku 🤝', body_pl = 'Na zjeżdżalni odepchnął inne dziecko, bo sam chciał zjechać? Nie bij go ze wstydu. Przypomnij zasadę łagodnym, ale stanowczym głosem: „Teraz jego kolej, potem ty”. Tak nauczy się zasad społecznych.', title_pt = 'A política do escorrega no parque 🤝', body_pt = 'No escorrega, empurrou outra criança para passar à frente? Não fique envergonhada nem lhe bata. Lembre a regra com voz suave mas firme: "Agora é a vez dele, depois és tu". É assim que vai aprender as regras sociais.', title_sv = 'Rutschkanepolitik i parken 🤝', body_sv = 'Knuffade barnet undan ett annat barn i rutschkanan för att åka själv? Skäms inte och slå inte barnet. Säg ”Nu är det hens tur, sedan din” och påminn om regeln med en mjuk men bestämd röst. Så lär sig barnet de sociala reglerna.', title_vi = 'Luật chơi cầu trượt ở công viên 🤝', body_vi = 'Ở cầu trượt, bé đẩy một bạn khác ra để được trượt trước? Đừng xấu hổ mà đánh bé. Hãy nhắc quy tắc bằng giọng nhẹ nhàng nhưng dứt khoát: "Giờ đến lượt bạn, sau đó đến con." Bé sẽ học các quy tắc xã hội như thế.', title_zh = '公园滑梯的“政治学” 🤝', body_zh = '在滑梯上推开别的小朋友，想自己先滑？别因为难为情就打孩子。用温和但坚定的语气提醒规则：“现在轮到他了，然后是你。”宝宝就是这样学会社交规则的。' WHERE id = 'ce02bfea-edc6-42ad-80fd-37f3c322993b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que no llore el huevo 🍳', body_es = '¿Le ha dado pena el huevo al romperlo y no se lo come? Su empatía no tiene límites. Salva la situación al instante con una historia tierna como «Ahora va a vivir en tus músculos y te hará fuerte».', title_fr = 'Que l''œuf ne pleure pas 🍳', body_fr = 'Il a eu pitié de l''œuf quand vous l''avez cassé et refuse de le manger ? Son empathie est sans limites. Sauvez aussitôt la situation avec de douces inventions comme « Maintenant, il va vivre dans tes muscles et te rendre fort ».', title_hi = 'अंडा रोए नहीं 🍳', body_hi = 'अंडा तोड़ते समय उसे अंडे पर तरस आ गया और अब खा नहीं रहा? उसकी हमदर्दी की कोई सीमा नहीं। ‘अब यह तुम्हारी मांसपेशियों में रहकर तुम्हें ताकतवर बनाएगा’ जैसी प्यारी गढ़ी बातों से हालात तुरंत संभालिए।', title_id = 'Jangan biarkan telurnya menangis 🍳', body_id = 'Ia kasihan pada telur saat Anda memecahkannya dan tidak mau memakannya? Empatinya tak terbatas. Langsung selamatkan keadaan dengan karangan manis seperti ''Sekarang telurnya akan tinggal di ototmu dan membuatmu kuat''.', title_ja = '卵さん泣かないで 🍳', body_ja = '卵を割ったら、かわいそうになって食べない？共感力は限りなしです。「卵さんはこれから、あなたの筋肉の中で暮らして強くしてくれるんだよ」というかわいいお話で、その場をすぐに救いましょう。', title_ko = '달걀이 울면 안 돼 🍳', body_ko = '달걀을 깨뜨리자 불쌍하다며 안 먹나요? 공감 능력에 끝이 없네요. ''이제 달걀은 네 근육 속에서 살면서 너를 튼튼하게 해 줄 거야'' 같은 귀여운 이야기로 바로 상황을 구해 주세요.', title_nl = 'Het ei mag niet huilen 🍳', body_nl = 'Heeft hij medelijden met het ei als je het breekt en eet hij het niet? Zijn empathie kent geen grenzen. Red de situatie meteen met lieve verzinsels als ''Nu gaat het in jouw spieren wonen en maakt het je sterk.''', title_pl = 'Niech jajko nie płacze 🍳', body_pl = 'Zrobiło mu się żal jajka, gdy je rozbiłaś, i nie chce go jeść? Jego empatia nie zna granic. Od razu uratuj sytuację uroczą bajeczką w stylu „Teraz zamieszka w twoich mięśniach i zrobi cię silnym”.', title_pt = 'Que o ovo não chore 🍳', body_pt = 'Ficou com pena do ovo quando o partiu e não o quer comer? A empatia dele não tem limites. Salve logo a situação com pequenas invenções doces como "Agora vai viver nos teus músculos e deixar-te forte".', title_sv = 'Ägget får inte gråta 🍳', body_sv = 'Tyckte barnet synd om ägget när du knäckte det, och vill inte äta? Empatin har inga gränser. Rädda situationen direkt med söta påhitt som ”Nu ska det bo i dina muskler och göra dig stark”.', title_vi = 'Đừng để quả trứng khóc 🍳', body_vi = 'Bé thương quả trứng khi mẹ đập vỡ nó và không chịu ăn? Lòng trắc ẩn của bé thật vô bờ. Hãy cứu vãn tình hình ngay bằng những câu chuyện ngọt ngào như "Giờ nó sẽ sống trong cơ bắp của con và làm con khỏe mạnh".', title_zh = '别让鸡蛋哭 🍳', body_zh = '你打鸡蛋时，宝宝心疼鸡蛋，不肯吃了？宝宝的同理心没有边界。用“它现在要住进你的肌肉里，让你变得强壮”这样可爱的小故事，立刻化解局面吧。' WHERE id = '2128fd31-18d2-4020-9903-1e4bdb06a192' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las reglas para colocar las almohadas 🛏️', body_es = '¿Llora para que le pongas la almohada recta al milímetro? Le han surgido manías con el sueño. Sigue sus reglas, coloca la almohada como si la hubieras medido con regla, apaga las luces con decisión y dale seguridad.', title_fr = 'La règle d''alignement des oreillers 🛏️', body_fr = 'Il pleure pour que l''oreiller soit ajusté au millimètre ? Les obsessions du coucher sont apparues. Pliez-vous aux règles, arrangez l''oreiller comme s''il était mesuré à la règle, éteignez la lumière avec fermeté et rassurez-le.', title_hi = 'तकियों को लगाने का नियम 🛏️', body_hi = 'तकिए को मिलीमीटर तक ठीक करवाने के लिए रो रहा है? नींद से जुड़ी सनक शुरू हो गई है। नियम मान लीजिए, तकिया ऐसे ठीक कीजिए जैसे स्केल से नापा हो, और पक्के इरादे से लाइटें बंद करके उसे भरोसा दीजिए।', title_id = 'Aturan menyusun bantal 🛏️', body_id = 'Ia menangis minta bantalnya dirapikan sampai ke milimeter? Obsesi menjelang tidur mulai muncul. Ikuti aturannya, rapikan bantal seolah diukur dengan penggaris, lalu matikan lampu dengan tegas untuk memberinya rasa aman.', title_ja = 'まくらの並べ方ルール 🛏️', body_ja = 'まくらをミリ単位で直したくて泣いている？眠りへのこだわりが出てきました。ルールに従って、定規で測ったようにまくらを整え、きっぱり明かりを消して安心させてあげましょう。', title_ko = '베개 놓는 규칙 🛏️', body_ko = '베개를 밀리미터 단위로 맞추겠다고 우나요? 잠자리 집착이 생긴 거예요. 규칙에 따라 자로 잰 듯 베개를 반듯하게 놓고, 단호하게 불을 끄며 안심시켜 주세요.', title_nl = 'De regels van het kussen 🛏️', body_nl = 'Huilt hij omdat zijn kussen tot op de millimeter recht moet liggen? Er zijn slaapobsessies ontstaan. Ga mee in zijn regels, leg het kussen neer alsof je het met een liniaal hebt opgemeten, doe vastberaden het licht uit en geef hem zo vertrouwen.', title_pl = 'Zasady układania poduszek 🛏️', body_pl = 'Płacze, bo poduszkę trzeba poprawić co do milimetra? Pojawiły się obsesje związane ze snem. Podporządkuj się zasadom, ułóż poduszkę jak od linijki, stanowczo zgaś światło i daj mu poczucie bezpieczeństwa.', title_pt = 'A regra de arrumar as almofadas 🛏️', body_pt = 'Chora para que a almofada fique ajeitada ao milímetro? Surgiram obsessões na hora de dormir. Siga as regras, endireite a almofada como se a tivesse medido com régua, apague as luzes com firmeza e dê-lhe segurança.', title_sv = 'Kuddarnas ordning 🛏️', body_sv = 'Gråter barnet för att kudden ska ligga rätt på millimetern? Sömntvångstankarna har dykt upp. Följ reglerna, rätta till kudden som om den vore uppmätt med linjal, släck lamporna bestämt och ge barnet trygghet.', title_vi = 'Quy tắc xếp gối 🛏️', body_vi = 'Bé khóc đòi chỉnh gối chuẩn từng milimet? Những ám ảnh trước giờ ngủ đã xuất hiện. Hãy làm theo luật, chỉnh gối như được đo bằng thước kẻ, rồi dứt khoát tắt đèn để bé thấy an tâm.', title_zh = '枕头的摆放规则 🛏️', body_zh = '为了把枕头调整到毫米级精准而哭？睡前的执念出现了。照规矩来，像用尺子量过一样把枕头摆正，然后果断关灯，给宝宝安全感。' WHERE id = '2fbf236d-dcf9-462e-911e-87f8e16831b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Devuélveme la basura que he sacado! 🗑️', body_es = '¿Se ha armado una buena porque has tirado a la basura ese envoltorio viejo de chocolate que guardaba? Para ti es basura, para él un tesoro. Desvía su atención hacia otro juguete brillante.', title_fr = 'Rends-moi le déchet que j''ai sorti ! 🗑️', body_fr = 'C''est l''apocalypse parce que vous avez jeté le vieux papier de chocolat qu''il gardait ? Pour vous, c''est un déchet, pour lui, un trésor. Détournez son attention vers un autre jouet brillant.', title_hi = 'जो कूड़ा मैंने रखा था, वापस दो! 🗑️', body_hi = 'संभालकर रखा चॉकलेट का पुराना रैपर आपने कूड़े में डाल दिया, इसलिए हंगामा मच गया? आपके लिए कूड़ा, उसके लिए खज़ाना है। उसका ध्यान किसी और चमकदार खिलौने पर लगाइए।', title_id = 'Kembalikan sampah yang kubuang! 🗑️', body_id = 'Kiamat terjadi karena Anda membuang bungkus cokelat lama yang ia simpan? Bagi Anda sampah, baginya harta karun. Alihkan perhatiannya ke mainan lain yang berkilau.', title_ja = '捨てたゴミを返して！ 🗑️', body_ja = 'とっておいた古いチョコの包み紙を捨てたら大さわぎ？あなたにはゴミでも、この子には宝ものです。別のきらきらしたおもちゃに気をそらしましょう。', title_ko = '내가 버린 쓰레기 돌려줘! 🗑️', body_ko = '모아 둔 낡은 초콜릿 포장지를 버렸다고 난리가 났나요? 엄마에겐 쓰레기지만 아이에겐 보물이에요. 다른 반짝이는 장난감으로 관심을 돌려 주세요.', title_nl = 'Geef mijn afval terug! 🗑️', body_nl = 'Breekt de hel los omdat je dat oude chocoladepapiertje dat hij bewaarde hebt weggegooid? Voor jou is het afval, voor hem een schat. Leid zijn aandacht af met een ander glimmend speeltje.', title_pl = 'Oddaj śmieci, które wyrzuciłaś! 🗑️', body_pl = 'Wybuchła awantura, bo wyrzuciłaś stare opakowanie po czekoladzie, które trzymał? Dla ciebie to śmieć, dla niego skarb. Odwróć jego uwagę inną błyszczącą zabawką.', title_pt = 'Devolve-me o lixo que tiraste! 🗑️', body_pt = 'Caiu o Carmo e a Trindade porque deitou ao lixo aquele papel velho de chocolate que ele guardava? Para si é lixo, para ele é um tesouro. Desvie-lhe a atenção para outro brinquedo brilhante.', title_sv = 'Ge tillbaka skräpet jag sparade! 🗑️', body_sv = 'Blev det världens undergång för att du slängde det gamla chokladpapperet barnet sparat? För dig är det skräp, för barnet en skatt. Led om uppmärksamheten till en annan glänsande leksak.', title_vi = 'Trả lại "rác" của con đây! 🗑️', body_vi = 'Cả nhà như "tận thế" vì mẹ vứt tờ giấy gói kẹo cũ bé cất giữ? Với mẹ là rác, với bé là kho báu. Hãy chuyển sự chú ý của bé sang một món đồ chơi lấp lánh khác.', title_zh = '把我捡的垃圾还给我！🗑️', body_zh = '你把宝宝收藏的旧巧克力包装纸扔了，就闹翻天了？对你是垃圾，对宝宝是宝藏。把宝宝的注意力转到另一个亮晶晶的玩具上吧。' WHERE id = '3b18406f-7fbc-4193-88c1-aa910648f2b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dictador de casa en la mesa 👑', body_es = '¿En el desayuno dirige la mesa con un «Tú no te sientes ahí, siéntate aquí»? Sin romper de golpe su voluntad, mantén el equilibrio y la paz con una pequeña sonrisa y un «Vale, como tú digas».', title_fr = 'Le dictateur de la maison à table 👑', body_fr = 'Au petit-déjeuner, il dirige la table en disant « Toi, assieds-toi pas là, mais ici » ? Sans briser brutalement sa volonté, dites « D''accord, comme tu veux » et préservez l''équilibre et la paix avec un petit sourire.', title_hi = 'मेज़ पर घर का तानाशाह 👑', body_hi = 'नाश्ते में ‘तुम वहाँ नहीं, यहाँ बैठो’ कहकर मेज़ चला रहा है? उसकी इच्छा को झटके से तोड़े बिना, ‘ठीक है, जैसा तुम कहो’ कहकर एक छोटी सी मुस्कान से संतुलन और कमरे की शांति बनाए रखिए।', title_id = 'Diktator rumah di meja makan 👑', body_id = 'Saat sarapan ia mengatur meja dengan berkata ''Mama jangan duduk di sana, duduk di sini''? Tanpa mematahkan kemauannya secara keras, jaga keseimbangan dan kedamaian di kamar dengan senyum kecil sambil berkata ''Baik, terserah kamu''.', title_ja = '食卓の小さな独裁者 👑', body_ja = '朝ごはんで「ママはそこじゃない、ここに座って」と食卓をしきる？意志を強く押さえつけず、「わかった、あなたの言うとおりにしよう」と言って、小さな笑顔でバランスと部屋の平和を守りましょう。', title_ko = '식탁 위의 꼬마 독재자 👑', body_ko = '아침 식사 때 ''거기 말고 여기 앉아'' 하며 식탁을 지휘하나요? 의지를 확 꺾지 말고 ''좋아, 네 말대로 하자'' 하며 작은 미소로 균형과 평화를 지키세요.', title_nl = 'De dictator van het huis aan tafel 👑', body_nl = 'Bepaalt hij bij het ontbijt de hele tafel met ''Jij gaat niet daar, maar hier zitten''? Breek zijn wil niet hard, maar bewaar met een kleine glimlach de balans en de vrede: ''Goed, we doen het zoals jij zegt.''', title_pl = 'Domowy dyktator przy stole 👑', body_pl = 'Przy śniadaniu rządzi stołem: „Nie siadaj tam, siadaj tu”? Nie łamiąc ostro jego woli, powiedz: „Dobrze, niech będzie, jak mówisz” i z lekkim uśmiechem zachowaj równowagę i spokój w pokoju.', title_pt = 'O ditador da casa à mesa 👑', body_pt = 'Ao pequeno-almoço manda na mesa a dizer "Não te sentes aí, senta-te aqui"? Sem quebrar a vontade dele de forma brusca, diga "Está bem, fica como tu dizes" e mantenha o equilíbrio e a paz com um pequeno sorriso.', title_sv = 'Hemmets diktator vid bordet 👑', body_sv = 'Styr barnet bordet vid frukosten med ”Sitt inte där, sitt här”? Utan att bryta viljan hårt, säg ”Okej, vi gör som du säger” och bevara balansen och freden i rummet med ett litet leende.', title_vi = '"Nhà độc tài" nhí bên bàn ăn 👑', body_vi = 'Bữa sáng, bé điều khiển cả bàn: "Mẹ đừng ngồi đó, ngồi đây cơ"? Đừng bẻ gãy ý chí của bé một cách gay gắt, hãy nói "Được, theo ý con" và giữ cân bằng, hòa bình trong phòng bằng một nụ cười nhỏ.', title_zh = '餐桌上的家庭“独裁者” 👑', body_zh = '早餐时指挥全桌：“你别坐那儿，坐这儿”？不硬生生地打压宝宝的意愿，说一句“好，听你的”，用一个小小的微笑守住平衡和房间里的和平。' WHERE id = '3d6e1c1c-6a73-4824-ae1e-d09852574023' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No tener que explicarle nada a nadie 📝', body_es = '¿Nadie ve lo cansada que estás en casa y eso te hace explotar? Abre el Diario de ánimo. Escribe ahí todo lo que hoy te ha vuelto loca. Aceptar la emoción y escribirla te ayudará mucho más.', title_fr = 'N''avoir rien à expliquer à personne 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée à la maison, et ça vous fait exploser ? Ouvrez le Journal d''humeur. Écrivez-y tout ce qui vous a rendue folle aujourd''hui. Accepter l''émotion et l''écrire vous aidera bien plus.', title_hi = 'किसी को कुछ न समझाना 📝', body_hi = 'कोई नहीं देखता कि आप घर में कितना थकती हैं, और इससे आप फट पड़ती हैं? मूड डायरी खोलिए। आज जिसने भी आपको पागल किया, सब वहाँ लिख दीजिए। भावना को स्वीकार करके लिखना आपकी ज़्यादा मदद करेगा।', title_id = 'Tak perlu menjelaskan apa pun kepada siapa pun 📝', body_id = 'Tidak ada yang melihat betapa lelahnya Anda di rumah, dan itu membuat Anda ingin meledak? Buka Buku Harian Suasana Hati. Tulis di sana semua yang membuat Anda kesal hari ini. Menerima dan menuliskan emosi akan jauh lebih membantu Anda.', title_ja = '誰にも説明しなくていい 📝', body_ja = '家でどれだけ疲れているか誰も気づいてくれなくて、爆発しそう？「気分日記」を開きましょう。今日イライラしたことを全部そこに書いて。気持ちを受けとめて書くことが、ずっと助けになります。', title_ko = '아무에게도 설명하지 않아도 돼요 📝', body_ko = '집에서 내가 얼마나 지치는지 아무도 몰라줘서 폭발할 것 같나요? 기분 일기를 열고 오늘 나를 미치게 한 걸 전부 적어 보세요. 감정을 받아들이고 글로 쓰는 게 훨씬 도움이 될 거예요.', title_nl = 'Je hoeft niemand iets uit te leggen 📝', body_nl = 'Ziet niemand hoe moe je thuis bent en word je daar gek van? Open je Stemmingsdagboek. Schrijf alles op wat je vandaag gek heeft gemaakt. Je emoties accepteren en opschrijven helpt je echt.', title_pl = 'Nikomu niczego nie tłumaczyć 📝', body_pl = 'Nikt nie widzi, jak bardzo męczysz się w domu, i to doprowadza cię do wybuchu? Otwórz Dziennik nastroju. Zapisz tam wszystko, co dziś doprowadzało cię do szału. Przyjęcie emocji i zapisanie ich bardziej ci pomoże.', title_pt = 'Não ter de explicar nada a ninguém 📝', body_pt = 'Ninguém vê o quanto se cansa em casa e isso fá-la explodir? Abra o Diário de Humor. Escreva lá tudo o que hoje a deixou louca. Aceitar a emoção e escrevê-la vai ajudá-la muito mais.', title_sv = 'Att inte förklara något för någon 📝', body_sv = 'Ingen ser hur trött du blir hemma, och det får dig att explodera? Öppna Humördagboken. Skriv ner allt som gjort dig galen i dag. Att acceptera känslan och skriva ner den hjälper dig mer.', title_vi = 'Không cần giải thích với ai cả 📝', body_vi = 'Không ai thấy mẹ ở nhà mệt đến mức nào, và điều đó khiến mẹ muốn bùng nổ? Hãy mở Nhật ký tâm trạng. Viết hết vào đó mọi điều khiến mẹ phát điên hôm nay. Chấp nhận và viết ra cảm xúc sẽ giúp mẹ nhiều hơn.', title_zh = '不必向任何人解释 📝', body_zh = '没人看到你在家有多累，这让你快要爆发了？打开心情日记。把今天让你抓狂的事都写进去。接纳情绪、把它写下来，会更能帮到你。' WHERE id = '51ca75c5-97b8-4826-b323-ca25f125a567' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de leer en silencio 📖', body_es = 'Esta noche no hay lectura. Pon una música de fondo suave de Cuentos inteligentes y mirad solo los dibujos en silencio. Su cerebro se cansará visualmente y se rendirá al sueño sin que tengas que decir ni una palabra.', title_fr = 'L''heure de la lecture silencieuse 📖', body_fr = 'Ce soir, pas de lecture. Mettez une douce musique de fond des Contes intelligents et regardez seulement les images en silence. Son cerveau se fatiguera visuellement et il cédera au sommeil sans que vous disiez un seul mot.', title_hi = 'चुपचाप पढ़ने का समय 📖', body_hi = 'आज शाम पढ़ना नहीं। स्मार्ट कहानियों से धीमा बैकग्राउंड संगीत चलाइए और बस तस्वीरें चुपचाप देखिए। उसका दिमाग देख-देखकर थक जाएगा और आपके एक शब्द बोले बिना वह नींद के आगे हार मान लेगा।', title_id = 'Jam membaca tanpa suara 📖', body_id = 'Malam ini tidak ada membaca. Putar musik latar yang lembut dari Dongeng Pintar dan cukup lihat gambar-gambarnya dalam diam. Otaknya akan lelah secara visual, dan tanpa Anda mengucapkan sepatah kata pun, ia akan menyerah pada kantuk.', title_ja = '静かな読書タイム 📖', body_ja = '今夜は読み聞かせはお休み。「スマートおはなし」からやさしいBGMを流して、絵だけを静かに眺めましょう。目から脳が疲れて、あなたがひと言も話さなくても眠りに落ちます。', title_ko = '소리 없는 독서 시간 📖', body_ko = '오늘 저녁엔 읽지 않기로 해요. 스마트 동화에서 잔잔한 배경 음악을 틀고 그림만 조용히 함께 보세요. 눈으로 보다 지친 아이는 엄마가 한마디 하지 않아도 잠에 항복할 거예요.', title_nl = 'Stil leesuurtje 📖', body_nl = 'Vanavond geen voorlezen. Zet rustige achtergrondmuziek op uit Slimme sprookjes en kijk alleen stil naar de plaatjes. Zijn brein wordt visueel moe en hij valt in slaap zonder dat jij een woord hoeft te zeggen.', title_pl = 'Godzina cichego czytania 📖', body_pl = 'Dziś wieczorem bez czytania. Włącz łagodną muzykę w tle z Mądrych bajek i po prostu w ciszy oglądajcie obrazki. Jego mózg zmęczy się wzrokowo i podda się snowi, zanim powiesz choć słowo.', title_pt = 'Hora da leitura silenciosa 📖', body_pt = 'Esta noite não há leitura. Ponha uma música de fundo suave das Histórias Inteligentes e vejam as imagens em silêncio. O cérebro dele vai cansar-se visualmente e, sem dizer uma palavra, ele rende-se ao sono.', title_sv = 'En tyst lässtund 📖', body_sv = 'I kväll läser ingen. Sätt på en mild bakgrundsmusik i Smarta sagor och titta bara tyst på bilderna. Hjärnan blir visuellt trött och barnet somnar utan att du säger ett enda ord.', title_vi = 'Giờ đọc sách trong yên lặng 📖', body_vi = 'Tối nay không đọc gì cả. Hãy bật một bản nhạc nền êm dịu từ Truyện cổ tích thông minh và cùng lặng lẽ xem tranh. Não bé sẽ mệt vì hình ảnh và bé sẽ chìm vào giấc ngủ mà mẹ không cần nói một lời.', title_zh = '安静阅读时间 📖', body_zh = '今晚不朗读了。打开智慧童话里一段轻柔的背景音乐，只是静静地看图片。宝宝的大脑在视觉上累了，你一句话都不用说，宝宝就会进入梦乡。' WHERE id = '989e82d9-dbab-4ad4-8fb4-42a6025e0511' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de fuego en la caja del súper 🛒', body_es = '¿Grita por un chocolate justo delante de la caja? No cedas aunque te miren los de atrás. Abre la Lista de la compra y dile: «Aquí no está, la caja no lo va a leer». Si tú te mantienes firme, él también se echará atrás.', title_fr = 'L''épreuve de la caisse du supermarché 🛒', body_fr = 'Il hurle pour un chocolat juste devant la caisse ? Malgré les regards derrière vous, ne cédez pas. Ouvrez la Liste de courses et dites : « Ce n''est pas dedans, la caisse ne le lira pas. » Si vous restez ferme, il reculera lui aussi.', title_hi = 'सुपरमार्केट के काउंटर पर परीक्षा 🛒', body_hi = 'ठीक काउंटर के सामने चॉकलेट के लिए चिल्ला रहा है? पीछे वालों की नज़रों के बावजूद हार मत मानिए। शॉपिंग लिस्ट खोलिए और कहिए, ‘यह इसमें नहीं है, काउंटर इसे स्कैन नहीं करेगा।’ आप पक्की रहेंगी, तो वह भी पीछे हट जाएगा।', title_id = 'Ujian di kasir supermarket 🛒', body_id = 'Ia menjerit minta cokelat tepat di depan kasir? Jangan menyerah meski orang-orang di belakang memandangi. Buka Daftar Belanja dan katakan ''Ini tidak ada di sini, kasirnya tidak akan bisa membacanya''. Kalau Anda tegas, ia pun akan mundur.', title_ja = 'スーパーのレジで試練 🛒', body_ja = 'レジの目の前でチョコがほしいと叫ぶ？後ろの人の視線があっても負けないで。「買い物リスト」を開いて「ここには入っていないから、レジは読みとってくれないよ」と言いましょう。あなたがきっぱりしていれば、この子もあきらめます。', title_ko = '마트 계산대의 시험 🛒', body_ko = '계산대 바로 앞에서 초콜릿 사 달라고 소리치나요? 뒷사람들 시선에도 굴복하지 마세요. 쇼핑 목록을 열고 ''여기 없지? 계산대가 이건 안 읽어 줘''라고 말하세요. 엄마가 단호하면 아이도 물러날 거예요.', title_nl = 'Een test bij de kassa 🛒', body_nl = 'Schreeuwt hij vlak voor de kassa om chocola? Geef niet toe, ook al kijken de mensen achter je. Open het Boodschappenlijstje en zeg: ''Het staat er niet op, de kassa scant het niet.'' Als jij vastberaden bent, geeft hij ook toe.', title_pl = 'Próba przy kasie w sklepie 🛒', body_pl = 'Krzyczy o czekoladę tuż przed kasą? Mimo spojrzeń ludzi w kolejce nie poddawaj się. Otwórz Listę zakupów i powiedz: „Tego tu nie ma, kasa tego nie zeskanuje”. Jeśli będziesz stanowcza, on też odpuści.', title_pt = 'O teste da caixa do supermercado 🛒', body_pt = 'Grita por um chocolate mesmo em frente à caixa? Apesar dos olhares de quem está atrás, não ceda. Abra a Lista de Compras e diga: "Não está aqui, a caixa não o vai ler". Se a mãe for firme, ele também recua.', title_sv = 'Prövningen vid kassan 🛒', body_sv = 'Skriker barnet efter choklad precis framför kassan? Ge inte efter, trots blickarna från folket i kön. Öppna Inköpslistan och säg: ”Den står inte här, kassan kommer inte att läsa den.” Om du är bestämd backar barnet också.', title_vi = 'Thử thách ở quầy thu ngân 🛒', body_vi = 'Bé gào đòi sô-cô-la ngay trước quầy thu ngân? Dù người phía sau nhìn chằm chằm, đừng nhượng bộ. Mở Danh sách mua sắm và nói: "Không có trong này, quầy thu ngân sẽ không quét món này đâu." Mẹ kiên quyết thì bé cũng sẽ lùi bước.', title_zh = '超市收银台前的考验 🛒', body_zh = '就在收银台前为了巧克力尖叫？不管后面的人怎么看，都别让步。打开购物清单，说：“这里面没有，收银台扫不了它。”只要你坚定，宝宝也会退让。' WHERE id = '6f490476-47fe-4d7a-adc6-bf02e33e53bc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comer con la boca, no con las manos 🐶', body_es = '¿Quiere comer del plato como un gato, sin usar las manos? No se lo prohíbas. La cocina se va a ensuciar igualmente: deja que sea un gato 5 minutos. Este juego de rol tan gracioso es la forma más alegre de acabar con la falta de apetito.', title_fr = 'Manger avec la bouche, pas avec les mains 🐶', body_fr = 'Il veut manger dans son assiette comme un chat, sans utiliser ses mains ? N''interdisez pas. La cuisine sera sale de toute façon, laissez-le être un chat 5 minutes. Ce jeu de rôle comique est la façon la plus joyeuse de vaincre le manque d''appétit.', title_hi = 'हाथ से नहीं, मुँह से खाना 🐶', body_hi = 'प्लेट से बिना हाथ लगाए बिल्ली की तरह खाना चाहता है? मना मत कीजिए। रसोई वैसे भी गंदी होगी, उसे 5 मिनट बिल्ली बनने दीजिए। यह मज़ेदार रोल-प्ले भूख न लगने की समस्या दूर करने का सबसे खुशनुमा तरीका है।', title_id = 'Makan pakai mulut, bukan tangan 🐶', body_id = 'Ia ingin makan dari piring seperti kucing tanpa memakai tangan? Jangan dilarang. Dapur toh akan kotor, biarkan ia jadi kucing selama 5 menit. Permainan peran lucu ini adalah cara paling ceria untuk mengatasi susah makan.', title_ja = '手を使わずに口で食べる 🐶', body_ja = 'お皿から手を使わずに、ねこのように食べたがる？禁止しないで。キッチンはどうせ汚れます。5分だけねこにさせてあげましょう。このおかしなごっこ遊びは、食欲のなさを解消するいちばん楽しい方法です。', title_ko = '손 말고 입으로 먹기 🐶', body_ko = '손을 쓰지 않고 고양이처럼 접시에서 먹고 싶어 하나요? 금지하지 마세요. 부엌은 어차피 더러워질 테니 5분만 고양이가 되게 두세요. 이 재미있는 역할 놀이가 입맛 없는 날을 이기는 가장 즐거운 방법이에요.', title_nl = 'Eten met zijn mond, niet met zijn handen 🐶', body_nl = 'Wil hij als een poes zonder handen van zijn bord eten? Verbied het niet. De keuken wordt toch vies, laat hem 5 minuten een poes zijn. Dit grappige rollenspel is de vrolijkste manier om een gebrek aan eetlust te verhelpen.', title_pl = 'Jeść buzią, a nie rękami 🐶', body_pl = 'Chce jeść z talerza bez użycia rąk, jak kotek? Nie zabraniaj. Kuchnia i tak się ubrudzi, niech przez 5 minut będzie kotkiem. Ta zabawna gra w odgrywanie ról to najweselszy sposób na brak apetytu.', title_pt = 'Comer com a boca, sem as mãos 🐶', body_pt = 'Quer comer do prato como um gato, sem usar as mãos? Não proíba. A cozinha vai ficar suja de qualquer forma, deixe-o ser gato durante 5 minutos. Este jogo de faz de conta cómico é a forma mais alegre de combater a falta de apetite.', title_sv = 'Äta med munnen, inte med händerna 🐶', body_sv = 'Vill barnet äta direkt från tallriken som en katt, utan att använda händerna? Förbjud det inte. Köket blir ändå smutsigt, låt barnet vara katt i 5 minuter. Den roliga rolleken är det gladaste sättet att få bukt med dålig aptit.', title_vi = 'Ăn bằng miệng, không dùng tay 🐶', body_vi = 'Bé muốn ăn từ đĩa như mèo, không dùng tay? Đừng cấm. Bếp đằng nào cũng bẩn, cứ để bé làm mèo 5 phút. Trò nhập vai hài hước này là cách vui nhất để trị chứng lười ăn.', title_zh = '不用手，用嘴吃 🐶', body_zh = '想像小猫一样不用手直接从盘子里吃？别禁止。厨房反正会弄脏，就让宝宝当5分钟小猫吧。这个搞笑的角色扮演，是解决不爱吃饭最欢乐的方法。' WHERE id = '851d1060-8f2e-4d29-b181-eb135eec18ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy has pasado mucho tiempo de pie y se te parte la espalda de correr detrás de él y recoger juguetes del suelo. En cuanto el peque se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el motor de la casa y tienes que recuperarte sí o sí.', body_fr = 'Aujourd''hui, vous êtes restée longtemps debout, et à force de courir après lui et de ramasser les jouets, votre dos vous lâche. Dès que l''enfant dort, demandez à votre partenaire un massage des épaules de 10 minutes. Vous êtes le moteur de la maison, vous devez absolument récupérer.', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते और फ़र्श से खिलौने उठाते-उठाते कमर टूट गई। बच्चे के सोते ही अपने साथी से 10 मिनट कंधों की मालिश माँगिए। आप घर का इंजन हैं, आपको फिर से ऊर्जा चाहिए।', body_id = 'Hari ini Anda terlalu lama berdiri, punggung Anda serasa patah karena mengejarnya dan memunguti mainan dari lantai. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasangan Anda. Anda mesin rumah ini, Anda wajib dipulihkan.', body_ja = '今日は一日じゅう立ちっぱなしで、この子を追いかけたり、床のおもちゃを拾ったりして、腰が痛いですね。子どもが寝たら、パートナーに10分間の肩もみをお願いしましょう。あなたはこの家のエンジン。必ず回復が必要です。', body_ko = '오늘 하루 종일 서 있으면서 아이를 쫓아다니고 바닥의 장난감을 줍느라 허리가 끊어질 것 같나요? 아이가 잠들면 바로 배우자에게 10분간 어깨 마사지를 부탁하세요. 엄마는 이 집의 엔진이에요, 꼭 회복해야 해요.', body_nl = 'Je hebt vandaag veel gestaan, en van het achter hem aanrennen en speelgoed van de grond rapen doet je rug pijn. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de motor van dit huis, je moet echt herstellen.', body_pl = 'Dziś dużo stałaś na nogach, a od biegania za nim i zbierania zabawek z podłogi pęka ci kręgosłup. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś silnikiem tego domu, koniecznie musisz się zregenerować.', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de tanto correr atrás dele e apanhar brinquedos do chão. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o motor da casa e precisa mesmo de recuperar.', body_sv = 'I dag har du stått mycket, ryggen värker av att springa efter barnet och plocka upp leksaker från golvet. Så fort barnet somnat, be din partner om en 10 minuters axelmassage. Du är hemmets motor, du måste återhämta dig.', body_vi = 'Hôm nay mẹ đứng quá lâu, chạy theo bé, nhặt đồ chơi dưới sàn đến gãy lưng. Bé vừa ngủ, hãy nhờ chồng mát-xa vai cho mình 10 phút. Mẹ là động cơ của ngôi nhà, mẹ nhất định phải được hồi phục.', body_zh = '今天你站了太久，追着宝宝跑、从地上捡玩具，腰都快断了。宝宝一睡着，就请另一半给你按摩10分钟肩膀。你是这个家的引擎，一定要好好恢复。' WHERE id = '9555c57b-eea5-4d41-a55f-827af2218674' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Habitación totalmente a oscuras 🌌', body_es = '¿No puede dormir por la luz que se cuela desde el pasillo? Busca la perfección. Cierra bien la puerta, oscurece del todo la habitación y deja que la melatonina haga su trabajo natural y lo duerma rápido.', title_fr = 'Le noir complet dans la chambre 🌌', body_fr = 'Il n''arrive pas à dormir à cause de la lumière qui filtre du couloir ? Il cherche la perfection. Fermez bien la porte, plongez la chambre dans le noir complet et laissez la mélatonine faire son travail naturel pour l''endormir rapidement.', title_hi = 'कमरे में पूरा अंधेरा 🌌', body_hi = 'गलियारे से आती रोशनी की लकीर की वजह से सो नहीं पा रहा? वह परफ़ेक्शन ढूँढ रहा है। दरवाज़ा कसकर बंद कीजिए, कमरे में पूरा अंधेरा कीजिए, मेलाटोनिन को अपना प्राकृतिक काम करके उसे जल्दी सुलाने दीजिए।', title_id = 'Kamar yang benar-benar gelap 🌌', body_id = 'Ia tidak bisa tidur karena cahaya merembes dari lorong? Ia sedang mencari kesempurnaan. Tutup pintu rapat-rapat, gelapkan kamar sepenuhnya, biarkan melatonin bekerja secara alami dan membuatnya cepat tertidur.', title_ja = '部屋を真っ暗に 🌌', body_ja = '廊下からもれる光で眠れない？完璧を求めているんです。ドアをしっかり閉めて部屋を真っ暗にし、メラトニンの自然な働きで、すばやく眠らせてあげましょう。', title_ko = '완전히 어두운 방 🌌', body_ko = '복도에서 새어 들어오는 빛 때문에 잠을 못 자나요? 완벽을 찾는 중이에요. 문을 꼭 닫고 방을 완전히 어둡게 해서, 멜라토닌이 자연스럽게 제 할 일을 하며 빨리 재워 주게 하세요.', title_nl = 'De kamer helemaal donker 🌌', body_nl = 'Kan hij niet slapen door het licht dat vanuit de gang naar binnen kiert? Hij zoekt perfectie. Doe de deur goed dicht, maak de kamer helemaal donker en laat melatonine zijn natuurlijke werk doen, zodat hij snel in slaap valt.', title_pl = 'Całkowicie ciemny pokój 🌌', body_pl = 'Nie może zasnąć przez światło sączące się z korytarza? Szuka perfekcji. Szczelnie zamknij drzwi, całkiem zaciemnij pokój i pozwól melatoninie naturalnie zrobić swoje i szybko go uśpić.', title_pt = 'O quarto completamente às escuras 🌌', body_pt = 'Não consegue dormir por causa da luz que entra do corredor? Procura a perfeição. Feche bem a porta, escureça totalmente o quarto e deixe a melatonina fazer o seu trabalho natural e adormecê-lo depressa.', title_sv = 'Ett helt mörkt rum 🌌', body_sv = 'Kan barnet inte sova för ljuset som läcker in från hallen? Hen söker perfektion. Stäng dörren ordentligt, gör rummet helt mörkt och låt melatoninet göra sitt naturliga jobb och snabbt söva barnet.', title_vi = 'Phòng tối hoàn toàn 🌌', body_vi = 'Bé không ngủ được vì ánh sáng lọt vào từ hành lang? Bé đang tìm kiếm sự hoàn hảo. Hãy đóng chặt cửa, làm tối hoàn toàn căn phòng, để melatonin tự nhiên làm nhiệm vụ và đưa bé vào giấc ngủ thật nhanh.', title_zh = '让房间彻底变暗 🌌', body_zh = '因为走廊透进来的光睡不着？宝宝在追求完美。把门关紧，让房间完全暗下来，让褪黑素自然发挥作用，让宝宝快快入睡。' WHERE id = 'ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis del «es mío» 🧸', body_es = '¿Abraza el mando de la tele y dice «¡Es mío!»? Está poniendo a prueba los límites de la propiedad. No lo llames egoísta: dile «Gracias por encontrármelo», lleva su atención a otro juego y recupéralo.', title_fr = 'La crise du « C''est à moi » 🧸', body_fr = 'Il serre la télécommande dans ses bras en disant « C''est à moi ! » ? Il teste les limites de la propriété. Ne le traitez pas d''égoïste : dites « Merci de l''avoir trouvée pour moi », détournez son attention vers un autre jeu et récupérez-la.', title_hi = '‘वह मेरा है’ वाला संकट 🧸', body_hi = 'घर का रिमोट गले लगाकर कहता है, ‘यह मेरा है!’? वह मालिकाना हक की सीमाएँ परख रहा है। उसे स्वार्थी मत कहिए, ‘शुक्रिया, तुमने इसे मेरे लिए ढूँढ लिया’ कहकर उसका ध्यान दूसरे खेल पर लगाइए और रिमोट वापस ले लीजिए।', title_id = 'Krisis ''Itu punyaku'' 🧸', body_id = 'Ia memeluk remote di rumah dan berkata ''Ini punyaku!''? Ia sedang menguji batas kepemilikan. Jangan sebut ia egois, katakan ''Terima kasih sudah menemukannya untuk Mama'' dan ambil kembali sambil mengalihkan perhatiannya ke permainan lain.', title_ja = '「それ、ぼくの」危機 🧸', body_ja = '家のリモコンを抱えて「これ、ぼくの！」？自分のものの境界線をためしています。わがままと呼ばず、「見つけてくれてありがとう」と言って、ほかの遊びに気をそらしながら返してもらいましょう。', title_ko = '''내 거야'' 위기 🧸', body_ko = '집 리모컨을 끌어안고 ''이건 내 거야!'' 하나요? 소유의 경계를 시험하는 중이에요. 이기적이라고 하지 말고 ''찾아 줘서 고마워'' 하며 다른 놀이로 관심을 돌려 돌려받으세요.', title_nl = 'De ''Dat is van mij''-crisis 🧸', body_nl = 'Knuffelt hij de afstandsbediening en roept hij ''Die is van mij!''? Hij test de grenzen van bezit. Noem hem geen egoïst, zeg ''Dank je dat je hem voor me gevonden hebt'', leid zijn aandacht naar een ander spel en neem hem terug.', title_pl = 'Kryzys „to moje” 🧸', body_pl = 'Ściska pilota i mówi „To moje!”? Sprawdza granice własności. Nie nazywaj go egoistą, powiedz: „Dziękuję, że mi go znalazłeś”, przekieruj jego uwagę na inną zabawę i odzyskaj pilota.', title_pt = 'A crise do "é meu" 🧸', body_pt = 'Abraça o comando da televisão e diz "Isto é meu!"? Está a testar os limites da posse. Não lhe chame egoísta: diga "Obrigada por o teres encontrado para mim", desvie a atenção dele para outro jogo e recupere-o.', title_sv = 'Krisen ”Den är min” 🧸', body_sv = 'Kramar barnet fjärrkontrollen och säger ”Den är min!”? Hen testar ägandets gränser. Kalla inte barnet egoistiskt, säg ”Tack för att du hittade den åt mig”, led uppmärksamheten till en annan lek och ta tillbaka den.', title_vi = 'Khủng hoảng "Của con!" 🧸', body_vi = 'Bé ôm khư khư chiếc điều khiển TV và nói: "Cái này của con!"? Bé đang thử ranh giới sở hữu. Đừng gọi bé là ích kỷ, hãy nói "Cảm ơn con đã tìm giúp mẹ" và chuyển sự chú ý của bé sang trò chơi khác để lấy lại.', title_zh = '“那是我的”危机 🧸', body_zh = '抱着家里的遥控器说“这是我的！”？宝宝在测试所有权的边界。别说宝宝自私，说一句“谢谢你帮我找到它”，把宝宝的注意力引到别的游戏上，再把遥控器拿回来。' WHERE id = 'e268e86b-b622-447e-800e-69d444728521' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El significado de las frases a medias 🗣️', body_es = '¿Cuando se le olvida una palabra hace gestos con la mano y espera a que la adivines? Fíjate en el alivio de su cara cuando completas su frase con paciencia. Así, justo con tu apoyo, construye su vocabulario y su autoestima.', title_fr = 'Le sens des phrases inachevées 🗣️', body_fr = 'Quand il oublie un mot, il fait des gestes avec ses mains et attend que vous le trouviez ? Quand vous terminez patiemment sa phrase, observez le soulagement sur son visage. C''est justement grâce à votre soutien qu''il construit son vocabulaire et sa confiance en soi.', title_hi = 'अधूरे वाक्यों का मतलब 🗣️', body_hi = 'कोई शब्द भूलने पर हाथों से इशारे करके इंतज़ार करता है कि आप ढूँढ दें? धीरज से उसका वाक्य पूरा कीजिए और उसके चेहरे पर आई राहत देखिए। वह अपनी शब्दावली और आत्मविश्वास आपके इसी सहारे से बनाता है।', title_id = 'Arti kalimat yang belum selesai 🗣️', body_id = 'Saat lupa satu kata, ia memberi isyarat dengan tangan dan menunggu Anda menebaknya? Saat Anda dengan sabar melengkapi kalimatnya, perhatikan rasa lega di wajahnya. Dengan dukungan Anda-lah ia membangun kosakata dan rasa percaya dirinya.', title_ja = 'とちゅうで止まった文の意味 🗣️', body_ja = 'ことばを忘れると、手でジェスチャーをしてあなたが当てるのを待つ？根気よく文を完成させてあげたときの、ほっとした顔を見て。まさにあなたの支えで、語彙と自信を育てているんです。', title_ko = '끝맺지 못한 문장의 의미 🗣️', body_ko = '단어가 생각나지 않으면 손짓을 하며 엄마가 맞혀 주길 기다리나요? 차분히 문장을 완성해 줄 때 아이 얼굴에 번지는 안도감을 보세요. 바로 엄마의 도움으로 어휘와 자신감을 쌓아 가는 거예요.', title_nl = 'De betekenis van halve zinnen 🗣️', body_nl = 'Maakt hij gebaren als hij een woord vergeet en wacht hij tot jij het raadt? Kijk naar de opluchting op zijn gezicht als je geduldig zijn zin afmaakt. Precies met jouw steun bouwt hij zijn woordenschat en zelfvertrouwen op.', title_pl = 'Sens niedokończonych zdań 🗣️', body_pl = 'Gdy zapomni słowa, pokazuje coś rękami i czeka, aż zgadniesz? Gdy cierpliwie dokończysz jego zdanie, przyjrzyj się uldze na jego twarzy. To właśnie z twoim wsparciem buduje swoje słownictwo i pewność siebie.', title_pt = 'O significado das frases a meio 🗣️', body_pt = 'Quando se esquece de uma palavra, faz gestos com as mãos e espera que a adivinhe? Ao completar com paciência a frase dele, repare no alívio que lhe aparece no rosto. É exatamente com o seu apoio que ele constrói o vocabulário e a autoconfiança.', title_sv = 'Meningen med halva meningar 🗣️', body_sv = 'När barnet glömmer ett ord gör hen tecken med händerna och väntar på att du ska hitta det? När du tålmodigt avslutar meningen, se lättnaden i ansiktet. Det är just med ditt stöd som barnet bygger upp ordförrådet och självförtroendet.', title_vi = 'Ý nghĩa của những câu nói dở dang 🗣️', body_vi = 'Quên một từ, bé ra hiệu bằng tay và chờ mẹ đoán ra? Hãy kiên nhẫn giúp bé nói trọn câu và ngắm vẻ nhẹ nhõm trên gương mặt bé. Chính nhờ sự hỗ trợ của mẹ mà bé xây dựng vốn từ và sự tự tin.', title_zh = '说一半的句子的意思 🗣️', body_zh = '忘了一个词，就用手比划，等你来猜？耐心地帮宝宝把句子说完，看看宝宝脸上那份如释重负。宝宝正是在你的支持下，这样建立起词汇和自信的。' WHERE id = 'e71d30e6-0cdb-4938-b907-fc93e194b4d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La exigencia de secar el agua 💧', body_es = '¿En lugar de beberse el agua del vaso grita «Está demasiado mojada, sécala»? Sin buscar lógica, échala en un vaso de otro color y dile «Te he traído agua seca». El arte de la ilusión es tu mejor arma como mamá.', title_fr = 'L''exigence de sécher l''eau 💧', body_fr = 'Au lieu de boire l''eau de son verre, il crie « Elle est trop mouillée, sèche-la ! » ? Sans chercher de logique, versez l''eau dans un verre d''une autre couleur et dites « Je t''ai apporté de l''eau sèche ». L''art de l''illusion est votre plus grande arme de maman.', title_hi = 'पानी सुखाने की माँग 💧', body_hi = 'गिलास का पानी पीने के बजाय चिल्लाता है, ‘यह बहुत गीला है, इसे सुखाओ’? तर्क ढूँढे बिना पानी दूसरे रंग के गिलास में डालिए और कहिए, ‘सूखा पानी लाई हूँ।’ भ्रम की कला माँ होने में आपका सबसे बड़ा हथियार है।', title_id = 'Tuntutan ''keringkan airnya'' 💧', body_id = 'Bukannya meminum air di gelas, ia malah berteriak ''Ini terlalu basah, keringkan!''? Tanpa mencari logika, tuang airnya ke gelas berwarna lain dan katakan ''Mama bawakan air kering''. Seni ilusi adalah senjata terbesar dalam menjadi ibu.', title_ja = 'お水をかわかしてと言う 💧', body_ja = 'コップのお水を飲まずに「これ、ぬれすぎ、かわかして」と叫ぶ？理屈を探さずに、別の色のコップにお水を入れて「かわいたお水を持ってきたよ」と言いましょう。イリュージョンの技は、子育てで最大の武器です。', title_ko = '물을 말려 달라는 요구 💧', body_ko = '컵에 든 물을 마시는 대신 ''이거 너무 젖었어, 말려 줘!'' 하고 소리치나요? 논리를 찾지 말고 물을 다른 색 컵에 옮겨 ''마른 물 가져왔어''라고 말해 주세요. 착시의 기술은 육아의 가장 큰 무기예요.', title_nl = 'De eis om water droog te maken 💧', body_nl = 'Drinkt hij het water niet, maar roept hij ''Dit is te nat, maak het droog''? Zoek geen logica, schenk het water in een beker met een andere kleur en zeg: ''Ik heb droog water voor je.'' De kunst van de illusie is je grootste wapen als mama.', title_pl = 'Żądanie wysuszenia wody 💧', body_pl = 'Zamiast wypić wodę z kubka, krzyczy: „Ona jest za mokra, wysusz ją”? Nie szukaj logiki, przelej wodę do kubka w innym kolorze i powiedz: „Przyniosłam suchą wodę”. Sztuka iluzji to twoja największa broń w macierzyństwie.', title_pt = 'A exigência de secar a água 💧', body_pt = 'Em vez de beber a água do copo, grita "Isto está muito molhado, seca-a"? Sem procurar lógica, deite a água num copo de outra cor e diga "Trouxe-te água seca". A arte da ilusão é a sua maior arma na maternidade.', title_sv = 'Kravet att torka vattnet 💧', body_sv = 'I stället för att dricka vattnet i glaset skriker barnet ”Det är för blött, torka det”? Leta inte efter logik, häll vattnet i ett glas med en annan färg och säg ”Jag har tagit med torrt vatten”. Illusionens konst är ditt största vapen som mamma.', title_vi = 'Đòi làm khô nước 💧', body_vi = 'Thay vì uống nước trong cốc, bé hét lên: "Nước này ướt quá, mẹ làm khô đi"? Đừng tìm logic, hãy rót nước sang chiếc cốc màu khác và nói "Mẹ mang nước khô đến rồi". Nghệ thuật ảo thuật là vũ khí lớn nhất của mẹ.', title_zh = '要求把水弄干 💧', body_zh = '不喝杯子里的水，却大喊“这水太湿了，把它弄干”？别找逻辑，把水倒进另一个颜色的杯子，说“我给你拿来了干的水”。当妈妈的路上，“障眼法”是你最大的武器。' WHERE id = '0a86e24e-bf60-4b61-ae36-925c5211691c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Entre cuatro paredes su energía se convierte en agresividad y cada frase empieza por «no»? Confía en Tiempo y ropa y sácalo fuera sí o sí. Tocar la tierra reiniciará al instante su sistema nervioso.', body_fr = 'Entre quatre murs, son énergie se transforme en agressivité et chaque phrase commence par « non » ? Faites confiance à Météo et tenue et sortez-le absolument. Toucher la terre remettra aussitôt son système nerveux à zéro.', body_hi = 'चार दीवारों के बीच उसकी ऊर्जा गुस्से में बदल रही है और हर वाक्य ‘नहीं’ से शुरू होता है? मौसम और कपड़े पर भरोसा करके उसे ज़रूर बाहर ले जाइए। मिट्टी को छूना उसके तंत्रिका तंत्र को तुरंत रीसेट कर देगा।', body_id = 'Di dalam empat dinding, energinya berubah menjadi agresi dan setiap kalimatnya dimulai dengan ''nggak''? Andalkan Cuaca dan Pakaian dan pastikan ia keluar rumah. Menyentuh tanah akan langsung me-reset sistem sarafnya.', body_ja = '四方の壁の中でエネルギーがイライラに変わり、口を開けば「いや」から始まる？「天気と服装」を信じて、必ず外へ連れ出しましょう。土にふれることで、神経がすぐにリセットされます。', body_ko = '네 벽 안에서 에너지가 공격성으로 바뀌고, 하는 말마다 ''싫어''로 시작하나요? 날씨와 옷차림을 믿고 꼭 밖으로 데리고 나가세요. 흙을 만지는 것만으로 아이의 신경계가 바로 리셋될 거예요.', body_nl = 'Slaat zijn energie tussen vier muren om in agressie en begint elke zin met ''nee''? Vertrouw op Weer en kleding en ga beslist met hem naar buiten. De aarde aanraken zet zijn zenuwstelsel meteen weer op nul.', body_pl = 'W czterech ścianach jego energia zmienia się w agresję, a każde zdanie zaczyna się od „nie”? Zaufaj narzędziu Pogoda i ubiór i koniecznie wyjdź z nim na dwór. Kontakt z ziemią od razu wyzeruje jego układ nerwowy.', body_pt = 'Entre quatro paredes, a energia dele transforma-se em agressividade e cada frase começa por "não"? Confie no Tempo e Roupa e leve-o sem falta para a rua. Tocar na terra vai pôr logo a zero o sistema nervoso dele.', body_sv = 'Bakom de fyra väggarna blir energin till aggression och varje mening börjar med ”nej”? Lita på Väder och kläder och ta absolut ut barnet. Att röra vid jorden nollställer genast nervsystemet.', body_vi = 'Ở giữa bốn bức tường, năng lượng của bé biến thành cáu gắt và câu nào cũng bắt đầu bằng "không"? Hãy tin vào Thời tiết và trang phục và nhất định đưa bé ra ngoài. Được chạm vào đất sẽ lập tức "khởi động lại" hệ thần kinh của bé.', body_zh = '被困在四面墙里，精力变成了攻击性，每句话都以“不”开头？相信天气与穿衣，一定要带宝宝出门。接触泥土会让宝宝的神经系统立刻重启。' WHERE id = 'b27687ec-9619-4dbe-be9c-054706708b62' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir solo con el sonido de la campana ⏱️', body_es = '¿Cuando llega la hora de dormir de repente quiere ir al baño? Pon un temporizador. Aplica la regla «Cuando suena la campanita, todos apagamos las luces» y líbrate sin discusiones de esta despedida sin fin y esta manipulación de experto.', title_fr = 'Le sommeil automatique au son de la sonnerie ⏱️', body_fr = 'À l''heure du coucher, il veut soudain aller aux toilettes ? Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde éteint la lumière » et échappez sans dispute à ces adieux sans fin, à cette manipulation de maître.', title_hi = 'घंटी की आवाज़ से अपने आप नींद ⏱️', body_hi = 'सोने का समय आते ही अचानक टॉयलेट जाना है? टाइमर लगाइए। ‘घंटी बजे तो सब लाइटें बंद करते हैं’ वाला नियम लागू कीजिए और इस अंतहीन अलविदा, इस माहिर चाल से बिना बहस के छुटकारा पाइए।', title_id = 'Tidur otomatis dengan bunyi bel ⏱️', body_id = 'Begitu waktu tidur tiba, tiba-tiba ia ingin ke toilet? Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua lampu dimatikan'' dan bebaskan diri tanpa perdebatan dari pamitan tanpa akhir dan manipulasi ahli ini.', title_ja = 'ベルの音で自然とおやすみ ⏱️', body_ja = '寝る時間になると、急にトイレに行きたくなる？タイマーをセットして、「ベルが鳴ったらみんな明かりを消す」というルールを使い、この終わりのないおやすみと名人の駆け引きから、言い合いなしで抜け出しましょう。', title_ko = '알람 소리에 저절로 잠들기 ⏱️', body_ko = '잘 시간만 되면 갑자기 화장실에 가겠다고 하나요? 타이머를 맞추고 ''알람이 울리면 모두 불을 끈다''는 규칙을 적용해, 끝없는 작별 인사와 노련한 작전에서 다툼 없이 벗어나세요.', title_nl = 'Vanzelf slapen bij het belsignaal ⏱️', body_nl = 'Moet hij als het bedtijd is ineens naar de wc? Zet een timer. Pas de regel toe ''Als de bel gaat, doet iedereen het licht uit'' en verlos jezelf zonder discussie van dit eindeloze afscheid en deze meesterlijke manipulatie.', title_pl = 'Automatyczny sen na dźwięk dzwonka ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce iść do toalety? Nastaw timer. Wprowadź zasadę „Gdy zadzwoni dzwonek, wszyscy gaszą światło” i bez kłótni uwolnij się od tych niekończących się pożegnań i mistrzowskiej manipulacji.', title_pt = 'Sono automático ao som da campainha ⏱️', body_pt = 'Quando chega a hora de dormir, de repente quer ir à casa de banho? Programe um temporizador. Aplique a regra "quando a campainha toca, todos apagam as luzes" e livre-se, sem discussões, desta despedida sem fim e desta manipulação de mestre.', title_sv = 'Automatisk sömn när klockan ringer ⏱️', body_sv = 'Vill barnet plötsligt gå på toaletten när det är dags att sova? Ställ in en timer. Inför regeln ”när klockan ringer släcker alla” och rädda dig utan bråk från det ändlösa farvälet och den mästerliga manipulationen.', title_vi = 'Tiếng chuông và giấc ngủ tự động ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng đòi đi vệ sinh? Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà tắt đèn" để thoát khỏi màn tạm biệt bất tận, chiêu thao túng bậc thầy này mà không cần tranh cãi.', title_zh = '铃声一响自动入睡 ⏱️', body_zh = '一到睡觉时间就突然要上厕所？设个计时器。执行“铃声一响，大家都关灯”的规则，不用争吵，就能摆脱这场没完没了的告别和高明的“小伎俩”。' WHERE id = 'eeca2adc-6712-4238-9603-30877865ed81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escondite detrás de la puerta 🙈', body_es = 'Llegáis tarde a la guarde y él se esconde detrás de la cortina diciendo «¡Encuéntrame!». Gritar alargará todo. Únete a un juego de 2 minutos con un «¿Dónde estará mi peque?» y sácalo de ahí entre risas.', title_fr = 'Cache-cache derrière la porte 🙈', body_fr = 'Vous êtes en retard pour la crèche, et lui se cache derrière le rideau en disant « Trouve-moi ! ». Crier ne fera que rallonger les choses. Dites « Mais où est donc mon bébé ? », entrez dans le jeu pendant 2 minutes et faites-le sortir de là en riant.', title_hi = 'दरवाज़े के पीछे छुपन-छुपाई 🙈', body_hi = 'किंडरगार्टन के लिए देर हो रही है, और वह पर्दे के पीछे छिपकर कह रहा है, ‘मुझे ढूँढो!’ चिल्लाने से देर और बढ़ेगी। ‘पता नहीं मेरा बच्चा कहाँ है?’ कहकर 2 मिनट के खेल में शामिल हो जाइए और उसे हँसाते हुए वहाँ से निकालिए।', title_id = 'Petak umpet di balik pintu 🙈', body_id = 'Kalian sudah terlambat ke TK, sementara ia bersembunyi di balik gorden dan berkata ''Cari aku!''. Berteriak hanya akan memperpanjang prosesnya. Katakan ''Di mana ya anak Mama?'', ikut bermain selama 2 menit, dan keluarkan ia dari sana sambil tertawa.', title_ja = 'ドアのかげでかくれんぼ 🙈', body_ja = '保育園に遅れそうなのに、カーテンのうしろに隠れて「見つけて！」。叫ぶと時間がもっとかかります。「あれ、うちの子はどこかな？」と言って2分だけ遊びに加わり、笑いながら出てこさせましょう。', title_ko = '문 뒤의 숨바꼭질 🙈', body_ko = '어린이집에 늦었는데 커튼 뒤에 숨어 ''나 찾아 봐!'' 하나요? 소리치면 시간만 더 걸려요. ''우리 아기 어디 있지?'' 하며 2분만 놀이에 함께하고, 웃으며 데리고 나오세요.', title_nl = 'Verstoppertje achter de deur 🙈', body_nl = 'Jullie zijn te laat voor de opvang en hij verstopt zich achter het gordijn: ''Zoek me maar!'' Schreeuwen maakt het alleen langer. Zeg ''Waar zou mijn kleintje toch zijn?'', speel 2 minuten mee en haal hem lachend tevoorschijn.', title_pl = 'Zabawa w chowanego za drzwiami 🙈', body_pl = 'Spóźniacie się do przedszkola, a on schował się za zasłoną i woła: „Znajdź mnie!”. Krzyk tylko przedłuży sprawę. Powiedz: „Ciekawe, gdzie jest mój skarb?”, włącz się na 2 minuty w zabawę i wyciągnij go stamtąd ze śmiechem.', title_pt = 'Escondidas atrás da cortina 🙈', body_pt = 'Estão atrasados para o jardim de infância e ele escondeu-se atrás da cortina a dizer "Encontra-me!". Gritar só vai prolongar tudo. Diga "Onde estará o meu menino?", entre no jogo durante 2 minutos e tire-o de lá a rir.', title_sv = 'Kurragömma bakom dörren 🙈', body_sv = 'Ni är sena till förskolan, och barnet gömmer sig bakom gardinen och säger ”Hitta mig!” Att skrika drar bara ut på det. Säg ”Undrar var mitt lilla barn är?”, var med i leken i 2 minuter och få fram barnet skrattande.', title_vi = 'Trốn tìm sau cánh cửa 🙈', body_vi = 'Đã muộn giờ đi mẫu giáo, bé lại trốn sau rèm và nói: "Mẹ tìm con đi!" Quát mắng chỉ làm mọi chuyện kéo dài. Hãy nói "Không biết bé con của mẹ đâu rồi nhỉ?", chơi cùng bé 2 phút và dắt bé ra trong tiếng cười.', title_zh = '门后的捉迷藏 🙈', body_zh = '去幼儿园要迟到了，宝宝却躲在窗帘后面喊“来找我！”吼叫只会让过程更长。说一句“我的宝贝去哪儿了呢？”，加入2分钟的游戏，笑着把宝宝从那里“找”出来。' WHERE id = '4e140178-6301-4406-9f9f-fe623cbcfff7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Efectos de sonido distintos en Cuentos inteligentes 🪄', body_es = 'Abre Cuentos inteligentes. Mientras lees la historia, monta un teatro de sonidos en la habitación con solo el chirrido de una puerta, el viento y unos susurros. Estas ondas sonoras tan originales meterán su atención al instante dentro del cuento.', title_fr = 'Des effets sonores originaux dans le Conte intelligent 🪄', body_fr = 'Ouvrez les Contes intelligents. Pendant la lecture, faites simplement des grincements de porte, des bruits de vent et des chuchotements pour créer un théâtre sonore dans la chambre. Ces ondes sonores inhabituelles plongeront aussitôt son attention dans le conte.', title_hi = 'स्मार्ट कहानी में अलग-अलग साउंड इफ़ेक्ट 🪄', body_hi = 'स्मार्ट कहानियाँ खोलिए। कहानी पढ़ते समय बस दरवाज़े की चरमराहट, हवा की आवाज़ और सरसराहट निकालकर कमरे में आवाज़ों का थिएटर बनाइए। ये अनोखी आवाज़ें उसका ध्यान तुरंत कहानी के अंदर खींच लेंगी।', title_id = 'Efek suara berbeda di Dongeng Pintar 🪄', body_id = 'Buka Dongeng Pintar. Sambil membacakan cerita, buat teater suara di kamar cukup dengan bunyi pintu berderit, angin, dan desisan. Gelombang suara yang tak biasa ini akan langsung menarik perhatiannya masuk ke dalam dongeng.', title_ja = 'スマートおはなしでいろいろな効果音 🪄', body_ja = '「スマートおはなし」を開きましょう。お話を読みながら、ドアのきしむ音や風の音、ささやき声を出して、部屋に音の劇場をつくって。ふしぎな音の波が、すぐにこの子をお話の中へ引きこみます。', title_ko = '스마트 동화 속 색다른 효과음 🪄', body_ko = '스마트 동화를 열어 보세요. 이야기를 읽으며 문 삐걱거리는 소리, 바람 소리, 속삭임을 내어 방 안에 소리 극장을 만들어 보세요. 이 특별한 소리가 아이의 관심을 단숨에 동화 속으로 끌어들일 거예요.', title_nl = 'Andere geluidseffecten in Slimme sprookjes 🪄', body_nl = 'Open Slimme sprookjes. Maak tijdens het voorlezen een geluidstheater in de kamer met een krakende deur, waaiende wind en gefluister. Deze ongewone geluidsgolven trekken zijn aandacht meteen het sprookje in.', title_pl = 'Różne efekty dźwiękowe w Mądrej bajce 🪄', body_pl = 'Otwórz Mądre bajki. Czytając historię, po prostu naśladuj skrzypienie drzwi, szum wiatru i syczenie, tworząc w pokoju teatr dźwięku. Te niezwykłe fale dźwiękowe od razu wciągną jego uwagę do bajki.', title_pt = 'Efeitos sonoros diferentes nas Histórias Inteligentes 🪄', body_pt = 'Abra as Histórias Inteligentes. Enquanto lê a história, faça só o ranger da porta, o som do vento e sussurros e monte um teatro de sons no quarto. Estas ondas sonoras invulgares vão puxar logo a atenção dele para dentro da história.', title_sv = 'Olika ljudeffekter i Smarta sagor 🪄', body_sv = 'Öppna Smarta sagor. Medan du läser berättelsen, gör bara dörrknarr, vindsus och viskningar och bygg en ljudteater i rummet. De ovanliga ljudvågorna drar genast in barnets uppmärksamhet i sagan.', title_vi = 'Hiệu ứng âm thanh lạ trong Truyện cổ tích thông minh 🪄', body_vi = 'Hãy mở Truyện cổ tích thông minh. Khi đọc truyện, chỉ cần tạo tiếng cửa kẽo kẹt, tiếng gió và tiếng xì xào để dựng một "nhà hát âm thanh" trong phòng. Những làn sóng âm khác lạ này sẽ lập tức kéo sự chú ý của bé vào câu chuyện.', title_zh = '智慧童话里的特别音效 🪄', body_zh = '打开智慧童话。讲故事时，只要发出门吱呀声、风声和沙沙声，就能在房间里搭起一座声音剧场。这些不寻常的声音会立刻把宝宝的注意力拉进故事里。' WHERE id = '7964aed1-1770-40a2-a565-23bfdc9aea21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La culpa del descanso con pantallas 📺', body_es = '¿Hoy tenías mucho que hacer y ha pasado mucho rato delante de la tele? ¿Te come la culpa por dentro? No puedes ser perfecta todos los días. A veces las pantallas son la niñera más inocente que nos salva de grandes caos. Tranquila.', title_fr = 'Culpabilité de la pause écran 📺', body_fr = 'Aujourd''hui, vous aviez beaucoup à faire et il est resté longtemps devant la télé ? La culpabilité vous ronge ? Vous ne pouvez pas être parfaite tous les jours. Parfois, les écrans sont la nounou la plus innocente qui nous sauve des grands chaos, détendez-vous.', title_hi = 'बिना स्क्रीन वाले ब्रेक का अपराधबोध 📺', body_hi = 'आज आपके पास बहुत काम था, इसलिए वह देर तक टीवी के सामने रहा? अंदर ही अंदर अपराधबोध खा रहा है? आप हर दिन परफ़ेक्ट नहीं हो सकतीं। कभी-कभी स्क्रीन ही वह मासूम आया होती है जो हमें बड़ी अफ़रा-तफ़री से बचाती है, निश्चिंत रहिए।', title_id = 'Rasa bersalah soal jeda tanpa layar 📺', body_id = 'Hari ini Anda sangat sibuk sehingga ia lama di depan TV? Rasa bersalah menggerogoti hati Anda? Anda tidak bisa sempurna setiap hari. Kadang layar adalah pengasuh paling polos yang menyelamatkan kita dari kekacauan besar, tenanglah.', title_ja = '画面の時間への罪悪感 📺', body_ja = '今日は用事が多くて、テレビの前にいる時間が長くなった？罪悪感で胸がちくちくする？毎日完璧ではいられません。ときには画面が、大きなカオスから救ってくれるいちばん無邪気なベビーシッターです。気楽にね。', title_ko = '화면 시간에 대한 죄책감 📺', body_ko = '오늘 할 일이 많아 아이가 TV 앞에 오래 있었나요? 죄책감이 마음을 갉아먹나요? 매일 완벽할 순 없어요. 때로는 화면이 큰 혼란에서 우리를 구해 주는 가장 순한 베이비시터예요. 마음 편히 가지세요.', title_nl = 'Schuldgevoel over schermtijd 📺', body_nl = 'Zat hij vandaag lang voor de tv omdat jij veel te doen had? Knaagt het schuldgevoel? Je kunt niet elke dag perfect zijn. Soms is een scherm de onschuldigste oppas die ons van grote chaos redt, maak je niet druk.', title_pl = 'Wyrzuty sumienia po czasie przed ekranem 📺', body_pl = 'Dziś miałaś dużo pracy i długo siedział przed telewizorem? Gryzą cię wyrzuty sumienia? Nie możesz być idealna każdego dnia. Czasem ekran to najbardziej niewinna niania, która ratuje nas przed wielkim chaosem, odpuść sobie.', title_pt = 'A culpa da pausa com ecrã 📺', body_pt = 'Hoje tinha muito que fazer e ele passou muito tempo em frente à televisão? A culpa está a roê-la por dentro? Não pode ser perfeita todos os dias. Às vezes os ecrãs são a ama mais inocente, que nos salva de grandes caos. Fique tranquila.', title_sv = 'Dåligt samvete över skärmtid 📺', body_sv = 'Hade du så mycket att göra i dag att barnet satt länge framför tv:n? Gnager det dåliga samvetet? Du kan inte vara perfekt varje dag. Ibland är skärmen den mest oskyldiga barnvakten som räddar oss från stort kaos, ta det lugnt.', title_vi = 'Day dứt vì không có giờ nghỉ màn hình 📺', body_vi = 'Hôm nay mẹ bận nhiều việc nên bé ngồi trước TV lâu? Cảm giác tội lỗi đang gặm nhấm mẹ? Mẹ không thể hoàn hảo mỗi ngày. Đôi khi màn hình là "bảo mẫu" vô tội nhất cứu chúng ta khỏi những hỗn loạn lớn, cứ thoải mái đi.', title_zh = '屏幕时间的内疚 📺', body_zh = '今天事情太多，宝宝在电视前待得太久了？心里满是内疚？你不可能每天都完美。有时候，屏幕就是把我们从大混乱中拯救出来的最无辜的“保姆”，放轻松。' WHERE id = 'c87486c1-f5de-473b-8cd5-b9e2e2bd31c1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El artista que rompe su obra 🖍️', body_es = '¿No le ha gustado la línea que ha dibujado, dice «Ha quedado mal» y rompe el papel? ¡Están naciendo la autocrítica y el sentido de la perfección! Convierte su frustración en descubrimiento con un «La próxima vez probamos otro color».', title_fr = 'L''artiste qui déchire son œuvre 🖍️', body_fr = 'Il n''aime pas le trait qu''il a tracé et déchire la feuille en disant « C''est raté » ? L''autocritique et le sens de la perfection apparaissent ! Dites « Viens, la prochaine fois on essaie une autre couleur » et transformez sa déception en découverte.', title_hi = 'अपनी ही कलाकृति फाड़ने वाला कलाकार 🖍️', body_hi = 'अपनी बनाई लकीर पसंद नहीं आई, तो ‘यह खराब बनी’ कहकर कागज़ फाड़कर फेंक देता है? खुद की आलोचना और परफ़ेक्शन की भावना जाग रही है! ‘चलो, अगली बार कोई और रंग आज़माते हैं’ कहकर उसकी निराशा को खोज में बदल दीजिए।', title_id = 'Seniman yang merobek karyanya sendiri 🖍️', body_id = 'Ia tidak suka garis yang ia gambar, berkata ''Ini jelek'', lalu merobek dan membuang kertasnya? Kemampuan mengkritik diri dan rasa kesempurnaan mulai muncul! Ubah kekecewaannya menjadi penemuan dengan berkata ''Yuk, lain kali kita coba warna lain''.', title_ja = '自分の作品をやぶる画家 🖍️', body_ja = 'かいた線が気に入らなくて「これ、だめ」と紙をやぶって捨てる？自分を振り返る力と、完璧を求める気持ちが芽生えています！「次はちがう色をためしてみよう」と言って、がっかりを発見に変えましょう。', title_ko = '자기 작품을 찢는 화가 🖍️', body_ko = '자기가 그은 선이 마음에 안 들어 ''이거 망했어'' 하며 종이를 찢어 버리나요? 자기비판과 완벽주의가 생겨나는 중이에요! ''다음엔 다른 색으로 해 보자'' 하며 실망을 탐험으로 바꿔 주세요.', title_nl = 'De kunstenaar die zijn eigen werk verscheurt 🖍️', body_nl = 'Vindt hij een lijn die hij tekende niet mooi, zegt hij ''Dit is lelijk'' en verscheurt hij het papier? Zelfkritiek en perfectionisme ontstaan! Maak van zijn teleurstelling een ontdekking: ''Kom, de volgende keer proberen we een andere kleur.''', title_pl = 'Artysta, który drze swoje dzieło 🖍️', body_pl = 'Nie podoba mu się narysowana kreska, mówi „Wyszło brzydko” i drze kartkę? Rodzi się samokrytyka i poczucie perfekcji! Powiedz: „Następnym razem spróbujmy innego koloru” i zamień jego rozczarowanie w odkrycie.', title_pt = 'O artista que rasga a própria obra 🖍️', body_pt = 'Não gostou da linha que desenhou, disse "Ficou mal" e rasgou o papel? Estão a nascer a autocrítica e o sentido de perfeição! Transforme a desilusão dele em descoberta: "Da próxima vez vamos experimentar outra cor".', title_sv = 'Konstnären som river sitt eget verk 🖍️', body_sv = 'Gillade barnet inte strecket hen ritade, sa ”Det blev dåligt” och rev sönder pappret? Självkritik och känslan för perfektion växer fram! Säg ”Nästa gång testar vi en annan färg” och gör besvikelsen till en upptäckt.', title_vi = 'Họa sĩ xé tác phẩm của mình 🖍️', body_vi = 'Không thích nét vẽ của mình, bé nói "Xấu quá" rồi xé giấy vứt đi? Khả năng tự đánh giá và cảm giác cầu toàn đang hình thành! Hãy biến nỗi thất vọng thành khám phá: "Lần sau mình thử màu khác nhé."', title_zh = '撕掉自己作品的小画家 🖍️', body_zh = '不喜欢自己画的线，说“画得不好”，就把纸撕了扔掉？自我批评和追求完美的意识正在出现！说一句“下次我们试试别的颜色吧”，把宝宝的失望变成一次探索。' WHERE id = '0c893825-691b-4509-9849-6369336b84d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Frotarse como un gato 🐾', body_es = '¿Esta mañana anda a cuatro patas, se frota contra tus piernas y solo dice «miau»? En lugar de ponerte a leerle las normas, acércale tú también un cuenco de leche imaginario. Jugar siempre es más fácil y divertido que regañar.', title_fr = 'Se frotter comme un chat 🐾', body_fr = 'Ce matin, il marche à quatre pattes, se frotte contre vos jambes et dit seulement « Miaou » ? Au lieu de lui faire la leçon, tendez-lui vous aussi un bol de lait imaginaire. Jouer est toujours plus facile et plus amusant que gronder.', title_hi = 'बिल्ली की तरह लिपटना 🐾', body_hi = 'आज सुबह वह चारों पैरों पर चल रहा है, आपके पैरों से लिपट रहा है और बस ‘म्याऊँ’ कह रहा है? उसे नियम समझाने के बजाय आप भी उसकी ओर दूध का एक काल्पनिक कटोरा बढ़ा दीजिए। खेलना डाँटने से हमेशा आसान और मज़ेदार होता है।', title_id = 'Menggosok-gosokkan badan seperti kucing 🐾', body_id = 'Pagi ini ia berjalan merangkak, menggosokkan badan ke kaki Anda, dan hanya berkata ''meong''? Daripada membacakan aturan, sodorkan juga mangkuk susu khayalan untuknya. Bermain selalu lebih mudah dan menyenangkan daripada memarahi.', title_ja = 'ねこみたいにすりすり 🐾', body_ja = '今朝は四つ足で歩いて、足にすりすりして「にゃー」としか言わない？ルールを説くかわりに、空想のミルクのお皿を差し出しましょう。遊ぶほうが、叱るよりいつも楽で楽しいものです。', title_ko = '고양이처럼 비비기 🐾', body_ko = '오늘 아침 네 발로 다니며 다리에 몸을 비비고 ''야옹''만 하나요? 훈계하는 대신 상상의 우유 그릇을 내밀어 주세요. 놀아 주는 게 혼내는 것보다 언제나 쉽고 즐거워요.', title_nl = 'Kopjes geven als een poes 🐾', body_nl = 'Loopt hij vanochtend op handen en voeten, schurkt hij tegen je been en zegt hij alleen ''miauw''? Ga hem geen regels voorlezen, maar geef hem een denkbeeldig schoteltje melk. Spelen is altijd makkelijker en leuker dan mopperen.', title_pl = 'Łasi się jak kotek 🐾', body_pl = 'Dziś rano chodzi na czworakach, ociera się o twoją nogę i mówi tylko „miau”? Zamiast wygłaszać mu zasady, podaj mu wyimaginowaną miseczkę mleka. Zabawa jest zawsze łatwiejsza i przyjemniejsza niż besztanie.', title_pt = 'Esfregar-se como um gato 🐾', body_pt = 'Esta manhã anda de quatro, esfrega-se nas suas pernas e só diz "miau"? Em vez de parar para lhe ditar regras, estenda-lhe também uma tigela de leite imaginária. Brincar é sempre mais fácil e divertido do que ralhar.', title_sv = 'Stryka sig mot benen som en katt 🐾', body_sv = 'Går barnet på alla fyra i morse, stryker sig mot dina ben och säger bara ”mjau”? I stället för att läsa upp regler, ställ fram en låtsasskål med mjölk du också. Att leka är alltid lättare och roligare än att skälla.', title_vi = 'Dụi người như mèo con 🐾', body_vi = 'Sáng nay bé bò bằng bốn chân, dụi vào chân mẹ và chỉ kêu "meo"? Thay vì đứng giảng giải quy tắc, mẹ cũng hãy đưa bé một bát sữa tưởng tượng. Chơi cùng luôn dễ và vui hơn mắng mỏ.', title_zh = '像小猫一样蹭蹭 🐾', body_zh = '今早四肢着地走路，蹭着你的腿，只会说“喵”？与其停下来给宝宝讲规矩，不如你也递上一碗想象中的牛奶。玩耍总比责骂更轻松、更有趣。' WHERE id = 'bcac5731-4815-4adc-beb4-861e3ff078b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Mezcla jabones de colores en el agua y prepara pociones? El baño queda perdido, sí. Pero está aprendiendo qué cosas se disuelven. Esta exploración científica es la mejor forma de quitarle el cansancio de la tarde y prepararlo para un sueño tranquilo.', body_fr = 'Il mélange des savons de différentes couleurs dans l''eau pour préparer une potion ? La salle de bain est inondée, oui. Mais il apprend ce que sont les solvants. Cette exploration scientifique est le plus beau moyen d''effacer la fatigue du soir et de le préparer à un sommeil paisible.', body_hi = 'पानी में अलग-अलग रंग के साबुन मिलाकर जादुई घोल बना रहा है? बाथरूम गंदा हो रहा है, हाँ। पर वह घुलने वाली चीज़ों के बारे में सीख रहा है। यह वैज्ञानिक खोज शाम की थकान उतारकर उसे शांत नींद के लिए तैयार करने का सबसे प्यारा तरीका है।', body_id = 'Ia mencampur sabun berwarna-warni ke dalam air untuk membuat ramuan? Kamar mandi jadi berantakan, ya. Tapi ia sedang belajar tentang zat pelarut. Penjelajahan ilmiah ini adalah cara terindah untuk menghapus lelah sore hari dan menyiapkannya untuk tidur yang tenang.', body_ja = 'お湯にいろいろな色の石けんをまぜて、魔法の薬をつくっている？お風呂は水びたし、そうですね。でも、溶けるしくみを学んでいます。この科学の探検が夕方の疲れをとって、静かな眠りへ導くいちばんすてきな方法です。', body_ko = '물에 여러 색 비누를 섞어 물약을 만드나요? 욕실이 엉망이 되죠, 맞아요. 하지만 용해를 배우는 중이에요. 이 과학 탐험이 저녁의 피로를 풀고 아이를 차분한 잠으로 이끄는 가장 좋은 방법이에요.', body_nl = 'Mengt hij zeepjes in verschillende kleuren in het water om een toverdrankje te maken? De badkamer wordt een ravage, ja. Maar hij leert over oplossen. Deze wetenschappelijke ontdekkingstocht is de mooiste manier om de vermoeidheid van de avond weg te spoelen en hem klaar te maken voor een rustige slaap.', body_pl = 'Dodaje do wody mydła w różnych kolorach i przygotowuje eliksir? Łazienka tonie, tak. Ale on poznaje rozpuszczalniki. To naukowe odkrywanie zabiera wieczorne zmęczenie i jest najpiękniejszym sposobem, by przygotować go do spokojnego snu.', body_pt = 'Junta à água sabonetes de cores diferentes e prepara poções? Sim, a casa de banho fica inundada. Mas ele está a aprender o que se dissolve. Esta exploração científica leva o cansaço do fim do dia e é a melhor forma de o preparar para um sono tranquilo.', body_sv = 'Blandar barnet olikfärgade tvålar i vattnet och gör en trolldryck? Badrummet blir nedsölat, ja. Men barnet lär sig om lösningsmedel. Den vetenskapliga upptäcktsfärden tar bort kvällens trötthet och är det finaste sättet att förbereda barnet för en lugn sömn.', body_vi = 'Bé pha xà phòng nhiều màu vào nước để làm "thuốc tiên"? Phòng tắm lênh láng, đúng vậy. Nhưng bé đang học về sự hòa tan. Cuộc thám hiểm khoa học này là cách tuyệt vời nhất để xua đi mệt mỏi buổi tối và chuẩn bị cho bé một giấc ngủ êm.', body_zh = '往水里加不同颜色的肥皂，调制“魔法药水”？浴室被弄得一团糟，是的。可宝宝正在学习溶解的知识。这场科学探索能带走傍晚的疲惫，是帮宝宝准备安稳入睡的最好方式。' WHERE id = 'c6026760-e985-429a-b39f-d4d1786df630' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La función de «¿Tú quién eres?» 🎭', body_es = '¿Te mira como a una desconocida y te dice «¿Tú quién eres? ¿Dónde está mi mamá?»? Es un nuevo juego de rol. Dile «Soy la doctora, he venido a escucharte el corazón» y hazle cosquillas. Que la habitación se llene de risas por la mañana.', title_fr = 'Le spectacle du « Qui es-tu ? » 🎭', body_fr = 'Il vous regarde comme une inconnue et dit « Qui es-tu ? Où est ma maman ? » ? C''est un nouveau jeu de rôle. Dites « Je suis la dame docteur, je viens écouter ton cœur » et chatouillez-le. Que la chambre éclate de rire dès le matin.', title_hi = '‘तुम कौन हो?’ वाला नाटक 🎭', body_hi = 'आपको अजनबी की तरह देखकर कहता है, ‘तुम कौन हो? मेरी माँ कहाँ है?’ यह नया रोल-प्ले है। कहिए, ‘मैं डॉक्टर आंटी हूँ, तुम्हारा दिल सुनने आई हूँ’ और गुदगुदी कीजिए। सुबह हँसी से कमरा गूँजने दीजिए।', title_id = 'Pertunjukan ''Kamu siapa?'' 🎭', body_id = 'Ia menatap Anda seperti orang asing dan berkata ''Kamu siapa? Mamaku mana?''? Ini permainan peran baru. Katakan ''Aku tante dokter, datang untuk mendengarkan jantungmu'' dan gelitik ia. Biarkan kamar pecah oleh tawa pagi ini.', title_ja = '「あなたは誰？」劇場 🎭', body_ja = '知らない人を見るような顔で「あなたは誰？ママはどこ？」と言う？新しいごっこ遊びです。「お医者さんよ、あなたの心臓の音を聞きに来たの」と言って、くすぐりましょう。朝から笑いで部屋をいっぱいに。', title_ko = '''누구세요?'' 연극 🎭', body_ko = '낯선 사람 보듯 ''누구세요? 우리 엄마 어디 있어요?'' 하나요? 새로운 역할 놀이예요. ''나는 의사 선생님이야, 네 심장 소리 들으러 왔어'' 하며 간지럼을 태워 주세요. 아침부터 웃음으로 방이 떠나가게 두세요.', title_nl = 'Het ''Wie ben jij?''-toneelstuk 🎭', body_nl = 'Kijkt hij je aan als een vreemde en zegt hij: ''Wie ben jij? Waar is mijn mama?'' Dit is een nieuw rollenspel. Zeg: ''Ik ben de dokter, ik kom naar je hartje luisteren'' en kietel hem. Laat de kamer vanochtend schudden van het lachen.', title_pl = 'Przedstawienie „Kim jesteś?” 🎭', body_pl = 'Patrzy na ciebie jak na obcą i pyta: „Kim jesteś? Gdzie moja mama?”. To nowa zabawa w odgrywanie ról. Powiedz: „Jestem panią doktor, przyszłam posłuchać twojego serduszka” i go połaskocz. Niech poranek wypełni śmiech.', title_pt = 'O espetáculo "Quem és tu?" 🎭', body_pt = 'Olha para si como para uma estranha e diz "Quem és tu? Onde está a minha mãe?"? É um novo jogo de faz de conta. Diga "Sou a senhora doutora, vim ouvir o teu coração" e faça-lhe cócegas. Deixe que o quarto se encha de gargalhadas logo de manhã.', title_sv = 'Föreställningen ”Vem är du?” 🎭', body_sv = 'Tittar barnet på dig som på en främling och säger ”Vem är du? Var är mamma?” Det är en ny rollek. Säg ”Jag är doktorstanten, jag har kommit för att lyssna på ditt hjärta” och kittla. Låt rummet fyllas av skratt på morgonen.', title_vi = 'Vở kịch "Cô là ai?" 🎭', body_vi = 'Bé nhìn mẹ như người lạ và hỏi "Cô là ai? Mẹ con đâu?" Đây là trò nhập vai mới. Hãy nói: "Cô là cô bác sĩ, cô đến nghe tim cho con đây" rồi cù bé. Để cả phòng rộn tiếng cười buổi sáng.', title_zh = '“你是谁？”小剧场 🎭', body_zh = '像看陌生人一样看着你说：“你是谁？我妈妈在哪儿？”这是新的角色扮演游戏。说“我是医生阿姨，来听听你的心跳”，再挠挠宝宝的痒痒。让早晨的笑声充满房间吧。' WHERE id = '40e041b4-2484-475f-93b5-25cda3ee362e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Has entrado en la habitación y has visto todo el papel higiénico desenrollado por la casa? En lugar de enfadarte, recoged juntos los papeles y haced una pelota. Al caos no se le gana gritando, sino con creatividad y risas.', body_fr = 'En entrant dans la pièce, vous avez vu tout le papier toilette déroulé et étalé dans la maison ? Plutôt que de vous énerver, ramassez le papier et faites-en une balle ensemble. Battez le chaos non pas en criant, mais avec créativité et des rires.', body_hi = 'कमरे में आईं और देखा कि टॉयलेट पेपर का पूरा रोल खुलकर घर भर में फैला है? गुस्सा होने के बजाय वे कागज़ इकट्ठे करके साथ मिलकर गेंद बनाइए। अफ़रा-तफ़री को चिल्लाकर नहीं, रचनात्मकता और हँसी से जीतिए।', body_id = 'Saat masuk kamar, Anda melihat seluruh tisu toilet terurai dan tersebar di rumah? Daripada kesal, kumpulkan tisu itu dan buatlah bola bersama. Kalahkan kekacauan bukan dengan berteriak, tapi dengan kreativitas dan tawa.', body_ja = '部屋に入ったら、トイレットペーパーが全部引き出されて家じゅうに広がっていた？怒るより、その紙を集めて一緒にボールをつくりましょう。カオスには叫び声ではなく、創造力と笑いで勝ちましょう。', body_ko = '방에 들어갔더니 두루마리 휴지가 전부 풀려 온 집에 퍼져 있나요? 화내기보다 그 휴지를 모아 함께 공을 만들어 보세요. 혼돈은 고함이 아니라 창의력과 웃음으로 이기는 거예요.', body_nl = 'Kwam je de kamer in en zag je dat al het wc-papier was afgerold en door het huis lag? Word niet boos, maar maak er samen een bal van. Win van de chaos niet met schreeuwen, maar met creativiteit en gelach.', body_pl = 'Wchodzisz do pokoju i widzisz, że cały papier toaletowy jest rozwinięty i rozwleczony po domu? Zamiast się złościć, zbierzcie razem ten papier i zróbcie z niego kulę. Wygraj z chaosem nie krzykiem, tylko kreatywnością i śmiechem.', body_pt = 'Ao entrar no quarto, viu o rolo de papel higiénico todo desenrolado e espalhado pela casa? Em vez de se irritar, apanhem o papel e façam juntos uma bola. Vença o caos não aos gritos, mas com criatividade e riso.', body_sv = 'Kom du in i rummet och såg att hela toarullen var avrullad och spridd över huset? I stället för att bli arg, samla ihop pappret och gör en boll tillsammans. Besegra kaoset med kreativitet och skratt, inte med skrik.', body_vi = 'Bước vào phòng, mẹ thấy cả cuộn giấy vệ sinh bị tháo tung khắp nhà? Thay vì bực mình, hãy cùng bé gom giấy lại và vo thành quả bóng. Hãy chiến thắng hỗn loạn không phải bằng tiếng quát, mà bằng sự sáng tạo và tiếng cười.', body_zh = '走进房间，发现整卷卫生纸都被拉开铺满了家？与其生气，不如一起把纸收起来，团成一个球。战胜混乱靠的不是吼叫，而是创意和笑声。' WHERE id = '417e0bcc-cf3b-4a96-95e9-58a2f51764f6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El placer del silencio 🤫', body_es = 'Por fin se ha dormido. ¿Hay tanto silencio en casa que te pitan los oídos? Abre el Medidor de sonido en la app. Ver ese 0 decibelios será el mejor masaje visual del mundo para tu cerebro cansado y saturado de ruido.', title_fr = 'Le plaisir du silence 🤫', body_fr = 'Il dort enfin. Un tel silence est tombé sur la maison que vos oreilles bourdonnent ? Ouvrez le Sonomètre dans l''application. Voir afficher 0 décibel sera le meilleur massage visuel au monde pour votre cerveau fatigué, saturé de bruit.', title_hi = 'खामोशी का मज़ा 🤫', body_hi = 'आखिरकार सो गया। घर में ऐसा सन्नाटा छा गया कि कानों में सीटी सी बज रही है? ऐप में साउंड मीटर खोलिए। वह ‘0 डेसिबल’ देखना आपके थके, शोर से भरे दिमाग के लिए दुनिया की सबसे अच्छी विज़ुअल मसाज होगी।', title_id = 'Nikmatnya keheningan 🤫', body_id = 'Akhirnya ia tidur. Rumah begitu hening sampai telinga Anda berdenging? Buka Pengukur Suara di aplikasi. Melihat tulisan 0 desibel itu akan menjadi pijatan visual terbaik di dunia untuk otak Anda yang lelah dan penuh kebisingan.', title_ja = '静けさのごほうび 🤫', body_ja = 'やっと寝てくれた。家が静かすぎて耳鳴りがする？アプリで「サウンドメーター」を開いてみて。0デシベルの表示を見ることが、疲れて騒音でいっぱいの頭にとって、世界一の目のマッサージになります。', title_ko = '고요가 주는 기쁨 🤫', body_ko = '드디어 잠들었어요. 집이 너무 고요해져 귀가 울릴 정도인가요? 앱에서 소음 측정기를 열어 보세요. 0 데시벨이라는 숫자를 보는 것만으로 소음에 지친 머리에 세상에서 가장 좋은 시각적 마사지가 될 거예요.', title_nl = 'Het genot van stilte 🤫', body_nl = 'Eindelijk slaapt hij. Is het zo stil in huis dat je oren suizen? Open de Geluidsmeter in de app. Kijken naar die 0 decibel is de beste visuele massage voor je vermoeide, door lawaai overprikkelde brein.', title_pl = 'Przyjemność, jaką daje cisza 🤫', body_pl = 'Wreszcie zasnął. W domu zapadła taka cisza, że aż dzwoni ci w uszach? Otwórz w aplikacji Miernik dźwięku. Widok napisu 0 decybeli będzie dla twojego zmęczonego, przeładowanego hałasem mózgu najlepszym wizualnym masażem na świecie.', title_pt = 'O prazer do silêncio 🤫', body_pt = 'Finalmente adormeceu. Caiu um silêncio tão grande na casa que lhe zumbem os ouvidos? Abra o Medidor de Som na app. Olhar para aqueles 0 decibéis será a melhor massagem visual do mundo para o seu cérebro cansado e inchado de barulho.', title_sv = 'Njutningen av tystnad 🤫', body_sv = 'Äntligen sover barnet. Det har blivit så tyst hemma att det ringer i öronen? Öppna Ljudmätaren i appen. Att titta på 0 decibel blir världens bästa visuella massage för din trötta, bullerfyllda hjärna.', title_vi = 'Niềm vui của sự im lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ. Nhà yên tĩnh đến mức tai mẹ ù đi? Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số 0 decibel sẽ là màn mát-xa thị giác tuyệt vời nhất cho bộ não mệt mỏi, căng thẳng vì tiếng ồn của mẹ.', title_zh = '安静带来的享受 🤫', body_zh = '终于睡着了。家里安静得让你耳朵都嗡嗡响？打开应用里的分贝仪。看着那个0分贝，对你疲惫、被噪音塞满的大脑来说，就是世界上最好的视觉按摩。' WHERE id = '4a1de341-603c-4aae-ab4d-439d7bb05d7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La taza es del color equivocado 🥤', body_es = '¿Se ha armado una buena porque le has dado el agua en el vaso amarillo? No le des más vueltas, esta mañana solo está poniendo a prueba sus límites. Échale el agua en el vaso azul en un segundo, pon paz en la habitación y guarda tu energía.', title_fr = 'La couleur du verre n''est pas la bonne 🥤', body_fr = 'C''est l''apocalypse parce que vous avez servi l''eau dans le verre jaune ? Ne cherchez pas plus loin, il teste juste ses limites ce matin. Versez aussitôt l''eau dans le verre bleu, rétablissez la paix et préservez votre énergie.', title_hi = 'कप का रंग गलत है 🥤', body_hi = 'पानी पीले गिलास में दिया, इसलिए कमरे में तूफ़ान आ गया? ज़्यादा मत सोचिए, वह बस आज सुबह अपनी सीमाएँ परख रहा है। फ़ौरन पानी नीले गिलास में डाल दीजिए, कमरे में शांति लौटाइए और अपनी ऊर्जा बचाइए।', title_id = 'Warna cangkirnya salah 🥤', body_id = 'Kiamat terjadi di kamar karena Anda memberinya air di gelas kuning? Jangan terlalu dipikirkan, ia hanya sedang menguji batasannya pagi ini. Segera tuang airnya ke gelas biru, kembalikan kedamaian di kamar, dan simpan energi Anda.', title_ja = 'コップの色がちがう 🥤', body_ja = '黄色いコップでお水を出したから、部屋は大さわぎ？深く考えないで。今朝は境界線をためしているだけです。すぐに青いコップに入れなおして部屋に平和をとり戻し、エネルギーを守りましょう。', title_ko = '컵 색깔이 틀렸어 🥤', body_ko = '물을 노란 컵에 줬다고 방이 난리가 났나요? 깊이 생각하지 마세요, 오늘 아침 경계를 시험하는 것뿐이에요. 바로 파란 컵에 물을 옮겨 담아 평화를 되찾고 에너지를 아끼세요.', title_nl = 'De beker heeft de verkeerde kleur 🥤', body_nl = 'Breekt de hel los omdat je zijn water in een gele beker gaf? Denk er niet te veel over na, hij test vanochtend gewoon zijn grenzen. Schenk het water meteen in een blauwe beker, breng de vrede terug en spaar je energie.', title_pl = 'Kubek ma zły kolor 🥤', body_pl = 'W pokoju wybuchła awantura, bo podałaś wodę w żółtym kubku? Nie analizuj, on po prostu sprawdza dziś rano granice. Od razu przelej wodę do niebieskiego kubka, przywróć spokój i oszczędzaj energię.', title_pt = 'O copo é da cor errada 🥤', body_pt = 'Caiu o Carmo e a Trindade porque lhe deu a água num copo amarelo? Não pense demasiado: esta manhã está só a testar limites. Deite logo a água num copo azul, restabeleça a paz no quarto e poupe a sua energia.', title_sv = 'Fel färg på muggen 🥤', body_sv = 'Utbryter världens undergång för att du serverade vattnet i det gula glaset? Gå inte på djupet, barnet testar bara sina gränser i morse. Häll genast över vattnet i det blå glaset, skapa fred i rummet och spara din energi.', title_vi = 'Màu cốc sai rồi 🥤', body_vi = 'Cả phòng như "tận thế" chỉ vì mẹ đưa nước bằng cốc màu vàng? Đừng nghĩ nhiều, sáng nay bé chỉ đang thử giới hạn thôi. Rót ngay nước sang cốc màu xanh, lập lại hòa bình trong phòng và giữ sức nhé.', title_zh = '杯子颜色不对 🥤', body_zh = '因为用黄杯子倒水，房间里就闹翻天了？别想太多，宝宝只是在今早试探你的底线。马上把水倒进蓝杯子，让房间恢复和平，保存你的精力。' WHERE id = '3d9dcc3e-1698-4fca-951e-a58aed0724d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo abrazarlo contra tu pecho 🫂', body_es = '¿Hoy te ha vuelto loca de verdad y te ha dejado sin energía? Pero duerme en la cama con tanta inocencia... Apaga las luces, no leas cuento. Túmbate a su lado, respira hondo ese olor limpio de niño y da gracias.', title_fr = 'Simplement le serrer contre vous 🫂', body_fr = 'Aujourd''hui, il vous a vraiment rendue folle et a aspiré toute votre énergie ? Mais il dort si innocemment dans son lit... Éteignez la lumière, ne lisez pas de conte. Allongez-vous près de lui, respirez profondément cette pure odeur d''enfant et soyez reconnaissante.', title_hi = 'बस सीने से लगा लेना 🫂', body_hi = 'आज उसने सच में आपको पागल कर दिया, सारी ऊर्जा निचोड़ ली? पर बिस्तर पर कितना मासूम सो रहा है... लाइटें बंद कीजिए, कहानी मत पढ़िए। उसके पास लेटिए, उस मासूम बच्चे की खुशबू गहरी साँसों में भरिए और शुक्रिया कहिए।', title_id = 'Cukup dekap di dada 🫂', body_id = 'Hari ini ia benar-benar membuat Anda pusing dan menyedot energi Anda? Tapi ia tidur begitu polos di tempat tidurnya... Matikan lampu, tak perlu membacakan dongeng. Berbaringlah di sampingnya, hirup dalam-dalam aroma anak yang bersih itu, dan bersyukurlah.', title_ja = 'ただ胸に抱きしめて 🫂', body_ja = '今日は本当に振りまわされて、エネルギーを吸いとられた？でも、ベッドではこんなに無邪気に眠っている…。明かりを消して、絵本はお休み。そばに横になって、子どもの清らかなにおいを深く吸いこみ、感謝しましょう。', title_ko = '그냥 꼭 안아 주기 🫂', body_ko = '오늘 정말 미칠 것 같고 에너지를 다 빼앗겼나요? 그래도 침대에선 저렇게 순하게 자고 있죠... 불을 끄고 동화도 읽지 마세요. 옆에 누워 그 깨끗한 아이 냄새를 깊이 들이마시고 감사하세요.', title_nl = 'Hem gewoon tegen je aan drukken 🫂', body_nl = 'Heeft hij je vandaag echt gek gemaakt en al je energie opgezogen? Maar hij ligt zo onschuldig in bed... Doe het licht uit, lees geen verhaaltje voor. Ga naast hem liggen, snuif diep die zuivere kindergeur op en wees dankbaar.', title_pl = 'Po prostu przytul go do piersi 🫂', body_pl = 'Dziś naprawdę doprowadził cię do szału i wyssał z ciebie energię? A jednak śpi w łóżku tak niewinnie... Zgaś światło, nie czytaj bajki. Połóż się obok, głęboko wdychaj ten czysty dziecięcy zapach i bądź wdzięczna.', title_pt = 'Apenas apertá-lo contra o peito 🫂', body_pt = 'Hoje deu-lhe mesmo cabo da cabeça e sugou-lhe a energia? Mas está a dormir na cama tão inocente... Apague as luzes, não leia histórias. Deite-se ao lado dele, respire fundo aquele cheirinho puro de criança e agradeça.', title_sv = 'Bara hålla barnet tätt intill dig 🫂', body_sv = 'Gjorde barnet dig verkligen galen i dag och sög ut all energi? Men i sängen ligger hen så oskyldigt... Släck lamporna, läs ingen saga. Lägg dig bredvid, andas djupt in den rena barndoften och var tacksam.', title_vi = 'Chỉ cần ôm bé vào lòng 🫂', body_vi = 'Hôm nay bé thật sự làm mẹ phát điên, rút cạn sức lực? Nhưng lúc này bé nằm ngủ trên giường thật ngây thơ... Hãy tắt đèn, bỏ qua truyện. Nằm xuống cạnh bé, hít thật sâu mùi hương trẻ thơ trong trẻo ấy và biết ơn.', title_zh = '就这样抱在怀里 🫂', body_zh = '今天宝宝真的快把你逼疯了，耗尽了你的能量？可躺在床上的样子又那么天真……关上灯，今天不讲故事。躺在宝宝身边，深深吸一口那纯净的孩子气息，心怀感恩吧。' WHERE id = '522145b2-4826-4821-80c0-e0e180045415' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las historias de otras mamás 💬', body_es = '¡No te desanimes al abrir Instagram y ver los niños perfectos de todo el mundo! Cierra esa app y entra en la Comunidad Anacan. Verás que en todas las casas hay el mismo desorden que en la tuya: respira hondo.', title_fr = 'Les histoires des autres mamans 💬', body_fr = 'Ne vous découragez pas en voyant les enfants parfaits de tout le monde dès que vous ouvrez Instagram ! Fermez cette appli et rejoignez la Communauté Anacan. Voyez que chez les autres aussi, la maison est sens dessus dessous, et respirez profondément.', title_hi = 'दूसरी माँओं की कहानियाँ 💬', body_hi = 'इंस्टाग्राम खोलते ही सबके परफ़ेक्ट बच्चे देखकर हिम्मत मत हारिए! वह ऐप बंद कीजिए और Anacan कम्युनिटी में आइए। देखिए कि सबके घर आपके घर जैसे ही बिखरे हैं, और गहरी साँस लीजिए।', title_id = 'Kisah ibu-ibu lain 💬', body_id = 'Jangan patah semangat melihat anak-anak sempurna orang lain begitu membuka Instagram! Tutup aplikasinya, masuk ke Komunitas Anacan. Lihat bahwa rumah semua orang berantakan seperti rumah Anda, lalu tarik napas dalam.', title_ja = 'ほかのママたちのお話 💬', body_ja = 'インスタを開くたびに、みんなの完璧な子どもを見て落ちこまないで！そのアプリは閉じて、Anacanコミュニティへ。どの家もあなたの家のように散らかっているのを見て、深呼吸しましょう。', title_ko = '다른 엄마들의 이야기 💬', body_ko = '인스타그램을 열자마자 다들 완벽한 아이만 보여서 기운 빠지나요? 그 앱은 닫고 Anacan 커뮤니티에 들어가 보세요. 다들 집이 엄마 집처럼 엉망이라는 걸 보고 깊게 숨 쉬세요.', title_nl = 'De verhalen van andere mama''s 💬', body_nl = 'Raak niet ontmoedigd als je op Instagram ieders perfecte kinderen ziet! Sluit die app en ga naar de Anacan Community. Zie dat bij iedereen het huis net zo''n rommel is als bij jou, en haal diep adem.', title_pl = 'Historie innych mam 💬', body_pl = 'Nie trać ducha, gdy tylko otworzysz Instagram i zobaczysz same idealne dzieci! Zamknij tę aplikację i wejdź do Społeczności Anacan. Zobacz, że u innych w domu jest taki sam bałagan jak u ciebie, i weź głęboki oddech.', title_pt = 'As histórias de outras mães 💬', body_pt = 'Não desanime ao ver os filhos perfeitos de toda a gente mal abre o Instagram! Feche essa app e entre na Comunidade Anacan. Ao ver que as casas dos outros estão tão desarrumadas como a sua, respire fundo.', title_sv = 'Andra mammors berättelser 💬', body_sv = 'Bli inte nedslagen av att se allas perfekta barn så fort du öppnar Instagram! Stäng appen och gå in i Anacan Community. Se att alla andras hem är lika stökiga som ditt och andas djupt.', title_vi = 'Câu chuyện của các mẹ khác 💬', body_vi = 'Đừng nản lòng khi vừa mở Instagram đã thấy những đứa trẻ hoàn hảo của mọi người! Hãy đóng ứng dụng đó lại và vào Cộng đồng Anacan. Thấy nhà ai cũng bừa bộn như nhà mình, mẹ hãy hít một hơi thật sâu.', title_zh = '其他妈妈的故事 💬', body_zh = '一打开Instagram就看到别人家完美的孩子，别灰心！关掉那个应用，来Anacan社区吧。看到大家家里都和你家一样乱，深呼吸一下。' WHERE id = '792e3525-032e-4662-ba49-1276a3b3ef78' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La independencia de «¡No me cojas la mano!» 🚶‍♂️', body_es = '¿Por el camino te suelta la mano y quiere ir libre? Si es una zona segura, deja que ponga a prueba su independencia. Tú solo sigue con orgullo, dos pasos por detrás, a este pequeño rebelde libre.', title_fr = 'L''indépendance du « Me tiens pas la main ! » 🚶‍♂️', body_fr = 'Dans la rue, il lâche votre main et veut marcher librement ? Si la zone est sûre, laissez-le tester son indépendance. Suivez simplement, deux pas derrière, ce petit rebelle libre, avec fierté.', title_hi = '‘मेरा हाथ मत पकड़ो!’ वाली आत्मनिर्भरता 🚶‍♂️', body_hi = 'रास्ते में हाथ छुड़ाकर आज़ाद चलना चाहता है? अगर जगह सुरक्षित है, तो उसे अपनी आत्मनिर्भरता परखने दीजिए। आप बस दो कदम पीछे से इस नन्हे, आज़ाद बागी को गर्व से देखिए।', title_id = 'Kemandirian ''Jangan pegang tanganku!'' 🚶‍♂️', body_id = 'Di jalan ia melepaskan tangan Anda dan ingin berjalan bebas? Kalau areanya aman, biarkan ia menguji kemandiriannya. Anda cukup mengikuti si pemberontak kecil yang bebas ini dengan bangga dua langkah di belakang.', title_ja = '「手をつながないで！」の自立 🚶‍♂️', body_ja = '道で手をはなして、自由に歩きたがる？安全な場所なら、自立をためさせてあげましょう。あなたは2歩うしろから、この小さな自由な反逆者を誇らしく見守るだけでOK。', title_ko = '''손 잡지 마!'' 독립 선언 🚶‍♂️', body_ko = '길에서 손을 놓고 혼자 걷고 싶어 하나요? 안전한 곳이라면 독립심을 시험하게 두세요. 엄마는 두 걸음 뒤에서 이 작고 자유로운 반항아를 뿌듯하고 자랑스럽게 지켜봐 주세요.', title_nl = 'Zelfstandig: ''Niet mijn hand vasthouden!'' 🚶‍♂️', body_nl = 'Laat hij onderweg je hand los en wil hij zelf lopen? Is het een veilige plek, laat hem dan zijn zelfstandigheid testen. Loop gewoon twee stappen achter deze kleine, vrije rebel en kijk trots toe.', title_pl = 'Samodzielność „Nie trzymaj mnie za rękę!” 🚶‍♂️', body_pl = 'Na spacerze puszcza twoją rękę i chce iść sam? Jeśli to bezpieczna strefa, niech sprawdzi swoją samodzielność. Ty po prostu idź dwa kroki za nim i z dumą obserwuj tego małego, wolnego buntownika.', title_pt = 'A independência do "Não me dês a mão!" 🚶‍♂️', body_pt = 'Na rua larga-lhe a mão e quer andar sozinho? Se a zona for segura, deixe-o testar a sua independência. Limite-se a seguir, dois passos atrás e cheia de orgulho, este pequeno rebelde livre.', title_sv = 'Självständigheten i ”Håll mig inte i handen!” 🚶‍♂️', body_sv = 'Vill barnet släppa din hand och gå fritt på vägen? Om det är en säker zon, låt hen testa sin självständighet. Följ bara efter två steg bakom och titta stolt på den lilla, fria rebellen.', title_vi = 'Sự tự lập "Đừng nắm tay con!" 🚶‍♂️', body_vi = 'Trên đường, bé muốn buông tay mẹ và tự đi? Nếu là khu vực an toàn, hãy để bé thử sự tự lập của mình. Mẹ chỉ cần đi sau hai bước và tự hào ngắm "kẻ nổi loạn" nhỏ bé, tự do này.', title_zh = '“别牵我的手！”的独立 🚶‍♂️', body_zh = '走在路上，想松开你的手自己走？如果是安全的地方，就让宝宝试试自己的独立吧。你只要在后面两步远的地方，骄傲又自豪地看着这个自由的小“叛逆者”。' WHERE id = '3e4bbd84-ef8f-45a2-b630-5aeadd95390e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desastre de ayudarte en la cocina 🧑‍🍳', body_es = '¿Mientras estirabas la masa ha venido, ha puesto su silla y quería echar él la harina sí o sí? Si no le dejas, llorará. Dale un bol pequeño de plástico y un poco de harina. La cocina quedará hecha un desastre, pero su ego quedará satisfecho.', title_fr = 'La catastrophe de l''aide en cuisine 🧑‍🍳', body_fr = 'Pendant que vous étaliez la pâte, il a installé sa chaise et voulait absolument verser la farine lui-même ? Si vous refusez, il pleurera. Donnez-lui un petit bol en plastique et un peu de farine. La cuisine sera sens dessus dessous, mais son ego sera satisfait.', title_hi = 'रसोई में आपकी मदद वाली आफ़त 🧑‍🍳', body_hi = 'आप आटा बेल रही थीं, वह आकर अपनी कुर्सी लगा बैठा और आटा खुद ही डालना चाहता है? मना करेंगी तो रोएगा। उसे एक छोटा प्लास्टिक का कटोरा और थोड़ा आटा दे दीजिए। रसोई गंदी होगी, पर उसका अहं संतुष्ट होगा।', title_id = 'Bencana membantu di dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia datang membawa kursinya dan bersikeras menuang tepung sendiri? Kalau tidak diizinkan, ia akan menangis. Beri ia mangkuk plastik kecil dan sedikit tepung. Dapur akan belepotan, tapi egonya akan terpuaskan.', title_ja = 'キッチンのお手伝い大惨事 🧑‍🍳', body_ja = '生地をのばしていると、いすを持ってきて粉を自分で入れたがった？だめと言えば泣いてしまう。小さなプラスチックのボウルと少しの粉を渡しましょう。キッチンは粉だらけになりますが、プライドは満たされます。', title_ko = '주방 도우미 대참사 🧑‍🍳', body_ko = '반죽을 밀고 있는데 의자를 끌고 와서 꼭 밀가루를 자기가 붓겠다고 하나요? 허락하지 않으면 울 거예요. 작은 플라스틱 그릇과 밀가루를 조금 주세요. 부엌은 엉망이 되겠지만 자존심은 채워질 거예요.', title_nl = 'Rampenhulpje in de keuken 🧑‍🍳', body_nl = 'Was je deeg aan het uitrollen en zette hij zijn stoel ernaast om per se zelf de bloem te storten? Laat je het niet toe, dan gaat hij huilen. Geef hem een klein plastic bakje en wat bloem. De keuken wordt een ravage, maar zijn ego is tevreden.', title_pl = 'Katastrofalna pomoc w kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, przystawił krzesło i koniecznie chce sam wsypać mąkę? Jeśli nie pozwolisz, będzie płakał. Daj mu małą plastikową miskę i trochę mąki. Kuchnia będzie w mące, ale jego ego zostanie zaspokojone.', title_pt = 'O desastre de te ajudar na cozinha 🧑‍🍳', body_pt = 'Enquanto estendia a massa, ele pôs a cadeira ao seu lado e quis deitar a farinha sozinho? Se não deixar, vai chorar. Dê-lhe uma pequena taça de plástico e um pouco de farinha. A cozinha vai ficar um caos, mas o ego dele fica satisfeito.', title_sv = 'Katastrofhjälpen i köket 🧑‍🍳', body_sv = 'Kom barnet och ställde fram sin stol när du kavlade degen och ville absolut hälla i mjölet själv? Om du säger nej blir det gråt. Ge barnet en liten plastskål och lite mjöl. Köket blir nedsölat, men självkänslan blir nöjd.', title_vi = 'Thảm họa phụ bếp 🧑‍🍳', body_vi = 'Mẹ đang cán bột thì bé kê ghế lại và nhất định đòi tự đổ bột? Không cho thì bé sẽ khóc. Hãy đưa bé một chiếc bát nhựa nhỏ và ít bột. Căn bếp sẽ ngập bột, nhưng cái tôi của bé được thỏa mãn.', title_zh = '厨房小帮手大灾难 🧑‍🍳', body_zh = '你擀面团时，宝宝搬来椅子，非要自己倒面粉？不让就会哭。给宝宝一个小塑料碗和一点面粉吧。厨房会变得一团糟，但宝宝的自我会得到满足。' WHERE id = '6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La luna corre delante de nosotros 🌕', body_es = '¿Al volver en coche al atardecer mira por la ventana y dice «La luna nos sigue»? Cree que el universo gira a su alrededor. Sin romper su imaginación, únete al juego con un «¿Adónde vendrá con nosotros?».', title_fr = 'La lune court devant nous 🌕', body_fr = 'En rentrant en voiture le soir, il regarde par la fenêtre et dit « La lune nous suit » ? Il pense que l''univers tourne autour de lui. Sans briser son imagination, entrez dans le jeu : « Je me demande où elle va avec nous ? »', title_hi = 'चाँद हमारे आगे-आगे दौड़ रहा है 🌕', body_hi = 'शाम को गाड़ी से लौटते समय खिड़की से देखकर कहता है, ‘चाँद हमारा पीछा कर रहा है’? उसे लगता है कि पूरा ब्रह्मांड उसके इर्द-गिर्द घूमता है। उसकी कल्पना तोड़े बिना, ‘पता नहीं, हमारे साथ कहाँ जा रहा है?’ कहकर खेल में शामिल हो जाइए।', title_id = 'Bulan berlari di depan kita 🌕', body_id = 'Saat pulang naik mobil sore hari, ia melihat dari jendela dan berkata ''Bulannya mengikuti kita''? Ia mengira alam semesta berputar di sekelilingnya. Tanpa merusak imajinasinya, ikutlah bermain dengan berkata ''Kira-kira ia ikut kita ke mana ya?''', title_ja = 'お月さまが追いかけてくる 🌕', body_ja = '夕方、車で帰るとき窓の外を見て「お月さまがついてくる」と言う？宇宙が自分のまわりをまわっていると思っているんです。その想像力をこわさず、「わたしたちと一緒にどこへ行くのかな？」と言って遊びに加わりましょう。', title_ko = '달님이 앞에서 달려가 🌕', body_ko = '저녁에 차를 타고 돌아오며 창밖을 보고 ''달님이 우리를 따라와'' 하나요? 우주가 자기를 중심으로 돈다고 생각해요. 상상력을 깨지 말고 ''우리랑 어디까지 가려나?'' 하며 놀이에 함께하세요.', title_nl = 'De maan rent voor ons uit 🌕', body_nl = 'Kijkt hij ''s avonds in de auto naar buiten en zegt hij ''De maan volgt ons''? Hij denkt dat het heelal om hem draait. Breek zijn fantasie niet af en speel mee: ''Waar zou hij met ons naartoe gaan?''', title_pl = 'Księżyc biegnie przed nami 🌕', body_pl = 'Wieczorem, wracając autem, patrzy przez okno i mówi: „Księżyc nas śledzi”? Myśli, że wszechświat kręci się wokół niego. Nie burząc jego wyobraźni, włącz się w zabawę: „Ciekawe, dokąd z nami jedzie?”.', title_pt = 'A lua corre à nossa frente 🌕', body_pt = 'Ao fim da tarde, de regresso a casa de carro, olha pela janela e diz "A lua está a seguir-nos"? Acha que o universo gira à volta dele. Sem quebrar esta imaginação, entre no jogo: "Para onde é que ela vai connosco?"', title_sv = 'Månen springer framför oss 🌕', body_sv = 'Tittar barnet ut genom bilfönstret på kvällen och säger ”Månen följer efter oss”? Hen tror att universum kretsar kring hen. Utan att förstöra fantasin, säg ”Undrar vart den ska med oss?” och var med i leken.', title_vi = 'Mặt Trăng chạy trước mình 🌕', body_vi = 'Chiều tối trên xe về nhà, bé nhìn qua cửa sổ và nói "Mặt Trăng đi theo mình"? Bé nghĩ cả vũ trụ xoay quanh mình. Đừng phá vỡ trí tưởng tượng ấy, hãy cùng chơi: "Không biết Mặt Trăng đi cùng mình đến đâu nhỉ?"', title_zh = '月亮在我们前面跑 🌕', body_zh = '傍晚坐车回家时，看着窗外说“月亮在跟着我们”？宝宝觉得宇宙在围着自己转。别打破这份想象，说一句“它要跟我们去哪儿呢？”，加入这个游戏吧。' WHERE id = '776040ef-af05-4430-a752-3b380b194dba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por la camiseta sucia 👕', body_es = '¿Lleva 3 días con la misma camiseta y no te deja lavarla? A esta edad algunas cosas les dan seguridad. No discutas: quítasela con un cuento inventado como «La he mandado a una aventura mágica en la lavadora y volverá con más fuerza». Se creerá la ilusión.', title_fr = 'L''amour du t-shirt sale 👕', body_fr = 'Il porte le même t-shirt depuis 3 jours et refuse qu''on le lave ? À cet âge, certains objets les rassurent. Ne discutez pas : récupérez le t-shirt avec une petite histoire inventée, « Je l''ai envoyé dans une aventure magique dans la machine à laver, il reviendra plus fort ». Il croira à l''illusion.', title_hi = 'गंदी कमीज़ से प्यार 👕', body_hi = '3 दिन से वही कमीज़ पहन रहा है और धोने नहीं देता? इस उम्र में कुछ चीज़ें उन्हें भरोसा देती हैं। बहस मत कीजिए, ‘मैंने कमीज़ को वॉशिंग मशीन में जादुई सफ़र पर भेजा है, वह और ताकतवर होकर लौटेगी’ जैसी कहानी सुनाकर उसे ले लीजिए। वह इस भ्रम पर यकीन कर लेगा।', title_id = 'Cinta pada baju kotor 👕', body_id = 'Sudah 3 hari ia memakai baju yang sama dan tidak mengizinkannya dicuci? Di usia ini beberapa barang memberi mereka rasa aman. Jangan berdebat, ambil bajunya dengan dongeng karangan: ''Mama kirim bajunya ke petualangan ajaib di mesin cuci, nanti kembali lebih kuat''. Ia akan percaya pada ilusi ini.', title_ja = '汚れたシャツが大好き 👕', body_ja = '3日も同じシャツを着て、洗わせてくれない？この年齢では、あるものが安心をくれるんです。言い合いはせず、「シャツを洗濯機で魔法の冒険に送ったよ、強くなって帰ってくるからね」とお話をして受けとりましょう。イリュージョンを信じますよ。', title_ko = '더러운 티셔츠 사랑 👕', body_ko = '3일째 같은 티셔츠를 입고 빨지도 못하게 하나요? 이 나이엔 어떤 물건들이 안정감을 줘요. 다투지 말고 ''티셔츠를 세탁기 속 마법 모험에 보냈어, 더 힘이 세져서 돌아올 거야'' 하는 이야기로 받아 내세요. 아이는 그 상상을 믿을 거예요.', title_nl = 'Verliefd op een vies shirt 👕', body_nl = 'Draagt hij al 3 dagen hetzelfde shirt en mag het niet gewassen worden? Op deze leeftijd geven sommige spullen hem houvast. Ga niet in discussie, neem het af met een verzonnen sprookje: ''Ik heb het shirt op een magisch avontuur in de wasmachine gestuurd, het komt sterker terug.'' Hij gelooft in de illusie.', title_pl = 'Miłość do brudnej koszulki 👕', body_pl = 'Od 3 dni nosi tę samą koszulkę i nie pozwala jej wyprać? W tym wieku niektóre rzeczy dają dzieciom poczucie bezpieczeństwa. Nie kłóć się, zabierz ją z bajeczką: „Wysłałam koszulkę na magiczną przygodę w pralce, wróci silniejsza”. Uwierzy w tę iluzję.', title_pt = 'A paixão pela camisola suja 👕', body_pt = 'Há 3 dias que veste a mesma camisola e não deixa lavá-la? Nesta idade, algumas coisas dão-lhes segurança. Não discuta: tire-lha com uma história inventada, "Mandei a camisola numa aventura mágica na máquina de lavar, vai voltar mais forte". Ele vai acreditar na ilusão.', title_sv = 'Kärleken till den smutsiga tröjan 👕', body_sv = 'Har barnet haft samma tröja i 3 dagar och låter dig inte tvätta den? I den här åldern ger vissa saker trygghet. Bråka inte, säg ”Jag skickade tröjan på ett magiskt äventyr i tvättmaskinen, den kommer tillbaka ännu starkare” och ta den med en påhittad saga. Barnet tror på illusionen.', title_vi = 'Mê mẩn chiếc áo bẩn 👕', body_vi = 'Bé mặc cùng một chiếc áo 3 ngày liền và không cho giặt? Ở tuổi này, một số đồ vật mang lại cho bé cảm giác an toàn. Đừng tranh cãi, hãy kể một câu chuyện tưởng tượng: "Mẹ gửi áo vào máy giặt đi phiêu lưu kỳ diệu, nó sẽ trở về mạnh mẽ hơn" để lấy áo. Bé sẽ tin vào ảo ảnh ấy.', title_zh = '爱上脏衣服 👕', body_zh = '同一件衣服穿了3天，就是不让洗？这个年龄，有些物品能给孩子安全感。别争了，编一个小故事：“我把衣服送到洗衣机里去参加魔法冒险了，它会变得更厉害再回来。”然后把衣服拿走。宝宝会相信这个小魔术的。' WHERE id = '58e2fe84-f6c5-40ff-93ab-26ea06ad9f14' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Funeral por una hormiga 🐜', body_es = '¿En el parque ha visto una hormiga en el suelo y no se mueve, llorando porque se ha perdido? Su empatía no conoce límites. Dile: «Su mamá viene ahora a buscarla».', title_fr = 'Cérémonie de deuil pour une fourmi 🐜', body_fr = 'Au parc, il a vu une fourmi par terre et refuse de bouger, il pleure parce qu''elle s''est perdue ? Son empathie ne connaît pas de limites. Dites-lui : « Sa maman va venir la chercher. »', title_hi = 'चींटी के लिए शोक सभा 🐜', body_hi = 'पार्क में ज़मीन पर चींटी देखी, इसलिए हिल नहीं रहा, रो रहा है कि वह खो गई? उसकी हमदर्दी की कोई सीमा नहीं। कहिए, ‘उसकी माँ अभी आकर उसे ले जाएगी।’', title_id = 'Upacara duka untuk semut 🐜', body_id = 'Di taman ia melihat seekor semut di tanah dan tidak mau bergerak, menangis karena semutnya tersesat? Empatinya tak mengenal batas. Katakan ''Sebentar lagi mamanya datang menjemputnya''.', title_ja = 'アリさんのお葬式 🐜', body_ja = '公園で地面のアリを見て動かなくなり、迷子だと泣いている？共感力に限りはありません。「アリさんのママがすぐ迎えに来るよ」と言ってあげましょう。', title_ko = '개미를 위한 장례식 🐜', body_ko = '공원에서 개미를 보고는 길을 잃었다며 꼼짝 않고 우나요? 공감 능력에 한계가 없네요. ''개미 엄마가 곧 데리러 올 거야''라고 말해 주세요.', title_nl = 'Een rouwplechtigheid voor een mier 🐜', body_nl = 'Zag hij in het park een mier op de grond, beweegt hij niet meer en huilt hij omdat de mier verdwaald is? Zijn empathie kent geen grenzen. Zeg: ''Zijn mama komt hem zo halen.''', title_pl = 'Żałoba po mrówce 🐜', body_pl = 'W parku zobaczył na ziemi mrówkę, nie rusza się z miejsca i płacze, że się zgubiła? Jego empatia nie zna granic. Powiedz: „Jej mama zaraz przyjdzie i ją zabierze”.', title_pt = 'O funeral da formiga 🐜', body_pt = 'No parque viu uma formiga no chão e não sai do sítio, a chorar porque ela se perdeu? A empatia dele não conhece limites. Diga-lhe: "A mãe dela já vem buscá-la".', title_sv = 'Sorgceremoni för en myra 🐜', body_sv = 'Står barnet still i parken för att hen sett en myra på marken, och gråter för att den har gått vilse? Empatin känner inga gränser. Säg ”Dess mamma kommer snart och hämtar den”.', title_vi = 'Lễ tang cho chú kiến 🐜', body_vi = 'Ở công viên, thấy một chú kiến dưới đất, bé đứng im và khóc vì nó bị lạc? Lòng trắc ẩn của bé thật vô bờ. Hãy nói: "Mẹ của kiến sẽ đến đón nó ngay thôi."', title_zh = '为蚂蚁办的“葬礼” 🐜', body_zh = '在公园看到地上的一只蚂蚁，就站着不动，哭着说它迷路了？宝宝的同理心没有边界。就说：“它的妈妈马上就来接它了。”' WHERE id = 'b740d6be-007b-4aa6-9c46-6ffbce8b157e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ruido blanco en el pantano 🌊', body_es = '¿En lugar de dormir salta de un lado a otro de la habitación? Pon de fondo en el Medidor de sonido unas olas fuertes del mar o ruido blanco. Esa frecuencia monótona se llevará la energía loca de su cerebro y en 10 minutos se le cerrarán los ojos.', title_fr = 'Le bruit blanc du marais 🌊', body_fr = 'Au lieu de dormir, il saute partout dans la chambre ? Mettez avec le bruit de fond du Sonomètre un fort son de vagues ou un bruit blanc. Cette fréquence monotone emportera cette énergie folle dans son cerveau, et ses yeux se fermeront en 10 minutes.', title_hi = 'लहरों वाला व्हाइट नॉइज़ 🌊', body_hi = 'कमरे में सोने के बजाय इधर-उधर उछल रहा है? साउंड मीटर के बैकग्राउंड से तेज़ समुद्री लहरों या व्हाइट नॉइज़ की आवाज़ चलाइए। वह एक-सी धुन दिमाग की उस बेकाबू ऊर्जा को बहा ले जाएगी, 10 मिनट में उसकी आँखें बंद हो जाएँगी।', title_id = 'Suara putih di tengah kekacauan 🌊', body_id = 'Bukannya tidur, ia malah melompat ke sana kemari di kamar? Putar suara ombak laut yang kuat atau suara putih dari latar Pengukur Suara. Frekuensi yang monoton itu akan membasuh energi gila di otaknya, dan dalam 10 menit matanya akan terpejam.', title_ja = '荒れた夜にホワイトノイズ 🌊', body_ja = '部屋で寝るかわりに、あちこち飛びはねている？「サウンドメーター」の背景音から、力強い波の音やホワイトノイズを流しましょう。単調な周波数が頭の中のはちゃめちゃなエネルギーを洗い流し、10分で目が閉じます。', title_ko = '파도 같은 백색소음 🌊', body_ko = '방에서 자는 대신 이리저리 뛰어다니나요? 소음 측정기의 배경 소리에서 힘찬 파도 소리나 백색소음을 틀어 주세요. 그 단조로운 주파수가 머릿속의 넘치는 에너지를 씻어 내, 10분이면 눈이 감길 거예요.', title_nl = 'Witte ruis uit het moeras 🌊', body_nl = 'Springt hij in de kamer alle kanten op in plaats van te slapen? Zet via de achtergrond van de Geluidsmeter krachtige zeegolven of witte ruis aan. Die eentonige frequentie spoelt die gekke energie uit zijn hoofd weg, en binnen 10 minuten vallen zijn ogen dicht.', title_pl = 'Biały szum z bagien 🌊', body_pl = 'Zamiast spać, skacze po całym pokoju? Włącz w tle Miernika dźwięku mocny szum fal morskich albo biały szum. Ta monotonna częstotliwość zmyje z jego mózgu tę szaloną energię, a za 10 minut oczy same mu się zamkną.', title_pt = 'Ruído branco do pântano 🌊', body_pt = 'Em vez de dormir, salta de um lado para o outro no quarto? Ponha, no som de fundo do Medidor de Som, ondas do mar fortes ou ruído branco. Essa frequência monótona vai levar consigo toda aquela energia louca e em 10 minutos os olhos fecham-se.', title_sv = 'Vitt brus i träsket 🌊', body_sv = 'Hoppar barnet runt i rummet i stället för att sova? Sätt på kraftiga havsvågor eller vitt brus som bakgrundsljud i Ljudmätaren. Den monotona frekvensen sköljer bort den galna energin i hjärnan, och ögonen sluts inom 10 minuter.', title_vi = 'Tiếng ồn trắng của đầm lầy 🌊', body_vi = 'Thay vì ngủ, bé nhảy từ chỗ này sang chỗ khác trong phòng? Hãy bật tiếng sóng biển mạnh hoặc tiếng ồn trắng từ âm thanh nền của Đo âm thanh. Tần số đều đều ấy sẽ cuốn trôi nguồn năng lượng cuồng nhiệt trong đầu bé, 10 phút sau mắt bé sẽ khép lại.', title_zh = '吵闹中的白噪音 🌊', body_zh = '不在房间里睡觉，到处跳来跳去？在分贝仪的背景声里打开有力的海浪声或白噪音。那种单调的频率会冲走大脑里那股疯狂的能量，10分钟后眼睛就会合上。' WHERE id = 'fcc60573-09e9-4a7c-8399-55df532828cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una ayuda desastrosa con la escoba 🧹', body_es = '¿Cuando recoges la casa viene, dice «lo hago yo» y esparce aún más la basura por la habitación? Si no le dejas, se armará una buena. Dale una toallita húmeda y dile: «Tú solo te encargas de esta esquina de la mesa». Tú haces tu trabajo y su ego queda satisfecho.', title_fr = 'L''aide catastrophique au balai 🧹', body_fr = 'Quand vous rangez la maison, il vient dire « C''est moi qui fais ! » et étale encore plus les saletés dans la pièce ? Si vous refusez, ce sera l''apocalypse. Donnez-lui une lingette humide et dites « Toi, tu t''occupes seulement de ce coin de la table ». Vous faites votre travail, et son ego reste satisfait.', title_hi = 'झाड़ू वाली आफ़त भरी मदद 🧹', body_hi = 'आप घर समेट रही हैं और वह आकर ‘मैं करूँगा’ कहकर कूड़ा और फैला देता है? मना करेंगी तो हंगामा होगा। उसके हाथ में गीला कपड़ा दीजिए और कहिए, ‘तुम सिर्फ़ इस मेज़ के कोने के ज़िम्मेदार हो।’ आप अपना काम भी कर लेंगी और उसका अहं भी संतुष्ट रहेगा।', title_id = 'Bantuan sapu yang membawa bencana 🧹', body_id = 'Saat Anda membereskan rumah, ia datang berkata ''Aku yang kerjain'' dan malah menyebarkan sampah ke seluruh kamar? Kalau tidak diizinkan, kiamat akan terjadi. Beri ia tisu basah dan katakan ''Kamu hanya bertanggung jawab atas sudut meja ini''. Anda bisa menyelesaikan pekerjaan, egonya pun terpuaskan.', title_ja = 'ほうきでお手伝い大惨事 🧹', body_ja = '家を片づけていると「ぼくがやる」と来て、ゴミをもっと広げる？だめと言えば大さわぎ。ぬれたふきんを渡して「あなたはこのテーブルの角の担当ね」と言いましょう。あなたは自分の作業ができて、この子のプライドも満たされます。', title_ko = '빗자루로 하는 대참사 도움 🧹', body_ko = '청소하는데 ''내가 할래'' 하며 와서 쓰레기를 방에 더 퍼뜨리나요? 못 하게 하면 난리가 날 거예요. 젖은 물티슈를 주며 ''너는 이 식탁 모서리 담당이야'' 하고 말해 주세요. 엄마는 할 일을 하고 아이의 자존심도 채워져요.', title_nl = 'Rampzalige hulp met de bezem 🧹', body_nl = 'Komt hij als jij opruimt met ''Ik doe het'' en verspreidt hij de rommel nog verder door de kamer? Laat je het niet toe, dan breekt de hel los. Geef hem een vochtig doekje en zeg: ''Jij bent alleen verantwoordelijk voor dit hoekje van de tafel.'' Zo doe jij je werk en blijft zijn ego tevreden.', title_pl = 'Katastrofalna pomoc z miotłą 🧹', body_pl = 'Gdy sprzątasz, przychodzi z okrzykiem „ja to zrobię” i rozrzuca śmieci jeszcze bardziej? Jeśli nie pozwolisz, wybuchnie awantura. Daj mu wilgotną ściereczkę i powiedz: „Ty odpowiadasz tylko za ten róg stołu”. Ty zrobisz swoje, a jego ego będzie syte.', title_pt = 'Ajuda desastrosa com a vassoura 🧹', body_pt = 'Quando está a arrumar a casa, vem dizer "Eu faço!" e espalha o lixo ainda mais pelo quarto? Se não deixar, cai o Carmo e a Trindade. Dê-lhe um toalhete húmido e diga "Tu és responsável só por este canto da mesa". Assim a mãe faz o seu trabalho e o ego dele fica satisfeito.', title_sv = 'Katastrofhjälp med sopborsten 🧹', body_sv = 'När du städar kommer barnet, säger ”Jag gör det” och sprider skräpet ännu mer i rummet? Om du säger nej blir det världens undergång. Ge barnet en fuktig servett och säg ”Du har bara ansvar för det här hörnet av bordet”. Så kan du göra ditt, och barnets självkänsla blir mätt.', title_vi = 'Giúp quét nhà thành thảm họa 🧹', body_vi = 'Mẹ dọn nhà, bé chạy đến "Để con làm" rồi càng làm rác vương khắp phòng? Không cho thì "tận thế" sẽ nổ ra. Hãy đưa bé một chiếc khăn ẩm: "Con chỉ phụ trách góc bàn này thôi nhé." Mẹ làm xong việc, còn cái tôi của bé cũng được thỏa mãn.', title_zh = '拿着扫帚越帮越忙 🧹', body_zh = '你收拾屋子时，宝宝跑来说“我来”，结果把垃圾弄得满屋都是？不让就会闹翻天。递给宝宝一张湿巾，说“你只负责这张桌子的一角”。你能干活，宝宝的自我也得到满足。' WHERE id = '73abbd29-9b2f-4f48-8461-6482853b741f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de mirar la pared vacía 🛋️', body_es = '¿Está jugando solo en la habitación? ¡Ay, cariño, no gastes ese momento en fregar los platos! Siéntate en el sofá, coge tu té y solo mira la pared. Sí, sin pensar en nada. Escribe 5 minutos de paz en el Diario de ánimo. Lo necesitas.', title_fr = 'L''heure de contempler un mur vide 🛋️', body_fr = 'Il joue seul dans sa chambre ? Ma chérie, ne gaspillez pas ce moment à faire la vaisselle ! Allez sur le canapé, prenez votre thé et regardez simplement le mur. Oui, sans penser à rien. Écrivez 5 minutes de paix dans le Journal d''humeur. Vous en avez besoin.', title_hi = 'खाली दीवार निहारने का समय 🛋️', body_hi = 'कमरे में अकेले खेल रहा है? मेरी जान, वह पल बर्तन धोने में मत गँवाइए! सोफ़े पर जाइए, हाथ में चाय लीजिए और बस दीवार को देखिए। हाँ, बिना कुछ सोचे। मूड डायरी में 5 मिनट की शांति लिखिए। आपको इसकी ज़रूरत है।', title_id = 'Jam memandangi dinding kosong 🛋️', body_id = 'Ia bermain sendirian di kamar? Aduh sayang, jangan habiskan momen itu untuk mencuci piring! Pindah ke sofa, pegang teh Anda, dan cukup pandangi dinding. Ya, tanpa memikirkan apa pun. Tulis 5 menit kedamaian di Buku Harian Suasana Hati. Anda membutuhkannya.', title_ja = '何もない壁を眺める時間 🛋️', body_ja = '部屋でひとりで遊んでいる？その時間を食器洗いに使わないで！ソファに移って、お茶を手に、ただ壁を眺めましょう。そう、何も考えずに。「気分日記」に5分間の平和をひと言。あなたにはそれが必要です。', title_ko = '빈 벽 바라보기 시간 🛋️', body_ko = '방에서 혼자 놀고 있나요? 그 순간을 설거지에 쓰지 마세요! 소파로 가서 차를 들고 그냥 벽을 바라보세요. 네, 아무 생각 없이요. 기분 일기에 5분의 평화를 적어 보세요. 엄마에게 꼭 필요한 시간이에요.', title_nl = 'Tijd om naar een lege muur te staren 🛋️', body_nl = 'Speelt hij in zijn eentje in de kamer? Besteed dat moment alsjeblieft niet aan de afwas! Ga op de bank zitten, pak je thee en staar gewoon naar de muur. Ja, zonder iets te denken. Schrijf in je Stemmingsdagboek 5 minuten vrede op. Dit heb je nodig.', title_pl = 'Godzina patrzenia w pustą ścianę 🛋️', body_pl = 'Bawi się sam w pokoju? Błagam, nie wydawaj tej chwili na zmywanie! Usiądź na kanapie, weź herbatę i po prostu patrz w ścianę. Tak, o niczym nie myśląc. Zapisz w Dzienniku nastroju 5 minut spokoju. Potrzebujesz tego.', title_pt = 'Hora de olhar para a parede vazia 🛋️', body_pt = 'Está a brincar sozinho no quarto? Por favor, não gaste esse momento a lavar a loiça! Vá para o sofá, pegue no seu chá e fique só a olhar para a parede. Sim, sem pensar em nada. Escreva no Diário de Humor 5 minutos de paz. Precisa disto.', title_sv = 'Stunden att stirra på en tom vägg 🛋️', body_sv = 'Leker barnet själv i rummet? Älskade du, lägg inte den stunden på att diska! Gå till soffan, ta ditt te och titta bara på väggen. Ja, utan att tänka på någonting. Skriv 5 minuter av frid i Humördagboken. Det behöver du.', title_vi = 'Giờ ngắm bức tường trống 🛋️', body_vi = 'Bé đang tự chơi một mình trong phòng? Mẹ ơi, đừng dành khoảnh khắc ấy để đi rửa bát! Hãy ngồi xuống sofa, cầm tách trà và chỉ nhìn vào tường. Đúng vậy, không nghĩ gì cả. Ghi vào Nhật ký tâm trạng 5 phút bình yên. Mẹ cần điều đó.', title_zh = '盯着空墙发呆时间 🛋️', body_zh = '宝宝在房间里自己玩？亲爱的，别把这一刻花在洗碗上！去沙发上，端起你的茶，只是看着墙。是的，什么都不想。在心情日记里写下5分钟的平静。你需要这个。' WHERE id = 'eacaec53-45d2-4b70-9f52-8b48878bd78c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de «¡Se me ha roto el pelo!» 🪮', body_es = '¿En cuanto ve el peine sale corriendo diciendo que le duele el pelo? Su sensibilidad sensorial le asusta. Distráelo. Dale un espejo y dile «¿A ver quién saca la lengua más gracioso en el espejo?», y mientras está entretenido, péinalo en un segundo y listo.', title_fr = 'Le drame du « Mes cheveux se cassent ! » 🪮', body_fr = 'Dès qu''il voit le peigne, il dit que ses cheveux lui font mal et s''enfuit ? Sa sensibilité sensorielle lui fait peur. Détournez son attention. Donnez-lui un miroir et dites « Voyons qui tire la langue la plus drôle dans le miroir ? », et pendant qu''il est occupé, coiffez-le en une seconde, c''est fini.', title_hi = '‘मेरे बाल टूट गए!’ वाला ड्रामा 🪮', body_hi = 'कंघी देखते ही ‘बाल दुखते हैं’ कहकर भाग जाता है? संवेदी संवेदनशीलता उसे डराती है। उसका ध्यान भटकाइए। हाथ में आईना दीजिए, ‘चलो देखें, आईने में कौन ज़्यादा मज़ेदार जीभ निकालता है?’ कहिए और जब वह खेल में लगा हो, सेकंडों में बाल सँवारकर काम खत्म कीजिए।', title_id = 'Drama ''Rambutku patah!'' 🪮', body_id = 'Begitu melihat sisir, ia lari sambil berkata rambutnya sakit? Kepekaan sensoriknya membuatnya takut. Alihkan perhatiannya. Beri ia cermin, katakan ''Yuk lihat, siapa yang bisa melet paling lucu di cermin?'', dan selagi ia sibuk, sisir rambutnya dalam sekejap dan selesai.', title_ja = '「髪がこわれた！」ドラマ 🪮', body_ja = 'くしを見たとたん、髪が痛いと言って逃げる？感覚の敏感さがこわがらせているんです。気をそらしましょう。鏡を持たせて「鏡の中で、どっちがおもしろい顔で舌を出せるかな？」と言い、夢中になっている間にさっととかして終わりにしましょう。', title_ko = '''머리 끊어져!'' 드라마 🪮', body_ko = '빗만 보면 머리가 아프다며 도망가나요? 감각 예민함이 두렵게 하는 거예요. 관심을 돌려 주세요. 손거울을 주며 ''거울 보고 누가 더 웃기게 혀 내미나 볼까?'' 하고, 정신이 팔린 사이 얼른 빗어 끝내세요.', title_nl = 'Het ''Mijn haar is gebroken!''-drama 🪮', body_nl = 'Zegt hij zodra hij de kam ziet dat zijn haar pijn doet en rent hij weg? Zijn zintuiglijke gevoeligheid maakt hem bang. Leid zijn aandacht af. Geef hem een spiegel, zeg ''Wie steekt in de spiegel de gekste tong uit?'' en kam terwijl hij afgeleid is zijn haar in een seconde klaar.', title_pl = 'Dramat „Włos mi się złamał!” 🪮', body_pl = 'Gdy tylko zobaczy grzebień, mówi, że bolą go włosy, i ucieka? Wrażliwość sensoryczna go przeraża. Odwróć jego uwagę. Daj mu lusterko, zapytaj: „Zobaczmy, kto w lustrze pokaże śmieszniejszy język?” i gdy jest zajęty, w sekundę uczesz włosy i gotowe.', title_pt = 'O drama do "Partiu-se-me o cabelo!" 🪮', body_pt = 'Mal vê o pente, diz que lhe dói o cabelo e foge? A sensibilidade sensorial assusta-o. Distraia-o. Dê-lhe um espelho e diga "Vamos ver quem deita a língua de fora de forma mais cómica ao espelho?" e, enquanto está entretido, penteie-o num segundo e despache.', title_sv = 'Dramat ”Håret gick av!” 🪮', body_sv = 'Säger barnet att håret gör ont och springer iväg så fort hen ser kammen? Den sensoriska känsligheten skrämmer hen. Distrahera. Ge barnet en spegel och säg ”Vi ser vem som räcker ut tungan roligast i spegeln!”, och medan hen är upptagen kammar du håret på en sekund och är klar.', title_vi = 'Màn kịch "Tóc con gãy rồi!" 🪮', body_vi = 'Vừa thấy lược, bé đã kêu đau tóc và bỏ chạy? Sự nhạy cảm giác quan khiến bé sợ. Hãy đánh lạc hướng. Đưa bé chiếc gương: "Xem ai lè lưỡi trong gương buồn cười hơn nào?", và trong lúc bé mải chơi, chải tóc xong trong tích tắc.', title_zh = '“我的头发断了！”的闹剧 🪮', body_zh = '一看到梳子就说头发疼，跑开了？感官敏感让宝宝害怕。转移注意力吧。递给宝宝一面镜子，说“我们看看谁在镜子里吐舌头最搞笑？”，趁宝宝分心，几秒钟梳完头发。' WHERE id = 'f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Chantaje con la lista en el súper 🛒', body_es = '¿Delante de la caja de repente te ha exigido caramelos? Ignora por completo las miradas de «menuda madre» de los que están alrededor. Abre la Lista de la compra, dile «No está en la lista, la caja no nos lo va a vender» y mantente firme.', title_fr = 'Le chantage à la liste au supermarché 🛒', body_fr = 'Devant la caisse, il a soudain réclamé des bonbons ? Ignorez complètement les regards qui semblent dire « Quelle mère ! ». Ouvrez la Liste de courses, dites « Ce n''est pas sur la liste, la caisse ne nous le vendra pas » et restez ferme.', title_hi = 'सुपरमार्केट में लिस्ट वाली ब्लैकमेलिंग 🛒', body_hi = 'काउंटर के सामने अचानक टॉफ़ी माँगने लगा? आस-पास वालों की ‘कैसी माँ है’ वाली नज़रों की बिल्कुल परवाह मत कीजिए। शॉपिंग लिस्ट खोलिए, कहिए, ‘यह लिस्ट में नहीं है, काउंटर हमें यह नहीं बेचेगा’ और अपनी बात पर डटी रहिए।', title_id = 'Pemerasan daftar di supermarket 🛒', body_id = 'Di depan kasir ia tiba-tiba menuntut permen? Jangan pedulikan tatapan orang-orang yang seolah berkata ''Ibu macam apa ini''. Buka Daftar Belanja, katakan ''Ini tidak ada di daftar, kasirnya tidak akan menjualnya pada kita'' dan bersikaplah tegas.', title_ja = 'スーパーでリストを使った交渉 🛒', body_ja = 'レジの前で急にお菓子をねだった？まわりの「どんなママなの」という視線は気にしないで。「買い物リスト」を開いて「リストにないから、レジは売ってくれないよ」と言い、きっぱりした態度でいましょう。', title_ko = '마트에서 목록으로 협상하기 🛒', body_ko = '계산대 앞에서 갑자기 사탕을 사 달라고 했나요? ''저 엄마는 뭐 하나'' 하는 주변 시선은 신경 쓰지 마세요. 쇼핑 목록을 열고 ''목록에 없지? 계산대가 이건 안 팔아 줘'' 하며 단호하게 버티세요.', title_nl = 'Chantage met het boodschappenlijstje 🛒', body_nl = 'Eiste hij bij de kassa ineens snoep? Trek je helemaal niets aan van de blikken van omstanders die denken ''wat een moeder''. Open het Boodschappenlijstje, zeg ''Het staat er niet op, de kassa verkoopt het ons niet'' en houd voet bij stuk.', title_pl = 'Szantaż listą w sklepie 🛒', body_pl = 'Przed kasą nagle zażądał cukierków? Zupełnie nie przejmuj się spojrzeniami innych w stylu „co z niej za matka”. Otwórz Listę zakupów, powiedz: „Tego nie ma na liście, kasa nam tego nie sprzeda” i bądź stanowcza.', title_pt = 'A chantagem da lista no supermercado 🛒', body_pt = 'De repente exigiu um rebuçado em frente à caixa? Ignore por completo os olhares de "que mãe é esta" de quem está à volta. Abra a Lista de Compras, diga "Não está na lista, a caixa não nos vai vender isto" e mantenha-se firme.', title_sv = 'Listutpressning i affären 🛒', body_sv = 'Krävde barnet plötsligt godis framför kassan? Bry dig absolut inte om blickarna som säger ”vad är det för mamma”. Öppna Inköpslistan, säg ”Det står inte på listan, kassan säljer det inte till oss” och stå fast.', title_vi = '"Mặc cả" bằng danh sách ở siêu thị 🛒', body_vi = 'Bé bỗng đòi kẹo ngay trước quầy thu ngân? Tuyệt đối đừng bận tâm đến ánh mắt "mẹ kiểu gì thế" của người xung quanh. Mở Danh sách mua sắm và nói: "Không có trong danh sách, quầy thu ngân sẽ không bán cho mình đâu", rồi giữ vững lập trường.', title_zh = '超市里的清单“谈判” 🛒', body_zh = '在收银台前突然要糖果？完全不用在意旁人那种“这是什么妈妈”的眼神。打开购物清单，说：“清单里没有，收银台不会卖给我们的。”然后坚定立场。' WHERE id = '2127b5f4-7e9a-438e-9094-bd9d7f0d5237' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las pinturas se han desbordado a la pared 🖍️', body_es = '¿Has entrado en la habitación y has visto un nuevo fresco en la pared? Respira hondo. Ha superado los límites del papel y está probando su motricidad a gran escala. Antes de borrarla, hazle una foto a esta obra maestra para enseñársela en el futuro y reíros.', title_fr = 'Les couleurs ont débordé sur le mur 🖍️', body_fr = 'Vous êtes entrée dans la pièce et avez découvert une nouvelle fresque sur le mur ? Respirez profondément. Il dépasse les limites de la feuille et teste sa motricité à grande échelle. Avant d''effacer ce chef-d''œuvre, prenez-le absolument en photo pour le lui montrer plus tard et en rire.', title_hi = 'रंग दीवार तक पहुँच गए 🖍️', body_hi = 'कमरे में आईं और दीवार पर एक नई भित्तिचित्र कलाकृति देखी? गहरी साँस लीजिए। वह कागज़ की सीमाएँ पार करके बड़े पैमाने पर अपनी मोटर स्किल्स परख रहा है। मिटाने से पहले इस कलाकृति की फ़ोटो ज़रूर लीजिए, ताकि भविष्य में उसे दिखाकर हँस सकें।', title_id = 'Catnya meluber ke dinding 🖍️', body_id = 'Anda masuk kamar dan melihat lukisan dinding baru? Tarik napas dalam. Ia melampaui batas kertas dan menguji motoriknya dalam skala besar. Sebelum menghapusnya, jangan lupa memotret mahakarya ini supaya kelak bisa ditunjukkan kepadanya dan ditertawakan bersama.', title_ja = '絵の具が壁にはみ出した 🖍️', body_ja = '部屋に入ったら、壁に新しいフレスコ画が？深呼吸して。紙の枠をこえて、大きなスケールで運動能力をためしているんです。消す前に、将来見せて一緒に笑えるように、この傑作をぜひ写真に撮っておきましょう。', title_ko = '크레용이 벽까지 넘어왔어 🖍️', body_ko = '방에 들어갔더니 벽에 새 벽화가 생겼나요? 깊게 숨 쉬세요. 종이의 경계를 넘어 큰 규모로 운동 능력을 시험하는 중이에요. 지우기 전에 나중에 보여 주며 함께 웃을 수 있게 이 걸작은 꼭 사진으로 남겨 두세요.', title_nl = 'De verf ging over de muur 🖍️', body_nl = 'Kwam je de kamer in en zag je een nieuw fresco op de muur? Haal diep adem. Hij gaat over de grenzen van het papier en test zijn motoriek op grote schaal. Maak voor je het wegveegt beslist een foto van dit meesterwerk, om het hem later te laten zien en er samen om te lachen.', title_pl = 'Farby wylały się na ścianę 🖍️', body_pl = 'Weszłaś do pokoju i zobaczyłaś na ścianie nowy fresk? Weź głęboki oddech. Przekroczył granice kartki i sprawdza swoją motorykę na wielką skalę. Zanim to zmyjesz, koniecznie zrób zdjęcie temu arcydziełu, żeby w przyszłości pokazać mu je i się pośmiać.', title_pt = 'As cores passaram para a parede 🖍️', body_pt = 'Entrou no quarto e viu um fresco novo na parede? Respire fundo. Ele ultrapassou os limites do papel e está a testar a motricidade em grande escala. Antes de limpar, não deixe de fotografar esta obra-prima para um dia lha mostrar e se rirem juntos.', title_sv = 'Färgerna rann över på väggen 🖍️', body_sv = 'Kom du in i rummet och såg en ny fresk på väggen? Andas djupt. Barnet har gått utanför papprets gränser och testar motoriken i stor skala. Innan du torkar bort det, fotografera absolut mästerverket så att ni kan skratta åt det tillsammans i framtiden.', title_vi = 'Màu vẽ tràn lên tường 🖍️', body_vi = 'Bước vào phòng, mẹ thấy một bức bích họa mới trên tường? Hít thở thật sâu. Bé đang vượt khỏi giới hạn trang giấy để thử kỹ năng vận động ở quy mô lớn. Trước khi lau, nhớ chụp lại kiệt tác này để sau này cho bé xem và cùng cười nhé.', title_zh = '颜料画到了墙上 🖍️', body_zh = '走进房间，发现墙上多了一幅新“壁画”？深呼吸。宝宝正在突破纸张的边界，大尺度地测试自己的动作能力。擦掉之前，一定要给这幅杰作拍张照，以后拿给宝宝看，一起笑一笑。' WHERE id = '73af2e7a-1bb5-4576-8888-801050bfada3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La confirmación del silencio en la pantalla 📉', body_es = 'Por fin se ha dormido. ¿Todavía te retumban los gritos en los oídos? Abre el Medidor de sonido. Ver la línea de la habitación bajar a 0 decibelios será el masaje visual más bonito del mundo para tu cerebro cansado y saturado.', title_fr = 'La preuve du silence à l''écran 📉', body_fr = 'Il dort enfin. Les cris résonnent encore dans vos oreilles ? Ouvrez le Sonomètre. Regarder la courbe descendre à 0 décibel dans la pièce sera le plus beau massage visuel au monde pour votre cerveau fatigué et saturé.', title_hi = 'स्क्रीन पर खामोशी की पुष्टि 📉', body_hi = 'आखिरकार सो गया। कानों में अब भी चीखें गूँज रही हैं? साउंड मीटर खोलिए। कमरे में 0 डेसिबल तक उतरती लकीर देखना आपके थके, भारी दिमाग के लिए दुनिया की सबसे सुंदर विज़ुअल मसाज होगी।', title_id = 'Bukti keheningan di layar 📉', body_id = 'Akhirnya ia tidur. Telinga Anda masih berdenging oleh suara teriakan? Buka Pengukur Suara. Melihat garis yang turun ke 0 desibel di kamar akan menjadi pijatan visual terindah di dunia untuk otak Anda yang lelah dan penuh.', title_ja = '静けさを画面で確認 📉', body_ja = 'やっと寝てくれた。耳にはまだ叫び声が鳴りひびいている？「サウンドメーター」を開きましょう。部屋の0デシベルまで下がる線を眺めることが、疲れていっぱいいっぱいの頭にとって、世界一すてきな目のマッサージになります。', title_ko = '화면이 확인해 주는 고요 📉', body_ko = '드디어 잠들었어요. 귓가에 아직 고함 소리가 울리나요? 소음 측정기를 열어 보세요. 방 안의 선이 0 데시벨로 내려가는 걸 보는 게 지친 머리에 세상에서 가장 좋은 시각적 마사지가 될 거예요.', title_nl = 'Stilte bevestigd op het scherm 📉', body_nl = 'Eindelijk slaapt hij. Galmen de schreeuwen nog na in je oren? Open de Geluidsmeter. Kijken naar die lijn die in de kamer naar 0 decibel zakt, is de mooiste visuele massage voor je vermoeide, overvolle brein.', title_pl = 'Potwierdzenie ciszy na ekranie 📉', body_pl = 'Wreszcie zasnął. W uszach wciąż dzwonią ci krzyki? Otwórz Miernik dźwięku. Patrzenie, jak linia w pokoju opada do 0 decybeli, będzie najpiękniejszym wizualnym masażem na świecie dla twojego zmęczonego, przeładowanego mózgu.', title_pt = 'A confirmação do silêncio no ecrã 📉', body_pt = 'Finalmente adormeceu. Os gritos ainda lhe zumbem nos ouvidos? Abra o Medidor de Som. Ver aquela linha descer até aos 0 decibéis no quarto será a massagem visual mais bonita do mundo para o seu cérebro cansado e inchado.', title_sv = 'Tystnaden bekräftad på skärmen 📉', body_sv = 'Äntligen sover barnet. Ringer skriken fortfarande i öronen? Öppna Ljudmätaren. Att se linjen sjunka till 0 decibel i rummet blir världens finaste visuella massage för din trötta, överfulla hjärna.', title_vi = 'Màn hình xác nhận sự im lặng 📉', body_vi = 'Cuối cùng bé cũng ngủ. Tai mẹ vẫn còn văng vẳng tiếng la hét? Hãy mở Đo âm thanh. Nhìn đường biểu đồ trong phòng hạ xuống 0 decibel sẽ là màn mát-xa thị giác tuyệt vời nhất cho bộ não mệt mỏi, căng thẳng của mẹ.', title_zh = '屏幕上确认的安静 📉', body_zh = '终于睡着了。耳朵里还回响着尖叫声？打开分贝仪。看着那条降到0分贝的曲线，对你疲惫、被塞满的大脑来说，就是世界上最美好的视觉按摩。' WHERE id = 'f6ed5025-5dc3-4f4a-8ce2-d48478e2666f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento inventado de papá 🦸‍♂️', body_es = '¿Te has quedado sin voz y no te apetece leer el libro? Pásale el cuento a papá. Que cuente una historia inventada y absurda cuyo protagonista sea el propio peque. Túmbate y, mientras descansas, disfruta viendo cómo el peque se ríe a carcajadas con papá.', title_fr = 'Le conte inventé par papa 🦸‍♂️', body_fr = 'Vous n''avez plus de voix et pas envie de lire le livre ? Confiez le conte à papa. Qu''il raconte une histoire inventée et absurde dont le héros est l''enfant lui-même. Allongée, reposez-vous en regardant l''enfant éclater de rire avec son papa.', title_hi = 'पापा की गढ़ी हुई कहानी 🦸‍♂️', body_hi = 'आवाज़ नहीं निकल रही, किताब पढ़ने का मन नहीं? कहानी पापा को सौंप दीजिए। पापा एक गढ़ी हुई, बेतुकी कहानी सुनाएँ जिसका हीरो खुद बच्चा हो। आराम से लेटकर देखिए कि बच्चा पापा की बातों पर कैसे ठहाके लगाता है।', title_id = 'Dongeng karangan Ayah 🦸‍♂️', body_id = 'Suara Anda habis dan tidak ingin membacakan buku? Serahkan dongengnya kepada Ayah. Biarkan Ayah menceritakan kisah karangan yang absurd dengan tokoh utamanya si anak sendiri. Saksikan sambil berbaring dan beristirahat bagaimana anak tertawa terbahak-bahak bersama ayahnya.', title_ja = 'パパのつくり話 🦸‍♂️', body_ja = '声が出ない、絵本を読みたくない？お話はパパに渡しましょう。主人公が子ども自身の、おかしなつくり話をしてもらって。子どもがパパと大笑いするのを、横になってのんびり休みながら眺めましょう。', title_ko = '아빠가 지어낸 동화 🦸‍♂️', body_ko = '목소리도 안 나오고 책 읽기도 싫은가요? 동화는 아빠에게 넘기세요. 아이가 주인공인 엉뚱하고 말도 안 되는 이야기를 아빠가 지어내게 하세요. 엄마는 누워서 쉬며 아이가 아빠 이야기에 깔깔 웃는 모습을 지켜보세요.', title_nl = 'Papa''s verzonnen sprookje 🦸‍♂️', body_nl = 'Is je stem op en heb je geen zin om voor te lezen? Geef het sprookje aan papa. Laat hem een verzonnen, absurd verhaal vertellen met je kind zelf als hoofdpersoon. Lig lekker uit te rusten en kijk hoe je kind het uitschatert om papa.', title_pl = 'Wymyślona bajka taty 🦸‍♂️', body_pl = 'Nie masz głosu i nie chcesz czytać książki? Oddaj bajkę tacie. Niech tata opowie wymyśloną, absurdalną historię, w której głównym bohaterem jest samo dziecko. Odpoczywaj, leżąc pod ścianą, i patrz, jak dziecko zaśmiewa się z taty.', title_pt = 'A história inventada pelo pai 🦸‍♂️', body_pt = 'Ficou sem voz e não lhe apetece ler o livro? Passe a história ao pai. Que ele conte uma história inventada e absurda em que o herói principal é a própria criança. Deite-se a descansar e observe as gargalhadas que a criança dá com o pai.', title_sv = 'Pappas påhittade saga 🦸‍♂️', body_sv = 'Har du ingen röst kvar och vill inte läsa boken? Ge sagan till pappa. Låt pappa berätta en påhittad, absurd historia där barnet självt är huvudpersonen. Luta dig mot väggen, vila och se hur barnet gapskrattar åt pappa.', title_vi = 'Câu chuyện bố tự nghĩ ra 🦸‍♂️', body_vi = 'Mẹ khản giọng, không muốn đọc sách? Hãy giao câu chuyện cho bố. Để bố kể một câu chuyện tưởng tượng, vô lý mà nhân vật chính là bé. Còn mẹ nằm nghỉ và ngắm bé cười khanh khách cùng bố.', title_zh = '爸爸编的故事 🦸‍♂️', body_zh = '嗓子哑了，不想读书？把故事交给爸爸。让爸爸讲一个以宝宝自己为主角、天马行空又荒诞的故事。你就靠着墙躺下，一边休息一边看宝宝被爸爸逗得哈哈大笑。' WHERE id = '48318bc7-c4f3-4717-9848-18bd10967e29' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esta comida tiene mala forma 🥒', body_es = '¿Ha apartado el plato porque cortaste el pepino a lo largo y no en rodajas? Su estética alimentaria se está formando del todo. Aprende a disfrazar la misma verdura con figuras divertidas. En este juego de diseño vas a ganar tú.', title_fr = 'Ce plat a une mauvaise forme 🥒', body_fr = 'Il a repoussé son assiette parce que vous avez coupé le concombre en long et non en rondelles ? Son esthétique alimentaire se forme pleinement. Apprenez à déguiser le même légume en figurines amusantes. Vous gagnerez ce jeu de design.', title_hi = 'इस खाने का आकार खराब है 🥒', body_hi = 'खीरा गोल नहीं, लंबा काटा, इसलिए प्लेट धकेल दी? खाने का सौंदर्यबोध पूरी तरह बन रहा है। सीखिए कि उसी सब्ज़ी को मज़ेदार आकृतियों में कैसे छिपाएँ। डिज़ाइन के इस खेल में जीत आपकी होगी।', title_id = 'Bentuk makanan ini jelek 🥒', body_id = 'Ia menyingkirkan piringnya karena Anda memotong mentimun memanjang, bukan bulat? Estetika makanannya sedang terbentuk sepenuhnya. Pelajari cara menyamarkan sayur yang sama dalam bentuk-bentuk yang lucu. Anda akan menang dalam permainan desain ini.', title_ja = 'この食べもの、形がいや 🥒', body_ja = 'きゅうりを輪切りではなく細長く切ったから、お皿を押しのけた？食の美学がしっかり育っています。同じ野菜を楽しい形に変身させる方法を覚えましょう。このデザイン勝負には、あなたが勝てますよ。', title_ko = '이 음식 모양이 별로야 🥒', body_ko = '오이를 동그랗게가 아니라 길게 잘랐다고 접시를 밀어냈나요? 음식 미학이 완성되는 중이에요. 같은 채소를 재미있는 모양으로 변신시키는 법을 배워 보세요. 이 디자인 게임에서 엄마가 이길 거예요.', title_nl = 'Dit eten heeft de verkeerde vorm 🥒', body_nl = 'Duwde hij zijn bord weg omdat je de komkommer in lange reepjes sneed in plaats van rondjes? Zijn smaak voor hoe eten eruitziet is volop in ontwikkeling. Leer hoe je dezelfde groente als leuke figuurtjes vermomt. Dit designspel ga jij winnen.', title_pl = 'To jedzenie ma zły kształt 🥒', body_pl = 'Odsunął talerz, bo pokroiłaś ogórka w słupki, a nie w krążki? Jego estetyka jedzenia właśnie się kształtuje. Dowiedz się, jak zamaskować to samo warzywo w zabawnych kształtach. Wygrasz tę grę w design.', title_pt = 'Esta comida tem a forma errada 🥒', body_pt = 'Afastou o prato porque cortou o pepino às tiras e não às rodelas? A estética alimentar está em plena formação. Aprenda a disfarçar o mesmo legume em figuras divertidas. Vai ganhar este jogo de design.', title_sv = 'Den här maten har fel form 🥒', body_sv = 'Knuffade barnet bort tallriken för att du skar gurkan i stavar i stället för skivor? Matestetiken håller på att formas fullt ut. Lär dig att maskera samma grönsak i roliga figurer. Du kommer att vinna det här designspelet.', title_vi = 'Món này hình dạng không ổn 🥒', body_vi = 'Bé đẩy đĩa ra vì mẹ cắt dưa chuột thành que dài thay vì lát tròn? "Thẩm mỹ ăn uống" của bé đang hình thành rõ rệt. Hãy học cách "ngụy trang" cùng một loại rau thành những hình thù vui nhộn. Mẹ sẽ thắng trong trò chơi thiết kế này.', title_zh = '这个食物的形状不好 🥒', body_zh = '因为你把黄瓜切成了长条而不是圆片，就把盘子推开了？宝宝对食物的审美正在完全成形。学学怎样把同样的蔬菜伪装成有趣的造型。这场设计游戏，你一定会赢。' WHERE id = '4ac93f87-372d-4d1a-a449-a2da763a8227' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escaparse al baño para estar a solas 🛀', body_es = '¿Se te pega a las piernas todo el día y tienes el cuerpo entumecido de tanto contacto? Estar saturada de contacto (touched out) es real. Déjalo en la habitación, entra 5 minutos en el baño, cierra la puerta y solo respira. Necesitas recuperarte.', title_fr = 'S''échapper dans la salle de bain pour être seule 🛀', body_fr = 'Il s''accroche à vos jambes toute la journée, et votre corps est engourdi à force d''être touché ? Le « touched out », c''est réel. Laissez-le dans la pièce, entrez 5 minutes dans la salle de bain, fermez la porte et respirez simplement. Vous avez besoin de récupérer.', title_hi = 'अकेलेपन के लिए बाथरूम की ओर भागना 🛀', body_hi = 'दिनभर पैरों से लिपटा रहता है, छुए जाने से आपका शरीर सुन्न हो गया? ‘टच्ड आउट’ सच में होता है। उसे कमरे में छोड़कर 5 मिनट बाथरूम चली जाइए, दरवाज़ा बंद कीजिए और बस साँस लीजिए। आपको फिर से ऊर्जा चाहिए।', title_id = 'Kabur ke kamar mandi untuk menyendiri 🛀', body_id = 'Seharian ia menempel di kaki Anda, dan tubuh Anda mati rasa karena terus disentuh? Kelelahan disentuh (touched out) itu nyata. Tinggalkan ia di kamar, masuk ke kamar mandi selama 5 menit, tutup pintunya, dan cukup bernapas. Anda perlu memulihkan diri.', title_ja = 'ひとりになりにお風呂へ避難 🛀', body_ja = '一日じゅう足にしがみつかれて、さわられすぎて体がしびれた？タッチアウトは本当にあります。子どもを部屋に置いて5分だけお風呂場に入り、ドアを閉めて、ただ呼吸しましょう。あなたには回復が必要です。', title_ko = '혼자 있고 싶어 욕실로 도피 🛀', body_ko = '하루 종일 다리에 매달리고 만져져서 몸이 저리나요? 터치 피로(touched out)는 진짜예요. 아이를 방에 두고 5분만 욕실에 들어가 문을 닫고 그저 숨 쉬세요. 엄마에게도 회복이 필요해요.', title_nl = 'Naar de badkamer vluchten om alleen te zijn 🛀', body_nl = 'Hangt hij de hele dag aan je been en voelt je lichaam verdoofd van al het aanraken? Touched out is echt. Laat hem in de kamer, ga 5 minuten naar de badkamer, doe de deur dicht en adem gewoon. Je moet herstellen.', title_pl = 'Ucieczka do łazienki po samotność 🛀', body_pl = 'Cały dzień wisi ci na nodze i od dotyku zdrętwiało ci ciało? Przebodźcowanie dotykiem (touched out) jest prawdziwe. Zostaw go w pokoju, wejdź na 5 minut do łazienki, zamknij drzwi i po prostu oddychaj. Musisz się zregenerować.', title_pt = 'Fugir para a casa de banho para estar sozinha 🛀', body_pt = 'Passa o dia agarrado às suas pernas e o corpo já está dormente de tanto toque? O "touched out" é real. Deixe-o no quarto, entre 5 minutos na casa de banho, feche a porta e respire apenas. Precisa de recuperar.', title_sv = 'Flykt till badrummet för lite ensamtid 🛀', body_sv = 'Har barnet hängt i benen hela dagen och kroppen domnat av all beröring? Touched out är på riktigt. Lämna barnet i rummet, gå in i badrummet i 5 minuter, stäng dörren och andas bara. Du behöver återhämta dig.', title_vi = 'Trốn vào phòng tắm để được một mình 🛀', body_vi = 'Cả ngày bé bám chân, bị chạm vào nhiều đến tê cả người? "Touched out" là có thật. Hãy để bé trong phòng, vào phòng tắm 5 phút, đóng cửa lại và chỉ cần thở. Mẹ cần được hồi phục.', title_zh = '逃进浴室享受独处 🛀', body_zh = '一整天抱着你的腿，被碰得身体都麻了？“触碰疲劳”是真实存在的。让宝宝留在房间，你进浴室5分钟，关上门，只是呼吸。你需要恢复一下。' WHERE id = '61167ef0-dce7-4186-9b36-5aa8a00936ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ataque filosófico repentino 🤔', body_es = '¿De repente te ha hecho una pregunta científica como «¿Por qué el fondo del mar es oscuro?»? ¡Sin sudores! Abre Anacan AI, consigue la respuesta más tierna y de cuento, avalada por pediatras y psicólogos, que pueda entender a esta edad, y léesela. ¡Eres la mamá que siempre lo sabe todo!', title_fr = 'Attaque philosophique surprise 🤔', body_fr = 'Il a soudain posé une question scientifique : « Pourquoi le fond de la mer est noir ? » ? Pas de panique ! Ouvrez Anacan AI, obtenez la réponse féerique la plus douce, validée par des pédiatres et des psychologues et compréhensible à son âge, et lisez-la-lui. Vous êtes toujours la maman qui sait tout !', title_hi = 'अचानक फ़लसफ़े का हमला 🤔', body_hi = 'अचानक वैज्ञानिक सवाल पूछ लिया, ‘समुद्र की तली काली क्यों होती है?’ पसीना मत छोड़िए! Anacan AI खोलिए, इस उम्र के समझ में आने वाला सबसे प्यारा, बाल रोग विशेषज्ञ और मनोवैज्ञानिक द्वारा पुष्ट, परी-कथा जैसा जवाब लीजिए और उसे सुनाइए। आप हमेशा सब जानने वाली माँ हैं!', title_id = 'Serangan filsafat mendadak 🤔', body_id = 'Tiba-tiba ia bertanya pertanyaan ilmiah ''Kenapa dasar laut itu gelap?'' Jangan panik! Buka Anacan AI, dapatkan jawaban seperti dongeng yang paling manis, bisa dipahami usia ini, dan disetujui dokter anak serta psikolog, lalu bacakan untuknya. Anda selalu ibu yang tahu segalanya!', title_ja = '突然の哲学攻撃 🤔', body_ja = '「海の底はなんで黒いの？」と急に科学的な質問？あせらないで！Anacan AIを開いて、この年齢でも理解できる、小児科医と心理士が確認したいちばんかわいいお話風の答えを聞いて読んであげましょう。あなたはいつでも何でも知っているママです！', title_ko = '갑작스러운 철학 공격 🤔', body_ko = '''바닷속은 왜 까매?'' 하고 갑자기 과학 질문을 했나요? 진땀 흘리지 마세요! Anacan AI를 열어 이 나이가 이해할 수 있는, 소아과 의사와 심리학자가 확인한 가장 귀엽고 동화 같은 답을 받아 읽어 주세요. 엄마는 언제나 모든 걸 아는 엄마예요!', title_nl = 'Een plotselinge filosofieaanval 🤔', body_nl = 'Stelde hij ineens een wetenschappelijke vraag als ''Waarom is de bodem van de zee zwart?'' Geen paniek! Open Anacan AI, vraag het liefste, door kinderartsen en psychologen bevestigde sprookjesachtige antwoord dat past bij deze leeftijd, en lees het hem voor. Jij bent altijd de mama die alles weet!', title_pl = 'Nagły atak filozofii 🤔', body_pl = 'Nagle zadał naukowe pytanie: „Czemu dno morza jest czarne?”. Bez nerwów! Otwórz Anacan AI, uzyskaj najsłodszą, bajkową odpowiedź potwierdzoną przez pediatrów i psychologów, zrozumiałą w tym wieku, i mu ją przeczytaj. Zawsze jesteś mamą, która wie wszystko!', title_pt = 'Ataque repentino de filosofia 🤔', body_pt = 'Fez de repente uma pergunta científica: "Porque é que o fundo do mar é escuro?"? Não se aflija! Abra o Anacan AI, obtenha a resposta mais doce e encantada que esta idade consegue perceber, validada por pediatras e psicólogos, e leia-lha. É sempre a mãe que sabe tudo!', title_sv = 'Plötslig filosofiattack 🤔', body_sv = 'Ställde barnet plötsligt den vetenskapliga frågan ”Varför är havsbotten svart?” Svettas inte! Öppna Anacan AI, få det sötaste sagolika svaret som den här åldern kan förstå, godkänt av barnläkare och psykologer, och läs det för barnet. Du är alltid mamman som vet allt!', title_vi = 'Cơn "tấn công" triết lý bất ngờ 🤔', body_vi = 'Bé bất ngờ hỏi một câu khoa học: "Sao đáy biển lại tối?" Đừng toát mồ hôi! Hãy mở Anacan AI, lấy câu trả lời ngọt ngào, đậm chất cổ tích, được bác sĩ nhi khoa và chuyên gia tâm lý xác nhận, phù hợp với lứa tuổi này và đọc cho bé nghe. Mẹ luôn là người mẹ biết tuốt!', title_zh = '突如其来的哲学攻击 🤔', body_zh = '突然问了个科学问题：“海底为什么是黑的？”别慌！打开Anacan AI，找一个这个年龄能理解、儿科医生和心理学家认可的、最可爱的童话式回答，读给宝宝听。你永远是无所不知的妈妈！' WHERE id = '4c96a8e1-971d-4b98-9e5c-faff2c2726a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pilla-pilla en la habitación a oscuras 🔦', body_es = '¿Es hora de dormir, pero no se le acaba la energía? Apaga todas las luces de la habitación. Coge una linternita y jugad a «¿A ver a quién pilla la luz en la pared?». Jugar a oscuras acelerará la liberación de melatonina y además lo cansará.', title_fr = 'Chat perché dans la chambre sombre 🔦', body_fr = 'C''est l''heure de dormir, mais son énergie ne s''épuise pas ? Éteignez toutes les lumières de la chambre. Prenez une petite lampe de poche et jouez à « Voyons qui la lumière va attraper sur le mur ». Jouer dans le noir accélérera la sécrétion de mélatonine et le fatiguera.', title_hi = 'अंधेरे कमरे में पकड़म-पकड़ाई 🔦', body_hi = 'सोने का समय है, पर ऊर्जा खत्म नहीं हो रही? कमरे की सारी लाइटें बंद कीजिए। हाथ में छोटी टॉर्च लीजिए और ‘देखें, दीवार पर रोशनी किसे पकड़ती है’ वाला खेल खेलिए। अंधेरे में खेलना मेलाटोनिन बनना भी तेज़ करेगा और उसे थका भी देगा।', title_id = 'Kejar-kejaran di kamar gelap 🔦', body_id = 'Sudah waktunya tidur tapi energinya tak kunjung habis? Matikan semua lampu kamar. Ambil senter kecil dan mainkan ''Yuk lihat, cahayanya akan menangkap siapa di dinding''. Bermain dalam gelap akan mempercepat produksi melatonin sekaligus membuatnya lelah.', title_ja = '暗い部屋でおにごっこ 🔦', body_ja = '寝る時間なのにエネルギーが尽きない？部屋の明かりを全部消しましょう。小さな懐中電灯を持って「光が壁で誰をつかまえるかな」ゲームを。暗やみで遊ぶと、メラトニンの分泌が早まり、ほどよく疲れさせてくれます。', title_ko = '어두운 방에서 술래잡기 🔦', body_ko = '잘 시간인데 에너지가 끝이 없나요? 방 불을 모두 끄세요. 작은 손전등을 들고 ''불빛이 벽에서 누구를 잡을까?'' 놀이를 해 보세요. 어둠 속 놀이는 멜라토닌 분비를 앞당기고 아이를 지치게도 해 줘요.', title_nl = 'Tikkertje in de donkere kamer 🔦', body_nl = 'Is het bedtijd maar is zijn energie nog niet op? Doe al het licht in de kamer uit. Pak een klein zaklampje en speel ''Wie vangt het licht op de muur?'' Spelen in het donker versnelt de aanmaak van melatonine en maakt hem ook moe.', title_pl = 'Berek w ciemnym pokoju 🔦', body_pl = 'Pora spać, ale energia mu się nie kończy? Zgaś wszystkie światła w pokoju. Weź małą latarkę i zagraj w „Zobaczmy, kogo światło złapie na ścianie”. Zabawa w ciemności przyspieszy wydzielanie melatoniny i go zmęczy.', title_pt = 'Apanhada no quarto às escuras 🔦', body_pt = 'É hora de dormir, mas a energia não acaba? Apague todas as luzes do quarto. Pegue numa pequena lanterna e jogue a "Vamos ver quem a luz apanha na parede". Brincar no escuro vai acelerar a produção de melatonina e também cansá-lo.', title_sv = 'Kull i ett mörkt rum 🔦', body_sv = 'Det är läggdags men energin tar inte slut? Släck alla lampor i rummet. Ta en liten ficklampa och lek ”Vi ser vem ljuset fångar på väggen”. Att leka i mörkret både påskyndar melatoninet och tröttar ut barnet.', title_vi = 'Đuổi bắt trong phòng tối 🔦', body_vi = 'Đến giờ ngủ mà năng lượng của bé vẫn chưa cạn? Hãy tắt hết đèn trong phòng. Cầm một chiếc đèn pin nhỏ và chơi trò "Xem ánh đèn bắt được ai trên tường nào". Chơi trong bóng tối vừa giúp tiết melatonin nhanh hơn, vừa làm bé mệt.', title_zh = '黑暗房间里的你追我跑 🔦', body_zh = '到了睡觉时间，精力却用不完？把房间的灯全关掉。拿一支小手电筒，玩“看看光在墙上能抓住谁”的游戏。在黑暗中玩耍既能加快褪黑素分泌，也能让宝宝累下来。' WHERE id = '9f289ae7-fe30-4b1a-8ebd-63874521363d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sufrimiento de la herida invisible 🩹', body_es = '¿No tiene nada en el dedo, pero llora diciendo que le sangra y pide una tirita? No es dolor físico: necesita tu cariño. Ponle la tirita, dale un beso y dile «Te lo he curado con un beso mágico». Así se salvará el día.', title_fr = 'La souffrance de la blessure invisible 🩹', body_fr = 'Il n''a rien au doigt, mais pleure en disant qu''il saigne et réclame un pansement ? Ce n''est pas une douleur physique, il a besoin de votre tendresse. Collez le pansement, faites un bisou et dites « Je l''ai guéri avec un bisou magique ». Votre journée sera ainsi sauvée.', title_hi = 'अदृश्य घाव का दर्द 🩹', body_hi = 'उँगली पर कुछ भी नहीं है, पर ‘खून निकल रहा है’ कहकर रोता है और बैंडेज माँगता है? यह शारीरिक दर्द नहीं, उसे आपके प्यार और दुलार की ज़रूरत है। बैंडेज लगाइए, चूमिए और कहिए, ‘जादुई पप्पी से ठीक कर दिया।’ आपका दिन ऐसे ही बच जाएगा।', title_id = 'Derita luka tak kasatmata 🩹', body_id = 'Tidak ada apa-apa di jarinya, tapi ia menangis bilang berdarah dan minta plester? Ini bukan rasa sakit fisik, ia butuh kasih sayang dari Anda. Tempelkan plesternya, cium, dan katakan ''Mama sudah menyembuhkannya dengan ciuman ajaib''. Hari kalian pun terselamatkan.', title_ja = '見えない傷のいたみ 🩹', body_ja = '指には何もないのに「血が出た」と泣いて、ばんそうこうをほしがる？体の痛みではなく、あなたのいたわりが必要なんです。ばんそうこうを貼ってキスして、「魔法のキスで治したよ」と言いましょう。これで一日が救われます。', title_ko = '보이지 않는 상처의 고통 🩹', body_ko = '손가락에 아무것도 없는데 피가 났다며 울고 반창고를 달라고 하나요? 몸이 아픈 게 아니라 엄마의 다정함이 필요한 거예요. 반창고를 붙이고 뽀뽀하며 ''마법 뽀뽀로 다 나았어''라고 말해 주세요. 이렇게 하루가 구원받아요.', title_nl = 'De pijn van een onzichtbaar wondje 🩹', body_nl = 'Is er niets aan zijn vinger te zien, maar huilt hij dat hij bloedt en wil hij een pleister? Dit is geen lichamelijke pijn, hij heeft jouw medeleven nodig. Plak de pleister, geef er een kus op en zeg: ''Ik heb het genezen met een toverkus.'' Zo is jullie dag gered.', title_pl = 'Ból niewidzialnej rany 🩹', body_pl = 'Na palcu nic nie ma, ale płacze, że leci krew, i chce plaster? To nie fizyczny ból, potrzebuje twojej czułości. Naklej plaster, pocałuj i powiedz: „Wyleczyłam magicznym całusem”. Tak uratujecie dzień.', title_pt = 'O sofrimento da ferida invisível 🩹', body_pt = 'Não tem nada no dedo, mas chora a dizer que está a sangrar e pede um penso? Não é dor física, precisa do seu carinho. Cole o penso, dê-lhe um beijo e diga "Curei-o com um beijo mágico". O dia está salvo.', title_sv = 'Plågan från ett osynligt sår 🩹', body_sv = 'Det finns ingenting på fingret, men barnet gråter att det blöder och vill ha plåster? Det är inte fysisk smärta, hen behöver din omtanke. Sätt på plåstret, pussa och säg ”Jag har läkt det med en magisk puss”. Så är dagen räddad.', title_vi = 'Nỗi đau của vết thương vô hình 🩹', body_vi = 'Ngón tay chẳng có gì, nhưng bé khóc bảo bị chảy máu và đòi dán băng cá nhân? Đây không phải đau thể xác, bé cần sự vỗ về của mẹ. Hãy dán băng, hôn lên và nói "Mẹ chữa khỏi bằng nụ hôn thần kỳ rồi". Ngày của hai mẹ con sẽ được cứu như thế.', title_zh = '看不见的伤口之痛 🩹', body_zh = '手指上什么都没有，却哭着说流血了，要创可贴？这不是身体上的疼痛，宝宝需要的是你的关爱。贴上创可贴，亲一亲，说“我用魔法之吻把它治好了”。这一天就这样被拯救了。' WHERE id = 'd28d5d46-d2a6-4daa-b454-adbdf6be3f63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cerrar la puerta y el espacio personal 🚪', body_es = '¿Ha entrado en su habitación, ha cerrado la puerta y ha dicho «No entres»? No te lo tomes a mal. Solo quiere aislarse del ruido y del caos y descansar. Si todo es seguro, deja que disfrute de su espacio personal. ¡Está creciendo!', title_fr = 'Fermer la porte et l''espace personnel 🚪', body_fr = 'Il est entré dans sa chambre, a fermé la porte derrière lui et a dit « Viens pas » ? Ne vous vexez pas. Il veut simplement s''isoler du bruit et du chaos pour se reposer. Si la sécurité est assurée, laissez-le savourer cet espace personnel. Il grandit !', title_hi = 'दरवाज़ा बंद करना और अपनी जगह 🚪', body_hi = 'अपने कमरे में जाकर दरवाज़ा बंद कर लिया और बोला, ‘मत आना’? बुरा मत मानिए। वह बस शोर और अफ़रा-तफ़री से अलग होकर आराम करना चाहता है। अगर सब सुरक्षित है, तो उसे अपनी निजी जगह का मज़ा लेने दीजिए। वह बड़ा हो रहा है!', title_id = 'Menutup pintu dan ruang pribadi 🚪', body_id = 'Ia masuk ke kamarnya, menutup pintu, dan berkata ''Jangan masuk''? Jangan tersinggung. Ia hanya ingin menjauh dari kebisingan dan kekacauan untuk beristirahat. Kalau aman, biarkan ia menikmati ruang pribadinya. Ia sedang tumbuh!', title_ja = 'ドアを閉めて、自分だけの空間 🚪', body_ja = '自分の部屋に入ってドアを閉め、「来ないで」と言った？傷つかないで。騒音とカオスから離れて休みたいだけです。安全が確保されていれば、自分だけの空間を楽しませてあげましょう。大きくなっていますね！', title_ko = '문 닫기와 개인 공간 🚪', body_ko = '자기 방에 들어가 문을 닫고 ''들어오지 마''라고 했나요? 서운해하지 마세요. 소음과 혼란에서 벗어나 쉬고 싶은 것뿐이에요. 안전하다면 개인 공간을 누리게 두세요. 이렇게 크는 거예요!', title_nl = 'De deur dicht en persoonlijke ruimte 🚪', body_nl = 'Ging hij zijn kamer in, deed hij de deur achter zich dicht en zei hij ''Niet binnenkomen''? Voel je niet gekwetst. Hij wil zich gewoon even afzonderen van het lawaai en de chaos om tot rust te komen. Is het veilig, laat hem dan genieten van die persoonlijke ruimte. Hij wordt groot!', title_pl = 'Zamknięte drzwi i własna przestrzeń 🚪', body_pl = 'Wszedł do swojego pokoju, zamknął za sobą drzwi i powiedział „nie wchodź”? Nie obrażaj się. Chce po prostu odciąć się od hałasu i chaosu i odpocząć. Jeśli jest bezpiecznie, niech nacieszy się własną przestrzenią. Rośnie!', title_pt = 'Fechar a porta e o espaço pessoal 🚪', body_pt = 'Entrou no quarto, fechou a porta atrás de si e disse "Não entres"? Não fique magoada. Só quer isolar-se do barulho e do caos e descansar. Se estiver tudo seguro, deixe-o saborear esse espaço pessoal. Está a crescer!', title_sv = 'Att stänga dörren och eget utrymme 🚪', body_sv = 'Gick barnet in i sitt rum, stängde dörren bakom sig och sa ”Kom inte in”? Ta inte illa upp. Hen vill bara isolera sig från oljud och kaos och vila. Om säkerheten är i ordning, låt hen njuta av sitt eget utrymme. Barnet växer!', title_vi = 'Đóng cửa và không gian riêng 🚪', body_vi = 'Bé vào phòng, đóng cửa lại và nói "Mẹ đừng vào"? Đừng tự ái. Bé chỉ muốn tách mình khỏi tiếng ồn và hỗn loạn để nghỉ ngơi. Nếu mọi thứ an toàn, hãy để bé tận hưởng không gian riêng ấy. Bé đang lớn!', title_zh = '关上门与私人空间 🚪', body_zh = '走进自己的房间，从里面关上门，说“别进来”？别难过。宝宝只是想远离吵闹和混乱，自己歇一歇。只要安全，就让宝宝享受一下私人空间吧。宝宝在长大！' WHERE id = '19ac1700-7f02-47aa-b9e8-f8064c7e18d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las excusas infinitas de la noche 🚰', body_es = '¿Se le cierran los ojos, pero de repente salta con «Me pica el pie» o «Quiero agua»? Es catedrático en retrasar el sueño. Pon un temporizador. Dile: «Cuando suene el móvil, todas las excusas se van a dormir». Deja la autoridad en manos del móvil y quítate de en medio.', title_fr = 'Les prétextes sans fin de la nuit 🚰', body_fr = 'Ses yeux se ferment, mais soudain il bondit : « Mon pied me gratte », « Je veux de l''eau » ? C''est un professeur du retardement du sommeil. Réglez un minuteur. Dites « Quand le téléphone sonne, tous les prétextes vont dormir ». Confiez l''autorité au téléphone et effacez-vous.', title_hi = 'रात के अंतहीन बहाने 🚰', body_hi = 'आँखें बंद हो रही हैं, पर अचानक ‘पैर में खुजली हो रही है’, ‘पानी चाहिए’ कहकर उछल पड़ता है? वह नींद टालने का प्रोफ़ेसर है। टाइमर लगाइए। कहिए, ‘फ़ोन की घंटी बजते ही सारे बहाने सो जाते हैं।’ अथॉरिटी फ़ोन को सौंपिए, खुद बीच से हट जाइए।', title_id = 'Alasan malam yang tak ada habisnya 🚰', body_id = 'Matanya sudah terpejam, tapi tiba-tiba ia melompat sambil berkata ''Kakiku gatal'', ''Aku mau minum''? Ia profesor dalam menunda tidur. Pasang timer. Katakan ''Saat ponsel berbunyi, semua alasan ikut tidur''. Serahkan otoritas pada ponsel, Anda cukup menyingkir.', title_ja = '夜の終わらない言いわけ 🚰', body_ja = '目が閉じかけているのに、急に「足がかゆい」「お水ほしい」と飛び起きる？寝る時間を遅らせるプロです。タイマーをセットして「スマホのベルが鳴ったら、言いわけもみんな寝るよ」と言いましょう。ルールはスマホにまかせて、あなたは一歩下がって。', title_ko = '끝없는 밤의 핑계 🚰', body_ko = '눈이 감기다가도 갑자기 ''다리가 간지러워'', ''물 줘'' 하며 벌떡 일어나나요? 잠 미루기 박사네요. 타이머를 맞추고 ''알람이 울리면 모든 핑계도 잠들어'' 하고 말하세요. 권위는 휴대폰에 맡기고 엄마는 빠지세요.', title_nl = 'De eindeloze smoesjes van de nacht 🚰', body_nl = 'Vallen zijn ogen dicht, maar springt hij ineens op met ''Mijn voet jeukt'' of ''Ik wil water''? Hij is professor in het uitstellen van slaap. Zet een timer. Zeg: ''Als de telefoon gaat, gaan alle smoesjes slapen.'' Laat de telefoon de autoriteit zijn, en stap zelf opzij.', title_pl = 'Niekończące się nocne wymówki 🚰', body_pl = 'Oczy mu się kleją, ale nagle podskakuje: „Swędzi mnie noga”, „Chcę wody”? To profesor od odwlekania snu. Nastaw timer. Powiedz: „Gdy telefon zadzwoni, wszystkie wymówki idą spać”. Przenieś autorytet na telefon, a sama zejdź z linii ognia.', title_pt = 'As desculpas sem fim da noite 🚰', body_pt = 'Os olhos estão a fechar-se, mas de repente salta a dizer "Tenho comichão no pé" ou "Quero água"? É um professor catedrático em adiar o sono. Programe um temporizador. Diga "Quando o telemóvel tocar, todas as desculpas vão dormir". Passe a autoridade para o telemóvel e saia de cena.', title_sv = 'Nattens ändlösa ursäkter 🚰', body_sv = 'Ögonen håller på att slutas, men plötsligt hoppar barnet upp: ”Det kliar i foten”, ”Jag vill ha vatten”? Hen är professor i att skjuta upp sömnen. Ställ in en timer. Säg ”När telefonen ringer somnar alla ursäkter”. Lägg auktoriteten på telefonen och kliv själv åt sidan.', title_vi = 'Những cái cớ bất tận ban đêm 🚰', body_vi = 'Mắt bé đã díp lại, nhưng bỗng bật dậy: "Con ngứa chân", "Con muốn uống nước"? Bé là "giáo sư" trì hoãn giấc ngủ. Hãy đặt hẹn giờ. Khi điện thoại reo, nói: "Mọi cái cớ đều đi ngủ rồi." Để điện thoại làm "người có quyền", mẹ đứng ngoài cuộc.', title_zh = '夜里没完没了的借口 🚰', body_zh = '眼睛都快闭上了，突然跳起来说“我脚痒”“我要喝水”？简直是拖延睡觉的教授。设个计时器。说：“手机铃一响，所有借口都要睡觉了。”把“权威”交给手机，你退到一边。' WHERE id = '2cb51eab-cbdc-48ba-8569-e245d61ad27e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ese no es mi nombre 📛', body_es = '¿Te dice «No me llames por mi nombre, soy Spider-Man»? Está buscando su identidad. ¡Adáptate! Dale el desayuno con un «Aquí tiene, señor Araña». Convertir en un segundo la tensión de la habitación en comedia está en tus manos.', title_fr = 'Ce n''est pas mon prénom 📛', body_fr = 'Il dit « M''appelle pas par mon prénom, je suis Spider-Man » ? C''est une quête d''identité. Adaptez-vous ! Servez-lui son petit-déjeuner en disant « Voilà, monsieur Spider-Man ». Transformer en une seconde la tension de la pièce en comédie, c''est entre vos mains.', title_hi = 'तुम मेरा नाम नहीं हो 📛', body_hi = '‘मुझे मेरे नाम से मत बुलाओ, मैं स्पाइडर-मैन हूँ’ कहता है? यह पहचान की तलाश है। ढल जाइए! ‘लीजिए मिस्टर स्पाइडर’ कहकर नाश्ता दीजिए। कमरे के तनाव को सेकंडों में कॉमेडी में बदलना आपके हाथ में है।', title_id = 'Itu bukan namaku 📛', body_id = 'Ia berkata ''Jangan panggil namaku, aku Spider-Man''? Ini pencarian jati diri. Ikuti saja! Berikan sarapannya sambil berkata ''Silakan, Tuan Spider-Man''. Mengubah ketegangan di kamar menjadi komedi dalam sekejap ada di tangan Anda.', title_ja = 'それはぼくの名前じゃない 📛', body_ja = '「名前で呼ばないで、ぼくはスパイダーマン」と言う？自分探しの最中です。合わせてあげましょう！「どうぞ、スパイダーマンさん」と朝ごはんを出して。部屋の緊張をすぐにコメディに変えられるかは、あなた次第です。', title_ko = '그건 내 이름이 아니야 📛', body_ko = '''내 이름으로 부르지 마, 나는 스파이더맨이야'' 하나요? 정체성을 찾는 중이에요. 맞춰 주세요! ''자, 스파이더맨 님, 아침 드세요'' 하며 아침을 주세요. 방 안의 긴장을 순식간에 코미디로 바꾸는 건 엄마 손에 달렸어요.', title_nl = 'Dat is niet mijn naam 📛', body_nl = 'Zegt hij ''Noem me niet bij mijn naam, ik ben Spider-Man''? Hij is op zoek naar zijn identiteit. Ga erin mee! Geef zijn ontbijt met ''Alsjeblieft, meneer Spider-Man.'' Het ligt in jouw handen om de spanning in de kamer in een seconde in komedie te veranderen.', title_pl = 'To nie moje imię 📛', body_pl = 'Mówi „Nie mów do mnie po imieniu, jestem Spider-Manem”? To poszukiwanie tożsamości. Dostosuj się! Podaj śniadanie ze słowami: „Proszę, panie Spider-Manie”. Zamiana napięcia w pokoju w komedię w sekundę jest w twoich rękach.', title_pt = 'Esse não é o meu nome 📛', body_pt = 'Diz "Não me chames pelo meu nome, eu sou o Homem-Aranha"? É a procura da identidade. Entre no jogo! Dê-lhe o pequeno-almoço a dizer "Aqui tem, senhor Homem-Aranha". Está nas suas mãos transformar num segundo a tensão do quarto em comédia.', title_sv = 'Det är inte mitt namn 📛', body_sv = 'Säger barnet ”Kalla mig inte vid mitt namn, jag är Spindelmannen”? Det är ett sökande efter identitet. Anpassa dig! Servera frukosten med ”Varsågod, herr Spindel”. Det ligger i dina händer att förvandla spänningen i rummet till komedi på en sekund.', title_vi = 'Đó không phải tên con 📛', body_vi = 'Bé bảo "Đừng gọi con bằng tên, con là Người Nhện"? Đó là hành trình tìm kiếm bản thân. Hãy hòa theo! Đưa bữa sáng và nói "Mời ngài Người Nhện ạ". Biến căng thẳng trong phòng thành tiếng cười trong tích tắc nằm trong tay mẹ.', title_zh = '那不是我的名字 📛', body_zh = '说“别叫我的名字，我是蜘蛛侠”？宝宝在探索自我身份。配合一下！递早餐时说“请吧，蜘蛛侠先生”。几秒钟把房间里的紧张变成喜剧，全在你手里。' WHERE id = '9240add5-52c7-45dc-8ae0-15dd7dadfa88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las canciones que se inventa 🎤', body_es = '¿Aún no ha salido el sol y él ya canta a voz en grito, dando saltos, una canción con palabras sin sentido? No le cortes gritando. Un niño que empieza el día cantando suelta su agresividad. Únete 1 minuto a esa energía loca y se te quitará el sueño al instante.', title_fr = 'Les chansons qu''il invente 🎤', body_fr = 'Le soleil n''est pas encore levé, et lui saute en chantant à tue-tête des mots sans queue ni tête ? Ne criez pas pour le faire taire. Un enfant qui commence la matinée en chanson évacue son agressivité. Rejoignez cette énergie folle pendant 1 minute : votre sommeil s''envolera aussitôt.', title_hi = 'खुद के गढ़े हुए गाने 🎤', body_hi = 'अभी सूरज भी नहीं निकला, और वह उछलते हुए बेमतलब शब्दों वाला गाना ज़ोर-ज़ोर से गा रहा है? चिल्लाकर उसकी आवाज़ मत रोकिए। जो बच्चा सुबह गाने से शुरुआत करता है, वह अपना गुस्सा निकाल देता है। उस मस्त ऊर्जा में 1 मिनट के लिए आप भी शामिल हो जाइए, आपकी नींद तुरंत उड़ जाएगी।', title_id = 'Lagu-lagu karangannya sendiri 🎤', body_id = 'Matahari belum terbit, tapi ia sudah melompat-lompat sambil menyanyi keras-keras dengan kata-kata tak bermakna? Jangan membentak dan menghentikannya. Anak yang memulai pagi dengan lagu sedang melepaskan agresinya. Ikutlah dalam energi gila itu selama 1 menit, kantuk Anda langsung hilang.', title_ja = '自分でつくった歌 🎤', body_ja = 'まだお日さまも出ていないのに、飛びはねながら意味のないことばで大声でうたっている？叫んで止めないで。朝を歌で始めた子は、イライラを発散できます。あなたも1分だけそのパワフルなエネルギーに乗れば、眠気もすぐに吹き飛びますよ。', title_ko = '스스로 지어낸 노래 🎤', body_ko = '해도 뜨기 전에 폴짝폴짝 뛰며 뜻 모를 말로 큰 소리로 노래하나요? 소리쳐서 막지 마세요. 노래로 아침을 시작하는 아이는 공격성을 털어 내요. 엄마도 1분만 그 넘치는 에너지에 함께하면 잠이 확 달아날 거예요.', title_nl = 'Zelfverzonnen liedjes 🎤', body_nl = 'De zon is nog niet eens op, maar hij springt rond en zingt luid met onzinwoorden? Snoer hem niet schreeuwend de mond. Een kind dat de dag met een liedje begint, raakt zijn agressie kwijt. Doe 1 minuut mee met die gekke energie, je slaap is meteen weg.', title_pl = 'Piosenki jego własnego wymysłu 🎤', body_pl = 'Słońce jeszcze nie wzeszło, a on skacze i głośno śpiewa piosenkę z bezsensownymi słowami? Nie przerywaj mu krzykiem. Dziecko, które zaczyna dzień od piosenki, pozbywa się agresji. Dołącz na minutę do tej szalonej energii, senność od razu ci minie.', title_pt = 'As canções que ele inventa 🎤', body_pt = 'O sol ainda não nasceu e ele já salta e canta bem alto palavras sem sentido? Não grite para o calar. A criança que começa a manhã a cantar liberta a agressividade. Junte-se a essa energia louca durante 1 minuto e o sono foge-lhe logo.', title_sv = 'Egna påhittade låtar 🎤', body_sv = 'Solen har inte ens gått upp, och barnet hoppar runt och sjunger högt med meningslösa ord? Skrik inte och tysta inte. Ett barn som börjar morgonen med sång blir av med sin aggression. Var med i den galna energin i 1 minut, så försvinner sömnigheten direkt.', title_vi = 'Những bài hát bé tự sáng tác 🎤', body_vi = 'Mặt trời còn chưa mọc mà bé đã nhảy nhót và hát vang những từ vô nghĩa? Đừng quát bắt bé im. Đứa trẻ bắt đầu buổi sáng bằng bài hát sẽ xả hết cáu gắt. Hãy hòa vào nguồn năng lượng cuồng nhiệt ấy 1 phút, cơn buồn ngủ của mẹ sẽ bay biến ngay.', title_zh = '自己编的歌 🎤', body_zh = '太阳还没出来，宝宝就跳着用听不懂的词大声唱歌？别吼着让宝宝闭嘴。用歌声开始早晨的孩子能释放攻击性。你也加入这股疯狂的能量1分钟吧，困意马上就会跑光。' WHERE id = 'a897741a-cd22-4371-a712-b1ae3911676e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las mamás perfectas de Instagram 📱', body_es = '¿Te has desanimado al abrir Instagram y ver las casas ordenadas y los niños listos de todo el mundo? ¡Borra esa app! Entra en la Comunidad Anacan. Lee las historias de mamás reales con la casa desordenada como la tuya y peques cabezotas, y relájate.', title_fr = 'Les mamans parfaites d''Instagram 📱', body_fr = 'Vous vous êtes découragée en voyant sur Instagram les maisons bien rangées et les enfants sages de tout le monde ? Supprimez cette appli ! Rejoignez la Communauté Anacan. Lisez les histoires de vraies mamans dont la maison est en désordre comme la vôtre et l''enfant têtu, et détendez-vous.', title_hi = 'इंस्टाग्राम की बेदाग माँएँ 📱', body_hi = 'इंस्टाग्राम खोलते ही सबके सजे-सँवरे घर और समझदार बच्चे देखकर हिम्मत टूट गई? वह ऐप हटा दीजिए! Anacan कम्युनिटी में आइए। उन असली माँओं की कहानियाँ पढ़िए जिनके घर आपकी तरह बिखरे हैं और बच्चे ज़िद्दी हैं, और सुकून पाइए।', title_id = 'Ibu-ibu sempurna di Instagram 📱', body_id = 'Begitu membuka Instagram, Anda patah semangat melihat rumah rapi dan anak pintar milik orang lain? Hapus aplikasinya! Masuk ke Komunitas Anacan. Baca kisah ibu-ibu nyata yang rumahnya berantakan seperti rumah Anda dan anaknya keras kepala, lalu rileks.', title_ja = 'インスタの完璧なママたち 📱', body_ja = 'インスタを開いたら、みんなの整った家やかしこい子どもを見て落ちこんだ？そのアプリは消しちゃいましょう！Anacanコミュニティに入って、あなたと同じように家が散らかり、子どもががんこな、本物のママたちのお話を読んでほっとしましょう。', title_ko = '인스타그램 속 완벽한 엄마들 📱', body_ko = '인스타그램을 열자마자 다들 깔끔한 집과 똑똑한 아이만 보여서 기운 빠졌나요? 그 앱은 지우세요! Anacan 커뮤니티에 들어가 엄마처럼 집이 어질러져 있고 아이가 고집 센 진짜 엄마들의 이야기를 읽으며 마음을 놓으세요.', title_nl = 'De foutloze mama''s van Instagram 📱', body_nl = 'Werd je op Instagram ontmoedigd door ieders opgeruimde huis en slimme kind? Verwijder die app! Ga naar de Anacan Community. Lees de verhalen van echte mama''s met net zo''n rommelig huis en net zo''n koppig kind als jij, en ontspan.', title_pl = 'Idealne mamy z Instagrama 📱', body_pl = 'Gdy tylko otworzyłaś Instagram i zobaczyłaś wszystkie te schludne domy i mądre dzieci, straciłaś ducha? Usuń tę aplikację! Wejdź do Społeczności Anacan. Poczytaj historie prawdziwych mam, które mają taki sam bałagan w domu jak ty i równie uparte dzieci, i odetchnij.', title_pt = 'As mães perfeitas do Instagram 📱', body_pt = 'Mal abriu o Instagram, desanimou ao ver as casas arrumadas e os filhos inteligentes de toda a gente? Apague essa app! Entre na Comunidade Anacan. Leia as histórias de mães reais, com a casa tão desarrumada como a sua e filhos igualmente teimosos, e fique aliviada.', title_sv = 'De felfria mammorna på Instagram 📱', body_sv = 'Blev du nedslagen av att se allas prydliga hem och smarta barn så fort du öppnade Instagram? Radera appen! Gå in i Anacan Community. Läs berättelser från riktiga mammor vars hem är lika stökiga som ditt och vars barn är envisa, och slappna av.', title_vi = 'Những bà mẹ hoàn hảo trên Instagram 📱', body_vi = 'Vừa mở Instagram, thấy nhà ai cũng gọn gàng, con ai cũng thông minh, mẹ nản lòng? Xóa ứng dụng đó đi! Hãy vào Cộng đồng Anacan. Đọc câu chuyện của những bà mẹ thật, nhà cũng bừa bộn như nhà mình, con cũng bướng bỉnh, và thả lỏng.', title_zh = 'Instagram上的完美妈妈 📱', body_zh = '一打开Instagram，看到别人家整洁的家、聪明的孩子，你就灰心了？删掉那个应用！进入Anacan社区。读读那些家里和你一样乱、孩子一样倔的真实妈妈的故事，放松一下吧。' WHERE id = 'ad4460c3-33b8-4fdc-85b5-ca63eae32f6e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sueño que llega con susurros 🤫', body_es = '¿Se escapa de la cama y salta de un lado a otro? Baja la voz del todo de repente. Empieza a hablar muy bajito, en susurros. Para entenderte tendrá que concentrarse físicamente y en 5 minutos su cerebro se cansará y pasará al modo sueño. ¡Pruébalo!', title_fr = 'Le sommeil qui vient en chuchotant 🤫', body_fr = 'Il s''échappe du lit et saute partout ? Baissez soudain complètement la voix. Mettez-vous à parler très bas, en chuchotant. Pour vous comprendre, il devra physiquement se concentrer, et son cerveau, fatigué, passera en mode sommeil en 5 minutes. Essayez !', title_hi = 'फुसफुसाहट के साथ आती नींद 🤫', body_hi = 'बिस्तर से भागकर इधर-उधर उछल रहा है? अचानक अपनी आवाज़ पूरी तरह धीमी कर दीजिए। बहुत हल्के से फुसफुसाकर बोलना शुरू कीजिए। आपको समझने के लिए उसे पूरा ध्यान लगाना पड़ेगा और 5 मिनट में दिमाग थककर स्लीप मोड में चला जाएगा। आज़माइए!', title_id = 'Kantuk yang datang lewat bisikan 🤫', body_id = 'Ia kabur dari tempat tidur dan melompat ke sana kemari? Tiba-tiba kecilkan suara Anda sepenuhnya. Mulailah berbicara sangat pelan sambil berbisik. Untuk memahami Anda, ia harus memusatkan perhatian secara fisik, dan dalam 5 menit otaknya lelah dan masuk mode tidur. Coba saja!', title_ja = 'ささやき声でやってくる眠り 🤫', body_ja = 'ベッドから逃げてあちこち飛びはねている？急に声をぐっと落として、とても小さなささやき声で話し始めましょう。聞きとろうと体ごと集中するうちに、5分で脳が疲れて睡眠モードに切りかわります。ためしてみて！', title_ko = '속삭임이 데려오는 잠 🤫', body_ko = '침대에서 빠져나와 이리저리 뛰어다니나요? 갑자기 목소리를 완전히 낮추세요. 아주 작게 속삭이며 말하기 시작하면, 엄마 말을 알아들으려 집중하다 5분 만에 머리가 지쳐 수면 모드로 넘어갈 거예요. 해 보세요!', title_nl = 'Slaap die fluisterend komt 🤫', body_nl = 'Ontsnapt hij uit bed en springt hij alle kanten op? Laat je stem ineens helemaal wegzakken. Ga heel zacht fluisterend praten. Om je te verstaan moet hij zich lichamelijk concentreren, en binnen 5 minuten is zijn brein moe en gaat het in slaapstand. Probeer het!', title_pl = 'Sen, który przychodzi z szeptem 🤫', body_pl = 'Ucieka z łóżka i skacze po całym pokoju? Nagle całkiem ścisz głos. Zacznij mówić bardzo cicho, szeptem. Żeby cię zrozumieć, będzie musiał fizycznie skupić uwagę, a jego mózg za 5 minut się zmęczy i przejdzie w tryb snu. Spróbuj!', title_pt = 'O sono que chega em sussurro 🤫', body_pt = 'Foge da cama e salta de um lado para o outro? Baixe de repente a voz por completo. Comece a falar muito baixinho, em sussurro. Para a perceber, vai ter de se concentrar fisicamente e em 5 minutos o cérebro cansa-se e passa para o modo de sono. Experimente!', title_sv = 'Sömnen som kommer med viskningar 🤫', body_sv = 'Smiter barnet ur sängen och hoppar runt? Dämpa plötsligt rösten helt. Börja prata väldigt tyst och viskande. Barnet måste fysiskt koncentrera sig för att förstå dig, och inom 5 minuter blir hjärnan trött och går över i sömnläge. Prova!', title_vi = 'Giấc ngủ đến cùng lời thì thầm 🤫', body_vi = 'Bé trốn khỏi giường và nhảy khắp nơi? Hãy bất ngờ hạ giọng hoàn toàn. Bắt đầu nói thì thầm thật nhỏ. Để hiểu mẹ, bé phải tập trung cao độ và 5 phút sau não bé sẽ mệt, chuyển sang chế độ ngủ. Thử xem!', title_zh = '悄悄话带来的睡意 🤫', body_zh = '从床上跑下来，到处跳来跳去？突然把声音完全压低。用很轻很轻的悄悄话说话。为了听懂你，宝宝不得不集中注意力，大脑5分钟就会累了，进入睡眠模式。试试吧！' WHERE id = 'b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un juguete encontrado en la nevera 🧊', body_es = '¿Has abierto la nevera y ha salido un coche de goma? Es un juego para poner a prueba la memoria y los objetos en un lugar distinto. No te enfades: este absurdo forma parte de su desarrollo.', title_fr = 'Un jouet trouvé dans le frigo 🧊', body_fr = 'Vous avez ouvert le frigo et une voiture en caoutchouc en est sortie ? C''est un jeu pour tester la mémoire et l''objet dans un autre lieu. Ne vous fâchez pas, cette absurdité fait partie de son développement.', title_hi = 'फ़्रिज में मिला खिलौना 🧊', body_hi = 'फ़्रिज खोला और अंदर से रबर की गाड़ी निकली? यह याददाश्त और चीज़ को अलग जगह पर परखने का खेल है। गुस्सा मत कीजिए, यह बेतुकापन उसके विकास का हिस्सा है।', title_id = 'Mainan yang ditemukan di kulkas 🧊', body_id = 'Anda membuka kulkas dan menemukan mobil-mobilan karet di dalamnya? Ini permainan menguji ingatan dan menaruh benda di tempat berbeda. Jangan marah, hal absurd ini adalah bagian dari perkembangannya.', title_ja = '冷蔵庫で見つかったおもちゃ 🧊', body_ja = '冷蔵庫を開けたら、中からゴムの車が出てきた？記憶と、ものをちがう場所に置いてためす遊びです。怒らないで。このおかしさも発達の一部です。', title_ko = '냉장고에서 발견된 장난감 🧊', body_ko = '냉장고를 열었더니 고무 자동차가 나왔나요? 기억력과 물건을 다른 장소에 두는 걸 시험하는 놀이예요. 화내지 마세요, 이 엉뚱함도 발달의 일부예요.', title_nl = 'Speelgoed in de koelkast 🧊', body_nl = 'Deed je de koelkast open en kwam er een rubberen autootje uit? Dit is een spel waarmee hij zijn geheugen en spullen op een andere plek test. Word niet boos, deze absurditeit hoort bij zijn ontwikkeling.', title_pl = 'Zabawka znaleziona w lodówce 🧊', body_pl = 'Otworzyłaś lodówkę, a w środku gumowe autko? To zabawa w sprawdzanie pamięci i przedmiotów w innym miejscu. Nie złość się, ten absurd to część jego rozwoju.', title_pt = 'O brinquedo que apareceu no frigorífico 🧊', body_pt = 'Abriu o frigorífico e lá dentro estava um carrinho de borracha? É um jogo de memória e de testar objetos em sítios diferentes. Não se zangue: este absurdo faz parte do desenvolvimento dele.', title_sv = 'Leksaken i kylskåpet 🧊', body_sv = 'Öppnade du kylskåpet och hittade en gummibil? Det är en lek där barnet testar minnet och föremål på en ny plats. Bli inte arg, det absurda är en del av utvecklingen.', title_vi = 'Đồ chơi trong tủ lạnh 🧊', body_vi = 'Mở tủ lạnh, mẹ thấy một chiếc ô tô cao su bên trong? Đây là trò chơi thử trí nhớ và thử đặt đồ vật ở không gian khác. Đừng giận, sự vô lý này là một phần trong quá trình phát triển của bé.', title_zh = '冰箱里找到的玩具 🧊', body_zh = '打开冰箱，从里面拿出一辆橡胶小汽车？这是一个测试记忆、把物品放在不同地方的游戏。别生气，这种荒诞也是宝宝成长的一部分。' WHERE id = '1dcf070f-1d18-4228-b248-9ed1c6174aff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No quiere salir de casa ⛅', body_es = '¿La casa está patas arriba y él llora en el sofá diciendo que no va? Abre Tiempo y ropa, mira la temperatura real de fuera, ponle el conjunto adecuado y llévalo al parque aunque sea a regañadientes. En cuanto le dé el aire fresco en la cara, toda su agresividad se esfumará.', title_fr = 'Il ne veut pas sortir de la maison ⛅', body_fr = 'La maison est sens dessus dessous, et lui pleure sur le canapé en disant « J''y vais pas » ? Ouvrez Météo et tenue, vérifiez la vraie température dehors, habillez-le de la tenue adaptée et emmenez-le au parc, même à contrecœur. Dès que l''air frais touchera son visage, toute son agressivité s''envolera.', title_hi = 'घर से नहीं निकलना चाहता ⛅', body_hi = 'घर बिखरा पड़ा है, और वह सोफ़े पर रोते हुए कह रहा है, ‘मैं नहीं जाऊँगा’? मौसम और कपड़े खोलकर बाहर का असली तापमान देखिए, सही कपड़े पहनाइए और ज़बरदस्ती ही सही, पार्क ले जाइए। ताज़ी हवा चेहरे पर लगते ही उसका सारा गुस्सा उड़ जाएगा।', title_id = 'Ia tidak mau keluar rumah ⛅', body_id = 'Rumah berantakan, sementara ia menangis di sofa berkata ''Aku nggak mau pergi''? Buka Cuaca dan Pakaian, cek suhu sebenarnya di luar, pakaikan setelan yang sesuai, dan bawa ia ke taman meski harus sedikit dipaksa. Begitu udara segar menyentuh wajahnya, semua agresinya akan hilang.', title_ja = '家から出たくない ⛅', body_ja = '家は散らかり放題、この子はソファで泣いて「行かない」と言う？「天気と服装」を開いて外の本当の気温を確認し、ぴったりの服を着せて、多少強引にでも公園へ。新鮮な空気が顔にあたった瞬間、イライラは全部吹き飛びます。', title_ko = '밖에 나가기 싫대요 ⛅', body_ko = '집은 엉망인데 아이는 소파에서 울며 안 나가겠다고 하나요? 날씨와 옷차림을 열어 바깥의 실제 기온을 확인하고 알맞은 옷을 입혀, 억지로라도 공원에 데려가세요. 맑은 공기가 얼굴에 닿는 순간 공격성이 다 날아갈 거예요.', title_nl = 'Hij wil de deur niet uit ⛅', body_nl = 'Het huis is een puinhoop en hij huilt op de bank dat hij niet mee gaat? Open Weer en kleding, check de echte temperatuur buiten, trek hem de juiste outfit aan en ga desnoods met wat moeite naar het park. Zodra de frisse lucht zijn gezicht raakt, waait al die agressie weg.', title_pl = 'Nie chce wyjść z domu ⛅', body_pl = 'W domu straszny bałagan, a on płacze na kanapie: „Nie idę”? Otwórz Pogodę i ubiór, sprawdź prawdziwą temperaturę na dworze, ubierz go w odpowiedni zestaw i choćby na siłę zabierz do parku. Gdy tylko świeże powietrze owieje mu twarz, cała złość uleci.', title_pt = 'Não quer sair de casa ⛅', body_pt = 'A casa está um caos e ele chora no sofá a dizer que não sai? Abra o Tempo e Roupa, veja a temperatura real lá fora, vista-lhe a combinação certa e leve-o ao parque, nem que seja à força. Mal o ar puro lhe bater na cara, toda a agressividade vai desaparecer.', title_sv = 'Vill inte gå ut ⛅', body_sv = 'Huset är i kaos, och barnet gråter i soffan och säger ”Jag går inte”? Öppna Väder och kläder, kolla den verkliga temperaturen ute, klä barnet i rätt kombination och ta med hen till parken, även om det tar emot. Så fort den friska luften når ansiktet flyger all ilska iväg.', title_vi = 'Bé không muốn ra khỏi nhà ⛅', body_vi = 'Nhà cửa bừa bộn, còn bé thì khóc trên sofa: "Con không đi đâu"? Hãy mở Thời tiết và trang phục, kiểm tra nhiệt độ thực tế bên ngoài, mặc bộ đồ phù hợp và đưa bé ra công viên, dù có phải hơi ép. Gió trời vừa chạm mặt, mọi cơn cáu giận sẽ tan biến.', title_zh = '不想出门 ⛅', body_zh = '家里一片狼藉，宝宝却在沙发上哭着说“我不去”？打开天气与穿衣，查看外面的真实温度，穿上合适的搭配，哪怕连哄带拉也要去公园。新鲜空气一吹到脸上，那些火气就会飞走。' WHERE id = 'ba708130-cef9-4b08-8a17-7c16cb66de0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando es el protagonista del cuento 🪄', body_es = 'Abre Cuentos inteligentes. Cambia directamente el nombre del protagonista por el de tu peque. Lee cómo, a lo largo de la historia, ese protagonista se duerme valiente y obediente. Cuando se oiga a sí mismo en la historia, cerrará los ojos sin ninguna protesta.', title_fr = 'Quand il devient le héros du conte 🪄', body_fr = 'Ouvrez les Contes intelligents. Remplacez directement le nom du héros par le prénom de votre enfant. Lisez comment, tout au long de l''histoire, ce héros s''endort courageusement et sagement. En s''entendant dans l''histoire, il fermera les yeux sans la moindre protestation.', title_hi = 'जब कहानी में हीरो वही हो 🪄', body_hi = 'स्मार्ट कहानियाँ खोलिए। उसमें हीरो का नाम सीधे अपने बच्चे के नाम से बदल दीजिए। पढ़िए कि कहानी में वह हीरो कितनी बहादुरी से और बात मानकर सो जाता है। कहानी में खुद को सुनकर वह बिना किसी विरोध के आँखें बंद कर लेगा।', title_id = 'Saat ia jadi tokoh di dongeng 🪄', body_id = 'Buka Dongeng Pintar. Ganti nama tokoh di sana langsung dengan nama anak Anda. Bacakan bagaimana sepanjang cerita tokoh itu tidur dengan berani dan patuh. Saat mendengar dirinya dalam cerita itu, ia akan memejamkan mata tanpa protes sedikit pun.', title_ja = 'お話の主人公になったら 🪄', body_ja = '「スマートおはなし」を開きましょう。主人公の名前をそのままお子さんの名前に変えて、主人公が勇敢に素直に眠るお話を読んであげて。お話の中に自分を見つけたら、文句も言わずに目を閉じますよ。', title_ko = '동화 속 주인공이 되면 🪄', body_ko = '스마트 동화를 열어 보세요. 주인공 이름을 아이 이름으로 바꾸고, 그 주인공이 얼마나 용감하고 말 잘 듣게 잠드는지 읽어 주세요. 이야기 속 자기 모습을 들으면 아무 저항 없이 눈을 감을 거예요.', title_nl = 'Als hij de held van het sprookje is 🪄', body_nl = 'Open Slimme sprookjes. Vervang de naam van de held direct door de naam van je kind. Lees hoe dapper en braaf die held in het verhaal gaat slapen. Als hij zichzelf in het verhaal hoort, doet hij zonder protest zijn ogen dicht.', title_pl = 'Gdy w bajce jest bohaterem 🪄', body_pl = 'Otwórz Mądre bajki. Zamień imię bohatera na imię swojego dziecka. Czytaj, jak przez całą historię ten bohater dzielnie i grzecznie zasypia. Gdy usłyszy w tej historii siebie, zamknie oczy bez żadnego sprzeciwu.', title_pt = 'Quando ele é o herói da história 🪄', body_pt = 'Abra as Histórias Inteligentes. Troque diretamente o nome do herói pelo nome do seu filho. Leia como, ao longo da história, o herói adormece com coragem e bem-comportado. Ao ouvir-se na história, vai fechar os olhos sem protestar.', title_sv = 'När man blir hjälte i sagan 🪄', body_sv = 'Öppna Smarta sagor. Byt hjältens namn direkt mot ditt barns namn. Läs hur hjälten modigt och snällt somnar genom hela berättelsen. När barnet hör sig själv i historien blundar hen utan minsta protest.', title_vi = 'Khi bé là nhân vật chính 🪄', body_vi = 'Hãy mở Truyện cổ tích thông minh. Thay tên nhân vật chính bằng chính tên của bé. Đọc cho bé nghe nhân vật ấy dũng cảm và ngoan ngoãn đi ngủ thế nào trong suốt câu chuyện. Nghe thấy chính mình trong truyện, bé sẽ nhắm mắt mà không phản đối gì.', title_zh = '当宝宝成为故事里的英雄 🪄', body_zh = '打开智慧童话。把故事里主角的名字直接换成宝宝的名字。读一读主角是怎样勇敢又乖巧地睡着的。在故事里听到自己，宝宝就会毫无异议地闭上眼睛。' WHERE id = 'c3fe5fd9-dde9-47f5-b95c-98d26881d393' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un llanto incomprensible a medianoche 😭', body_es = '¿En plena noche se ha despertado llorando con los ojos cerrados y no te oye? Compruébalo con el Análisis del llanto: lo más probable es que sean terrores nocturnos. Intenta no despertarlo, solo quédate a su lado y cógele la mano. Se calmará solo y volverá a dormirse.', title_fr = 'Des pleurs incompréhensibles en pleine nuit 😭', body_fr = 'Il s''est réveillé en pleine nuit en pleurant, les yeux fermés, et ne vous entend pas ? Vérifiez avec l''Analyse des pleurs : il s''agit très probablement d''une terreur nocturne. N''essayez pas de le réveiller, restez simplement près de lui et tenez-lui la main. Il se calmera de lui-même et se rendormira.', title_hi = 'आधी रात का समझ न आने वाला रोना 😭', body_hi = 'आधी रात को आँखें बंद किए रोते हुए जागा और आपकी बात नहीं सुन रहा? क्राइंग एनालिसिस से जाँचिए; ज़्यादा संभावना है कि यह नाइट टेरर है। जगाने की कोशिश मत कीजिए, बस पास रहिए, हाथ थामिए। वह अपने आप शांत होकर फिर सो जाएगा।', title_id = 'Tangisan tak jelas di tengah malam 😭', body_id = 'Di tengah malam ia terbangun menangis dengan mata terpejam dan tidak mendengar Anda? Periksa dengan Analisis Tangisan; kemungkinan besar ini teror tidur (night terror). Jangan coba membangunkannya, cukup berada di sampingnya dan pegang tangannya. Ia akan tenang sendiri dan tidur lagi.', title_ja = '真夜中のわけのわからない泣き 😭', body_ja = '真夜中に目を閉じたまま泣いて起き、あなたの声が聞こえていない？「泣き声分析」で確かめましょう。おそらく夜驚症です。起こそうとせず、ただそばにいて手をにぎって。自然に落ち着いて、また眠ります。', title_ko = '한밤중 알 수 없는 울음 😭', body_ko = '한밤중에 눈을 감은 채 울며 깨어나 엄마 말을 듣지 못하나요? 울음 분석으로 확인해 보세요. 아마도 야경증일 거예요. 깨우려 하지 말고 곁에서 손을 잡아 주세요. 스스로 진정하고 다시 잠들 거예요.', title_nl = 'Onbegrijpelijk huilen midden in de nacht 😭', body_nl = 'Werd hij midden in de nacht huilend wakker met zijn ogen dicht en hoort hij je niet? Check het met Huilanalyse; dit is hoogstwaarschijnlijk nachtangst (pavor nocturnus). Probeer hem niet wakker te maken, blijf gewoon bij hem en pak zijn hand. Hij kalmeert vanzelf en slaapt weer in.', title_pl = 'Niezrozumiały płacz o północy 😭', body_pl = 'W środku nocy obudził się z płaczem, z zamkniętymi oczami, i cię nie słyszy? Sprawdź to w Analizie płaczu; najpewniej to lęk nocny. Nie próbuj go budzić, po prostu bądź obok i trzymaj go za rękę. Sam się uspokoi i znów zaśnie.', title_pt = 'Choro inexplicável a meio da noite 😭', body_pt = 'A meio da noite acordou a chorar, de olhos fechados, e não a ouve? Confirme com a Análise do Choro: muito provavelmente é terror noturno. Tente não o acordar, fique só ao lado dele e pegue-lhe na mão. Vai acalmar-se sozinho e voltar a adormecer.', title_sv = 'Obegriplig gråt mitt i natten 😭', body_sv = 'Vaknade barnet gråtande mitt i natten med slutna ögon och hör dig inte? Kontrollera med Gråtanalys; det är sannolikt nattskräck. Försök inte väcka barnet, stå bara bredvid och håll handen. Barnet lugnar sig av sig självt och somnar om.', title_vi = 'Tiếng khóc khó hiểu lúc nửa đêm 😭', body_vi = 'Giữa đêm bé khóc thét, mắt vẫn nhắm và không nghe thấy mẹ? Hãy kiểm tra bằng Phân tích tiếng khóc; rất có thể đây là hoảng sợ khi ngủ. Cố đừng đánh thức bé, chỉ cần ở bên và nắm tay bé. Bé sẽ tự bình tĩnh lại và ngủ tiếp.', title_zh = '半夜莫名的哭闹 😭', body_zh = '半夜闭着眼睛哭醒，好像听不见你说话？用哭声分析看看：这很可能是夜惊。尽量别叫醒宝宝，只要陪在身边，握着小手。宝宝会自己平静下来，重新睡着。' WHERE id = '139226ae-9370-42b4-954a-012623528599' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora secreta del chocolate de mamá 🍫', body_es = '¿Te comes un chocolate a escondidas de él, detrás del armario? ¡Que aproveche! Para aguantar los «¿por qué?» sin fin y los gritos, y recuperar energía, esa glucosa es tu derecho más natural. Nunca te culpes por ello.', title_fr = 'L''heure secrète du chocolat de maman 🍫', body_fr = 'Vous mangez du chocolat en cachette derrière le placard ? Bon appétit ! Pour supporter ces « pourquoi » sans fin et ces cris, et pour recharger votre énergie, ce glucose est votre droit le plus naturel. Ne vous en voulez jamais pour ça.', title_hi = 'माँ का चुपके वाला चॉकलेट टाइम 🍫', body_hi = 'अलमारी के पीछे छिपकर चॉकलेट खा रही हैं? मज़े से खाइए! उन अंतहीन ‘क्यों’ और चीखों को झेलने और ऊर्जा वापस पाने के लिए वह ग्लूकोज़ आपका सबसे स्वाभाविक हक है। इसके लिए खुद को कभी दोष मत दीजिए।', title_id = 'Jam cokelat rahasia Ibu 🍫', body_id = 'Anda diam-diam makan cokelat di balik lemari tanpa sepengetahuannya? Selamat menikmati! Untuk menghadapi ''kenapa'' yang tak ada habisnya dan teriakan-teriakan, serta memulihkan energi, glukosa itu hak Anda yang paling alami. Jangan pernah menyalahkan diri karenanya.', title_ja = 'ママのこっそりチョコタイム 🍫', body_ja = '戸棚のかげで、こっそりチョコを食べている？めしあがれ！終わりのない「なんで？」や叫び声に耐えて、エネルギーをとり戻すためのそのブドウ糖は、あなたのいちばん自然な権利です。決して自分を責めないで。', title_ko = '엄마의 비밀 초콜릿 시간 🍫', body_ko = '찬장 뒤에서 아이 몰래 초콜릿을 먹고 있나요? 맛있게 드세요! 끝없는 ''왜?''와 고함을 견디고 에너지를 채우는 그 당분은 엄마의 가장 당연한 권리예요. 절대 자책하지 마세요.', title_nl = 'Mama''s geheime chocoladeuurtje 🍫', body_nl = 'Eet je stiekem achter de kast chocola, zodat hij het niet ziet? Eet smakelijk! Om al die eindeloze waaroms en het geschreeuw te doorstaan en je energie terug te krijgen, is die glucose je meest natuurlijke recht. Veroordeel jezelf daar nooit om.', title_pl = 'Tajna czekoladowa chwila mamy 🍫', body_pl = 'Za szafką po kryjomu jesz czekoladę? Smacznego! Żeby znieść te niekończące się „dlaczego” i krzyki i odzyskać energię, ta glukoza po prostu ci się należy. Nigdy się za to nie obwiniaj.', title_pt = 'A hora secreta do chocolate da mãe 🍫', body_pt = 'Come chocolate atrás do armário, às escondidas dele? Bom proveito! Para aguentar os "porquês" sem fim e os gritos e recuperar energia, essa glicose é o seu direito mais natural. Nunca se culpe por isso.', title_sv = 'Mammas hemliga chokladstund 🍫', body_sv = 'Äter du choklad i smyg bakom skåpet, utan att barnet ser? Smaklig måltid! För att stå ut med alla ändlösa varför och skrik och för att återställa energin är den glukosen din mest naturliga rättighet. Döm aldrig dig själv för det.', title_vi = 'Giờ sô-cô-la bí mật của mẹ 🍫', body_vi = 'Mẹ lén ăn sô-cô-la sau tủ để bé không thấy? Chúc mẹ ngon miệng! Để chịu đựng những câu "tại sao" và tiếng la hét không dứt, và để nạp lại năng lượng, chút đường ấy là quyền tự nhiên nhất của mẹ. Đừng bao giờ tự trách mình vì điều đó.', title_zh = '妈妈的秘密巧克力时间 🍫', body_zh = '躲在柜子后面，偷偷吃巧克力？好好享受吧！为了扛住那些没完没了的“为什么”和尖叫、恢复精力，这点葡萄糖是你最天然的权利。永远别为这个责怪自己。' WHERE id = 'a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pilla-pilla con la sombra 🏃‍♂️', body_es = '¿Va por la calle y de repente sale corriendo para atrapar su propia sombra? Su imaginación supera a su lógica. No lo pares: únete tú también a este juego loco y alegre en medio de la calle intentando atrapar tu sombra. La vida no es tan larga como para tomársela tan en serio.', title_fr = 'Chat perché avec l''ombre 🏃‍♂️', body_fr = 'Dans la rue, il se met soudain à courir pour attraper sa propre ombre ? Son imagination l''emporte sur sa logique. Ne l''arrêtez pas : essayez vous aussi d''attraper votre ombre et rejoignez ce jeu fou et joyeux en pleine rue. La vie n''est pas assez longue pour être prise trop au sérieux.', title_hi = 'परछाईं के साथ पकड़म-पकड़ाई 🏃‍♂️', body_hi = 'सड़क पर चलते-चलते अचानक दौड़कर अपनी परछाईं पकड़ने की कोशिश करता है? उसकी कल्पना तर्क से आगे निकल रही है। उसे मत रोकिए, आप भी अपनी परछाईं पकड़ने की कोशिश करते हुए सड़क के बीच इस मस्त, खुशनुमा खेल में शामिल हो जाइए। ज़िंदगी इतनी लंबी नहीं कि उसे इतनी गंभीरता से लिया जाए।', title_id = 'Kejar-kejaran dengan bayangan 🏃‍♂️', body_id = 'Saat berjalan di luar, tiba-tiba ia berlari mencoba menangkap bayangannya sendiri? Imajinasinya mengalahkan logikanya. Jangan hentikan, ikutlah dalam permainan gila dan ceria ini di tengah jalan dengan mencoba menangkap bayangan Anda sendiri. Hidup terlalu singkat untuk dianggap terlalu serius.', title_ja = '影とおにごっこ 🏃‍♂️', body_ja = '道を歩いていて、急に走り出して自分の影をつかまえようとする？想像力が理屈を上まわっています。止めないで、あなたも自分の影をつかまえようとして、道のまん中でこのはちゃめちゃで楽しい遊びに加わりましょう。人生は、深刻にばかり考えるほど長くはありません。', title_ko = '그림자 술래잡기 🏃‍♂️', body_ko = '길을 걷다 갑자기 뛰어가 자기 그림자를 잡으려 하나요? 상상력이 논리를 앞서고 있어요. 막지 말고 엄마도 자기 그림자를 잡으며 길 한복판에서 이 신나는 놀이에 함께하세요. 인생은 너무 심각하게 살기엔 길지 않아요.', title_nl = 'Tikkertje met je schaduw 🏃‍♂️', body_nl = 'Rent hij op straat ineens weg om zijn eigen schaduw te vangen? Zijn fantasie wint het van zijn logica. Hou hem niet tegen, probeer zelf ook je schaduw te vangen en doe midden op straat mee met dit gekke, vrolijke spel. Het leven is te kort om alles zo serieus te nemen.', title_pl = 'Berek z cieniem 🏃‍♂️', body_pl = 'Idąc ulicą, nagle biegnie i próbuje złapać własny cień? Jego wyobraźnia wygrywa z logiką. Nie zatrzymuj go, też spróbuj złapać swój cień i dołącz do tej szalonej, wesołej zabawy na środku ulicy. Życie nie jest na tyle długie, by brać je zbyt poważnie.', title_pt = 'Apanhada com a sombra 🏃‍♂️', body_pt = 'Na rua, desata de repente a correr para apanhar a própria sombra? A imaginação vence a lógica. Não o trave: tente também apanhar a sua sombra e entre neste jogo louco e alegre no meio da rua. A vida não é assim tão longa para se levar tão a sério.', title_sv = 'Kull med skuggan 🏃‍♂️', body_sv = 'Springer barnet plötsligt iväg på gatan och försöker fånga sin egen skugga? Fantasin övertrumfar logiken. Stoppa inte barnet, försök fånga din egen skugga du också och var med i den galna, glada leken mitt på gatan. Livet är inte långt nog för att tas på så stort allvar.', title_vi = 'Đuổi bắt cái bóng 🏃‍♂️', body_vi = 'Đang đi trên đường, bé bỗng chạy đi bắt cái bóng của mình? Trí tưởng tượng của bé lấn át cả logic. Đừng ngăn lại, mẹ cũng hãy thử bắt bóng của mình và hòa vào trò chơi điên rồ, vui nhộn này ngay giữa đường. Cuộc sống không dài đến mức phải nghiêm túc mãi.', title_zh = '和影子你追我跑 🏃‍♂️', body_zh = '走在街上，突然跑去抓自己的影子？想象力胜过了逻辑。别阻止，你也来抓自己的影子，在街上加入这场疯狂又快乐的游戏吧。人生没有长到需要事事都那么认真。' WHERE id = 'a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El síndrome del zapato cambiado 👟', body_es = '¿Se ha puesto el zapato derecho en el pie izquierdo y el izquierdo en el derecho, y no te deja cambiarlos? ¡Que se queden así! Ese orgullo de «me los he puesto yo» y esa sensación de libertad valen un millón de veces más que llevar bien los zapatos.', title_fr = 'Le syndrome des chaussures inversées 👟', body_fr = 'Il a mis la chaussure droite au pied gauche, la gauche au pied droit, et refuse qu''on les remette bien ? Laissez-les ainsi ! Sa fierté de dire « Je me suis habillé tout seul » et son sentiment de liberté valent un million de fois plus que des chaussures bien mises.', title_hi = 'उल्टे जूतों वाला सिंड्रोम 👟', body_hi = 'दायाँ जूता बाएँ पैर में और बायाँ दाएँ में पहन लिया और ठीक नहीं करने देता? वैसे ही रहने दीजिए! ‘मैंने खुद पहना’ वाला उसका गर्व और आज़ादी का एहसास जूतों के सही होने से लाख गुना ज़्यादा कीमती है।', title_id = 'Sindrom sepatu tertukar 👟', body_id = 'Ia memakai sepatu kanan di kaki kiri dan sepatu kiri di kaki kanan, lalu tidak mau dibetulkan? Biarkan saja begitu! Rasa bangga ''aku pakai sendiri'' dan rasa bebasnya sejuta kali lebih berharga daripada sepatu yang terpasang benar.', title_ja = '左右逆のくつ症候群 👟', body_ja = '右のくつを左に、左のくつを右にはいて、直させない？そのままにしておきましょう！「自分ではいた」という誇りと自由な気持ちは、くつが正しいことより百万倍大切です。', title_ko = '신발 거꾸로 신기 증후군 👟', body_ko = '오른쪽 신발을 왼발에, 왼쪽 신발을 오른발에 신고 못 고치게 하나요? 그대로 두세요! ''내가 신었어'' 하는 자부심과 자유로움은 신발을 바르게 신는 것보다 백만 배 더 소중해요.', title_nl = 'Het verkeerde-schoenensyndroom 👟', body_nl = 'Heeft hij zijn rechterschoen aan zijn linkervoet en zijn linkerschoen aan zijn rechtervoet, en mag je het niet goed doen? Laat het zo! Zijn trots van ''ik heb het zelf aangedaan'' en zijn gevoel van vrijheid zijn een miljoen keer meer waard dan goed zittende schoenen.', title_pl = 'Syndrom butów na odwrót 👟', body_pl = 'Włożył prawy but na lewą nogę, a lewy na prawą, i nie pozwala tego poprawić? Niech tak zostanie! Jego duma, mówiąca „sam się ubrałem”, i poczucie wolności są milion razy cenniejsze niż poprawnie założone buty.', title_pt = 'A síndrome dos sapatos trocados 👟', body_pt = 'Calçou o sapato direito no pé esquerdo e o esquerdo no direito e não deixa trocar? Deixe ficar assim! O orgulho de "fui eu que calcei" e a sensação de liberdade valem um milhão de vezes mais do que os sapatos bem calçados.', title_sv = 'Syndromet med skorna på fel fot 👟', body_sv = 'Har barnet satt höger sko på vänster fot och vänster på höger och låter dig inte rätta till dem? Låt dem sitta så! Stoltheten och frihetskänslan som säger ”jag tog på mig dem själv” är en miljon gånger mer värd än rätt skor.', title_vi = 'Hội chứng đi giày ngược 👟', body_vi = 'Bé đi giày phải vào chân trái, giày trái vào chân phải và không cho sửa? Cứ để vậy! Niềm tự hào "con tự đi được" và cảm giác tự do ấy quý hơn việc đi giày đúng cả triệu lần.', title_zh = '鞋子反穿综合征 👟', body_zh = '右脚的鞋穿在左脚，左脚的穿在右脚，还不让你改？就这样吧！那份“我自己穿的”骄傲和自由感，比鞋穿得对不对珍贵一百万倍。' WHERE id = '4d4b704f-57d5-4f72-9df3-13398bb1f2e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Volcar en digital la rabia que llevo dentro 📝', body_es = '¿Nadie ve lo cansada que estás hoy y tener que sonreír te ahoga? Abre el Diario de ánimo. Vuelca en la pantalla todo ese veneno y ese cansancio de dentro. Escribir «estoy agotada» te curará antes que una falsa perfección.', title_fr = 'Déverser ma colère dans le numérique 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée aujourd''hui, et sourire vous étouffe ? Ouvrez le Journal d''humeur. Déversez sur l''écran tout ce poison, toute cette fatigue. Écrire « Je suis à bout » vous fera du bien plus vite qu''une fausse perfection.', title_hi = 'अंदर का गुस्सा डिजिटल में उतारना 📝', body_hi = 'कोई नहीं देखता कि आज आप कितनी थकीं, और मुस्कुराना आपका दम घोंट रहा है? मूड डायरी खोलिए। अंदर का सारा ज़हर और थकान स्क्रीन पर उड़ेल दीजिए। ‘मैं थककर चूर हूँ’ लिखना आपको नकली परफ़ेक्शन से कहीं जल्दी ठीक करेगा।', title_id = 'Menumpahkan amarah ke ruang digital 📝', body_id = 'Tak ada yang melihat betapa lelahnya Anda hari ini, dan tersenyum membuat Anda sesak? Buka Buku Harian Suasana Hati. Tumpahkan semua racun dan lelah di dalam diri ke layar. Menulis ''Aku sudah habis'' akan memulihkan Anda lebih cepat daripada kesempurnaan palsu.', title_ja = '心の中の怒りをデジタルに吐き出す 📝', body_ja = '今日どれだけ疲れているか誰も気づかず、笑顔でいるのが苦しい？「気分日記」を開いて、心の中の毒も疲れも全部画面に吐き出しましょう。「もう限界」と書くことは、うわべの完璧さよりずっと早くあなたを癒やしてくれます。', title_ko = '속에 쌓인 화를 디지털로 털어놓기 📝', body_ko = '오늘 내가 얼마나 지쳤는지 아무도 모르고, 웃는 게 숨 막히나요? 기분 일기를 열고 속에 쌓인 독과 피로를 화면에 모두 쏟아 내세요. ''나 다 소진됐어''라고 쓰는 게 가짜 완벽함보다 더 빨리 회복시켜 줄 거예요.', title_nl = 'Mijn boosheid digitaal uitstorten 📝', body_nl = 'Ziet niemand hoe moe je vandaag bent en word je benauwd van het glimlachen? Open je Stemmingsdagboek. Gooi al dat gif en die vermoeidheid eruit op het scherm. ''Ik ben op'' opschrijven heelt je sneller dan nepperfectie.', title_pl = 'Wylać złość na cyfrowy papier 📝', body_pl = 'Nikt nie widzi, jak bardzo jesteś dziś zmęczona, a uśmiechanie się cię dusi? Otwórz Dziennik nastroju. Wylej na ekran całą truciznę i zmęczenie, które w sobie masz. Napisanie „Nie mam już sił” uleczy cię szybciej niż udawana perfekcja.', title_pt = 'Despejar a raiva no digital 📝', body_pt = 'Ninguém vê o quanto se cansou hoje e sorrir está a sufocá-la? Abra o Diário de Humor. Despeje no ecrã todo esse veneno e todo o cansaço. Escrever "estou esgotada" vai curá-la mais depressa do que uma falsa perfeição.', title_sv = 'Häll ut ilskan digitalt 📝', body_sv = 'Ser ingen hur trött du har blivit i dag, och kväver det dig att le? Öppna Humördagboken. Häll ut allt gift och all trötthet på skärmen. Att skriva ”Jag är slut” läker dig snabbare än falsk perfektion.', title_vi = 'Trút cơn giận lên màn hình 📝', body_vi = 'Không ai thấy hôm nay mẹ đã mệt đến mức nào, và việc mỉm cười làm mẹ nghẹt thở? Hãy mở Nhật ký tâm trạng. Trút hết mọi bực bội, mệt mỏi trong lòng lên màn hình. Viết "Mình kiệt sức rồi" sẽ chữa lành cho mẹ nhanh hơn sự hoàn hảo giả tạo.', title_zh = '把心里的火倒进屏幕 📝', body_zh = '没人看到你今天有多累，微笑让你喘不过气？打开心情日记。把心里所有的“毒”和疲惫都倒在屏幕上。写下“我被掏空了”，会比假装完美更快治愈你。' WHERE id = '95ee8df4-a59a-42f4-b252-bf062304f70b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy has pasado mucho tiempo de pie y se te parte la espalda de correr detrás de él y recoger juguetes del suelo. En cuanto el peque se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el motor de esta casa, y un motor tiene que descansar y recuperarse sí o sí.', body_fr = 'Aujourd''hui, vous êtes restée longtemps debout, et à force de courir après lui et de ramasser les jouets, votre dos vous lâche. Dès que l''enfant dort, demandez à votre partenaire un massage des épaules de 10 minutes. Vous êtes le moteur de cette maison, et un moteur doit absolument se reposer et récupérer.', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते और फ़र्श से खिलौने उठाते-उठाते कमर टूट गई। बच्चे के सोते ही अपने साथी से 10 मिनट कंधों की मालिश माँगिए। आप इस घर का इंजन हैं, और इंजन को आराम और फिर से ऊर्जा ज़रूर चाहिए।', body_id = 'Hari ini Anda terlalu lama berdiri, punggung Anda serasa patah karena mengejarnya dan memunguti mainan dari lantai. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasangan Anda. Anda mesin rumah ini, dan mesin wajib beristirahat dan dipulihkan.', body_ja = '今日は一日じゅう立ちっぱなしで、この子を追いかけたり、床のおもちゃを拾ったりして、腰が痛いですね。子どもが寝たら、パートナーに10分間の肩もみをお願いしましょう。あなたはこの家のエンジン。エンジンには必ず休息と回復が必要です。', body_ko = '오늘 하루 종일 서 있으면서 아이를 쫓아다니고 바닥의 장난감을 줍느라 허리가 끊어질 것 같나요? 아이가 잠들면 바로 배우자에게 10분간 어깨 마사지를 부탁하세요. 엄마는 이 집의 엔진이고, 엔진은 꼭 쉬고 회복해야 해요.', body_nl = 'Je hebt vandaag veel gestaan, en van het achter hem aanrennen en speelgoed van de grond rapen doet je rug pijn. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de motor van dit huis, en een motor moet echt rusten en herstellen.', body_pl = 'Dziś dużo stałaś na nogach, a od biegania za nim i zbierania zabawek z podłogi pęka ci kręgosłup. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś silnikiem tego domu, a silnik koniecznie musi odpocząć i się zregenerować.', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de tanto correr atrás dele e apanhar brinquedos do chão. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o motor desta casa, e um motor precisa mesmo de descansar e recuperar.', body_sv = 'I dag har du stått mycket, ryggen värker av att springa efter barnet och plocka upp leksaker från golvet. Så fort barnet somnat, be din partner om en 10 minuters axelmassage. Du är hemmets motor, och en motor måste få vila och återhämta sig.', body_vi = 'Hôm nay mẹ đứng quá lâu, chạy theo bé, nhặt đồ chơi dưới sàn đến gãy lưng. Bé vừa ngủ, hãy nhờ chồng mát-xa vai cho mình 10 phút. Mẹ là động cơ của ngôi nhà này, mà động cơ thì nhất định phải được nghỉ ngơi và phục hồi.', body_zh = '今天你站了太久，追着宝宝跑、从地上捡玩具，腰都快断了。宝宝一睡着，就请另一半给你按摩10分钟肩膀。你是这个家的引擎，而引擎一定要休息、要恢复。' WHERE id = 'ec907054-781c-4e3c-be06-6c97119a4864' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡¿Por qué has pelado tú el plátano?! 🍌', body_es = '¿Se ha armado una revolución porque el plátano lo has pelado tú? La regla de oro de esta edad: todo lo tiene que decidir él. No puedes volver a pegar el plátano: dale otro enseguida y deja que lo pele como quiera. Ponerte cabezota solo te hará perder tiempo.', title_fr = 'Pourquoi c''est toi qui as épluché la banane ?! 🍌', body_fr = 'C''est la révolution dans la pièce parce que c''est vous qui avez épluché la banane ? La règle d''or de cet âge : c''est lui qui doit tout décider. Vous ne pourrez pas recoller la banane : donnez-en vite une nouvelle et laissez-le l''éplucher comme il veut. S''entêter ne vous fera que perdre du temps.', title_hi = 'केला तुमने क्यों छीला?! 🍌', body_hi = 'केला आपने छीला, इसलिए कमरे में क्रांति आ गई? इस उम्र का सुनहरा नियम: हर बात का फ़ैसला उसे करना है। केला वापस नहीं जोड़ सकतीं, फ़ौरन नया केला दीजिए, उसे जैसे चाहे छीलने दीजिए। ज़िद करने से आपका बस समय बर्बाद होगा।', title_id = 'Kenapa Mama yang kupas pisangnya?! 🍌', body_id = 'Revolusi meletus di kamar karena Anda yang mengupas pisangnya? Aturan emas usia ini: semuanya harus ia yang putuskan. Pisang tidak bisa ditempel lagi, segera beri pisang baru, biarkan ia mengupas sesuai keinginannya. Beradu keras kepala hanya membuang waktu Anda.', title_ja = 'なんでママがバナナをむいたの？！ 🍌', body_ja = 'あなたがバナナをむいたから大さわぎ？この年齢の黄金のルールは「何でも自分で決めたい」。バナナは元に戻せません。すぐに新しいバナナを渡して、好きなようにむかせてあげましょう。意地を張り合っても時間がなくなるだけです。', title_ko = '왜 엄마가 바나나 깠어?! 🍌', body_ko = '엄마가 바나나를 깠다고 방에 혁명이 일어났나요? 이 나이의 황금률: 모든 건 아이가 정해야 해요. 바나나를 다시 붙일 순 없으니 바로 새 바나나를 주고 원하는 대로 까게 두세요. 고집 싸움은 시간만 버릴 뿐이에요.', title_nl = 'Waarom heb jij de banaan gepeld?! 🍌', body_nl = 'Breekt er een revolutie uit omdat jij de banaan pelde? De gouden regel van deze leeftijd: hij moet over alles zelf beslissen. Je kunt de schil er niet weer omheen plakken, geef meteen een nieuwe banaan en laat hem die pellen zoals hij wil. Koppig volhouden kost je alleen maar tijd.', title_pl = 'Czemu to ty obrałaś banana?! 🍌', body_pl = 'W pokoju wybuchła rewolucja, bo to ty obrałaś banana? Złota zasada tego wieku: o wszystkim musi decydować on. Banana nie skleisz z powrotem, od razu daj nowego i niech obierze go sam, jak chce. Upieranie się tylko zabierze ci czas.', title_pt = 'Porque é que foste tu a descascar a banana?! 🍌', body_pt = 'Houve uma revolução no quarto porque foi a mãe a descascar a banana? A regra de ouro desta idade: é ele que tem de decidir tudo. Não consegue voltar a colar a banana, por isso dê-lhe logo uma nova e deixe-o descascá-la como quiser. Teimar só a vai fazer perder tempo.', title_sv = 'Varför skalade du bananen?! 🍌', body_sv = 'Blev det revolution i rummet för att du skalade bananen? Den här ålderns gyllene regel: barnet ska bestämma allt. Du kan inte sätta ihop bananen igen, ge genast en ny banan och låt barnet skala den som hen vill. Att tjafsa kostar dig bara tid.', title_vi = 'Sao mẹ lại bóc chuối?! 🍌', body_vi = 'Cả phòng nổi loạn chỉ vì mẹ bóc chuối? Quy tắc vàng của tuổi này: mọi thứ đều phải do bé quyết định. Mẹ không thể dán vỏ chuối lại, hãy đưa ngay quả mới và để bé tự bóc theo ý mình. Giằng co chỉ làm mẹ mất thời gian.', title_zh = '香蕉为什么是你剥的？！🍌', body_zh = '因为香蕉是你剥的，房间里就闹起了革命？这个年龄的黄金法则：什么都得宝宝自己决定。香蕉粘不回去了，马上再给一根新的，让宝宝按自己想要的方式剥。较劲只会浪费你的时间。' WHERE id = '486ad622-5eff-484f-8ea8-ea64a245ed91' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En silencio, en pareja 🥂', body_es = 'El peque duerme y la casa está recogida. Siéntate en el sofá junto a tu pareja, sin encender siquiera la tele. Solo miraos con esa mirada de «esto también lo hemos conseguido, hemos sobrevivido». Este es el momento de equipo más romántico y auténtico de ser padres.', title_fr = 'En silence, à deux 🥂', body_fr = 'L''enfant dort, la maison est rangée. Asseyez-vous côte à côte sur le canapé avec votre partenaire, sans même allumer la télé. Échangez simplement ce regard qui dit « On y est arrivés, on a survécu ». Voilà le moment d''équipe le plus romantique et le plus vrai de la vie de parents.', title_hi = 'जोड़ी के रूप में खामोशी में 🥂', body_hi = 'बच्चा सो गया, घर समेट लिया। अपने साथी के साथ सोफ़े पर पास-पास बैठिए, टीवी भी मत चलाइए। बस एक-दूसरे को ‘यह भी कर लिया, हम बच गए’ वाली नज़र से देखिए। पेरेंटिंग का सबसे रोमांटिक और सच्चा टीमवर्क वाला पल यही है।', title_id = 'Hening berdua sebagai pasangan 🥂', body_id = 'Anak sudah tidur, rumah sudah rapi. Duduklah berdampingan dengan pasangan di sofa, bahkan tanpa menyalakan TV. Cukup saling bertukar tatapan ''kita berhasil melewati ini juga, kita bertahan''. Inilah momen tim paling romantis dan nyata dalam menjadi orang tua.', title_ja = 'ふたりで静かな時間を 🥂', body_ja = '子どもは寝て、家も片づいた。パートナーとソファに並んで座り、テレビもつけないで。ただ「今日も乗りきったね」という視線を交わしましょう。それこそが、子育てのいちばんロマンチックで本当のチームの瞬間です。', title_ko = '부부가 함께하는 고요 🥂', body_ko = '아이는 잠들고 집도 정리됐어요. 배우자와 소파에 나란히 앉아 TV도 켜지 마세요. 그저 ''오늘도 해냈다, 살아남았다''는 눈빛을 서로 나누세요. 이게 바로 육아에서 가장 로맨틱하고 진짜인 팀워크의 순간이에요.', title_nl = 'Samen in stilte 🥂', body_nl = 'Je kind slaapt, het huis is opgeruimd. Ga met je partner naast elkaar op de bank zitten, zet zelfs de tv niet aan. Geef elkaar gewoon die blik van ''we hebben het weer gered, we hebben het overleefd''. Dit is het meest romantische en echte teammoment van het ouderschap.', title_pl = 'We dwoje w ciszy 🥂', body_pl = 'Dziecko śpi, dom posprzątany. Usiądź z partnerem obok siebie na kanapie, nawet nie włączajcie telewizora. Po prostu wymieńcie spojrzenia mówiące „i to nam się udało, przetrwaliśmy”. To właśnie najbardziej romantyczna i prawdziwa drużynowa chwila rodzicielstwa.', title_pt = 'Em silêncio, como um casal 🥂', body_pt = 'A criança adormeceu, a casa está arrumada. Sente-se no sofá ao lado do seu companheiro, nem sequer ligue a televisão. Troquem apenas aquele olhar de "também conseguimos isto, sobrevivemos". É este o momento de equipa mais romântico e verdadeiro da parentalidade.', title_sv = 'Tystnad som par 🥂', body_sv = 'Barnet sover, huset är städat. Sätt dig bredvid din partner i soffan och slå inte ens på tv:n. Ge bara varandra blicken som säger ”vi klarade det här också, vi överlevde”. Det är föräldraskapets mest romantiska och äkta lagstund.', title_vi = 'Hai vợ chồng trong yên lặng 🥂', body_vi = 'Bé đã ngủ, nhà đã dọn. Hãy ngồi cạnh chồng trên sofa, thậm chí đừng bật TV. Chỉ cần trao nhau ánh mắt "Chúng ta lại làm được rồi, lại sống sót rồi". Đó chính là khoảnh khắc đồng đội lãng mạn và chân thật nhất của việc làm cha mẹ.', title_zh = '两个人的安静时光 🥂', body_zh = '宝宝睡了，家也收拾好了。和另一半并肩坐在沙发上，连电视都别开。只要彼此对视一眼：“这一关我们也挺过来了。”这就是为人父母最浪漫、最真实的团队时刻。' WHERE id = 'b59a06d3-66eb-4eef-8c37-b58f8b3331ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una casita debajo de la mesa ⛺', body_es = '¿Se ha metido debajo de la mesa del comedor, se ha montado una casa y quiere comer ahí? Flexibiliza las reglas. Pásale la sopa a ese rincón oscuro. Cambiar de sitio puede hacer que hasta el niño más inapetente coma con sensación de aventura.', title_fr = 'La petite maison sous la table ⛺', body_fr = 'Il s''est construit une maison sous la table à manger et veut y déjeuner ? Assouplissez les règles. Tendez la soupe dans ce coin sombre. Changer de lieu peut nourrir, par le goût de l''aventure, même l''enfant le moins affamé.', title_hi = 'मेज़ के नीचे छोटा सा घर ⛺', body_hi = 'खाने की मेज़ के नीचे घुसकर अपना घर बना लिया है और लंच वहीं करना चाहता है? नियमों में थोड़ी ढील दीजिए। सूप उस अंधेरी जगह में पहुँचा दीजिए। जगह बदलने से रोमांच का एहसास सबसे कम भूख वाले बच्चे का भी पेट भर सकता है।', title_id = 'Rumah kecil di kolong meja ⛺', body_id = 'Ia masuk ke kolong meja makan, membuat rumah untuk dirinya, dan ingin makan siang di sana? Longgarkan aturannya. Sodorkan supnya ke tempat gelap itu. Pergantian tempat bisa membuat anak yang paling susah makan sekalipun kenyang berkat rasa petualangan.', title_ja = 'テーブルの下の小さなおうち ⛺', body_ja = '食卓の下にもぐっておうちをつくり、そこでお昼ごはんを食べたい？ルールを少しゆるめましょう。その薄暗い場所にスープを差し入れて。場所が変わると、食の細い子でも冒険気分でしっかり食べられます。', title_ko = '식탁 밑 작은 집 ⛺', body_ko = '식탁 밑에 들어가 집을 만들고 거기서 점심을 먹겠다고 하나요? 규칙을 조금 느슨하게 해 보세요. 그 어두운 공간으로 수프를 건네 주세요. 장소가 바뀌면 입맛 없는 아이도 모험하는 기분으로 배불리 먹을 수 있어요.', title_nl = 'Een huisje onder de tafel ⛺', body_nl = 'Heeft hij onder de eettafel een huisje gebouwd en wil hij daar lunchen? Wees wat soepeler met de regels. Geef de soep aan in dat donkere plekje. Een andere plek kan zelfs het minst hongerige kind laten eten met een gevoel van avontuur.', title_pl = 'Mały domek pod stołem ⛺', body_pl = 'Wszedł pod stół, zbudował sobie domek i chce tam zjeść obiad? Nagnij zasady. Podaj mu zupę do tej ciemnej kryjówki. Zmiana miejsca potrafi nakarmić poczuciem przygody nawet największego niejadka.', title_pt = 'A casinha debaixo da mesa ⛺', body_pt = 'Meteu-se debaixo da mesa de jantar, fez uma casa e quer almoçar lá? Flexibilize as regras. Passe-lhe a sopa para aquele cantinho escuro. Mudar de sítio consegue encher até a criança com menos apetite de um sentimento de aventura.', title_sv = 'Ett litet hus under bordet ⛺', body_sv = 'Har barnet krupit in under matbordet, byggt ett hus och vill äta lunch där? Tänj på reglerna. Räck in soppan till det mörka stället. En ny miljö kan med hjälp av äventyrskänslan få även det minst hungriga barnet att äta sig mätt.', title_vi = 'Ngôi nhà nhỏ dưới gầm bàn ⛺', body_vi = 'Bé chui xuống gầm bàn ăn, dựng cho mình một ngôi nhà và muốn ăn trưa ở đó? Hãy nới lỏng quy tắc. Đưa bát súp vào góc tối ấy. Thay đổi không gian có thể khiến cả đứa trẻ biếng ăn nhất cũng ăn no nhờ cảm giác phiêu lưu.', title_zh = '桌子底下的小房子 ⛺', body_zh = '钻到餐桌底下给自己搭了个“家”，还想在那里吃午饭？把规矩放宽一点。把汤递进那个昏暗的小空间吧。换个地方，再不爱吃饭的孩子也会被冒险感吸引，吃得饱饱的。' WHERE id = 'c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No juegas conmigo! 😠', body_es = '¿Mientras mirabas el móvil ha venido y te ha girado la cara hacia él con las manos: «¡Mírame!»? Tiene razón. No quiere tu presencia física, sino tu atención completa. Deja el móvil a un lado, míralo a los ojos 3 minutos y se calmará al instante.', title_fr = 'Tu ne joues pas avec moi ! 😠', body_fr = 'Pendant que vous regardiez votre téléphone, il est venu tourner votre visage vers lui avec ses mains : « Regarde-moi ! » ? Il a raison. Ce n''est pas votre présence physique qu''il veut, mais votre attention entière. Posez le téléphone, regardez-le dans les yeux pendant 3 minutes, et il se calmera aussitôt.', title_hi = 'तुम मेरे साथ नहीं खेल रहीं! 😠', body_hi = 'आप फ़ोन देख रही थीं और उसने आकर हाथों से आपका चेहरा अपनी ओर घुमाया: ‘मुझे देखो!’? वह सही है। उसे आपकी मौजूदगी नहीं, आपका पूरा ध्यान चाहिए। फ़ोन एक तरफ़ रखिए, 3 मिनट पूरी आँखों में आँखें डालिए, वह तुरंत शांत हो जाएगा।', title_id = 'Mama nggak main sama aku! 😠', body_id = 'Saat Anda melihat ponsel, ia datang dan memutar wajah Anda ke arahnya dengan kedua tangan: ''Lihat aku!''? Ia benar. Ia tidak menginginkan kehadiran fisik Anda, tapi perhatian Anda yang utuh. Letakkan ponsel, buat kontak mata penuh selama 3 menit, dan ia akan langsung tenang.', title_ja = 'ママ、遊んでくれない！ 😠', body_ja = 'スマホを見ていたら、やってきて両手であなたの顔を自分に向けて「ママ、見て！」？そのとおりです。そばにいるだけでなく、まるごとの注意を求めているんです。スマホを置いて3分間しっかり目を合わせれば、すぐに落ち着きます。', title_ko = '엄마는 나랑 안 놀아 줘! 😠', body_ko = '휴대폰을 보고 있는데 와서 두 손으로 엄마 얼굴을 돌리며 ''나 봐!'' 했나요? 맞는 말이에요. 몸이 곁에 있는 게 아니라 온전한 관심을 원해요. 휴대폰을 내려놓고 3분만 눈을 맞춰 주면 금세 진정할 거예요.', title_nl = 'Je speelt niet met mij! 😠', body_nl = 'Draaide hij terwijl jij op je telefoon keek met zijn handjes je gezicht naar zich toe: ''Kijk naar mij!''? Hij heeft gelijk. Hij wil niet alleen dat je er bent, hij wil je onverdeelde aandacht. Leg je telefoon weg, maak 3 minuten volledig oogcontact en hij kalmeert meteen.', title_pl = 'Nie bawisz się ze mną! 😠', body_pl = 'Gdy patrzyłaś w telefon, podszedł i rączkami odwrócił twoją twarz do siebie: „Patrz na mnie!”? Ma rację. Nie chodzi mu o twoją fizyczną obecność, tylko o niepodzielną uwagę. Odłóż telefon, przez 3 minuty patrz mu w oczy, a od razu się uspokoi.', title_pt = 'Não estás a brincar comigo! 😠', body_pt = 'Enquanto olhava para o telemóvel, ele veio virar-lhe a cara para ele com as mãos: "Olha para mim!"? Tem razão. Não quer a sua presença física, quer a sua atenção total. Ponha o telemóvel de lado, faça 3 minutos de contacto visual total e ele acalma-se logo.', title_sv = 'Du leker inte med mig! 😠', body_sv = 'Kom barnet medan du tittade i telefonen och vände ditt ansikte mot sig med händerna: ”Titta på mig!” Hen har rätt. Hen vill inte ha din fysiska närvaro, utan din odelade uppmärksamhet. Lägg undan telefonen, ha full ögonkontakt i 3 minuter, så lugnar sig barnet direkt.', title_vi = 'Mẹ không chơi với con! 😠', body_vi = 'Mẹ đang xem điện thoại thì bé đến, lấy tay xoay mặt mẹ về phía mình: "Mẹ nhìn con này!"? Bé nói đúng đấy. Bé không cần mẹ chỉ có mặt, mà cần sự chú ý trọn vẹn của mẹ. Đặt điện thoại xuống, nhìn thẳng vào mắt bé 3 phút, bé sẽ bình tĩnh ngay.', title_zh = '你都不陪我玩！😠', body_zh = '你在看手机时，宝宝过来用小手把你的脸转过去：“看我！”宝宝说得对。宝宝要的不是你在身边，而是你全部的注意力。把手机放到一边，看着宝宝的眼睛3分钟，宝宝马上就会平静下来。' WHERE id = '1f9be131-7868-4433-adc0-efe09d70723d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equilibrista en el bordillo 🧱', body_es = '¿De camino al parque no quiere ir por el camino recto, sino sí o sí por el borde más estrecho de la acera? Sujétalo del brazo y deja que conquiste esta pequeña cumbre. El equilibrio y la autoestima se desarrollan a la vez de forma perfecta, no se lo impidas.', title_fr = 'Funambule sur le bord du trottoir 🧱', body_fr = 'En allant au parc, il veut absolument marcher non pas sur le chemin, mais sur le rebord le plus étroit du trottoir ? Assurez-le en lui tenant le bras et laissez-le conquérir ce petit sommet. L''équilibre et la confiance en soi se développent parfaitement en même temps, ne l''en empêchez pas.', title_hi = 'फ़ुटपाथ के किनारे पर रस्सी वाला नट 🧱', body_hi = 'पार्क जाते समय सीधे रास्ते से नहीं, फ़ुटपाथ के सबसे पतले किनारे पर ही चलना चाहता है? हाथ पकड़कर सहारा दीजिए, उसे यह छोटी सी चोटी फ़तह करने दीजिए। संतुलन और आत्मविश्वास एक साथ शानदार ढंग से बढ़ते हैं, उसे मत रोकिए।', title_id = 'Pemain akrobat tali di tepi trotoar 🧱', body_id = 'Saat ke taman, ia tidak mau lewat jalan biasa dan bersikeras berjalan di tepi trotoar yang paling sempit? Pegangi lengannya untuk berjaga-jaga, biarkan ia menaklukkan puncak kecil ini. Keseimbangan dan rasa percaya dirinya berkembang sempurna sekaligus, jangan halangi.', title_ja = '歩道のふちで綱わたり 🧱', body_ja = '公園へ行くとき、まっすぐな道ではなく、歩道のいちばんせまいふちを歩きたがる？腕を支えて、この小さな頂上を制覇させてあげましょう。バランス感覚と自信が同時にぐんぐん育ちます。じゃまをしないで。', title_ko = '보도 끝의 줄타기 곡예사 🧱', body_ko = '공원에 가는 길에 평평한 길이 아니라 꼭 보도 가장 좁은 가장자리로 걷고 싶어 하나요? 팔을 잡아 안전을 지켜 주고 이 작은 정상을 정복하게 두세요. 균형 감각과 자신감이 동시에 쑥쑥 자라니 막지 마세요.', title_nl = 'Koorddansen op de stoeprand 🧱', body_nl = 'Wil hij op weg naar het park niet over het pad, maar per se over het smalste randje van de stoep lopen? Houd zijn arm vast voor de veiligheid en laat hem deze kleine top veroveren. Evenwicht en zelfvertrouwen ontwikkelen zich zo tegelijk perfect, houd hem niet tegen.', title_pl = 'Linoskoczek na krawężniku 🧱', body_pl = 'W drodze do parku nie chce iść prosto, tylko koniecznie po najwęższej krawędzi krawężnika? Asekuruj go za rękę i pozwól zdobyć ten mały szczyt. Równowaga i pewność siebie rozwijają się jednocześnie wspaniale, nie przeszkadzaj mu.', title_pt = 'Equilibrista na beira do passeio 🧱', body_pt = 'A caminho do parque, não quer ir pelo caminho direito, mas sim pela beira mais estreita do passeio? Segure-o pelo braço e deixe-o conquistar este pequeno cume. O equilíbrio e a autoconfiança desenvolvem-se na perfeição ao mesmo tempo, não o impeça.', title_sv = 'Lindansare på trottoarkanten 🧱', body_sv = 'Vill barnet på väg till parken inte gå rakt fram, utan absolut balansera på den smalaste trottoarkanten? Säkra barnet i armen och låt hen erövra den lilla toppen. Balans och självförtroende utvecklas samtidigt, stoppa inte barnet.', title_vi = 'Đi dây trên mép vỉa hè 🧱', body_vi = 'Trên đường ra công viên, bé không đi đường thẳng mà nhất định đi trên mép hẹp nhất của vỉa hè? Hãy đỡ tay bé cho an toàn và để bé chinh phục "đỉnh núi" nhỏ này. Khả năng giữ thăng bằng và sự tự tin đang cùng lúc phát triển tuyệt vời, đừng cản bé.', title_zh = '马路牙子上的走钢丝 🧱', body_zh = '去公园的路上不走平路，非要沿着人行道最窄的边走？扶好宝宝的胳膊，让宝宝征服这座小小的“山峰”吧。平衡感和自信心会同时完美地发展，别阻止。' WHERE id = '86f2c2e9-f758-416c-a78d-b431eb3db53a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Esta noche estás cansada de leer? Abre Cuentos inteligentes. Mientras lees la historia, monta un teatro de sonidos en la habitación con solo el chirrido de una puerta, el viento y unos susurros. Estas ondas sonoras tan originales meterán su atención al instante dentro del cuento.', body_fr = 'Fatiguée de lire ce soir ? Ouvrez les Contes intelligents. Pendant la lecture, faites simplement des grincements de porte, des bruits de vent et des chuchotements pour créer un théâtre sonore dans la chambre. Ces ondes sonores inhabituelles plongeront aussitôt son attention dans le conte.', body_hi = 'आज शाम पढ़ते-पढ़ते थक गईं? स्मार्ट कहानियाँ खोलिए। कहानी पढ़ते समय बस दरवाज़े की चरमराहट, हवा की आवाज़ और सरसराहट निकालकर कमरे में आवाज़ों का थिएटर बनाइए। ये अनोखी आवाज़ें उसका ध्यान तुरंत कहानी के अंदर खींच लेंगी।', body_id = 'Malam ini Anda lelah membaca? Buka Dongeng Pintar. Sambil membacakan cerita, buat teater suara di kamar cukup dengan bunyi pintu berderit, angin, dan desisan. Gelombang suara yang tak biasa ini akan langsung menarik perhatiannya masuk ke dalam dongeng.', body_ja = '今夜は読むのに疲れた？「スマートおはなし」を開きましょう。お話を読みながら、ドアのきしむ音や風の音、ささやき声を出して、部屋に音の劇場をつくって。ふしぎな音の波が、すぐにこの子をお話の中へ引きこみます。', body_ko = '오늘 저녁엔 읽기도 지쳤나요? 스마트 동화를 열어 보세요. 이야기를 읽으며 문 삐걱거리는 소리, 바람 소리, 속삭임을 내어 방 안에 소리 극장을 만들어 보세요. 이 특별한 소리가 아이의 관심을 단숨에 동화 속으로 끌어들일 거예요.', body_nl = 'Ben je vanavond moe van het voorlezen? Open Slimme sprookjes. Maak tijdens het voorlezen een geluidstheater in de kamer met alleen een krakende deur, waaiende wind en gefluister. Deze ongewone geluidsgolven trekken zijn aandacht meteen het sprookje in.', body_pl = 'Dziś wieczorem masz dość czytania? Otwórz Mądre bajki. Czytając historię, po prostu naśladuj skrzypienie drzwi, szum wiatru i syczenie, tworząc w pokoju teatr dźwięku. Te niezwykłe fale dźwiękowe od razu wciągną jego uwagę do bajki.', body_pt = 'Esta noite está cansada de ler? Abra as Histórias Inteligentes. Enquanto lê a história, faça só o ranger da porta, o som do vento e sussurros e monte um teatro de sons no quarto. Estas ondas sonoras invulgares vão puxar logo a atenção dele para dentro da história.', body_sv = 'Är du trött på att läsa i kväll? Öppna Smarta sagor. Medan du läser berättelsen, gör bara dörrknarr, vindsus och viskningar och bygg en ljudteater i rummet. De ovanliga ljudvågorna drar genast in barnets uppmärksamhet i sagan.', body_vi = 'Tối nay mẹ mệt không muốn đọc? Hãy mở Truyện cổ tích thông minh. Khi đọc truyện, chỉ cần tạo tiếng cửa kẽo kẹt, tiếng gió và tiếng xì xào để dựng một "nhà hát âm thanh" trong phòng. Những làn sóng âm khác lạ này sẽ lập tức kéo sự chú ý của bé vào câu chuyện.', body_zh = '今晚读累了？打开智慧童话。讲故事时，只要发出门吱呀声、风声和沙沙声，就能在房间里搭起一座声音剧场。这些不寻常的声音会立刻把宝宝的注意力拉进故事里。' WHERE id = '963db29c-a2ad-4233-bbc2-364a68692feb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica de la carrera para salir del parque 🌳', body_es = 'Es hora de volver del parque y empiezan las crisis de llanto. Llevarlo a rastras no va a funcionar. Dile «¿A ver quién llega antes al coche saltando como un conejo?» y lleva su atención enseguida a una competición divertida. Seguro que se apunta a la carrera.', title_fr = 'La tactique de la course pour quitter le parc 🌳', body_fr = 'C''est l''heure de rentrer du parc et les crises de larmes ont commencé. Le traîner ne servira à rien. Dites : « Voyons qui arrivera le premier à la voiture en sautant comme un lapin ! » et détournez aussitôt son attention vers une course rigolote, il voudra absolument participer.', title_hi = 'पार्क से निकलने की मुकाबले वाली तरकीब 🌳', body_hi = 'पार्क से लौटने का समय हो गया और रोना शुरू हो गया है। उसे घसीटकर ले जाना काम नहीं करेगा। ‘चलो देखें, गाड़ी तक खरगोश की तरह कौन जल्दी कूदता है?’ कहकर उसका ध्यान तुरंत एक मज़ेदार मुकाबले पर ले जाइए, वह ज़रूर दौड़ लगाएगा।', title_id = 'Taktik lomba untuk pulang dari taman 🌳', body_id = 'Sudah waktunya pulang dari taman dan krisis tangisan dimulai. Menyeretnya tidak akan berhasil. Katakan ''Yuk lihat, siapa yang paling cepat melompat seperti kelinci sampai mobil?'' dan segera alihkan perhatiannya ke lomba yang lucu, ia pasti ikut berlomba.', title_ja = '公園から帰るための競争作戦 🌳', body_ja = '公園から帰る時間になって、泣きわめき始めた。引きずって連れていってもうまくいきません。「車までうさぎみたいにぴょんぴょん、どっちが早いかな？」と言って、すぐにおもしろい競争に気をそらしましょう。きっと競争したくなりますよ。', title_ko = '공원에서 나오는 시합 작전 🌳', body_ko = '공원에서 돌아갈 시간인데 울음 폭발이 시작됐나요? 끌고 가는 건 소용없어요. ''차까지 누가 더 빨리 토끼처럼 뛰어갈까?'' 하며 바로 재미있는 시합으로 관심을 돌리세요. 아이는 꼭 경주하려 할 거예요.', title_nl = 'De wedstrijdtactiek om het park te verlaten 🌳', body_nl = 'Het is tijd om naar huis te gaan en de huilbuien zijn begonnen. Hem meeslepen werkt niet. Zeg: ''Wie springt er het snelst als een konijn naar de auto?'' en richt zijn aandacht meteen op een grappige wedstrijd, hij doet vast mee.', title_pl = 'Taktyka rywalizacji przy wyjściu z parku 🌳', body_pl = 'Pora wracać z parku i zaczęły się płaczliwe kryzysy. Ciągnięcie go siłą nic nie da. Zapytaj: „Zobaczmy, kto szybciej doskacze do auta jak zajączek?” i od razu przekieruj jego uwagę na zabawną rywalizację, na pewno stanie do wyścigu.', title_pt = 'A tática da competição para sair do parque 🌳', body_pt = 'É hora de voltar do parque e começaram as crises de choro. Levá-lo arrastado não vai resultar. Diga "Vamos ver quem chega mais depressa ao carro aos saltos como um coelho?" e desvie logo a atenção dele para uma competição divertida: ele vai entrar na corrida de certeza.', title_sv = 'Tävlingstaktiken för att lämna parken 🌳', body_sv = 'Det är dags att gå hem från parken och gråtkriserna har börjat. Att släpa iväg barnet fungerar inte. Säg ”Vi ser vem som först hoppar som en kanin till bilen!” och led genast om uppmärksamheten till en rolig tävling, barnet kommer absolut att tävla.', title_vi = 'Chiến thuật thi đua để rời công viên 🌳', body_vi = 'Đến giờ rời công viên và cơn khóc lóc bắt đầu. Kéo lê bé đi sẽ không có tác dụng. Hãy nói "Xem ai nhảy kiểu thỏ ra xe nhanh hơn nào?" để chuyển ngay sự chú ý của bé sang một cuộc thi vui nhộn, bé chắc chắn sẽ tham gia.', title_zh = '离开公园的比赛战术 🌳', body_zh = '该从公园回家了，哭闹开始了。硬拖着走没有用。说一句“我们看看谁能像小兔子一样先跳到车边？”，马上把注意力引到一场搞笑的比赛上，宝宝一定会参加。' WHERE id = '2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo respira su olor 🫂', body_es = '¿Hoy te ha vuelto loca de verdad y te ha dejado sin nada de energía? Pero duerme en la cama con tanta inocencia... Apaga las luces. Túmbate a su lado, respira hondo ese olor limpio de niño y susúrrale lo valioso que es.', title_fr = 'Respirez simplement son odeur 🫂', body_fr = 'Aujourd''hui, il vous a vraiment rendue folle et a aspiré toute votre énergie ? Mais il dort si innocemment dans son lit... Éteignez la lumière. Allongez-vous près de lui, respirez profondément cette pure odeur d''enfant et chuchotez-lui combien il est précieux.', title_hi = 'बस उसकी खुशबू अपने अंदर भर लीजिए 🫂', body_hi = 'आज उसने सच में आपको पागल कर दिया, सारी ऊर्जा पूरी तरह निचोड़ ली? पर बिस्तर पर कितना मासूम सो रहा है... लाइटें बंद कीजिए। उसके पास लेटिए, उस मासूम बच्चे की खुशबू गहरी साँसों में भरिए और फुसफुसाकर बताइए कि वह कितना कीमती है।', title_id = 'Cukup hirup aromanya 🫂', body_id = 'Hari ini ia benar-benar membuat Anda pusing dan menyedot habis energi Anda? Tapi ia tidur begitu polos di tempat tidurnya... Matikan lampu. Berbaringlah di sampingnya, hirup dalam-dalam aroma anak yang bersih itu, dan bisikkan betapa berharganya ia.', title_ja = 'においを深く吸いこんで 🫂', body_ja = '今日は本当に振りまわされて、エネルギーをすっかり吸いとられた？でも、ベッドではこんなに無邪気に眠っている…。明かりを消しましょう。そばに横になって、子どもの清らかなにおいを深く吸いこみ、どれほど大切かをささやいてあげて。', title_ko = '그냥 냄새를 깊이 들이마셔요 🫂', body_ko = '오늘 정말 미칠 것 같고 에너지를 몽땅 빼앗겼나요? 그래도 침대에선 저렇게 순하게 자고 있죠... 불을 끄세요. 옆에 누워 그 깨끗한 아이 냄새를 깊이 들이마시고, 얼마나 소중한지 속삭여 주세요.', title_nl = 'Snuif gewoon zijn geur op 🫂', body_nl = 'Heeft hij je vandaag echt gek gemaakt en al je energie helemaal opgezogen? Maar hij ligt zo onschuldig in bed... Doe het licht uit. Ga naast hem liggen, snuif diep die zuivere kindergeur op en fluister hoe kostbaar hij voor je is.', title_pl = 'Po prostu poczuj jego zapach 🫂', body_pl = 'Dziś naprawdę doprowadził cię do szału i wyssał z ciebie całą energię? A jednak śpi w łóżku tak niewinnie... Zgaś światło. Połóż się obok, głęboko wdychaj ten czysty dziecięcy zapach i wyszeptaj mu, jaki jest cenny.', title_pt = 'Respire só o cheirinho dele 🫂', body_pt = 'Hoje deu-lhe mesmo cabo da cabeça e sugou-lhe toda a energia? Mas está a dormir na cama tão inocente... Apague as luzes. Deite-se ao lado dele, respire fundo aquele cheirinho puro de criança e sussurre-lhe o quanto é precioso.', title_sv = 'Andas bara in doften 🫂', body_sv = 'Gjorde barnet dig verkligen galen i dag och sög ut precis all energi? Men i sängen ligger hen så oskyldigt... Släck lamporna. Lägg dig bredvid, andas djupt in den rena barndoften och viska hur värdefullt barnet är.', title_vi = 'Chỉ cần hít hương thơm của bé 🫂', body_vi = 'Hôm nay bé thật sự làm mẹ phát điên, rút cạn hết sức lực? Nhưng lúc này bé nằm ngủ trên giường thật ngây thơ... Hãy tắt đèn. Nằm xuống cạnh bé, hít thật sâu mùi hương trẻ thơ trong trẻo ấy và thì thầm rằng bé quý giá biết bao.', title_zh = '深深闻一闻宝宝的味道 🫂', body_zh = '今天宝宝真的快把你逼疯了，把你的能量全耗光了？可躺在床上的样子又那么天真……关上灯。躺在宝宝身边，深深吸一口那纯净的孩子气息，轻声告诉宝宝有多珍贵。' WHERE id = '42b47472-82e3-49e8-bb91-8de4938efbde' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Dame el agua en otro vaso! 🥤', body_es = '¿Se ha armado una buena porque le has dado el agua en el vaso amarillo? Dice «¡Yo quería el azul!». No le des más vueltas, solo está poniendo a prueba sus límites. Échale el agua en el vaso azul en un segundo, pon paz en la habitación y guarda tu energía.', title_fr = 'Donne l''eau dans un autre verre ! 🥤', body_fr = 'C''est l''apocalypse parce que vous avez servi l''eau dans le verre jaune ? Il dit : « Je voulais le bleu ! » Ne cherchez pas plus loin, il teste juste ses limites. Versez aussitôt l''eau dans le verre bleu, rétablissez la paix et préservez votre énergie.', title_hi = 'पानी दूसरे गिलास में दो! 🥤', body_hi = 'पानी पीले गिलास में दिया, इसलिए कमरे में तूफ़ान आ गया? ‘मुझे नीला चाहिए था!’ कहता है। ज़्यादा मत सोचिए, वह बस अपनी सीमाएँ परख रहा है। फ़ौरन पानी नीले गिलास में डाल दीजिए, कमरे में शांति लौटाइए और अपनी ऊर्जा बचाइए।', title_id = 'Kasih airnya di gelas lain! 🥤', body_id = 'Kiamat terjadi di kamar karena Anda memberinya air di gelas kuning? Ia berkata ''Aku maunya yang biru!''. Jangan terlalu dipikirkan, ia hanya sedang menguji batasannya. Segera tuang airnya ke gelas biru, kembalikan kedamaian di kamar, dan simpan energi Anda.', title_ja = 'お水はちがうコップで！ 🥤', body_ja = '黄色いコップでお水を出したから、部屋は大さわぎ？「青いのがよかったの！」と言っている。深く考えないで。境界線をためしているだけです。すぐに青いコップに入れなおして部屋に平和をとり戻し、エネルギーを守りましょう。', title_ko = '물은 다른 컵에 줘! 🥤', body_ko = '물을 노란 컵에 줬다고 방이 난리가 났나요? ''파란 컵 원했단 말이야!'' 하면서요. 깊이 생각하지 마세요, 경계를 시험하는 것뿐이에요. 바로 파란 컵에 물을 옮겨 담아 평화를 되찾고 에너지를 아끼세요.', title_nl = 'Geef water in een andere beker! 🥤', body_nl = 'Breekt de hel los omdat je zijn water in een gele beker gaf? ''Ik wilde de blauwe!'' Denk er niet te veel over na, hij test gewoon zijn grenzen. Schenk het water meteen in een blauwe beker, breng de vrede terug en spaar je energie.', title_pl = 'Podaj wodę w innym kubku! 🥤', body_pl = 'W pokoju wybuchła awantura, bo podałaś wodę w żółtym kubku? Woła: „Chciałem niebieski!”. Nie analizuj, on po prostu sprawdza granice. Od razu przelej wodę do niebieskiego kubka, przywróć spokój i oszczędzaj energię.', title_pt = 'Dá-me a água noutro copo! 🥤', body_pt = 'Foi o fim do mundo porque lhe deu a água num copo amarelo? "Eu queria o azul!", diz ele. Não pense demasiado: está só a testar limites. Deite logo a água num copo azul, restabeleça a paz no quarto e poupe a sua energia.', title_sv = 'Ge mig vattnet i ett annat glas! 🥤', body_sv = 'Utbryter världens undergång för att du serverade vattnet i det gula glaset? ”Jag ville ha det blå!” Gå inte på djupet, barnet testar bara sina gränser. Häll genast över vattnet i det blå glaset, skapa fred i rummet och spara din energi.', title_vi = 'Đưa nước bằng cốc khác cơ! 🥤', body_vi = 'Cả phòng như "tận thế" chỉ vì mẹ đưa nước bằng cốc màu vàng? Bé nói: "Con muốn cốc xanh cơ!" Đừng nghĩ nhiều, bé chỉ đang thử giới hạn thôi. Rót ngay nước sang cốc màu xanh, lập lại hòa bình trong phòng và giữ sức nhé.', title_zh = '换个杯子倒水！🥤', body_zh = '因为用黄杯子倒水，房间里就闹翻天了？“我要蓝色的！”别想太多，宝宝只是在试探底线。马上把水倒进蓝杯子，让房间恢复和平，保存你的精力。' WHERE id = '67931668-7ad8-456d-8077-31b1756abd2c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Los dinosaurios no comen papilla! 🦖', body_es = '¿Por la mañana no contesta a ninguna pregunta y solo ruge? Hoy es un T-Rex. Adáptate a la identidad que se ha inventado con un «¿Y los T-Rex desayunan?» y consigue en paz que se siente a la mesa sin lágrimas.', title_fr = 'Les dinosaures ne mangent pas de bouillie ! 🦖', body_fr = 'Le matin, il ne répond à aucune question et se contente de rugir ? Aujourd''hui, c''est un T-Rex. Demandez : « Et les T-Rex, ils prennent un petit-déjeuner ? », adaptez-vous à ce personnage inventé et faites-le s''asseoir à table sans larmes, en douceur.', title_hi = 'डायनासोर दलिया नहीं खाते! 🦖', body_hi = 'सुबह किसी सवाल का जवाब नहीं देता, बस दहाड़ता है? आज वह एक टी-रेक्स है। ‘तो क्या टी-रेक्स नाश्ता करते हैं?’ कहकर उसके गढ़े हुए किरदार के हिसाब से ढल जाइए और शांति से पक्का कीजिए कि वह बिना आँसुओं के मेज़ पर बैठ जाए।', title_id = 'Dinosaurus tidak makan bubur! 🦖', body_id = 'Pagi ini ia tidak menjawab satu pun pertanyaan, hanya mengaum? Hari ini ia seekor T-Rex. Ikuti identitas karangannya ini dengan bertanya ''T-Rex sarapan nggak ya?'' dan pastikan dengan damai ia duduk di meja tanpa air mata.', title_ja = '恐竜はおかゆを食べない！ 🦖', body_ja = '朝、何を聞いても答えず、ガオーとうなるだけ？今日はティラノサウルスなんです。「じゃあ、ティラノサウルスは朝ごはん食べるの？」と聞いて、この子がつくったキャラクターに合わせ、涙なしで穏やかに食卓につけるようにしましょう。', title_ko = '공룡은 죽 안 먹어! 🦖', body_ko = '아침에 아무 질문에도 대답 없이 으르렁거리기만 하나요? 오늘은 티라노사우루스래요. ''그런데 티라노도 아침 먹나?'' 하며 아이가 만든 캐릭터에 맞춰 주고, 눈물 없이 평화롭게 식탁에 앉게 해 주세요.', title_nl = 'Dinosaurussen eten geen pap! 🦖', body_nl = 'Geeft hij ''s ochtends op geen enkele vraag antwoord en brult hij alleen maar? Vandaag is hij een T-rex. Ga mee in zijn verzonnen identiteit met ''Eten T-rexen eigenlijk ontbijt?'' en zorg vreedzaam dat hij zonder tranen aan tafel gaat zitten.', title_pl = 'Dinozaury nie jedzą owsianki! 🦖', body_pl = 'Rano nie odpowiada na żadne pytanie, tylko ryczy? Dziś jest T-Reksem. Zapytaj: „A czy T-Reksy jedzą śniadanie?”, dopasuj się do wymyślonej przez niego postaci i pokojowo sprawisz, że usiądzie do stołu bez łez.', title_pt = 'Os dinossauros não comem papas! 🦖', body_pt = 'De manhã não responde a nenhuma pergunta, só ruge? Hoje é um T-Rex. Entre na personagem que ele inventou perguntando "E os T-Rex tomam o pequeno-almoço?" e faça com que se sente à mesa em paz e sem lágrimas.', title_sv = 'Dinosaurier äter inte gröt! 🦖', body_sv = 'Svarar barnet inte på en enda fråga på morgonen, utan bara ryter? I dag är hen en T-Rex. Säg ”Men äter T-Rexar frukost?”, anpassa dig efter den påhittade personligheten och se i lugn och ro till att barnet sätter sig vid bordet utan tårar.', title_vi = 'Khủng long không ăn cháo! 🦖', body_vi = 'Sáng nay bé không trả lời câu nào, chỉ gầm gừ? Hôm nay bé là một con T-Rex. Hãy hòa theo nhân vật bé tự nghĩ ra: "Thế T-Rex có ăn sáng không nhỉ?", để bé ngồi vào bàn trong hòa bình, không có giọt nước mắt nào.', title_zh = '恐龙不吃粥！🦖', body_zh = '早上什么问题都不回答，只会“嗷呜”？今天宝宝是一只霸王龙。说一句“那霸王龙早上吃早餐吗？”，配合宝宝编出来的这个身份，平和地让宝宝不掉眼泪地坐到餐桌前。' WHERE id = '047715fd-ae66-4d00-8341-50e230c2b688' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quedarse en blanco en medio del súper 🛒', body_es = '¿Has entrado en el súper y se te ha olvidado qué ibas a comprar? El cerebro de mamá está de verdad a tope. Abrir la Lista de la compra de la app y confiar en esa memoria digital siempre te salvará de volver a casa con las manos vacías.', title_fr = 'Figée au milieu du supermarché 🛒', body_fr = 'Vous êtes entrée au supermarché et avez oublié ce que vous deviez acheter ? Le cerveau d''une maman est vraiment surchargé. Ouvrir la Liste de courses de l''application et faire confiance à cette mémoire numérique vous évitera toujours de rentrer les mains vides.', title_hi = 'सुपरमार्केट के बीच में जम जाना 🛒', body_hi = 'सुपरमार्केट में घुसीं और भूल गईं कि क्या लेना है? माँ का दिमाग सच में बहुत भरा होता है। ऐप में शॉपिंग लिस्ट खोलकर उस डिजिटल याददाश्त पर भरोसा करना आपको खाली हाथ घर लौटने से हमेशा बचाएगा।', title_id = 'Terpaku di tengah supermarket 🛒', body_id = 'Anda masuk supermarket dan lupa mau beli apa? Otak seorang ibu memang sangat penuh. Membuka Daftar Belanja di aplikasi dan mengandalkan memori digital itu akan selalu menyelamatkan Anda dari pulang dengan tangan kosong.', title_ja = 'スーパーのまん中でフリーズ 🛒', body_ja = 'スーパーに入ったら、何を買うか忘れてしまった？ママの頭は本当にいっぱいなんです。アプリの「買い物リスト」を開いて、そのデジタルの記憶にたよれば、手ぶらで帰ることもなくなります。', title_ko = '마트 한가운데서 멈춤 🛒', body_ko = '마트에 들어갔는데 뭘 사야 할지 잊어버렸나요? 엄마의 머리는 정말 꽉 차 있거든요. 앱의 쇼핑 목록을 열고 디지털 기억에 맡기면 빈손으로 돌아오는 일은 언제나 막을 수 있어요.', title_nl = 'Bevroren midden in de supermarkt 🛒', body_nl = 'Kom je de supermarkt in en weet je niet meer wat je moest kopen? Een mamabrein zit echt overvol. Open het Boodschappenlijstje in de app en vertrouw op dat digitale geheugen, dan kom je nooit meer met lege handen thuis.', title_pl = 'Zawieszona na środku sklepu 🛒', body_pl = 'Weszłaś do sklepu i zapomniałaś, co miałaś kupić? Mamusiowy mózg naprawdę jest przepełniony. Otwórz Listę zakupów w aplikacji i zaufaj tej cyfrowej pamięci, zawsze uchroni cię przed powrotem do domu z pustymi rękami.', title_pt = 'Parada no meio do supermercado 🛒', body_pt = 'Entrou no supermercado e esqueceu-se do que ia comprar? O cérebro de mãe anda mesmo cheio. Abrir a Lista de Compras da app e confiar nessa memória digital vai salvá-la sempre de voltar para casa de mãos a abanar.', title_sv = 'Att stelna till mitt i affären 🛒', body_sv = 'Gick du in i affären och glömde vad du skulle köpa? Mammahjärnan är verkligen överfull. Att öppna Inköpslistan i appen och lita på det digitala minnet räddar dig alltid från att komma hem tomhänt.', title_vi = 'Đứng hình giữa siêu thị 🛒', body_vi = 'Vào siêu thị rồi mà quên mất định mua gì? Đầu óc người mẹ thật sự đã quá tải. Mở Danh sách mua sắm trong ứng dụng và tin vào "bộ nhớ số" ấy sẽ luôn giúp mẹ không phải về nhà tay không.', title_zh = '在超市中间愣住 🛒', body_zh = '走进超市，却忘了要买什么？当了妈妈，大脑真的太满了。打开应用里的购物清单，交给这份数字记忆，你就再也不会空着手回家。' WHERE id = '2da52e9b-b72c-461f-8480-276d6d5e47df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es una obra de arte 🎨', body_es = '¿Ha creado una gran obra de arte con pasta seca y trocitos de papel en medio de la habitación? Deja a un lado la obsesión por la limpieza. Es un trabajo de motricidad tan bonito que merece entrar en el Seguimiento del desarrollo. La casa no es un museo.', title_fr = 'Pas des déchets, une œuvre d''art 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre d''art avec des pâtes sèches et des bouts de papier ? Mettez de côté l''obsession du ménage. C''est un travail de motricité globale assez beau pour figurer dans le Suivi de développement. La maison n''est pas un musée.', title_hi = 'कूड़ा नहीं, कलाकृति है 🎨', body_hi = 'कमरे के बीच सूखे पास्ता और कागज़ के टुकड़ों से एक बड़ी कलाकृति बना दी है? सफ़ाई की धुन एक तरफ़ रखिए। यह बड़ी मोटर स्किल्स का इतना सुंदर काम है कि ग्रोथ ट्रैकर में दर्ज होने लायक है। घर कोई म्यूज़ियम नहीं है।', title_id = 'Bukan sampah, tapi karya seni 🎨', body_id = 'Di tengah kamar ia membuat karya seni besar dari makaroni kering dan sobekan kertas? Singkirkan dulu obsesi kebersihan. Ini karya motorik kasar yang cukup indah untuk dicatat di Pelacak Perkembangan. Rumah bukan museum.', title_ja = 'ゴミじゃなくてアート作品 🎨', body_ja = '部屋のまん中に、乾いたパスタや紙きれで大きなアート作品をつくった？きれい好きはひと休み。これは「発達トラッカー」に記録したくなるほどすてきな、体全体を使った運動の作品です。家は美術館ではありません。', title_ko = '쓰레기가 아니라 예술 작품이에요 🎨', body_ko = '방 한가운데 마른 파스타와 종이 조각으로 커다란 예술 작품을 만들었나요? 깔끔 강박은 잠시 내려놓으세요. 성장 기록에 남길 만큼 멋진 대근육 활동이에요. 집은 박물관이 아니니까요.', title_nl = 'Geen afval, maar kunst 🎨', body_nl = 'Heeft hij midden in de kamer een groot kunstwerk gemaakt van droge pasta en papiersnippers? Zet je opruimobsessie opzij. Dit is grove motoriek die mooi genoeg is voor de Groeitracker. Je huis is geen museum.', title_pl = 'To nie śmieci, to dzieło sztuki 🎨', body_pl = 'Na środku pokoju stworzył wielkie dzieło sztuki z suchego makaronu i skrawków papieru? Odłóż obsesję porządku na bok. To praca motoryczna tak piękna, że zasługuje na miejsce w Śledzeniu rozwoju. Dom to nie muzeum.', title_pt = 'Não é lixo, é uma obra de arte 🎨', body_pt = 'No meio do quarto criou uma grande obra de arte com massa seca e pedacinhos de papel? Ponha de lado a obsessão pela limpeza. É um trabalho de motricidade tão bonito que merece ir para o Registo de Crescimento. A casa não é um museu.', title_sv = 'Inte skräp, utan ett konstverk 🎨', body_sv = 'Har barnet skapat ett stort konstverk av torr pasta och pappersbitar mitt i rummet? Lägg städmanin åt sidan. Det är ett grovmotoriskt arbete som är fint nog att hamna i Utvecklingsspåraren. Hemmet är inget museum.', title_vi = 'Không phải rác, mà là nghệ thuật 🎨', body_vi = 'Bé tạo ra một tác phẩm nghệ thuật lớn từ mì ống khô và giấy vụn ngay giữa phòng? Hãy gác lại nỗi ám ảnh sạch sẽ. Đây là một bài tập vận động thô đẹp đến mức đáng ghi vào Theo dõi phát triển. Nhà đâu phải viện bảo tàng.', title_zh = '不是垃圾，是艺术品 🎨', body_zh = '在房间中间用干意面和碎纸片创作了一件大“艺术品”？先放下你的整洁强迫症。这是一件值得记进成长记录的大运动作品。家不是博物馆。' WHERE id = '020f5f2c-bba3-4441-b9a0-518ce0263ac5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El número del silencio en la pantalla 📉', body_es = 'Por fin se ha dormido. ¿Hay tanto silencio en casa que te pitan los oídos? Abre el Medidor de sonido en la app. Ver ese 0 decibelios será el mejor masaje visual del mundo para tu cerebro cansado y saturado de ruido.', title_fr = 'Le chiffre du silence à l''écran 📉', body_fr = 'Il dort enfin. Un tel silence est tombé sur la maison que vos oreilles bourdonnent ? Ouvrez le Sonomètre dans l''application. Voir afficher 0 décibel sera le meilleur massage visuel au monde pour votre cerveau fatigué, saturé de bruit.', title_hi = 'स्क्रीन पर खामोशी का आँकड़ा 📉', body_hi = 'आखिरकार सो गया। घर में ऐसा सन्नाटा छा गया कि कानों में सीटी सी बज रही है? ऐप में साउंड मीटर खोलिए। वह ‘0 डेसिबल’ देखना आपके थके, शोर से भरे दिमाग के लिए दुनिया की सबसे अच्छी विज़ुअल मसाज होगी।', title_id = 'Angka keheningan di layar 📉', body_id = 'Akhirnya ia tidur. Rumah begitu hening sampai telinga Anda berdenging? Buka Pengukur Suara di aplikasi. Melihat tulisan 0 desibel itu akan menjadi pijatan visual terbaik di dunia untuk otak Anda yang lelah dan penuh kebisingan.', title_ja = '静けさを示す画面の数字 📉', body_ja = 'やっと寝てくれた。家が静かすぎて耳鳴りがする？アプリで「サウンドメーター」を開いてみて。0デシベルの表示を見ることが、疲れて騒音でいっぱいの頭にとって、世界一の目のマッサージになります。', title_ko = '화면 속 고요의 숫자 📉', body_ko = '드디어 잠들었어요. 집이 너무 고요해져 귀가 울릴 정도인가요? 앱에서 소음 측정기를 열어 보세요. 0 데시벨이라는 숫자를 보는 것만으로 소음에 지친 머리에 세상에서 가장 좋은 시각적 마사지가 될 거예요.', title_nl = 'Stilte in cijfers op het scherm 📉', body_nl = 'Eindelijk slaapt hij. Is het zo stil in huis dat je oren suizen? Open de Geluidsmeter in de app. Kijken naar die 0 decibel is de beste visuele massage voor je vermoeide, door lawaai overprikkelde brein.', title_pl = 'Cisza w liczbach na ekranie 📉', body_pl = 'Wreszcie zasnął. W domu zapadła taka cisza, że aż dzwoni ci w uszach? Otwórz w aplikacji Miernik dźwięku. Widok napisu 0 decybeli będzie dla twojego zmęczonego, przeładowanego hałasem mózgu najlepszym wizualnym masażem na świecie.', title_pt = 'O número do silêncio no ecrã 📉', body_pt = 'Finalmente adormeceu. Caiu um silêncio tão grande na casa que lhe zumbem os ouvidos? Abra o Medidor de Som na app. Olhar para aqueles 0 decibéis será a melhor massagem visual do mundo para o seu cérebro cansado e inchado de barulho.', title_sv = 'Tystnaden i siffror på skärmen 📉', body_sv = 'Äntligen sover barnet. Det har blivit så tyst hemma att det ringer i öronen? Öppna Ljudmätaren i appen. Att titta på 0 decibel blir världens bästa visuella massage för din trötta, bullerfyllda hjärna.', title_vi = 'Con số của sự im lặng trên màn hình 📉', body_vi = 'Cuối cùng bé cũng ngủ. Nhà yên tĩnh đến mức tai mẹ ù đi? Hãy mở Đo âm thanh trong ứng dụng. Nhìn con số 0 decibel sẽ là màn mát-xa thị giác tuyệt vời nhất cho bộ não mệt mỏi, căng thẳng vì tiếng ồn của mẹ.', title_zh = '屏幕上的安静数字 📉', body_zh = '终于睡着了。家里安静得让你耳朵都嗡嗡响？打开应用里的分贝仪。看着那个0分贝，对你疲惫、被噪音塞满的大脑来说，就是世界上最好的视觉按摩。' WHERE id = '7231bd75-47cb-4255-ae64-144dcd8d314f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cuando se le olvida una palabra hace gestos con la mano y espera a que la adivines? Su vocabulario crece, pero su cerebro va más rápido que su lengua. Cuando completes su frase con paciencia, fíjate en ese alivio de «¡eso, eso es lo que quería decir!» en su cara.', body_fr = 'Quand il oublie un mot, il fait des gestes avec ses mains et attend que vous le trouviez ? Son vocabulaire grandit, mais son cerveau va plus vite que sa langue. Quand vous terminez patiemment sa phrase, observez le soulagement sur son visage qui dit « Ouiii, c''est exactement ça ! ».', body_hi = 'कोई शब्द भूलने पर हाथों से इशारे करके इंतज़ार करता है कि आप ढूँढ दें? उसकी शब्दावली बढ़ रही है, पर दिमाग ज़ुबान से तेज़ चलता है। धीरज से उसका वाक्य पूरा कीजिए और उसके चेहरे पर आई ‘हाँ, यही कहना था’ वाली राहत देखिए।', body_id = 'Saat lupa satu kata, ia memberi isyarat dengan tangan dan menunggu Anda menebaknya? Kosakatanya bertambah, tapi otaknya bekerja lebih cepat daripada lidahnya. Saat Anda dengan sabar melengkapi kalimatnya, perhatikan rasa lega di wajahnya: ''Iya, itu maksudku''.', body_ja = 'ことばを忘れると、手でジェスチャーをしてあなたが当てるのを待つ？語彙は増えているけれど、頭の回転のほうが口より速いんです。根気よく文を完成させてあげたときの「そう、それが言いたかったの」というほっとした顔を見て。', body_ko = '단어가 생각나지 않으면 손짓을 하며 엄마가 맞혀 주길 기다리나요? 어휘는 늘고 있지만 머리가 입보다 빨리 움직여요. 차분히 문장을 완성해 줄 때 ''응, 바로 그 말이야!'' 하며 번지는 안도감을 지켜보세요.', body_nl = 'Maakt hij gebaren als hij een woord vergeet en wacht hij tot jij het raadt? Zijn woordenschat groeit, maar zijn brein werkt sneller dan zijn tong. Kijk naar die opluchting op zijn gezicht, ''Ja, dát bedoelde ik!'', als je geduldig zijn zin afmaakt.', body_pl = 'Gdy zapomni słowa, pokazuje coś rękami i czeka, aż zgadniesz? Jego słownictwo rośnie, ale mózg pracuje szybciej niż język. Gdy cierpliwie dokończysz jego zdanie, przyjrzyj się uldze na jego twarzy, mówiącej „taak, właśnie to chciałem powiedzieć”.', body_pt = 'Quando se esquece de uma palavra, faz gestos com as mãos e espera que a adivinhe? O vocabulário está a crescer, mas o cérebro trabalha mais depressa do que a língua. Ao completar com paciência a frase dele, repare no alívio de "isso, era mesmo isso que eu queria dizer" que lhe aparece no rosto.', body_sv = 'När barnet glömmer ett ord gör hen tecken med händerna och väntar på att du ska hitta det? Ordförrådet växer, men hjärnan arbetar snabbare än tungan. När du tålmodigt avslutar meningen, se lättnaden i ansiktet: ”Jaa, det var precis det jag menade!”', body_vi = 'Quên một từ, bé ra hiệu bằng tay và chờ mẹ đoán ra? Vốn từ của bé đang lớn, nhưng não bé chạy nhanh hơn lưỡi. Hãy kiên nhẫn giúp bé nói trọn câu và ngắm vẻ nhẹ nhõm "Đúng rồi, con định nói thế đấy" trên gương mặt bé.', body_zh = '忘了一个词，就用手比划，等你来猜？宝宝的词汇在增长，但大脑转得比嘴快。耐心地帮宝宝把句子说完，看看宝宝脸上那种“对，我就是想说这个”的轻松。' WHERE id = 'd3223299-be6e-4dfc-bfb7-c168e33bb866' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lucha en el sofá con papá 🤼‍♂️', body_es = '¿Ha salido corriendo a esconderse para no irse a la cama? Pásale la pelota a papá. Que hagan una lucha de mentira en el sofá. Ese juego ruidoso y sudoroso con papá le quitará hasta la última gota de energía rebelde y lo rendirá al sueño sin esfuerzo.', title_fr = 'Lutte sur le canapé avec papa 🤼‍♂️', body_fr = 'Il s''est enfui et caché pour ne pas aller au lit ? Passez la balle à papa. Qu''ils fassent semblant de lutter. Ce jeu bruyant et transpirant entre papa et son enfant aspirera ses dernières réserves d''énergie têtue et le livrera facilement au sommeil.', title_hi = 'पापा के साथ सोफ़े पर कुश्ती 🤼‍♂️', body_hi = 'सोने न जाने के लिए भागकर छिप गया? गेंद पापा के पाले में डालिए। उन्हें सोफ़े पर नकली कुश्ती करने दीजिए। पापा और बच्चे का यह शोर-शराबे वाला, पसीना छुड़ाने वाला खेल बच्चे की आखिरी ज़िद्दी ऊर्जा भी सोख लेगा और उसे आसानी से नींद के हवाले कर देगा।', title_id = 'Gulat di sofa bersama Ayah 🤼‍♂️', body_id = 'Ia lari dan bersembunyi supaya tidak tidur? Oper bolanya ke Ayah. Biarkan mereka gulat pura-pura di sofa. Permainan Ayah dan anak yang heboh dan bikin berkeringat ini akan menyedot sisa energi keras kepalanya dan membuatnya mudah menyerah pada kantuk.', title_ja = 'パパとソファでレスリング 🤼‍♂️', body_ja = '寝たくなくて逃げて隠れた？ボールはパパにパス。ソファでレスリングごっこをしてもらいましょう。にぎやかで汗をかくパパとの遊びが、最後のがんこなエネルギーまで使いきって、すんなり眠りへと導いてくれます。', title_ko = '아빠와 소파 레슬링 🤼‍♂️', body_ko = '자러 가기 싫어서 도망쳐 숨었나요? 공을 아빠에게 넘기세요. 장난 레슬링을 하게 두세요. 시끌벅적하고 땀나는 아빠와의 놀이가 마지막 남은 고집스러운 에너지까지 빼내 쉽게 잠에 항복하게 할 거예요.', title_nl = 'Stoeien op de bank met papa 🤼‍♂️', body_nl = 'Is hij weggerend en verstopt om niet naar bed te hoeven? Speel de bal door naar papa. Laat ze een nepworstelpartij houden. Dat luidruchtige, bezwete spel met papa zuigt zijn laatste koppige energie op en laat hem makkelijk in slaap vallen.', title_pl = 'Zapasy z tatą na kanapie 🤼‍♂️', body_pl = 'Uciekł i schował się, żeby nie iść spać? Przekaż piłeczkę tacie. Niech pobawią się w udawane zapasy. Ta głośna, męcząca zabawa taty z dzieckiem wyssie z malucha resztki upartej energii i łatwo odda je we władanie snu.', title_pt = 'Luta no sofá com o pai 🤼‍♂️', body_pt = 'Fugiu e escondeu-se para não ir para a cama? Passe a bola ao pai. Que façam uma luta a fingir junto à parede. Essa brincadeira barulhenta e suada entre pai e filho vai gastar a última energia teimosa e entregá-lo facilmente ao sono.', title_sv = 'Soffbrottning med pappa 🤼‍♂️', body_sv = 'Sprang barnet iväg och gömde sig för att slippa gå och lägga sig? Skicka bollen till pappa. Låt dem låtsasbrottas i soffan. Den högljudda, svettiga leken med pappa suger ut barnets sista envisa energi och får hen att lätt ge upp för sömnen.', title_vi = 'Đấu vật trên sofa cùng bố 🤼‍♂️', body_vi = 'Bé chạy trốn để khỏi phải đi ngủ? Hãy chuyền bóng cho bố. Để hai bố con vật nhau "giả vờ" bên tường. Trò chơi ồn ào, đẫm mồ hôi cùng bố sẽ rút cạn chút năng lượng bướng bỉnh cuối cùng và đưa bé vào giấc ngủ thật dễ dàng.', title_zh = '和爸爸在沙发上摔跤 🤼‍♂️', body_zh = '为了不去睡觉，跑去躲起来了？把球传给爸爸。让他们假装摔跤。这场又吵又出汗的亲子游戏，会把宝宝最后那点倔强的能量耗光，让宝宝轻松入睡。' WHERE id = '3f9c24cf-68b9-4b5b-9e40-a3652b7d443e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de esconder las verduras 🥦', body_es = '¿Ha encontrado esa única zanahoria en la sopa y ha dicho «Esto no me lo como»? Haz puré las verduras y mételas en las salsas, ¡a ver cómo las encuentra ahora! Gánale con maña a ese genio de la cocina.', title_fr = 'L''art de cacher les légumes 🥦', body_fr = 'Il a trouvé l''unique rondelle de carotte dans la soupe et a dit « Je mange pas ça » ? Réduisez les légumes en purée et ajoutez-les aux sauces, on verra s''il les trouve maintenant ! Battez habilement ce petit génie culinaire.', title_hi = 'सब्ज़ियाँ छिपाने की कला 🥦', body_hi = 'सूप में गाजर का वह एक टुकड़ा ढूँढकर बोला, ‘यह मैं नहीं खाऊँगा’? सब्ज़ियों की प्यूरी बनाकर सॉस में मिलाइए, फिर देखते हैं कैसे ढूँढता है! उसकी पाक-कला वाली समझ को बड़ी चतुराई से मात दीजिए।', title_id = 'Seni menyembunyikan sayur 🥦', body_id = 'Ia menemukan satu potong wortel di supnya dan berkata ''Aku nggak mau makan ini''? Haluskan sayurnya dan campurkan ke saus, coba lihat bagaimana ia akan menemukannya sekarang! Kalahkan kecerdasan kulinernya itu dengan cerdik.', title_ja = '野菜を隠すテクニック 🥦', body_ja = 'スープの中のにんじんひとかけを見つけて「これは食べない」と言った？野菜をピューレにしてソースにまぜ、さあ見つけられるかな！この小さなシェフの知恵に、上手に勝ちましょう。', title_ko = '채소 숨기기의 기술 🥦', body_ko = '수프 속 당근 한 조각을 찾아내고 ''이거 안 먹어'' 했나요? 채소를 퓌레로 만들어 소스에 섞어 보세요. 이제 어떻게 찾나 볼까요! 그 요리 감별 능력을 멋지게 이겨 보세요.', title_nl = 'De kunst van groenten verstoppen 🥦', body_nl = 'Vond hij dat ene stukje wortel in zijn soep en zei hij ''Dit eet ik niet''? Pureer de groenten en verwerk ze in sauzen, eens kijken hoe hij ze nu vindt! Wees zijn kookinstinct slim af.', title_pl = 'Sztuka ukrywania warzyw 🥦', body_pl = 'Znalazł w zupie tę jedną marchewkę i oznajmił: „Tego nie jem”? Zmiksuj warzywa i dodaj je do sosów, zobaczymy, jak teraz je znajdzie! Po mistrzowsku przechytrz ten kulinarny geniusz.', title_pt = 'A arte de esconder legumes 🥦', body_pt = 'Encontrou na sopa aquele único pedaço de cenoura e disse "Isto não como"? Faça puré dos legumes e junte-os aos molhos: vamos ver como os encontra agora! Vença com mestria aquela inteligência de pequeno chef.', title_sv = 'Konsten att gömma grönsaker 🥦', body_sv = 'Hittade barnet den enda morotsbiten i soppan och sa ”Det där äter jag inte”? Mixa grönsakerna och blanda dem i såser, så får vi se hur hen hittar dem nu! Överlista den lilla kockhjärnan på ett mästerligt sätt.', title_vi = 'Nghệ thuật giấu rau củ 🥦', body_vi = 'Bé tìm ra đúng một miếng cà rốt trong súp và tuyên bố "Con không ăn cái này"? Hãy xay nhuyễn rau và trộn vào nước sốt, xem giờ bé còn tìm thấy không! Hãy khéo léo chiến thắng "trí tuệ ẩm thực" ấy.', title_zh = '藏蔬菜的艺术 🥦', body_zh = '在汤里找到唯一一块胡萝卜，就说“我不吃这个”？把蔬菜打成泥拌进酱汁里，看宝宝现在还怎么找！巧妙地智胜这位小美食家吧。' WHERE id = '4d053e9f-b091-45c7-9c6a-66e7f1ab590e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Quiero volar! 🕊️', body_es = '¿Salta del sofá agitando los brazos y se enfada contigo porque no vuela? Todavía es pronto para enseñarle las leyes de la física. Dile «No vuelas porque tus alas todavía están creciendo» y lleva su atención a saltar sobre algo blandito.', title_fr = 'Je veux voler ! 🕊️', body_fr = 'Il saute du canapé en battant des bras et vous en veut de ne pas voler ? Il est encore trop tôt pour lui apprendre les lois de la physique. Dites « Tu ne voles pas parce que tes ailes sont encore en train de pousser » et orientez-le vers des sauts sur un endroit moelleux.', title_hi = 'मुझे उड़ना है! 🕊️', body_hi = 'सोफ़े से कूदकर बाँहें फड़फड़ाता है और उड़ न पाने पर आपसे नाराज़ होता है? भौतिकी के नियम सिखाना अभी जल्दी है। ‘तुम नहीं उड़ते, क्योंकि तुम्हारे पंख अभी बढ़ रहे हैं’ कहकर उसका ध्यान किसी नरम जगह पर कूदने की ओर लगाइए।', title_id = 'Aku mau terbang! 🕊️', body_id = 'Ia melompat dari sofa sambil mengepakkan tangan dan marah pada Anda karena tidak bisa terbang? Masih terlalu dini mengajarinya hukum fisika. Katakan ''Kamu belum bisa terbang karena sayapmu masih tumbuh'' dan alihkan perhatiannya untuk melompat ke tempat yang empuk.', title_ja = '飛びたいの！ 🕊️', body_ja = 'ソファから飛びおりて腕をパタパタさせ、飛べないことにあなたへ怒っている？物理の法則を教えるのはまだ早いですね。「飛べないのは、羽がまだ育っているからだよ」と言って、やわらかい場所へのジャンプに気をそらしましょう。', title_ko = '날고 싶어! 🕊️', body_ko = '소파에서 뛰어내리며 팔을 퍼덕이다가 못 날았다고 엄마에게 화를 내나요? 물리 법칙을 가르치기엔 아직 일러요. ''아직 날개가 자라는 중이라 못 나는 거야'' 하며 푹신한 곳으로 뛰어내리는 놀이로 관심을 돌려 주세요.', title_nl = 'Ik wil vliegen! 🕊️', body_nl = 'Springt hij van de bank, fladdert hij met zijn armen en is hij boos op je omdat hij niet vliegt? Het is nog te vroeg om hem de wetten van de natuurkunde te leren. Zeg ''Je vliegt nog niet, want je vleugels groeien nog'' en richt zijn aandacht op springen op een zachte plek.', title_pl = 'Chcę latać! 🕊️', body_pl = 'Skacze z kanapy, macha rękami i złości się na ciebie, że nie leci? Na naukę praw fizyki jest jeszcze za wcześnie. Powiedz: „Nie latasz, bo twoje skrzydła jeszcze rosną” i skieruj jego uwagę na skakanie na coś miękkiego.', title_pt = 'Quero voar! 🕊️', body_pt = 'Salta do sofá a bater os braços e zanga-se consigo porque não voa? Ainda é cedo para lhe ensinar as leis da física. Diga "Não voas porque as tuas asas ainda estão a crescer" e desvie a atenção dele para saltar para um sítio macio.', title_sv = 'Jag vill flyga! 🕊️', body_sv = 'Hoppar barnet från soffan, flaxar med armarna och blir arg på dig för att hen inte flyger? Det är för tidigt att lära ut fysikens lagar. Säg ”Du flyger inte för att dina vingar fortfarande växer” och led uppmärksamheten till att hoppa ner på något mjukt.', title_vi = 'Con muốn bay! 🕊️', body_vi = 'Bé nhảy từ sofa xuống, vỗ tay như cánh và giận mẹ vì mình không bay được? Còn quá sớm để dạy bé các định luật vật lý. Hãy nói: "Con chưa bay được vì đôi cánh còn đang lớn" và hướng bé sang nhảy xuống chỗ mềm.', title_zh = '我想飞！🕊️', body_zh = '从沙发上跳下来拍着手臂，因为飞不起来而冲你发火？现在教宝宝物理定律还太早。说“你还飞不起来，因为你的翅膀还在长”，再把宝宝的注意力引到往软软的地方跳上。' WHERE id = 'db42b564-536c-485c-afff-dce099e8c451' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La revolución del «¡Es mío!» 🧸', body_es = '¿Abraza el mando de la tele y dice «¡Es mío!»? Está poniendo a prueba los límites de la propiedad. No lo llames egoísta: dile «Gracias por encontrármelo», lleva su atención a otro juego y recupéralo poco a poco.', title_fr = 'L''apocalypse du « C''est à moi ! » 🧸', body_fr = 'Il serre la télécommande dans ses bras en disant « C''est à moi ! » ? Il teste les limites de la propriété. Ne le traitez pas d''égoïste : dites « Merci de l''avoir trouvée pour moi », détournez son attention vers un autre jeu et récupérez-la doucement.', title_hi = '‘वह मेरा है!’ वाला हंगामा 🧸', body_hi = 'घर का रिमोट गले लगाकर कहता है, ‘यह मेरा है!’? वह मालिकाना हक की सीमाएँ परख रहा है। उसे स्वार्थी मत कहिए, ‘शुक्रिया, तुमने इसे मेरे लिए ढूँढ लिया’ कहकर उसका ध्यान दूसरे खेल पर लगाइए और धीरे से रिमोट वापस ले लीजिए।', title_id = 'Kiamat ''Itu punyaku!'' 🧸', body_id = 'Ia memeluk remote di rumah dan berkata ''Ini punyaku!''? Ia sedang menguji batas kepemilikan. Jangan sebut ia egois, katakan ''Terima kasih sudah menemukannya untuk Mama'' dan ambil kembali perlahan sambil mengalihkan perhatiannya ke permainan lain.', title_ja = '「それ、ぼくの！」大さわぎ 🧸', body_ja = '家のリモコンを抱えて「これ、ぼくの！」？自分のものの境界線をためしています。わがままと呼ばず、「見つけてくれてありがとう」と言って、ほかの遊びに気をそらしながら、そっと返してもらいましょう。', title_ko = '''내 거야!'' 대소동 🧸', body_ko = '집 리모컨을 끌어안고 ''이건 내 거야!'' 하나요? 소유의 경계를 시험하는 중이에요. 이기적이라고 하지 말고 ''찾아 줘서 고마워'' 하며 다른 놀이로 관심을 돌려 살며시 돌려받으세요.', title_nl = 'De ''Dat is van mij!''-storm 🧸', body_nl = 'Knuffelt hij de afstandsbediening en roept hij ''Die is van mij!''? Hij test de grenzen van bezit. Noem hem geen egoïst, zeg ''Dank je dat je hem voor me gevonden hebt'', leid zijn aandacht naar een ander spel en neem hem rustig terug.', title_pl = 'Awantura „To moje!” 🧸', body_pl = 'Ściska pilota i mówi „To moje!”? Sprawdza granice własności. Nie nazywaj go egoistą, powiedz: „Dziękuję, że mi go znalazłeś”, przekieruj jego uwagę na inną zabawę i powoli odzyskaj pilota.', title_pt = 'A tempestade do "É meu!" 🧸', body_pt = 'Abraça o comando da televisão e diz "Isto é meu!"? Está a testar os limites da posse. Não lhe chame egoísta: diga "Obrigada por o teres encontrado para mim", desvie a atenção dele para outro jogo e recupere-o devagarinho.', title_sv = 'Upproret ”Den är min!” 🧸', body_sv = 'Kramar barnet fjärrkontrollen och säger ”Den är min!”? Hen testar ägandets gränser. Kalla inte barnet egoistiskt, säg ”Tack för att du hittade den åt mig”, led uppmärksamheten till en annan lek och ta försiktigt tillbaka den.', title_vi = 'Cơn "tận thế" "Của con!" 🧸', body_vi = 'Bé ôm khư khư chiếc điều khiển TV và nói: "Cái này của con!"? Bé đang thử ranh giới sở hữu. Đừng gọi bé là ích kỷ, hãy nói "Cảm ơn con đã tìm giúp mẹ" và chuyển sự chú ý của bé sang trò chơi khác để nhẹ nhàng lấy lại.', title_zh = '“那是我的！”大风波 🧸', body_zh = '抱着家里的遥控器说“这是我的！”？宝宝在测试所有权的边界。别说宝宝自私，说一句“谢谢你帮我找到它”，把宝宝的注意力引到别的游戏上，再慢慢把遥控器拿回来。' WHERE id = '76fc525d-97d8-486f-adde-6d0bdc417bbe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando suena la campana, a dormir ⏱️', body_es = 'La hora de dormir se alarga y se alarga. Agua, baño, despedirse de la pared... Pon el temporizador del móvil. Establece la regla: «Cuando suena la campanita, todos apagamos las luces». Obedecer a una autoridad externa siempre les resulta más fácil.', title_fr = 'Quand la sonnerie retentit, on dort ⏱️', body_fr = 'L''heure du coucher s''éternise. L''eau, les toilettes, dire au revoir au mur... Réglez le minuteur de votre téléphone. Instaurez la règle « Quand la sonnerie retentit, tout le monde éteint la lumière ». Se plier à une autorité extérieure leur paraît toujours plus facile.', title_hi = 'घंटी बजी तो सो जाएँगे ⏱️', body_hi = 'सोने का समय खिंचता ही जाता है। पानी, टॉयलेट, दीवार को गुड नाइट... फ़ोन का टाइमर लगाइए। नियम बनाइए: ‘घंटी की आवाज़ आते ही सब लाइटें बंद करते हैं।’ बाहर की किसी ‘अथॉरिटी’ के आगे झुकना बच्चों को हमेशा आसान लगता है।', title_id = 'Saat bel berbunyi, kita tidur ⏱️', body_id = 'Waktu tidur terus molor. Minum, ke toilet, pamitan dengan dinding... Pasang timer di ponsel. Buat aturan ''Saat bel berbunyi, semua lampu dimatikan''. Tunduk pada otoritas dari luar selalu terasa lebih mudah bagi mereka.', title_ja = 'ベルが鳴ったらみんな寝る ⏱️', body_ja = '寝る時間がどんどん延びていく。お水、トイレ、壁におやすみ…。スマホのタイマーをセットして、「ベルが鳴ったらみんな明かりを消す」というルールを決めましょう。外からのルールには、いつも素直に従いやすいものです。', title_ko = '알람이 울리면 자는 거야 ⏱️', body_ko = '잠자리 시간이 끝없이 늘어지나요? 물, 화장실, 벽에게 인사하기... 휴대폰 타이머를 맞추고 ''알람이 울리면 모두 불을 끈다''는 규칙을 정하세요. 바깥의 권위에는 늘 더 쉽게 따르거든요.', title_nl = 'Als de bel gaat, gaan we slapen ⏱️', body_nl = 'Bedtijd rekt zich eindeloos uit. Water, wc, de muur welterusten zeggen... Zet een timer op je telefoon. Maak de regel: ''Als de bel gaat, doet iedereen het licht uit.'' Buigen voor een autoriteit van buitenaf valt kinderen altijd makkelijker.', title_pl = 'Gdy zadzwoni dzwonek, idziemy spać ⏱️', body_pl = 'Pora snu ciągnie się w nieskończoność. Woda, toaleta, żegnanie się ze ścianą... Nastaw minutnik w telefonie. Wprowadź zasadę: „Gdy zadzwoni dzwonek, wszyscy gaszą światło”. Dzieciom zawsze łatwiej podporządkować się zewnętrznemu autorytetowi.', title_pt = 'Quando toca a campainha, vamos dormir ⏱️', body_pt = 'A hora de dormir estica-se sem fim. Água, casa de banho, despedir-se da parede... Programe o temporizador do telemóvel. Crie a regra "quando a campainha toca, todos apagam as luzes". Obedecer a uma autoridade externa é-lhes sempre mais fácil.', title_sv = 'När klockan ringer sover vi ⏱️', body_sv = 'Läggdags drar ut mer och mer. Vatten, toaletten, säga god natt till väggen... Ställ in timern på telefonen. Inför regeln ”när klockan ringer släcker alla”. Att böja sig för en yttre auktoritet känns alltid lättare för barn.', title_vi = 'Chuông reo là đi ngủ ⏱️', body_vi = 'Giờ đi ngủ cứ kéo dài mãi. Uống nước, đi vệ sinh, chúc ngủ ngon bức tường... Hãy đặt hẹn giờ trên điện thoại. Đặt quy tắc "Nghe tiếng chuông là cả nhà tắt đèn". Trẻ luôn thấy dễ nghe theo một "uy quyền bên ngoài" hơn.', title_zh = '铃声一响就睡觉 ⏱️', body_zh = '睡前时间越拖越长。喝水、上厕所、和墙壁说再见……设好手机计时器。定一个规则：“铃声一响，大家都关灯。”服从一个外部“权威”，对孩子来说总是更容易。' WHERE id = 'ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No le rindas cuentas a nadie 🛑', body_es = '¿Hoy se te ha agotado la paciencia y has levantado la voz? No te castigues. Escribe en el Diario de ánimo: «Soy una buena madre, solo que hoy estoy muy cansada». Sé compasiva contigo: nadie espera que seas perfecta.', title_fr = 'Vous n''avez de comptes à rendre à personne 🛑', body_fr = 'Aujourd''hui, votre patience a lâché et vous avez haussé le ton ? Ne vous punissez pas. Écrivez dans le Journal d''humeur : « Je suis une bonne maman, j''étais juste très fatiguée aujourd''hui. » Soyez bienveillante envers vous-même, personne n''attend de vous la perfection.', title_hi = 'किसी को हिसाब मत दीजिए 🛑', body_hi = 'आज आपका सब्र छोटा पड़ गया और आवाज़ ऊँची हो गई? खुद को सज़ा मत दीजिए। मूड डायरी में लिखिए, ‘मैं अच्छी माँ हूँ, बस आज बहुत थक गई।’ खुद पर दया कीजिए, कोई आपसे बेदाग होने की उम्मीद नहीं करता।', title_id = 'Tak perlu melapor kepada siapa pun 🛑', body_id = 'Hari ini kesabaran Anda menipis dan suara Anda meninggi? Jangan menghukum diri. Tulis di Buku Harian Suasana Hati: ''Aku ibu yang baik, hanya saja hari ini aku sangat lelah.'' Berbelas kasihlah pada diri sendiri, tidak ada yang mengharapkan Anda sempurna.', title_ja = '誰にも報告しなくていい 🛑', body_ja = '今日はがまんの限界で、声を荒らげてしまった？自分を責めないで。「気分日記」に「わたしはいいママ。今日はただ、とても疲れただけ」と書きましょう。自分にやさしく。誰もあなたに完璧を求めていません。', title_ko = '누구에게도 해명하지 않아도 돼요 🛑', body_ko = '오늘 인내심이 바닥나서 목소리가 높아졌나요? 자신을 벌주지 마세요. 기분 일기에 ''나는 좋은 엄마야, 오늘은 그냥 너무 지쳤을 뿐이야''라고 쓰세요. 스스로에게 너그러워지세요. 아무도 엄마에게 완벽을 바라지 않아요.', title_nl = 'Je bent niemand verantwoording schuldig 🛑', body_nl = 'Raakte je geduld vandaag op en verhief je je stem? Straf jezelf niet. Schrijf in je Stemmingsdagboek: ''Ik ben een goede mama, ik was vandaag gewoon heel moe.'' Wees mild voor jezelf, niemand verwacht perfectie van je.', title_pl = 'Nie tłumacz się nikomu 🛑', body_pl = 'Dziś zabrakło ci cierpliwości i podniosłaś głos? Nie karz się. Napisz w Dzienniku nastroju: „Jestem dobrą mamą, po prostu dziś bardzo się zmęczyłam”. Bądź dla siebie wyrozumiała, nikt nie oczekuje od ciebie perfekcji.', title_pt = 'Não deve explicações a ninguém 🛑', body_pt = 'Hoje a paciência encurtou e levantou a voz? Não se castigue. Escreva no Diário de Humor: "Sou uma boa mãe, só que hoje estava muito cansada". Seja compreensiva consigo, ninguém espera de si a perfeição.', title_sv = 'Du behöver inte redovisa för någon 🛑', body_sv = 'Tröt tålamodet i dag och du höjde rösten? Straffa inte dig själv. Skriv i Humördagboken: ”Jag är en bra mamma, jag var bara väldigt trött i dag.” Var snäll mot dig själv, ingen förväntar sig att du ska vara felfri.', title_vi = 'Không cần báo cáo với ai 🛑', body_vi = 'Hôm nay mẹ cạn kiên nhẫn và đã lớn tiếng? Đừng tự trừng phạt mình. Hãy viết vào Nhật ký tâm trạng: "Mình là một người mẹ tốt, chỉ là hôm nay mình quá mệt." Hãy bao dung với bản thân, không ai đòi hỏi mẹ phải hoàn hảo.', title_zh = '不必向任何人交代 🛑', body_zh = '今天耐心用完了，你提高了嗓门？别惩罚自己。在心情日记里写下：“我是个好妈妈，只是今天太累了。”对自己温柔一点，没有人要求你完美无缺。' WHERE id = 'f24ccc35-5845-4b4b-803c-db7a68218026' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La barrita de energía de mamá 🥗', body_es = 'Has montado menús distintos para darle de comer, ¿y tú qué has comido? Prepárate esa ensalada fácil de 5 minutos para mamás de Recetas saludables.', title_fr = 'La barre énergétique de maman 🥗', body_fr = 'Vous avez imaginé différents menus pour le nourrir, mais vous, qu''avez-vous mangé ? Préparez la salade facile en 5 minutes pour les mamans des Recettes saines.', title_hi = 'माँ की एनर्जी बार 🥗', body_hi = 'उसे खिलाने के लिए तरह-तरह के मेन्यू बनाए, पर आपने क्या खाया? सेहतमंद रेसिपी में माँओं के लिए वाला 5 मिनट का आसान सलाद बनाइए।', title_id = 'Bar energi Ibu 🥗', body_id = 'Anda menyusun berbagai menu untuk memberinya makan, lalu Anda sendiri makan apa? Siapkan salad 5 menit yang mudah untuk ibu dari Resep Sehat.', title_ja = 'ママのエナジーバー 🥗', body_ja = 'この子に食べさせるためにいろいろな献立を考えたけれど、あなたは何を食べた？「ヘルシーレシピ」にあるママ向けの簡単5分サラダをつくりましょう。', title_ko = '엄마의 에너지 충전 🥗', body_ko = '아이를 먹이려고 여러 메뉴를 고민했는데 정작 엄마는 뭘 먹었나요? 건강한 레시피에 있는 엄마를 위한 간단한 5분 샐러드를 만들어 보세요.', title_nl = 'Mama''s energiereep 🥗', body_nl = 'Je hebt allerlei menu''s bedacht om hem te laten eten, maar wat heb jij gegeten? Maak die makkelijke salade van 5 minuten voor mama''s uit Gezonde recepten.', title_pl = 'Baton energetyczny mamy 🥗', body_pl = 'Wymyślasz różne menu, żeby go nakarmić, a co ty zjadłaś? Przygotuj ze Zdrowych przepisów tę łatwą 5-minutową sałatkę dla mam.', title_pt = 'A barra de energia da mãe 🥗', body_pt = 'Inventou menus diferentes para ele comer, mas e a mãe, o que comeu? Prepare aquela salada fácil de 5 minutos para mães das Receitas Saudáveis.', title_sv = 'Mammas energibar 🥗', body_sv = 'Du gjorde olika menyer för att få barnet att äta, men vad åt du själv? Gör den enkla 5-minuterssalladen för mammor i Hälsosamma recept.', title_vi = 'Thanh năng lượng của mẹ 🥗', body_vi = 'Mẹ đã lên đủ thực đơn để bé ăn, còn mẹ đã ăn gì chưa? Hãy làm món salad 5 phút dễ dàng dành cho mẹ trong Công thức lành mạnh.', title_zh = '妈妈的能量棒 🥗', body_zh = '为了喂宝宝想了好几种菜单，那你自己吃了什么？在健康食谱里做一份给妈妈的5分钟简单沙拉吧。' WHERE id = '3fdd99bb-9e81-4b54-a9b9-28997c15bd09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente en silencio ☕', body_es = 'Por fin se ha dormido. Mira los juguetes tirados en medio de la habitación y respira hondo. ¡No los recojas ahora! Sírvete un té caliente, siéntate en el sofá y disfruta de la tranquilidad que te regala este silencio.', title_fr = 'Un thé chaud dans le silence ☕', body_fr = 'L''enfant dort enfin. Regardez les jouets éparpillés au milieu de la pièce et respirez profondément. Ne les rangez pas maintenant ! Servez-vous un thé chaud, asseyez-vous sur le canapé et savourez simplement la paix que vous offre ce silence.', title_hi = 'खामोशी में गरम चाय ☕', body_hi = 'बच्चा आखिरकार सो गया। कमरे के बीच बिखरे खिलौनों को देखकर गहरी साँस लीजिए। अभी उन्हें मत समेटिए! अपने लिए गरम चाय डालिए, सोफ़े पर बैठिए और बस इस खामोशी से मिलने वाले सुकून का मज़ा लीजिए।', title_id = 'Teh hangat dalam keheningan ☕', body_id = 'Akhirnya anak tidur. Lihat mainan yang berserakan di tengah kamar dan tarik napas dalam. Jangan bereskan sekarang! Tuang teh hangat untuk diri sendiri, duduk di sofa, dan nikmati saja ketenangan yang diberikan keheningan ini.', title_ja = '静けさの中の温かいお茶 ☕', body_ja = 'やっと子どもが寝ました。部屋のまん中に散らかったおもちゃを見て、深呼吸。今は片づけないで！温かいお茶を入れてソファに座り、この静けさがくれる安らぎをただ味わいましょう。', title_ko = '고요 속 따뜻한 차 한 잔 ☕', body_ko = '드디어 아이가 잠들었어요. 방 한가운데 흩어진 장난감을 보며 깊게 숨 쉬세요. 지금은 치우지 마세요! 따뜻한 차 한 잔을 따라 소파에 앉아, 이 고요가 주는 편안함을 그저 즐기세요.', title_nl = 'Warme thee in stilte ☕', body_nl = 'Eindelijk slaapt je kind. Kijk naar het rondslingerende speelgoed midden in de kamer en haal diep adem. Ruim het nu niet op! Schenk jezelf een warme thee in, ga op de bank zitten en geniet gewoon van de rust die deze stilte je geeft.', title_pl = 'Gorąca herbata w ciszy ☕', body_pl = 'Dziecko wreszcie zasnęło. Spójrz na rozrzucone na środku pokoju zabawki i weź głęboki oddech. Nie sprzątaj ich teraz! Nalej sobie gorącej herbaty, usiądź na kanapie i po prostu rozkoszuj się spokojem, jaki daje ci ta cisza.', title_pt = 'Chá quente em silêncio ☕', body_pt = 'A criança finalmente adormeceu. Olhe para os brinquedos espalhados no meio do quarto e respire fundo. Não os arrume agora! Sirva-se de um chá quente, sente-se no sofá e saboreie apenas o descanso que este silêncio lhe dá.', title_sv = 'Varmt te i stillheten ☕', body_sv = 'Äntligen har barnet somnat. Titta på de utspridda leksakerna mitt i rummet och andas djupt. Plocka inte upp dem nu! Häll upp ett varmt te, sätt dig i soffan och njut bara av vilan som tystnaden ger dig.', title_vi = 'Tách trà nóng trong yên lặng ☕', body_vi = 'Cuối cùng bé cũng ngủ. Hãy nhìn đống đồ chơi bừa bộn giữa phòng và hít thở thật sâu. Đừng dọn bây giờ! Rót cho mình một tách trà nóng, ngồi xuống sofa và chỉ tận hưởng sự bình yên mà khoảng lặng này mang lại.', title_zh = '安静中的一杯热茶 ☕', body_zh = '宝宝终于睡着了。看着房间中间散落一地的玩具，深呼吸。现在别收拾！给自己倒一杯热茶，坐到沙发上，只是享受这份安静带来的平和。' WHERE id = '8e09c446-7bb4-4213-903b-ca0d9d539235' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Largas charlas con objetos 🗣️', body_es = '¿En el parque le habla muy en serio a una piedra, o en casa a una silla? A través del juego está asimilando las reglas y el mundo.', title_fr = 'Longues conversations avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise ? Par le jeu, il assimile les règles et le monde.', title_hi = 'बेजान चीज़ों से लंबी बातें 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ बातें करता है? वह खेल के ज़रिए नियम और दुनिया समझ रहा है।', title_id = 'Obrolan panjang dengan benda mati 🗣️', body_id = 'Ia berbicara dengan sangat serius kepada sebuah batu di taman atau kursi di rumah? Lewat permainan, ia sedang memahami aturan dan dunia.', title_ja = 'ものとの長いおしゃべり 🗣️', body_ja = '公園の石や家のいすに、とても真剣に何かを話しかけている？遊びを通して、ルールや世界を身につけているんです。', title_ko = '물건들과 나누는 긴 대화 🗣️', body_ko = '공원의 돌이나 집 안 의자에게 아주 진지하게 무언가를 말하나요? 놀이를 통해 규칙과 세상을 익히는 중이에요.', title_nl = 'Lange gesprekken met levenloze dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of thuis tegen een stoel? Via spel leert hij de regels en de wereld kennen.', title_pl = 'Długie rozmowy z przedmiotami 🗣️', body_pl = 'W parku z całą powagą opowiada coś kamieniowi albo w domu krzesłu? Przez zabawę oswaja zasady i świat.', title_pt = 'Longas conversas com objetos 🗣️', body_pt = 'No parque fala muito a sério com uma pedra ou, em casa, com uma cadeira? Através do jogo, está a aprender as regras e o mundo.', title_sv = 'Långa samtal med livlösa ting 🗣️', body_sv = 'Pratar barnet helt allvarligt med en sten i parken eller en stol hemma? Genom leken tar barnet till sig reglerna och världen.', title_vi = 'Những cuộc trò chuyện dài với đồ vật 🗣️', body_vi = 'Bé nói chuyện hết sức nghiêm túc với một hòn đá ở công viên hay chiếc ghế ở nhà? Qua trò chơi, bé đang học về các quy tắc và thế giới.', title_zh = '和没有生命的东西长谈 🗣️', body_zh = '在公园里对着一块石头，或在家对着一把椅子，一本正经地说着什么？宝宝正在通过游戏理解规则和这个世界。' WHERE id = 'b85f6433-c512-4f2e-a5d4-b9023f0eb544' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Autocrítica en sus dibujos 🖍️', body_es = '¿No le ha gustado la línea que ha dibujado, dice «Ha quedado mal» y rompe el papel? ¡Están naciendo la autocrítica y el sentido de la perfección! Convierte su frustración en un descubrimiento que le dé apoyo con un «La próxima vez probamos otro color».', title_fr = 'L''autocritique dans son dessin 🖍️', body_fr = 'Il n''aime pas le trait qu''il a tracé et déchire la feuille en disant « C''est raté » ? L''autocritique et le sens de la perfection apparaissent ! Dites « Viens, la prochaine fois on essaie une autre couleur » et transformez sa déception en découverte encourageante.', title_hi = 'अपनी ड्रॉइंग में खुद की आलोचना 🖍️', body_hi = 'अपनी बनाई लकीर पसंद नहीं आई, तो ‘यह खराब बनी’ कहकर कागज़ फाड़कर फेंक देता है? खुद की आलोचना और परफ़ेक्शन की भावना जाग रही है! ‘चलो, अगली बार कोई और रंग आज़माते हैं’ कहकर उसकी निराशा को हौसला देने वाली खोज में बदल दीजिए।', title_id = 'Mengkritik diri lewat gambar 🖍️', body_id = 'Ia tidak suka garis yang ia gambar, berkata ''Ini jelek'', lalu merobek dan membuang kertasnya? Kemampuan mengkritik diri dan rasa kesempurnaan mulai muncul! Ubah kekecewaannya menjadi penemuan yang menyemangati dengan berkata ''Yuk, lain kali kita coba warna lain''.', title_ja = '自分の絵にダメ出し 🖍️', body_ja = 'かいた線が気に入らなくて「これ、だめ」と紙をやぶって捨てる？自分を振り返る力と、完璧を求める気持ちが芽生えています！「次はちがう色をためしてみよう」と言って、がっかりを前向きな発見に変えましょう。', title_ko = '그림 속 자기비판 🖍️', body_ko = '자기가 그은 선이 마음에 안 들어 ''이거 망했어'' 하며 종이를 찢어 버리나요? 자기비판과 완벽주의가 생겨나는 중이에요! ''다음엔 다른 색으로 해 보자'' 하며 실망을 응원 가득한 탐험으로 바꿔 주세요.', title_nl = 'Kritiek op zijn eigen tekening 🖍️', body_nl = 'Vindt hij een lijn die hij tekende niet mooi, zegt hij ''Dit is lelijk'' en verscheurt hij het papier? Zelfkritiek en perfectionisme ontstaan! Maak van zijn teleurstelling een ondersteunende ontdekking: ''Kom, de volgende keer proberen we een andere kleur.''', title_pl = 'Samokrytyka w rysunku 🖍️', body_pl = 'Nie podoba mu się narysowana kreska, mówi „Wyszło brzydko” i drze kartkę? Rodzi się samokrytyka i poczucie perfekcji! Powiedz: „Następnym razem spróbujmy innego koloru” i zamień jego rozczarowanie we wspierające odkrycie.', title_pt = 'A autocrítica no desenho 🖍️', body_pt = 'Não gostou da linha que desenhou, disse "Ficou mal" e rasgou o papel? Estão a nascer a autocrítica e o sentido de perfeição! Transforme a desilusão dele numa descoberta com apoio: "Da próxima vez vamos experimentar outra cor".', title_sv = 'Självkritik i teckningen 🖍️', body_sv = 'Gillade barnet inte strecket hen ritade, sa ”Det blev dåligt” och rev sönder pappret? Självkritik och känslan för perfektion växer fram! Säg ”Nästa gång testar vi en annan färg” och gör besvikelsen till en upptäckt med stöd.', title_vi = 'Tự chê bức tranh của mình 🖍️', body_vi = 'Không thích nét vẽ của mình, bé nói "Xấu quá" rồi xé giấy vứt đi? Khả năng tự đánh giá và cảm giác cầu toàn đang hình thành! Hãy biến nỗi thất vọng thành một khám phá đầy khích lệ: "Lần sau mình thử màu khác nhé."', title_zh = '在画里批评自己 🖍️', body_zh = '不喜欢自己画的线，说“画得不好”，就把纸撕了扔掉？自我批评和追求完美的意识正在出现！说一句“下次我们试试别的颜色吧”，把宝宝的失望变成一次被支持的探索。' WHERE id = '294ce10a-4fac-4bfb-8007-e2e3fea714ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Consuelo secreto en la Comunidad 💬', body_es = '¿Estás tan cansada que no te apetece ni desahogarte con nadie? Entra en la Comunidad Anacan y limítate a leer. Ver cómo otras mamás lidian con las mismas crisis absurdas será tu consuelo silencioso más poderoso.', title_fr = 'Un réconfort discret dans la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez même pas envie de parler à quelqu''un ? Rejoignez la Communauté Anacan et contentez-vous de lire. Voir comment les autres mamans affrontent les mêmes crises absurdes sera le plus puissant des réconforts silencieux.', title_hi = 'कम्युनिटी में चुपचाप मिलने वाली तसल्ली 💬', body_hi = 'बहुत थक गई हैं और किसी से बात करने का भी मन नहीं? Anacan कम्युनिटी में आइए और बस पढ़िए। दूसरी माँएँ उन्हीं बेतुके संकटों से कैसे जूझती हैं, यह देखना आपके लिए सबसे बड़ी खामोश तसल्ली होगी।', title_id = 'Penghiburan diam-diam di komunitas 💬', body_id = 'Anda sangat lelah dan bahkan tidak ingin curhat dengan siapa pun? Masuk ke Komunitas Anacan dan cukup jadi pembaca. Melihat ibu-ibu lain berjuang menghadapi krisis absurd yang sama akan menjadi penghiburan diam-diam yang paling kuat bagi Anda.', title_ja = 'コミュニティでこっそりなぐさめ 💬', body_ja = '疲れきって、誰かと話す気にもなれない？Anacanコミュニティに入って、読むだけにしましょう。ほかのママたちが同じおかしなかんしゃくとどう向き合っているかを見るのが、いちばん力強い静かななぐさめになります。', title_ko = '커뮤니티 속 조용한 위로 💬', body_ko = '너무 지쳐서 누구와 이야기하기조차 싫은가요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들이 똑같이 엉뚱한 위기와 씨름하는 걸 보는 게 가장 강력한 조용한 위로가 될 거예요.', title_nl = 'Stille troost in de Community 💬', body_nl = 'Ben je zo moe dat je zelfs met niemand wilt praten? Ga naar de Anacan Community en lees alleen mee. Zien hoe andere mama''s met precies dezelfde absurde crisissen worstelen, is de sterkste stille troost.', title_pl = 'Ciche pocieszenie w Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie masz ochoty nawet z nikim rozmawiać? Wejdź do Społeczności Anacan i tylko czytaj. Widok tego, jak inne mamy radzą sobie z tymi samymi absurdalnymi kryzysami, będzie dla ciebie najsilniejszym cichym pocieszeniem.', title_pt = 'Um consolo secreto na comunidade 💬', body_pt = 'Está tão cansada que nem lhe apetece desabafar com ninguém? Entre na Comunidade Anacan e seja apenas leitora. Ver como as outras mães lidam com as mesmas crises absurdas será o consolo silencioso mais forte.', title_sv = 'Hemlig tröst i Community 💬', body_sv = 'Är du så trött att du inte ens vill prata av dig med någon? Gå in i Anacan Community och bara läs. Att se hur andra mammor hanterar samma absurda kriser blir den starkaste tysta trösten.', title_vi = 'Niềm an ủi thầm lặng trong cộng đồng 💬', body_vi = 'Mẹ mệt đến mức không muốn tâm sự với ai? Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác đối phó với những cơn "khủng hoảng" phi lý y hệt, đó sẽ là niềm an ủi thầm lặng mạnh mẽ nhất cho mẹ.', title_zh = '在社区里悄悄获得安慰 💬', body_zh = '累到连和人说话都不想？进入Anacan社区，只当一名读者。看到其他妈妈怎样应对同样荒诞的危机，就是给你最有力的无声安慰。' WHERE id = '76df67fe-b947-400d-8825-c8fd1637478f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿El baño es una excusa y en realidad ha montado un océano en la bañera para jugar con las olas? Deja que juegue. El ruido del agua y las salpicaduras se llevarán toda esa energía cabezota que no se acaba. Por la noche se meterá en la cama sin oponer resistencia.', body_fr = 'Le bain n''est qu''un prétexte : en réalité, il crée un océan et joue avec les vagues ? Laissez-le jouer. Le bruit de l''eau et les éclaboussures emporteront toute cette énergie têtue et inépuisable. Le soir, il ira se coucher sans aucune résistance.', body_hi = 'नहाना तो बहाना है, असल में टब में समंदर बनाकर लहरों से खेल रहा है? खेलने दीजिए। पानी का शोर और छींटे उसके अंदर की वह खत्म न होने वाली ज़िद्दी ऊर्जा बहा ले जाएँगे। शाम को वह बिना किसी विरोध के बिस्तर पर लेट जाएगा।', body_id = 'Mandi hanya alasan, sebenarnya ia menciptakan lautan di bak dan bermain ombak? Biarkan saja. Suara dan cipratan air akan membasuh energi keras kepala yang tak ada habisnya itu. Malam nanti ia akan berbaring di tempat tidur tanpa perlawanan.', body_ja = 'お風呂は口実で、本当は浴槽に海をつくって波遊び？遊ばせてあげましょう。水の音としぶきが、終わりのないがんこなエネルギーを洗い流してくれます。夜はまったく抵抗せずにベッドに入りますよ。', body_ko = '목욕은 핑계고 사실은 욕조에 바다를 만들어 파도 놀이를 하나요? 놀게 두세요. 물소리와 물장구가 속에 쌓인 끝없는 고집 에너지를 씻어 줄 거예요. 저녁엔 아무 저항 없이 침대에 누울 거예요.', body_nl = 'Is in bad gaan maar een excuus en maakt hij eigenlijk een oceaan om met de golven te spelen? Laat hem lekker spelen. Het geluid en gespetter van het water spoelt al die eindeloze koppige energie weg. ''s Avonds gaat hij zonder enig verzet in bed liggen.', body_pl = 'Kąpiel to tylko pretekst, a w wannie tak naprawdę tworzy ocean i bawi się falami? Niech się bawi. Szum i pluskanie wody zmyją z niego tę niekończącą się upartą energię. Wieczorem położy się do łóżka bez żadnego oporu.', body_pt = 'O banho é só uma desculpa e, na verdade, ele cria um oceano na banheira e brinca com as ondas? Deixe-o brincar. O barulho e os salpicos da água vão levar consigo toda aquela energia teimosa e sem fim. À noite vai deitar-se sem resistência nenhuma.', body_sv = 'Är badet bara en förevändning, och barnet har egentligen skapat ett hav i badkaret och leker med vågorna? Låt hen leka. Vattnets ljud och plask sköljer bort den outtröttliga, envisa energin. På kvällen lägger sig barnet utan minsta motstånd.', body_vi = 'Tắm chỉ là cái cớ, thật ra bé đang tạo cả đại dương trong bồn và chơi với sóng? Cứ để bé chơi. Tiếng nước và những cú té nước sẽ cuốn trôi hết năng lượng bướng bỉnh không ngừng bên trong bé. Tối đến, bé sẽ lên giường mà không phản đối chút nào.', body_zh = '洗澡只是借口，其实是在浴缸里造了一片海洋，和浪花玩耍？就让宝宝玩吧。哗哗的水声和溅起的水花，会把宝宝身体里那股停不下来的倔强能量冲走。晚上就会毫无抵抗地躺上床。' WHERE id = '882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filosofía repentina a primera hora 🤔', body_es = '¿De repente te ha hecho una pregunta científica como «¿Por qué no se ve el viento?»? ¡Sin sudores! Abre Anacan AI, consigue la respuesta más tierna y de cuento, avalada por pediatras y psicólogos, que pueda entender a esta edad, y léesela. ¡Eres la mamá que siempre lo sabe todo!', title_fr = 'Philosophie surprise dès le matin 🤔', body_fr = 'Il a soudain posé une question scientifique : « Pourquoi on ne voit pas le vent ? » ? Pas de panique ! Ouvrez Anacan AI, obtenez la réponse féerique la plus douce, validée par des pédiatres et des psychologues et compréhensible à son âge, et lisez-la-lui. Vous êtes toujours la maman qui sait tout !', title_hi = 'सुबह-सुबह अचानक फ़लसफ़ा 🤔', body_hi = 'अचानक वैज्ञानिक सवाल पूछ लिया, ‘हवा दिखती क्यों नहीं?’ पसीना मत छोड़िए! Anacan AI खोलिए, इस उम्र के समझ में आने वाला सबसे प्यारा, बाल रोग विशेषज्ञ और मनोवैज्ञानिक द्वारा पुष्ट, परी-कथा जैसा जवाब लीजिए और उसे सुनाइए। आप हमेशा सब जानने वाली माँ हैं!', title_id = 'Filsafat mendadak pagi-pagi 🤔', body_id = 'Tiba-tiba ia bertanya pertanyaan ilmiah ''Kenapa angin tidak kelihatan?'' Jangan panik! Buka Anacan AI, dapatkan jawaban seperti dongeng yang paling manis, bisa dipahami usia ini, dan disetujui dokter anak serta psikolog, lalu bacakan untuknya. Anda selalu ibu yang tahu segalanya!', title_ja = '朝から突然の哲学 🤔', body_ja = '「風はなんで見えないの？」と急に科学的な質問？あせらないで！Anacan AIを開いて、この年齢でも理解できる、小児科医と心理士が確認したいちばんかわいいお話風の答えを聞いて読んであげましょう。あなたはいつでも何でも知っているママです！', title_ko = '아침부터 갑작스러운 철학 🤔', body_ko = '''바람은 왜 안 보여?'' 하고 갑자기 과학 질문을 했나요? 진땀 흘리지 마세요! Anacan AI를 열어 이 나이가 이해할 수 있는, 소아과 의사와 심리학자가 확인한 가장 귀엽고 동화 같은 답을 받아 읽어 주세요. 엄마는 언제나 모든 걸 아는 엄마예요!', title_nl = 'Plotselinge filosofie in de ochtend 🤔', body_nl = 'Stelde hij ineens een wetenschappelijke vraag als ''Waarom kun je de wind niet zien?'' Geen paniek! Open Anacan AI, vraag het liefste, door kinderartsen en psychologen bevestigde sprookjesachtige antwoord dat past bij deze leeftijd, en lees het hem voor. Jij bent altijd de mama die alles weet!', title_pl = 'Poranna nagła filozofia 🤔', body_pl = 'Nagle zadał naukowe pytanie: „Czemu wiatru nie widać?”. Bez nerwów! Otwórz Anacan AI, uzyskaj najsłodszą, bajkową odpowiedź potwierdzoną przez pediatrów i psychologów, zrozumiałą w tym wieku, i mu ją przeczytaj. Zawsze jesteś mamą, która wie wszystko!', title_pt = 'Filosofia logo pela manhã 🤔', body_pt = 'Fez de repente uma pergunta científica: "Porque é que não se vê o vento?"? Não se aflija! Abra o Anacan AI, obtenha a resposta mais doce e encantada que esta idade consegue perceber, validada por pediatras e psicólogos, e leia-lha. É sempre a mãe que sabe tudo!', title_sv = 'Plötslig filosofi på morgonen 🤔', body_sv = 'Ställde barnet plötsligt den vetenskapliga frågan ”Varför syns inte vinden?” Svettas inte! Öppna Anacan AI, få det sötaste sagolika svaret som den här åldern kan förstå, godkänt av barnläkare och psykologer, och läs det för barnet. Du är alltid mamman som vet allt!', title_vi = 'Triết lý bất ngờ từ sáng sớm 🤔', body_vi = 'Bé bất ngờ hỏi một câu khoa học: "Sao không nhìn thấy gió?" Đừng toát mồ hôi! Hãy mở Anacan AI, lấy câu trả lời ngọt ngào, đậm chất cổ tích, được bác sĩ nhi khoa và chuyên gia tâm lý xác nhận, phù hợp với lứa tuổi này và đọc cho bé nghe. Mẹ luôn là người mẹ biết tuốt!', title_zh = '一大早的哲学突袭 🤔', body_zh = '突然问了个科学问题：“风为什么看不见？”别慌！打开Anacan AI，找一个这个年龄能理解、儿科医生和心理学家认可的、最可爱的童话式回答，读给宝宝听。你永远是无所不知的妈妈！' WHERE id = '3e4c8054-2b97-4968-a10f-267dccb5b8c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo tumbarte tranquila 🛋️', body_es = '¿Está haciendo un puzle solo y de repente hay silencio en casa? ¡Ay, cariño, no gastes ese momento en barrer! Túmbate en el sofá. Tu batería también tiene que cargarse para aguantar este ritmo hasta la noche. Descansa sí o sí.', title_fr = 'Simplement s''allonger au calme 🛋️', body_fr = 'Il fait un puzzle tout seul et un silence soudain règne dans la maison ? Ma chérie, ne gaspillez pas ce moment à balayer ! Allongez-vous sur le canapé. Votre batterie aussi doit se recharger pour tenir ce rythme jusqu''au soir. Reposez-vous absolument.', title_hi = 'बस चुपचाप लेट जाना 🛋️', body_hi = 'वह अपने आप पज़ल जोड़ रहा है और घर में अचानक सन्नाटा है? मेरी जान, वह पल झाड़ू लगाने में मत गँवाइए! सोफ़े पर लेट जाइए। आपकी बैटरी भी चार्ज होनी चाहिए, ताकि शाम तक यह रफ़्तार झेल सकें। आराम ज़रूर कीजिए।', title_id = 'Cukup berbaring dengan tenang 🛋️', body_id = 'Ia menyusun puzzle sendiri dan rumah tiba-tiba hening? Aduh sayang, jangan habiskan momen itu untuk menyapu rumah! Berbaringlah di sofa. Baterai Anda juga harus terisi agar sanggup mengikuti tempo ini sampai sore. Beristirahatlah.', title_ja = 'ただ静かに横になる 🛋️', body_ja = 'ひとりでパズルをしていて、家が急に静かになった？その時間を掃除に使わないで！ソファに横になりましょう。夜までこのペースについていくには、あなたのバッテリーも充電が必要です。しっかり休んでね。', title_ko = '그냥 조용히 누워 있기 🛋️', body_ko = '혼자 퍼즐을 맞추느라 집이 갑자기 조용해졌나요? 그 순간을 청소에 쓰지 마세요! 소파에 누우세요. 저녁까지 이 속도를 버티려면 엄마도 배터리를 채워야 해요. 꼭 쉬세요.', title_nl = 'Gewoon rustig liggen 🛋️', body_nl = 'Maakt hij in zijn eentje een puzzel en is het ineens stil in huis? Besteed dat moment alsjeblieft niet aan stofzuigen! Ga op de bank liggen. Ook jouw batterij moet opladen, zodat je dit tempo tot de avond volhoudt. Rust echt uit.', title_pl = 'Po prostu spokojnie się położyć 🛋️', body_pl = 'Sam układa puzzle, a w domu nagle zapadła cisza? Błagam, nie wydawaj tej chwili na zamiatanie! Połóż się na kanapie. Twoja bateria też musi się naładować, żebyś wytrzymała to tempo do wieczora. Koniecznie odpocznij.', title_pt = 'Apenas deitar-se em sossego 🛋️', body_pt = 'Está a fazer um puzzle sozinho e de repente há silêncio em casa? Por favor, não gaste esse momento a varrer a casa! Deite-se no sofá. A sua bateria também precisa de carregar para aguentar este ritmo até à noite. Descanse sem falta.', title_sv = 'Bara ligga ner i lugn och ro 🛋️', body_sv = 'Lägger barnet pussel själv och det är plötsligt tyst hemma? Älskade du, lägg inte den stunden på att dammsuga! Lägg dig i soffan. Ditt batteri måste också laddas så att du orkar med tempot till kvällen. Vila, absolut.', title_vi = 'Chỉ cần lặng lẽ nằm xuống 🛋️', body_vi = 'Bé tự ghép hình và nhà bỗng yên ắng? Mẹ ơi, đừng dành khoảnh khắc ấy để quét nhà! Hãy nằm dài trên sofa. Pin của mẹ cũng cần được sạc đầy để theo kịp nhịp độ này đến tối. Nhất định phải nghỉ ngơi nhé.', title_zh = '只是静静地躺一躺 🛋️', body_zh = '宝宝自己在拼拼图，家里突然安静了？亲爱的，别把这一刻花在扫地上！去沙发上躺一躺。你的电池也得充满，才能撑住这个节奏到晚上。一定要休息。' WHERE id = 'b7b7faa9-f807-43f1-bf54-6d7f963c5e32' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Al lavarle el pantalón ha salido una hoja seca o una piedra del bolsillo? No es glotonería, es exploración infantil. Tírala a la basura con cara seria, pero sonríe por dentro a ese pequeño proveedor: está descubriendo el mundo.', body_fr = 'En lavant son pantalon, vous avez trouvé dans sa poche une feuille séchée ou un caillou ? Ce n''est pas de la gourmandise, c''est une exploration d''enfant. Jetez-les avec un air sérieux, mais souriez intérieurement à ce petit ravitailleur : il découvre le monde.', body_hi = 'पैंट धोते समय जेब से सूखा पत्ता या पत्थर निकला? यह लालच नहीं, बच्चों वाली खोजबीन है। गंभीर चेहरे से उसे कूड़े में डालिए, पर अंदर ही अंदर इस भंडार जमा करने वाले बच्चे पर मुस्कुराइए, वह दुनिया खोज रहा है।', body_id = 'Saat mencuci celananya, dari sakunya keluar daun kering atau batu? Ini bukan rakus, ini penjelajahan ala anak-anak. Buang ke tempat sampah dengan wajah serius, tapi dalam hati tersenyumlah pada si pemasok kecil ini, ia sedang menjelajahi dunia.', body_ja = 'ズボンを洗おうとしたら、ポケットから乾いた葉っぱや石が出てきた？食いしんぼうではなく、子どもなりの探検です。まじめな顔で捨てながらも、心の中ではこの調達係の子にほほえんで。世界を発見しているんです。', body_ko = '바지를 빨려다 주머니에서 마른 나뭇잎이나 돌멩이가 나왔나요? 욕심이 아니라 아이다운 탐험이에요. 진지한 얼굴로 버리되, 속으로는 이 꼬마 보급 담당에게 미소 지어 주세요. 세상을 탐험하는 중이니까요.', body_nl = 'Kwam er bij het wassen een opgedroogd blaadje of een steentje uit zijn broekzak? Dat is geen hebzucht, maar kinderlijk ontdekken. Gooi het met een serieus gezicht weg, maar glimlach vanbinnen om je kleine verzamelaar, hij ontdekt de wereld.', body_pl = 'Podczas prania spodni z kieszeni wypadł suchy liść albo kamyk? To nie łakomstwo, tylko dziecięce odkrywanie. Z poważną miną wyrzuć to do kosza, ale uśmiechnij się w duchu do tego małego zaopatrzeniowca, on odkrywa świat.', body_pt = 'Ao lavar as calças, saiu do bolso uma folha seca ou uma pedra? Não é gula, é exploração infantil. Com uma cara séria, deite-a ao lixo, mas sorria por dentro a este pequeno fornecedor: está a descobrir o mundo.', body_sv = 'Hittade du torkade löv eller en sten i byxfickan när du tvättade? Det är inte girighet, det är barnslig upptäckarlust. Släng dem med allvarlig min, men le inombords åt den lilla förrådsförvaltaren, hen upptäcker världen.', body_vi = 'Lúc giặt quần, mẹ thấy trong túi bé có chiếc lá khô hay hòn sỏi? Đó không phải tham lam, mà là một cuộc thám hiểm kiểu trẻ con. Hãy nghiêm mặt bỏ vào thùng rác, nhưng thầm mỉm cười với "người dự trữ" nhỏ này, bé đang khám phá thế giới.', body_zh = '洗裤子时，从口袋里掏出干树叶或石头？这不是贪吃，而是孩子式的探险。板着脸把它扔进垃圾桶，但心里对这个小“后勤官”笑一笑吧，宝宝正在探索世界。' WHERE id = 'ccae9470-c321-4925-94c0-7408317b4c14' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rechazar la chaqueta 🧥', body_es = '¿No quiere ponerse la chaqueta de invierno porque fuera hace sol? No te dejes engañar mirando por la ventana. Abre Tiempo y ropa y enséñale el símbolo del niño con ropa de invierno en el móvil. Deja la regla en manos de la pantalla y quítate de en medio.', title_fr = 'Le refus du blouson 🧥', body_fr = 'Parce qu''il y a du soleil dehors, il ne veut pas mettre son blouson d''hiver ? Ne vous fiez pas à ce que vous voyez par la fenêtre. Ouvrez Météo et tenue et montrez-lui sur le téléphone l''icône de l''enfant en tenue d''hiver. Confiez la règle à l''écran et effacez-vous.', title_hi = 'जैकेट से इनकार 🧥', body_hi = 'बाहर धूप है, इसलिए सर्दियों वाली जैकेट नहीं पहनना चाहता? खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े खोलिए, फ़ोन पर सर्दियों के कपड़े पहने बच्चे का निशान दिखाइए। नियम डिजिटल स्क्रीन पर डाल दीजिए, खुद बीच से हट जाइए।', title_id = 'Menolak jaket 🧥', body_id = 'Ia tidak mau memakai jaket musim dinginnya karena di luar cerah? Jangan tertipu dengan melihat dari jendela. Buka Cuaca dan Pakaian, tunjukkan simbol anak berpakaian musim dingin di ponsel. Serahkan aturan pada layar digital, Anda cukup menyingkir.', title_ja = 'ジャケットはいや 🧥', body_ja = '外は晴れているから冬のジャケットを着たがらない？窓の外を見てだまされないで。「天気と服装」を開いて、冬服を着た子どものマークを見せましょう。ルールはデジタル画面にまかせて、あなたは一歩下がって。', title_ko = '점퍼는 싫어 🧥', body_ko = '밖에 해가 났다고 겨울 점퍼를 안 입겠대요? 창밖만 보고 속지 마세요. 날씨와 옷차림을 열어 휴대폰 속 겨울옷 입은 아이 그림을 보여 주세요. 규칙은 화면에 맡기고 엄마는 빠지세요.', title_nl = 'De jas weigeren 🧥', body_nl = 'Wil hij zijn winterjas niet aan omdat de zon schijnt? Laat je niet misleiden door een blik uit het raam. Open Weer en kleding en laat hem het symbool zien van een kind in winterkleding. Laat het scherm de regel brengen en stap zelf opzij.', title_pl = 'Odmowa założenia kurtki 🧥', body_pl = 'Nie chce założyć zimowej kurtki, bo na dworze świeci słońce? Nie daj się zwieść widokowi z okna. Otwórz Pogodę i ubiór i pokaż w telefonie symbol dziecka w zimowym ubraniu. Przenieś zasadę na ekran, a sama zejdź z linii ognia.', title_pt = 'Recusar o casaco 🧥', body_pt = 'Não quer vestir o casaco de inverno porque está sol? Não se deixe enganar pela janela. Abra o Tempo e Roupa e mostre-lhe no telemóvel o símbolo da criança com roupa de inverno. Passe a regra para o ecrã digital e saia de cena.', title_sv = 'Att vägra jackan 🧥', body_sv = 'Vill barnet inte ta på sig vinterjackan för att solen skiner? Låt dig inte luras av att titta ut genom fönstret. Öppna Väder och kläder och visa telefonens symbol med ett vinterklätt barn. Lägg regeln på den digitala skärmen och kliv själv åt sidan.', title_vi = 'Không chịu mặc áo khoác 🧥', body_vi = 'Bên ngoài có nắng nên bé không chịu mặc áo khoác mùa đông? Đừng để bị đánh lừa khi chỉ nhìn qua cửa sổ. Hãy mở Thời tiết và trang phục, cho bé xem biểu tượng em bé mặc đồ mùa đông trên điện thoại. Để màn hình đặt ra quy tắc, mẹ đứng ngoài cuộc.', title_zh = '拒绝穿外套 🧥', body_zh = '因为外面有太阳，不肯穿冬天的外套？别被窗外的景象骗了。打开天气与穿衣，给宝宝看手机上穿着冬装的小朋友图标。把规则交给屏幕，你退到一边。' WHERE id = '039b7451-67d0-43b6-9ed0-d4ec9bf47752' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escondite debajo de la cama 🛏️', body_es = '¿No quiere dormir en su cama, sino sí o sí debajo de ella? Estos espacios pequeños y cerrados les dan la seguridad del vientre materno. Déjalo: cuando se duerma, lo subes con cuidado. Guarda tu energía.', title_fr = 'Cache-cache sous le lit 🛏️', body_fr = 'Il veut absolument dormir non pas dans son lit, mais dessous ? Ces petits espaces fermés le rassurent comme le ventre de sa mère. Laissez-le faire, vous le remonterez doucement une fois endormi, préservez votre énergie.', title_hi = 'बिस्तर के नीचे छुपन-छुपाई 🛏️', body_hi = 'बिस्तर पर नहीं, बिस्तर के नीचे ही सोना चाहता है? ऐसी बंद, छोटी जगहें उन्हें माँ के गर्भ जैसा भरोसा देती हैं। इजाज़त दीजिए, सो जाने के बाद धीरे से ऊपर लिटा दीजिएगा, अपनी ऊर्जा बचाइए।', title_id = 'Petak umpet di kolong tempat tidur 🛏️', body_id = 'Ia tidak mau tidur di tempat tidurnya, tapi bersikeras tidur di kolongnya? Tempat kecil dan tertutup seperti ini memberi mereka rasa aman seperti di dalam rahim. Biarkan saja, setelah ia tertidur Anda bisa mengangkatnya perlahan, simpan energi Anda.', title_ja = 'ベッドの下でかくれんぼ 🛏️', body_ja = 'ベッドの上ではなく、どうしてもベッドの下で眠りたい？せまくて囲まれた場所は、おなかの中にいたときのような安心感をくれるんです。させてあげて、寝ついたらそっと上に移しましょう。エネルギーを守って。', title_ko = '침대 밑 숨바꼭질 🛏️', body_ko = '침대 위가 아니라 꼭 침대 밑에서 자겠다고 하나요? 이런 좁고 아늑한 공간은 엄마 배 속처럼 안정감을 줘요. 허락해 주세요. 잠든 뒤 살며시 침대 위로 옮기면 돼요, 에너지를 아끼세요.', title_nl = 'Verstoppertje onder het bed 🛏️', body_nl = 'Wil hij niet in zijn bed, maar per se onder zijn bed slapen? Zulke kleine, afgesloten plekjes geven hem een veilig gevoel, net als in de buik. Laat het maar, als hij slaapt til je hem voorzichtig in bed, spaar je energie.', title_pl = 'Chowany pod łóżkiem 🛏️', body_pl = 'Chce spać nie w łóżku, tylko koniecznie pod łóżkiem? Takie zamknięte, małe przestrzenie dają mu poczucie bezpieczeństwa jak w łonie mamy. Pozwól mu, a gdy zaśnie, powoli przeniesiesz go wyżej. Oszczędzaj energię.', title_pt = 'Escondidas debaixo da cama 🛏️', body_pt = 'Não quer dormir na cama, mas sim debaixo dela? Estes espaços pequenos e fechados dão-lhes uma segurança como a do útero. Deixe: depois de adormecer, passe-o devagarinho para cima e poupe a sua energia.', title_sv = 'Kurragömma under sängen 🛏️', body_sv = 'Vill barnet absolut sova under sängen i stället för i den? Små, slutna utrymmen ger samma trygghet som i livmodern. Låt barnet göra det, när hen somnat kan du försiktigt lyfta upp hen, spara din energi.', title_vi = 'Trốn tìm dưới gầm giường 🛏️', body_vi = 'Bé không ngủ trên giường mà nhất định đòi ngủ dưới gầm giường? Những không gian nhỏ, kín đáo cho bé cảm giác an toàn như trong bụng mẹ. Cứ để bé ngủ, sau khi bé ngủ say mẹ có thể nhẹ nhàng bế lên giường, giữ sức nhé.', title_zh = '床底下的捉迷藏 🛏️', body_zh = '不睡床上，非要睡在床底下？这种封闭的小空间会给孩子像在妈妈肚子里一样的安全感。随宝宝去吧，等宝宝睡着后再轻轻抱上床，保存你的精力。' WHERE id = '1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un absurdo helado 🥶', body_es = '¿En lugar de soplar el té caliente para bebérselo, te exige que le eches hielo sí o sí? Está aprendiendo el contraste entre caliente y frío. Dale el hielo y deja que observe cómo se derrite. Aunque el desayuno se retrase, habrá hecho su propio descubrimiento científico.', title_fr = 'Une logique glaciale 🥶', body_fr = 'Au lieu de souffler sur son thé chaud, il exige absolument que vous y mettiez un glaçon ? Il découvre le contraste entre le chaud et le froid. Donnez-lui le glaçon et laissez-le observer la fonte. Même si le petit-déjeuner prend du retard, il aura fait sa découverte scientifique.', title_hi = 'बर्फ़ जैसी बेतुकी बात 🥶', body_hi = 'गरम चाय को फूँककर पीने के बजाय ज़िद करता है कि उसमें बर्फ़ डालो? वह गरम और ठंडे का फ़र्क सीख रहा है। बर्फ़ दे दीजिए, उसे पिघलते देखने दीजिए। नाश्ते में देर भले हो, पर उसने अपनी वैज्ञानिक खोज कर ली होगी।', title_id = 'Tak masuk akal sedingin es 🥶', body_id = 'Bukannya meniup teh panas lalu meminumnya, ia malah menuntut Anda memasukkan es ke dalamnya? Ia sedang mempelajari kontras panas dan dingin. Berikan esnya, biarkan ia mengamati proses mencair. Meski sarapan jadi terlambat, ia sudah melakukan penemuan ilmiahnya sendiri.', title_ja = '氷のように理屈ぬき 🥶', body_ja = '熱いお茶をふーふーして飲むかわりに、どうしても氷を入れてと言う？熱いと冷たいのちがいを学んでいます。氷を入れて、溶けていく様子を観察させてあげましょう。朝ごはんが遅れても、この子は自分なりの科学の発見をしています。', title_ko = '얼음 같은 비논리 🥶', body_ko = '뜨거운 차를 후후 불어 마시는 대신 꼭 얼음을 넣어 달라고 하나요? 뜨거움과 차가움의 대비를 배우는 중이에요. 얼음을 주고 녹는 과정을 지켜보게 하세요. 아침이 좀 늦어져도 아이는 자기만의 과학적 발견을 해낼 거예요.', title_nl = 'IJskoude onlogica 🥶', body_nl = 'Blaast hij niet op zijn warme thee, maar eist hij dat je er ijs in doet? Hij leert het verschil tussen warm en koud. Geef hem het ijs en laat hem kijken hoe het smelt. Ook al wordt het ontbijt later, hij heeft zijn eigen wetenschappelijke ontdekking gedaan.', title_pl = 'Lodowaty brak logiki 🥶', body_pl = 'Zamiast dmuchać na gorącą herbatę, żąda, żebyś koniecznie wrzuciła do niej lód? Poznaje kontrast ciepła i zimna. Daj mu lód i pozwól obserwować topnienie. Śniadanie może się opóźni, ale on dokona swojego naukowego odkrycia.', title_pt = 'Uma falta de lógica gelada 🥶', body_pt = 'Em vez de soprar o chá quente, exige que lhe ponha gelo lá dentro? Está a aprender o contraste entre quente e frio. Dê-lhe o gelo e deixe-o observar como derrete. Mesmo que o pequeno-almoço se atrase, ele terá feito a sua descoberta científica.', title_sv = 'Iskall ologik 🥶', body_sv = 'I stället för att blåsa på det varma teet kräver barnet att du lägger i is? Hen lär sig om kontrasten mellan varmt och kallt. Ge isen och låt barnet se hur den smälter. Även om frukosten blir sen har hen gjort sin egen vetenskapliga upptäckt.', title_vi = 'Sự phi lý lạnh như băng 🥶', body_vi = 'Thay vì thổi cho trà nguội, bé nhất định đòi mẹ thả đá vào? Bé đang học về sự tương phản nóng và lạnh. Hãy đưa đá cho bé, để bé quan sát quá trình tan chảy. Bữa sáng có muộn một chút, nhưng bé đã có một khám phá khoa học của riêng mình.', title_zh = '冰一样的“没逻辑” 🥶', body_zh = '热茶不吹凉了喝，却非要你往里面放冰块？宝宝在学习冷和热的对比。把冰块给宝宝，让宝宝看着它融化。就算早餐晚一点，宝宝也完成了自己的科学发现。' WHERE id = '73a43849-8300-493d-9040-f05eaf01e5b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una habitación de cuentos con sonido de lluvia 🌧️', body_es = '¿Te has quedado sin voz y sin fuerzas para leer el cuento? En Cuentos inteligentes pon de fondo solo el sonido de la lluvia y del bosque. A veces esta calma monótona de la naturaleza hipnotiza y duerme antes que la mejor y más emocionante historia.', title_fr = 'Une chambre à contes au son de la pluie 🌧️', body_fr = 'Vous n''avez plus de voix ni la force de lire un conte ? Dans les Contes intelligents, mettez seulement en fond le son de la pluie et de la forêt. Ce calme monotone de la nature hypnotise et endort parfois plus vite que la meilleure et la plus palpitante des histoires.', title_hi = 'बारिश की आवाज़ वाला कहानी कमरा 🌧️', body_hi = 'आवाज़ नहीं निकल रही, कहानी पढ़ने की ताकत नहीं? स्मार्ट कहानियों में बस बारिश और जंगल की आवाज़ बैकग्राउंड में चलाइए। प्रकृति की यह एक-सी शांति कभी-कभी सबसे अच्छी, सबसे रोमांचक कहानी से भी जल्दी जादू करके सुला देती है।', title_id = 'Kamar dongeng dengan suara hujan 🌧️', body_id = 'Suara Anda habis dan tak punya tenaga membacakan dongeng? Di Dongeng Pintar, putar saja suara hujan dan hutan sebagai latar. Ketenangan alam yang monoton ini kadang lebih cepat menghipnosis dan membawanya tidur daripada cerita terbaik dan paling seru.', title_ja = '雨の音のお話部屋 🌧️', body_ja = '声が出ない、お話を読む元気がない？「スマートおはなし」で、雨と森の音だけを背景に流しましょう。単調な自然の静けさは、ときにどんなにおもしろいお話よりも早く、眠りへと誘ってくれます。', title_ko = '빗소리 가득한 동화의 방 🌧️', body_ko = '목소리도 안 나오고 동화 읽을 힘도 없나요? 스마트 동화에서 빗소리와 숲 소리만 배경으로 틀어 두세요. 자연의 이 잔잔한 고요가 때로는 가장 신나는 최고의 이야기보다 더 빨리 최면을 걸어 잠들게 해 줘요.', title_nl = 'Een sprookjeskamer vol regengeluid 🌧️', body_nl = 'Is je stem op en heb je geen kracht om voor te lezen? Zet in Slimme sprookjes alleen regen- en bosgeluiden op de achtergrond aan. Deze eentonige stilte van de natuur hypnotiseert soms sneller dan het beste, spannendste verhaal en brengt hem in slaap.', title_pl = 'Bajkowy pokój z odgłosem deszczu 🌧️', body_pl = 'Nie masz głosu ani siły, by czytać bajkę? Włącz w Mądrych bajkach w tle tylko szum deszczu i lasu. Ta monotonna cisza natury czasem hipnotyzuje i usypia szybciej niż najlepsza, najbardziej ekscytująca historia.', title_pt = 'Um quarto de histórias com som de chuva 🌧️', body_pt = 'Ficou sem voz e não tem forças para ler uma história? Nas Histórias Inteligentes, ponha de fundo apenas o som da chuva e da floresta. Este sossego monótono da natureza às vezes hipnotiza e adormece mais depressa do que a melhor e mais emocionante história.', title_sv = 'Ett sagorum med regnljud 🌧️', body_sv = 'Har du ingen röst kvar och orkar inte läsa saga? Sätt bara på regn- och skogsljud som bakgrund i Smarta sagor. Naturens monotona stillhet hypnotiserar ibland snabbare än den bästa och mest spännande berättelsen och för barnet in i sömnen.', title_vi = 'Căn phòng kể chuyện có tiếng mưa 🌧️', body_vi = 'Mẹ khản giọng, không còn sức đọc truyện? Trong Truyện cổ tích thông minh, chỉ cần bật tiếng mưa và tiếng rừng làm nền. Sự tĩnh lặng đều đều của thiên nhiên đôi khi "thôi miên" và đưa bé vào giấc ngủ nhanh hơn cả câu chuyện hay nhất, hấp dẫn nhất.', title_zh = '有雨声的故事房间 🌧️', body_zh = '嗓子哑了，没力气讲故事？在智慧童话里只把雨声和森林声当背景打开。大自然这份单调的宁静，有时比最好、最精彩的故事更快让人“被催眠”、进入梦乡。' WHERE id = '1171703b-c644-4ad0-8298-a24063264467' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se enfada consigo mismo en el espejo 🪞', body_es = '¿Se pone delante del espejo, hace ruidos distintos y pone muecas? Es su conciencia de sí mismo que se fortalece. Está comprobando cómo se ven desde fuera su cuerpo y sus emociones. Obsérvalo en silencio desde fuera.', title_fr = 'Il s''énerve contre lui-même dans le miroir 🪞', body_fr = 'Il se met devant le miroir, fait des bruits différents et des grimaces ? C''est la conscience de soi qui se renforce. Il teste à quoi ressemblent de l''extérieur son corps et ses émotions. Observez en silence, de loin.', title_hi = 'आईने में खुद पर गुस्सा 🪞', body_hi = 'आईने के सामने जाकर अलग-अलग आवाज़ें निकालता है और चेहरे बनाता है? यह ‘मैं’ वाली समझ का मज़बूत होना है। वह परख रहा है कि उसका शरीर और भावनाएँ बाहर से कैसी दिखती हैं। किनारे से चुपचाप देखिए।', title_id = 'Kesal pada dirinya di cermin 🪞', body_id = 'Ia berdiri di depan cermin, membuat berbagai suara dan ekspresi? Ini tanda kesadaran diri yang menguat. Ia sedang menguji bagaimana tubuh dan emosinya terlihat dari luar. Saksikan diam-diam dari samping.', title_ja = '鏡の中の自分にイライラ 🪞', body_ja = '鏡の前で、いろいろな声を出したり、表情をつくったりしている？これは自我の意識が強くなっているしるし。自分の体や気持ちが外からどう見えるかをためしています。そばで静かに見守りましょう。', title_ko = '거울 속 자신에게 화내기 🪞', body_ko = '거울 앞에 서서 여러 소리를 내고 표정을 지어 보나요? 자아의식이 강해지는 중이에요. 자기 몸과 감정이 밖에서 어떻게 보이는지 시험하는 거예요. 옆에서 조용히 지켜봐 주세요.', title_nl = 'Boos op zichzelf in de spiegel 🪞', body_nl = 'Gaat hij voor de spiegel staan en maakt hij allerlei geluiden en gezichten? Dit is het groeiende ik-besef. Hij test hoe zijn lichaam en emoties er van buitenaf uitzien. Kijk stilletjes van een afstand toe.', title_pl = 'Złości się na siebie w lustrze 🪞', body_pl = 'Staje przed lustrem, wydaje różne dźwięki i robi miny? To wzmacnia się jego świadomość własnego „ja”. Sprawdza, jak jego ciało i emocje wyglądają z zewnątrz. Obserwuj po cichu z boku.', title_pt = 'Zanga-se consigo próprio ao espelho 🪞', body_pt = 'Põe-se em frente ao espelho a fazer sons e expressões diferentes? É a consciência de si próprio a ganhar força. Está a testar como o corpo e as emoções se veem de fora. Observe em silêncio, à distância.', title_sv = 'Blir arg på sig själv i spegeln 🪞', body_sv = 'Ställer sig barnet framför spegeln, gör olika ljud och miner? Det är jagmedvetandet som blir starkare. Hen testar hur kroppen och känslorna ser ut utifrån. Titta tyst på från sidan.', title_vi = 'Bé tự giận mình trong gương 🪞', body_vi = 'Bé đứng trước gương, phát ra đủ thứ âm thanh và làm đủ kiểu nét mặt? Đó là ý thức về "cái tôi" đang mạnh dần lên. Bé đang thử xem cơ thể và cảm xúc của mình trông thế nào từ bên ngoài. Hãy lặng lẽ quan sát từ xa.', title_zh = '对着镜子里的自己生气 🪞', body_zh = '走到镜子前，发出各种声音、做各种表情？这是自我意识在增强。宝宝在测试自己的身体和情绪从外面看起来是什么样子。在一旁静静地看着吧。' WHERE id = '43e7fbfe-64bc-4627-85d6-4ddae59c6985' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se te pega a las piernas todo el día pidiendo brazos? Estás agotada físicamente. Estás saturada de contacto. Déjalo en su habitación con sus juguetes, escápate 5 minutos al baño y cierra la puerta. Solo siente esa soledad.', body_fr = 'Il s''accroche à vos jambes toute la journée et veut des câlins ? Vous êtes physiquement à bout. Vous vivez la saturation du toucher. Laissez-le dans la pièce avec ses jouets, filez 5 minutes dans la salle de bain et fermez la porte. Ressentez simplement cette solitude.', body_hi = 'दिनभर पैरों से लिपटा रहता है, गोद माँगता है? आप शारीरिक रूप से थक चुकी हैं। यह छुए जाने की थकान है। उसे खिलौनों के साथ कमरे में छोड़कर 5 मिनट बाथरूम चली जाइए, दरवाज़ा बंद कीजिए। बस उस अकेलेपन को महसूस कीजिए।', body_id = 'Seharian ia menempel di kaki Anda dan minta digendong? Secara fisik Anda sudah habis. Anda sedang mengalami kelelahan disentuh. Tinggalkan ia di kamar dengan mainannya, larilah ke kamar mandi selama 5 menit, dan tutup pintunya. Rasakan saja kesendirian itu.', body_ja = '一日じゅう足にしがみついて抱っこをせがむ？体力が尽きていますね。触れられ疲れを感じているんです。おもちゃと一緒に部屋で遊ばせて、5分だけお風呂場に逃げこみ、ドアを閉めて。ただそのひとりの時間を感じましょう。', body_ko = '하루 종일 다리에 매달려 안아 달라고 하나요? 몸이 완전히 지쳤어요. 터치 피로를 겪고 있는 거예요. 아이를 장난감과 함께 방에 두고 5분만 욕실로 피신해 문을 닫으세요. 그저 혼자임을 느껴 보세요.', body_nl = 'Hangt hij de hele dag aan je been en wil hij steeds op schoot? Je bent lichamelijk op. Je hebt last van aanrakingsmoeheid. Laat hem met zijn speelgoed in de kamer, vlucht 5 minuten naar de badkamer en doe de deur dicht. Voel gewoon even die rust van het alleen zijn.', body_pl = 'Cały dzień wisi ci na nodze i chce na ręce? Jesteś fizycznie wyczerpana. Przeżywasz przebodźcowanie dotykiem. Zostaw go z zabawkami w pokoju, uciekaj na 5 minut do łazienki i zamknij drzwi. Po prostu poczuj tę samotność.', body_pt = 'Passa o dia agarrado às suas pernas a pedir colo? Está fisicamente esgotada. É o cansaço de toque. Deixe-o no quarto com os brinquedos, fuja 5 minutos para a casa de banho e feche a porta. Sinta apenas essa solidão.', body_sv = 'Hänger barnet i benen hela dagen och vill bli buren? Du är fysiskt slutkörd. Du upplever beröringsutmattning. Lämna barnet med leksakerna i ett säkert rum, fly till badrummet i 5 minuter och stäng dörren. Känn bara ensamheten.', body_vi = 'Cả ngày bé bám chân, đòi bế? Mẹ đã kiệt sức về thể chất. Mẹ đang "quá tải vì bị chạm". Hãy để bé chơi đồ chơi trong phòng, trốn vào phòng tắm 5 phút và đóng cửa lại. Chỉ cần cảm nhận khoảnh khắc một mình ấy.', body_zh = '一整天抱着你的腿，要你抱？你的身体已经透支了。这是“触碰疲劳”。让宝宝在房间里玩玩具，你躲进浴室5分钟，关上门。好好感受那份独处。' WHERE id = '5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá que da sueño 📖', body_es = '¿Tienes la voz cansada y no te quedan fuerzas para leer el cuento? Pásale la pelota a papá. Su tono de voz distinto y grave y los detalles absurdos que se invente hipnotizarán y dormirán al peque antes que tu voz de siempre.', title_fr = 'Le conte de papa qui endort 📖', body_fr = 'Votre voix est fatiguée et vous n''avez pas la force de lire le conte ? Passez la balle à papa. Sa voix différente et grave, et les détails absurdes qu''il invente, hypnotiseront le cerveau de l''enfant et l''endormiront plus vite que votre voix habituelle.', title_hi = 'पापा की नींद लाने वाली कहानी 📖', body_hi = 'आपकी आवाज़ थक गई है, कहानी पढ़ने की ताकत नहीं? गेंद पापा के पाले में डालिए। पापा की अलग, भारी आवाज़ और गढ़ी हुई बेतुकी बातें बच्चे के दिमाग पर आपकी जानी-पहचानी आवाज़ से जल्दी जादू करके उसे सुला देंगी।', title_id = 'Dongeng pengantar tidur dari Ayah 📖', body_id = 'Suara Anda lelah dan tak punya tenaga membacakan dongeng? Oper bolanya ke Ayah. Suara Ayah yang berbeda dan berat serta detail-detail absurd karangannya akan menghipnosis otak anak dan membawanya tidur lebih cepat daripada suara Anda yang sudah biasa ia dengar.', title_ja = 'パパの眠くなるお話 📖', body_ja = '声が疲れて、お話を読む元気がない？ボールはパパにパス。いつもとちがう低い声と、パパが考えたおかしなディテールが、聞きなれたあなたの声よりも早く子どもを眠りへと誘います。', title_ko = '잠이 오는 아빠의 동화 📖', body_ko = '목소리도 지치고 동화 읽을 힘도 없나요? 공을 아빠에게 넘기세요. 아빠의 다르고 굵은 목소리와 지어낸 엉뚱한 이야기가, 익숙한 엄마 목소리보다 더 빨리 아이에게 최면을 걸어 잠들게 할 거예요.', title_nl = 'Papa''s slaapverwekkende sprookje 📖', body_nl = 'Is je stem moe en heb je geen kracht om voor te lezen? Speel de bal door naar papa. Zijn andere, zware stem en de absurde details die hij verzint, hypnotiseren het brein van je kind sneller dan jouw vertrouwde stem en brengen hem in slaap.', title_pl = 'Usypiająca bajka taty 📖', body_pl = 'Twój głos jest zmęczony i nie masz siły czytać bajki? Przekaż piłeczkę tacie. Jego inny, niski głos i wymyślone absurdalne szczegóły zahipnotyzują i uśpią mózg dziecka szybciej niż twój znajomy głos.', title_pt = 'A história do pai que dá sono 📖', body_pt = 'Tem a voz cansada e não tem forças para ler a história? Passe a bola ao pai. A voz grossa e diferente dele e os pormenores absurdos que inventa vão hipnotizar e adormecer o cérebro da criança mais depressa do que a voz a que já está habituado.', title_sv = 'Pappas sövande saga 📖', body_sv = 'Är rösten trött och du orkar inte läsa saga? Skicka bollen till pappa. Pappas annorlunda, djupa röst och de absurda detaljerna han hittar på hypnotiserar barnets hjärna och för hen in i sömnen snabbare än din välbekanta röst.', title_vi = 'Câu chuyện ru ngủ của bố 📖', body_vi = 'Giọng mẹ đã mệt, không còn sức đọc truyện? Hãy chuyền bóng cho bố. Giọng trầm ấm khác lạ của bố cùng những chi tiết vô lý bố tự nghĩ ra sẽ "thôi miên" não bé và đưa bé vào giấc ngủ nhanh hơn giọng quen thuộc của mẹ.', title_zh = '爸爸的催眠故事 📖', body_zh = '嗓子累了，没力气讲故事？把球传给爸爸。爸爸不一样的低沉嗓音和编出来的荒诞细节，会比你熟悉的声音更快让宝宝“被催眠”、进入梦乡。' WHERE id = '14317db1-b6eb-40d2-8404-59bcea4acdf7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La función de «¿Tú quién eres?» 🎭', body_es = '¿Por la mañana te ha mirado como a una desconocida y te ha dicho «¿Tú quién eres? ¿Dónde está mi mamá?»? Es un nuevo juego de rol. Dile: «Soy la vecina, tu mamá viene ahora». Que la habitación se llene de risas por la mañana: ahorra muchísima más energía que ponerse cabezota.', title_fr = 'Le spectacle du « Qui es-tu ? » 🎭', body_fr = 'Le matin, il vous a regardée comme une inconnue et a dit : « Qui es-tu ? Où est ma maman ? » C''est un nouveau jeu de rôle. Dites : « Je suis la voisine, ta maman arrive. » Que la chambre éclate de rire dès le matin : cela économise bien plus d''énergie que de s''entêter.', title_hi = '‘तुम कौन हो?’ वाला नाटक 🎭', body_hi = 'सुबह आपको अजनबी की तरह देखकर पूछा, ‘तुम कौन हो? मेरी माँ कहाँ है?’ यह नया रोल-प्ले है। कहिए, ‘मैं पड़ोस वाली आंटी हूँ, तुम्हारी माँ अभी आ रही है।’ सुबह हँसी से कमरा गूँजने दीजिए, यह ज़िद करने से कहीं ज़्यादा ऊर्जा बचाता है।', title_id = 'Pertunjukan ''Kamu siapa?'' 🎭', body_id = 'Pagi ini ia menatap Anda seperti orang asing dan berkata ''Kamu siapa? Mamaku mana?'' Ini permainan peran baru. Katakan ''Aku tante tetangga, mamamu sebentar lagi datang''. Biarkan kamar pecah oleh tawa pagi ini, ini jauh lebih menghemat energi daripada beradu keras kepala.', title_ja = '「あなたは誰？」劇場 🎭', body_ja = '朝、知らない人を見るような顔で「あなたは誰？ママはどこ？」と言った？新しいごっこ遊びです。「となりのおばさんよ、ママはすぐ来るからね」と言ってあげて。朝から笑いで部屋をいっぱいにしましょう。意地の張り合いよりずっとエネルギーの節約になります。', title_ko = '''누구세요?'' 연극 🎭', body_ko = '아침에 낯선 사람 보듯 ''누구세요? 우리 엄마 어디 있어요?'' 했나요? 새로운 역할 놀이예요. ''나는 옆집 아줌마야, 엄마는 곧 오실 거야'' 하고 받아 주세요. 아침부터 웃음으로 방이 떠나가게 두세요, 고집 싸움보다 훨씬 에너지를 아껴 줘요.', title_nl = 'Het ''Wie ben jij?''-toneelstuk 🎭', body_nl = 'Keek hij je ''s ochtends aan als een vreemde en zei hij: ''Wie ben jij? Waar is mijn mama?'' Dit is een nieuw rollenspel. Zeg: ''Ik ben de buurvrouw, je mama komt zo.'' Laat de kamer vanochtend schudden van het lachen, dat bespaart je veel meer energie dan koppig volhouden.', title_pl = 'Przedstawienie „Kim jesteś?” 🎭', body_pl = 'Rano spojrzał na ciebie jak na obcą i zapytał: „Kim jesteś? Gdzie moja mama?”. To nowa zabawa w odgrywanie ról. Powiedz: „Jestem panią sąsiadką, mama zaraz przyjdzie”. Niech poranek wypełni śmiech, to oszczędza dużo więcej energii niż upieranie się.', title_pt = 'O espetáculo "Quem és tu?" 🎭', body_pt = 'De manhã olhou para si como para uma estranha e disse "Quem és tu? Onde está a minha mãe?"? É um novo jogo de faz de conta. Diga "Sou a vizinha, a tua mãe já vem". Deixe que o quarto se encha de gargalhadas logo de manhã: poupa muito mais energia do que teimar.', title_sv = 'Föreställningen ”Vem är du?” 🎭', body_sv = 'Tittade barnet på dig som på en främling i morse och sa ”Vem är du? Var är mamma?” Det är en ny rollek. Säg ”Jag är tanten från grannhuset, mamma kommer snart”. Låt rummet fyllas av skratt på morgonen, det sparar mångdubbelt mer energi än att tjafsa.', title_vi = 'Vở kịch "Cô là ai?" 🎭', body_vi = 'Sáng nay bé nhìn mẹ như người lạ và hỏi "Cô là ai? Mẹ con đâu?" Đây là trò nhập vai mới. Hãy nói: "Cô là cô hàng xóm, mẹ con sắp về rồi." Để cả phòng rộn tiếng cười buổi sáng, cách này tiết kiệm sức hơn gấp nhiều lần so với giằng co.', title_zh = '“你是谁？”小剧场 🎭', body_zh = '早上像看陌生人一样看着你说：“你是谁？我妈妈在哪儿？”这是新的角色扮演游戏。说“我是邻居阿姨，你妈妈马上就来”。让早晨的笑声充满房间，这比较劲省力得多。' WHERE id = '5d28c236-3ed8-4900-b875-c6d0d9b2aa20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Su comida no la comparte contigo 🍳', body_es = '¿No te da nada de su plato, pero insiste en comer del tuyo? Los niños siempre confían plenamente en lo que eligen sus padres. No pelees: pásale el bocado con cariño y sonríe ante este egoísmo tan cómico.', title_fr = 'Il ne partage pas son repas avec vous 🍳', body_fr = 'Il ne vous donne rien de son assiette, mais vient insister pour manger dans la vôtre ? Les enfants font toujours entièrement confiance aux choix de leurs parents. Ne luttez pas, donnez-lui la bouchée avec amour et souriez simplement à cet égoïsme comique.', title_hi = 'अपना खाना आपको नहीं देगा 🍳', body_hi = 'अपनी प्लेट का खाना आपको नहीं देता, पर आकर ज़िद से आपकी प्लेट से खाना चाहता है? बच्चे अपने माता-पिता की पसंद पर हमेशा पूरा भरोसा करते हैं। लड़िए मत, निवाला प्यार से उसे दे दीजिए और इस मज़ेदार स्वार्थ पर बस मुस्कुराइए।', title_id = 'Makanannya sendiri tidak akan dibagi 🍳', body_id = 'Ia tidak mau membagi isi piringnya, tapi bersikeras makan dari piring Anda? Anak selalu sepenuhnya percaya pada pilihan orang tuanya. Jangan dilawan, berikan suapan itu dengan penuh cinta dan tersenyumlah saja pada keegoisan lucu ini.', title_ja = '自分のごはんはくれない 🍳', body_ja = '自分のお皿のものはくれないのに、あなたのお皿からは食べたがる？子どもはいつも、親の選ぶものを信頼しています。争わずに、ひと口を愛情こめて分けてあげて、このおかしなわがままにただほほえみましょう。', title_ko = '자기 음식은 절대 안 줘 🍳', body_ko = '자기 접시는 절대 안 나눠 주면서 엄마 접시의 음식은 꼭 먹겠다고 하나요? 아이들은 부모의 선택을 언제나 믿어요. 실랑이하지 말고 한 입을 사랑스럽게 건네며 이 귀여운 이기심에 그냥 웃어 주세요.', title_nl = 'Zijn eigen eten deelt hij niet 🍳', body_nl = 'Geeft hij jou niets van zijn bord, maar wil hij per se van jouw bord eten? Kinderen vertrouwen altijd volledig op de keuze van hun ouders. Ga de strijd niet aan, geef hem liefdevol een hapje en glimlach gewoon om dit grappige egoïsme.', title_pl = 'Swojego jedzenia ci nie odda 🍳', body_pl = 'Nie daje ci nic ze swojego talerza, ale uparcie chce jeść z twojego? Dzieci zawsze w pełni ufają wyborom rodziców. Nie walcz, z miłością podaj mu kęs i po prostu uśmiechnij się do tego zabawnego egoizmu.', title_pt = 'Não dá a comida dele 🍳', body_pt = 'Não lhe dá nada do prato dele, mas vem insistir em comer do seu? As crianças confiam sempre totalmente nas escolhas dos pais. Não lute: passe-lhe a garfada com amor e sorria simplesmente a este egoísmo cómico.', title_sv = 'Ger inte bort sin egen mat 🍳', body_sv = 'Barnet delar inte med sig av det som ligger på hens tallrik, men vill envist äta från din? Barn litar alltid helt på föräldrarnas val. Kämpa inte emot, ge barnet tuggan med kärlek och le bara åt den komiska egoismen.', title_vi = 'Không chia đồ ăn của mình 🍳', body_vi = 'Bé không cho mẹ ăn gì trong đĩa của mình, nhưng lại nhất định đòi ăn từ đĩa của mẹ? Trẻ luôn hoàn toàn tin vào lựa chọn của cha mẹ. Đừng giằng co, hãy âu yếm đút cho bé một miếng và mỉm cười trước sự "ích kỷ" đáng yêu này.', title_zh = '自己的饭不给你 🍳', body_zh = '自己盘子里的不给你，却非要来吃你盘子里的？孩子总是完全信任父母的选择。别较劲，满怀爱意地把这一口递给宝宝，对这份可爱的“自私”笑一笑吧。' WHERE id = '8758179c-cc13-42d7-b2c1-4900aea35e3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Quiero volar! 🕊️', body_es = '¿Salta del sofá agitando los brazos y se enfada contigo porque no vuela? Todavía es pronto para enseñarle las leyes de la física. Dile «No vuelas porque tus alas todavía están creciendo» y lleva su atención a saltar sobre algo blandito.', title_fr = 'Je veux voler ! 🕊️', body_fr = 'Il saute du canapé en battant des bras et vous en veut de ne pas voler ? Il est encore trop tôt pour lui apprendre les lois de la physique. Dites « Tu ne voles pas parce que tes ailes sont encore en train de pousser » et orientez-le vers des sauts sur un endroit moelleux.', title_hi = 'मुझे उड़ना है! 🕊️', body_hi = 'सोफ़े से कूदकर बाँहें फड़फड़ाता है और उड़ न पाने पर आपसे नाराज़ होता है? भौतिकी के नियम सिखाना अभी जल्दी है। ‘तुम नहीं उड़ते, क्योंकि तुम्हारे पंख अभी बढ़ रहे हैं’ कहकर उसका ध्यान किसी नरम जगह पर कूदने की ओर लगाइए।', title_id = 'Aku mau terbang! 🕊️', body_id = 'Ia melompat dari sofa sambil mengepakkan tangan dan marah pada Anda karena tidak bisa terbang? Masih terlalu dini mengajarinya hukum fisika. Katakan ''Kamu belum bisa terbang karena sayapmu masih tumbuh'' dan alihkan perhatiannya untuk melompat ke tempat yang empuk.', title_ja = '飛びたいの！ 🕊️', body_ja = 'ソファから飛びおりて腕をパタパタさせ、飛べないことにあなたへ怒っている？物理の法則を教えるのはまだ早いですね。「飛べないのは、羽がまだ育っているからだよ」と言って、やわらかい場所へのジャンプに気をそらしましょう。', title_ko = '날고 싶어! 🕊️', body_ko = '소파에서 뛰어내리며 팔을 퍼덕이다가 못 날았다고 엄마에게 화를 내나요? 물리 법칙을 가르치기엔 아직 일러요. ''아직 날개가 자라는 중이라 못 나는 거야'' 하며 푹신한 곳으로 뛰어내리는 놀이로 관심을 돌려 주세요.', title_nl = 'Ik wil vliegen! 🕊️', body_nl = 'Springt hij van de bank, fladdert hij met zijn armen en is hij boos op je omdat hij niet vliegt? Het is nog te vroeg om hem de wetten van de natuurkunde te leren. Zeg ''Je vliegt nog niet, want je vleugels groeien nog'' en richt zijn aandacht op springen op een zachte plek.', title_pl = 'Chcę latać! 🕊️', body_pl = 'Skacze z kanapy, macha rękami i złości się na ciebie, że nie leci? Na naukę praw fizyki jest jeszcze za wcześnie. Powiedz: „Nie latasz, bo twoje skrzydła jeszcze rosną” i skieruj jego uwagę na skakanie na coś miękkiego.', title_pt = 'Quero voar! 🕊️', body_pt = 'Salta do sofá a bater os braços e zanga-se consigo porque não voa? Ainda é cedo para lhe ensinar as leis da física. Diga "Não voas porque as tuas asas ainda estão a crescer" e desvie a atenção dele para saltar para um sítio macio.', title_sv = 'Jag vill flyga! 🕊️', body_sv = 'Hoppar barnet från soffan, flaxar med armarna och blir arg på dig för att hen inte flyger? Det är för tidigt att lära ut fysikens lagar. Säg ”Du flyger inte för att dina vingar fortfarande växer” och led uppmärksamheten till att hoppa ner på något mjukt.', title_vi = 'Con muốn bay! 🕊️', body_vi = 'Bé nhảy từ sofa xuống, vỗ tay như cánh và giận mẹ vì mình không bay được? Còn quá sớm để dạy bé các định luật vật lý. Hãy nói: "Con chưa bay được vì đôi cánh còn đang lớn" và hướng bé sang nhảy xuống chỗ mềm.', title_zh = '我想飞！🕊️', body_zh = '从沙发上跳下来拍着手臂，因为飞不起来而冲你发火？现在教宝宝物理定律还太早。说“你还飞不起来，因为你的翅膀还在长”，再把宝宝的注意力引到往软软的地方跳上。' WHERE id = '12a06ab8-bcee-4772-8e2b-6f509250a594' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Al servirte un té has visto que el móvil ha desaparecido y que detrás del sofá está diciendo «¿Diga?» igual que tú? Está copiando tus hábitos digitales. Al quitarle el aparato, dile entre risas «Mi móvil también quería hablar contigo».', body_fr = 'En vous servant un thé, vous avez remarqué que votre téléphone avait disparu, et derrière le canapé, il dit « Allô » comme vous ? Il copie vos habitudes numériques. En récupérant l''appareil, dites en riant « Mon téléphone voulait te parler aussi ».', body_hi = 'अपने लिए चाय डालते समय देखा कि आपका फ़ोन गायब है और वह सोफ़े के पीछे आपकी तरह ‘हैलो’ बोल रहा है? वह आपकी डिजिटल आदतों की नकल कर रहा है। ‘मेरा फ़ोन भी तुमसे बात करना चाहता था’ कहकर हँसते हुए फ़ोन वापस ले लीजिए।', body_id = 'Saat menuang teh, Anda sadar ponsel Anda hilang dan ia di balik sofa sedang bilang ''Halo'' persis seperti Anda? Ia sedang meniru kebiasaan digital Anda. Saat mengambil ponselnya, katakan sambil tertawa ''Ternyata ponsel Mama juga ingin ngobrol denganmu''.', body_ja = '自分にお茶を入れていたら、スマホがなくなっていて、ソファの後ろであなたのまねをして「もしもし」と言っている？あなたのデジタル習慣をまねしているんです。「スマホもあなたとお話ししたかったんだね」と言って、笑いながら返してもらいましょう。', body_ko = '차를 따르다 보니 휴대폰이 사라졌고, 아이가 소파 뒤에서 엄마처럼 ''여보세요'' 하고 있나요? 엄마의 디지털 습관을 따라 하는 중이에요. ''휴대폰도 엄마랑 이야기하고 싶대'' 하며 웃으면서 돌려받으세요.', body_nl = 'Schenk je thee in en merk je dat je telefoon verdwenen is, terwijl hij achter de bank net als jij ''Hallo?'' zegt? Hij kopieert je digitale gewoontes. Zeg bij het teruggeven ''Mijn telefoon wilde ook met jou praten'' en neem hem lachend uit zijn hand.', body_pl = 'Nalewasz sobie herbatę i nagle widzisz, że telefon zniknął, a on za kanapą mówi „Halo” dokładnie jak ty? Kopiuje wasze cyfrowe nawyki. Zabierając mu urządzenie, powiedz ze śmiechem: „Mój telefon też chciał z tobą porozmawiać”.', body_pt = 'Ao servir-se de chá, reparou que o telemóvel desapareceu e que ele, atrás do sofá, está a dizer "Estou?" como a mãe? Está a copiar os seus hábitos digitais. Ao recuperar o aparelho, diga "O meu telemóvel também queria falar contigo" e tire-lho da mão a rir.', body_sv = 'När du hällde upp te åt dig själv märkte du att telefonen hade försvunnit, och bakom soffan säger barnet ”Hallå” precis som du? Barnet kopierar dina digitala vanor. Säg ”Min telefon ville visst också prata med dig” och ta den skrattande ur handen.', body_vi = 'Lúc rót trà, mẹ chợt thấy điện thoại biến mất, và sau sofa vang lên tiếng bé nói "A lô" y như mẹ? Bé đang bắt chước thói quen dùng điện thoại của mẹ. Khi lấy lại máy, hãy cười và nói: "Hóa ra điện thoại cũng muốn nói chuyện với con."', body_zh = '给自己倒茶时，发现手机不见了，原来宝宝正躲在沙发后面学你说“喂？”？宝宝在模仿你们的数字习惯。拿回手机时笑着说一句“原来我的手机也想跟你聊天呀”。' WHERE id = 'e80a8c85-c67a-45b2-8209-90553a33fb5f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En silencio, en pareja 🥂', body_es = 'El peque duerme y la casa está recogida. Siéntate en el sofá junto a tu pareja, sin encender siquiera la tele. Solo miraos con esa mirada de «esto también lo hemos conseguido, hemos sobrevivido». Créeme, este es el momento de equipo más auténtico de unos padres cansados.', title_fr = 'En silence, à deux 🥂', body_fr = 'L''enfant dort, la maison est rangée. Asseyez-vous côte à côte sur le canapé avec votre partenaire, sans même allumer la télé. Échangez simplement ce regard qui dit « On y est arrivés, on a survécu ». Croyez-moi, voilà le moment d''équipe le plus vrai de la vie de parents fatigués.', title_hi = 'जोड़ी के रूप में खामोशी में 🥂', body_hi = 'बच्चा सो गया, घर समेट लिया। अपने साथी के साथ सोफ़े पर पास-पास बैठिए, टीवी भी मत चलाइए। बस एक-दूसरे को ‘यह भी कर लिया, हम बच गए’ वाली नज़र से देखिए। यकीन मानिए, थकी हुई पेरेंटिंग का सबसे सच्चा टीमवर्क वाला पल यही है।', title_id = 'Hening berdua sebagai pasangan 🥂', body_id = 'Anak sudah tidur, rumah sudah rapi. Duduklah berdampingan dengan pasangan di sofa, bahkan tanpa menyalakan TV. Cukup saling bertukar tatapan ''kita berhasil melewati ini juga, kita bertahan''. Percayalah, inilah momen tim paling nyata bagi orang tua yang lelah.', title_ja = 'ふたりで静かな時間を 🥂', body_ja = '子どもは寝て、家も片づいた。パートナーとソファに並んで座り、テレビもつけないで。ただ「今日も乗りきったね」という視線を交わしましょう。それこそが、疲れた子育ての中のいちばん本当のチームの瞬間です。', title_ko = '부부가 함께하는 고요 🥂', body_ko = '아이는 잠들고 집도 정리됐어요. 배우자와 소파에 나란히 앉아 TV도 켜지 마세요. 그저 ''오늘도 해냈다, 살아남았다''는 눈빛을 서로 나누세요. 이게 바로 지친 육아 속 가장 진짜인 팀워크의 순간이에요.', title_nl = 'Samen in stilte 🥂', body_nl = 'Je kind slaapt, het huis is opgeruimd. Ga met je partner naast elkaar op de bank zitten, zet zelfs de tv niet aan. Geef elkaar gewoon die blik van ''we hebben het weer gered, we hebben het overleefd''. Geloof ons, dit is het meest echte teammoment van vermoeid ouderschap.', title_pl = 'We dwoje w ciszy 🥂', body_pl = 'Dziecko śpi, dom posprzątany. Usiądź z partnerem obok siebie na kanapie, nawet nie włączajcie telewizora. Po prostu wymieńcie spojrzenia mówiące „i to nam się udało, przetrwaliśmy”. Uwierz, to właśnie najprawdziwsza drużynowa chwila zmęczonego rodzicielstwa.', title_pt = 'Em silêncio, como um casal 🥂', body_pt = 'A criança adormeceu, a casa está arrumada. Sente-se no sofá ao lado do seu companheiro, nem sequer ligue a televisão. Troquem apenas aquele olhar de "também conseguimos isto, sobrevivemos". Acredite, é este o momento de equipa mais verdadeiro de uma parentalidade cansada.', title_sv = 'Tystnad som par 🥂', body_sv = 'Barnet sover, huset är städat. Sätt dig bredvid din partner i soffan och slå inte ens på tv:n. Ge bara varandra blicken som säger ”vi klarade det här också, vi överlevde”. Tro mig, det är det trötta föräldraskapets mest äkta lagstund.', title_vi = 'Hai vợ chồng trong yên lặng 🥂', body_vi = 'Bé đã ngủ, nhà đã dọn. Hãy ngồi cạnh chồng trên sofa, thậm chí đừng bật TV. Chỉ cần trao nhau ánh mắt "Chúng ta lại làm được rồi, lại sống sót rồi". Tin đi, đó chính là khoảnh khắc đồng đội chân thật nhất của những bậc cha mẹ mệt mỏi.', title_zh = '两个人的安静时光 🥂', body_zh = '宝宝睡了，家也收拾好了。和另一半并肩坐在沙发上，连电视都别开。只要彼此对视一眼：“这一关我们也挺过来了。”相信我，这就是疲惫的为人父母最真实的团队时刻。' WHERE id = 'ebb45c07-d4c6-4504-ac39-3e83655d3e00' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea por salir del parque 🤝', body_es = '¿En el tobogán ha empujado a otro niño para subirse él? Todo el mundo te mira. No te avergüences ni le pegues. Recuérdale la regla con voz suave pero firme: «Ahora le toca a él, luego subimos nosotros». Así funciona el sistema.', title_fr = 'La dispute pour quitter le parc 🤝', body_fr = 'Il a poussé un autre enfant pour passer avant lui sur le toboggan ? Tout le monde vous regarde. Ne le frappez pas parce que vous avez honte. Dites « Maintenant, c''est son tour, après c''est nous » et rappelez-lui la règle d''une voix douce mais ferme. C''est comme ça que ça marche.', title_hi = 'पार्क से निकलने की लड़ाई 🤝', body_hi = 'फिसलपट्टी पर दूसरे बच्चे को धक्का देकर खुद चढ़ना चाहा? सब आपको देख रहे हैं। शर्मिंदा होकर बच्चे को मारिए मत। ‘अभी उसकी बारी है, फिर हम चढ़ेंगे’ कहकर नियम को नरम, पर पक्की आवाज़ में याद दिलाइए। सिस्टम ऐसे ही चलता है।', title_id = 'Perkara pulang dari taman 🤝', body_id = 'Ia mendorong anak lain di perosotan supaya bisa meluncur duluan? Semua orang melihat Anda. Jangan malu lalu memukulnya. Ingatkan aturannya dengan suara lembut tapi tegas: ''Sekarang gilirannya, nanti kita''. Begitulah sistemnya bekerja.', title_ja = '公園での順番争い 🤝', body_ja = 'すべり台でほかの子を押して、自分が先にすべろうとした？みんながあなたを見ている。恥ずかしさからたたいたりしないで。「今はあの子の番、次はわたしたちね」と、やさしく、でもきっぱりとルールを伝えましょう。そうやって順番は回っていきます。', title_ko = '놀이터 다툼 🤝', body_ko = '미끄럼틀에서 다른 아이를 밀치고 자기가 타려고 했나요? 모두가 엄마를 보고 있죠. 창피하다고 아이를 때리지 마세요. ''지금은 저 친구 차례, 그다음에 우리가 타자'' 하며 부드럽지만 단호하게 규칙을 알려 주세요. 원래 그렇게 돌아가는 거예요.', title_nl = 'Gedoe bij het verlaten van het park 🤝', body_nl = 'Duwde hij op de glijbaan een ander kind weg om zelf te gaan? Iedereen kijkt naar jou. Schaam je niet en sla hem niet. Herinner hem met een zachte maar vaste stem aan de regel: ''Nu is hij aan de beurt, daarna gaan wij.'' Zo werkt het systeem.', title_pl = 'Kłótnia przy wyjściu z parku 🤝', body_pl = 'Na zjeżdżalni odepchnął inne dziecko, bo sam chciał zjechać? Wszyscy na ciebie patrzą. Nie bij go ze wstydu. Przypomnij mu zasadę łagodnym, ale stanowczym głosem: „Teraz jego kolej, potem my zjedziemy”. Tak działa system.', title_pt = 'A disputa no parque 🤝', body_pt = 'No escorrega, empurrou outra criança para passar à frente? Toda a gente está a olhar para si. Não fique envergonhada nem lhe bata. Lembre-lhe a regra com voz suave mas firme: "Agora é a vez dele, depois vamos nós". É assim que o sistema funciona.', title_sv = 'Bråket om att lämna parken 🤝', body_sv = 'Knuffade barnet undan ett annat barn i rutschkanan för att åka själv? Alla tittar på dig. Skäms inte och slå inte barnet. Säg ”Nu är det hens tur, sedan åker vi” och påminn om regeln med en mjuk men bestämd röst. Så fungerar systemet.', title_vi = 'Cuộc chiến rời công viên 🤝', body_vi = 'Ở cầu trượt, bé đẩy một bạn khác ra để được trượt trước? Mọi người đang nhìn mẹ. Đừng xấu hổ mà đánh bé. Hãy nhắc quy tắc bằng giọng nhẹ nhàng nhưng dứt khoát: "Giờ đến lượt bạn, sau đó mình trượt." Mọi thứ vận hành như vậy.', title_zh = '公园里的“离场之争” 🤝', body_zh = '在滑梯上推开别的小朋友，想自己先滑？大家都在看着你。别因为难为情就打孩子。用温和但坚定的语气提醒宝宝规则：“现在轮到他了，然后我们再滑。”规则就是这样运作的。' WHERE id = '2a662eb4-1c17-46f1-ad5d-c566286402e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pilla-pilla de buena mañana 🏃‍♂️', body_es = '¿A las 7 de la mañana corre por encima de los sofás? No grites. Deja lo que estás haciendo 2 minutos y únete dando saltos. Entrar en su mundo imaginario es, en realidad, una forma curiosa pero muy eficaz de soltar estrés también para ti.', title_fr = 'Chat perché dès le matin 🏃‍♂️', body_fr = 'À 7 heures du matin, il court sur les canapés ? Ne criez pas. Lâchez tout pendant 2 minutes et rejoignez-le en sautant vous aussi. Entrer dans le monde imaginaire de l''enfant est en fait, pour vous aussi, une façon étrange mais très efficace d''évacuer le stress.', title_hi = 'सुबह-सुबह पकड़म-पकड़ाई 🏃‍♂️', body_hi = 'सुबह 7 बजे सोफ़ों पर दौड़ रहा है? चिल्लाइए मत। अपने काम 2 मिनट के लिए छोड़कर आप भी उछलते हुए साथ आ जाइए। बच्चे की कल्पना की दुनिया में शामिल होना असल में आपके लिए भी तनाव उतारने का एक अनोखा, पर बहुत कारगर तरीका है।', title_id = 'Kejar-kejaran pagi-pagi 🏃‍♂️', body_id = 'Jam 7 pagi ia berlarian di atas sofa? Jangan berteriak. Tinggalkan urusan Anda selama 2 menit dan ikutlah melompat bersamanya. Masuk ke dunia khayal anak sebenarnya juga cara melepas stres yang unik tapi sangat ampuh bagi Anda.', title_ja = '朝からおにごっこ 🏃‍♂️', body_ja = '朝7時にソファの上を走りまわっている？叫ばないで。2分だけ手を止めて、あなたも飛びはねて仲間入りしましょう。子どもの空想の世界に入るのは、あなたにとってもふしぎだけれど、とても効くストレス解消法です。', title_ko = '아침부터 술래잡기 🏃‍♂️', body_ko = '아침 7시에 소파 위를 뛰어다니나요? 소리치지 마세요. 하던 일을 2분만 내려놓고 엄마도 폴짝폴짝 뛰며 함께하세요. 아이의 상상 세계에 들어가는 건 사실 엄마에게도 색다르지만 아주 효과적인 스트레스 해소법이에요.', title_nl = 'Tikkertje in de ochtend 🏃‍♂️', body_nl = 'Rent hij om 7 uur ''s ochtends over de banken? Ga niet schreeuwen. Laat je klusjes 2 minuten liggen en spring gewoon mee. Meegaan in de fantasiewereld van je kind is eigenlijk ook voor jou een vreemde, maar heel effectieve manier om stress kwijt te raken.', title_pl = 'Berek od samego rana 🏃‍♂️', body_pl = 'O 7 rano biega po kanapach? Nie krzycz. Rzuć swoje sprawy na 2 minuty i dołącz do niego, skacząc. Wejście w świat wyobraźni dziecka to tak naprawdę także dla ciebie dziwny, ale bardzo skuteczny sposób na odstresowanie.', title_pt = 'Apanhada logo pela manhã 🏃‍♂️', body_pt = 'Às 7 da manhã corre por cima dos sofás? Não grite. Largue as tarefas por 2 minutos e junte-se a ele aos saltos. Entrar no mundo de fantasia da criança é, na verdade, uma forma estranha, mas muito eficaz, de também libertar o seu stress.', title_sv = 'Kull tidigt på morgonen 🏃‍♂️', body_sv = 'Springer barnet över sofforna klockan 7 på morgonen? Skrik inte. Släpp det du gör i 2 minuter och hoppa med. Att gå in i barnets fantasivärld är faktiskt ett märkligt men mycket effektivt sätt att släppa stress för dig också.', title_vi = 'Đuổi bắt từ sáng sớm 🏃‍♂️', body_vi = '7 giờ sáng bé đã chạy nhảy trên sofa? Đừng quát. Bỏ việc xuống 2 phút và nhảy cùng bé. Hòa vào thế giới tưởng tượng của bé thật ra là một cách xả stress kỳ lạ nhưng rất hiệu quả cho chính mẹ.', title_zh = '一大早的你追我跑 🏃‍♂️', body_zh = '早上7点就在沙发上跑来跑去？别吼。放下手头的事2分钟，你也跳着加入吧。走进孩子的想象世界，其实对你来说也是一种奇妙却非常管用的解压方式。' WHERE id = 'c0dcbfbe-b91a-462c-890d-a8770be19cf3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La solución científica al miedo nocturno 🔦', body_es = '¿Le dan miedo las sombras del dormitorio? No dejes la habitación totalmente a oscuras: pon una lamparita de noche de luz cálida. No altera la liberación de melatonina y además le da seguridad visual y le quita el miedo.', title_fr = 'La solution scientifique aux peurs nocturnes 🔦', body_fr = 'Il a peur des ombres dans sa chambre ? Ne faites pas le noir complet, installez une petite veilleuse à lumière chaude. Elle ne perturbe pas la sécrétion de mélatonine et lui donne un repère visuel rassurant qui efface sa peur.', title_hi = 'रात के डर का वैज्ञानिक हल 🔦', body_hi = 'सोने के कमरे की परछाइयों से डरता है? कमरे में पूरा अंधेरा मत कीजिए, गरम रंग का एक छोटा नाइट लैंप लगाइए। इससे मेलाटोनिन बनने में रुकावट नहीं आती, और उसे दिखता हुआ भरोसा मिलता है जो डर मिटा देता है।', title_id = 'Solusi ilmiah untuk takut malam 🔦', body_id = 'Ia takut pada bayangan di kamar tidur? Jangan buat kamar gelap total, pasang lampu tidur kecil berwarna hangat. Ini tidak mengganggu produksi melatonin, dan memberinya rasa aman secara visual sehingga rasa takutnya hilang.', title_ja = '夜のこわさを科学で解決 🔦', body_ja = '寝室の影がこわい？部屋を真っ暗にせず、暖色の小さな常夜灯を置きましょう。メラトニンの分泌をさまたげず、目で見て安心できるので、こわさが消えていきます。', title_ko = '밤의 두려움을 위한 과학적 해결책 🔦', body_ko = '침실의 그림자를 무서워하나요? 방을 완전히 깜깜하게 하지 말고 따뜻한 색의 작은 수면등을 켜 두세요. 멜라토닌 분비를 방해하지 않으면서 눈으로 안심하게 해 두려움을 지워 줘요.', title_nl = 'Een wetenschappelijke oplossing voor nachtangst 🔦', body_nl = 'Is hij bang voor de schaduwen in de slaapkamer? Maak de kamer niet helemaal donker, maar zet er een klein nachtlampje met warm licht neer. Dat verstoort de aanmaak van melatonine niet, geeft hem visueel houvast en neemt de angst weg.', title_pl = 'Naukowe rozwiązanie na nocne lęki 🔦', body_pl = 'Boi się cieni w sypialni? Nie zaciemniaj pokoju całkowicie, postaw małą lampkę nocną o ciepłej barwie. Nie zaburza ona wydzielania melatoniny, a jednocześnie daje mu wizualne poczucie bezpieczeństwa i usuwa strach.', title_pt = 'A solução científica para os medos noturnos 🔦', body_pt = 'Tem medo das sombras do quarto? Não deixe o quarto totalmente às escuras: ponha uma pequena luz de presença de cor quente. Não prejudica a produção de melatonina e dá-lhe segurança visual, apagando o medo.', title_sv = 'En vetenskaplig lösning på natträdsla 🔦', body_sv = 'Är barnet rädd för skuggorna i sovrummet? Gör inte rummet helt mörkt, sätt en liten nattlampa med varmt ljus. Den stör inte melatoninet och ger barnet visuell trygghet som suddar ut rädslan.', title_vi = 'Giải pháp khoa học cho nỗi sợ ban đêm 🔦', body_vi = 'Bé sợ những cái bóng trong phòng ngủ? Đừng làm phòng tối hoàn toàn, hãy đặt một chiếc đèn ngủ nhỏ ánh sáng ấm. Cách này vừa không cản trở việc tiết melatonin, vừa cho bé cảm giác an toàn khi nhìn và xóa tan nỗi sợ.', title_zh = '夜晚恐惧的科学解法 🔦', body_zh = '害怕卧室里的影子？别让房间全黑，放一盏暖色的小夜灯。这既不会干扰褪黑素分泌，也能给宝宝视觉上的安全感，赶走恐惧。' WHERE id = 'e41be904-7cb3-4dd6-8966-ea3b375783f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras juega en medio de la habitación, de repente te mira, viene corriendo y se te abraza al cuello. ¡Merecen la pena todas las noches sin dormir y todo el cansancio! Disfruta de la paz profunda y única de este momento y olvídate del caos.', body_fr = 'En jouant au milieu de la pièce, il vous regarde soudain, accourt et se jette à votre cou. Cela vaut toutes les nuits blanches et toute la fatigue ! Savourez la paix profonde et unique de cet instant, oubliez le chaos.', body_hi = 'कमरे के बीच खेलते-खेलते अचानक आपको देखकर दौड़ता हुआ आता है और गले से लिपट जाता है। सारी बिना नींद वाली रातें, सारी थकान इसके लायक थीं! इस पल के गहरे, अनोखे सुकून का मज़ा लीजिए, उस अफ़रा-तफ़री को भूल जाइए।', body_id = 'Sedang bermain di tengah kamar, tiba-tiba ia menatap Anda, berlari, dan memeluk leher Anda. Itu sepadan dengan semua malam tanpa tidur dan rasa lelah! Nikmati ketenangan yang dalam dan istimewa dari momen ini, lupakan kekacauannya.', body_ja = '部屋のまん中で遊んでいたのに、急にあなたを見て走ってきて、首に抱きついてくる。眠れない夜も疲れも、すべて報われる瞬間です！この瞬間がくれる深くて特別な安らぎを味わって、カオスは忘れましょう。', body_ko = '방 한가운데서 놀다가 갑자기 엄마를 보고 달려와 목을 꼭 끌어안나요? 잠 못 이룬 모든 밤과 피로가 이 순간을 위해서였어요! 이 순간이 주는 깊고 특별한 평온을 누리고, 혼란은 잊으세요.', body_nl = 'Hij speelt midden in de kamer, kijkt ineens naar je, rent naar je toe en slaat zijn armen om je nek. Dat is alle slapeloze nachten en vermoeidheid waard! Geniet van de diepe, unieke rust van dit moment en vergeet die chaos.', body_pl = 'Bawiąc się na środku pokoju, nagle na ciebie spogląda, przybiega i obejmuje cię za szyję. To jest warte wszystkich nieprzespanych nocy i zmęczenia! Rozkoszuj się tym głębokim, wyjątkowym spokojem, jaki daje ta chwila, i zapomnij o chaosie.', body_pt = 'A brincar no meio do quarto, olha de repente para si, vem a correr e abraça-se ao seu pescoço. Valeu todas as noites sem dormir e todo o cansaço! Saboreie a calma profunda e única deste momento e esqueça o caos.', body_sv = 'Mitt i leken på golvet tittar barnet plötsligt på dig, springer fram och kramar dig runt halsen. Det är värt alla sömnlösa nätter och all trötthet! Njut av det djupa, unika lugnet som stunden ger och glöm kaoset.', body_vi = 'Đang chơi giữa phòng, bé bỗng nhìn mẹ, chạy đến và ôm chặt lấy cổ mẹ. Đáng giá cho mọi đêm mất ngủ, mọi mệt mỏi! Hãy tận hưởng sự bình yên sâu lắng, duy nhất mà khoảnh khắc này mang lại, và quên đi mớ hỗn loạn.', body_zh = '在房间中间玩着玩着，突然看着你，跑过来搂住你的脖子。所有不眠的夜晚、所有的疲惫都值了！好好享受这一刻带来的深深的、独一无二的平静，忘掉那些混乱吧。' WHERE id = 'b5588608-ef71-4787-b05e-09f4f4f2492a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se escapa de la cama y salta de un lado a otro? Baja la voz del todo de repente. Empieza a hablar muy bajito, en susurros. Para entenderte tendrá que concentrarse físicamente y en 5 minutos su cerebro se cansará y pasará al modo sueño. ¡Pruébalo!', body_fr = 'Il s''échappe du lit et saute partout ? Baissez soudain complètement la voix. Mettez-vous à parler très bas, en chuchotant. Pour vous comprendre, il devra physiquement se concentrer, et son cerveau, fatigué, passera en mode sommeil en 5 minutes. Essayez !', body_hi = 'बिस्तर से भागकर इधर-उधर उछल रहा है? अचानक अपनी आवाज़ पूरी तरह धीमी कर दीजिए। बहुत हल्के से फुसफुसाकर बोलना शुरू कीजिए। आपको समझने के लिए उसे पूरा ध्यान लगाना पड़ेगा और 5 मिनट में दिमाग थककर स्लीप मोड में चला जाएगा। आज़माइए!', body_id = 'Ia kabur dari tempat tidur dan melompat ke sana kemari? Tiba-tiba kecilkan suara Anda sepenuhnya. Mulailah berbicara sangat pelan sambil berbisik. Untuk memahami Anda, ia harus memusatkan perhatian secara fisik, dan dalam 5 menit otaknya lelah dan masuk mode tidur. Coba saja!', body_ja = 'ベッドから逃げてあちこち飛びはねている？急に声をぐっと落として、とても小さなささやき声で話し始めましょう。聞きとろうと体ごと集中するうちに、5分で脳が疲れて睡眠モードに切りかわります。ためしてみて！', body_ko = '침대에서 빠져나와 이리저리 뛰어다니나요? 갑자기 목소리를 완전히 낮추세요. 아주 작게 속삭이며 말하기 시작하면, 엄마 말을 알아들으려 집중하다 5분 만에 머리가 지쳐 수면 모드로 넘어갈 거예요. 해 보세요!', body_nl = 'Ontsnapt hij uit bed en springt hij alle kanten op? Laat je stem ineens helemaal wegzakken. Ga heel zacht fluisterend praten. Om je te verstaan moet hij zich lichamelijk concentreren, en binnen 5 minuten is zijn brein moe en gaat het in slaapstand. Probeer het!', body_pl = 'Ucieka z łóżka i skacze po całym pokoju? Nagle całkiem ścisz głos. Zacznij mówić bardzo cicho, szeptem. Żeby cię zrozumieć, będzie musiał fizycznie skupić uwagę, a jego mózg za 5 minut się zmęczy i przejdzie w tryb snu. Spróbuj!', body_pt = 'Foge da cama e salta de um lado para o outro? Baixe de repente a voz por completo. Comece a falar muito baixinho, em sussurro. Para a perceber, vai ter de se concentrar fisicamente e em 5 minutos o cérebro cansa-se e passa para o modo de sono. Experimente!', body_sv = 'Smiter barnet ur sängen och hoppar runt? Dämpa plötsligt rösten helt. Börja prata väldigt tyst och viskande. Barnet måste fysiskt koncentrera sig för att förstå dig, och inom 5 minuter blir hjärnan trött och går över i sömnläge. Prova!', body_vi = 'Bé trốn khỏi giường và nhảy khắp nơi? Hãy bất ngờ hạ giọng hoàn toàn. Bắt đầu nói thì thầm thật nhỏ. Để hiểu mẹ, bé phải tập trung cao độ và 5 phút sau não bé sẽ mệt, chuyển sang chế độ ngủ. Thử xem!', body_zh = '从床上跑下来，到处跳来跳去？突然把声音完全压低。用很轻很轻的悄悄话说话。为了听懂你，宝宝不得不集中注意力，大脑5分钟就会累了，进入睡眠模式。试试吧！' WHERE id = 'e2ac4132-1e14-42d5-a828-9c40ffb00179' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ilusión de las mamás de Instagram 📱', body_es = '¿Te has desanimado al abrir Instagram y ver las casas ordenadas y los niños listos de todo el mundo? ¡Borra esa app! Entra en la Comunidad Anacan. Lee las historias de mamás reales con la casa desordenada como la tuya y peques cabezotas.', title_fr = 'L''illusion des mamans d''Instagram 📱', body_fr = 'Vous vous êtes découragée en voyant sur Instagram les maisons bien rangées et les enfants sages de tout le monde ? Supprimez cette appli ! Rejoignez la Communauté Anacan. Lisez les histoires de vraies mamans dont la maison est en désordre comme la vôtre et l''enfant têtu.', title_hi = 'इंस्टाग्राम वाली माँओं का भ्रम 📱', body_hi = 'इंस्टाग्राम खोलते ही सबके सजे-सँवरे घर और समझदार बच्चे देखकर हिम्मत टूट गई? वह ऐप हटा दीजिए! Anacan कम्युनिटी में आइए। उन असली माँओं की कहानियाँ पढ़िए जिनके घर आपकी तरह बिखरे हैं और बच्चे ज़िद्दी हैं।', title_id = 'Ilusi ibu-ibu Instagram 📱', body_id = 'Begitu membuka Instagram, Anda patah semangat melihat rumah rapi dan anak pintar milik orang lain? Hapus aplikasinya! Masuk ke Komunitas Anacan. Baca kisah ibu-ibu nyata yang rumahnya berantakan seperti rumah Anda dan anaknya keras kepala.', title_ja = 'インスタのママたちという幻想 📱', body_ja = 'インスタを開いたら、みんなの整った家やかしこい子どもを見て落ちこんだ？そのアプリは消しちゃいましょう！Anacanコミュニティに入って、あなたと同じように家が散らかり、子どもががんこな、本物のママたちのお話を読みましょう。', title_ko = '인스타그램 엄마들이라는 착각 📱', body_ko = '인스타그램을 열자마자 다들 깔끔한 집과 똑똑한 아이만 보여서 기운 빠졌나요? 그 앱은 지우세요! Anacan 커뮤니티에 들어가 엄마처럼 집이 어질러져 있고 아이가 고집 센 진짜 엄마들의 이야기를 읽어 보세요.', title_nl = 'De illusie van Instagrammama''s 📱', body_nl = 'Werd je op Instagram ontmoedigd door ieders opgeruimde huis en slimme kind? Verwijder die app! Ga naar de Anacan Community. Lees de verhalen van echte mama''s met net zo''n rommelig huis en net zo''n koppig kind als jij.', title_pl = 'Iluzja mam z Instagrama 📱', body_pl = 'Gdy tylko otworzyłaś Instagram i zobaczyłaś wszystkie te schludne domy i mądre dzieci, straciłaś ducha? Usuń tę aplikację! Wejdź do Społeczności Anacan. Poczytaj historie prawdziwych mam, które mają taki sam bałagan w domu jak ty i równie uparte dzieci.', title_pt = 'A ilusão das mães do Instagram 📱', body_pt = 'Mal abriu o Instagram, desanimou ao ver as casas arrumadas e os filhos inteligentes de toda a gente? Apague essa app! Entre na Comunidade Anacan. Leia as histórias de mães reais, com a casa tão desarrumada como a sua e filhos igualmente teimosos.', title_sv = 'Illusionen om Instagrammammor 📱', body_sv = 'Blev du nedslagen av att se allas prydliga hem och smarta barn så fort du öppnade Instagram? Radera appen! Gå in i Anacan Community. Läs berättelser från riktiga mammor vars hem är lika stökiga som ditt och vars barn är envisa.', title_vi = 'Ảo ảnh các bà mẹ Instagram 📱', body_vi = 'Vừa mở Instagram, thấy nhà ai cũng gọn gàng, con ai cũng thông minh, mẹ nản lòng? Xóa ứng dụng đó đi! Hãy vào Cộng đồng Anacan. Đọc câu chuyện của những bà mẹ thật, nhà cũng bừa bộn như nhà mình, con cũng bướng bỉnh.', title_zh = 'Instagram妈妈的幻象 📱', body_zh = '一打开Instagram，看到别人家整洁的家、聪明的孩子，你就灰心了？删掉那个应用！进入Anacan社区。读读那些家里和你一样乱、孩子一样倔的真实妈妈的故事吧。' WHERE id = 'f5be8b0c-0a17-4790-b9b1-73d205d64a76' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirlo sin leer el cuento 🪄', body_es = '¿Esta noche no te queda aliento para leer el cuento? Abre Cuentos inteligentes. Pon de fondo solo los susurros del bosque y el viento. En la oscuridad, escuchad esos sonidos de la naturaleza y descansad los dos del ruido. El cansancio visual desaparecerá al instante.', title_fr = 'L''endormir sans lire de conte 🪄', body_fr = 'Ce soir, vous n''avez pas le souffle pour lire un conte ? Ouvrez les Contes intelligents. Mettez seulement en fond les bruissements de la forêt et le vent. Dans le noir, en écoutant ces sons de la nature, reposez-vous tous les deux du bruit. La fatigue visuelle disparaîtra aussitôt.', title_hi = 'बिना कहानी पढ़े सुलाना 🪄', body_hi = 'आज शाम कहानी पढ़ने की हिम्मत नहीं बची? स्मार्ट कहानियाँ खोलिए। बस सरसराते जंगल और हवा की आवाज़ें बैकग्राउंड में लगाइए। अंधेरे में प्रकृति की वे आवाज़ें सुनते हुए आप दोनों शोर से आराम कीजिए। आँखों की थकान तुरंत उतर जाएगी।', title_id = 'Menidurkan tanpa membacakan dongeng 🪄', body_id = 'Malam ini Anda tidak punya tenaga untuk membacakan dongeng? Buka Dongeng Pintar. Putar saja suara hutan dan angin yang berdesir sebagai latar. Dalam gelap, beristirahatlah berdua dari kebisingan sambil mendengarkan suara alam itu. Kelelahan visual pun langsung hilang.', title_ja = '絵本を読まずに寝かしつけ 🪄', body_ja = '今夜は絵本を読む元気がない？「スマートおはなし」を開いて、ささやくような森と風の音だけを背景に流しましょう。暗やみの中で自然の音を聞きながら、ふたりとも騒音から休んで。目の疲れもすぐにとれます。', title_ko = '동화 읽지 않고 재우기 🪄', body_ko = '오늘 저녁엔 동화 읽을 기운도 없나요? 스마트 동화를 열고 바스락거리는 숲과 바람 소리만 배경으로 틀어 두세요. 어둠 속에서 자연의 소리를 들으며 두 사람 모두 소음에서 벗어나 쉬세요. 눈의 피로도 금세 풀릴 거예요.', title_nl = 'In slaap zonder voorlezen 🪄', body_nl = 'Heb je vanavond geen adem meer om voor te lezen? Open Slimme sprookjes. Zet alleen ruisende bos- en windgeluiden op de achtergrond. Luister samen in het donker naar die natuurgeluiden en rust allebei uit van het lawaai. De visuele vermoeidheid is meteen weg.', title_pl = 'Usypianie bez czytania bajki 🪄', body_pl = 'Dziś wieczorem nie masz siły czytać bajki? Otwórz Mądre bajki. Włącz w tle tylko szum lasu i wiatru. Słuchając w ciemności odgłosów natury, oboje odpocznijcie od hałasu. Zmęczenie wzroku od razu minie.', title_pt = 'Adormecer sem ler a história 🪄', body_pt = 'Esta noite não tem fôlego para ler uma história? Abra as Histórias Inteligentes. Ponha de fundo apenas os sons sussurrados da floresta e do vento. No escuro, a ouvir os sons da natureza, descansem os dois do barulho. O cansaço visual acaba num instante.', title_sv = 'Somna utan att läsa sagan 🪄', body_sv = 'Orkar du inte läsa saga i kväll? Öppna Smarta sagor. Sätt bara på susande skog och vind som bakgrund. Lyssna på naturljuden i mörkret och vila båda två från oljudet. Den visuella tröttheten försvinner direkt.', title_vi = 'Ru ngủ mà không cần đọc truyện 🪄', body_vi = 'Tối nay mẹ không còn hơi để đọc truyện? Hãy mở Truyện cổ tích thông minh. Chỉ cần bật tiếng rừng xào xạc và tiếng gió làm nền. Trong bóng tối, cả hai mẹ con cùng lắng nghe âm thanh thiên nhiên và nghỉ ngơi khỏi tiếng ồn. Sự mệt mỏi thị giác sẽ tan biến ngay.', title_zh = '不讲故事也能哄睡 🪄', body_zh = '今晚没力气讲故事了？打开智慧童话。只放沙沙的森林声和风声当背景。在黑暗中听着这些自然的声音，你们俩都从喧闹中歇一歇。视觉疲劳会立刻消失。' WHERE id = 'add15a56-d6d1-4819-af57-b57688cec0f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escribir la rabia que llevo dentro 📝', body_es = '¿Nadie ve lo cansada que estás en casa y eso te hace explotar? Abre el Diario de ánimo. Escribe ahí todo lo que hoy te ha vuelto loca. Aceptar la emoción y escribirla te ayudará mucho más que sonreír de mentira.', title_fr = 'Écrire la colère qui est en moi 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée à la maison, et ça vous fait exploser ? Ouvrez le Journal d''humeur. Écrivez-y tout ce qui vous a rendue folle aujourd''hui. Accepter l''émotion et l''écrire vous aidera bien plus qu''un sourire forcé.', title_hi = 'अंदर का गुस्सा लिख डालना 📝', body_hi = 'कोई नहीं देखता कि आप घर में कितना थकती हैं, और इससे आप फट पड़ती हैं? मूड डायरी खोलिए। आज जिसने भी आपको पागल किया, सब वहाँ लिख दीजिए। नकली मुस्कान से ज़्यादा भावना को स्वीकार करके लिखना आपकी मदद करेगा।', title_id = 'Menuliskan amarah di dalam diri 📝', body_id = 'Tidak ada yang melihat betapa lelahnya Anda di rumah, dan itu membuat Anda ingin meledak? Buka Buku Harian Suasana Hati. Tulis di sana semua yang membuat Anda kesal hari ini. Menerima dan menuliskan emosi akan jauh lebih membantu daripada tersenyum palsu.', title_ja = '心の中の怒りを書き出す 📝', body_ja = '家でどれだけ疲れているか誰も気づいてくれなくて、爆発しそう？「気分日記」を開きましょう。今日イライラしたことを全部そこに書いて。無理に笑顔をつくるより、気持ちを受けとめて書くほうがずっと助けになります。', title_ko = '속에 쌓인 화를 글로 쓰기 📝', body_ko = '집에서 내가 얼마나 지치는지 아무도 몰라줘서 폭발할 것 같나요? 기분 일기를 열고 오늘 나를 미치게 한 걸 전부 적어 보세요. 억지로 웃는 것보다 감정을 받아들이고 글로 쓰는 게 훨씬 도움이 될 거예요.', title_nl = 'De boosheid van me afschrijven 📝', body_nl = 'Ziet niemand hoe moe je thuis bent en word je daar gek van? Open je Stemmingsdagboek. Schrijf alles op wat je vandaag gek heeft gemaakt. Je emoties accepteren en opschrijven helpt je meer dan een nepglimlach.', title_pl = 'Wypisz złość, która w tobie siedzi 📝', body_pl = 'Nikt nie widzi, jak bardzo męczysz się w domu, i to doprowadza cię do wybuchu? Otwórz Dziennik nastroju. Zapisz tam wszystko, co dziś doprowadzało cię do szału. Przyjęcie emocji i zapisanie ich pomoże ci bardziej niż sztuczny uśmiech.', title_pt = 'Escrever a raiva que trago cá dentro 📝', body_pt = 'Ninguém vê o quanto se cansa em casa e isso fá-la explodir? Abra o Diário de Humor. Escreva lá tudo o que hoje a deixou louca. Aceitar a emoção e escrevê-la vai ajudá-la mais do que sorrir à força.', title_sv = 'Skriv ner ilskan inom dig 📝', body_sv = 'Ingen ser hur trött du blir hemma, och det får dig att explodera? Öppna Humördagboken. Skriv ner allt som gjort dig galen i dag. Att acceptera känslan och skriva ner den hjälper dig mer än ett konstlat leende.', title_vi = 'Viết ra cơn giận trong lòng 📝', body_vi = 'Không ai thấy mẹ ở nhà mệt đến mức nào, và điều đó khiến mẹ muốn bùng nổ? Hãy mở Nhật ký tâm trạng. Viết hết vào đó mọi điều khiến mẹ phát điên hôm nay. Chấp nhận và viết ra cảm xúc sẽ giúp mẹ nhiều hơn là cười gượng.', title_zh = '把心里的火写下来 📝', body_zh = '没人看到你在家有多累，这让你快要爆发了？打开心情日记。把今天让你抓狂的事都写进去。比起假笑，接纳情绪、把它写下来，更能帮到你。' WHERE id = 'b000be1e-116f-4403-b926-fe4428d04231' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Yo lo sé, te lo enseño ☝️', body_es = '¿Viene a explicarte algo que tú ya sabes con una cara muy seria e inteligente? Está poniendo a prueba su inteligencia. Muérdete el labio para no reírte, pero escúchalo muy en serio y dile: «¿De verdad? Muchas gracias». Mima su ego.', title_fr = 'Je sais, je vais t''apprendre ☝️', body_fr = 'Il vient vous expliquer, avec une mine très sérieuse et savante, quelque chose que vous savez déjà ? Il teste son intelligence. Mordez-vous la lèvre pour ne pas rire, mais écoutez-le très sérieusement et dites : « Vraiment ? Merci beaucoup. » Flattez son ego.', title_hi = 'मुझे पता है, तुम्हें भी सिखाता हूँ ☝️', body_hi = 'जो बात आप जानती हैं, वही आकर बड़े गंभीर और समझदार चेहरे से आपको समझाता है? वह अपनी बुद्धि परख रहा है। हँसी रोकने के लिए होंठ दबाइए, पर बड़ी गंभीरता से सुनकर कहिए, ‘सच में? बहुत-बहुत शुक्रिया।’ उसके अहं को सहलाइए।', title_id = 'Aku tahu, aku ajari kamu ya ☝️', body_id = 'Ia datang dan menjelaskan sesuatu yang sudah Anda ketahui dengan wajah sangat serius dan sok pintar? Ia sedang menguji kecerdasannya. Gigit bibir supaya tidak tertawa, tapi dengarkan ia dengan sangat serius dan katakan ''Oh ya? Terima kasih banyak''. Sanjung egonya.', title_ja = 'わたし知ってるよ、教えてあげる ☝️', body_ja = 'あなたが知っていることを、とても真剣でかしこい顔で説明してくれる？自分の知恵をためしているんです。笑わないよう唇をかみつつ、とても真剣に聞いて「本当？ありがとう」と言いましょう。自尊心をくすぐってあげて。', title_ko = '내가 알아, 엄마한테도 알려 줄게 ☝️', body_ko = '엄마가 이미 아는 걸 아주 진지하고 똑똑한 표정으로 설명해 주나요? 자기 지식을 시험하는 중이에요. 웃음을 참으려 입술을 깨물더라도 아주 진지하게 듣고 ''정말? 고마워''라고 말해 주세요. 자존감을 세워 주세요.', title_nl = 'Ik weet het, ik leer het jou ook ☝️', body_nl = 'Legt hij jou met een heel serieus, slim gezicht iets uit wat jij allang weet? Hij test zijn eigen verstand. Bijt op je lip om niet te lachen, luister heel serieus en zeg: ''Echt? Dank je wel!'' Streel zijn ego.', title_pl = 'Ja wiem, to cię nauczę ☝️', body_pl = 'Z bardzo poważną i mądrą miną tłumaczy ci coś, co doskonale wiesz? Sprawdza swoją inteligencję. Przygryź wargę, żeby się nie roześmiać, ale wysłuchaj go z pełną powagą i powiedz: „Naprawdę? Bardzo dziękuję”. Połechtaj jego ego.', title_pt = 'Eu sei, deixa-me ensinar-te ☝️', body_pt = 'Vem explicar-lhe algo que a mãe já sabe, com uma expressão muito séria e inteligente? Está a testar a sua inteligência. Morda o lábio para não se rir, mas ouça-o com toda a seriedade e diga: "A sério? Muito obrigada". Afague-lhe o ego.', title_sv = 'Jag vet, jag ska lära dig ☝️', body_sv = 'Förklarar barnet något du redan vet, med en väldigt allvarlig och klok min? Hen testar sin egen intelligens. Bit dig i läppen för att inte skratta, men lyssna på fullt allvar och säg ”Verkligen? Tack så mycket!” Smeka självkänslan.', title_vi = 'Con biết, để con dạy mẹ ☝️', body_vi = 'Bé đến giải thích cho mẹ một điều mẹ đã biết với vẻ mặt cực kỳ nghiêm túc và thông thái? Bé đang thử trí tuệ của mình. Cắn môi để khỏi bật cười, nhưng hãy lắng nghe thật nghiêm túc và nói: "Thật à? Cảm ơn con nhiều nhé." Hãy vỗ về cái tôi nhỏ của bé.', title_zh = '我知道，我来教你 ☝️', body_zh = '把你本来就知道的事，带着一本正经、很聪明的表情讲给你听？宝宝在测试自己的智慧。咬住嘴唇别笑，非常认真地听完，说：“真的吗？太谢谢你了。”给宝宝的自尊心一点满足。' WHERE id = 'f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inundación en la bañera 🌊', body_es = '¿El baño es una excusa y en realidad ha montado un océano en la bañera para jugar con las olas? Deja que juegue. El ruido del agua y las salpicaduras se llevarán toda esa energía cabezota que no se acaba. Por la noche se meterá en la cama sin oponer resistencia.', title_fr = 'Inondation dans la baignoire 🌊', body_fr = 'Le bain n''est qu''un prétexte : en réalité, il crée un océan et joue avec les vagues ? Laissez-le jouer. Le bruit de l''eau et les éclaboussures emporteront toute cette énergie têtue et inépuisable. Le soir, il ira se coucher sans aucune résistance.', title_hi = 'बाथटब में पानी की बाढ़ 🌊', body_hi = 'नहाना तो बहाना है, असल में टब में समंदर बनाकर लहरों से खेल रहा है? खेलने दीजिए। पानी का शोर और छींटे उसके अंदर की वह खत्म न होने वाली ज़िद्दी ऊर्जा बहा ले जाएँगे। शाम को वह बिना किसी विरोध के बिस्तर पर लेट जाएगा।', title_id = 'Banjir di bak mandi 🌊', body_id = 'Mandi hanya alasan, sebenarnya ia menciptakan lautan di bak dan bermain ombak? Biarkan saja. Suara dan cipratan air akan membasuh energi keras kepala yang tak ada habisnya itu. Malam nanti ia akan berbaring di tempat tidur tanpa perlawanan.', title_ja = 'お風呂で大洪水 🌊', body_ja = 'お風呂は口実で、本当は浴槽に海をつくって波遊び？遊ばせてあげましょう。水の音としぶきが、終わりのないがんこなエネルギーを洗い流してくれます。夜はまったく抵抗せずにベッドに入りますよ。', title_ko = '욕조 속 물난리 🌊', body_ko = '목욕은 핑계고 사실은 욕조에 바다를 만들어 파도 놀이를 하나요? 놀게 두세요. 물소리와 물장구가 속에 쌓인 끝없는 고집 에너지를 씻어 줄 거예요. 저녁엔 아무 저항 없이 침대에 누울 거예요.', title_nl = 'Overstroming in bad 🌊', body_nl = 'Is in bad gaan maar een excuus en maakt hij eigenlijk een oceaan om met de golven te spelen? Laat hem lekker spelen. Het geluid en gespetter van het water spoelt al die eindeloze koppige energie weg. ''s Avonds gaat hij zonder enig verzet in bed liggen.', title_pl = 'Powódź w wannie 🌊', body_pl = 'Kąpiel to tylko pretekst, a w wannie tak naprawdę tworzy ocean i bawi się falami? Niech się bawi. Szum i pluskanie wody zmyją z niego tę niekończącą się upartą energię. Wieczorem położy się do łóżka bez żadnego oporu.', title_pt = 'Inundação na banheira 🌊', body_pt = 'O banho é só uma desculpa e, na verdade, ele cria um oceano na banheira e brinca com as ondas? Deixe-o brincar. O barulho e os salpicos da água vão levar consigo toda aquela energia teimosa e sem fim. À noite vai deitar-se sem resistência nenhuma.', title_sv = 'Översvämning i badkaret 🌊', body_sv = 'Är badet bara en förevändning, och barnet har egentligen skapat ett hav i badkaret och leker med vågorna? Låt hen leka. Vattnets ljud och plask sköljer bort den outtröttliga, envisa energin. På kvällen lägger sig barnet utan minsta motstånd.', title_vi = 'Lũ lụt trong bồn tắm 🌊', body_vi = 'Tắm chỉ là cái cớ, thật ra bé đang tạo cả đại dương trong bồn và chơi với sóng? Cứ để bé chơi. Tiếng nước và những cú té nước sẽ cuốn trôi hết năng lượng bướng bỉnh không ngừng bên trong bé. Tối đến, bé sẽ lên giường mà không phản đối chút nào.', title_zh = '浴缸里发大水 🌊', body_zh = '洗澡只是借口，其实是在浴缸里造了一片海洋，和浪花玩耍？就让宝宝玩吧。哗哗的水声和溅起的水花，会把宝宝身体里那股停不下来的倔强能量冲走。晚上就会毫无抵抗地躺上床。' WHERE id = '5b3e259a-f085-41f9-b9ba-e7ff8789e89c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te ayuda en la cocina 🧑‍🍳', body_es = '¿Mientras estirabas la masa ha venido, ha puesto su silla y quería echar él la harina sí o sí? Si no le dejas, llorará. Dale un bol pequeño de plástico y un poco de harina. La cocina quedará hecha un desastre, pero esa cara seria de chef vale más que tu limpieza.', title_fr = 'Il vous aide en cuisine 🧑‍🍳', body_fr = 'Pendant que vous étaliez la pâte, il a installé sa chaise et voulait absolument verser la farine lui-même ? Si vous refusez, il pleurera. Donnez-lui un petit bol en plastique et un peu de farine. La cuisine sera sens dessus dessous, mais sa mine de chef sérieux vaut bien votre ménage.', title_hi = 'रसोई में आपकी मदद करता है 🧑‍🍳', body_hi = 'आप आटा बेल रही थीं, वह आकर अपनी कुर्सी लगा बैठा और आटा खुद ही डालना चाहता है? मना करेंगी तो रोएगा। उसे एक छोटा प्लास्टिक का कटोरा और थोड़ा आटा दे दीजिए। रसोई गंदी होगी, पर उसके गंभीर शेफ़ वाले चेहरे के आगे आपकी सफ़ाई कुछ भी नहीं।', title_id = 'Ia membantu Anda di dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia datang membawa kursinya dan bersikeras menuang tepung sendiri? Kalau tidak diizinkan, ia akan menangis. Beri ia mangkuk plastik kecil dan sedikit tepung. Dapur akan belepotan, tapi ekspresi koki seriusnya itu sepadan dengan kebersihan Anda.', title_ja = 'キッチンでお手伝い 🧑‍🍳', body_ja = '生地をのばしていると、いすを持ってきて粉を自分で入れたがった？だめと言えば泣いてしまう。小さなプラスチックのボウルと少しの粉を渡しましょう。キッチンは粉だらけになりますが、その真剣なシェフの顔は、掃除の手間に見合う価値があります。', title_ko = '부엌에서 엄마를 도와줘요 🧑‍🍳', body_ko = '반죽을 밀고 있는데 의자를 끌고 와서 꼭 밀가루를 자기가 붓겠다고 하나요? 허락하지 않으면 울 거예요. 작은 플라스틱 그릇과 밀가루를 조금 주세요. 부엌은 엉망이 되겠지만, 그 진지한 꼬마 셰프의 표정은 깨끗한 부엌보다 값져요.', title_nl = 'Hij helpt je in de keuken 🧑‍🍳', body_nl = 'Was je deeg aan het uitrollen en zette hij zijn stoel ernaast om per se zelf de bloem te storten? Laat je het niet toe, dan gaat hij huilen. Geef hem een klein plastic bakje en wat bloem. De keuken wordt een ravage, maar die serieuze koksblik is je schoonmaakwerk waard.', title_pl = 'Pomaga ci w kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, przystawił krzesło i koniecznie chce sam wsypać mąkę? Jeśli nie pozwolisz, będzie płakał. Daj mu małą plastikową miskę i trochę mąki. Kuchnia będzie w mące, ale jego poważna mina kucharza jest warta twojego sprzątania.', title_pt = 'Ajuda-a na cozinha 🧑‍🍳', body_pt = 'Enquanto estendia a massa, ele pôs a cadeira ao seu lado e quis deitar a farinha sozinho? Se não deixar, vai chorar. Dê-lhe uma pequena taça de plástico e um pouco de farinha. A cozinha vai ficar um caos, mas aquela cara séria de cozinheiro vale bem a limpeza.', title_sv = 'Barnet hjälper dig i köket 🧑‍🍳', body_sv = 'Kom barnet och ställde fram sin stol när du kavlade degen och ville absolut hälla i mjölet själv? Om du säger nej blir det gråt. Ge barnet en liten plastskål och lite mjöl. Köket blir nedsölat, men den allvarliga kockminen är värd din städning.', title_vi = 'Bé giúp mẹ trong bếp 🧑‍🍳', body_vi = 'Mẹ đang cán bột thì bé kê ghế lại và nhất định đòi tự đổ bột? Không cho thì bé sẽ khóc. Hãy đưa bé một chiếc bát nhựa nhỏ và ít bột. Căn bếp sẽ ngập bột, nhưng vẻ mặt đầu bếp nghiêm túc ấy đáng giá hơn công dọn dẹp của mẹ.', title_zh = '在厨房给你帮忙 🧑‍🍳', body_zh = '你擀面团时，宝宝搬来椅子，非要自己倒面粉？不让就会哭。给宝宝一个小塑料碗和一点面粉吧。厨房会变得一团糟，但那副认真的小厨师表情，值得你多打扫一次。' WHERE id = '7c552cb2-0d81-4027-8eba-e235f8359b1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quedarse en blanco en medio del súper 🛒', body_es = '¿Te has quedado parada en medio del súper pensando «¿A qué venía yo?»? El cerebro de mamá está de verdad a tope. Abrir la Lista de la compra de la app y confiar en esa memoria digital siempre te salvará de este caos.', title_fr = 'Figée au milieu du supermarché 🛒', body_fr = 'Vous vous êtes arrêtée au milieu du supermarché en vous demandant « Qu''est-ce que je venais acheter ? » ? Le cerveau d''une maman est vraiment surchargé. Ouvrir la Liste de courses de l''application et faire confiance à cette mémoire numérique vous sauvera toujours de ce chaos.', title_hi = 'सुपरमार्केट के बीच में जम जाना 🛒', body_hi = 'सुपरमार्केट के बीच खड़ी होकर सोच में पड़ गईं, ‘मैं क्या लेने आई थी?’ माँ का दिमाग सच में बहुत भरा होता है। ऐप में शॉपिंग लिस्ट खोलकर उस डिजिटल याददाश्त पर भरोसा करना आपको इस अफ़रा-तफ़री से हमेशा बचाएगा।', title_id = 'Terpaku di tengah supermarket 🛒', body_id = 'Anda berdiri di tengah supermarket dan termenung, ''Tadi aku mau beli apa ya?'' Otak seorang ibu memang sangat penuh. Membuka Daftar Belanja di aplikasi dan mengandalkan memori digital itu akan selalu menyelamatkan Anda dari kekacauan ini.', title_ja = 'スーパーのまん中でフリーズ 🛒', body_ja = 'スーパーのまん中で立ち止まって「何を買いに来たんだっけ？」と考えこんだ？ママの頭は本当にいっぱいなんです。アプリの「買い物リスト」を開いて、そのデジタルの記憶にたよれば、いつでもこのカオスから救われます。', title_ko = '마트 한가운데서 멍해지는 순간 🛒', body_ko = '마트 한가운데 서서 ''내가 뭘 사러 왔더라?'' 하고 멍해졌나요? 엄마의 머리는 정말 꽉 차 있거든요. 앱의 쇼핑 목록을 열고 디지털 기억에 맡기면 이런 혼란에서 언제나 구해 줄 거예요.', title_nl = 'Bevroren midden in de supermarkt 🛒', body_nl = 'Sta je midden in de supermarkt te denken: ''Wat kwam ik hier ook alweer halen?'' Een mamabrein zit echt overvol. Open het Boodschappenlijstje in de app en vertrouw op dat digitale geheugen, dan red je je altijd uit deze chaos.', title_pl = 'Zawieszona na środku sklepu 🛒', body_pl = 'Stoisz na środku sklepu i zastanawiasz się: „Po co ja tu przyszłam?”. Mamusiowy mózg naprawdę jest przepełniony. Otwórz Listę zakupów w aplikacji i zaufaj tej cyfrowej pamięci, zawsze uratuje cię z tego chaosu.', title_pt = 'Parada no meio do supermercado 🛒', body_pt = 'Parou no meio do supermercado a pensar "O que é que eu vim cá comprar?"? O cérebro de mãe anda mesmo cheio. Abrir a Lista de Compras da app e confiar nessa memória digital vai salvá-la sempre deste caos.', title_sv = 'Att stelna till mitt i affären 🛒', body_sv = 'Står du mitt i affären och funderar ”Vad var det jag skulle köpa?” Mammahjärnan är verkligen överfull. Att öppna Inköpslistan i appen och lita på det digitala minnet räddar dig alltid ur det här kaoset.', title_vi = 'Đứng hình giữa siêu thị 🛒', body_vi = 'Đứng giữa siêu thị, mẹ ngẩn ra: "Mình định mua gì nhỉ?" Đầu óc người mẹ thật sự đã quá tải. Mở Danh sách mua sắm trong ứng dụng và tin vào "bộ nhớ số" ấy sẽ luôn cứu mẹ khỏi mớ hỗn loạn này.', title_zh = '在超市中间愣住了 🛒', body_zh = '站在超市中间想：“我是来买什么的？”当了妈妈，大脑真的太满了。打开应用里的购物清单，交给这份数字记忆，总能帮你摆脱这种混乱。' WHERE id = '86e3829d-08da-4b37-867c-0faf0ab2fa1c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La etiqueta de la camiseta pica! 🏷️', body_es = '¿No se la quiere poner porque esa etiquetita de atrás se le clava como una aguja? La sensibilidad sensorial de esta edad vuelve loco a cualquiera. No entres a discutir: coge las tijeras, córtala de raíz y cierra esta minicrisis en un segundo.', title_fr = 'L''étiquette du t-shirt pique ! 🏷️', body_fr = 'Il refuse de s''habiller parce que la petite étiquette au dos le pique comme une aiguille ? La sensibilité sensorielle de cet âge rend fou. N''entrez même pas dans la discussion : prenez les ciseaux, coupez-la à la racine et réglez cette mini-crise en une seconde.', title_hi = 'कमीज़ का लेबल चुभ रहा है! 🏷️', body_hi = 'कपड़े नहीं पहनेगा, क्योंकि पीछे का वह छोटा लेबल उसे सुई की तरह चुभता है? इस उम्र की संवेदी संवेदनशीलता किसी को भी पागल कर दे। बहस में मत पड़िए, कैंची उठाइए, जड़ से काट दीजिए और यह छोटा संकट सेकंडों में खत्म कीजिए।', title_id = 'Label bajunya menusuk! 🏷️', body_id = 'Ia tidak mau berpakaian karena label kecil di belakang bajunya terasa menusuk seperti jarum? Kepekaan sensorik usia ini memang bisa bikin pusing. Jangan berdebat, ambil gunting, potong labelnya sampai habis, dan tutup krisis kecil ini dalam sekejap.', title_ja = 'シャツのタグがチクチク！ 🏷️', body_ja = '背中の小さなタグが針のように刺さるから、着ないと言う？この年齢の感覚の敏感さには参りますよね。言い合いはせずに、はさみでタグを根元から切って、このミニ危機をすぐに解決しましょう。', title_ko = '옷 라벨이 따가워! 🏷️', body_ko = '뒤에 달린 작은 라벨이 바늘처럼 찔러서 안 입겠다고 하나요? 이 나이의 감각 예민함은 정말 사람을 미치게 하죠. 다투지 말고 가위로 라벨을 싹 잘라 이 작은 위기를 바로 끝내세요.', title_nl = 'Dat labeltje prikt! 🏷️', body_nl = 'Wil hij zich niet aankleden omdat dat kleine labeltje achterin prikt als een naald? De zintuiglijke gevoeligheid op deze leeftijd kan je gek maken. Ga niet in discussie, pak de schaar, knip het eraf en los deze minicrisis in een seconde op.', title_pl = 'Metka w koszulce gryzie! 🏷️', body_pl = 'Nie założy, bo ta mała metka z tyłu kłuje go jak igła? Wrażliwość sensoryczna w tym wieku potrafi doprowadzić do szału. Nie wchodź w dyskusję, weź nożyczki, odetnij ją u nasady i zamknij ten mini kryzys w sekundę.', title_pt = 'A etiqueta da camisola pica! 🏷️', body_pt = 'Não se quer vestir porque aquela etiquetazinha atrás o pica como uma agulha? A sensibilidade sensorial desta idade dá com qualquer um em doido. Não discuta: pegue na tesoura, corte-a pela raiz e resolva esta mini-crise num segundo.', title_sv = 'Lappen på tröjan sticks! 🏷️', body_sv = 'Barnet vägrar ta på sig tröjan för att den lilla lappen i nacken sticks som en nål? Den sensoriska känsligheten i den här åldern kan göra vem som helst galen. Gå inte in i något gräl, ta saxen, klipp bort lappen helt och avsluta minikrisen på en sekund.', title_vi = 'Mác áo cấn quá! 🏷️', body_vi = 'Bé không chịu mặc áo vì cái mác nhỏ sau lưng cấn như kim châm? Sự nhạy cảm giác quan ở tuổi này có thể khiến mẹ phát điên. Đừng tranh cãi, cầm kéo cắt tận gốc và kết thúc "khủng hoảng mini" này trong vài giây.', title_zh = '衣服标签扎人！🏷️', body_zh = '不肯穿，因为背后那个小标签像针一样扎？这个年龄的感官敏感真能把人逼疯。别争了，拿起剪刀从根部剪掉，几秒钟就化解这场小危机。' WHERE id = '202773be-9378-4cfa-915c-7cbc9e98cdc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento de silencio perfecto 🛋️', body_es = '¿Está tan metido en sus puzles que de repente hay silencio en casa? No sospeches, sírvete un café ya mismo. Esos minutos raros y de oro no los gastes en limpiar ni en la ropa, sino en descansar el alma y mirar al techo. No eres un robot.', title_fr = 'Un moment de silence parfait 🛋️', body_fr = 'Il est tellement absorbé par ses puzzles qu''un silence soudain règne dans la maison ? Ne vous méfiez pas, servez-vous tout de suite un café. Ces minutes rares et précieuses, ne les dépensez pas en ménage ou en linge, mais à reposer votre âme et à contempler le plafond. Vous n''êtes pas un robot.', title_hi = 'खामोशी का परफ़ेक्ट पल 🛋️', body_hi = 'अपनी पज़ल से इतनी गहराई से खेल रहा है कि घर में अचानक सन्नाटा छा गया? शक मत कीजिए, फ़ौरन अपने लिए कॉफ़ी डालिए। ये दुर्लभ, सुनहरे मिनट सफ़ाई या कपड़ों पर नहीं, अपने मन को आराम देने और छत निहारने में लगाइए। आप रोबोट नहीं हैं।', title_id = 'Momen hening yang sempurna 🛋️', body_id = 'Ia begitu asyik bermain puzzle sampai rumah tiba-tiba hening? Jangan curiga, segera tuang kopi untuk diri sendiri. Pakai menit-menit langka dan berharga itu bukan untuk bersih-bersih atau cucian, tapi untuk mengistirahatkan jiwa dan memandangi langit-langit. Anda bukan robot.', title_ja = '完璧な静けさのひととき 🛋️', body_ja = 'パズルに夢中で、家が急に静かになった？疑わないで、すぐに自分にコーヒーを入れましょう。その貴重な黄金の数分間は、掃除や洗濯ではなく、心を休めて天井をながめるために使って。あなたはロボットではありません。', title_ko = '완벽한 고요의 순간 🛋️', body_ko = '퍼즐에 푹 빠져 집이 갑자기 조용해졌나요? 의심하지 말고 바로 커피 한 잔 따르세요. 이 귀한 황금 같은 몇 분은 청소나 빨래가 아니라 마음을 쉬고 천장을 바라보는 데 쓰세요. 엄마는 로봇이 아니에요.', title_nl = 'Het perfecte stille moment 🛋️', body_nl = 'Speelt hij zo geconcentreerd met zijn puzzels dat het ineens stil is in huis? Wees niet achterdochtig, schenk jezelf meteen een kop koffie in. Besteed die zeldzame, gouden minuten niet aan schoonmaken of de was, maar aan rust voor je ziel, naar het plafond staren. Je bent geen robot.', title_pl = 'Chwila idealnej ciszy 🛋️', body_pl = 'Tak bardzo pochłonęły go puzzle, że w domu nagle zrobiło się cicho? Nie podejrzewaj niczego, od razu nalej sobie kawy. Te rzadkie, złote minuty przeznacz nie na sprzątanie czy pranie, tylko na odpoczynek dla duszy i patrzenie w sufit. Nie jesteś robotem.', title_pt = 'O momento perfeito de silêncio 🛋️', body_pt = 'Está tão concentrado nos puzzles que caiu de repente o silêncio em casa? Não desconfie, sirva-se já de um café. Gaste esses minutos raros e de ouro não em limpezas ou roupa, mas a descansar a alma e a olhar para o teto. Não é um robô.', title_sv = 'En stund av perfekt tystnad 🛋️', body_sv = 'Leker barnet så djupt med pusslen att det plötsligt blev tyst hemma? Bli inte misstänksam, häll genast upp en kopp kaffe åt dig. Lägg de sällsynta, gyllene minuterna på att vila själen och stirra i taket, inte på städning eller tvätt. Du är ingen robot.', title_vi = 'Khoảnh khắc yên lặng hoàn hảo 🛋️', body_vi = 'Bé mải mê ghép hình đến mức cả nhà bỗng im phăng phắc? Đừng nghi ngờ, rót ngay cho mình một tách cà phê. Hãy dành những phút vàng hiếm hoi ấy không phải cho dọn dẹp hay quần áo, mà để tâm hồn nghỉ ngơi, ngắm trần nhà. Mẹ đâu phải người máy.', title_zh = '完美的安静时刻 🛋️', body_zh = '拼图拼得那么投入，家里突然安静下来了？别怀疑，马上给自己倒杯咖啡。把这难得的黄金几分钟，用来放松心灵、发发呆看看天花板，而不是打扫或洗衣服。你不是机器人。' WHERE id = '65b5e1a3-f9ad-4e00-a2af-7ae096f9121d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un grito repentino a medianoche 😭', body_es = '¿Se ha despertado de noche llorando con los ojos cerrados y no te oye? Pasa por el Análisis del llanto: son terrores nocturnos. Intenta no despertarlo, solo quédate a su lado, cógele la mano y acarícialo. Se calmará solo y volverá a dormirse profundamente.', title_fr = 'Un cri soudain en pleine nuit 😭', body_fr = 'Il s''est réveillé la nuit en pleurant, les yeux fermés, et ne vous entend pas ? Vérifiez avec l''Analyse des pleurs : c''est une terreur nocturne. N''essayez pas de le réveiller, restez simplement près de lui, tenez-lui la main et caressez-le. Il se calmera de lui-même et retombera dans un sommeil profond.', title_hi = 'आधी रात को अचानक चीख 😭', body_hi = 'रात को आँखें बंद किए रोते हुए जागा और आपकी बात नहीं सुन रहा? क्राइंग एनालिसिस बताता है: यह नाइट टेरर है। जगाने की कोशिश मत कीजिए, बस पास रहिए, हाथ थामकर सहलाइए। वह अपने आप शांत होकर फिर गहरी नींद में चला जाएगा।', title_id = 'Jeritan tiba-tiba di tengah malam 😭', body_id = 'Malam-malam ia terbangun menangis dengan mata terpejam dan tidak mendengar Anda? Periksa dengan Analisis Tangisan; ini teror tidur (night terror). Jangan coba membangunkannya, cukup berada di sampingnya, pegang dan usap tangannya. Ia akan tenang sendiri dan kembali tidur nyenyak.', title_ja = '真夜中の突然の叫び 😭', body_ja = '夜中に目を閉じたまま泣いて起き、あなたの声が聞こえていない？「泣き声分析」で確かめてみましょう。これは夜驚症です。起こそうとせず、ただそばにいて手をにぎり、なでてあげて。自然に落ち着いて、また深い眠りに戻ります。', title_ko = '한밤중 갑작스러운 비명 😭', body_ko = '밤에 눈을 감은 채 울며 깨어나 엄마 말을 듣지 못하나요? 울음 분석은 넘기세요, 이건 야경증이에요. 깨우려 하지 말고 곁에서 손을 잡고 쓰다듬어 주세요. 스스로 진정하고 다시 깊이 잠들 거예요.', title_nl = 'Plots gegil midden in de nacht 😭', body_nl = 'Werd hij ''s nachts huilend wakker met zijn ogen dicht en hoort hij je niet? Laat het door Huilanalyse gaan; dit is nachtangst (pavor nocturnus). Probeer hem niet wakker te maken, blijf gewoon bij hem, pak zijn hand en aai hem. Hij kalmeert vanzelf en valt weer diep in slaap.', title_pl = 'Nagły krzyk w środku nocy 😭', body_pl = 'W nocy obudził się z płaczem, z zamkniętymi oczami, i cię nie słyszy? Sprawdź to w Analizie płaczu; to lęk nocny. Nie próbuj go budzić, po prostu bądź obok, trzymaj go za rękę i głaszcz. Sam się uspokoi i znów zapadnie w głęboki sen.', title_pt = 'Gritos repentinos a meio da noite 😭', body_pt = 'Acordou de noite a chorar, de olhos fechados, e não a ouve? Confirme com a Análise do Choro: é terror noturno. Tente não o acordar, fique só ao lado dele, pegue-lhe na mão e faça-lhe festas. Vai acalmar-se sozinho e voltar a adormecer profundamente.', title_sv = 'Ett plötsligt skrik mitt i natten 😭', body_sv = 'Vaknade barnet gråtande på natten med slutna ögon och hör dig inte? Kontrollera med Gråtanalys; det är nattskräck. Försök inte väcka barnet, stå bara bredvid, håll handen och stryk lätt. Barnet lugnar sig av sig självt och somnar djupt igen.', title_vi = 'Tiếng hét bất ngờ lúc nửa đêm 😭', body_vi = 'Ban đêm bé khóc thét, mắt vẫn nhắm và không nghe thấy mẹ? Hãy kiểm tra bằng Phân tích tiếng khóc; đây là hoảng sợ khi ngủ. Cố đừng đánh thức bé, chỉ cần ở bên, nắm tay và vuốt ve. Bé sẽ tự bình tĩnh lại và chìm vào giấc ngủ sâu.', title_zh = '半夜突然尖叫 😭', body_zh = '半夜闭着眼睛哭醒，好像听不见你说话？用哭声分析看看：这是夜惊。尽量别叫醒宝宝，只要陪在身边，握着小手轻轻抚摸。宝宝会自己平静下来，重新进入深睡。' WHERE id = 'a86a31ee-9e29-4f41-aa7c-1edc94992d88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga las luces, que llegue el sueño 🌙', body_es = 'Para que se duerma antes, apaga todas las pantallas de tele y móvil de la habitación 1 hora antes de dormir. La melatonina se libera rápido en un ambiente oscuro: deja que el proceso natural trabaje por ti.', title_fr = 'Éteignez les lumières, que le sommeil vienne 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez tous les écrans de télé et de téléphone de la chambre 1 heure avant le coucher. La mélatonine est sécrétée rapidement dans un environnement sombre : laissez le processus naturel travailler à votre place.', title_hi = 'लाइटें बंद, नींद आए 🌙', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी टीवी और फ़ोन की स्क्रीनें बंद कर दीजिए। मेलाटोनिन धुँधले माहौल में तेज़ी से बनता है, प्राकृतिक प्रक्रिया को आपकी जगह काम करने दीजिए।', title_id = 'Matikan lampu, biarkan kantuk datang 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua layar TV dan ponsel di kamar 1 jam sebelum tidur. Melatonin diproduksi dengan cepat di lingkungan yang redup, biarkan proses alami bekerja untuk Anda.', title_ja = '明かりを消して、眠りを呼ぼう 🌙', body_ja = '早く寝つけるように、寝る1時間前に部屋のテレビやスマホの画面をすべて消しましょう。メラトニンは暗い環境でこそすばやく分泌されます。自然の流れにまかせて、あなたのかわりに働いてもらいましょう。', title_ko = '불을 끄면 잠이 와요 🌙', body_ko = '더 빨리 잠들게 하려면 자기 1시간 전에 방 안의 TV와 휴대폰 화면을 모두 끄세요. 멜라토닌은 어두운 환경에서 빠르게 분비돼요. 자연스러운 과정이 엄마 대신 일하게 두세요.', title_nl = 'Licht uit, tijd voor slaap 🌙', body_nl = 'Zet een uur voor het slapengaan alle tv- en telefoonschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine wordt in een donkere omgeving snel aangemaakt, laat het natuurlijke proces het werk voor je doen.', title_pl = 'Zgaś światło, niech przyjdzie sen 🌙', body_pl = 'Żeby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie ekrany telewizora i telefonu. Melatonina szybko wydziela się w ciemnym otoczeniu, niech naturalny proces popracuje za ciebie.', title_pt = 'Apague as luzes e o sono vem 🌙', body_pt = 'Para que adormeça mais depressa, desligue 1 hora antes de dormir todos os ecrãs de televisão e telemóvel do quarto. A melatonina é produzida rapidamente num ambiente escuro: deixe o processo natural trabalhar por si.', title_sv = 'Släck lamporna, låt sömnen komma 🌙', body_sv = 'För att barnet ska somna snabbare, stäng av alla tv- och telefonskärmar i rummet en timme före läggdags. Melatonin utsöndras snabbt i en mörk miljö, låt den naturliga processen arbeta åt dig.', title_vi = 'Tắt đèn, giấc ngủ đến 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt hết TV và màn hình điện thoại trong phòng 1 tiếng trước giờ ngủ. Melatonin được tiết ra nhanh trong môi trường tối, hãy để quá trình tự nhiên làm việc thay mẹ.', title_zh = '关灯，睡意就来 🌙', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有电视和手机屏幕。褪黑素在昏暗的环境里才会快速分泌，让自然的过程替你工作吧。' WHERE id = '2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tienes una carta de Anacan 💌', body_es = 'Verduras escondidas con Recetas saludables, lágrimas volcadas en el Diario de ánimo y momentos de agotamiento... En estos 4 años te has convertido en experta en la profesión más difícil del mundo. Ya eres una heroína que no necesita ninguna app y que maneja el caos con su propia intuición. Nosotros solo éramos la guía en segundo plano: ¡el trabajo de verdad lo hacías tú!', title_fr = 'Une lettre d''Anacan pour vous 💌', body_fr = 'Les légumes cachés grâce aux Recettes saines, les larmes déversées dans le Journal d''humeur et les moments d''épuisement... En 4 ans, vous êtes devenue experte dans le métier le plus difficile du monde. Vous êtes désormais une héroïne qui n''a besoin d''aucune application et qui gère le chaos avec sa propre intuition. Nous n''étions qu''un guide en arrière-plan, c''est vous qui avez fait l''essentiel !', title_hi = 'Anacan की ओर से आपके लिए एक चिट्ठी 💌', body_hi = 'सेहतमंद रेसिपी से छिपाई गई सब्ज़ियाँ, मूड डायरी में बहे आँसू और थककर चूर होने के पल... इन 4 सालों में आप दुनिया के सबसे मुश्किल पेशे में माहिर हो गईं। अब आप वह हीरो हैं जिसे किसी ऐप की ज़रूरत नहीं, जो अपनी अंतर्ज्ञान से अफ़रा-तफ़री संभालती है। हम तो बस पीछे खड़े एक गाइड थे, असली काम आपने किया!', title_id = 'Ada surat dari Anacan untuk Anda 💌', body_id = 'Sayur yang disembunyikan berkat Resep Sehat, air mata dan momen kehabisan tenaga yang tertuang di Buku Harian Suasana Hati... Dalam 4 tahun ini Anda telah menguasai profesi tersulit di dunia. Kini Anda adalah pahlawan yang tak lagi butuh aplikasi apa pun dan mengelola kekacauan dengan intuisi Anda sendiri. Kami hanya pemandu di belakang layar, Andalah yang melakukan pekerjaan utamanya!', title_ja = 'Anacanからあなたへの手紙 💌', body_ja = '「ヘルシーレシピ」でこっそり隠した野菜、「気分日記」にこぼした涙と、燃えつきそうになった瞬間…。この4年間で、あなたは世界でいちばん大変な仕事の達人になりました。あなたはもう、どんなアプリもいらない、自分の直感でカオスを乗りこなすヒーローです。わたしたちは背景で見守るガイドにすぎず、本当にがんばったのはあなたでした！', title_ko = 'Anacan이 보내는 편지 💌', body_ko = '건강한 레시피로 숨긴 채소들, 기분 일기에 쏟아 낸 눈물과 지쳐 버린 순간들... 지난 4년 동안 엄마는 세상에서 가장 어려운 직업의 달인이 되었어요. 이제 어떤 앱도 필요 없이 자신의 직감으로 혼란을 다스리는 영웅이에요. 우리는 그저 뒤에서 길을 안내했을 뿐, 진짜 일을 해낸 건 엄마예요!', title_nl = 'Een brief van Anacan voor jou 💌', body_nl = 'Groenten verstopt met Gezonde recepten, tranen in je Stemmingsdagboek en momenten van uitputting... In deze 4 jaar ben je meester geworden in het moeilijkste beroep ter wereld. Je bent nu een heldin die geen enkele app meer nodig heeft en de chaos op haar eigen intuïtie bestuurt. Wij waren alleen een gids op de achtergrond, het echte werk deed jij!', title_pl = 'Masz list od Anacan 💌', body_pl = 'Warzywa ukryte dzięki Zdrowym przepisom, łzy wylane w Dzienniku nastroju i chwile wyczerpania... Przez te 4 lata opanowałaś najtrudniejszy zawód na świecie. Jesteś bohaterką, która nie potrzebuje już żadnej aplikacji i panuje nad chaosem dzięki własnej intuicji. My byliśmy tylko przewodnikiem w tle, a całą główną pracę wykonałaś ty!', title_pt = 'Tem uma carta da Anacan 💌', body_pt = 'Legumes escondidos com as Receitas Saudáveis, lágrimas derramadas no Diário de Humor e momentos de esgotamento... Nestes 4 anos tornou-se mestre na profissão mais difícil do mundo. Já é uma heroína que não precisa de nenhuma app e que gere o caos com a sua própria intuição. Nós fomos apenas um guia em segundo plano, quem fez o trabalho a sério foi você!', title_sv = 'Ett brev till dig från Anacan 💌', body_sv = 'Grönsaker gömda med Hälsosamma recept, tårar och stunder av utmattning utskrivna i Humördagboken... Under de här 4 åren har du blivit mästare i världens svåraste yrke. Nu är du en hjälte som inte behöver någon app, som styr kaoset med sin egen intuition. Vi var bara guiden i bakgrunden, det stora jobbet gjorde du!', title_vi = 'Anacan gửi mẹ một lá thư 💌', body_vi = 'Những món rau được giấu khéo nhờ Công thức lành mạnh, những giọt nước mắt trút vào Nhật ký tâm trạng và những lúc kiệt sức... Trong 4 năm qua, mẹ đã thành thạo nghề khó nhất thế giới. Giờ mẹ là người hùng không cần đến bất kỳ ứng dụng nào, tự điều khiển mọi hỗn loạn bằng trực giác của mình. Chúng tôi chỉ là người dẫn đường phía sau, người làm nên tất cả chính là mẹ!', title_zh = 'Anacan给你的一封信 💌', body_zh = '用健康食谱藏起来的蔬菜，倒进心情日记的眼泪和那些被掏空的时刻……这4年里，你在世界上最难的职业里成为了高手。你已经是不再需要任何应用、凭自己的直觉驾驭混乱的英雄。我们只是背景里的向导，真正完成这一切的，是你！' WHERE id = '5430bad3-c2db-4b2e-bb46-e51168e8dd91' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Día {milestone_days}: ¡Lo hemos conseguido! 🚀', body_es = 'Te despiertas por la mañana y lo miras... ¡Ya tiene 4 años! Durante exactamente {milestone_days} días has criado a esta personita luchando contra la falta de sueño, las crisis y las cabezonerías. En estos años no solo has creado un niño, sino también, dentro de ti, una mamá nueva, fuerte e invencible. Hoy no hay reglas: solo abrázalo y mira con orgullo este milagro que has construido.', title_fr = 'Jour {milestone_days} : on a réussi ! 🚀', body_fr = 'Vous vous réveillez le matin et vous le regardez... Il a déjà 4 ans ! Depuis exactement {milestone_days} jours, vous élevez ce petit être en luttant contre le manque de sommeil, les crises et les caprices. Pendant ces années, vous n''avez pas seulement fait grandir un enfant, vous avez aussi fait naître en vous une nouvelle maman, forte et invincible. Aujourd''hui, pas de règles : serrez-le simplement dans vos bras et contemplez avec fierté ce miracle que vous avez construit.', title_hi = 'दिन {milestone_days}: हमने कर दिखाया! 🚀', body_hi = 'सुबह उठकर उसे देखती हैं... वह अब पूरे 4 साल का है! ठीक {milestone_days} दिनों से आप नींद की कमी, संकटों और ज़िद से लड़ते हुए इस नन्हे इंसान को बड़ा कर रही हैं। इन सालों में आपने सिर्फ़ एक बच्चा नहीं, अपने अंदर एक मज़बूत, अटूट नई माँ भी रची है। आज कोई नियम नहीं, बस उसे गले लगाइए और अपने बनाए इस चमत्कार को गर्व से देखिए।', title_id = 'Hari ke-{milestone_days}: Kita berhasil! 🚀', body_id = 'Anda bangun pagi dan memandanginya... Kini ia genap berusia 4 tahun! Tepat {milestone_days} hari Anda membesarkan manusia kecil ini sambil berjuang melawan kurang tidur, krisis, dan keras kepala. Selama tahun-tahun ini Anda bukan hanya membesarkan seorang anak, tapi juga melahirkan sosok ibu baru yang kuat dan tak terkalahkan di dalam diri Anda. Hari ini tidak ada aturan, cukup peluk ia dan pandangilah dengan bangga keajaiban yang Anda bangun sendiri.', title_ja = '{milestone_days}日目：やりとげました！ 🚀', body_ja = '朝起きてこの子を見ると…もうすっかり4歳！ちょうど{milestone_days}日間、寝不足やかんしゃく、がんこさと向き合いながら、この小さな人を育ててきました。この数年で、あなたはひとりの子どもだけでなく、自分の中に強くてくじけない新しいママを生み出したのです。今日はルールなし。ただ抱きしめて、自分が築いたこの奇跡を誇りをもって眺めましょう。', title_ko = '{milestone_days}일째: 우리가 해냈어요! 🚀', body_ko = '아침에 눈을 떠 아이를 바라보면... 벌써 꼭 4살이에요! 꼬박 {milestone_days}일 동안 잠 못 드는 밤과 위기, 고집과 싸우며 이 작은 사람을 키워 냈어요. 이 시간 동안 엄마는 아이 한 명만이 아니라, 내면에 강하고 꺾이지 않는 새로운 엄마도 만들어 냈어요. 오늘은 아무 규칙도 없어요. 그저 아이를 안아 주고, 엄마가 일궈 낸 이 기적을 자랑스럽게 바라보세요.', title_nl = 'Dag {milestone_days}: we hebben het gered! 🚀', body_nl = 'Je wordt wakker en kijkt naar hem... Hij is al 4 jaar! Precies {milestone_days} dagen lang heb je deze kleine mens grootgebracht, in strijd met slapeloosheid, crisissen en koppigheid. In deze jaren heb je niet alleen een kind laten opgroeien, maar ook in jezelf een sterke, onverwoestbare nieuwe mama gevormd. Vandaag zijn er geen regels, knuffel hem gewoon en kijk trots naar dit wonder dat je zelf hebt gebouwd.', title_pl = 'Dzień {milestone_days}: Udało nam się! 🚀', body_pl = 'Budzisz się rano i patrzysz na nie... Ma już równe 4 lata! Przez całe {milestone_days} dni, walcząc z niewyspaniem, kryzysami i uporem, wychowywałaś tego małego człowieka. Przez te lata stworzyłaś nie tylko dziecko, ale też w sobie nową, silną i niezłomną mamę. Dziś nie ma żadnych zasad, po prostu je przytul i z dumą popatrz na ten cud, który zbudowałaś.', title_pt = 'Dia {milestone_days}: conseguimos! 🚀', body_pt = 'Acorda de manhã e olha para ele... Já tem 4 anos feitos! Há exatamente {milestone_days} dias que cria esta pequena pessoa, a lutar contra noites sem dormir, crises e teimosias. Ao longo destes anos, não criou apenas uma criança: criou também dentro de si uma mãe nova, forte e invencível. Hoje não há regras, abrace-o e olhe com orgulho para este milagre que construiu.', title_sv = 'Dag {milestone_days}: Vi klarade det! 🚀', body_sv = 'Du vaknar på morgonen och tittar på barnet... Hen är redan hela 4 år! I precis {milestone_days} dagar har du kämpat mot sömnlöshet, kriser och envishet och fostrat den här lilla människan. Under de här åren har du inte bara skapat ett barn, utan också en stark, obesegrad ny mamma inom dig. I dag finns det inga regler, krama bara barnet och titta stolt på miraklet du själv har byggt.', title_vi = 'Ngày thứ {milestone_days}: Chúng ta đã làm được! 🚀', body_vi = 'Sáng nay thức dậy, mẹ nhìn bé... Bé đã tròn 4 tuổi rồi! Suốt đúng {milestone_days} ngày, mẹ đã vượt qua những đêm mất ngủ, những cơn ăn vạ, những lần bướng bỉnh để nuôi lớn con người bé nhỏ này. Trong những năm qua, mẹ không chỉ nuôi lớn một đứa trẻ, mà còn tạo nên trong chính mình một người mẹ mới mạnh mẽ, không gì khuất phục được. Hôm nay không có quy tắc nào cả, chỉ cần ôm bé thật chặt và tự hào ngắm nhìn phép màu do chính tay mẹ tạo nên.', title_zh = '第{milestone_days}天：我们做到了！🚀', body_zh = '早上醒来，你看着宝宝……宝宝已经整整4岁了！整整{milestone_days}天，你和失眠、崩溃、倔强斗争着，把这个小小的人养大。这些年里，你创造的不只是一个孩子，还有内心那个强大、不可战胜的全新的妈妈。今天没有任何规矩，只要抱紧宝宝，骄傲地看着你亲手创造的这个奇迹。' WHERE id = '7c7b74a0-c6ab-409c-babd-0085e345da09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La última notificación, el último silencio 🌌', body_es = 'Se ha dormido. Apaga las luces. Esta es la última notificación que te llega de la app. Durante {milestone_days} días, cuando estabas cansada, cuando llorabas y cuando te sentías acorralada, intentamos entenderte y estar a tu lado en silencio. Ahora deja el móvil a un lado. Eres perfecta, eres suficiente. La maravillosa historia que viene a partir de ahora la escribirás tú, por ti misma. Ha sido un honor recorrer este camino contigo. ¡Hasta pronto, Anacan! ❤️', title_fr = 'Dernière notification, dernier silence 🌌', body_fr = 'Il dort. Éteignez la lumière. C''est la dernière notification que l''application vous envoie. Pendant {milestone_days} jours, quand vous étiez fatiguée, quand vous pleuriez et quand vous vous sentiez acculée, nous avons essayé de vous comprendre et d''être à vos côtés en silence. Maintenant, posez votre téléphone. Vous êtes parfaite, vous êtes suffisante. La suite de cette magnifique histoire, c''est vous qui l''écrirez, seule. Ce fut un honneur de faire ce chemin avec vous. À bientôt, Anacan ! ❤️', title_hi = 'आखिरी नोटिफ़िकेशन, आखिरी खामोशी 🌌', body_hi = 'वह सो गया। लाइटें बंद कीजिए। यह ऐप से आपके पास आने वाला आखिरी नोटिफ़िकेशन है। {milestone_days} दिनों तक, जब आप थकीं, रोईं और कोने में सिमट गईं, हमने आपको समझने और चुपचाप आपके साथ रहने की कोशिश की। अब फ़ोन एक तरफ़ रख दीजिए। आप परफ़ेक्ट हैं, आप काफ़ी हैं। इसके आगे की शानदार कहानी आप खुद, अपने दम पर लिखेंगी। आपके साथ यह सफ़र तय करना हमारे लिए सम्मान की बात थी। फिर मिलेंगे, Anacan! ❤️', title_id = 'Notifikasi terakhir, keheningan terakhir 🌌', body_id = 'Ia sudah tidur. Matikan lampu. Ini notifikasi terakhir dari aplikasi untuk Anda. Selama {milestone_days} hari, saat Anda lelah, menangis, dan merasa terpojok, kami berusaha memahami Anda dan diam-diam berada di sisi Anda. Sekarang letakkan ponsel Anda. Anda sempurna, Anda sudah cukup. Kisah luar biasa selanjutnya akan Anda tulis sendiri. Menempuh perjalanan ini bersama Anda adalah sebuah kehormatan. Sampai jumpa, Anacan! ❤️', title_ja = '最後のお知らせ、最後の静けさ 🌌', body_ja = '眠りました。明かりを消しましょう。これがアプリから届く最後のお知らせです。{milestone_days}日間、あなたが疲れたとき、泣いたとき、追いつめられたとき、わたしたちはあなたを理解し、静かにそばにいようとしてきました。さあ、スマホを置いて。あなたは完璧で、あなたはそのままで十分です。ここから先のすばらしい物語は、あなた自身が書いていきます。一緒に歩めたことを光栄に思います。またね、Anacanより！❤️', title_ko = '마지막 알림, 마지막 고요 🌌', body_ko = '아이가 잠들었어요. 불을 끄세요. 이건 앱이 보내는 마지막 알림이에요. {milestone_days}일 동안 엄마가 지치고, 울고, 궁지에 몰렸을 때 엄마를 이해하고 조용히 곁에 있으려 했어요. 이제 휴대폰을 내려놓으세요. 엄마는 완벽하고, 충분해요. 앞으로의 멋진 이야기는 엄마가 직접, 스스로 써 나갈 거예요. 함께 걸어온 길은 영광이었어요. 또 만나요, Anacan! ❤️', title_nl = 'De laatste melding, de laatste stilte 🌌', body_nl = 'Hij slaapt. Doe het licht uit. Dit is de laatste melding die je van de app krijgt. {milestone_days} dagen lang hebben we geprobeerd je te begrijpen en stil naast je te staan als je moe was, huilde of in het nauw zat. Leg je telefoon nu weg. Je bent perfect, je bent genoeg. Het prachtige verhaal dat nu komt, schrijf je zelf, helemaal alleen. Het was een eer om met je mee te reizen. Tot ziens, je Anacan! ❤️', title_pl = 'Ostatnie powiadomienie, ostatnia cisza 🌌', body_pl = 'Zasnęło. Zgaś światło. To ostatnie powiadomienie, jakie dostajesz od aplikacji. Przez {milestone_days} dni, gdy byłaś zmęczona, płakałaś i czułaś się przyparta do muru, staraliśmy się cię rozumieć i po cichu być obok. Teraz odłóż telefon. Jesteś wspaniała, jesteś wystarczająca. Dalszą, niesamowitą historię napiszesz już sama. Wspólna droga z tobą była zaszczytem. Do zobaczenia, Anacan! ❤️', title_pt = 'A última notificação, o último silêncio 🌌', body_pt = 'Ele adormeceu. Apague as luzes. Esta é a última notificação que recebe da app. Durante {milestone_days} dias, quando estava cansada, quando chorou e quando se sentiu encurralada, tentámos compreendê-la e estar ao seu lado em silêncio. Agora ponha o telemóvel de lado. É perfeita, é suficiente. A partir daqui, a próxima história magnífica vai escrevê-la sozinha. Foi uma honra fazer este caminho consigo. Até breve, Anacan! ❤️', title_sv = 'Den sista aviseringen, den sista tystnaden 🌌', body_sv = 'Barnet sover. Släck lamporna. Det här är den sista aviseringen du får från appen. I {milestone_days} dagar, när du var trött, när du grät och när du kände dig trängd, försökte vi förstå dig och tyst finnas vid din sida. Lägg nu undan telefonen. Du är perfekt, du räcker till. Nästa fantastiska berättelse skriver du själv, på egen hand. Det var en ära att gå den här vägen med dig. Vi ses, Anacan! ❤️', title_vi = 'Thông báo cuối cùng, khoảng lặng cuối cùng 🌌', body_vi = 'Bé đã ngủ. Hãy tắt đèn. Đây là thông báo cuối cùng ứng dụng gửi đến mẹ. Suốt {milestone_days} ngày, những lúc mẹ mệt mỏi, bật khóc hay thấy mình bị dồn vào góc, chúng tôi đã cố gắng thấu hiểu và lặng lẽ ở bên mẹ. Giờ hãy đặt điện thoại xuống. Mẹ thật tuyệt vời, mẹ đã là đủ. Câu chuyện tuyệt vời tiếp theo, mẹ sẽ tự mình viết nên. Được đồng hành cùng mẹ là một vinh dự. Hẹn gặp lại, Anacan! ❤️', title_zh = '最后一条通知，最后的安静 🌌', body_zh = '宝宝睡着了。关上灯吧。这是应用发给你的最后一条通知。{milestone_days}天里，每当你疲惫、哭泣、被逼到墙角时，我们都努力理解你，默默陪在你身边。现在，把手机放到一边吧。你很完美，你已经足够好。接下来精彩的故事，将由你自己亲手书写。能与你同行，是我们的荣幸。再见，Anacan！❤️' WHERE id = 'e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
COMMIT;
